--
-- Name: customer_suspensions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.customer_suspensions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    customer_id uuid NOT NULL,
    status text NOT NULL,
    source text NOT NULL,
    reason text NOT NULL,
    findings jsonb DEFAULT '[]'::jsonb NOT NULL,
    suspended_by uuid,
    suspended_at timestamp with time zone DEFAULT now() NOT NULL,
    lifted_by uuid,
    lifted_at timestamp with time zone,
    lift_reason text,
    CONSTRAINT customer_suspensions_check CHECK (((status <> 'lifted'::text) OR ((lifted_by IS NOT NULL) AND (lift_reason IS NOT NULL)))),
    CONSTRAINT customer_suspensions_source_check CHECK ((source = ANY (ARRAY['automatic'::text, 'manual'::text]))),
    CONSTRAINT customer_suspensions_status_check CHECK ((status = ANY (ARRAY['active'::text, 'lifted'::text])))
);


--
-- Name: _customer_suspension_json(public.customer_suspensions); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private._customer_suspension_json(s public.customer_suspensions) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 SELECT jsonb_build_object('id',s.id,'customer_id',s.customer_id,
  'customer_name',(SELECT COALESCE(c.business_name,c.display_name) FROM public.customers c WHERE c.id=s.customer_id),
  'status',s.status,'source',s.source,'reason',s.reason,'findings',s.findings,
  'suspended_by_name',(SELECT p.full_name FROM public.profiles p WHERE p.id=s.suspended_by),'suspended_at',s.suspended_at,
  'lifted_by_name',(SELECT p.full_name FROM public.profiles p WHERE p.id=s.lifted_by),'lifted_at',s.lifted_at,'lift_reason',s.lift_reason,
  'owing',e->'total','owing_currency',e->'currency','owing_by_currency',e->'by_currency')
 FROM (SELECT private.customer_exposure(s.customer_id) AS e) x
$$;


--
-- Name: delivery_balance_approvals; Type: TABLE; Schema: public; Owner: -
