--
-- Name: driver_cash_handins; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.driver_cash_handins (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    document_number text NOT NULL,
    driver_user_id uuid NOT NULL,
    currency public.currency_code NOT NULL,
    expected_amount numeric(14,2) NOT NULL,
    declared_amount numeric(14,2) NOT NULL,
    received_amount numeric(14,2),
    variance numeric(14,2),
    collection_count integer NOT NULL,
    status text NOT NULL,
    reason_code text,
    driver_notes text,
    receiver_notes text,
    approver_notes text,
    submitted_at timestamp with time zone DEFAULT now() NOT NULL,
    received_by uuid,
    received_at timestamp with time zone,
    approved_by uuid,
    approved_at timestamp with time zone,
    journal_entry_id uuid,
    owed_amount numeric(14,2) DEFAULT 0 NOT NULL,
    recovered_amount numeric(14,2) DEFAULT 0 NOT NULL,
    written_off_amount numeric(14,2) DEFAULT 0 NOT NULL,
    CONSTRAINT driver_cash_handins_check CHECK (((approved_by IS NULL) OR (approved_by IS DISTINCT FROM received_by))),
    CONSTRAINT driver_cash_handins_declared_amount_check CHECK ((declared_amount >= (0)::numeric)),
    CONSTRAINT driver_cash_handins_owed_amount_check CHECK ((owed_amount >= (0)::numeric)),
    CONSTRAINT driver_cash_handins_received_amount_check CHECK ((received_amount >= (0)::numeric)),
    CONSTRAINT driver_cash_handins_recovered_amount_check CHECK ((recovered_amount >= (0)::numeric)),
    CONSTRAINT driver_cash_handins_settled_within_owed CHECK (((recovered_amount + written_off_amount) <= owed_amount)),
    CONSTRAINT driver_cash_handins_status_check CHECK ((status = ANY (ARRAY['submitted'::text, 'received'::text, 'variance_pending'::text, 'approved'::text]))),
    CONSTRAINT driver_cash_handins_written_off_amount_check CHECK ((written_off_amount >= (0)::numeric))
);


