--
-- Name: _post_pos_credit_note(uuid, jsonb, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private._post_pos_credit_note(p_invoice_id uuid, p_lines jsonb, p_credit_account text, p_memo text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_src public.sales_invoices%ROWTYPE;
  v_line public.sales_invoice_lines%ROWTYPE;
  v_quar uuid;
  v_cn uuid;
  v_el jsonb;
  v_qty numeric;
  v_qty_base numeric;
  v_prior numeric;
  v_value numeric;
  v_cost numeric;
  v_total numeric := 0;
  v_cost_total numeric := 0;
  v_journal uuid;
  v_jl jsonb;
BEGIN
  -- 1170: refunded to the customer's card through the card machine (finalize_pos_card_terminal_refund).
  IF p_credit_account NOT IN ('1200','1100','1170') THEN RAISE EXCEPTION 'invalid credit note account'; END IF;
  IF p_lines IS NULL OR jsonb_typeof(p_lines)<>'array' OR jsonb_array_length(p_lines)=0 THEN
    RAISE EXCEPTION 'credit note lines required';
  END IF;
  SELECT * INTO v_src FROM public.sales_invoices WHERE id=p_invoice_id FOR UPDATE;
  IF NOT FOUND OR v_src.doc_type<>'invoice' OR v_src.status<>'posted' THEN RAISE EXCEPTION 'posted source invoice required'; END IF;
  IF p_credit_account='1200' AND v_src.customer_id IS NULL THEN RAISE EXCEPTION 'credit note to account requires named customer'; END IF;
  SELECT id INTO v_quar FROM public.warehouses WHERE is_active AND is_quarantine ORDER BY code LIMIT 1;
  IF v_quar IS NULL THEN RAISE EXCEPTION 'active quarantine warehouse required'; END IF;

  INSERT INTO public.sales_invoices(
    doc_type,status,document_number,customer_id,warehouse_id,currency,exchange_rate_applied,
    return_against_id,customer_phone_e164,customer_email,customer_whatsapp_e164,posted_by,posted_at
  ) VALUES(
    'credit_note','draft',public.next_series_value('CN-'),v_src.customer_id,v_quar,v_src.currency,v_src.exchange_rate_applied,
    v_src.id,v_src.customer_phone_e164,v_src.customer_email,v_src.customer_whatsapp_e164,auth.uid(),now()
  ) RETURNING id INTO v_cn;

  FOR v_el IN SELECT * FROM jsonb_array_elements(p_lines) LOOP
    SELECT * INTO v_line FROM public.sales_invoice_lines
    WHERE id=(v_el->>'source_invoice_line_id')::uuid FOR UPDATE;
    IF NOT FOUND OR v_line.invoice_id<>v_src.id THEN RAISE EXCEPTION 'source invoice line not on this invoice'; END IF;
    IF COALESCE(v_line.is_core_charge,false) THEN RAISE EXCEPTION 'core charges are returned through the core return'; END IF;
    v_qty:=(v_el->>'qty')::numeric;
    IF v_qty IS NULL OR v_qty<=0 OR v_line.qty<=0 THEN RAISE EXCEPTION 'return quantity must be positive'; END IF;
    v_qty_base:=round(v_qty*v_line.qty_base/v_line.qty,6);
    SELECT COALESCE(sum(sil.qty_base),0) INTO v_prior
    FROM public.sales_invoice_lines sil JOIN public.sales_invoices cn ON cn.id=sil.invoice_id
    WHERE sil.return_against_line_id=v_line.id AND cn.doc_type='credit_note' AND cn.status='posted';
    IF v_qty_base>GREATEST(COALESCE(v_line.qty_fulfilled,v_line.qty_base)-v_prior,0)+0.0001 THEN
      RAISE EXCEPTION 'return quantity exceeds remaining sold quantity';
    END IF;
    v_value:=round(v_line.line_total*v_qty/v_line.qty,2);
    v_cost:=round(COALESCE(v_line.unit_cost_basis,0)*v_qty_base,2);

    INSERT INTO public.sales_invoice_lines(
      invoice_id,stock_item_id,uom_id,qty,qty_base,unit_price,line_total,qty_fulfilled,
      issues_stock,unit_cost_basis,cost_total_basis,return_against_line_id
    ) VALUES(
      v_cn,v_line.stock_item_id,v_line.uom_id,v_qty,v_qty_base,v_line.unit_price,v_value,v_qty_base,
      true,v_line.unit_cost_basis,v_cost,v_line.id
    );
    PERFORM public._adjust_stock_level(v_line.stock_item_id,v_quar,v_qty_base,'FIFO',COALESCE(v_line.unit_cost_basis,0),v_src.currency);
    INSERT INTO public.stock_batches(batch_code,stock_item_id,warehouse_id,valuation_method,unit_cost,currency,qty_on_hand)
    VALUES(public.next_series_value('BATCH-'),v_line.stock_item_id,v_quar,'FIFO',COALESCE(v_line.unit_cost_basis,0),v_src.currency,v_qty_base);
    v_total:=v_total+v_value;
    v_cost_total:=v_cost_total+v_cost;
  END LOOP;

  IF v_total<=0 THEN RAISE EXCEPTION 'return has no credit value'; END IF;
  v_jl:=jsonb_build_array(
    jsonb_build_object('account_code','4110','debit',v_total,'credit',0,'currency',v_src.currency),
    jsonb_build_object('account_code',p_credit_account,'debit',0,'credit',v_total,'currency',v_src.currency));
  IF v_cost_total>0 THEN
    v_jl:=v_jl||jsonb_build_array(
      jsonb_build_object('account_code','1310','debit',v_cost_total,'credit',0,'currency',v_src.currency),
      jsonb_build_object('account_code','5100','debit',0,'credit',v_cost_total,'currency',v_src.currency));
  END IF;
  v_journal:=public.post_journal_entry(CURRENT_DATE,COALESCE(p_memo,format('Return CN against %s',COALESCE(v_src.document_number,v_src.id::text))),
    v_src.currency,v_src.exchange_rate_applied,v_jl);
  UPDATE public.sales_invoices SET status='posted',subtotal=v_total,total=v_total,journal_entry_id=v_journal,posted_at=now() WHERE id=v_cn;
  IF p_credit_account='1200' THEN
    UPDATE public.customers SET open_balance=open_balance-v_total,updated_at=now() WHERE id=v_src.customer_id;
  END IF;

  PERFORM public.emit_domain_event('return_completed','return:done:'||v_cn::text,
    jsonb_build_object('credit_note_id',v_cn,'invoice_id',v_src.id,'amount',v_total),auth.uid(),NULL);
  PERFORM public.emit_domain_event('quarantine_received','return:quar:'||v_cn::text,
    jsonb_build_object('credit_note_id',v_cn),auth.uid(),NULL);
  PERFORM public.enqueue_customer_receipts(v_cn);
  RETURN v_cn;
END;
$$;


--
-- Name: active_commerce_payment_intent(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.active_commerce_payment_intent(p_order_id uuid, p_requested_provider text) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_other_provider text;
  v_id uuid;
BEGIN
  IF p_requested_provider NOT IN ('paynow','ecocash','contipay') THEN
    RAISE EXCEPTION 'unsupported commerce payment provider: %', p_requested_provider;
  END IF;

  SELECT x.provider INTO v_other_provider
  FROM (
    SELECT 'paynow'::text AS provider, id, created_at
    FROM public.paynow_payment_intents
    WHERE commerce_order_id=p_order_id AND status IN ('pending','authorized')
    UNION ALL
    SELECT 'ecocash'::text, id, created_at
    FROM public.ecocash_payment_intents
    WHERE commerce_order_id=p_order_id AND status IN ('pending','authorized')
    UNION ALL
    SELECT 'contipay'::text, id, created_at
    FROM public.contipay_payment_intents
    WHERE commerce_order_id=p_order_id AND status IN ('pending','authorized')
  ) x
  WHERE x.provider <> p_requested_provider
  ORDER BY x.created_at DESC
  LIMIT 1;

  IF v_other_provider IS NOT NULL THEN
    RAISE EXCEPTION 'active % payment attempt exists for this order; wait for it to fail/cancel/expire before switching provider', v_other_provider;
  END IF;

  IF p_requested_provider='paynow' THEN
    SELECT id INTO v_id
    FROM public.paynow_payment_intents
    WHERE commerce_order_id=p_order_id AND status IN ('pending','authorized')
    ORDER BY created_at DESC LIMIT 1;
  ELSIF p_requested_provider='ecocash' THEN
    SELECT id INTO v_id
    FROM public.ecocash_payment_intents
    WHERE commerce_order_id=p_order_id AND status IN ('pending','authorized')
    ORDER BY created_at DESC LIMIT 1;
  ELSE
    SELECT id INTO v_id
    FROM public.contipay_payment_intents
    WHERE commerce_order_id=p_order_id AND status IN ('pending','authorized')
    ORDER BY created_at DESC LIMIT 1;
  END IF;

  RETURN v_id;
END;
$$;


--
-- Name: allocate_pos_split_receipt_to_invoice(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.allocate_pos_split_receipt_to_invoice(p_leg_id uuid, p_invoice_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE l public.pos_split_payment_legs%ROWTYPE; pe public.payment_entries%ROWTYPE; i public.sales_invoices%ROWTYPE;
 v_open NUMERIC; v_apply NUMERIC; v_journal UUID;
BEGIN
 PERFORM public._payments_rpc_enter();
 SELECT * INTO l FROM public.pos_split_payment_legs WHERE id=p_leg_id FOR UPDATE;
 IF NOT FOUND OR l.status NOT IN('captured','refund_review','refund_pending') OR l.payment_entry_id IS NULL THEN RAISE EXCEPTION 'captured split leg required'; END IF;
 SELECT * INTO pe FROM public.payment_entries WHERE id=l.payment_entry_id FOR UPDATE;
 SELECT * INTO i FROM public.sales_invoices WHERE id=p_invoice_id FOR UPDATE;
 IF pe.status<>'posted' OR i.status<>'posted' OR i.doc_type<>'invoice' OR pe.customer_id IS DISTINCT FROM i.customer_id OR pe.currency<>i.currency THEN
  RAISE EXCEPTION 'split receipt/invoice mismatch'; END IF;
 IF EXISTS(SELECT 1 FROM public.payment_allocations WHERE payment_entry_id=pe.id) THEN RETURN pe.id; END IF;
 v_apply:=round(COALESCE(l.applied_target_amount,l.requested_amount),2);
 IF v_apply<0 OR v_apply>pe.amount+0.01 THEN RAISE EXCEPTION 'invalid split applied target'; END IF;
 IF v_apply>0 THEN
  v_open:=round(i.total-i.amount_paid,2); IF v_apply>v_open+0.01 THEN RAISE EXCEPTION 'split receipt exceeds invoice open balance'; END IF;
  v_journal:=public.post_journal_entry(CURRENT_DATE,format('Apply POS split receipt %s to %s',pe.document_number,i.document_number),pe.currency,pe.exchange_rate_applied,
   jsonb_build_array(jsonb_build_object('account_code','2215','debit',v_apply,'credit',0,'currency',pe.currency),
                     jsonb_build_object('account_code','1200','debit',0,'credit',v_apply,'currency',pe.currency)));
  INSERT INTO public.payment_allocations(payment_entry_id,sales_invoice_id,amount,currency,exchange_rate_applied)
  VALUES(pe.id,i.id,v_apply,pe.currency,pe.exchange_rate_applied);
  UPDATE public.sales_invoices SET amount_paid=amount_paid+v_apply WHERE id=i.id;
  UPDATE public.customers SET open_balance=greatest(0,open_balance-v_apply),updated_at=now() WHERE id=pe.customer_id;
 END IF;
 UPDATE public.pos_split_payment_legs SET
  status=CASE WHEN refund_required_amount>0.009 THEN 'refund_review'::public.pos_split_payment_leg_status ELSE 'allocated'::public.pos_split_payment_leg_status END,
  allocation_journal_entry_id=v_journal,allocated_at=CASE WHEN v_apply>0 THEN now() ELSE allocated_at END,updated_at=now() WHERE id=l.id;
 RETURN pe.id;
END $$;


--
-- Name: approvals_for(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.approvals_for(p_uid uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
 v_admin boolean := private.user_has_staff_role(p_uid, ARRAY['admin']::public.staff_role[]);
 v_finance boolean := private.user_has_staff_role(p_uid, ARRAY['admin','finance']::public.staff_role[]);
 v_dispatch boolean := private.user_has_staff_role(p_uid, ARRAY['admin','dispatcher']::public.staff_role[]);
 v_counter boolean := private.user_has_staff_role(p_uid, ARRAY['admin','finance','sales','dispatcher']::public.staff_role[]);
 v_warehouse boolean := private.user_has_staff_role(p_uid, ARRAY['admin','warehouse']::public.staff_role[]);
 v_manager boolean := private.pos_approver_source(p_uid) IS NOT NULL OR private.user_has_staff_role(p_uid, ARRAY['admin']::public.staff_role[]);
 v_items jsonb := '[]'::jsonb;
BEGIN
 IF p_uid IS NULL OR NOT private.user_has_staff_role(p_uid, ARRAY['admin','finance','sales','dispatcher','warehouse']::public.staff_role[]) THEN
  RETURN v_items;
 END IF;

 IF v_dispatch THEN
  v_items := v_items || COALESCE((SELECT jsonb_agg(jsonb_build_object(
    'kind','delivery_balance','ref',a.id,'urgent',true,'href','/staff/logistics/balances',
    'title','Balance on account: '||COALESCE(c.business_name,c.display_name,'customer'),
    'detail','Driver waiting at the door. '||a.reason,
    'amount',a.amount,'currency',a.currency,'waiting_since',a.created_at))
   FROM public.delivery_balance_approvals a LEFT JOIN public.customers c ON c.id=a.customer_id
   WHERE a.status='pending'),'[]'::jsonb);
 END IF;

 IF v_counter THEN
  v_items := v_items || COALESCE((SELECT jsonb_agg(jsonb_build_object(
    'kind','driver_cash_count','ref',h.id,'urgent',false,'href','/staff/logistics/driver-cash',
    'title','Count driver cash: '||COALESCE(p.full_name,'driver'),
    'detail',h.document_number||' · '||h.collection_count||' collections',
    'amount',h.expected_amount,'currency',h.currency,'waiting_since',h.submitted_at))
   FROM public.driver_cash_handins h LEFT JOIN public.profiles p ON p.id=h.driver_user_id
   WHERE h.status='submitted' AND h.driver_user_id<>p_uid),'[]'::jsonb);
 END IF;

 IF v_manager THEN
  v_items := v_items || COALESCE((SELECT jsonb_agg(jsonb_build_object(
    'kind','driver_cash_difference','ref',h.id,'urgent',false,'href','/staff/logistics/driver-cash',
    'title','Driver cash difference: '||COALESCE(p.full_name,'driver'),
    'detail',h.document_number||' · counted '||h.received_amount||' of '||h.expected_amount,
    'amount',h.variance,'currency',h.currency,'waiting_since',h.received_at))
   FROM public.driver_cash_handins h LEFT JOIN public.profiles p ON p.id=h.driver_user_id
   WHERE h.status='variance_pending' AND h.received_by<>p_uid AND h.driver_user_id<>p_uid),'[]'::jsonb);

  v_items := v_items || COALESCE((SELECT jsonb_agg(jsonb_build_object(
    'kind','till_variance','ref',s.id,'urgent',false,'href','/pos',
    'title','Till difference: '||COALESCE(w.name,'till')||' · '||COALESCE(p.full_name,'cashier'),
    'detail','Counted '||s.counted_cash||', expected '||s.expected_cash,
    'amount',s.variance,'currency',s.currency,'waiting_since',COALESCE(s.closed_at,s.updated_at)))
   FROM public.pos_till_sessions s LEFT JOIN public.warehouses w ON w.id=s.warehouse_id
   LEFT JOIN public.profiles p ON p.id=s.operator_user_id
   WHERE s.status='variance_pending' AND s.operator_user_id<>p_uid),'[]'::jsonb);

  v_items := v_items || COALESCE((SELECT jsonb_agg(jsonb_build_object(
    'kind','return','ref',r.id,'urgent',false,'href','/pos',
    'title','Return to approve: '||r.document_number,
    'detail',replace(r.resolution::text,'_',' ')||' · '||COALESCE(r.reason_code,''),
    'amount',(SELECT SUM(round(l.qty*l.unit_price,2)) FROM public.pos_return_case_lines l WHERE l.return_case_id=r.id),
    'currency',i.currency,'waiting_since',r.created_at))
   FROM public.pos_return_cases r JOIN public.sales_invoices i ON i.id=r.source_invoice_id
   WHERE r.status='draft'),'[]'::jsonb);

  v_items := v_items || COALESCE((SELECT jsonb_agg(jsonb_build_object(
    'kind','split_refund','ref',x.id,'urgent',false,'href','/pos',
    'title','Part-payment refund to approve','detail',COALESCE(x.failure_reason,x.notes,''),
    'amount',x.gross_amount,'currency',NULL,'waiting_since',x.created_at))
   FROM public.pos_split_refund_requests x WHERE x.status IN('review','failed')),'[]'::jsonb);

  v_items := v_items || COALESCE((SELECT jsonb_agg(jsonb_build_object(
    'kind','warranty','ref',w.id,'urgent',false,'href','/staff/warranty',
    'title','Warranty claim: '||w.document_number,'detail',COALESCE(w.notes,''),
    'amount',NULL,'currency',w.currency,'waiting_since',w.created_at))
   FROM public.warranty_claims w WHERE w.status='open'),'[]'::jsonb);
 END IF;

 IF v_manager OR v_finance THEN
  -- Card charges with no posted outcome: the customer may have been charged.
  v_items := v_items || COALESCE((SELECT jsonb_agg(jsonb_build_object(
    'kind','card_unresolved','ref',a.id,'urgent',true,'href','/pos',
    'title','Card payment to reconcile'||COALESCE(' ('||t.label||')',''),
    'detail',a.status||COALESCE(' · '||a.finalization_error,''),
    'amount',a.amount,'currency',a.currency,'waiting_since',a.created_at))
   FROM public.pos_card_terminal_attempts a LEFT JOIN public.pos_card_terminals t ON t.id=a.terminal_id
   WHERE a.status IN('unknown','approved') OR (a.status='initiated' AND a.created_at<now()-interval '10 minutes')
      OR (a.finalization_error IS NOT NULL AND a.status<>'settled')),'[]'::jsonb);
 END IF;

 IF v_finance THEN
  v_items := v_items || COALESCE((SELECT jsonb_agg(jsonb_build_object(
    'kind','requisition','ref',r.id,'urgent',false,'href','/staff/finance',
    'title','Requisition: '||COALESCE(r.payee,r.document_number),
    'detail',COALESCE(r.memo,'')||' · approvals '||COALESCE(r.approval_count,0)||'/'||COALESCE(r.required_approvals,1),
    'amount',r.amount,'currency',r.currency,'waiting_since',COALESCE(r.submitted_at,r.created_at)))
   FROM public.finance_requisitions r
   WHERE r.status='submitted' AND r.requested_by<>p_uid
     AND NOT EXISTS(SELECT 1 FROM public.finance_requisition_approvals x WHERE x.requisition_id=r.id AND x.approver_user_id=p_uid)),'[]'::jsonb);
 END IF;

 IF v_warehouse THEN
  v_items := v_items || COALESCE((SELECT jsonb_agg(jsonb_build_object(
    'kind','transfer_send','ref',f.id,'urgent',f.customer_id IS NOT NULL,'href','/pos',
    'title','Send to '||COALESCE(dw.name,'branch')||': '||COALESCE(si.oem_part_number,''),
    'detail',f.document_number||' · from '||COALESCE(sw.name,'')||CASE WHEN f.customer_id IS NOT NULL THEN ' · customer waiting' ELSE '' END,
    'amount',f.qty,'currency',NULL,'waiting_since',f.created_at))
   FROM public.pos_fulfillment_requests f
   LEFT JOIN public.warehouses sw ON sw.id=f.source_warehouse_id LEFT JOIN public.warehouses dw ON dw.id=f.destination_warehouse_id
   LEFT JOIN public.stock_items si ON si.id=f.stock_item_id
   WHERE f.kind='branch_transfer' AND f.status='reserved'),'[]'::jsonb);

  v_items := v_items || COALESCE((SELECT jsonb_agg(jsonb_build_object(
    'kind','stock_transfer','ref',e.id,'urgent',false,'href','/staff/warehouse/transfers',
    'title','Receive transfer '||COALESCE(e.document_number,''),
    'detail',COALESCE(fw.name,'')||' → '||COALESCE(tw.name,'')||COALESCE(' · '||e.notes,''),
    'amount',NULL,'currency',NULL,'waiting_since',e.created_at))
   FROM public.stock_entries e
   LEFT JOIN public.warehouses fw ON fw.id=e.from_warehouse_id LEFT JOIN public.warehouses tw ON tw.id=e.to_warehouse_id
   WHERE e.entry_type='transfer' AND e.status='pending_approval'
     AND COALESCE(e.first_approver_id,e.created_by)<>p_uid),'[]'::jsonb);
 END IF;

 RETURN COALESCE((SELECT jsonb_agg(x ORDER BY (x->>'urgent')::boolean DESC, x->>'waiting_since')
                  FROM jsonb_array_elements(v_items) x),'[]'::jsonb);
END $$;


--
-- Name: assert_customer_not_suspended(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.assert_customer_not_suspended(p_customer_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_id uuid; v_reason text;
BEGIN
 v_id := private.suspend_customer_if_due(p_customer_id);
 IF v_id IS NULL THEN RETURN; END IF;
 SELECT reason INTO v_reason FROM public.customer_suspensions WHERE id=v_id;
 RAISE EXCEPTION 'customer account suspended (%): pay upfront, or ask a manager to lift the suspension', v_reason
  USING ERRCODE='P0001', HINT='customer_suspended';
END $$;


--
-- Name: assert_pos_reason(text, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.assert_pos_reason(p_action text, p_code text, p_notes text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_requires_notes BOOLEAN;
BEGIN
 SELECT r.requires_notes INTO v_requires_notes
 FROM public.pos_approval_reason_codes r
 WHERE r.action=p_action AND r.code=p_code AND r.is_active;
 IF NOT FOUND THEN RAISE EXCEPTION 'valid active reason code required for %',p_action; END IF;
 IF v_requires_notes AND trim(COALESCE(p_notes,''))='' THEN
  RAISE EXCEPTION 'supporting notes required for reason %',p_code;
 END IF;
END $$;


--
-- Name: badge_holder_source(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.badge_holder_source(p_employee uuid, p_user uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT CASE WHEN p_employee IS NOT NULL THEN private.employee_approver_source(p_employee) ELSE private.pos_approver_source(p_user) END;
$$;


--
-- Name: capture_pos_split_external_leg(uuid, text, uuid, text, numeric, public.currency_code, numeric, public.currency_code, numeric, numeric); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.capture_pos_split_external_leg(p_leg_id uuid, p_provider text, p_provider_intent_id uuid, p_provider_ref text, p_amount numeric, p_currency public.currency_code, p_exchange_rate numeric, p_settlement_currency public.currency_code DEFAULT NULL::public.currency_code, p_settlement_amount numeric DEFAULT NULL::numeric, p_settlement_exchange_rate numeric DEFAULT NULL::numeric) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE l public.pos_split_payment_legs%ROWTYPE; s public.pos_split_payment_sessions%ROWTYPE; o public.commerce_orders%ROWTYPE; v_pe UUID;
BEGIN
 SELECT * INTO l FROM public.pos_split_payment_legs WHERE id=p_leg_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'split payment leg not found'; END IF;
 IF l.tender::text<>p_provider THEN RAISE EXCEPTION 'provider % does not match split leg tender %',p_provider,l.tender; END IF;
 IF l.status IN('captured','allocated','refund_review','refund_pending') AND l.payment_entry_id IS NOT NULL THEN RETURN l.payment_entry_id; END IF;
 IF l.status NOT IN('planned','pending','unknown') THEN RAISE EXCEPTION 'split leg cannot be captured in status %',l.status; END IF;
 SELECT * INTO s FROM public.pos_split_payment_sessions WHERE id=l.session_id FOR UPDATE;
 SELECT * INTO o FROM public.commerce_orders WHERE id=s.commerce_order_id FOR UPDATE;
 IF abs(round(p_amount,2)-l.requested_amount)>0.01 OR p_currency<>s.currency THEN RAISE EXCEPTION 'captured provider amount/currency does not match locked split leg'; END IF;
 v_pe:=public.create_payment_entry(o.customer_id,l.tender,l.requested_amount,s.currency,o.exchange_rate_applied,
  format('POS split %s %s',p_provider,s.id),p_settlement_currency,p_settlement_amount,p_settlement_exchange_rate);
 PERFORM private.post_pos_split_unapplied_payment_entry(v_pe,l.id);
 UPDATE public.pos_split_payment_legs SET status='captured',provider_intent_id=COALESCE(p_provider_intent_id,provider_intent_id),
  provider_ref=COALESCE(NULLIF(trim(COALESCE(p_provider_ref,'')),''),provider_ref),payment_entry_id=v_pe,locked_at=COALESCE(locked_at,now()),
  status_detail=NULL,updated_at=now() WHERE id=l.id;
 UPDATE public.commerce_orders SET active_payment_provider=NULL,active_payment_intent_id=NULL,payment_exception=NULL,updated_at=now()
  WHERE id=o.id AND (active_payment_intent_id IS NULL OR active_payment_intent_id=p_provider_intent_id);
 PERFORM private.refresh_pos_split_payment_session(s.id);
 IF (SELECT status FROM public.pos_split_payment_sessions WHERE id=s.id)='fully_committed' THEN PERFORM private.finalize_pos_split_payment_session(s.id); END IF;
 RETURN v_pe;
END $$;


--
-- Name: customer_exposure(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.customer_exposure(p_customer_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 WITH c AS (SELECT currency FROM public.customers WHERE id = p_customer_id),
 open AS (
  SELECT si.currency, greatest(si.total - si.amount_paid, 0) AS amount,
         CASE WHEN si.currency = 'USD' THEN 1 ELSE NULLIF(si.exchange_rate_applied, 0) END AS rate
    FROM public.sales_invoices si WHERE si.customer_id = p_customer_id AND si.status = 'posted' AND si.total - si.amount_paid > 0.009),
 per AS (SELECT currency, sum(amount) AS amount, count(*) AS invoices FROM open GROUP BY currency),
 usd AS (SELECT CASE WHEN bool_and(rate IS NOT NULL) OR count(*) = 0 THEN COALESCE(sum(amount / rate), 0) END AS v FROM open)
 SELECT jsonb_build_object(
  'currency', (SELECT currency FROM c),
  'by_currency', COALESCE((SELECT jsonb_agg(jsonb_build_object('currency', currency, 'amount', round(amount, 2), 'invoices', invoices) ORDER BY currency) FROM per), '[]'::jsonb),
  'total', (SELECT round(CASE WHEN (SELECT currency FROM c) = 'USD' THEN usd.v
                              ELSE usd.v * public.get_zig_exchange_rate(CURRENT_DATE) END, 2) FROM usd))
$$;


--
-- Name: customer_suspension_findings(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.customer_suspension_findings(p_customer_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_waived text[]; v_items jsonb := '[]'::jsonb; v_refused jsonb;
BEGIN
 SELECT COALESCE(array_agg(DISTINCT f->>'key'),'{}') INTO v_waived
 FROM public.customer_suspensions s, jsonb_array_elements(s.findings) f
 WHERE s.customer_id=p_customer_id AND s.status='lifted';

 -- Balance left on account at delivery, unpaid after 7 days.
 SELECT v_items || COALESCE(jsonb_agg(jsonb_build_object('rule','on_account_overdue','key','bal:'||b.id,'ref',b.sales_invoice_id,
   'label','Balance left on account at delivery '||COALESCE(si.document_number,''),'amount',round(si.total-si.amount_paid,2),
   'currency',si.currency,'since',b.created_at)),'[]'::jsonb) INTO v_items
 FROM public.delivery_balance_approvals b JOIN public.sales_invoices si ON si.id=b.sales_invoice_id
 WHERE b.customer_id=p_customer_id AND b.status IN('approved','auto_approved') AND b.created_at < now()-interval '7 days'
   AND si.total-si.amount_paid > 0.01 AND NOT ('bal:'||b.id = ANY(v_waived));

 -- Any posted invoice still owing 30 days after it was issued.
 SELECT v_items || COALESCE(jsonb_agg(jsonb_build_object('rule','invoice_overdue','key','inv:'||si.id,'ref',si.id,
   'label','Invoice '||COALESCE(si.document_number,si.id::text)||' unpaid','amount',round(si.total-si.amount_paid,2),
   'currency',si.currency,'since',COALESCE(si.posted_at,si.created_at))),'[]'::jsonb) INTO v_items
 FROM public.sales_invoices si
 WHERE si.customer_id=p_customer_id AND si.status='posted' AND si.doc_type='invoice'
   AND COALESCE(si.posted_at,si.created_at) < now()-interval '30 days' AND si.total-si.amount_paid > 0.01
   AND NOT ('inv:'||si.id = ANY(v_waived));

 -- Refused / absent pay-on-delivery deliveries in 90 days: two or more.
 SELECT COALESCE(jsonb_agg(jsonb_build_object('rule','refused_cod','key','job:'||j.id,'ref',j.id,
   'label','Pay-on-delivery '||COALESCE(j.document_number,'delivery')||' '||replace(j.failure_reason_code::text,'_',' '),
   'amount',round(si.total,2),'currency',si.currency,'since',j.failed_at)),'[]'::jsonb) INTO v_refused
 FROM public.delivery_jobs j JOIN public.delivery_notes dn ON dn.id=j.delivery_note_id JOIN public.sales_invoices si ON si.id=dn.sales_invoice_id
 WHERE si.customer_id=p_customer_id AND j.status='failed' AND j.failure_reason_code IN('refused','customer_absent')
   AND j.failed_at > now()-interval '90 days'
   AND si.delivery_payment_method IN('cash_on_delivery','card_on_delivery','cash_or_card_on_delivery')
   AND NOT ('job:'||j.id = ANY(v_waived));
 IF jsonb_array_length(v_refused) >= 2 THEN v_items := v_items || v_refused; END IF;
 RETURN v_items;
END $$;


--
-- Name: customer_suspension_preview(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.customer_suspension_preview(p_customer_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE s public.customer_suspensions%ROWTYPE; v_findings jsonb; e jsonb;
BEGIN
 IF p_customer_id IS NULL THEN RETURN NULL; END IF;
 SELECT * INTO s FROM public.customer_suspensions WHERE customer_id=p_customer_id AND status='active';
 IF FOUND THEN RETURN private._customer_suspension_json(s); END IF;
 v_findings := private.customer_suspension_findings(p_customer_id);
 IF jsonb_array_length(v_findings)=0 THEN RETURN NULL; END IF;
 e := private.customer_exposure(p_customer_id);
 RETURN jsonb_build_object('id',NULL,'customer_id',p_customer_id,
  'customer_name',(SELECT COALESCE(c.business_name,c.display_name) FROM public.customers c WHERE c.id=p_customer_id),
  'status','due','source','automatic','reason',private.suspension_reason(v_findings),'findings',v_findings,
  'suspended_by_name',NULL,'suspended_at',NULL,'lifted_by_name',NULL,'lifted_at',NULL,'lift_reason',NULL,
  'owing',e->'total','owing_currency',e->'currency','owing_by_currency',e->'by_currency');
END $$;


--
-- Name: delivery_failed_check_suspension(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.delivery_failed_check_suspension() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_cust uuid;
BEGIN
 IF NEW.status='failed' AND OLD.status IS DISTINCT FROM 'failed' AND NEW.failure_reason_code IN('refused','customer_absent') THEN
  SELECT si.customer_id INTO v_cust FROM public.delivery_notes dn JOIN public.sales_invoices si ON si.id=dn.sales_invoice_id WHERE dn.id=NEW.delivery_note_id;
  PERFORM private.suspend_customer_if_due(v_cust);
 END IF;
 RETURN NEW;
END $$;


--
-- Name: delivery_payment_completion_guard(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.delivery_payment_completion_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE i public.sales_invoices%ROWTYPE;
BEGIN
 IF NEW.status='completed' AND OLD.status IS DISTINCT FROM 'completed' THEN
  SELECT si.* INTO i FROM public.delivery_notes dn JOIN public.sales_invoices si ON si.id=dn.sales_invoice_id WHERE dn.id=NEW.delivery_note_id;
  IF i.delivery_payment_method IS NOT NULL AND i.amount_paid+0.01<i.total THEN RAISE EXCEPTION 'delivery cannot complete until required payment clears; outstanding % %',i.currency,round(i.total-i.amount_paid,2); END IF;
 END IF; RETURN NEW;
END $$;


--
-- Name: delivery_payment_rpc_active(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.delivery_payment_rpc_active() RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$ SELECT COALESCE(current_setting('app.delivery_payment_rpc',true),'')='1' $$;


--
-- Name: employee_approver_source(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.employee_approver_source(p_employee uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT CASE
    WHEN g.code IN ('A1','A2','B1') THEN 'senior_grade'
    WHEN COALESCE(r.approval_flags->>'approver', r.approval_flags->>'pos_approver', r.approval_flags->>'pos_manager', 'false') = 'true' THEN 'approval_role'
    WHEN r.id IS NOT NULL AND EXISTS (SELECT 1 FROM public.hr_roles c WHERE c.parent_role_id = r.id AND c.is_active) THEN 'department_manager'
    WHEN EXISTS (SELECT 1 FROM public.staff_approver_assignments a WHERE a.employee_id = e.id AND a.revoked_at IS NULL) THEN 'assigned'
    ELSE NULL
  END
  FROM public.employees e
  LEFT JOIN public.hr_grades g ON g.id = e.grade_id
  LEFT JOIN public.hr_roles r ON r.id = e.hr_role_id AND r.is_active
  WHERE e.id = p_employee AND e.status = 'active';
$$;


--
-- Name: enforce_pos_split_store_credit_holds(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enforce_pos_split_store_credit_holds() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_held NUMERIC:=0;
BEGIN
 IF NEW.balance<OLD.balance THEN
  SELECT COALESCE(SUM(l.requested_amount),0) INTO v_held
  FROM public.pos_split_payment_legs l JOIN public.pos_split_payment_sessions s ON s.id=l.session_id
  WHERE s.status NOT IN('settled','refunded','cancelled') AND l.status='held'
    AND s.currency=NEW.currency AND EXISTS(SELECT 1 FROM public.commerce_orders o WHERE o.id=s.commerce_order_id AND o.customer_id=NEW.customer_id);
  IF NEW.balance+0.001<v_held THEN RAISE EXCEPTION 'store credit is held for an active POS split payment; available balance would be exceeded'; END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: enforce_suspension_balance_on_account(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enforce_suspension_balance_on_account() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
 PERFORM private.assert_customer_not_suspended(NEW.customer_id);
 RETURN NEW;
END $$;


--
-- Name: enforce_suspension_fulfillment(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enforce_suspension_fulfillment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_cust uuid;
BEGIN
 IF NEW.kind = 'branch_transfer' THEN RETURN NEW; END IF;
 v_cust := COALESCE(NEW.customer_id, (SELECT customer_id FROM public.pos_carts WHERE id=NEW.cart_id));
 PERFORM private.assert_customer_not_suspended(v_cust);
 RETURN NEW;
END $$;


--
-- Name: enforce_suspension_pay_on_delivery(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enforce_suspension_pay_on_delivery() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
 IF NEW.delivery_payment_method IS DISTINCT FROM 'prepay' AND NEW.customer_id IS NOT NULL THEN
  PERFORM private.assert_customer_not_suspended(NEW.customer_id);
 END IF;
 RETURN NEW;
END $$;


--
-- Name: enqueue_commerce_event(text, text, uuid, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enqueue_commerce_event(p_event_key text, p_event_type text, p_aggregate_id uuid, p_payload jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_id uuid; v_aggregate_type text;
BEGIN
  v_aggregate_type:=CASE
    WHEN p_event_type LIKE 'return.%' THEN 'return_request'
    WHEN p_event_type LIKE 'refund.%' THEN 'return_refund'
    ELSE 'commerce_order'
  END;
  INSERT INTO public.commerce_outbox(event_key,event_type,aggregate_type,aggregate_id,payload)
  VALUES(p_event_key,p_event_type,v_aggregate_type,p_aggregate_id,COALESCE(p_payload,'{}'::jsonb))
  ON CONFLICT(event_key) DO NOTHING
  RETURNING id INTO v_id;
  IF v_id IS NULL THEN SELECT id INTO v_id FROM public.commerce_outbox WHERE event_key=p_event_key; END IF;
  RETURN v_id;
END;
$$;


--
-- Name: expire_commerce_checkouts_internal(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.expire_commerce_checkouts_internal() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  r RECORD;
  v_count INTEGER := 0;
BEGIN
  FOR r IN
    SELECT id
    FROM public.commerce_orders
    WHERE state IN ('awaiting_payment','payment_processing','payment_failed')
      AND reservation_expires_at IS NOT NULL
      AND reservation_expires_at <= now()
      AND settled_payment_entry_id IS NULL
    FOR UPDATE SKIP LOCKED
  LOOP
    PERFORM private.release_commerce_order(r.id, 'payment_expired', 'reservation TTL expired');
    v_count := v_count + 1;
  END LOOP;
  RETURN v_count;
END;
$$;


--
-- Name: fail_pos_split_provider_leg(uuid, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.fail_pos_split_provider_leg(p_provider_intent_id uuid, p_provider text, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE l public.pos_split_payment_legs%ROWTYPE; s public.pos_split_payment_sessions%ROWTYPE;
BEGIN
 SELECT * INTO l FROM public.pos_split_payment_legs WHERE provider_intent_id=p_provider_intent_id AND tender::text=p_provider FOR UPDATE;
 IF NOT FOUND OR l.status IN('captured','allocated','refund_review','refund_pending','refunded','cancelled') THEN RETURN; END IF;
 UPDATE public.pos_split_payment_legs SET status='failed',status_detail=left(COALESCE(p_reason,'provider payment failed'),500),failed_at=now(),updated_at=now() WHERE id=l.id;
 SELECT * INTO s FROM public.pos_split_payment_sessions WHERE id=l.session_id;
 UPDATE public.commerce_orders SET active_payment_provider=NULL,active_payment_intent_id=NULL,updated_at=now() WHERE id=s.commerce_order_id AND active_payment_intent_id=p_provider_intent_id;
 PERFORM private.refresh_pos_split_payment_session(l.session_id);
END $$;


--
-- Name: finalize_commerce_order(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.finalize_commerce_order(p_order_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_prev_accounting text := COALESCE(current_setting('app.sales_checkout_accounting',true),''); v_order public.commerce_orders%ROWTYPE; v_inv UUID; v_inv_row public.sales_invoices%ROWTYPE; v_total NUMERIC; v_bad BOOLEAN;
BEGIN
 SELECT * INTO v_order FROM public.commerce_orders WHERE id=p_order_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'commerce order not found'; END IF;
 IF v_order.sales_invoice_id IS NOT NULL THEN RETURN v_order.sales_invoice_id; END IF;
 IF v_order.state NOT IN ('awaiting_payment','payment_processing','payment_failed') THEN RAISE EXCEPTION 'commerce order cannot finalize in state %',v_order.state; END IF;
 IF v_order.reservation_expires_at IS NULL OR v_order.reservation_expires_at<=now() THEN RAISE EXCEPTION 'commerce reservation expired'; END IF;
 IF EXISTS(SELECT 1 FROM public.inventory_reservations r WHERE r.commerce_order_id=v_order.id AND r.state='active'
  AND (r.expires_at IS NULL OR r.expires_at<=now())) THEN RAISE EXCEPTION 'one or more inventory reservations expired'; END IF;
 SELECT COALESCE(SUM(line_total),0) INTO v_total FROM public.pos_cart_lines WHERE cart_id=v_order.cart_id;
 IF abs(v_total-v_order.total)>0.001 THEN RAISE EXCEPTION 'checkout snapshot total drift detected'; END IF;
 SELECT EXISTS(
  WITH required AS (
   SELECT stock_item_id,SUM(qty_base)::numeric qty FROM public.pos_cart_lines
   WHERE cart_id=v_order.cart_id AND COALESCE(issues_stock,true)=true AND is_core_charge=false GROUP BY stock_item_id
  )
  SELECT 1 FROM required q LEFT JOIN public.inventory_reservations r
   ON r.commerce_order_id=v_order.id AND r.stock_item_id=q.stock_item_id AND r.warehouse_id=v_order.warehouse_id
  WHERE r.id IS NULL OR abs(r.reserved_qty-q.qty)>0.0001 OR r.state<>'active'
 ) INTO v_bad;
 IF v_bad THEN RAISE EXCEPTION 'checkout reservation no longer matches cart snapshot'; END IF;
 PERFORM set_config('app.commerce_finalize','1',true);
 PERFORM set_config('app.commerce_fulfill_order_id',v_order.id::text,true);
 -- Posting the sale journal is part of checkout: allow it for the cashier, as the other checkout paths do.
 PERFORM public._sales_checkout_accounting_enter();
 BEGIN
  v_inv:=public.checkout_pos_cart(
   v_order.cart_id,
   NULLIF(v_order.checkout_snapshot->>'receipt_email',''),
   NULLIF(v_order.checkout_snapshot->>'receipt_whatsapp_e164',''),
   NULLIF(v_order.checkout_snapshot->>'receipt_phone_e164','')
  );
 EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('app.commerce_finalize','',true);
  PERFORM set_config('app.commerce_fulfill_order_id','',true);
  PERFORM set_config('app.sales_checkout_accounting',v_prev_accounting,true);
  RAISE;
 END;
 PERFORM set_config('app.commerce_finalize','',true);
 PERFORM set_config('app.commerce_fulfill_order_id','',true);
 PERFORM set_config('app.sales_checkout_accounting',v_prev_accounting,true);
 SELECT * INTO v_inv_row FROM public.sales_invoices WHERE id=v_inv;
 IF NOT FOUND OR v_inv_row.status<>'posted' OR v_inv_row.doc_type<>'invoice' THEN
  RAISE EXCEPTION 'commerce finalization did not produce a posted invoice';
 END IF;
 IF v_order.fulfillment_mode='immediate' THEN
  UPDATE public.inventory_reservations SET consumed_qty=reserved_qty,state='consumed',consumed_at=now(),expires_at=NULL
  WHERE commerce_order_id=v_order.id AND state='active';
 ELSE
  UPDATE public.inventory_reservations SET state='allocated',expires_at=NULL,reservation_reason='paid_dispatch_allocation'
  WHERE commerce_order_id=v_order.id AND state='active';
 END IF;
 UPDATE public.commerce_orders SET sales_invoice_id=v_inv,finalized_at=now(),updated_at=now() WHERE id=v_order.id;
 PERFORM private.enqueue_commerce_event('commerce:'||v_order.id::text||':invoice:'||v_inv::text,'commerce.order_finalized',
  v_order.id,jsonb_build_object('sales_invoice_id',v_inv));
 RETURN v_inv;
END $$;


--
-- Name: finalize_pos_split_payment_session(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.finalize_pos_split_payment_session(p_session_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE s public.pos_split_payment_sessions%ROWTYPE; o public.commerce_orders%ROWTYPE; l public.pos_split_payment_legs%ROWTYPE;
 v_inv UUID; v_pe UUID; v_first UUID; v_count INTEGER; v_error TEXT; v_apply NUMERIC; v_refunds INTEGER; v_status public.pos_split_payment_session_status;
BEGIN
 PERFORM private.refresh_pos_split_payment_session(p_session_id);
 SELECT * INTO s FROM public.pos_split_payment_sessions WHERE id=p_session_id FOR UPDATE;
 SELECT * INTO o FROM public.commerce_orders WHERE id=s.commerce_order_id FOR UPDATE;
 IF s.final_invoice_id IS NOT NULL AND s.status IN('settled','refund_review','refund_pending') THEN RETURN private.pos_split_payment_payload(s.id); END IF;
 IF s.pending_amount>0 OR s.captured_amount+s.held_amount+0.01<s.total_amount THEN RETURN private.pos_split_payment_payload(s.id); END IF;
 UPDATE public.pos_split_payment_sessions SET status='finalizing',finalization_error=NULL,updated_at=now() WHERE id=s.id;
 BEGIN
  v_inv:=private.finalize_commerce_order(o.id);
  FOR l IN SELECT * FROM public.pos_split_payment_legs WHERE session_id=s.id AND status IN('captured','held') ORDER BY sequence_no FOR UPDATE LOOP
   v_apply:=round(COALESCE(l.applied_target_amount,l.requested_amount),2);
   IF l.status='captured' THEN
    IF l.refund_required_amount>0.009 THEN
     INSERT INTO public.pos_split_refund_requests(session_id,leg_id,gross_amount,fee_policy,external_reference,notes,created_by)
     VALUES(s.id,l.id,l.refund_required_amount,'manual_review','GTR-SPLIT-SURPLUS-'||l.id::text,
       'Customer accepted a reduced basket; captured surplus requires explicit refund resolution.',auth.uid())
     ON CONFLICT(leg_id) DO UPDATE SET gross_amount=EXCLUDED.gross_amount,notes=EXCLUDED.notes,updated_at=now()
     WHERE public.pos_split_refund_requests.status IN('review','failed');
    END IF;
    v_pe:=private.allocate_pos_split_receipt_to_invoice(l.id,v_inv);
   ELSE
    IF v_apply<=0.009 THEN
     UPDATE public.pos_split_payment_legs SET status='cancelled',requested_amount=greatest(requested_amount,0.01),applied_target_amount=0,updated_at=now() WHERE id=l.id;
     CONTINUE;
    END IF;
    IF v_apply<l.requested_amount-0.009 THEN
     UPDATE public.pos_split_payment_legs SET metadata=metadata||jsonb_build_object('original_held_amount',requested_amount),requested_amount=v_apply,
      applied_target_amount=v_apply,updated_at=now() WHERE id=l.id;
    END IF;
    v_pe:=public.create_payment_entry(o.customer_id,'store_credit',v_apply,o.currency,o.exchange_rate_applied,format('POS split store credit %s',s.id));
    PERFORM public.allocate_payment(v_pe,jsonb_build_array(jsonb_build_object('sales_invoice_id',v_inv,'amount',v_apply)));
    PERFORM public.post_payment_entry(v_pe);
    UPDATE public.pos_split_payment_legs SET status='allocated',payment_entry_id=v_pe,allocated_at=now(),locked_at=COALESCE(locked_at,now()),updated_at=now() WHERE id=l.id;
   END IF;
   IF v_first IS NULL AND v_apply>0.009 THEN v_first:=v_pe; END IF;
  END LOOP;
 EXCEPTION WHEN OTHERS THEN
  v_error:=SQLERRM;
  UPDATE public.pos_split_payment_sessions SET status='finalization_failed',finalization_error=left(v_error,500),updated_at=now() WHERE id=s.id;
  UPDATE public.commerce_orders SET state='payment_processing',payment_exception='SPLIT_FINALIZATION_FAILED: '||left(v_error,400),updated_at=now() WHERE id=o.id;
  RETURN private.pos_split_payment_payload(s.id);
 END;
 IF NOT EXISTS(SELECT 1 FROM public.sales_invoices i WHERE i.id=v_inv AND i.amount_paid+0.01>=i.total) THEN
  RAISE EXCEPTION 'split finalization produced an invoice that is not fully paid';
 END IF;
 SELECT count(*) INTO v_count FROM public.pos_split_payment_legs WHERE session_id=s.id AND (status='allocated' OR payment_entry_id IS NOT NULL);
 UPDATE public.commerce_orders SET settled_payment_entry_id=v_first,settled_provider=CASE WHEN v_count=1 THEN
   (SELECT tender::text FROM public.pos_split_payment_legs WHERE session_id=s.id AND payment_entry_id IS NOT NULL ORDER BY sequence_no LIMIT 1)
  ELSE 'split_payment' END,
  settled_provider_ref='POS-SPLIT-'||s.id::text,payment_exception=NULL,active_payment_provider=NULL,active_payment_intent_id=NULL,
  state=CASE WHEN fulfillment_mode='dispatch' THEN 'allocation_pending'::public.commerce_order_state ELSE 'paid'::public.commerce_order_state END,
  updated_at=now() WHERE id=o.id;
 SELECT count(*) INTO v_refunds FROM public.pos_split_refund_requests WHERE session_id=s.id AND status<>'settled' AND status<>'cancelled';
 v_status:=CASE WHEN v_refunds>0 THEN 'refund_review'::public.pos_split_payment_session_status ELSE 'settled'::public.pos_split_payment_session_status END;
 UPDATE public.pos_split_payment_sessions SET status=v_status,final_invoice_id=v_inv,settled_at=now(),finalization_error=NULL,
  held_amount=0,pending_amount=0,updated_at=now() WHERE id=s.id;
 PERFORM private.enqueue_commerce_event('commerce:'||o.id::text||':split-settled:'||s.id::text,'commerce.payment_settled',o.id,
  jsonb_build_object('provider','split_payment','split_session_id',s.id,'sales_invoice_id',v_inv,'refunds_outstanding',v_refunds));
 RETURN private.pos_split_payment_payload(s.id);
END $$;


