  RAISE EXCEPTION '% is append-only', TG_TABLE_NAME;
END $$;


--
-- Name: hold_pos_fulfillment_stock(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.hold_pos_fulfillment_stock(p_request_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE r public.pos_fulfillment_requests%ROWTYPE; v_qty numeric; v_wh uuid;
BEGIN
 SELECT * INTO r FROM public.pos_fulfillment_requests WHERE id=p_request_id;
 v_wh:=COALESCE(r.destination_warehouse_id,r.source_warehouse_id);
 v_qty:=public.convert_to_base_uom(r.stock_item_id,r.uom_id,r.qty);
 IF EXISTS(SELECT 1 FROM public.inventory_reservations WHERE pos_fulfillment_request_id=p_request_id AND state='active' AND warehouse_id=v_wh) THEN RETURN; END IF;
 IF public.get_inventory_available_quantity(r.stock_item_id,v_wh)<v_qty THEN
  RAISE EXCEPTION 'the part has not arrived yet (available %, needed %)',public.get_inventory_available_quantity(r.stock_item_id,v_wh),v_qty;
 END IF;
 INSERT INTO public.inventory_reservations(pos_fulfillment_request_id,stock_item_id,warehouse_id,required_qty,reserved_qty,expires_at,state,reservation_reason)
 VALUES(p_request_id,r.stock_item_id,v_wh,v_qty,v_qty,now()+interval '14 days','active','customer_order_hold');
END $$;


--
-- Name: issue_pos_replacement_stock(uuid, jsonb, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.issue_pos_replacement_stock(p_from_warehouse_id uuid, p_lines jsonb, p_notes text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_entry UUID; e JSONB; v_item UUID; v_uom UUID; v_qty NUMERIC; v_base NUMERIC; v_cost NUMERIC; v_cur public.currency_code; v_val public.valuation_method; v_serial UUID;
BEGIN
 IF p_lines IS NULL OR jsonb_typeof(p_lines)<>'array' OR jsonb_array_length(p_lines)=0 THEN RAISE EXCEPTION 'replacement lines required'; END IF;
 IF EXISTS(SELECT 1 FROM public.warehouses WHERE id=p_from_warehouse_id AND is_quarantine) THEN RAISE EXCEPTION 'replacement source must be saleable warehouse'; END IF;
 INSERT INTO public.stock_entries(entry_type,status,from_warehouse_id,notes,created_by,posted_at,document_number)
 VALUES('issue','posted',p_from_warehouse_id,COALESCE(p_notes,'POS replacement issue'),auth.uid(),now(),public.next_series_value('ISS-')) RETURNING id INTO v_entry;
 FOR e IN SELECT * FROM jsonb_array_elements(p_lines) LOOP
  v_item:=(e->>'stock_item_id')::uuid; v_uom:=(e->>'uom_id')::uuid; v_qty:=(e->>'qty')::numeric;
  IF v_qty<=0 THEN RAISE EXCEPTION 'replacement qty must be > 0'; END IF;
  v_base:=public.convert_to_base_uom(v_item,v_uom,v_qty); v_val:=COALESCE(NULLIF(e->>'valuation_method','')::public.valuation_method,'FIFO');
  SELECT unit_cost,currency INTO v_cost,v_cur FROM public.stock_levels WHERE stock_item_id=v_item AND warehouse_id=p_from_warehouse_id FOR UPDATE;
  IF COALESCE((SELECT quantity FROM public.stock_levels WHERE stock_item_id=v_item AND warehouse_id=p_from_warehouse_id),0)<v_base THEN RAISE EXCEPTION 'insufficient replacement stock'; END IF;
  PERFORM public._consume_fifo_batches(v_item,p_from_warehouse_id,v_base);
  PERFORM public._adjust_stock_level(v_item,p_from_warehouse_id,-v_base,v_val,COALESCE(v_cost,0),COALESCE(v_cur,'USD'));
  INSERT INTO public.stock_entry_lines(stock_entry_id,stock_item_id,uom_id,qty,qty_base,unit_cost,currency,valuation_method)
   VALUES(v_entry,v_item,v_uom,v_qty,v_base,COALESCE(v_cost,0),COALESCE(v_cur,'USD'),v_val);
  IF e ? 'replacement_serial_id' THEN
   v_serial:=(e->>'replacement_serial_id')::uuid;
   UPDATE public.stock_serials SET status='sold',warehouse_id=NULL WHERE id=v_serial AND stock_item_id=v_item AND status='in_stock';
   IF NOT FOUND THEN RAISE EXCEPTION 'replacement serial unavailable'; END IF;
  END IF;
 END LOOP;
 RETURN v_entry;
END $$;


--
-- Name: mark_payment_resolution_letter_rendered(uuid, text, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.mark_payment_resolution_letter_rendered(p_letter_id uuid, p_bucket text, p_path text, p_sha256 text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
 IF auth.role()<>'service_role' THEN RAISE EXCEPTION 'service role required'; END IF;
 UPDATE public.payment_resolution_letters SET rendered_storage_bucket=p_bucket,rendered_storage_path=p_path,rendered_sha256=p_sha256,rendered_at=now() WHERE id=p_letter_id;
END $$;


--
-- Name: morning_summary_text(date, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.morning_summary_text(p_day date, d jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
 SELECT concat_ws(E'\n',
  'GTR Auto ' || to_char(p_day, 'Dy DD Mon') || ':',
  COALESCE((SELECT string_agg(format('Sales %s %s net (%s invoices, margin %s%%)', s->>'currency',
        to_char((s->>'net')::numeric, 'FM999,999,990.00'), s->>'invoices', COALESCE(round((s->>'margin_pct')::numeric)::text, '-')), E'\n')
     FROM jsonb_array_elements(COALESCE(d->'sales','[]'::jsonb)) s), 'No sales'),
  (SELECT 'Unpaid from the day: ' || string_agg(format('%s %s', u->>'currency', to_char((u->>'amount')::numeric, 'FM999,999,990.00')), ' + ')
     FROM jsonb_array_elements(COALESCE(d->'unpaid_today','[]'::jsonb)) u),
  (SELECT 'Till differences: ' || string_agg(format('%s %s %s', COALESCE(t->>'cashier','till'), t->>'currency', to_char((t->>'variance')::numeric, 'FM999,990.00')), ', ')
     FROM jsonb_array_elements(COALESCE(d->'tills','[]'::jsonb)) t WHERE abs(COALESCE((t->>'variance')::numeric, 0)) > 0.009),
  (SELECT 'Drivers still hold: ' || string_agg(format('%s %s', c->>'currency', to_char((c->>'amount')::numeric, 'FM999,999,990.00')), ' + ')
     FROM jsonb_array_elements(COALESCE(d->'driver_cash_held','[]'::jsonb)) c),
  CASE WHEN COALESCE((d->'deliveries'->>'failed')::int, 0) > 0 THEN 'Failed deliveries: ' || (d->'deliveries'->>'failed') END,
  CASE WHEN COALESCE((d->>'low_stock_count')::int, 0) > 0 THEN 'Parts at or under reorder point: ' || (d->>'low_stock_count') END,
  CASE WHEN COALESCE((d->>'approvals_waiting')::int, 0) > 0 THEN 'Waiting for approval now: ' || (d->>'approvals_waiting') END,
  'Details: Staff > Today')
$$;


--
-- Name: pos_approver_source(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.pos_approver_source(p_user uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT CASE
    WHEN p_user IS NULL THEN NULL
    WHEN EXISTS (SELECT 1 FROM public.staff_roles sr WHERE sr.user_id = p_user AND sr.role = 'admin') THEN 'admin_role'
    ELSE (SELECT private.employee_approver_source(e.id) FROM public.employees e WHERE e.user_id = p_user
          ORDER BY private.employee_approver_source(e.id) NULLS LAST LIMIT 1)
  END;
$$;


--
-- Name: pos_card_terminal_attempt_payload(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.pos_card_terminal_attempt_payload(p_attempt_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 SELECT jsonb_build_object(
  'attempt_id',a.id,'request_id',a.request_id,'operation',a.operation,'status',a.status,
  'terminal_id',a.terminal_id,'amount',a.amount,'currency',a.currency,'external_ref',a.external_ref,
  'terminal_transaction_id',a.terminal_transaction_id,'rrn',a.rrn,'authorization_code',a.authorization_code,
  'card_last4',a.card_last4,'card_scheme',a.card_scheme,'response_code',a.response_code,'response_message',a.response_message,
  'commerce_order_id',a.commerce_order_id,'delivery_job_id',a.delivery_job_id,'source_invoice_id',a.source_invoice_id,
  'parent_attempt_id',a.parent_attempt_id,'split_leg_id',a.split_leg_id,'split_refund_request_id',a.split_refund_request_id,
  'payment_entry_id',a.payment_entry_id,'invoice_id',a.invoice_id,'finance_refund_id',a.finance_refund_id,'credit_note_id',a.credit_note_id,'credit_note_number',(SELECT cn.document_number FROM public.sales_invoices cn WHERE cn.id=a.credit_note_id),'finalization_error',a.finalization_error,
  'terminal',jsonb_build_object('id',t.id,'code',t.code,'label',t.label,'acquirer_name',t.acquirer_name,
    'external_terminal_id',t.external_terminal_id,'adapter_key',t.adapter_key,'adapter_config',t.adapter_config,'allow_delivery',t.allow_delivery)
 ) FROM public.pos_card_terminal_attempts a JOIN public.pos_card_terminals t ON t.id=a.terminal_id WHERE a.id=p_attempt_id;
$$;


--
-- Name: pos_invoice_till_session_sync(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.pos_invoice_till_session_sync() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
 IF NEW.till_session_id IS NULL AND NEW.cart_id IS NOT NULL THEN
  SELECT c.till_session_id INTO NEW.till_session_id FROM public.pos_carts c WHERE c.id=NEW.cart_id;
 END IF; RETURN NEW;
END $$;


--
-- Name: pos_split_payment_payload(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.pos_split_payment_payload(p_session_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 SELECT jsonb_build_object(
  'session_id',s.id,'order_id',s.commerce_order_id,'status',s.status,'total',s.total_amount,'currency',s.currency,
  'captured_amount',s.captured_amount,'held_amount',s.held_amount,'pending_amount',s.pending_amount,'refunded_amount',s.refunded_amount,
  'locked_amount',round(s.captured_amount+s.held_amount,2),
  'balance_due',greatest(round(s.total_amount-s.captured_amount-s.held_amount,2),0),
  'available_to_allocate',greatest(round(s.total_amount-s.captured_amount-s.held_amount-s.pending_amount,2),0),
  'final_invoice_id',s.final_invoice_id,'finalization_error',s.finalization_error,
  'reduced_basket_accepted_at',s.reduced_basket_accepted_at,'reduced_basket_customer_confirmed',s.reduced_basket_customer_confirmed,
  'reduced_basket_notes',s.reduced_basket_notes,'created_at',s.created_at,'updated_at',s.updated_at,
  'legs',COALESCE((SELECT jsonb_agg(jsonb_build_object(
    'id',l.id,'request_id',l.request_id,'sequence_no',l.sequence_no,'tender',l.tender,'amount',l.requested_amount,'status',l.status,
    'applied_target_amount',l.applied_target_amount,'refund_required_amount',l.refund_required_amount,
    'external_reference',l.external_reference,'provider_intent_id',l.provider_intent_id,'provider_ref',l.provider_ref,
    'card_terminal_attempt_id',l.card_terminal_attempt_id,'payment_entry_id',l.payment_entry_id,'status_detail',l.status_detail,
    'created_at',l.created_at,'locked_at',l.locked_at,'failed_at',l.failed_at,'refunded_at',l.refunded_at
   ) ORDER BY l.sequence_no) FROM public.pos_split_payment_legs l WHERE l.session_id=s.id),'[]'::jsonb),
  'accepted_lines',COALESCE((SELECT jsonb_agg(jsonb_build_object(
    'cart_line_id',a.cart_line_id,'original_qty',a.original_qty,'accepted_qty',a.accepted_qty,
    'accepted_line_total',a.accepted_line_total,'auto_included_core',a.auto_included_core
   ) ORDER BY a.accepted_at,a.cart_line_id) FROM public.pos_split_acceptance_lines a WHERE a.session_id=s.id),'[]'::jsonb),
  'refunds',COALESCE((SELECT jsonb_agg(jsonb_build_object(
    'id',r.id,'leg_id',r.leg_id,'status',r.status,'gross_amount',r.gross_amount,'fee_policy',r.fee_policy,
    'estimated_provider_fee',r.estimated_provider_fee,'estimated_transfer_fee',r.estimated_transfer_fee,
    'approved_customer_fee',r.approved_customer_fee,'actual_provider_fee',r.actual_provider_fee,
    'actual_transfer_fee',r.actual_transfer_fee,'actual_customer_fee',r.actual_customer_fee,
    'net_customer_refund',r.net_customer_refund,'provider_ref',r.provider_ref,'expected_settlement_at',r.expected_settlement_at,
    'failure_reason',r.failure_reason,'notes',r.notes
   ) ORDER BY r.created_at) FROM public.pos_split_refund_requests r WHERE r.session_id=s.id),'[]'::jsonb)
 ) FROM public.pos_split_payment_sessions s WHERE s.id=p_session_id;
$$;


--
-- Name: post_pos_split_unapplied_payment_entry(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.post_pos_split_unapplied_payment_entry(p_payment_entry_id uuid, p_leg_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE pe public.payment_entries%ROWTYPE; l public.pos_split_payment_legs%ROWTYPE; v_alloc NUMERIC; v_acct TEXT; v_journal UUID;
BEGIN
 PERFORM public._payments_rpc_enter();
 SELECT * INTO l FROM public.pos_split_payment_legs WHERE id=p_leg_id FOR UPDATE;
 SELECT * INTO pe FROM public.payment_entries WHERE id=p_payment_entry_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'payment entry not found'; END IF;
 IF pe.status='posted' THEN RETURN pe.id; END IF;
 IF pe.status<>'draft' OR pe.tender='store_credit' THEN RAISE EXCEPTION 'cash/provider draft payment entry required'; END IF;
 IF l.id IS NULL OR l.requested_amount<>pe.amount OR l.tender<>pe.tender THEN RAISE EXCEPTION 'split leg/payment mismatch'; END IF;
 SELECT COALESCE(SUM(amount),0) INTO v_alloc FROM public.payment_allocations WHERE payment_entry_id=pe.id;
 IF v_alloc>0.001 THEN RAISE EXCEPTION 'split suspense receipt cannot already be allocated'; END IF;
 v_acct:=public.gl_account_for_payment_tender(pe.tender);
 v_journal:=public.post_journal_entry(CURRENT_DATE,format('POS split receipt %s',COALESCE(pe.document_number,pe.id::text)),pe.currency,pe.exchange_rate_applied,
  jsonb_build_array(jsonb_build_object('account_code',v_acct,'debit',pe.amount,'credit',0,'currency',pe.currency),
                    jsonb_build_object('account_code','2215','debit',0,'credit',pe.amount,'currency',pe.currency)));
 UPDATE public.payment_entries SET status='posted',journal_entry_id=v_journal,store_credit_issued=0,posted_by=auth.uid(),posted_at=now(),updated_at=now() WHERE id=pe.id;
 PERFORM public.emit_domain_event('payment_partial','pos-split:capture:'||l.id::text,
  jsonb_build_object('split_leg_id',l.id,'payment_entry_id',pe.id,'amount',pe.amount,'currency',pe.currency,'tender',pe.tender,'suspense_account','2215'),
  auth.uid(),format('GTR Auto: split payment locked %s %s via %s',pe.amount,pe.currency,pe.tender));
 RETURN pe.id;
END $$;


--
-- Name: post_unapplied_payment_entry(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.post_unapplied_payment_entry(p_payment_entry_id uuid, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_pe public.payment_entries%ROWTYPE;
  v_cash_acct TEXT;
  v_journal UUID;
  v_allocated NUMERIC;
BEGIN
  SELECT * INTO v_pe
  FROM public.payment_entries
  WHERE id = p_payment_entry_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'payment entry not found: %', p_payment_entry_id;
  END IF;
  IF v_pe.status = 'posted' THEN
    RETURN v_pe.id;
  END IF;
  IF v_pe.status <> 'draft' THEN
    RAISE EXCEPTION 'only draft payments can be posted as unapplied receipts';
  END IF;
  IF v_pe.tender = 'store_credit' THEN
    RAISE EXCEPTION 'store_credit is not a cash receipt tender';
  END IF;

  SELECT COALESCE(SUM(amount),0)
    INTO v_allocated
  FROM public.payment_allocations
  WHERE payment_entry_id = v_pe.id;
  IF v_allocated > 0.001 THEN
    RAISE EXCEPTION 'unapplied receipt cannot already have invoice allocations';
  END IF;

  v_cash_acct := public.gl_account_for_payment_tender(v_pe.tender);
  v_journal := public.post_journal_entry(
    CURRENT_DATE,
    format('Unapplied receipt %s', COALESCE(v_pe.document_number, v_pe.id::text)),
    v_pe.currency,
    v_pe.exchange_rate_applied,
    jsonb_build_array(
      jsonb_build_object(
        'account_code', v_cash_acct,
        'debit', v_pe.amount,
        'credit', 0,
        'currency', v_pe.currency
      ),
      jsonb_build_object(
        'account_code', '2200',
        'debit', 0,
        'credit', v_pe.amount,
        'currency', v_pe.currency
      )
    )
  );

  PERFORM public._append_store_credit(
    v_pe.customer_id,
    'issue',
    v_pe.amount,
    v_pe.currency,
    v_pe.exchange_rate_applied,
    v_pe.id,
    v_journal,
    COALESCE(NULLIF(trim(COALESCE(p_reason,'')),''), 'Unapplied commerce receipt')
  );

  UPDATE public.payment_entries
  SET status = 'posted',
      journal_entry_id = v_journal,
      store_credit_issued = v_pe.amount,
      posted_by = auth.uid(),
      posted_at = now(),
      updated_at = now()
  WHERE id = v_pe.id;

  PERFORM public.emit_domain_event(
    'payment_received',
    'payment:unapplied:' || v_pe.id::text,
    jsonb_build_object(
      'payment_entry_id', v_pe.id,
      'amount', v_pe.amount,
      'allocated', 0,
      'store_credit_issued', v_pe.amount,
      'currency', v_pe.currency,
      'tender', v_pe.tender,
      'gl_account', v_cash_acct,
      'reason', p_reason
    ),
    auth.uid(),
    format('GTR Auto: unapplied payment received %s %s', v_pe.amount, v_pe.currency)
  );

  RETURN v_pe.id;
END;
$$;


--
-- Name: FUNCTION post_unapplied_payment_entry(p_payment_entry_id uuid, p_reason text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.post_unapplied_payment_entry(p_payment_entry_id uuid, p_reason text) IS 'Posts a verified but unapplied cash/provider receipt to its tender GL account and customer-credit liability, preserving money received when commerce finalization cannot allocate it.';


--
-- Name: queue_staff_message(uuid, text, text, text, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.queue_staff_message(p_user_id uuid, p_event_code text, p_dedupe_key text, p_body text, p_payload jsonb DEFAULT '{}'::jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE s public.staff_alert_settings%ROWTYPE; v_event uuid;
BEGIN
 SELECT * INTO s FROM public.staff_alert_settings WHERE user_id = p_user_id AND phone_e164 IS NOT NULL;
 IF NOT FOUND THEN RETURN false; END IF;
 INSERT INTO public.domain_events(event_code, dedupe_key, payload, actor_user_id)
 VALUES (p_event_code, p_dedupe_key, COALESCE(p_payload, '{}'::jsonb), NULL)
 ON CONFLICT (event_code, dedupe_key) DO NOTHING RETURNING id INTO v_event;
 IF v_event IS NULL THEN RETURN false; END IF;  -- already sent
 INSERT INTO public.sms_outbox(domain_event_id, event_code, recipient_user_id, phone_e164, body, channel)
 VALUES (v_event, p_event_code, p_user_id, s.phone_e164, left(p_body, 640), s.channel);
 RETURN true;
END $$;


--
-- Name: receive_external_return_to_quarantine(jsonb, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.receive_external_return_to_quarantine(p_lines jsonb, p_notes text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_quar UUID; v_entry UUID; e JSONB; v_item UUID; v_uom UUID; v_qty NUMERIC; v_base NUMERIC; v_price NUMERIC; v_currency public.currency_code;
BEGIN
 SELECT id INTO v_quar FROM public.warehouses WHERE is_quarantine AND is_active ORDER BY code LIMIT 1;
 IF v_quar IS NULL THEN RAISE EXCEPTION 'quarantine warehouse required'; END IF;
 INSERT INTO public.stock_entries(entry_type,status,document_number,to_warehouse_id,notes,created_by,posted_at)
 VALUES('receipt','posted',public.next_series_value('RCV-'),v_quar,COALESCE(p_notes,'Customer return to Quarantine'),auth.uid(),now()) RETURNING id INTO v_entry;
 FOR e IN SELECT * FROM jsonb_array_elements(COALESCE(p_lines,'[]'::jsonb)) LOOP
  v_item:=(e->>'stock_item_id')::uuid; v_uom:=(e->>'uom_id')::uuid; v_qty:=(e->>'qty')::numeric;
  IF v_qty<=0 THEN RAISE EXCEPTION 'return qty must be > 0'; END IF;
  v_base:=public.convert_to_base_uom(v_item,v_uom,v_qty); v_price:=COALESCE(NULLIF(e->>'unit_price','')::numeric,0);
  v_currency:=COALESCE(NULLIF(e->>'currency','')::public.currency_code,'USD');
  INSERT INTO public.stock_entry_lines(stock_entry_id,stock_item_id,uom_id,qty,qty_base,unit_cost,currency,valuation_method)
   VALUES(v_entry,v_item,v_uom,v_qty,v_base,0,v_currency,'FIFO');
  PERFORM public._adjust_stock_level(v_item,v_quar,v_base,'FIFO',0,v_currency);
  INSERT INTO public.stock_batches(batch_code,stock_item_id,warehouse_id,valuation_method,unit_cost,currency,qty_on_hand)
   VALUES(public.next_series_value('BATCH-'),v_item,v_quar,'FIFO',0,v_currency,v_base);
 END LOOP;
 PERFORM public.emit_domain_event('quarantine_received','pos-external-return:'||v_entry::text,jsonb_build_object('stock_entry_id',v_entry,'notes',p_notes));
 RETURN v_entry;
END $$;


--
-- Name: refresh_pos_split_payment_session(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.refresh_pos_split_payment_session(p_session_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE s public.pos_split_payment_sessions%ROWTYPE; v_cap NUMERIC:=0; v_hold NUMERIC:=0; v_pending NUMERIC:=0; v_refunded NUMERIC:=0;
 v_status public.pos_split_payment_session_status; v_unknown BOOLEAN:=false; v_active UUID; v_provider TEXT;
BEGIN
 SELECT * INTO s FROM public.pos_split_payment_sessions WHERE id=p_session_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'split payment session not found'; END IF;
 SELECT COALESCE(SUM(requested_amount) FILTER(WHERE status IN('captured','allocated','refund_review','refund_pending')),0),
        COALESCE(SUM(requested_amount) FILTER(WHERE status='held'),0),
        COALESCE(SUM(requested_amount) FILTER(WHERE status IN('pending','unknown')),0),
        COALESCE(SUM(requested_amount) FILTER(WHERE status='refunded'),0),
        COALESCE(bool_or(status='unknown'),false)
 INTO v_cap,v_hold,v_pending,v_refunded,v_unknown FROM public.pos_split_payment_legs WHERE session_id=s.id;
 IF s.status IN('settled','refunded','cancelled') THEN v_status:=s.status;
 ELSIF s.status IN('refund_review','refund_pending') THEN v_status:=s.status;
 ELSIF v_pending>0 THEN v_status:='leg_pending';
 ELSIF v_cap+v_hold+0.01>=s.total_amount THEN v_status:='fully_committed';
 ELSIF v_cap+v_hold>0 THEN v_status:='partially_captured'; ELSE v_status:='open'; END IF;
 UPDATE public.pos_split_payment_sessions SET status=v_status,captured_amount=round(v_cap,2),held_amount=round(v_hold,2),
  pending_amount=round(v_pending,2),refunded_amount=round(v_refunded,2),updated_at=now(),updated_by=auth.uid() WHERE id=s.id;
 SELECT l.provider_intent_id,l.tender::text INTO v_active,v_provider FROM public.pos_split_payment_legs l
  WHERE l.session_id=s.id AND l.status IN('pending','unknown') ORDER BY l.sequence_no LIMIT 1;
 IF v_status NOT IN('settled','refunded','cancelled','refund_review','refund_pending') THEN
  UPDATE public.commerce_orders SET
   state=CASE WHEN v_cap+v_hold+v_pending>0 THEN 'payment_processing'::public.commerce_order_state ELSE 'awaiting_payment'::public.commerce_order_state END,
   active_payment_provider=CASE WHEN v_active IS NOT NULL THEN v_provider ELSE NULL END,
   active_payment_intent_id=v_active,
   payment_exception=CASE
    WHEN v_unknown THEN 'SPLIT_PAYMENT_OUTCOME_UNKNOWN'
    WHEN v_pending=0 AND v_cap+v_hold>0 AND v_cap+v_hold+0.01<s.total_amount THEN 'SPLIT_BALANCE_DUE'
    ELSE NULL END,
   reservation_expires_at=CASE WHEN v_cap+v_hold+v_pending>0 THEN greatest(COALESCE(reservation_expires_at,now()),now()+interval '60 minutes') ELSE reservation_expires_at END,
   updated_at=now() WHERE id=s.commerce_order_id AND settled_payment_entry_id IS NULL;
  IF v_cap+v_hold+v_pending>0 THEN
   UPDATE public.inventory_reservations SET expires_at=greatest(COALESCE(expires_at,now()),now()+interval '60 minutes')
    WHERE commerce_order_id=s.commerce_order_id AND state='active';
  END IF;
 END IF;
 RETURN private.pos_split_payment_payload(s.id);
END $$;


--
-- Name: release_commerce_order(uuid, public.commerce_order_state, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.release_commerce_order(p_order_id uuid, p_terminal_state public.commerce_order_state, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_order public.commerce_orders%ROWTYPE; BEGIN
 SELECT * INTO v_order FROM public.commerce_orders WHERE id=p_order_id FOR UPDATE; IF NOT FOUND THEN RETURN; END IF;
 IF v_order.finalized_at IS NOT NULL OR v_order.settled_payment_entry_id IS NOT NULL THEN RETURN; END IF;
 UPDATE public.inventory_reservations SET state=CASE WHEN p_terminal_state='payment_expired' THEN 'expired'::public.inventory_reservation_state ELSE 'released'::public.inventory_reservation_state END,
   released_at=now() WHERE commerce_order_id=p_order_id AND state='active';
 UPDATE public.commerce_orders SET state=p_terminal_state,payment_exception=COALESCE(p_reason,payment_exception),updated_at=now() WHERE id=p_order_id;
 UPDATE public.pos_carts SET checkout_locked_at=NULL,checkout_order_id=NULL,updated_at=now() WHERE id=v_order.cart_id AND status='open' AND checkout_order_id=p_order_id;
 PERFORM private.enqueue_commerce_event('commerce:'||p_order_id::text||':'||p_terminal_state::text,'commerce.'||p_terminal_state::text,p_order_id,jsonb_build_object('reason',p_reason)); END; $$;


--
-- Name: require_admin(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.require_admin() RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.staff_roles sr WHERE sr.user_id = auth.uid() AND sr.role = 'admin') THEN
    RAISE EXCEPTION 'admin role required';
  END IF;
END $$;


--
-- Name: require_approver_admin(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.require_approver_admin() RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.staff_roles sr WHERE sr.user_id = auth.uid() AND sr.role IN ('admin','hr')) THEN
    RAISE EXCEPTION 'admin or HR role required';
  END IF;
END $$;


--
-- Name: require_pos_reason(text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.require_pos_reason(p_action text, p_reason_code text) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
 IF COALESCE((SELECT reason_required FROM public.pos_approval_policies WHERE action=p_action),true) THEN
  IF trim(COALESCE(p_reason_code,''))='' OR NOT EXISTS(SELECT 1 FROM public.pos_approval_reason_codes WHERE action=p_action AND code=p_reason_code AND is_active) THEN
   RAISE EXCEPTION 'valid active reason code required for %',p_action;
  END IF;
 END IF;
END $$;


--
-- Name: send_morning_summaries(date); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.send_morning_summaries(p_day date DEFAULT NULL::date) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_day date := COALESCE(p_day, (now() AT TIME ZONE 'Africa/Harare')::date - 1); s record; d jsonb; v_text text; v_n integer := 0;
BEGIN
 FOR s IN SELECT a.user_id FROM public.staff_alert_settings a WHERE a.morning_summary AND a.phone_e164 IS NOT NULL LOOP
  BEGIN
   -- Run the dashboard as this person: its own role and branch checks decide what they get.
   PERFORM set_config('request.jwt.claims', json_build_object('sub', s.user_id, 'role', 'authenticated')::text, true);
   d := public.get_daily_dashboard(v_day, NULL);
  EXCEPTION WHEN OTHERS THEN
   d := NULL;  -- no longer a manager / finance / admin: nothing to send
  END;
  PERFORM set_config('request.jwt.claims', '', true);
  CONTINUE WHEN d IS NULL;
  v_text := private.morning_summary_text(v_day, d);
  IF private.queue_staff_message(s.user_id, 'morning_summary', 'morning:' || v_day || ':' || s.user_id, v_text, jsonb_build_object('day', v_day)) THEN
   v_n := v_n + 1;
  END IF;
  PERFORM set_config('app.staff_ops_notify','1',true);
  INSERT INTO public.staff_ops_notifications(kind, recipient_user_id, title, body, ref_key, href)
  VALUES ('morning_summary', s.user_id, 'Yesterday at a glance', v_text, 'morning:' || v_day, '/staff/dashboard?date=' || v_day)
  ON CONFLICT (recipient_user_id, ref_key) WHERE ref_key IS NOT NULL DO NOTHING;
  PERFORM set_config('app.staff_ops_notify','',true);
 END LOOP;
 RETURN v_n;
END $$;


--
-- Name: settle_commerce_payment(uuid, text, uuid, text, numeric, public.currency_code, numeric, public.currency_code, numeric, numeric); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.settle_commerce_payment(p_order_id uuid, p_provider text, p_provider_intent_id uuid, p_provider_ref text, p_amount numeric, p_currency public.currency_code, p_exchange_rate numeric, p_settlement_currency public.currency_code, p_settlement_amount numeric, p_settlement_exchange_rate numeric) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_leg UUID;
BEGIN
 SELECT l.id INTO v_leg FROM public.pos_split_payment_legs l JOIN public.pos_split_payment_sessions s ON s.id=l.session_id
 WHERE s.commerce_order_id=p_order_id AND l.tender::text=p_provider AND l.provider_intent_id=p_provider_intent_id
 ORDER BY l.sequence_no LIMIT 1;
 IF v_leg IS NOT NULL THEN
  RETURN private.capture_pos_split_external_leg(v_leg,p_provider,p_provider_intent_id,p_provider_ref,p_amount,p_currency,p_exchange_rate,
    p_settlement_currency,p_settlement_amount,p_settlement_exchange_rate);
 END IF;
 RETURN private.settle_commerce_payment_full_legacy(p_order_id,p_provider,p_provider_intent_id,p_provider_ref,p_amount,p_currency,p_exchange_rate,
   p_settlement_currency,p_settlement_amount,p_settlement_exchange_rate);
END $$;


--
-- Name: settle_commerce_payment_full_legacy(uuid, text, uuid, text, numeric, public.currency_code, numeric, public.currency_code, numeric, numeric); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.settle_commerce_payment_full_legacy(p_order_id uuid, p_provider text, p_provider_intent_id uuid, p_provider_ref text, p_amount numeric, p_currency public.currency_code, p_exchange_rate numeric, p_settlement_currency public.currency_code, p_settlement_amount numeric, p_settlement_exchange_rate numeric) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_order public.commerce_orders%ROWTYPE;
  v_inv UUID;
  v_pe UUID;
  v_error TEXT;
BEGIN
  IF p_provider NOT IN ('contipay','paynow','ecocash','cash','bank') THEN
    RAISE EXCEPTION 'unsupported provider';
  END IF;

  SELECT * INTO v_order
  FROM public.commerce_orders
  WHERE id=p_order_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'commerce order not found'; END IF;

  IF abs(p_amount-v_order.total)>0.001 OR p_currency<>v_order.currency THEN
    RAISE EXCEPTION 'payment does not match immutable checkout snapshot';
  END IF;

  IF v_order.settled_payment_entry_id IS NOT NULL THEN
    v_pe:=public.create_payment_entry(
      v_order.customer_id,
      p_provider::public.payment_tender,
      p_amount,
      p_currency,
      p_exchange_rate,
      format('%s duplicate settlement for commerce order %s',p_provider,v_order.id),
      p_settlement_currency,
      p_settlement_amount,
      p_settlement_exchange_rate
    );
    PERFORM private.post_unapplied_payment_entry(
      v_pe,
      format('Duplicate %s settlement for commerce order %s; held as customer credit pending refund/review.', p_provider, v_order.id)
    );
    INSERT INTO public.commerce_payment_exceptions(
      commerce_order_id,provider,provider_intent_id,provider_ref,amount,currency,
      exception_code,detail,payment_entry_id
    ) VALUES(
      v_order.id,p_provider,p_provider_intent_id,p_provider_ref,p_amount,p_currency,
      'DUPLICATE_PROVIDER_SETTLEMENT',
      'Order already has a settled payment; duplicate posted as unapplied customer credit pending refund/review.',
      v_pe
    );
    PERFORM private.enqueue_commerce_event(
      'commerce:'||v_order.id::text||':duplicate-settlement:'||p_provider||':'||COALESCE(p_provider_intent_id::text,p_provider_ref,'unknown'),
      'commerce.payment_exception',
      v_order.id,
      jsonb_build_object('code','DUPLICATE_PROVIDER_SETTLEMENT','provider',p_provider,'payment_entry_id',v_pe)
    );
    RETURN v_pe;
  END IF;

  BEGIN
    v_inv:=private.finalize_commerce_order(v_order.id);
  EXCEPTION WHEN OTHERS THEN
    v_error:=SQLERRM;
  END;

  IF v_inv IS NULL THEN
    v_pe:=public.create_payment_entry(
      v_order.customer_id,
      p_provider::public.payment_tender,
      p_amount,
      p_currency,
      p_exchange_rate,
      format('%s settlement pending order repair %s',p_provider,v_order.id),
      p_settlement_currency,
      p_settlement_amount,
      p_settlement_exchange_rate
    );
    PERFORM private.post_unapplied_payment_entry(
      v_pe,
      format('%s settlement received for commerce order %s but finalization failed: %s',p_provider,v_order.id,COALESCE(v_error,'unknown error'))
    );
    UPDATE public.commerce_orders
      SET state='allocation_pending',
          settled_payment_entry_id=v_pe,
          settled_provider=p_provider,
          settled_provider_ref=p_provider_ref,
          payment_exception=v_error,
          updated_at=now()
      WHERE id=v_order.id;
    INSERT INTO public.commerce_payment_exceptions(
      commerce_order_id,provider,provider_intent_id,provider_ref,amount,currency,
      exception_code,detail,payment_entry_id
    ) VALUES(
      v_order.id,p_provider,p_provider_intent_id,p_provider_ref,p_amount,p_currency,
      'PAID_ORDER_FINALIZATION_FAILED',v_error,v_pe
    );
    PERFORM private.enqueue_commerce_event(
      'commerce:'||v_order.id::text||':finalization-failed:'||COALESCE(p_provider_intent_id::text,p_provider_ref,'unknown'),
      'commerce.payment_exception',
      v_order.id,
      jsonb_build_object('code','PAID_ORDER_FINALIZATION_FAILED','provider',p_provider,'payment_entry_id',v_pe,'detail',v_error)
    );
    RETURN v_pe;
  END IF;

  v_pe:=public.create_payment_entry(
    v_order.customer_id,
    p_provider::public.payment_tender,
    p_amount,
    p_currency,
    p_exchange_rate,
    format('%s commerce order %s',p_provider,v_order.id),
    p_settlement_currency,
    p_settlement_amount,
    p_settlement_exchange_rate
  );
  PERFORM public.allocate_payment(
    v_pe,
    jsonb_build_array(jsonb_build_object('sales_invoice_id',v_inv,'amount',p_amount))
  );
  PERFORM public.post_payment_entry(v_pe);
  UPDATE public.commerce_orders
    SET settled_payment_entry_id=v_pe,
        settled_provider=p_provider,
        settled_provider_ref=p_provider_ref,
        state=CASE WHEN fulfillment_mode='dispatch'
          THEN 'allocation_pending'::public.commerce_order_state
          ELSE 'paid'::public.commerce_order_state END,
        payment_exception=NULL,
        updated_at=now()
    WHERE id=v_order.id;
  PERFORM private.enqueue_commerce_event(
    'commerce:'||v_order.id::text||':paid',
    'commerce.payment_settled',
    v_order.id,
    jsonb_build_object('provider',p_provider,'provider_ref',p_provider_ref,'payment_entry_id',v_pe,'sales_invoice_id',v_inv)
  );
  RETURN v_pe;
END;
$$;


--
-- Name: staff_badge_grant_active(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.staff_badge_grant_active() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM private.staff_badge_grants g
    WHERE g.id = NULLIF(current_setting('gtr.pos_badge_grant', true), '')::uuid
      AND g.txid = txid_current()
      AND g.requested_by = auth.uid());
$$;


--
-- Name: supplier_lead_days(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.supplier_lead_days(p_supplier_id uuid, p_stock_item_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 WITH r AS (
  SELECT DISTINCT gr.id, extract(epoch FROM gr.submitted_at - po.submitted_at) / 86400.0 AS days,
         EXISTS (SELECT 1 FROM public.goods_receipt_lines l WHERE l.goods_receipt_id=gr.id AND l.stock_item_id=p_stock_item_id) AS this_part
    FROM public.goods_receipts gr JOIN public.purchase_orders po ON po.id=gr.purchase_order_id
   WHERE gr.supplier_id=p_supplier_id AND gr.status IN ('submitted','approved') AND gr.submitted_at IS NOT NULL
     AND po.submitted_at IS NOT NULL AND gr.submitted_at >= po.submitted_at AND gr.submitted_at > now() - interval '365 days')
 SELECT CASE
  WHEN EXISTS (SELECT 1 FROM r WHERE this_part) THEN
   (SELECT jsonb_build_object('days', round(percentile_cont(0.5) WITHIN GROUP (ORDER BY days)), 'samples', count(*), 'scope', 'part') FROM r WHERE this_part)
  WHEN EXISTS (SELECT 1 FROM r) THEN
   (SELECT jsonb_build_object('days', round(percentile_cont(0.5) WITHIN GROUP (ORDER BY days)), 'samples', count(*), 'scope', 'supplier') FROM r)
 END
$$;


--
-- Name: suspend_customer_if_due(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.suspend_customer_if_due(p_customer_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_id uuid; v_findings jsonb;
BEGIN
 IF p_customer_id IS NULL THEN RETURN NULL; END IF;
 SELECT id INTO v_id FROM public.customer_suspensions WHERE customer_id=p_customer_id AND status='active';
 IF FOUND THEN RETURN v_id; END IF;
 v_findings := private.customer_suspension_findings(p_customer_id);
 IF jsonb_array_length(v_findings)=0 THEN RETURN NULL; END IF;
 INSERT INTO public.customer_suspensions(customer_id,status,source,reason,findings)
 VALUES(p_customer_id,'active','automatic',private.suspension_reason(v_findings),v_findings)
 ON CONFLICT DO NOTHING RETURNING id INTO v_id;
 RETURN v_id;
END $$;


--
-- Name: suspension_reason(jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.suspension_reason(p_findings jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
 SELECT 'Failed to settle: ' || string_agg(DISTINCT CASE f->>'rule'
   WHEN 'on_account_overdue' THEN 'balance left on account unpaid after 7 days'
   WHEN 'invoice_overdue' THEN 'invoice unpaid after 30 days'
   WHEN 'refused_cod' THEN 'refused pay-on-delivery deliveries' END, '; ')
 FROM jsonb_array_elements(p_findings) f
$$;


--
-- Name: sweep_approval_alerts(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sweep_approval_alerts() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE u record; it jsonb; v_n integer := 0; v_limit interval; v_urgent boolean;
BEGIN
 PERFORM set_config('app.staff_ops_notify','1',true);
 FOR u IN SELECT DISTINCT sr.user_id, COALESCE(a.urgent_approvals, false) AS wants_text FROM public.staff_roles sr
          LEFT JOIN public.staff_alert_settings a ON a.user_id = sr.user_id
          WHERE sr.role IN('admin','finance','sales','dispatcher','warehouse') LOOP
  FOR it IN SELECT * FROM jsonb_array_elements(private.approvals_for(u.user_id)) LOOP
   v_urgent := (it->>'urgent')::boolean;
   v_limit := CASE WHEN v_urgent THEN interval '10 minutes' ELSE interval '4 hours' END;
   CONTINUE WHEN (it->>'waiting_since')::timestamptz > now() - v_limit;
   INSERT INTO public.staff_ops_notifications(kind, recipient_user_id, title, body, ref_key, href)
   VALUES ('approval_waiting', u.user_id,
           CASE WHEN v_urgent THEN 'Urgent: ' ELSE 'Waiting: ' END || (it->>'title'),
           COALESCE(it->>'detail','') || ' · waiting since ' || to_char((it->>'waiting_since')::timestamptz AT TIME ZONE 'Africa/Harare','DD Mon HH24:MI'),
           (it->>'kind')||':'||(it->>'ref'), it->>'href')
   ON CONFLICT (recipient_user_id, ref_key) WHERE ref_key IS NOT NULL DO NOTHING;
   IF FOUND THEN
    v_n := v_n + 1;
    IF v_urgent AND u.wants_text THEN
     PERFORM private.queue_staff_message(u.user_id, 'approval_urgent', 'approval:'||(it->>'kind')||':'||(it->>'ref')||':'||u.user_id,
       format('GTR Auto URGENT: %s. %s Waiting since %s. Open Staff > Approvals.', it->>'title', COALESCE(it->>'detail',''),
              to_char((it->>'waiting_since')::timestamptz AT TIME ZONE 'Africa/Harare','HH24:MI')),
       jsonb_build_object('kind', it->>'kind', 'ref', it->>'ref'));
    END IF;
   END IF;
  END LOOP;
 END LOOP;
 PERFORM set_config('app.staff_ops_notify','',true);
 RETURN v_n;
END $$;


--
-- Name: sweep_customer_suspensions(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sweep_customer_suspensions() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_id uuid; n integer := 0; c uuid;
BEGIN
 FOR c IN
  SELECT DISTINCT customer_id FROM public.sales_invoices
   WHERE customer_id IS NOT NULL AND status='posted' AND total-amount_paid > 0.01 AND COALESCE(posted_at,created_at) < now()-interval '7 days'
  UNION
  SELECT DISTINCT si.customer_id FROM public.delivery_jobs j JOIN public.delivery_notes dn ON dn.id=j.delivery_note_id
   JOIN public.sales_invoices si ON si.id=dn.sales_invoice_id
   WHERE si.customer_id IS NOT NULL AND j.status='failed' AND j.failed_at > now()-interval '90 days'
 LOOP
  IF NOT EXISTS(SELECT 1 FROM public.customer_suspensions WHERE customer_id=c AND status='active') THEN
   v_id := private.suspend_customer_if_due(c);
   IF v_id IS NOT NULL THEN n := n+1; END IF;
  END IF;
 END LOOP;
 RETURN n;
END $$;


--
-- Name: sync_delivery_reservations(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sync_delivery_reservations() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_order_id UUID; r RECORD; v_remaining NUMERIC; BEGIN
 SELECT co.id INTO v_order_id FROM public.commerce_orders co WHERE co.sales_invoice_id=NEW.sales_invoice_id; IF v_order_id IS NULL THEN RETURN NEW; END IF;
 IF OLD.status='draft' AND NEW.status='submitted' THEN
  FOR r IN SELECT stock_item_id,SUM(qty_base)::numeric qty FROM public.delivery_note_lines WHERE delivery_note_id=NEW.id GROUP BY stock_item_id LOOP
   UPDATE public.inventory_reservations ir SET consumed_qty=LEAST(ir.reserved_qty,ir.consumed_qty+r.qty),consumed_at=CASE WHEN ir.consumed_qty+r.qty>=ir.reserved_qty THEN now() ELSE ir.consumed_at END,
    state=CASE WHEN ir.consumed_qty+r.qty>=ir.reserved_qty THEN 'consumed'::public.inventory_reservation_state ELSE 'allocated'::public.inventory_reservation_state END
    WHERE ir.commerce_order_id=v_order_id AND ir.stock_item_id=r.stock_item_id AND ir.warehouse_id=NEW.warehouse_id;
  END LOOP;
  SELECT COALESCE(SUM(GREATEST(reserved_qty-consumed_qty,0)),0) INTO v_remaining FROM public.inventory_reservations WHERE commerce_order_id=v_order_id;
  UPDATE public.commerce_orders SET state=CASE WHEN v_remaining>0 THEN 'partially_fulfilled'::public.commerce_order_state ELSE 'dispatch_ready'::public.commerce_order_state END,updated_at=now() WHERE id=v_order_id;
 ELSIF OLD.status='submitted' AND NEW.status='cancelled' THEN
  FOR r IN SELECT stock_item_id,SUM(qty_base)::numeric qty FROM public.delivery_note_lines WHERE delivery_note_id=NEW.id GROUP BY stock_item_id LOOP
   UPDATE public.inventory_reservations ir SET consumed_qty=GREATEST(ir.consumed_qty-r.qty,0),consumed_at=NULL,state='allocated'
    WHERE ir.commerce_order_id=v_order_id AND ir.stock_item_id=r.stock_item_id AND ir.warehouse_id=NEW.warehouse_id;
  END LOOP;
  UPDATE public.commerce_orders SET state='allocation_pending',updated_at=now() WHERE id=v_order_id;
 END IF; RETURN NEW; END; $$;


--
-- Name: sync_pos_fulfillment_invoice(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sync_pos_fulfillment_invoice() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
 IF NEW.status='posted' AND NEW.cart_id IS NOT NULL THEN
  UPDATE public.inventory_reservations SET state='released',released_at=now()
   WHERE pos_fulfillment_request_id IN(SELECT id FROM public.pos_fulfillment_requests WHERE cart_id=NEW.cart_id AND status='reserved') AND state='active';
  UPDATE public.pos_fulfillment_requests SET invoice_id=NEW.id,status='ready',ready_at=now(),expires_at=NULL,updated_at=now()
   WHERE cart_id=NEW.cart_id AND status='reserved' AND kind IN('alternate_pickup','customer_collection');
  -- A back-order sold on this sale: link the invoice only when the back-ordered part is on it.
  UPDATE public.pos_fulfillment_requests r
   SET invoice_id=NEW.id, status='ready', ready_at=COALESCE(r.ready_at,now()), updated_at=now()
   WHERE r.cart_id=NEW.cart_id AND r.invoice_id IS NULL
     AND ((r.kind='backorder' AND r.status IN('requested','ready')) OR (r.kind='branch_transfer' AND r.status='ready'))
     AND EXISTS(SELECT 1 FROM public.sales_invoice_lines l WHERE l.invoice_id=NEW.id AND l.stock_item_id=r.stock_item_id);
  UPDATE public.inventory_reservations SET state='released',released_at=now()
   WHERE state='active' AND pos_fulfillment_request_id IN(
     SELECT id FROM public.pos_fulfillment_requests WHERE cart_id=NEW.cart_id AND invoice_id=NEW.id AND kind IN('backorder','branch_transfer'));
 END IF; RETURN NEW;
END $$;


--
-- Name: sync_pos_fulfillment_transfer(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sync_pos_fulfillment_transfer() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
 IF NEW.entry_type='transfer' AND OLD.status IS DISTINCT FROM NEW.status THEN
  IF NEW.status='posted' THEN
   UPDATE public.inventory_reservations SET state='released',released_at=now()
    WHERE pos_fulfillment_request_id IN(SELECT id FROM public.pos_fulfillment_requests WHERE stock_entry_id=NEW.id) AND state IN('active','allocated');
   UPDATE public.pos_fulfillment_requests SET status='ready',ready_at=now(),expires_at=NULL,updated_at=now()
    WHERE stock_entry_id=NEW.id AND status='awaiting_transfer_approval';
   -- Moved for a customer: hold it at the receiving branch until they buy it.
   PERFORM private.hold_pos_fulfillment_stock(r.id)
    FROM public.pos_fulfillment_requests r WHERE r.stock_entry_id=NEW.id AND r.status='ready' AND r.customer_id IS NOT NULL;
  ELSIF NEW.status='rejected' THEN
   UPDATE public.inventory_reservations SET state='released',released_at=now()
    WHERE pos_fulfillment_request_id IN(SELECT id FROM public.pos_fulfillment_requests WHERE stock_entry_id=NEW.id) AND state IN('active','allocated');
   UPDATE public.pos_fulfillment_requests SET status='rejected',updated_at=now() WHERE stock_entry_id=NEW.id;
  END IF;
 END IF; RETURN NEW;
END $$;


--
-- Name: sync_pos_split_card_attempt_status(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sync_pos_split_card_attempt_status() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE l public.pos_split_payment_legs%ROWTYPE;
BEGIN
 IF NEW.split_leg_id IS NULL THEN RETURN NEW; END IF;
 SELECT * INTO l FROM public.pos_split_payment_legs WHERE id=NEW.split_leg_id FOR UPDATE; IF NOT FOUND THEN RETURN NEW; END IF;
 IF NEW.status='unknown' THEN UPDATE public.pos_split_payment_legs SET status='unknown',status_detail=COALESCE(NEW.response_message,'Swipe-machine outcome unknown'),updated_at=now() WHERE id=l.id AND status IN('pending','planned');
 ELSIF NEW.status IN('declined','cancelled','failed','reversed') THEN UPDATE public.pos_split_payment_legs SET status='failed',status_detail=COALESCE(NEW.response_message,NEW.status::text),failed_at=now(),updated_at=now() WHERE id=l.id AND status IN('pending','planned','unknown');
 END IF;
 PERFORM private.refresh_pos_split_payment_session(l.session_id); RETURN NEW;
END $$;


--
-- Name: sync_pos_split_provider_intent_status(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sync_pos_split_provider_intent_status() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_provider TEXT; v_status TEXT; l public.pos_split_payment_legs%ROWTYPE;
BEGIN
 v_provider:=CASE TG_TABLE_NAME WHEN 'ecocash_payment_intents' THEN 'ecocash' WHEN 'paynow_payment_intents' THEN 'paynow' WHEN 'contipay_payment_intents' THEN 'contipay' ELSE NULL END;
 IF v_provider IS NULL THEN RETURN NEW; END IF;
 SELECT * INTO l FROM public.pos_split_payment_legs WHERE provider_intent_id=NEW.id AND tender::text=v_provider FOR UPDATE;
 IF NOT FOUND THEN RETURN NEW; END IF;
 v_status:=NEW.status::text;
 IF v_status IN('failed','cancelled') THEN
  PERFORM private.fail_pos_split_provider_leg(NEW.id,v_provider,COALESCE(NEW.failure_reason,v_status));
 ELSIF v_status IN('pending','authorized') AND l.status='planned' THEN
  UPDATE public.pos_split_payment_legs SET status='pending',updated_at=now() WHERE id=l.id;
  PERFORM private.refresh_pos_split_payment_session(l.session_id);
 END IF;
 RETURN NEW;
END $$;


