--
-- Name: validate_pos_till_variance_reason(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.validate_pos_till_variance_reason() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
 IF NEW.variance IS NOT NULL AND abs(NEW.variance)>0.009
    AND NEW.status IN('variance_pending','closed') THEN
  PERFORM private.assert_pos_reason('till_variance',NEW.variance_reason_code,NEW.close_notes);
 END IF;
 RETURN NEW;
END $$;


--
-- Name: _adjust_consignment_level(public.consignment_kind, uuid, uuid, uuid, uuid, numeric, numeric, public.currency_code); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._adjust_consignment_level(p_kind public.consignment_kind, p_supplier_id uuid, p_customer_id uuid, p_item uuid, p_warehouse uuid, p_delta numeric, p_unit_cost numeric, p_currency public.currency_code) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id UUID;
  v_qty NUMERIC;
BEGIN
  IF p_kind = 'supplier_owned' THEN
    SELECT id, quantity INTO v_id, v_qty
    FROM public.consignment_stock_levels
    WHERE kind = 'supplier_owned'
      AND supplier_id = p_supplier_id
      AND stock_item_id = p_item
      AND warehouse_id = p_warehouse
    FOR UPDATE;

    IF v_id IS NULL THEN
      IF p_delta < 0 THEN
        RAISE EXCEPTION 'insufficient consignment qty for item %', p_item;
      END IF;
      INSERT INTO public.consignment_stock_levels (
        kind, supplier_id, stock_item_id, warehouse_id, quantity, unit_cost, currency
      ) VALUES (
        'supplier_owned', p_supplier_id, p_item, p_warehouse,
        p_delta, COALESCE(p_unit_cost, 0), p_currency
      );
    ELSE
      IF v_qty + p_delta < 0 THEN
        RAISE EXCEPTION 'insufficient consignment qty for item %', p_item;
      END IF;
      UPDATE public.consignment_stock_levels
      SET
        quantity = quantity + p_delta,
        unit_cost = CASE
          WHEN p_delta > 0 THEN COALESCE(p_unit_cost, unit_cost)
          ELSE unit_cost
        END,
        updated_at = now()
      WHERE id = v_id;
    END IF;
  ELSE
    SELECT id, quantity INTO v_id, v_qty
    FROM public.consignment_stock_levels
    WHERE kind = 'customer_held'
      AND customer_id = p_customer_id
      AND stock_item_id = p_item
      AND warehouse_id = p_warehouse
    FOR UPDATE;

    IF v_id IS NULL THEN
      IF p_delta < 0 THEN
        RAISE EXCEPTION 'insufficient consignment qty for item %', p_item;
      END IF;
      INSERT INTO public.consignment_stock_levels (
        kind, customer_id, stock_item_id, warehouse_id, quantity, unit_cost, currency
      ) VALUES (
        'customer_held', p_customer_id, p_item, p_warehouse,
        p_delta, COALESCE(p_unit_cost, 0), p_currency
      );
    ELSE
      IF v_qty + p_delta < 0 THEN
        RAISE EXCEPTION 'insufficient consignment qty for item %', p_item;
      END IF;
      UPDATE public.consignment_stock_levels
      SET
        quantity = quantity + p_delta,
        unit_cost = CASE
          WHEN p_delta > 0 THEN COALESCE(p_unit_cost, unit_cost)
          ELSE unit_cost
        END,
        updated_at = now()
      WHERE id = v_id;
    END IF;
  END IF;
END;
$$;


--
-- Name: _adjust_stock_level(uuid, uuid, numeric, public.valuation_method, numeric, public.currency_code); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._adjust_stock_level(p_item uuid, p_warehouse uuid, p_delta numeric, p_valuation public.valuation_method, p_unit_cost numeric, p_currency public.currency_code) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_qty NUMERIC; v_before NUMERIC; v_after NUMERIC; v_reserved NUMERIC:=0; v_exempt_order UUID; BEGIN
 SELECT COALESCE(SUM(quantity),0) INTO v_before FROM public.stock_levels WHERE stock_item_id=p_item;
 BEGIN v_exempt_order:=NULLIF(current_setting('app.commerce_fulfill_order_id',true),'')::uuid; EXCEPTION WHEN invalid_text_representation THEN v_exempt_order:=NULL; END;
 INSERT INTO public.stock_levels(stock_item_id,warehouse_id,quantity,valuation_method,unit_cost,currency) VALUES(p_item,p_warehouse,GREATEST(p_delta,0),p_valuation,p_unit_cost,p_currency)
 ON CONFLICT(stock_item_id,warehouse_id) DO UPDATE SET quantity=public.stock_levels.quantity+p_delta,updated_at=now(),unit_cost=CASE
  WHEN p_delta>0 AND public.stock_levels.valuation_method='AVG' THEN CASE WHEN public.stock_levels.quantity+p_delta=0 THEN p_unit_cost ELSE round((COALESCE(public.stock_levels.unit_cost,0)*public.stock_levels.quantity+COALESCE(p_unit_cost,0)*p_delta)/(public.stock_levels.quantity+p_delta),4) END
  WHEN p_delta>0 THEN COALESCE(p_unit_cost,public.stock_levels.unit_cost) ELSE public.stock_levels.unit_cost END RETURNING quantity INTO v_qty;
 IF v_qty<0 THEN RAISE EXCEPTION 'insufficient stock for item % in warehouse %',p_item,p_warehouse; END IF;
 IF p_delta<0 THEN
  SELECT COALESCE(SUM(GREATEST(r.reserved_qty-r.consumed_qty,0)),0) INTO v_reserved FROM public.inventory_reservations r
   WHERE r.stock_item_id=p_item AND r.warehouse_id=p_warehouse AND r.state IN ('active','allocated') AND (r.state='allocated' OR r.expires_at>now()) AND (v_exempt_order IS NULL OR r.commerce_order_id<>v_exempt_order);
  IF v_qty+0.0001<v_reserved THEN RAISE EXCEPTION 'insufficient unreserved stock for item % in warehouse %: resulting %, protected %',p_item,p_warehouse,v_qty,v_reserved; END IF;
 END IF;
 IF p_delta>0 THEN SELECT COALESCE(SUM(quantity),0) INTO v_after FROM public.stock_levels WHERE stock_item_id=p_item; IF v_before<=0 AND v_after>0 THEN PERFORM public._notify_wishlist_back_in_stock(p_item); END IF; END IF; END; $$;


--
-- Name: _append_loyalty(uuid, public.loyalty_movement, numeric, public.currency_code, numeric, numeric, uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._append_loyalty(p_customer_id uuid, p_movement public.loyalty_movement, p_points numeric, p_currency public.currency_code, p_exchange_rate numeric, p_money_value numeric, p_sales_invoice_id uuid, p_journal_entry_id uuid, p_reason text, p_reverses_ledger_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_acct UUID;
  v_bal NUMERIC;
  v_new NUMERIC;
  v_id UUID;
  v_prior public.loyalty_movement;
BEGIN
  IF p_points IS NULL OR p_points <= 0 THEN
    RAISE EXCEPTION 'loyalty points must be > 0';
  END IF;
  IF p_money_value IS NULL OR p_money_value < 0 THEN
    RAISE EXCEPTION 'loyalty money_value must be >= 0';
  END IF;

  v_acct := public._ensure_loyalty_account(p_customer_id, p_currency);

  SELECT points_balance INTO v_bal
  FROM public.loyalty_accounts
  WHERE id = v_acct
  FOR UPDATE;

  IF p_movement = 'earn' THEN
    v_new := v_bal + p_points;
  ELSIF p_movement IN ('redeem', 'expire') THEN
    IF v_bal < p_points THEN
      RAISE EXCEPTION 'loyalty overdraw: balance % points %', v_bal, p_points;
    END IF;
    v_new := v_bal - p_points;
  ELSIF p_movement = 'reverse' THEN
    IF p_reverses_ledger_id IS NULL THEN
      RAISE EXCEPTION 'reverse requires reverses_ledger_id';
    END IF;
    SELECT movement INTO v_prior
    FROM public.loyalty_ledger WHERE id = p_reverses_ledger_id;
    IF v_prior = 'earn' THEN
      IF v_bal < p_points THEN
        RAISE EXCEPTION 'cannot reverse loyalty earn: insufficient balance';
      END IF;
      v_new := v_bal - p_points;
    ELSIF v_prior IN ('redeem', 'expire') THEN
      v_new := v_bal + p_points;
    ELSE
      RAISE EXCEPTION 'cannot reverse a reverse ledger row';
    END IF;
  ELSE
    RAISE EXCEPTION 'unknown loyalty movement %', p_movement;
  END IF;

  UPDATE public.loyalty_accounts
  SET points_balance = v_new, updated_at = now()
  WHERE id = v_acct;

  INSERT INTO public.loyalty_ledger (
    document_number, account_id, customer_id, movement, points, money_value,
    currency, exchange_rate_applied, points_balance_after, sales_invoice_id,
    journal_entry_id, reason, reverses_ledger_id, created_by
  )
  VALUES (
    public.next_series_value('LP-'),
    v_acct, p_customer_id, p_movement, p_points, p_money_value,
    p_currency, COALESCE(p_exchange_rate, 1), v_new, p_sales_invoice_id,
    p_journal_entry_id, p_reason, p_reverses_ledger_id, auth.uid()
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


--
-- Name: _append_store_credit(uuid, public.store_credit_movement, numeric, public.currency_code, numeric, uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._append_store_credit(p_customer_id uuid, p_movement public.store_credit_movement, p_amount numeric, p_currency public.currency_code, p_exchange_rate numeric, p_payment_entry_id uuid, p_journal_entry_id uuid, p_reason text, p_reverses_ledger_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_acct UUID;
  v_bal NUMERIC;
  v_new NUMERIC;
  v_id UUID;
  v_prior public.store_credit_movement;
BEGIN
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION 'store credit amount must be > 0';
  END IF;

  v_acct := public._ensure_store_credit_account(p_customer_id, p_currency);

  SELECT balance INTO v_bal
  FROM public.store_credit_accounts
  WHERE id = v_acct
  FOR UPDATE;

  IF p_movement = 'issue' THEN
    v_new := v_bal + p_amount;
  ELSIF p_movement = 'redeem' THEN
    IF v_bal < p_amount THEN
      RAISE EXCEPTION 'store credit overdraw: balance % amount %', v_bal, p_amount;
    END IF;
    v_new := v_bal - p_amount;
  ELSIF p_movement = 'reverse' THEN
    IF p_reverses_ledger_id IS NULL THEN
      RAISE EXCEPTION 'reverse requires reverses_ledger_id';
    END IF;
    SELECT movement INTO v_prior
    FROM public.store_credit_ledger WHERE id = p_reverses_ledger_id;
    IF v_prior = 'issue' THEN
      IF v_bal < p_amount THEN
        RAISE EXCEPTION 'cannot reverse store credit issue: insufficient balance';
      END IF;
      v_new := v_bal - p_amount;
    ELSIF v_prior = 'redeem' THEN
      v_new := v_bal + p_amount;
    ELSE
      RAISE EXCEPTION 'cannot reverse a reverse ledger row';
    END IF;
  ELSE
    RAISE EXCEPTION 'unknown store credit movement %', p_movement;
  END IF;

  UPDATE public.store_credit_accounts
  SET balance = v_new, updated_at = now()
  WHERE id = v_acct;

  INSERT INTO public.store_credit_ledger (
    document_number, account_id, customer_id, movement, amount, currency,
    exchange_rate_applied, balance_after, payment_entry_id, journal_entry_id,
    reason, reverses_ledger_id, created_by
  )
  VALUES (
    public.next_series_value('SC-'),
    v_acct, p_customer_id, p_movement, p_amount, p_currency,
    COALESCE(p_exchange_rate, 1), v_new, p_payment_entry_id, p_journal_entry_id,
    p_reason, p_reverses_ledger_id, auth.uid()
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


