--
-- Name: _assert_customer_owns_invoice(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._assert_customer_owns_invoice(p_invoice_id uuid) RETURNS public.sales_invoices
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cust UUID := public._current_customer_id();
  v_inv public.sales_invoices%ROWTYPE;
BEGIN
  IF v_cust IS NULL THEN
    RAISE EXCEPTION 'customer profile required';
  END IF;
  SELECT * INTO v_inv
  FROM public.sales_invoices
  WHERE id = p_invoice_id;
  IF NOT FOUND OR v_inv.customer_id IS DISTINCT FROM v_cust THEN
    RAISE EXCEPTION 'not authorized for this invoice';
  END IF;
  RETURN v_inv;
END;
$$;


