-- Name: _assert_customer_owns_open_cart(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._assert_customer_owns_open_cart(p_cart_id uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_cust UUID:=public._current_customer_id(); BEGIN
 IF v_cust IS NULL THEN RAISE EXCEPTION 'customer profile required'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.pos_carts c WHERE c.id=p_cart_id AND c.customer_id=v_cust AND c.channel='storefront' AND c.status='open' AND c.checkout_locked_at IS NULL)
 THEN RAISE EXCEPTION 'not authorized for this open storefront cart'; END IF; END; $$;


--
-- Name: _assert_delivery_pod_object_for_job(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._assert_delivery_pod_object_for_job(p_delivery_job_id uuid, p_path text, p_kind text) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_path TEXT;
  v_prefix TEXT;
  v_fname TEXT;
BEGIN
  v_path := public._normalize_delivery_pod_object_path(p_path);
  v_prefix := p_delivery_job_id::text || '/';

  IF v_path IS NULL OR left(v_path, length(v_prefix)) IS DISTINCT FROM v_prefix THEN
    RAISE EXCEPTION
      'POD % path must start with % (got %)',
      p_kind, v_prefix, COALESCE(p_path, '<null>');
  END IF;

  v_fname := substr(v_path, length(v_prefix) + 1);
  IF v_fname IS NULL OR length(v_fname) = 0 OR position('/' IN v_fname) > 0 THEN
    RAISE EXCEPTION 'POD % path must be a single file under job folder', p_kind;
  END IF;

  IF p_kind = 'photo' THEN
    IF v_fname !~* '^photo\.(jpe?g|png|webp)$' THEN
      RAISE EXCEPTION
        'POD photo filename must be photo.jpg|jpeg|png|webp (got %)', v_fname;
    END IF;
  ELSIF p_kind = 'signature' THEN
    IF v_fname !~* '^signature\.(jpe?g|png|webp)$' THEN
      RAISE EXCEPTION
        'POD signature filename must be signature.jpg|jpeg|png|webp (got %)',
        v_fname;
    END IF;
  ELSE
    RAISE EXCEPTION 'unknown POD kind %', p_kind;
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM storage.objects o
    WHERE o.bucket_id = 'delivery-pods'
      AND o.name = v_path
  ) THEN
    RAISE EXCEPTION
      'POD % object missing in delivery-pods bucket at %', p_kind, v_path;
  END IF;

  RETURN v_path;
END;
$_$;


--
-- Name: FUNCTION _assert_delivery_pod_object_for_job(p_delivery_job_id uuid, p_path text, p_kind text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public._assert_delivery_pod_object_for_job(p_delivery_job_id uuid, p_path text, p_kind text) IS 'Binds POD path to {job_id}/photo|signature.* and requires storage.objects row in private delivery-pods bucket.';


