--
-- Name: _assert_journal_balanced(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._assert_journal_balanced(p_entry_id uuid) RETURNS void
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_debit NUMERIC(18, 2);
  v_credit NUMERIC(18, 2);
BEGIN
  SELECT COALESCE(SUM(debit), 0), COALESCE(SUM(credit), 0)
  INTO v_debit, v_credit
  FROM public.journal_entry_lines
  WHERE journal_entry_id = p_entry_id;

  IF abs(v_debit - v_credit) > 0.009 THEN
    RAISE EXCEPTION 'Unbalanced journal entry: debit=% credit=%', v_debit, v_credit;
  END IF;
  IF v_debit = 0 AND v_credit = 0 THEN
    RAISE EXCEPTION 'Journal entry has no lines';
  END IF;
END;
$$;


