--
-- Name: chat_threads; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.chat_threads (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    customer_user_id uuid NOT NULL,
    customer_id uuid,
    kind public.chat_thread_kind DEFAULT 'support'::public.chat_thread_kind NOT NULL,
    status public.chat_thread_status DEFAULT 'open'::public.chat_thread_status NOT NULL,
    subject text,
    assigned_to uuid,
    assigned_at timestamp with time zone,
    closed_at timestamp with time zone,
    closed_by uuid,
    last_message_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT chat_threads_assigned_requires_assignee CHECK ((((status = 'assigned'::public.chat_thread_status) AND (assigned_to IS NOT NULL)) OR (status <> 'assigned'::public.chat_thread_status))),
    CONSTRAINT chat_threads_closed_has_closed_at CHECK ((((status = 'closed'::public.chat_thread_status) AND (closed_at IS NOT NULL)) OR (status <> 'closed'::public.chat_thread_status)))
);


--
-- Name: TABLE chat_threads; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.chat_threads IS 'Customer support/parts chat threads. Auth customers only; staff claim via assigned_to.';


--
-- Name: _can_select_chat_thread(public.chat_threads); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._can_select_chat_thread(p_thread public.chat_threads) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    auth.role() = 'service_role'
    OR p_thread.customer_user_id = auth.uid()
    OR (
      public.has_staff_role(public._chat_staff_roles())
      AND (
        p_thread.status IN ('open', 'assigned')
        OR p_thread.assigned_to = auth.uid()
        OR public.has_staff_role(ARRAY['admin']::public.staff_role[])
      )
    );
$$;


--
-- Name: _can_select_delivery_pod_object(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._can_select_delivery_pod_object(p_name text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    auth.role() = 'service_role'
    OR (
      public.has_staff_role(
        ARRAY['admin', 'warehouse', 'dispatcher']::public.staff_role[]
      )
      AND public._delivery_pod_job_id_from_path(p_name) IS NOT NULL
    )
    -- Assigned driver may read own job objects (upload RETURNING / retries).
    OR EXISTS (
      SELECT 1
      FROM public.delivery_jobs dj
      WHERE dj.id = public._delivery_pod_job_id_from_path(p_name)
        AND dj.assignee_user_id = auth.uid()
        AND public.has_staff_role(ARRAY['driver']::public.staff_role[])
    );
$$;


--
-- Name: FUNCTION _can_select_delivery_pod_object(p_name text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public._can_select_delivery_pod_object(p_name text) IS 'dispatcher/admin/warehouse or assigned driver may SELECT; customers denied.';


--
-- Name: _can_select_review_photo_object(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._can_select_review_photo_object(p_name text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    auth.role() = 'service_role'
    OR public.has_staff_role(ARRAY['admin', 'sales']::public.staff_role[])
    OR EXISTS (
      SELECT 1
      FROM public.customer_product_reviews r
      WHERE r.id = public._review_photo_review_id_from_path(p_name)
        AND (
          r.status = 'approved'
          OR r.customer_id = public._current_customer_id()
        )
    );
$$;


