 SELECT auth.role()='service_role' OR (public.has_staff_role(ARRAY['admin','sales','warehouse']::public.staff_role[]) AND public._stock_item_id_from_product_image_path(p_name) IS NOT NULL AND EXISTS(SELECT 1 FROM public.stock_items si WHERE si.id=public._stock_item_id_from_product_image_path(p_name))); $$;


