--
-- Name: _checkout_pos_cart_core(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._checkout_pos_cart_core(p_cart_id uuid, p_receipt_email text DEFAULT NULL::text, p_receipt_whatsapp_e164 text DEFAULT NULL::text, p_receipt_phone_e164 text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cart public.pos_carts%ROWTYPE;
  v_cust public.customers%ROWTYPE;
  v_inv UUID;
  v_line RECORD;
  v_subtotal NUMERIC := 0;
  v_total NUMERIC := 0;
  v_journal UUID;
  v_lines JSONB := '[]'::jsonb;
  v_rev NUMERIC := 0;
  v_core NUMERIC := 0;
  v_cogs NUMERIC := 0;
  v_unit_cost NUMERIC;
  v_large NUMERIC := 1000;
  v_fulfill public.fulfillment_mode;
  v_qty_fulfilled NUMERIC;
  v_inv_line_id UUID;
  v_parent_inv UUID;
  v_cart_to_inv JSONB := '{}'::jsonb;
  v_issues BOOLEAN;
  v_email TEXT;
  v_wa TEXT;
  v_phone TEXT;
  v_bound UUID;
BEGIN
  PERFORM public._require_cart_mutate(p_cart_id);
  SELECT * INTO v_cart FROM public.pos_carts WHERE id = p_cart_id FOR UPDATE;
  IF NOT FOUND OR v_cart.status <> 'open' THEN
    RAISE EXCEPTION 'open cart not found';
  END IF;

  v_fulfill := COALESCE(v_cart.fulfillment_mode, 'immediate');

  v_email := public._normalize_receipt_email(p_receipt_email);
  v_wa := public._normalize_e164(p_receipt_whatsapp_e164);
  v_phone := public._normalize_e164(p_receipt_phone_e164);

  -- Best-effort bind when cart has no customer yet (walk-in → registered/trade).
  IF v_cart.customer_id IS NULL THEN
    v_bound := public.resolve_customer_for_receipt_contacts(v_email, v_wa, v_phone);
    IF v_bound IS NOT NULL THEN
      UPDATE public.pos_carts
      SET customer_id = v_bound, updated_at = now()
      WHERE id = p_cart_id;
      v_cart.customer_id := v_bound;
    END IF;
  END IF;

  IF v_cart.customer_id IS NOT NULL THEN
    SELECT * INTO v_cust FROM public.customers WHERE id = v_cart.customer_id;
  END IF;

  -- Invoice contacts: till capture overrides, else customer profile.
  v_email := COALESCE(v_email, public._normalize_receipt_email(v_cust.email));
  v_wa := COALESCE(v_wa, public._normalize_e164(v_cust.whatsapp_e164));
  v_phone := COALESCE(
    v_phone,
    public._normalize_e164(v_cust.phone_e164),
    v_wa
  );
  v_wa := COALESCE(v_wa, v_phone);

  IF v_cart.customer_id IS NOT NULL THEN
    IF v_cust.credit_hold THEN
      INSERT INTO public.sales_invoices (
        doc_type, status, customer_id, warehouse_id, currency,
        exchange_rate_applied, cart_id, fulfillment_mode,
        customer_phone_e164, customer_email, customer_whatsapp_e164
      )
      VALUES (
        'invoice', 'on_hold', v_cart.customer_id, v_cart.warehouse_id, v_cart.currency,
        v_cart.exchange_rate_applied, p_cart_id, v_fulfill,
        v_phone, v_email, v_wa
      )
      RETURNING id INTO v_inv;

      PERFORM public.emit_domain_event(
        'order_on_hold',
        'invoice:hold:' || v_inv::text,
        jsonb_build_object('invoice_id', v_inv, 'reason', 'credit_hold')
      );
      RETURN v_inv;
    END IF;
  END IF;

  SELECT COALESCE(SUM(line_total), 0) INTO v_subtotal
  FROM public.pos_cart_lines WHERE cart_id = p_cart_id;
  v_total := v_subtotal;

  IF v_cart.customer_id IS NOT NULL
     AND v_cust.credit_limit > 0
     AND (v_cust.open_balance + v_total) > v_cust.credit_limit THEN
    INSERT INTO public.sales_invoices (
      doc_type, status, customer_id, warehouse_id, currency,
      exchange_rate_applied, cart_id, subtotal, total, fulfillment_mode,
      customer_phone_e164, customer_email, customer_whatsapp_e164
    )
    VALUES (
      'invoice', 'on_hold', v_cart.customer_id, v_cart.warehouse_id, v_cart.currency,
      v_cart.exchange_rate_applied, p_cart_id, v_subtotal, v_total, v_fulfill,
      v_phone, v_email, v_wa
    )
    RETURNING id INTO v_inv;

    PERFORM public.emit_domain_event(
      'order_on_hold',
      'invoice:limit:' || v_inv::text,
      jsonb_build_object('invoice_id', v_inv, 'reason', 'credit_limit')
    );
    RETURN v_inv;
  END IF;

  INSERT INTO public.sales_invoices (
    doc_type, status, document_number, customer_id, warehouse_id, currency,
    exchange_rate_applied, subtotal, total, cart_id, fulfillment_mode,
    customer_phone_e164, customer_email, customer_whatsapp_e164,
    posted_by, posted_at
  )
  VALUES (
    'invoice', 'draft', public.next_series_value('SINV-'),
    v_cart.customer_id, v_cart.warehouse_id, v_cart.currency,
    v_cart.exchange_rate_applied, v_subtotal, v_total, p_cart_id, v_fulfill,
    v_phone, v_email, v_wa,
    auth.uid(), now()
  )
  RETURNING id INTO v_inv;

  PERFORM public.emit_domain_event(
    'order_received',
    'invoice:received:' || v_inv::text,
    jsonb_build_object(
      'invoice_id', v_inv,
      'fulfillment_mode', v_fulfill::text
    )
  );

  FOR v_line IN
    SELECT * FROM public.pos_cart_lines
    WHERE cart_id = p_cart_id
    ORDER BY created_at
  LOOP
    v_issues := COALESCE(v_line.issues_stock, true);

    IF v_line.is_core_charge THEN
      v_qty_fulfilled := 0;
    ELSIF NOT v_issues THEN
      v_qty_fulfilled := v_line.qty_base;
    ELSIF v_fulfill = 'immediate' THEN
      v_qty_fulfilled := v_line.qty_base;
    ELSE
      v_qty_fulfilled := 0;
    END IF;

    v_parent_inv := NULL;
    IF v_line.parent_line_id IS NOT NULL THEN
      v_parent_inv := (v_cart_to_inv ->> v_line.parent_line_id::text)::uuid;
    END IF;

    INSERT INTO public.sales_invoice_lines (
      invoice_id, stock_item_id, parent_line_id, is_core_charge, uom_id,
      qty, qty_base, unit_price, line_total, qty_fulfilled,
      issues_stock, kit_id, kit_line_kind
    )
    VALUES (
      v_inv, v_line.stock_item_id, v_parent_inv, v_line.is_core_charge, v_line.uom_id,
      v_line.qty, v_line.qty_base, v_line.unit_price, v_line.line_total, v_qty_fulfilled,
      v_issues, v_line.kit_id, v_line.kit_line_kind
    )
    RETURNING id INTO v_inv_line_id;

    v_cart_to_inv := v_cart_to_inv || jsonb_build_object(v_line.id::text, v_inv_line_id);

    IF v_line.is_core_charge THEN
      v_core := v_core + v_line.line_total;
    ELSE
      v_rev := v_rev + v_line.line_total;

      IF v_issues AND v_fulfill = 'immediate' THEN
        SELECT unit_cost INTO v_unit_cost
        FROM public.stock_levels
        WHERE stock_item_id = v_line.stock_item_id AND warehouse_id = v_cart.warehouse_id;

        PERFORM public._consume_fifo_batches(
          v_line.stock_item_id, v_cart.warehouse_id, v_line.qty_base
        );
        PERFORM public._adjust_stock_level(
          v_line.stock_item_id, v_cart.warehouse_id, -v_line.qty_base,
          'FIFO', COALESCE(v_unit_cost, 0), v_cart.currency
        );
        v_cogs := v_cogs + COALESCE(v_unit_cost, 0) * v_line.qty_base;
      END IF;
    END IF;
  END LOOP;

  v_lines := jsonb_build_array(
    jsonb_build_object(
      'account_code', CASE WHEN v_cart.customer_id IS NULL THEN '1100' ELSE '1200' END,
      'debit', v_total, 'credit', 0, 'currency', v_cart.currency
    ),
    jsonb_build_object(
      'account_code', '4100',
      'debit', 0, 'credit', v_rev, 'currency', v_cart.currency
    )
  );
  IF v_core > 0 THEN
    v_lines := v_lines || jsonb_build_array(
      jsonb_build_object(
        'account_code', '4200',
        'debit', 0, 'credit', v_core, 'currency', v_cart.currency
      )
    );
  END IF;
  IF v_cogs > 0 THEN
    v_lines := v_lines || jsonb_build_array(
      jsonb_build_object(
        'account_code', '5100',
        'debit', round(v_cogs, 2), 'credit', 0, 'currency', v_cart.currency
      ),
      jsonb_build_object(
        'account_code', '1300',
        'debit', 0, 'credit', round(v_cogs, 2), 'currency', v_cart.currency
      )
    );
  END IF;

  v_journal := public.post_journal_entry(
    CURRENT_DATE,
    format('Sale %s', (SELECT document_number FROM public.sales_invoices WHERE id = v_inv)),
    v_cart.currency,
    v_cart.exchange_rate_applied,
    v_lines
  );

  UPDATE public.sales_invoices
  SET status = 'posted', journal_entry_id = v_journal, posted_at = now()
  WHERE id = v_inv;

  UPDATE public.pos_carts SET status = 'checked_out', updated_at = now() WHERE id = p_cart_id;

  -- Close any companion sessions on checkout
  UPDATE public.pos_scan_sessions
  SET status = 'revoked', revoked_at = now(), updated_at = now()
  WHERE cart_id = p_cart_id AND status IN ('open', 'claimed');

  IF v_cart.customer_id IS NOT NULL THEN
    UPDATE public.customers
    SET open_balance = open_balance + v_total, updated_at = now()
    WHERE id = v_cart.customer_id;
  END IF;

  -- Enqueue only — sale never blocks on channel send (Phase 13 worker).
  PERFORM public.enqueue_customer_receipts(v_inv);

  IF v_total >= v_large THEN
    PERFORM public.emit_domain_event(
      'large_order',
      'invoice:large:' || v_inv::text,
      jsonb_build_object('invoice_id', v_inv, 'total', v_total)
    );
  END IF;

  RETURN v_inv;
END;
$$;


--
-- Name: _consume_auth_rate_limit(text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._consume_auth_rate_limit(p_scope text, p_key_hash text, p_max_requests integer, p_window_seconds integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_scope text := lower(trim(coalesce(p_scope,'')));
  v_key text := trim(coalesce(p_key_hash,''));
  v_max integer := greatest(1, least(coalesce(p_max_requests,1),100000));
  v_window integer := greatest(1, least(coalesce(p_window_seconds,60),86400));
  v_now timestamptz := clock_timestamp();
  v_row public.auth_request_rate_limits%rowtype;
  v_retry integer := 0;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'service_role required';
  end if;
  if v_scope = '' or v_key = '' then
    raise exception 'rate-limit scope/key required';
  end if;

  insert into public.auth_request_rate_limits(scope,key_hash,window_started_at,request_count,updated_at)
  values(v_scope,v_key,v_now,0,v_now)
  on conflict(scope,key_hash) do nothing;

  select * into strict v_row
  from public.auth_request_rate_limits
  where scope=v_scope and key_hash=v_key
  for update;

  if v_row.window_started_at + make_interval(secs => v_window) <= v_now then
    update public.auth_request_rate_limits
    set window_started_at=v_now, request_count=1, updated_at=v_now
    where scope=v_scope and key_hash=v_key;
    return jsonb_build_object('allowed',true,'remaining',v_max-1,'retry_after_seconds',0);
  end if;

  if v_row.request_count >= v_max then
    v_retry := greatest(1,ceil(extract(epoch from (v_row.window_started_at + make_interval(secs => v_window) - v_now)))::integer);
    raise exception 'AUTH_RATE_LIMITED scope=% retry_after_seconds=%', v_scope, v_retry;
  end if;

  update public.auth_request_rate_limits
  set request_count=request_count+1, updated_at=v_now
  where scope=v_scope and key_hash=v_key;

  return jsonb_build_object('allowed',true,'remaining',v_max-(v_row.request_count+1),'retry_after_seconds',0);
end;
$$;


--
-- Name: _consume_fifo_batches(uuid, uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._consume_fifo_batches(p_item uuid, p_warehouse uuid, p_qty_base numeric) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_remaining NUMERIC := p_qty_base;
  v_batch RECORD;
  v_take NUMERIC;
BEGIN
  FOR v_batch IN
    SELECT id, qty_on_hand
    FROM public.stock_batches
    WHERE stock_item_id = p_item
      AND warehouse_id = p_warehouse
      AND qty_on_hand > 0
    ORDER BY received_at ASC, created_at ASC
    FOR UPDATE
  LOOP
    EXIT WHEN v_remaining <= 0;
    v_take := LEAST(v_batch.qty_on_hand, v_remaining);
    UPDATE public.stock_batches
    SET qty_on_hand = qty_on_hand - v_take
    WHERE id = v_batch.id;
    v_remaining := v_remaining - v_take;
  END LOOP;

  IF v_remaining > 0.0005 THEN
    RAISE EXCEPTION 'insufficient FIFO batch qty for item % (short %)', p_item, v_remaining;
  END IF;
END;
$$;


--
-- Name: _current_customer_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._current_customer_id() RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT c.id
  FROM public.customers c
  WHERE c.profile_id = auth.uid()
  ORDER BY c.created_at ASC
  LIMIT 1;
$$;


--
-- Name: _customer_compare_max_items(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._customer_compare_max_items() RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  SELECT 8;
$$;


--
-- Name: _customer_owns_delivery_job(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._customer_owns_delivery_job(p_job_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.delivery_jobs dj
    JOIN public.delivery_notes dn ON dn.id = dj.delivery_note_id
    JOIN public.sales_invoices si ON si.id = dn.sales_invoice_id
    JOIN public.customers c ON c.id = si.customer_id
    WHERE dj.id = p_job_id
      AND c.profile_id = auth.uid()
  );
$$;


--
-- Name: _customers_credit_dual_write_minor(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._customers_credit_dual_write_minor() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  IF NEW.credit_limit IS NOT NULL THEN
    NEW.credit_limit_minor := public._major_to_minor(NEW.credit_limit);
  END IF;
  IF NEW.open_balance IS NOT NULL THEN
    NEW.open_balance_minor := public._major_to_minor(NEW.open_balance);
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: _delivery_job_customer_contact(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._delivery_job_customer_contact(p_delivery_job_id uuid) RETURNS TABLE(profile_id uuid, phone_e164 text, whatsapp_e164 text, sales_invoice_id uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    c.profile_id,
    NULLIF(trim(COALESCE(si.customer_phone_e164, c.phone_e164)), ''),
    NULLIF(trim(COALESCE(si.customer_whatsapp_e164, c.whatsapp_e164, si.customer_phone_e164, c.phone_e164)), ''),
    si.id
  FROM public.delivery_jobs dj
  JOIN public.delivery_notes dn ON dn.id = dj.delivery_note_id
  JOIN public.sales_invoices si ON si.id = dn.sales_invoice_id
  LEFT JOIN public.customers c ON c.id = si.customer_id
  WHERE dj.id = p_delivery_job_id
  LIMIT 1;
$$;


--
-- Name: _delivery_pod_job_id_from_path(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._delivery_pod_job_id_from_path(p_name text) RETURNS uuid
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_seg TEXT;
  v_id UUID;
BEGIN
  IF p_name IS NULL OR length(trim(p_name)) = 0 THEN
    RETURN NULL;
  END IF;
  -- Strip accidental bucket prefix if a client passes "delivery-pods/..."
  v_seg := trim(both '/' FROM p_name);
  IF split_part(v_seg, '/', 1) = 'delivery-pods' THEN
    v_seg := substr(v_seg, length('delivery-pods/') + 1);
  END IF;
  v_seg := split_part(v_seg, '/', 1);
  BEGIN
    v_id := v_seg::uuid;
  EXCEPTION
    WHEN invalid_text_representation THEN
      RETURN NULL;
  END;
  RETURN v_id;
END;
$$;


--
