--
-- Name: _driver_eligible_for_assign(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._driver_eligible_for_assign(p_user_id uuid, p_at timestamp with time zone DEFAULT now()) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row public.driver_presence%ROWTYPE;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.staff_roles
    WHERE user_id = p_user_id AND role = 'driver'
  ) THEN
    RETURN false;
  END IF;

  SELECT * INTO v_row FROM public.driver_presence WHERE user_id = p_user_id;
  IF NOT FOUND THEN
    RETURN false;
  END IF;

  IF v_row.status NOT IN ('available', 'on_duty') THEN
    RETURN false;
  END IF;

  IF NOT public._driver_shift_active(v_row.shift_starts_at, v_row.shift_ends_at, p_at) THEN
    RETURN false;
  END IF;

  IF public._driver_open_job_count(p_user_id) >= v_row.capacity THEN
    RETURN false;
  END IF;

  RETURN true;
END;
$$;


--
-- Name: _driver_open_job_count(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._driver_open_job_count(p_user_id uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT count(*)::integer
  FROM public.delivery_jobs dj
  WHERE dj.assignee_user_id = p_user_id
    AND dj.status IN ('pending', 'dispatched');
$$;


--
-- Name: _driver_shift_active(timestamp with time zone, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._driver_shift_active(p_starts timestamp with time zone, p_ends timestamp with time zone, p_at timestamp with time zone DEFAULT now()) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  SELECT
    (p_starts IS NULL AND p_ends IS NULL)
    OR (
      (p_starts IS NULL OR p_at >= p_starts)
      AND (p_ends IS NULL OR p_at <= p_ends)
    );
$$;


--
-- Name: _enqueue_customer_sms(text, text, uuid, text, jsonb, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._enqueue_customer_sms(p_event_code text, p_dedupe_key text, p_profile_id uuid, p_phone_e164 text, p_payload jsonb DEFAULT '{}'::jsonb, p_message_body text DEFAULT NULL::text, p_actor_user_id uuid DEFAULT auth.uid()) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_event_id UUID;
  v_body TEXT;
  v_desc TEXT;
  v_phone TEXT := NULLIF(trim(COALESCE(p_phone_e164, '')), '');
BEGIN
  IF p_profile_id IS NULL THEN
    RETURN NULL;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.sms_event_catalog c
    WHERE c.code = p_event_code AND c.is_active
  ) THEN
    RAISE EXCEPTION 'Unknown or inactive event_code: %', p_event_code;
  END IF;

  INSERT INTO public.domain_events (event_code, dedupe_key, payload, actor_user_id)
  VALUES (
    p_event_code,
    p_dedupe_key,
    COALESCE(p_payload, '{}'::jsonb),
    p_actor_user_id
  )
  ON CONFLICT (event_code, dedupe_key) DO NOTHING
  RETURNING id INTO v_event_id;

  IF v_event_id IS NULL THEN
    SELECT id INTO v_event_id
    FROM public.domain_events
    WHERE event_code = p_event_code AND dedupe_key = p_dedupe_key;
  END IF;

  -- No phone → still record domain event; skip outbox (fail-closed, no send).
  IF v_phone IS NULL THEN
    RETURN v_event_id;
  END IF;

  SELECT description INTO v_desc FROM public.sms_event_catalog WHERE code = p_event_code;
  v_body := COALESCE(
    p_message_body,
    format('GTR Auto: %s (%s)', v_desc, p_event_code)
  );

  INSERT INTO public.sms_outbox (
    domain_event_id, event_code, recipient_user_id, phone_e164, body
  )
  VALUES (v_event_id, p_event_code, p_profile_id, v_phone, v_body)
  ON CONFLICT (domain_event_id, recipient_user_id) DO NOTHING;

  RETURN v_event_id;
END;
$$;


--
-- Name: _enqueue_delivery_customer_sms(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._enqueue_delivery_customer_sms(p_delivery_job_id uuid, p_event_code text, p_dedupe_key text, p_body text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_contact RECORD;
  v_event_id UUID;
BEGIN
  IF p_event_code IS NULL OR length(trim(p_event_code)) = 0 THEN
    RETURN false;
  END IF;
  IF p_body IS NULL OR length(trim(p_body)) = 0 THEN
    RETURN false;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.sms_event_catalog c
    WHERE c.code = p_event_code AND c.is_active
  ) THEN
    RETURN false;
  END IF;

  SELECT * INTO v_contact
  FROM public._delivery_job_customer_contact(p_delivery_job_id);

  IF NOT FOUND
     OR v_contact.phone_e164 IS NULL
     OR v_contact.profile_id IS NULL THEN
    RETURN false;
  END IF;

  INSERT INTO public.domain_events (event_code, dedupe_key, payload, actor_user_id)
  VALUES (
    p_event_code,
    p_dedupe_key,
    jsonb_build_object(
      'delivery_job_id', p_delivery_job_id,
      'sales_invoice_id', v_contact.sales_invoice_id
    ),
    auth.uid()
  )
  ON CONFLICT (event_code, dedupe_key) DO NOTHING
  RETURNING id INTO v_event_id;

  IF v_event_id IS NULL THEN
    SELECT id INTO v_event_id
    FROM public.domain_events
    WHERE event_code = p_event_code AND dedupe_key = p_dedupe_key;
  END IF;

  IF v_event_id IS NULL THEN
    RETURN false;
  END IF;

  INSERT INTO public.sms_outbox (
    domain_event_id, event_code, recipient_user_id, phone_e164, body
  )
  VALUES (
    v_event_id,
    p_event_code,
    v_contact.profile_id,
    v_contact.phone_e164,
    trim(p_body)
  )
  ON CONFLICT (domain_event_id, recipient_user_id) DO NOTHING;

  RETURN true;
EXCEPTION
  WHEN OTHERS THEN
    RETURN false;
END;
$$;


--
-- Name: _ensure_loyalty_account(uuid, public.currency_code); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._ensure_loyalty_account(p_customer_id uuid, p_currency public.currency_code) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id UUID;
  v_cur public.currency_code;
BEGIN
  SELECT id, currency INTO v_id, v_cur
  FROM public.loyalty_accounts
  WHERE customer_id = p_customer_id
  FOR UPDATE;

  IF v_id IS NULL THEN
    INSERT INTO public.loyalty_accounts (customer_id, currency, points_balance)
    VALUES (p_customer_id, p_currency, 0)
    RETURNING id INTO v_id;
    RETURN v_id;
  END IF;

  IF v_cur <> p_currency THEN
    RAISE EXCEPTION 'loyalty account currency is %, cannot use %', v_cur, p_currency;
  END IF;

  RETURN v_id;
END;
$$;


--
-- Name: _ensure_pick_list_for_invoice(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._ensure_pick_list_for_invoice(p_invoice_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_inv public.sales_invoices%ROWTYPE;
  v_pick UUID;
  v_line RECORD;
  v_bin UUID;
  v_open NUMERIC;
  v_any BOOLEAN := false;
BEGIN
  PERFORM public._online_dispatch_auto_begin();
  PERFORM public._logistics_begin_rpc();

  SELECT * INTO v_inv
  FROM public.sales_invoices
  WHERE id = p_invoice_id AND doc_type = 'invoice' AND status = 'posted'
  FOR UPDATE;
  IF NOT FOUND THEN
    PERFORM public._online_dispatch_auto_clear();
    RAISE EXCEPTION 'posted sales invoice required';
  END IF;
  IF v_inv.fulfillment_mode <> 'dispatch' THEN
    PERFORM public._online_dispatch_auto_clear();
    RAISE EXCEPTION 'pick lists only for dispatch fulfillment invoices';
  END IF;

  SELECT pl.id INTO v_pick
  FROM public.pick_lists pl
  WHERE pl.sales_invoice_id = p_invoice_id
    AND pl.status IN ('draft', 'done')
  ORDER BY pl.created_at DESC
  LIMIT 1;

  IF v_pick IS NOT NULL THEN
    PERFORM public._online_dispatch_auto_clear();
    RETURN v_pick;
  END IF;

  INSERT INTO public.pick_lists (
    document_number, sales_invoice_id, warehouse_id, status, created_by
  )
  VALUES (
    public.next_series_value('PL-'),
    p_invoice_id,
    v_inv.warehouse_id,
    'draft',
    auth.uid()
  )
  RETURNING id INTO v_pick;

  FOR v_line IN
    SELECT *
    FROM public.sales_invoice_lines
    WHERE invoice_id = p_invoice_id
      AND NOT is_core_charge
      AND qty_base > qty_fulfilled
    ORDER BY created_at
  LOOP
    v_open := public._invoice_line_open_qty_base(v_line.id);
    IF v_open <= 0 THEN
      CONTINUE;
    END IF;
    v_any := true;

    SELECT sl.bin_id INTO v_bin
    FROM public.stock_levels sl
    WHERE sl.stock_item_id = v_line.stock_item_id
      AND sl.warehouse_id = v_inv.warehouse_id;

    INSERT INTO public.pick_list_lines (
      pick_list_id, sales_invoice_line_id, stock_item_id, uom_id,
      qty_requested, qty_base_requested, suggested_bin_id
    )
    VALUES (
      v_pick, v_line.id, v_line.stock_item_id, v_line.uom_id,
      v_open, v_open, v_bin
    );
  END LOOP;

  IF NOT v_any THEN
    UPDATE public.pick_lists SET status = 'cancelled', updated_at = now()
    WHERE id = v_pick;
    PERFORM public._online_dispatch_auto_clear();
    RETURN NULL;
  END IF;

  PERFORM public._online_dispatch_auto_clear();
  RETURN v_pick;
EXCEPTION
  WHEN OTHERS THEN
    PERFORM public._online_dispatch_auto_clear();
    RAISE;
END;
$$;


