--
-- Name: _expire_stale_pos_scan_sessions(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._expire_stale_pos_scan_sessions(p_cart_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE public.pos_scan_sessions
  SET status = 'expired', updated_at = now()
  WHERE status IN ('open', 'claimed')
    AND expires_at <= now()
    AND (p_cart_id IS NULL OR cart_id = p_cart_id);
END;
$$;


--
-- Name: _finalize_online_dispatch_order(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._finalize_online_dispatch_order(p_invoice_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_pick UUID;
BEGIN
  IF NOT public._invoice_is_storefront_dispatch(p_invoice_id) THEN
    RETURN NULL;
  END IF;

  BEGIN
    v_pick := public._ensure_pick_list_for_invoice(p_invoice_id);
  EXCEPTION
    WHEN OTHERS THEN
      v_pick := NULL;
  END;

  BEGIN
    PERFORM public._notify_sales_prep(p_invoice_id);
  EXCEPTION
    WHEN OTHERS THEN
      NULL;
  END;

  RETURN v_pick;
END;
$$;


