--
-- Name: _finance_req_approver_on_reporting_line(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._finance_req_approver_on_reporting_line(p_requester_user_id uuid, p_approver_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH RECURSIVE requester_role AS (
    SELECT e.hr_role_id AS role_id
    FROM public.employees e
    WHERE e.user_id = p_requester_user_id
      AND e.hr_role_id IS NOT NULL
    LIMIT 1
  ),
  ancestors AS (
    SELECT r.parent_role_id AS role_id
    FROM public.hr_roles r
    JOIN requester_role rr ON rr.role_id = r.id
    WHERE r.parent_role_id IS NOT NULL
    UNION ALL
    SELECT r.parent_role_id
    FROM public.hr_roles r
    JOIN ancestors a ON a.role_id = r.id
    WHERE r.parent_role_id IS NOT NULL
  )
  SELECT EXISTS (
    SELECT 1
    FROM public.employees e
    WHERE e.user_id = p_approver_user_id
      AND e.hr_role_id IS NOT NULL
      AND e.hr_role_id IN (SELECT role_id FROM ancestors WHERE role_id IS NOT NULL)
  );
$$;


--
-- Name: finance_requisitions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.finance_requisitions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    document_number text,
    req_type public.finance_requisition_type NOT NULL,
    status public.finance_requisition_status DEFAULT 'draft'::public.finance_requisition_status NOT NULL,
    amount numeric(18,2) NOT NULL,
    currency public.currency_code NOT NULL,
    exchange_rate_applied numeric(18,8),
    payee text,
    memo text,
    expense_account_code character varying(10) NOT NULL,
    cash_account_code character varying(10) NOT NULL,
    requested_by uuid NOT NULL,
    submitted_at timestamp with time zone,
    approved_by uuid,
    approved_at timestamp with time zone,
    rejected_by uuid,
    rejected_at timestamp with time zone,
    rejection_reason text,
    disbursed_by uuid,
    disbursed_at timestamp with time zone,
    journal_entry_id uuid,
    payment_entry_id uuid,
    cancelled_at timestamp with time zone,
    cancelled_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    required_approvals integer DEFAULT 1 NOT NULL,
    approval_count integer DEFAULT 0 NOT NULL,
    intended_entry_date date,
    CONSTRAINT finance_requisitions_amount_check CHECK ((amount > (0)::numeric)),
    CONSTRAINT finance_requisitions_approval_count_check CHECK ((approval_count >= 0)),
    CONSTRAINT finance_requisitions_required_approvals_check CHECK ((required_approvals >= 1))
);


--
-- Name: COLUMN finance_requisitions.intended_entry_date; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.finance_requisitions.intended_entry_date IS 'Preferred journal entry_date when disbursed; defaults to CURRENT_DATE.';


--
-- Name: _finance_req_can_approve(public.finance_requisitions); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._finance_req_can_approve(p_requisition public.finance_requisitions) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF auth.role() = 'service_role' THEN
    RETURN true;
  END IF;
  IF auth.uid() IS NULL THEN
    RETURN false;
  END IF;
  IF public.has_staff_role(ARRAY['admin', 'finance']::public.staff_role[]) THEN
    RETURN true;
  END IF;
  -- Reporting-line managers: never self-approve
  IF p_requisition.requested_by = auth.uid() THEN
    RETURN false;
  END IF;
  RETURN public._finance_req_approver_on_reporting_line(
    p_requisition.requested_by,
    auth.uid()
  );
END;
$$;


--
-- Name: _finance_req_id_from_receipt_path(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._finance_req_id_from_receipt_path(p_name text) RETURNS uuid
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$ DECLARE v_seg TEXT; v_id UUID; BEGIN IF p_name IS NULL OR length(trim(p_name))=0 THEN RETURN NULL; END IF; v_seg:=trim(both '/' FROM p_name); IF split_part(v_seg,'/',1)='petty-cash-receipts' THEN v_seg:=substr(v_seg,length('petty-cash-receipts/')+1); END IF; v_seg:=split_part(v_seg,'/',1); BEGIN v_id:=v_seg::uuid; EXCEPTION WHEN invalid_text_representation THEN RETURN NULL; END; RETURN v_id; END; $$;


--
-- Name: _finance_req_required_approvals(public.finance_requisition_type, public.currency_code, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._finance_req_required_approvals(p_req_type public.finance_requisition_type, p_currency public.currency_code, p_amount numeric) RETURNS integer
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  SELECT COALESCE(
    (
      SELECT t.required_approvals
      FROM public.finance_requisition_thresholds t
      WHERE t.is_active
        AND t.req_type = p_req_type
        AND t.currency = p_currency
        AND t.min_amount <= p_amount
      ORDER BY t.min_amount DESC
      LIMIT 1
    ),
    1
  );
$$;


