--
-- Name: _haversine_eta_seconds(double precision, double precision, double precision, double precision); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._haversine_eta_seconds(p_from_lat double precision, p_from_lng double precision, p_to_lat double precision, p_to_lng double precision) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  SELECT CASE
    WHEN public._haversine_meters(p_from_lat, p_from_lng, p_to_lat, p_to_lng) IS NULL
      THEN NULL
    ELSE greatest(
      0,
      ceil(
        public._haversine_meters(p_from_lat, p_from_lng, p_to_lat, p_to_lng)
        / (25.0 * 1000.0 / 3600.0)
      )::integer
    )
  END;
$$;


--
-- Name: _haversine_meters(double precision, double precision, double precision, double precision); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._haversine_meters(p_lat1 double precision, p_lng1 double precision, p_lat2 double precision, p_lng2 double precision) RETURNS double precision
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  SELECT CASE
    WHEN p_lat1 IS NULL OR p_lng1 IS NULL OR p_lat2 IS NULL OR p_lng2 IS NULL THEN NULL
    ELSE (
      2 * 6371000 * asin(
        sqrt(
          power(sin(radians(p_lat2 - p_lat1) / 2), 2)
          + cos(radians(p_lat1)) * cos(radians(p_lat2))
            * power(sin(radians(p_lng2 - p_lng1) / 2), 2)
        )
      )
    )
  END;
$$;


--
-- Name: _invoice_is_storefront_dispatch(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._invoice_is_storefront_dispatch(p_invoice_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.sales_invoices si
    JOIN public.pos_carts c ON c.id = si.cart_id
    WHERE si.id = p_invoice_id
      AND si.doc_type = 'invoice'
      AND si.status = 'posted'
      AND si.fulfillment_mode = 'dispatch'
      AND c.channel = 'storefront'
  );
$$;


--
-- Name: _invoice_line_open_qty_base(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._invoice_line_open_qty_base(p_invoice_line_id uuid) RETURNS numeric
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT GREATEST(
    COALESCE(sil.qty_base, 0) - COALESCE(sil.qty_fulfilled, 0) - COALESCE((
      SELECT SUM(dnl.qty_base)
      FROM public.delivery_note_lines dnl
      JOIN public.delivery_notes dn ON dn.id = dnl.delivery_note_id
      WHERE dnl.sales_invoice_line_id = sil.id
        AND dn.status = 'draft'
    ), 0),
    0
  )
  FROM public.sales_invoice_lines sil
  WHERE sil.id = p_invoice_line_id;
$$;


