-- Name: _line_usd_equiv(numeric, public.currency_code, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._line_usd_equiv(p_amount numeric, p_currency public.currency_code, p_rate numeric) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  SELECT CASE
    WHEN p_currency = 'USD' THEN p_amount
    WHEN p_rate IS NULL OR p_rate = 0 THEN NULL
    ELSE round(p_amount / p_rate, 2)
  END;
$$;


