--
-- Name: _next_payroll_schedule_at(public.hr_pay_frequency, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._next_payroll_schedule_at(p_frequency public.hr_pay_frequency, p_after timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_base TIMESTAMPTZ := COALESCE(p_after, now());
  v_day DATE := v_base::date;
  v_candidate TIMESTAMPTZ;
  v_dow INT;
BEGIN
  IF p_frequency = 'weekly' THEN
    v_dow := EXTRACT(ISODOW FROM v_day)::int;
    v_candidate := (v_day + ((8 - v_dow) % 7))::timestamptz + interval '6 hours';
    IF v_candidate <= v_base THEN v_candidate := v_candidate + interval '7 days'; END IF;
    RETURN v_candidate;
  ELSIF p_frequency = 'fortnightly' THEN
    v_candidate := date_trunc('month', v_base)::timestamptz + interval '6 hours';
    IF v_candidate > v_base THEN RETURN v_candidate; END IF;
    v_candidate := date_trunc('month', v_base)::timestamptz + interval '14 days 6 hours';
    IF v_candidate > v_base THEN RETURN v_candidate; END IF;
    RETURN (date_trunc('month', v_base) + interval '1 month')::timestamptz + interval '6 hours';
  ELSIF p_frequency = 'monthly' THEN
    v_candidate := date_trunc('month', v_base)::timestamptz + interval '24 days 6 hours';
    IF v_candidate <= v_base THEN v_candidate := (date_trunc('month', v_base) + interval '1 month 24 days 6 hours')::timestamptz; END IF;
    RETURN v_candidate;
  END IF;
  RAISE EXCEPTION 'unsupported pay frequency: %', p_frequency;
END;
$$;


--
-- Name: _normalize_delivery_pod_object_path(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._normalize_delivery_pod_object_path(p_path text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_path TEXT;
BEGIN
  IF p_path IS NULL OR length(trim(p_path)) = 0 THEN
    RETURN NULL;
  END IF;
  v_path := trim(both FROM p_path);
  v_path := trim(both '/' FROM v_path);
  -- Reject path traversal / absolute-looking segments
  IF v_path ~ '\.\.' OR v_path ~ '//' OR position('\' IN v_path) > 0 THEN
    RAISE EXCEPTION 'invalid POD storage path';
  END IF;
  IF split_part(v_path, '/', 1) = 'delivery-pods' THEN
    v_path := substr(v_path, length('delivery-pods/') + 1);
    v_path := trim(both '/' FROM v_path);
  END IF;
  IF v_path IS NULL OR length(v_path) = 0 OR position('/' IN v_path) = 0 THEN
    RAISE EXCEPTION 'POD path must be {job_id}/{filename} under delivery-pods';
  END IF;
  RETURN v_path;
END;
$$;


--
-- Name: _normalize_e164(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._normalize_e164(p_phone text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE
  v TEXT;
BEGIN
  v := NULLIF(trim(COALESCE(p_phone, '')), '');
  IF v IS NULL THEN
    RETURN NULL;
  END IF;
  v := regexp_replace(v, '[\s\-()]', '', 'g');
  IF v !~ '^\+?[0-9]{8,15}$' THEN
    RETURN NULL;
  END IF;
  IF left(v, 1) <> '+' THEN
    v := '+' || v;
  END IF;
  RETURN v;
END;
$_$;


