--
-- Name: _notify_out_for_delivery(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._notify_out_for_delivery(p_delivery_job_id uuid, p_track_token text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_base TEXT;
  v_track_url TEXT;
  v_body TEXT;
BEGIN
  IF p_track_token IS NULL OR length(trim(p_track_token)) = 0 THEN
    RETURN;
  END IF;

  -- PUBLIC_SITE_URL → GUC app.public_site_url; else app_settings public.site_url.
  v_base := NULLIF(
    trim(both FROM COALESCE(
      NULLIF(current_setting('app.public_site_url', true), ''),
      (
        SELECT NULLIF(trim(both FROM (s.value_json ->> 'url')), '')
        FROM public.app_settings s
        WHERE s.key = 'public.site_url'
      )
    )),
    ''
  );

  IF v_base IS NOT NULL THEN
    v_base := rtrim(v_base, '/');
    v_track_url := v_base || '/track/' || trim(p_track_token);
  ELSE
    v_track_url := '/track/' || trim(p_track_token);
  END IF;

  v_body := format(
    'GTR Auto: Your order is out for delivery. Track: %s',
    v_track_url
  );

  PERFORM public._enqueue_delivery_customer_sms(
    p_delivery_job_id,
    'delivery_out_for_delivery',
    'delivery_out_for_delivery:' || p_delivery_job_id::text,
    v_body
  );
EXCEPTION
  WHEN OTHERS THEN
    -- Fail closed: never surface notify errors to update_delivery_job_status.
    NULL;
END;
$$;


--
-- Name: FUNCTION _notify_out_for_delivery(p_delivery_job_id uuid, p_track_token text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public._notify_out_for_delivery(p_delivery_job_id uuid, p_track_token text) IS 'Best-effort SMS for dispatched jobs. Track URL absolute when PUBLIC_SITE_URL is mirrored as GUC app.public_site_url (or app_settings public.site_url.url); else relative /track/{token}. Fail closed. No WA outbox — skip WhatsApp.';


--
-- Name: _notify_sales_prep(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._notify_sales_prep(p_invoice_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_doc TEXT;
  v_title TEXT;
  v_body TEXT;
  v_uid UUID;
BEGIN
  IF NOT public._invoice_is_storefront_dispatch(p_invoice_id) THEN
    RETURN;
  END IF;

  SELECT COALESCE(si.document_number, si.id::text)
  INTO v_doc
  FROM public.sales_invoices si
  WHERE si.id = p_invoice_id;

  v_title := 'Prepare online order';
  v_body := format(
    'Online dispatch order %s is ready for pick/pack. Open Sales prep / Logistics.',
    v_doc
  );

  PERFORM public._staff_ops_notify_begin();

  FOR v_uid IN
    SELECT DISTINCT sr.user_id
    FROM public.staff_roles sr
    WHERE sr.role IN ('sales', 'admin')
  LOOP
    INSERT INTO public.staff_ops_notifications (
      kind, sales_invoice_id, recipient_user_id, title, body
    )
    VALUES (
      'sales_prep', p_invoice_id, v_uid, v_title, v_body
    )
    ON CONFLICT (kind, sales_invoice_id, recipient_user_id) DO NOTHING;
  END LOOP;

  BEGIN
    PERFORM public.emit_domain_event(
      'order_prep_needed',
      'invoice:prep:' || p_invoice_id::text,
      jsonb_build_object('invoice_id', p_invoice_id, 'document_number', v_doc),
      NULL,
      v_body
    );
  EXCEPTION
    WHEN OTHERS THEN
      NULL; -- fail closed: never block order path
  END;
END;
$$;


--
-- Name: _notify_wishlist_back_in_stock(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._notify_wishlist_back_in_stock(p_stock_item_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row RECORD;
  v_phone TEXT;
  v_oem TEXT;
  v_day TEXT := to_char(timezone('utc', now()), 'YYYY-MM-DD');
BEGIN
  SELECT oem_part_number INTO v_oem
  FROM public.stock_items
  WHERE id = p_stock_item_id;

  FOR v_row IN
    SELECT
      w.id AS wishlist_id,
      w.customer_id,
      c.profile_id,
      c.phone_e164 AS cust_phone,
      c.whatsapp_e164 AS cust_wa,
      p.phone_e164 AS profile_phone
    FROM public.customer_wishlist_items w
    JOIN public.customers c ON c.id = w.customer_id
    LEFT JOIN public.profiles p ON p.id = c.profile_id
    WHERE w.stock_item_id = p_stock_item_id
      AND w.notify_when_in_stock = true
      AND c.profile_id IS NOT NULL
  LOOP
    v_phone := COALESCE(
      NULLIF(trim(COALESCE(v_row.cust_phone, '')), ''),
      NULLIF(trim(COALESCE(v_row.profile_phone, '')), ''),
      NULLIF(trim(COALESCE(v_row.cust_wa, '')), '')
    );

    PERFORM public._enqueue_customer_sms(
      'wishlist_back_in_stock',
      format('wishlist:%s:%s:%s', v_row.wishlist_id::text, p_stock_item_id::text, v_day),
      v_row.profile_id,
      v_phone,
      jsonb_build_object(
        'wishlist_id', v_row.wishlist_id,
        'customer_id', v_row.customer_id,
        'stock_item_id', p_stock_item_id,
        'oem_part_number', v_oem
      ),
      format(
        'GTR Auto: %s is back in stock.',
        COALESCE(v_oem, 'A wishlist part')
      )
    );
  END LOOP;

  -- Optional staff fan-out via existing emit (manager prefs); ignore if no staff auth.
  BEGIN
    PERFORM public.emit_domain_event(
      'wishlist_back_in_stock',
      format('stock:back:%s:%s', p_stock_item_id::text, v_day),
      jsonb_build_object('stock_item_id', p_stock_item_id, 'oem_part_number', v_oem)
    );
  EXCEPTION
    WHEN OTHERS THEN
      NULL; -- fail-closed: customer enqueue already attempted
  END;
END;
$$;


