$$;


--
-- Name: _recompute_delivery_eta_haversine(uuid, double precision, double precision); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._recompute_delivery_eta_haversine(p_job_id uuid, p_lat double precision, p_lng double precision) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_drop_lat DOUBLE PRECISION;
  v_drop_lng DOUBLE PRECISION;
  v_secs INTEGER;
  v_source public.delivery_eta_source;
BEGIN
  SELECT dropoff_lat, dropoff_lng, eta_source
  INTO v_drop_lat, v_drop_lng, v_source
  FROM public.delivery_jobs
  WHERE id = p_job_id;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  -- Do not overwrite manual ETA
  IF v_source = 'manual' THEN
    RETURN;
  END IF;

  IF v_drop_lat IS NULL OR v_drop_lng IS NULL THEN
    RETURN;
  END IF;

  v_secs := public._haversine_eta_seconds(p_lat, p_lng, v_drop_lat, v_drop_lng);
  IF v_secs IS NULL THEN
    RETURN;
  END IF;

  UPDATE public.delivery_jobs
  SET
    eta_seconds = v_secs,
    eta_at = now() + make_interval(secs => v_secs),
    eta_source = 'haversine',
    eta_updated_at = now(),
    updated_at = now()
  WHERE id = p_job_id;
END;
$$;


--
-- Name: _recon_assert_single_currency(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._recon_assert_single_currency(p_reconciliation_id uuid) RETURNS void
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_header public.currency_code;
  v_bad INT;
BEGIN
  SELECT currency INTO v_header
  FROM public.stock_reconciliations
  WHERE id = p_reconciliation_id;

  SELECT count(DISTINCT l.currency) INTO v_bad
  FROM public.stock_reconciliation_lines l
  WHERE l.stock_reconciliation_id = p_reconciliation_id;

  IF v_bad > 1 THEN
    RAISE EXCEPTION 'mixed line currencies not allowed on reconciliation %', p_reconciliation_id;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.stock_reconciliation_lines l
    WHERE l.stock_reconciliation_id = p_reconciliation_id
      AND l.currency IS DISTINCT FROM v_header
  ) THEN
    RAISE EXCEPTION 'line currency must match reconciliation header currency %', v_header;
  END IF;
END;
$$;


