--
-- Name: _recon_compute_variance_value(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._recon_compute_variance_value(p_reconciliation_id uuid) RETURNS numeric
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(
    round(
      SUM(abs(l.variance_qty) * l.unit_cost),
      2
    ),
    0
  )
  FROM public.stock_reconciliation_lines l
  WHERE l.stock_reconciliation_id = p_reconciliation_id
    AND l.variance_qty <> 0;
$$;


--
-- Name: _recon_dual_auth_threshold(public.currency_code); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._recon_dual_auth_threshold(p_currency public.currency_code) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(
    (s.value_json ->> p_currency::text)::numeric,
    (s.value_json ->> 'USD')::numeric,
    500::numeric
  )
  FROM public.app_settings s
  WHERE s.key = 'inventory.reconciliation_variance_dual_auth_threshold';
$$;


