--
-- Name: _refresh_payroll_run_totals(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._refresh_payroll_run_totals(p_run_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE public.payroll_runs r
  SET
    total_gross = COALESCE((
      SELECT SUM(l.gross_amount) FROM public.payroll_lines l WHERE l.payroll_run_id = p_run_id
    ), 0),
    total_deductions = COALESCE((
      SELECT SUM(l.deductions_amount) FROM public.payroll_lines l WHERE l.payroll_run_id = p_run_id
    ), 0),
    total_net = COALESCE((
      SELECT SUM(l.net_amount) FROM public.payroll_lines l WHERE l.payroll_run_id = p_run_id
    ), 0),
    updated_at = now()
  WHERE r.id = p_run_id;
END;
$$;


--
-- Name: _require_cart_mutate(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._require_cart_mutate(p_cart_id uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_locked BOOLEAN;
BEGIN
  SELECT (checkout_locked_at IS NOT NULL)
    INTO v_locked
  FROM public.pos_carts
  WHERE id = p_cart_id;

  IF COALESCE(v_locked,false)
     AND COALESCE(current_setting('app.commerce_finalize',true),'') <> '1' THEN
    RAISE EXCEPTION 'cart is locked by checkout';
  END IF;

  IF COALESCE(current_setting('app.commerce_finalize',true),'') = '1' THEN
    IF COALESCE(auth.jwt()->>'role','') = 'service_role'
       OR public.has_staff_role(ARRAY['admin','finance','sales']::public.staff_role[]) THEN
      RETURN;
    END IF;
    RAISE EXCEPTION 'commerce finalization role required';
  END IF;

  IF public._storefront_rpc_active() THEN
    PERFORM public._assert_customer_owns_open_cart(p_cart_id);
    RETURN;
  END IF;
  PERFORM public._require_sales_staff();
END;
$$;


