--
-- Name: _resolve_customer_stock_item(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._resolve_customer_stock_item(p_stock_item_id uuid, p_oem_part_number text) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id UUID;
  v_oem TEXT := NULLIF(trim(COALESCE(p_oem_part_number, '')), '');
BEGIN
  IF p_stock_item_id IS NOT NULL THEN
    SELECT si.id INTO v_id
    FROM public.stock_items si
    WHERE si.id = p_stock_item_id;
    IF v_id IS NULL THEN
      RAISE EXCEPTION 'stock item not found';
    END IF;
    RETURN v_id;
  END IF;

  IF v_oem IS NULL THEN
    RAISE EXCEPTION 'stock_item_id or oem_part_number required';
  END IF;

  SELECT si.id INTO v_id
  FROM public.stock_items si
  WHERE lower(si.oem_part_number) = lower(v_oem)
  ORDER BY si.created_at ASC
  LIMIT 1;

  IF v_id IS NULL THEN
    RAISE EXCEPTION 'stock item not found for OEM %', v_oem;
  END IF;
  RETURN v_id;
END;
$$;


--
-- Name: _reverse_journal_inventory(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._reverse_journal_inventory(p_entry_id uuid, p_description text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_src public.journal_entries%ROWTYPE;
  v_new_id UUID;
  v_line RECORD;
  v_desc TEXT;
BEGIN
  SELECT * INTO v_src FROM public.journal_entries WHERE id = p_entry_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'journal entry not found: %', p_entry_id;
  END IF;
  IF v_src.status <> 'posted' THEN
    RAISE EXCEPTION 'only posted journals can be reversed';
  END IF;
  IF public.is_period_locked(CURRENT_DATE) THEN
    RAISE EXCEPTION 'accounting period is locked for today';
  END IF;

  v_desc := COALESCE(
    p_description,
    format('Reversal of %s', COALESCE(v_src.document_number, v_src.id::text))
  );

  INSERT INTO public.journal_entries (
    entry_date, description, currency, exchange_rate_applied,
    status, is_reversal, reverses_entry_id, posted_by, posted_at, document_number
  )
  VALUES (
    CURRENT_DATE,
    v_desc,
    v_src.currency,
    v_src.exchange_rate_applied,
    'draft',
    true,
    v_src.id,
    auth.uid(),
    now(),
    public.next_series_value('JV-')
  )
  RETURNING id INTO v_new_id;

  FOR v_line IN
    SELECT account_code, debit, credit, currency
    FROM public.journal_entry_lines
    WHERE journal_entry_id = p_entry_id
  LOOP
    INSERT INTO public.journal_entry_lines (
      journal_entry_id, account_code, debit, credit, currency
    )
    VALUES (
      v_new_id, v_line.account_code, v_line.credit, v_line.debit, v_line.currency
    );
  END LOOP;

  PERFORM public._assert_journal_balanced(v_new_id);

  UPDATE public.journal_entries
  SET status = 'posted', posted_at = now(), posted_by = COALESCE(auth.uid(), posted_by)
  WHERE id = v_new_id;

  RETURN v_new_id;
END;
$$;


--
-- Name: _review_photo_review_id_from_path(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._review_photo_review_id_from_path(p_name text) RETURNS uuid
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_seg TEXT;
  v_id UUID;
BEGIN
  IF p_name IS NULL OR length(trim(p_name)) = 0 THEN
    RETURN NULL;
  END IF;
  v_seg := trim(both '/' FROM p_name);
  IF split_part(v_seg, '/', 1) = 'review-photos' THEN
    v_seg := substr(v_seg, length('review-photos/') + 1);
  END IF;
  v_seg := split_part(v_seg, '/', 1);
  BEGIN
    v_id := v_seg::uuid;
  EXCEPTION
    WHEN invalid_text_representation THEN
      RETURN NULL;
  END;
  RETURN v_id;
END;
$$;


