--
-- Name: _storefront_customer_provision_denied(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._storefront_customer_provision_denied(p_uid uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT p_uid IS NOT NULL AND (
    EXISTS (
      SELECT 1 FROM public.profiles pr
      WHERE pr.id = p_uid AND pr.is_staff IS TRUE
    )
    OR EXISTS (
      SELECT 1 FROM public.staff_roles sr WHERE sr.user_id = p_uid
    )
    OR EXISTS (
      SELECT 1 FROM public.employees e WHERE e.user_id = p_uid
    )
    OR EXISTS (
      SELECT 1
      FROM auth.users u
      WHERE u.id = p_uid
        AND coalesce(u.raw_app_meta_data ->> 'gtr_provisioned_via', '') =
          'hr_onboarding'
    )
  );
$$;


--
-- Name: FUNCTION _storefront_customer_provision_denied(p_uid uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public._storefront_customer_provision_denied(p_uid uuid) IS 'True when uid must not receive a retail customers row (staff_roles, employees, profiles.is_staff, or HR onboarding Admin create). Internal helper: EXECUTE for service_role only; DEFINER callers use owner rights.';


