    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.source_cart_id IS NOT NULL THEN
    SELECT c.vehicle_model_slug, c.vehicle_model_name, c.vehicle_generation,
           c.vehicle_chassis_code, c.vehicle_engine_code, c.vehicle_contexts
