--
-- Name: accept_pos_split_affordable_items(uuid, jsonb, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accept_pos_split_affordable_items(p_session_id uuid, p_items jsonb, p_customer_confirmed boolean, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE s public.pos_split_payment_sessions%ROWTYPE; o public.commerce_orders%ROWTYPE; c public.pos_carts%ROWTYPE; l public.pos_cart_lines%ROWTYPE;
 e JSONB; v_id UUID; v_qty NUMERIC; v_fraction NUMERIC; v_total NUMERIC:=0; v_locked NUMERIC; v_remaining NUMERIC; v_apply NUMERIC; v_refund NUMERIC;
 leg public.pos_split_payment_legs%ROWTYPE; r RECORD; v_available NUMERIC; v_lines JSONB;
BEGIN
 PERFORM public._require_payments_staff();
 IF NOT COALESCE(p_customer_confirmed,false) THEN RAISE EXCEPTION 'explicit customer confirmation is required before reducing a paid basket'; END IF;
 IF p_items IS NULL OR jsonb_typeof(p_items)<>'array' OR jsonb_array_length(p_items)=0 THEN RAISE EXCEPTION 'at least one accepted line is required'; END IF;
 PERFORM private.refresh_pos_split_payment_session(p_session_id);
 SELECT * INTO s FROM public.pos_split_payment_sessions WHERE id=p_session_id FOR UPDATE;
 IF NOT FOUND OR s.final_invoice_id IS NOT NULL OR s.status IN('settled','refund_pending','refunded','cancelled','finalizing') THEN RAISE EXCEPTION 'active unsettled split session required'; END IF;
 IF EXISTS(SELECT 1 FROM public.pos_split_payment_legs WHERE session_id=s.id AND status IN('pending','unknown')) THEN RAISE EXCEPTION 'reconcile the in-flight payment before changing the basket'; END IF;
 v_locked:=round(s.captured_amount+s.held_amount,2); IF v_locked<=0 THEN RAISE EXCEPTION 'no locked payment is available for reduced-basket settlement'; END IF;
 SELECT * INTO o FROM public.commerce_orders WHERE id=s.commerce_order_id FOR UPDATE;
 SELECT * INTO c FROM public.pos_carts WHERE id=o.cart_id FOR UPDATE;
 IF NOT FOUND OR c.created_by<>auth.uid() THEN RAISE EXCEPTION 'current operator cart required'; END IF;
 DELETE FROM public.pos_split_acceptance_lines WHERE session_id=s.id;
 FOR e IN SELECT * FROM jsonb_array_elements(p_items) LOOP
  v_id:=(e->>'cart_line_id')::uuid; v_qty:=round(COALESCE((e->>'qty')::numeric,0),3);
  SELECT * INTO l FROM public.pos_cart_lines WHERE id=v_id AND cart_id=c.id AND NOT is_core_charge FOR UPDATE;
  IF NOT FOUND OR v_qty<=0 OR v_qty>l.qty+0.0001 THEN RAISE EXCEPTION 'invalid accepted quantity for cart line %',v_id; END IF;
  IF EXISTS(SELECT 1 FROM public.pos_split_acceptance_lines WHERE session_id=s.id AND cart_line_id=l.id) THEN RAISE EXCEPTION 'duplicate accepted cart line %',l.id; END IF;
  v_fraction:=v_qty/l.qty;
  INSERT INTO public.pos_split_acceptance_lines(session_id,cart_line_id,original_qty,accepted_qty,accepted_line_total,auto_included_core,accepted_by)
  VALUES(s.id,l.id,l.qty,v_qty,round(l.line_total*v_fraction,2),false,auth.uid());
  v_total:=v_total+round(l.line_total*v_fraction,2);
  FOR r IN SELECT x.* FROM public.pos_cart_lines x WHERE x.parent_line_id=l.id AND x.is_core_charge ORDER BY x.id LOOP
   INSERT INTO public.pos_split_acceptance_lines(session_id,cart_line_id,original_qty,accepted_qty,accepted_line_total,auto_included_core,accepted_by)
   VALUES(s.id,r.id,r.qty,round(r.qty*v_fraction,3),round(r.line_total*v_fraction,2),true,auth.uid());
   v_total:=v_total+round(r.line_total*v_fraction,2);
  END LOOP;
 END LOOP;
 v_total:=round(v_total,2);
 IF v_total<=0 OR v_total>v_locked+0.01 THEN RAISE EXCEPTION 'accepted basket total % must be > 0 and <= locked payment %',v_total,v_locked; END IF;

 UPDATE public.pos_cart_lines x SET
  qty=a.accepted_qty,
  qty_base=round(x.qty_base*(a.accepted_qty/a.original_qty),3),
  line_total=a.accepted_line_total
 FROM public.pos_split_acceptance_lines a WHERE a.session_id=s.id AND a.cart_line_id=x.id;
 DELETE FROM public.pos_cart_lines x WHERE x.cart_id=c.id AND NOT EXISTS(
  SELECT 1 FROM public.pos_split_acceptance_lines a WHERE a.session_id=s.id AND a.cart_line_id=x.id);

 DELETE FROM public.inventory_reservations WHERE commerce_order_id=o.id AND state='active';
 FOR r IN SELECT stock_item_id,SUM(qty_base)::numeric required_qty FROM public.pos_cart_lines
  WHERE cart_id=c.id AND COALESCE(issues_stock,true)=true AND NOT is_core_charge GROUP BY stock_item_id ORDER BY stock_item_id LOOP
  v_available:=public.get_inventory_available_quantity(r.stock_item_id,c.warehouse_id);
  IF v_available<r.required_qty THEN RAISE EXCEPTION 'accepted basket stock became unavailable for item % (available %, required %)',r.stock_item_id,v_available,r.required_qty; END IF;
  INSERT INTO public.inventory_reservations(commerce_order_id,stock_item_id,warehouse_id,required_qty,reserved_qty,expires_at,state,reservation_reason)
  VALUES(o.id,r.stock_item_id,c.warehouse_id,r.required_qty,r.required_qty,greatest(COALESCE(o.reservation_expires_at,now()),now()+interval '60 minutes'),'active','pos_checkout_reduced_basket_hold');
 END LOOP;
 SELECT COALESCE(jsonb_agg(jsonb_build_object('line_id',x.id,'stock_item_id',x.stock_item_id,'uom_id',x.uom_id,'qty',x.qty,'qty_base',x.qty_base,
  'unit_price',x.unit_price,'line_total',x.line_total,'is_core_charge',x.is_core_charge) ORDER BY x.created_at),'[]'::jsonb)
 INTO v_lines FROM public.pos_cart_lines x WHERE x.cart_id=c.id;
 UPDATE public.commerce_orders SET subtotal=v_total,total=v_total,checkout_snapshot=jsonb_set(checkout_snapshot,'{lines}',v_lines,true),
  reservation_expires_at=greatest(COALESCE(reservation_expires_at,now()),now()+interval '60 minutes'),updated_at=now() WHERE id=o.id;
 UPDATE public.pos_split_payment_sessions SET total_amount=v_total,reduced_basket_accepted_at=now(),reduced_basket_accepted_by=auth.uid(),
  reduced_basket_customer_confirmed=true,reduced_basket_notes=p_notes,updated_at=now() WHERE id=s.id;

 v_remaining:=v_total;
 FOR leg IN SELECT * FROM public.pos_split_payment_legs WHERE session_id=s.id AND status='captured' ORDER BY sequence_no FOR UPDATE LOOP
  v_apply:=least(leg.requested_amount,greatest(v_remaining,0)); v_refund:=round(leg.requested_amount-v_apply,2); v_remaining:=round(v_remaining-v_apply,2);
  UPDATE public.pos_split_payment_legs SET applied_target_amount=v_apply,refund_required_amount=v_refund,updated_at=now() WHERE id=leg.id;
  IF v_refund>0.009 THEN
   INSERT INTO public.pos_split_refund_requests(session_id,leg_id,gross_amount,fee_policy,external_reference,notes,created_by)
   VALUES(s.id,leg.id,v_refund,'manual_review','GTR-SPLIT-SURPLUS-'||leg.id::text,
    concat_ws(' · ','Captured surplus after customer accepted reduced basket',p_notes),auth.uid()) ON CONFLICT(leg_id) DO UPDATE SET
    gross_amount=EXCLUDED.gross_amount,notes=EXCLUDED.notes,updated_at=now() WHERE public.pos_split_refund_requests.status IN('review','failed');
  END IF;
 END LOOP;
 FOR leg IN SELECT * FROM public.pos_split_payment_legs WHERE session_id=s.id AND status='held' ORDER BY sequence_no FOR UPDATE LOOP
  v_apply:=least(leg.requested_amount,greatest(v_remaining,0)); v_remaining:=round(v_remaining-v_apply,2);
  IF v_apply<=0.009 THEN UPDATE public.pos_split_payment_legs SET status='cancelled',applied_target_amount=0,updated_at=now() WHERE id=leg.id;
  ELSE UPDATE public.pos_split_payment_legs SET metadata=CASE WHEN v_apply<requested_amount-0.009 THEN metadata||jsonb_build_object('original_held_amount',requested_amount) ELSE metadata END,
    requested_amount=v_apply,applied_target_amount=v_apply,refund_required_amount=0,updated_at=now() WHERE id=leg.id; END IF;
 END LOOP;
 IF v_remaining>0.01 THEN RAISE EXCEPTION 'accepted basket requires % more than locked captured/held funds',v_remaining; END IF;
 UPDATE public.pos_split_payment_legs SET status='cancelled',updated_at=now() WHERE session_id=s.id AND status='planned';
 PERFORM private.refresh_pos_split_payment_session(s.id);
 RETURN private.finalize_pos_split_payment_session(s.id);
END $$;


--
-- Name: add_cart_line(uuid, uuid, uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_cart_line(p_cart_id uuid, p_stock_item_id uuid, p_uom_id uuid, p_qty numeric) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_cart public.pos_carts%ROWTYPE;
  v_price numeric;
  v_core numeric;
  v_currency public.currency_code;
  v_qty_base numeric;
  v_part_id uuid;
  v_core_id uuid;
  v_kit public.item_kits%ROWTYPE;
  v_comp record;
  v_comp_qty numeric;
  v_comp_base numeric;
  v_comp_id uuid;
BEGIN
  PERFORM public._require_cart_mutate(p_cart_id);

  SELECT * INTO v_cart
  FROM public.pos_carts
  WHERE id = p_cart_id
  FOR UPDATE;

  IF NOT FOUND OR v_cart.status <> 'open' THEN
    RAISE EXCEPTION 'open cart not found';
  END IF;
  IF p_qty IS NULL OR p_qty <= 0 THEN
    RAISE EXCEPTION 'qty must be > 0';
  END IF;

  SELECT * INTO v_kit
  FROM public.item_kits
  WHERE stock_item_id = p_stock_item_id
    AND is_active;

  SELECT r.unit_price, r.core_charge, r.currency
  INTO v_price, v_core, v_currency
  FROM public.resolve_item_price(v_cart.customer_id, p_stock_item_id) r;

  IF v_currency IS NULL OR v_currency IS DISTINCT FROM v_cart.currency THEN
    RAISE EXCEPTION 'price currency % does not match cart currency %; cross-currency cart pricing is not allowed',
      COALESCE(v_currency::text, 'NULL'), v_cart.currency;
  END IF;

  v_qty_base := public.convert_to_base_uom(p_stock_item_id, p_uom_id, p_qty);

  IF v_kit.id IS NOT NULL AND v_kit.sell_mode = 'explode' THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.item_kit_components WHERE kit_id = v_kit.id
    ) THEN
      RAISE EXCEPTION 'explode kit % has no BOM components', v_kit.id;
    END IF;

    INSERT INTO public.pos_cart_lines(
      cart_id, stock_item_id, uom_id, qty, qty_base, unit_price, line_total,
      is_core_charge, issues_stock, kit_id, kit_line_kind
    ) VALUES (
      p_cart_id, p_stock_item_id, p_uom_id, p_qty, v_qty_base, v_price,
      round(v_price * p_qty, 2), false, false, v_kit.id, 'header'
    ) RETURNING id INTO v_part_id;

    IF v_core IS NOT NULL AND v_core > 0 THEN
      INSERT INTO public.pos_cart_lines(
        cart_id, stock_item_id, parent_line_id, uom_id, qty, qty_base,
        unit_price, line_total, is_core_charge, issues_stock, kit_id, kit_line_kind
      ) VALUES (
        p_cart_id, p_stock_item_id, v_part_id, p_uom_id, p_qty, v_qty_base,
        v_core, round(v_core * p_qty, 2), true, false, v_kit.id, NULL
      ) RETURNING id INTO v_core_id;
    END IF;

    FOR v_comp IN
      SELECT * FROM public.item_kit_components WHERE kit_id = v_kit.id ORDER BY created_at
    LOOP
      v_comp_qty := v_comp.qty * p_qty;
      v_comp_base := public.convert_to_base_uom(v_comp.component_item_id, v_comp.uom_id, v_comp_qty);
      INSERT INTO public.pos_cart_lines(
        cart_id, stock_item_id, parent_line_id, uom_id, qty, qty_base,
        unit_price, line_total, is_core_charge, issues_stock, kit_id, kit_line_kind
      ) VALUES (
        p_cart_id, v_comp.component_item_id, v_part_id, v_comp.uom_id,
        v_comp_qty, v_comp_base, 0, 0, false, true, v_kit.id, 'component'
      ) RETURNING id INTO v_comp_id;
    END LOOP;

    UPDATE public.pos_carts SET updated_at = now() WHERE id = p_cart_id;
    RETURN v_part_id;
  END IF;

  INSERT INTO public.pos_cart_lines(
    cart_id, stock_item_id, uom_id, qty, qty_base, unit_price, line_total,
    is_core_charge, issues_stock, kit_id, kit_line_kind
  ) VALUES (
    p_cart_id, p_stock_item_id, p_uom_id, p_qty, v_qty_base, v_price,
    round(v_price * p_qty, 2), false, true, v_kit.id,
    CASE WHEN v_kit.id IS NOT NULL THEN 'header'::public.kit_line_kind ELSE NULL END
  ) RETURNING id INTO v_part_id;

  IF v_core IS NOT NULL AND v_core > 0 THEN
    INSERT INTO public.pos_cart_lines(
      cart_id, stock_item_id, parent_line_id, uom_id, qty, qty_base,
      unit_price, line_total, is_core_charge, issues_stock, kit_id, kit_line_kind
    ) VALUES (
      p_cart_id, p_stock_item_id, v_part_id, p_uom_id, p_qty, v_qty_base,
      v_core, round(v_core * p_qty, 2), true, false, v_kit.id, NULL
    ) RETURNING id INTO v_core_id;
  END IF;

  UPDATE public.pos_carts SET updated_at = now() WHERE id = p_cart_id;
  RETURN v_part_id;
END;
$$;


--
-- Name: add_cart_line_from_qr(uuid, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_cart_line_from_qr(p_cart_id uuid, p_qr_payload text, p_qty numeric DEFAULT 1) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_oem TEXT;
  v_item UUID;
  v_uom UUID;
  v_m TEXT[];
  v_staff BOOLEAN;
  v_companion BOOLEAN;
BEGIN
  PERFORM public._expire_stale_pos_scan_sessions(p_cart_id);

  v_staff := (
    auth.role() = 'service_role'
    OR public.has_staff_role(ARRAY['admin', 'sales', 'warehouse']::public.staff_role[])
  );
  v_companion := EXISTS (
    SELECT 1
    FROM public.pos_scan_sessions s
    WHERE s.cart_id = p_cart_id
      AND s.status = 'claimed'
      AND s.scanner_user_id = auth.uid()
      AND s.expires_at > now()
  );

  -- Standalone: sales/warehouse/admin — no session required.
  -- Companion: claimed scanner may also add via this RPC.
  IF NOT v_staff AND NOT v_companion THEN
    RAISE EXCEPTION 'sales staff or claimed scan companion required';
  END IF;

  v_m := regexp_match(
    trim(p_qr_payload),
    '^gtr://part/([^?]+)\?batch=([^&]+)&valuation=(FIFO|AVG)$'
  );
  IF v_m IS NULL THEN
    RAISE EXCEPTION 'invalid inventory QR payload';
  END IF;
  v_oem := v_m[1];

  SELECT id, base_uom_id INTO v_item, v_uom
  FROM public.stock_items WHERE oem_part_number = v_oem;
  IF v_item IS NULL THEN
    RAISE EXCEPTION 'unknown part %', v_oem;
  END IF;

  -- add_cart_line uses _require_cart_mutate (staff). Companion who is staff is fine;
  -- if only companion flag (should not happen — claim requires staff), temporarily
  -- allow via service path by calling with storefront flag off — still need staff.
  IF NOT v_staff THEN
    RAISE EXCEPTION 'companion claim requires sales staff account';
  END IF;

  RETURN public.add_cart_line(p_cart_id, v_item, v_uom, p_qty);
END;
$_$;


--
-- Name: add_consignment_entry_line(uuid, uuid, uuid, numeric, numeric, numeric, public.currency_code); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_consignment_entry_line(p_entry_id uuid, p_stock_item_id uuid, p_uom_id uuid, p_qty numeric, p_unit_cost numeric DEFAULT 0, p_unit_price numeric DEFAULT 0, p_currency public.currency_code DEFAULT NULL::public.currency_code) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_hdr public.consignment_entries%ROWTYPE;
  v_line_no INT;
  v_id UUID;
  v_cur public.currency_code;
BEGIN
  PERFORM public._require_consignment_staff();

  SELECT * INTO v_hdr FROM public.consignment_entries WHERE id = p_entry_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'consignment entry not found: %', p_entry_id;
  END IF;
  IF v_hdr.status <> 'draft' THEN
    RAISE EXCEPTION 'lines editable only while draft';
  END IF;
  IF p_qty IS NULL OR p_qty <= 0 THEN
    RAISE EXCEPTION 'qty must be > 0';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.stock_items WHERE id = p_stock_item_id) THEN
    RAISE EXCEPTION 'stock item not found';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.uoms WHERE id = p_uom_id) THEN
    RAISE EXCEPTION 'uom not found';
  END IF;

  IF v_hdr.purpose = 'recognize_sale' AND COALESCE(p_unit_price, 0) <= 0 THEN
    RAISE EXCEPTION 'recognize_sale requires unit_price > 0';
  END IF;

  v_cur := COALESCE(p_currency, v_hdr.currency);

  SELECT COALESCE(MAX(line_no), 0) + 1 INTO v_line_no
  FROM public.consignment_entry_lines
  WHERE consignment_entry_id = p_entry_id;

  PERFORM set_config('gtr.consignment_rpc', 'on', true);

  INSERT INTO public.consignment_entry_lines (
    consignment_entry_id, line_no, stock_item_id, uom_id, qty,
    unit_cost, unit_price, currency
  )
  VALUES (
    p_entry_id, v_line_no, p_stock_item_id, p_uom_id, p_qty,
    COALESCE(p_unit_cost, 0), COALESCE(p_unit_price, 0), v_cur
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


--
-- Name: add_customer_cart_line(uuid, uuid, uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_customer_cart_line(p_cart_id uuid, p_stock_item_id uuid, p_uom_id uuid, p_qty numeric) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id UUID;
BEGIN
  PERFORM public._storefront_rpc_enter();
  BEGIN
    PERFORM public._assert_customer_owns_open_cart(p_cart_id);
    v_id := public.add_cart_line(p_cart_id, p_stock_item_id, p_uom_id, p_qty);
  EXCEPTION
    WHEN OTHERS THEN
      PERFORM public._storefront_rpc_exit();
      RAISE;
  END;
  PERFORM public._storefront_rpc_exit();
  RETURN v_id;
END;
$$;


--
-- Name: add_customer_compare_item(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_customer_compare_item(p_stock_item_id uuid DEFAULT NULL::uuid, p_oem_part_number text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cust UUID := public._current_customer_id();
  v_item UUID;
  v_id UUID;
  v_count INT;
BEGIN
  IF v_cust IS NULL THEN
    RAISE EXCEPTION 'customer profile required';
  END IF;

  v_item := public._resolve_customer_stock_item(p_stock_item_id, p_oem_part_number);

  SELECT count(*)::int INTO v_count
  FROM public.customer_compare_items
  WHERE customer_id = v_cust;

  IF NOT EXISTS (
    SELECT 1 FROM public.customer_compare_items
    WHERE customer_id = v_cust AND stock_item_id = v_item
  ) AND v_count >= public._customer_compare_max_items() THEN
    RAISE EXCEPTION 'compare list is full (max % items)', public._customer_compare_max_items();
  END IF;

  INSERT INTO public.customer_compare_items (customer_id, stock_item_id)
  VALUES (v_cust, v_item)
  ON CONFLICT (customer_id, stock_item_id) DO UPDATE
    SET created_at = public.customer_compare_items.created_at
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


--
-- Name: add_customer_product_review_photo(uuid, text, smallint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_customer_product_review_photo(p_review_id uuid, p_storage_path text, p_sort_order smallint DEFAULT 0) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cust UUID := public._current_customer_id();
  v_id UUID;
  v_path TEXT := NULLIF(trim(COALESCE(p_storage_path, '')), '');
  v_count INT;
BEGIN
  IF v_cust IS NULL THEN
    RAISE EXCEPTION 'customer profile required';
  END IF;
  IF p_review_id IS NULL OR v_path IS NULL THEN
    RAISE EXCEPTION 'review_id and storage_path required';
  END IF;
  IF v_path NOT LIKE (p_review_id::text || '/%') THEN
    RAISE EXCEPTION 'storage_path must start with review_id/';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.customer_product_reviews
    WHERE id = p_review_id
      AND customer_id = v_cust
      AND status = 'pending'
  ) THEN
    RAISE EXCEPTION 'pending review not found for customer';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM storage.objects o
    WHERE o.bucket_id = 'review-photos'
      AND o.name = v_path
  ) THEN
    RAISE EXCEPTION
      'review photo object missing in review-photos bucket at %', v_path;
  END IF;

  SELECT count(*)::int INTO v_count
  FROM public.customer_product_review_photos
  WHERE review_id = p_review_id;
  IF v_count >= 5 THEN
    RAISE EXCEPTION 'max 5 photos per review';
  END IF;

  INSERT INTO public.customer_product_review_photos (review_id, storage_path, sort_order)
  VALUES (p_review_id, v_path, COALESCE(p_sort_order, 0))
  ON CONFLICT (review_id, storage_path) DO UPDATE
    SET sort_order = EXCLUDED.sort_order
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


--
-- Name: FUNCTION add_customer_product_review_photo(p_review_id uuid, p_storage_path text, p_sort_order smallint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.add_customer_product_review_photo(p_review_id uuid, p_storage_path text, p_sort_order smallint) IS 'Attaches review photo metadata after Storage upload; requires storage.objects row in private review-photos bucket at storage_path.';


--
-- Name: add_customer_wishlist_item(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_customer_wishlist_item(p_stock_item_id uuid DEFAULT NULL::uuid, p_oem_part_number text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cust UUID := public._current_customer_id();
  v_item UUID;
  v_id UUID;
BEGIN
  IF v_cust IS NULL THEN
    RAISE EXCEPTION 'customer profile required';
  END IF;

  v_item := public._resolve_customer_stock_item(p_stock_item_id, p_oem_part_number);

  INSERT INTO public.customer_wishlist_items (customer_id, stock_item_id)
  VALUES (v_cust, v_item)
  ON CONFLICT (customer_id, stock_item_id) DO UPDATE
    SET created_at = public.customer_wishlist_items.created_at
