--
-- Name: add_kit_component(uuid, uuid, numeric, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_kit_component(p_kit_id uuid, p_component_item_id uuid, p_qty numeric, p_uom_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE v_id UUID; BEGIN PERFORM public._require_kit_staff(); IF p_qty IS NULL OR p_qty<=0 THEN RAISE EXCEPTION 'component qty must be > 0'; END IF; IF NOT EXISTS(SELECT 1 FROM public.item_kits WHERE id=p_kit_id) THEN RAISE EXCEPTION 'kit not found: %',p_kit_id; END IF; IF NOT EXISTS(SELECT 1 FROM public.stock_items WHERE id=p_component_item_id) THEN RAISE EXCEPTION 'component stock item not found: %',p_component_item_id; END IF; IF NOT EXISTS(SELECT 1 FROM public.uoms WHERE id=p_uom_id) THEN RAISE EXCEPTION 'uom not found: %',p_uom_id; END IF; INSERT INTO public.item_kit_components(kit_id,component_item_id,qty,uom_id) VALUES(p_kit_id,p_component_item_id,p_qty,p_uom_id) ON CONFLICT(kit_id,component_item_id) DO UPDATE SET qty=EXCLUDED.qty,uom_id=EXCLUDED.uom_id RETURNING id INTO v_id; RETURN v_id; END; $$;


--
-- Name: add_payroll_deduction(uuid, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_payroll_deduction(p_payroll_line_id uuid, p_label text, p_amount numeric) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_line public.payroll_lines%ROWTYPE;
  v_run public.payroll_runs%ROWTYPE;
  v_id UUID;
  v_ded NUMERIC;
BEGIN
  PERFORM public._payroll_begin_rpc();
  PERFORM public._require_hr_staff();

  IF p_label IS NULL OR length(trim(p_label)) = 0 THEN
    RAISE EXCEPTION 'deduction label required';
  END IF;
  -- Reject labels that imply statutory tax calc / authority remittance
  IF lower(p_label) ~ '(paye|nssa|pobs|apwcs|zimdef|statutory|tax.?bracket|p4a?|\ytax\y|zimra|fiscal)' THEN
    RAISE EXCEPTION 'statutory/tax deduction labels are not allowed; use manual labels only';
  END IF;
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION 'deduction amount must be > 0';
  END IF;

  SELECT * INTO v_line FROM public.payroll_lines WHERE id = p_payroll_line_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'payroll line not found: %', p_payroll_line_id;
  END IF;

  SELECT * INTO v_run FROM public.payroll_runs WHERE id = v_line.payroll_run_id FOR UPDATE;
  IF v_run.status <> 'draft' THEN
    RAISE EXCEPTION 'deductions only allowed on draft payroll runs';
  END IF;

  INSERT INTO public.payroll_deduction_lines (
    payroll_line_id, label, amount, currency
  )
  VALUES (
    p_payroll_line_id, trim(p_label), p_amount, v_line.currency
  )
  RETURNING id INTO v_id;

  SELECT COALESCE(SUM(amount), 0) INTO v_ded
  FROM public.payroll_deduction_lines
  WHERE payroll_line_id = p_payroll_line_id;

  IF v_ded > v_line.gross_amount THEN
    RAISE EXCEPTION 'deductions (%) exceed gross (%)', v_ded, v_line.gross_amount;
  END IF;

  UPDATE public.payroll_lines
  SET deductions_amount = v_ded,
      net_amount = gross_amount - v_ded
  WHERE id = p_payroll_line_id;

  PERFORM public._refresh_payroll_run_totals(v_line.payroll_run_id);
  RETURN v_id;
END;
$$;


--
-- Name: add_pos_split_payment_leg(uuid, public.payment_tender, numeric, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_pos_split_payment_leg(p_session_id uuid, p_tender public.payment_tender, p_amount numeric, p_request_id uuid, p_external_reference text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE s public.pos_split_payment_sessions%ROWTYPE; o public.commerce_orders%ROWTYPE; l public.pos_split_payment_legs%ROWTYPE;
 v_available NUMERIC; v_seq INTEGER; v_pe UUID; v_balance NUMERIC; v_held NUMERIC;
BEGIN
 PERFORM public._require_payments_staff();
 SELECT * INTO l FROM public.pos_split_payment_legs WHERE request_id=p_request_id;
 IF FOUND THEN RETURN jsonb_build_object('leg_id',l.id,'session',private.pos_split_payment_payload(l.session_id)); END IF;
 PERFORM private.refresh_pos_split_payment_session(p_session_id);
 SELECT * INTO s FROM public.pos_split_payment_sessions WHERE id=p_session_id FOR UPDATE;
 IF s.status IN('settled','refund_review','refund_pending','refunded','cancelled','finalizing') THEN RAISE EXCEPTION 'split session does not accept new payments in status %',s.status; END IF;
 IF EXISTS(SELECT 1 FROM public.pos_split_payment_legs WHERE session_id=s.id AND status IN('pending','unknown')) THEN
  RAISE EXCEPTION 'reconcile the in-flight payment before starting another tender'; END IF;
 v_available:=round(s.total_amount-s.captured_amount-s.held_amount-s.pending_amount,2);
 IF COALESCE(p_amount,0)<=0 OR p_amount>v_available+0.01 THEN RAISE EXCEPTION 'split leg amount must be > 0 and <= available balance %',v_available; END IF;
 SELECT * INTO o FROM public.commerce_orders WHERE id=s.commerce_order_id FOR UPDATE;
 v_seq:=COALESCE((SELECT max(sequence_no) FROM public.pos_split_payment_legs WHERE session_id=s.id),0)+1;
 IF p_tender='bank' AND trim(COALESCE(p_external_reference,''))='' THEN RAISE EXCEPTION 'bank split payment requires a transfer/reference number'; END IF;
 INSERT INTO public.pos_split_payment_legs(session_id,request_id,sequence_no,tender,requested_amount,status,external_reference,created_by)
 VALUES(s.id,p_request_id,v_seq,p_tender,round(p_amount,2),CASE WHEN p_tender='store_credit' THEN 'held'::public.pos_split_payment_leg_status
  WHEN p_tender IN('cash','bank') THEN 'planned'::public.pos_split_payment_leg_status ELSE 'planned'::public.pos_split_payment_leg_status END,
  NULLIF(trim(COALESCE(p_external_reference,'')),''),auth.uid()) RETURNING * INTO l;
 IF p_tender='store_credit' THEN
  SELECT COALESCE(a.balance,0) INTO v_balance FROM public.store_credit_accounts a WHERE a.customer_id=o.customer_id AND a.currency=o.currency FOR UPDATE;
  SELECT COALESCE(SUM(x.requested_amount),0) INTO v_held FROM public.pos_split_payment_legs x JOIN public.pos_split_payment_sessions xs ON xs.id=x.session_id
   WHERE x.status='held' AND x.id<>l.id AND xs.currency=o.currency AND EXISTS(SELECT 1 FROM public.commerce_orders xo WHERE xo.id=xs.commerce_order_id AND xo.customer_id=o.customer_id);
  IF v_balance-v_held+0.001<l.requested_amount THEN RAISE EXCEPTION 'insufficient available store credit after active POS holds'; END IF;
  UPDATE public.pos_split_payment_legs SET locked_at=now() WHERE id=l.id;
 ELSIF p_tender IN('cash','bank') THEN
  v_pe:=public.create_payment_entry(o.customer_id,p_tender,l.requested_amount,o.currency,o.exchange_rate_applied,
    concat_ws(' · ','POS split '||p_tender::text||' '||s.id::text,l.external_reference));
  PERFORM private.post_pos_split_unapplied_payment_entry(v_pe,l.id);
  UPDATE public.pos_split_payment_legs SET status='captured',payment_entry_id=v_pe,locked_at=now(),provider_ref=l.external_reference,updated_at=now() WHERE id=l.id;
 END IF;
 PERFORM private.refresh_pos_split_payment_session(s.id);
 IF (SELECT status FROM public.pos_split_payment_sessions WHERE id=s.id)='fully_committed' THEN PERFORM private.finalize_pos_split_payment_session(s.id); END IF;
 RETURN jsonb_build_object('leg_id',l.id,'session',private.pos_split_payment_payload(s.id));
END $$;


--
-- Name: allocate_payment(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.allocate_payment(p_payment_entry_id uuid, p_allocations jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_pe public.payment_entries%ROWTYPE;
  v_elem JSONB;
  v_inv public.sales_invoices%ROWTYPE;
  v_amt NUMERIC;
  v_sum NUMERIC := 0;
  v_open NUMERIC;
  v_draft_other NUMERIC;
BEGIN
  PERFORM public._require_payments_staff();
  PERFORM public._payments_rpc_enter();

  SELECT * INTO v_pe FROM public.payment_entries WHERE id = p_payment_entry_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'payment entry not found: %', p_payment_entry_id;
  END IF;
  IF v_pe.status <> 'draft' THEN
    RAISE EXCEPTION 'only draft payments can be allocated';
  END IF;

  IF p_allocations IS NULL OR jsonb_typeof(p_allocations) <> 'array'
     OR jsonb_array_length(p_allocations) = 0 THEN
    RAISE EXCEPTION 'allocations array required';
  END IF;

  DELETE FROM public.payment_allocations WHERE payment_entry_id = p_payment_entry_id;

  FOR v_elem IN SELECT * FROM jsonb_array_elements(p_allocations)
  LOOP
    v_amt := (v_elem ->> 'amount')::numeric;
    IF v_amt IS NULL OR v_amt <= 0 THEN
      RAISE EXCEPTION 'allocation amount must be > 0';
    END IF;

    SELECT * INTO v_inv
    FROM public.sales_invoices
    WHERE id = (v_elem ->> 'sales_invoice_id')::uuid
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'invoice not found';
    END IF;
    IF v_inv.status <> 'posted' OR v_inv.doc_type <> 'invoice' THEN
      RAISE EXCEPTION 'only posted sales invoices can be allocated';
    END IF;
    IF v_inv.customer_id IS DISTINCT FROM v_pe.customer_id THEN
      RAISE EXCEPTION 'invoice customer mismatch';
    END IF;
    IF v_inv.currency <> v_pe.currency THEN
      RAISE EXCEPTION 'allocation currency must match payment (invoice %, payment %)',
        v_inv.currency, v_pe.currency;
    END IF;

    SELECT COALESCE(SUM(pa.amount), 0) INTO v_draft_other
    FROM public.payment_allocations pa
    JOIN public.payment_entries pe ON pe.id = pa.payment_entry_id
    WHERE pa.sales_invoice_id = v_inv.id
      AND pe.status = 'draft'
      AND pe.id <> p_payment_entry_id;

    v_open := v_inv.total - v_inv.amount_paid - v_draft_other;

    IF v_amt > v_open + 0.001 THEN
      RAISE EXCEPTION 'over-allocate denied: invoice % open % allocate %',
        v_inv.document_number, v_open, v_amt;
    END IF;

    INSERT INTO public.payment_allocations (
      payment_entry_id, sales_invoice_id, amount, currency, exchange_rate_applied
    )
    VALUES (
      p_payment_entry_id,
      v_inv.id,
      v_amt,
      v_pe.currency,
      COALESCE((v_elem ->> 'exchange_rate_applied')::numeric, v_pe.exchange_rate_applied)
    );

    v_sum := v_sum + v_amt;
  END LOOP;

  IF v_sum > v_pe.amount + 0.001 THEN
    RAISE EXCEPTION 'allocations % exceed payment amount %', v_sum, v_pe.amount;
  END IF;

  UPDATE public.payment_entries SET updated_at = now() WHERE id = p_payment_entry_id;
  RETURN p_payment_entry_id;
END;
$$;


--
-- Name: apply_hr_onboarding_staff_role(uuid, public.staff_role); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_hr_onboarding_staff_role(p_user_id uuid, p_role public.staff_role) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF p_user_id IS NULL OR p_role IS NULL THEN
    RAISE EXCEPTION 'user_id and role required';
  END IF;

  IF auth.role() IS DISTINCT FROM 'service_role'
     AND NOT public.has_staff_role(ARRAY['admin', 'hr']::public.staff_role[]) THEN
    RAISE EXCEPTION 'hr or admin role required to apply onboarding staff role';
  END IF;

  IF p_role = 'admin'::public.staff_role
     AND auth.role() IS DISTINCT FROM 'service_role'
     AND NOT public.has_staff_role(ARRAY['admin']::public.staff_role[]) THEN
    RAISE EXCEPTION 'admin staff_role requires an admin caller';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = p_user_id) THEN
    RAISE EXCEPTION 'profile not found: %', p_user_id;
  END IF;

  INSERT INTO public.staff_roles (user_id, role)
  VALUES (p_user_id, p_role)
  ON CONFLICT (user_id, role) DO NOTHING;
END;
$$;


--
-- Name: apply_pos_cart_discount(uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_pos_cart_discount(p_cart_id uuid, p_discount_percent numeric, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cart public.pos_carts%ROWTYPE;
  v_before JSONB;
  v_after JSONB;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not authenticated';
  END IF;
  IF NOT public.is_pos_approver() THEN
    RAISE EXCEPTION 'admin or shop manager approval required';
  END IF;
  IF p_discount_percent IS NULL
     OR p_discount_percent < 0
     OR p_discount_percent > 100 THEN
    RAISE EXCEPTION 'discount percent must be between 0 and 100';
  END IF;

  PERFORM public._require_cart_mutate(p_cart_id);
  SELECT * INTO v_cart FROM public.pos_carts WHERE id = p_cart_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'cart not found: %', p_cart_id;
  END IF;
  IF v_cart.status <> 'open' THEN
    RAISE EXCEPTION 'only open carts can be discounted (got %)', v_cart.status;
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', l.id,
    'unit_price', l.unit_price,
    'line_total', l.line_total,
    'is_core_charge', l.is_core_charge
  )), '[]'::jsonb)
  INTO v_before
  FROM public.pos_cart_lines l
  WHERE l.cart_id = p_cart_id;

  UPDATE public.pos_cart_lines l
  SET
    unit_price = round(l.unit_price * (1 - p_discount_percent / 100.0), 4),
    line_total = round(
      round(l.unit_price * (1 - p_discount_percent / 100.0), 4) * l.qty,
      2
    )
  WHERE l.cart_id = p_cart_id
    AND l.is_core_charge = false;

  UPDATE public.pos_carts SET updated_at = now() WHERE id = p_cart_id;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', l.id,
    'unit_price', l.unit_price,
    'line_total', l.line_total,
    'is_core_charge', l.is_core_charge
  )), '[]'::jsonb)
  INTO v_after
  FROM public.pos_cart_lines l
  WHERE l.cart_id = p_cart_id;

  PERFORM public._log_pos_action(
    'discount_applied',
    'pos_carts',
    p_cart_id,
    v_before,
    v_after || jsonb_build_object('discount_percent', p_discount_percent),
    p_notes
  );

  RETURN p_cart_id;
END;
$$;


--
-- Name: apply_pos_cart_discount_governed(uuid, numeric, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_pos_cart_discount_governed(p_cart_id uuid, p_discount_percent numeric, p_reason_code text, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE c public.pos_carts%ROWTYPE; v_before JSONB; v_after JSONB; v_audit UUID;
BEGIN
 PERFORM public._require_sales_staff(); PERFORM private.require_pos_reason('discount_percent',p_reason_code);
 IF p_discount_percent IS NULL OR p_discount_percent<0 OR p_discount_percent>100 THEN RAISE EXCEPTION 'discount percent must be between 0 and 100'; END IF;
 IF public.pos_action_requires_manager('discount_percent',p_discount_percent) AND NOT public.is_pos_approver() THEN RAISE EXCEPTION 'POS manager approval required'; END IF;
 PERFORM public._require_cart_mutate(p_cart_id); SELECT * INTO c FROM public.pos_carts WHERE id=p_cart_id FOR UPDATE;
 IF NOT FOUND OR c.status<>'open' THEN RAISE EXCEPTION 'open cart required'; END IF;
 SELECT COALESCE(jsonb_agg(jsonb_build_object('id',id,'unit_price',unit_price,'line_total',line_total,'is_core_charge',is_core_charge)),'[]'::jsonb) INTO v_before FROM public.pos_cart_lines WHERE cart_id=p_cart_id;
 UPDATE public.pos_cart_lines SET unit_price=round(unit_price*(1-p_discount_percent/100.0),4),line_total=round(round(unit_price*(1-p_discount_percent/100.0),4)*qty,2)
  WHERE cart_id=p_cart_id AND NOT is_core_charge;
 UPDATE public.pos_carts SET updated_at=now() WHERE id=p_cart_id;
 SELECT COALESCE(jsonb_agg(jsonb_build_object('id',id,'unit_price',unit_price,'line_total',line_total,'is_core_charge',is_core_charge)),'[]'::jsonb) INTO v_after FROM public.pos_cart_lines WHERE cart_id=p_cart_id;
 v_audit:=public._log_pos_action('discount_applied','pos_carts',p_cart_id,v_before,v_after||jsonb_build_object('discount_percent',p_discount_percent),concat_ws(' · ',p_reason_code,p_notes));
 UPDATE public.pos_action_audit SET reason_code=p_reason_code,approved_by_user_id=CASE WHEN public.is_pos_approver() THEN auth.uid() ELSE NULL END,approval_policy_action='discount_percent' WHERE id=v_audit;
 RETURN p_cart_id;
END $$;


--
-- Name: apply_pos_line_price_override(uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_pos_line_price_override(p_line_id uuid, p_unit_price numeric, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_line public.pos_cart_lines%ROWTYPE;
  v_cart public.pos_carts%ROWTYPE;
  v_before JSONB;
  v_after JSONB;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not authenticated';
  END IF;
  IF NOT public.is_pos_approver() THEN
    RAISE EXCEPTION 'admin or shop manager approval required';
  END IF;
  IF p_unit_price IS NULL OR p_unit_price < 0 THEN
    RAISE EXCEPTION 'unit price must be >= 0';
  END IF;

  SELECT * INTO v_line FROM public.pos_cart_lines WHERE id = p_line_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'line not found: %', p_line_id;
  END IF;
  IF v_line.is_core_charge THEN
    RAISE EXCEPTION 'cannot override core-charge lines';
  END IF;

  SELECT * INTO v_cart FROM public.pos_carts WHERE id = v_line.cart_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'cart not found';
  END IF;
  IF v_cart.status <> 'open' THEN
    RAISE EXCEPTION 'only open carts support price override (got %)', v_cart.status;
  END IF;

  PERFORM public._require_cart_mutate(v_line.cart_id);

  v_before := jsonb_build_object(
    'id', v_line.id,
    'unit_price', v_line.unit_price,
    'line_total', v_line.line_total,
    'qty', v_line.qty
  );

  UPDATE public.pos_cart_lines
  SET
    unit_price = round(p_unit_price, 4),
    line_total = round(round(p_unit_price, 4) * qty, 2)
  WHERE id = p_line_id
  RETURNING * INTO v_line;

  v_after := jsonb_build_object(
    'id', v_line.id,
    'unit_price', v_line.unit_price,
    'line_total', v_line.line_total,
    'qty', v_line.qty
  );

  RETURN public._log_pos_action(
    'price_override',
    'pos_cart_line',
    p_line_id,
    v_before,
    v_after,
    p_notes
  );
END;
$$;


--
-- Name: FUNCTION apply_pos_line_price_override(p_line_id uuid, p_unit_price numeric, p_notes text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.apply_pos_line_price_override(p_line_id uuid, p_unit_price numeric, p_notes text) IS 'Admin|shop-manager unit price override on open non-core POS line; audited.';


--
-- Name: apply_pos_line_price_override_governed(uuid, numeric, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_pos_line_price_override_governed(p_line_id uuid, p_unit_price numeric, p_reason_code text, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE l public.pos_cart_lines%ROWTYPE; c public.pos_carts%ROWTYPE; v_delta NUMERIC; v_before JSONB; v_after JSONB; v_audit UUID;
BEGIN
 PERFORM public._require_sales_staff(); PERFORM private.require_pos_reason('price_override_delta_percent',p_reason_code);
 IF p_unit_price IS NULL OR p_unit_price<0 THEN RAISE EXCEPTION 'unit price must be >= 0'; END IF;
 SELECT * INTO l FROM public.pos_cart_lines WHERE id=p_line_id FOR UPDATE; IF NOT FOUND OR l.is_core_charge THEN RAISE EXCEPTION 'non-core cart line required'; END IF;
 v_delta:=CASE WHEN l.unit_price=0 THEN CASE WHEN p_unit_price=0 THEN 0 ELSE 100 END ELSE abs(p_unit_price-l.unit_price)/l.unit_price*100 END;
 IF public.pos_action_requires_manager('price_override_delta_percent',v_delta) AND NOT public.is_pos_approver() THEN RAISE EXCEPTION 'POS manager approval required'; END IF;
 SELECT * INTO c FROM public.pos_carts WHERE id=l.cart_id FOR UPDATE; IF NOT FOUND OR c.status<>'open' THEN RAISE EXCEPTION 'open cart required'; END IF;
 PERFORM public._require_cart_mutate(c.id); v_before:=jsonb_build_object('id',l.id,'unit_price',l.unit_price,'line_total',l.line_total,'qty',l.qty);
 UPDATE public.pos_cart_lines SET unit_price=round(p_unit_price,4),line_total=round(round(p_unit_price,4)*qty,2) WHERE id=p_line_id RETURNING * INTO l;
 v_after:=jsonb_build_object('id',l.id,'unit_price',l.unit_price,'line_total',l.line_total,'qty',l.qty,'delta_percent',v_delta);
 v_audit:=public._log_pos_action('price_override','pos_cart_line',p_line_id,v_before,v_after,concat_ws(' · ',p_reason_code,p_notes));
 UPDATE public.pos_action_audit SET reason_code=p_reason_code,approved_by_user_id=CASE WHEN public.is_pos_approver() THEN auth.uid() ELSE NULL END,approval_policy_action='price_override_delta_percent' WHERE id=v_audit;
 RETURN p_line_id;
END $$;


--
-- Name: approve_driver_cash_variance(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_driver_cash_variance(p_handin_id uuid, p_reason_code text, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE h public.driver_cash_handins%ROWTYPE; v_j uuid; v_owed numeric := 0; v_amt numeric;
BEGIN
 IF NOT public.is_pos_approver() THEN RAISE EXCEPTION 'POS manager approval required'; END IF;
 SELECT * INTO h FROM public.driver_cash_handins WHERE id=p_handin_id FOR UPDATE;
 IF NOT FOUND OR h.status<>'variance_pending' THEN RAISE EXCEPTION 'hand-in with a difference to review required'; END IF;
 IF h.received_by=auth.uid() THEN RAISE EXCEPTION 'a different manager must approve a difference you counted'; END IF;
 IF h.driver_user_id=auth.uid() THEN RAISE EXCEPTION 'you cannot approve your own hand-in'; END IF;
 IF trim(COALESCE(p_reason_code,''))='' THEN RAISE EXCEPTION 'reason required'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.pos_approval_reason_codes WHERE action='driver_cash_variance' AND code=p_reason_code AND is_active) THEN
  RAISE EXCEPTION 'unknown reason %', p_reason_code; END IF;
 v_amt := abs(h.variance);
 IF h.variance < 0 AND p_reason_code IN ('driver_short','investigation') THEN
  v_j := private._driver_cash_journal(h, '1250', '1120', v_amt, 'short, owed by the driver');
  v_owed := v_amt;
 ELSIF h.variance < 0 THEN
  v_j := private._driver_cash_journal(h, '5310', '1120', v_amt, 'short (' || p_reason_code || ')');
 ELSE
  v_j := private._driver_cash_journal(h, '1120', '5310', v_amt, 'over (' || p_reason_code || ')');
 END IF;
 UPDATE public.driver_cash_handins SET status='approved', reason_code=p_reason_code, approver_notes=NULLIF(trim(COALESCE(p_notes,'')),''),
  approved_by=auth.uid(), approved_at=now(), journal_entry_id=v_j, owed_amount=v_owed
 WHERE id=h.id RETURNING * INTO h;
 RETURN private._driver_cash_handin_json(h);
END $$;


--
-- Name: approve_finance_requisition(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_finance_requisition(p_requisition_id uuid, p_note text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE v_row public.finance_requisitions%ROWTYPE; v_uid UUID:=auth.uid(); v_new_count INT; v_final BOOLEAN:=false; BEGIN IF v_uid IS NULL AND auth.role()<>'service_role' THEN RAISE EXCEPTION 'not authenticated'; END IF; IF auth.role()='service_role' AND v_uid IS NULL THEN v_uid:='a0000000-0000-4000-8000-000000000002'::uuid; END IF; SELECT * INTO v_row FROM public.finance_requisitions WHERE id=p_requisition_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'requisition not found: %',p_requisition_id; END IF; IF v_row.status<>'submitted' THEN RAISE EXCEPTION 'only submitted requisitions can be approved (status=%)',v_row.status; END IF; IF NOT public._finance_req_can_approve(v_row) THEN RAISE EXCEPTION 'not allowed to approve (need finance/admin or organogram reporting line)'; END IF; IF EXISTS(SELECT 1 FROM public.finance_requisition_approvals WHERE requisition_id=p_requisition_id AND approver_user_id=v_uid) THEN RAISE EXCEPTION 'already approved by this user'; END IF; PERFORM public._finance_req_rpc_enter(); INSERT INTO public.finance_requisition_approvals(requisition_id,approver_user_id,note) VALUES(p_requisition_id,v_uid,nullif(trim(p_note),'')); v_new_count:=COALESCE(v_row.approval_count,0)+1; v_final:=v_new_count>=COALESCE(v_row.required_approvals,1); UPDATE public.finance_requisitions SET approval_count=v_new_count,status=CASE WHEN v_final THEN 'approved'::public.finance_requisition_status ELSE status END,approved_by=CASE WHEN v_final THEN v_uid ELSE approved_by END,approved_at=CASE WHEN v_final THEN now() ELSE approved_at END,updated_at=now() WHERE id=p_requisition_id; INSERT INTO public.finance_audit_log(actor_user_id,action,entity_type,entity_id,before_state,after_state) VALUES(v_uid,CASE WHEN v_final THEN 'requisition_approved' ELSE 'requisition_approval_partial' END,'finance_requisitions',p_requisition_id,jsonb_build_object('status',v_row.status,'approval_count',v_row.approval_count,'required_approvals',v_row.required_approvals),jsonb_build_object('status',CASE WHEN v_final THEN 'approved' ELSE 'submitted' END,'approval_count',v_new_count,'required_approvals',v_row.required_approvals,'final',v_final)); IF v_final AND v_row.req_type IN('petty_cash'::public.finance_requisition_type,'petty_float'::public.finance_requisition_type) THEN PERFORM public.disburse_finance_requisition(p_requisition_id,COALESCE(v_row.intended_entry_date,CURRENT_DATE)); END IF; RETURN p_requisition_id; END; $$;


--
-- Name: approve_material_request(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_material_request(p_material_request_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_st public.procurement_doc_status;
BEGIN
  PERFORM public._procurement_begin_rpc();
  PERFORM public._require_procurement_finance();
  PERFORM public._assert_procurement_period_open();

  SELECT status INTO v_st
  FROM public.material_requests
  WHERE id = p_material_request_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'material request not found: %', p_material_request_id;
  END IF;
  IF v_st <> 'submitted' THEN
    RAISE EXCEPTION 'only submitted material requests can be approved (status=%)', v_st;
  END IF;

  UPDATE public.material_requests
  SET
    status = 'approved',
    approved_by = auth.uid(),
    approved_at = now(),
    rejected_by = NULL,
    rejected_at = NULL,
    rejection_reason = NULL,
    updated_at = now()
  WHERE id = p_material_request_id;

  PERFORM public._procurement_end_rpc();
  RETURN p_material_request_id;
EXCEPTION
  WHEN OTHERS THEN
    PERFORM public._procurement_end_rpc();
    RAISE;
END;
$$;


--
-- Name: approve_pos_fulfillment_request(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_pos_fulfillment_request(p_request_id uuid, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE r public.pos_fulfillment_requests%ROWTYPE; v_entry UUID;
BEGIN
 PERFORM public._require_warehouse_staff(); SELECT * INTO r FROM public.pos_fulfillment_requests WHERE id=p_request_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'fulfillment request not found'; END IF;
 IF r.kind<>'branch_transfer' OR r.status<>'reserved' THEN RAISE EXCEPTION 'reserved branch-transfer request required'; END IF;
 UPDATE public.inventory_reservations SET state='released',released_at=now() WHERE pos_fulfillment_request_id=p_request_id AND state='active';
 IF public.get_inventory_available_quantity(r.stock_item_id,r.source_warehouse_id)<public.convert_to_base_uom(r.stock_item_id,r.uom_id,r.qty) THEN RAISE EXCEPTION 'source availability no longer supports request'; END IF;
 v_entry:=public.create_stock_transfer(r.source_warehouse_id,r.destination_warehouse_id,
  concat_ws(' · ',r.document_number,r.notes,p_notes),jsonb_build_array(jsonb_build_object('stock_item_id',r.stock_item_id,'uom_id',r.uom_id,'qty',r.qty,'valuation_method','FIFO')));
 UPDATE public.pos_fulfillment_requests SET status='awaiting_transfer_approval',stock_entry_id=v_entry,approved_by=auth.uid(),updated_at=now() WHERE id=p_request_id;
 RETURN v_entry;
END $$;


--
-- Name: approve_pos_split_refund(uuid, text, numeric, numeric, numeric, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_pos_split_refund(p_refund_id uuid, p_fee_policy text, p_estimated_provider_fee numeric DEFAULT 0, p_estimated_transfer_fee numeric DEFAULT 0, p_customer_fee numeric DEFAULT 0, p_expected_days integer DEFAULT 3, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE r public.pos_split_refund_requests%ROWTYPE; l public.pos_split_payment_legs%ROWTYPE;
BEGIN
 IF NOT (public.is_pos_approver() OR public.has_staff_role(ARRAY['finance']::public.staff_role[])) THEN RAISE EXCEPTION 'manager or finance approval required'; END IF;
 IF p_fee_policy NOT IN('business_absorbs','customer_bears','manual_review') THEN RAISE EXCEPTION 'unsupported refund fee policy'; END IF;
 SELECT * INTO r FROM public.pos_split_refund_requests WHERE id=p_refund_id FOR UPDATE; IF NOT FOUND OR r.status NOT IN('review','failed') THEN RAISE EXCEPTION 'review/failed refund request required'; END IF;
 SELECT * INTO l FROM public.pos_split_payment_legs WHERE id=r.leg_id FOR UPDATE;
 IF COALESCE(p_estimated_provider_fee,0)<0 OR COALESCE(p_estimated_transfer_fee,0)<0 OR COALESCE(p_customer_fee,0)<0 OR p_customer_fee>r.gross_amount THEN RAISE EXCEPTION 'invalid refund fee values'; END IF;
 IF p_customer_fee>0 AND p_fee_policy<>'customer_bears' THEN RAISE EXCEPTION 'customer fee deduction requires customer_bears policy'; END IF;
 UPDATE public.pos_split_refund_requests SET status='pending',fee_policy=p_fee_policy,estimated_provider_fee=round(COALESCE(p_estimated_provider_fee,0),2),
  estimated_transfer_fee=round(COALESCE(p_estimated_transfer_fee,0),2),approved_customer_fee=round(COALESCE(p_customer_fee,0),2),
  expected_settlement_at=now()+make_interval(days=>GREATEST(COALESCE(p_expected_days,3),0)),approved_by=auth.uid(),approved_at=now(),notes=concat_ws(E'\n',notes,p_notes),updated_at=now()
 WHERE id=r.id;
 UPDATE public.pos_split_payment_legs SET status='refund_pending',updated_at=now() WHERE id=l.id;
 UPDATE public.pos_split_payment_sessions SET status='refund_pending',updated_at=now() WHERE id=r.session_id;
 RETURN private.pos_split_payment_payload(r.session_id);
END $$;


--
-- Name: approve_pos_till_variance(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_pos_till_variance(p_session_id uuid, p_reason_code text, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE s public.pos_till_sessions%ROWTYPE;
BEGIN
 IF NOT public.is_pos_approver() THEN RAISE EXCEPTION 'POS manager approval required'; END IF;
 SELECT * INTO s FROM public.pos_till_sessions WHERE id=p_session_id FOR UPDATE;
 IF NOT FOUND OR s.status<>'variance_pending' THEN RAISE EXCEPTION 'variance-pending till session required'; END IF;
 IF trim(COALESCE(p_reason_code,''))='' THEN RAISE EXCEPTION 'reason_code required'; END IF;
 UPDATE public.pos_till_sessions SET status='closed',approved_by=auth.uid(),approved_at=now(),closed_at=now(),
  variance_reason_code=p_reason_code,close_notes=concat_ws(E'\n',close_notes,p_notes),updated_at=now() WHERE id=p_session_id;
 INSERT INTO public.pos_till_session_events(session_id,event_type,actor_user_id,detail)
 VALUES(p_session_id,'variance_approved',auth.uid(),jsonb_build_object('reason_code',p_reason_code,'notes',p_notes,'variance',s.variance));
 PERFORM public._log_pos_action('till_variance_approved','pos_till_sessions',p_session_id,to_jsonb(s),
  (SELECT to_jsonb(x) FROM public.pos_till_sessions x WHERE x.id=p_session_id),p_notes);
 UPDATE public.pos_action_audit SET reason_code=p_reason_code,approved_by_user_id=auth.uid(),approval_policy_action='till_variance'
 WHERE id=(SELECT id FROM public.pos_action_audit WHERE entity_type='pos_till_sessions' AND entity_id=p_session_id ORDER BY created_at DESC LIMIT 1);
 RETURN p_session_id;
END $$;


--
-- Name: approve_pos_warranty_claim(uuid, public.warranty_claim_resolution, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_pos_warranty_claim(p_claim_id uuid, p_resolution public.warranty_claim_resolution, p_lines jsonb DEFAULT NULL::jsonb, p_replacement_lines jsonb DEFAULT NULL::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE w public.warranty_claims%ROWTYPE; i public.sales_invoices%ROWTYPE; v_lines JSONB; v_uom UUID; v_cn UUID; v_quar UUID; v_repl UUID;
 v_src_lines JSONB:='[]'::jsonb; v_el JSONB; v_line_id UUID;
BEGIN
 IF NOT public.is_pos_approver() THEN RAISE EXCEPTION 'POS manager approval required'; END IF;
 SELECT * INTO w FROM public.warranty_claims WHERE id=p_claim_id FOR UPDATE;
 IF NOT FOUND OR w.status<>'open' THEN RAISE EXCEPTION 'open warranty claim required'; END IF;
 IF p_resolution NOT IN('replacement','credit_note','return_only') THEN RAISE EXCEPTION 'invalid warranty approval resolution'; END IF;
 IF w.sales_invoice_id IS NOT NULL THEN SELECT * INTO i FROM public.sales_invoices WHERE id=w.sales_invoice_id; END IF;
 v_lines:=p_lines;
 IF v_lines IS NULL AND w.stock_item_id IS NOT NULL THEN
  SELECT id INTO v_uom FROM public.uoms WHERE code='EA' ORDER BY created_at LIMIT 1;
  IF v_uom IS NULL THEN RAISE EXCEPTION 'EA UOM required for default warranty return'; END IF;
  v_lines:=jsonb_build_array(jsonb_build_object('stock_item_id',w.stock_item_id,'uom_id',v_uom,'qty',1,'unit_price',0,'currency',COALESCE(i.currency,'USD')));
 END IF;
 IF p_resolution='credit_note' THEN
  IF w.sales_invoice_id IS NULL OR v_lines IS NULL OR jsonb_array_length(v_lines)=0 THEN RAISE EXCEPTION 'credit-note warranty requires source invoice and return lines'; END IF;
  IF i.customer_id IS NULL THEN RAISE EXCEPTION 'credit note requires named customer'; END IF;
  -- Each line is credited at the price it was sold for: by source line, or the invoice line for that item.
  FOR v_el IN SELECT * FROM jsonb_array_elements(v_lines) LOOP
   v_line_id:=NULLIF(v_el->>'source_invoice_line_id','')::uuid;
   IF v_line_id IS NULL THEN
    SELECT sl.id INTO v_line_id FROM public.sales_invoice_lines sl
    WHERE sl.invoice_id=w.sales_invoice_id AND sl.stock_item_id=(v_el->>'stock_item_id')::uuid AND NOT COALESCE(sl.is_core_charge,false)
    ORDER BY sl.created_at,sl.id LIMIT 1;
   END IF;
   IF v_line_id IS NULL THEN RAISE EXCEPTION 'warranty item not on the source invoice'; END IF;
   v_src_lines:=v_src_lines||jsonb_build_array(jsonb_build_object('source_invoice_line_id',v_line_id,'qty',COALESCE((v_el->>'qty')::numeric,1)));
  END LOOP;
  v_cn:=private._post_pos_credit_note(w.sales_invoice_id,v_src_lines,'1200',format('Warranty %s credit note',w.document_number));
 ELSE
  IF v_lines IS NULL OR jsonb_array_length(v_lines)=0 THEN RAISE EXCEPTION 'physical warranty return lines required'; END IF;
  v_quar:=private.receive_external_return_to_quarantine(v_lines,format('Warranty return %s',w.document_number));
 END IF;
 IF p_resolution='replacement' THEN
  IF p_replacement_lines IS NULL OR jsonb_typeof(p_replacement_lines)<>'array' OR jsonb_array_length(p_replacement_lines)=0 THEN RAISE EXCEPTION 'replacement lines required'; END IF;
  v_repl:=private.issue_pos_replacement_stock(COALESCE(i.warehouse_id,(SELECT id FROM public.warehouses WHERE code='MAIN' AND is_active LIMIT 1)),p_replacement_lines,format('Warranty replacement %s',w.document_number));
 END IF;
 IF w.stock_serial_id IS NOT NULL THEN
  UPDATE public.stock_serials SET status='quarantine',warehouse_id=(SELECT id FROM public.warehouses WHERE is_quarantine AND is_active ORDER BY code LIMIT 1) WHERE id=w.stock_serial_id;
 END IF;
 UPDATE public.warranty_claims SET status='approved',resolution=p_resolution,credit_note_id=v_cn,quarantine_stock_entry_id=v_quar,
  replacement_stock_entry_id=v_repl,decided_by=auth.uid(),decided_at=now(),updated_at=now() WHERE id=p_claim_id;
 PERFORM public.emit_domain_event('warranty_claim_approved','warranty:pos-approved:'||p_claim_id::text,
  jsonb_build_object('warranty_claim_id',p_claim_id,'resolution',p_resolution,'credit_note_id',v_cn,'quarantine_stock_entry_id',v_quar,'replacement_stock_entry_id',v_repl));
 PERFORM public._log_pos_action('warranty_approved','warranty_claims',p_claim_id,to_jsonb(w),(SELECT to_jsonb(x) FROM public.warranty_claims x WHERE x.id=p_claim_id),NULL);
 RETURN p_claim_id;
END $$;


--
-- Name: approve_purchase_order(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_purchase_order(p_purchase_order_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_po public.purchase_orders%ROWTYPE; v_total NUMERIC; v_total_minor BIGINT; v_currency public.currency_code; v_release UUID;
BEGIN
 PERFORM public._procurement_begin_rpc(); PERFORM public._require_procurement_finance(); PERFORM public._assert_procurement_period_open();
 SELECT * INTO v_po FROM public.purchase_orders WHERE id=p_purchase_order_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'purchase order not found: %',p_purchase_order_id; END IF;
 IF v_po.status<>'submitted' THEN RAISE EXCEPTION 'only submitted purchase orders can be approved (status=%)',v_po.status; END IF;
 UPDATE public.purchase_orders SET status='approved',approved_by=auth.uid(),approved_at=now(),rejected_by=NULL,rejected_at=NULL,rejection_reason=NULL,progress_step='approved',updated_at=now() WHERE id=p_purchase_order_id;
 v_total:=public._po_quoted_total(p_purchase_order_id); v_total_minor:=public._major_to_minor(v_total); v_currency:=v_po.currency;
 INSERT INTO public.procurement_fund_releases(purchase_order_id,requesting_official_id,approved_by,amount,amount_minor,currency,status,notes)
 VALUES(p_purchase_order_id,v_po.created_by,auth.uid(),v_total,v_total_minor,v_currency,'released',format('Auto fund release on PO approve for official %s',COALESCE(v_po.created_by::text,'unknown')))
 ON CONFLICT(purchase_order_id) DO NOTHING RETURNING id INTO v_release;
 IF v_release IS NULL THEN SELECT id,amount,amount_minor,currency INTO v_release,v_total,v_total_minor,v_currency FROM public.procurement_fund_releases WHERE purchase_order_id=p_purchase_order_id; END IF;
 UPDATE public.purchase_orders SET funds_released_at=now(),progress_step='funds_released',updated_at=now() WHERE id=p_purchase_order_id;
 PERFORM public.emit_domain_event('po_approved','purchase_order_approved:'||p_purchase_order_id::text,jsonb_build_object('purchase_order_id',p_purchase_order_id,'document_number',v_po.document_number,'currency',v_currency,'supplier_id',v_po.supplier_id,'fund_release_id',v_release,'amount',v_total,'amount_minor',v_total_minor,'requesting_official_id',v_po.created_by),auth.uid(),format('GTR Auto: PO %s approved — funds released under requesting official',COALESCE(v_po.document_number,left(p_purchase_order_id::text,8))));
 PERFORM public.emit_domain_event('procurement_funds_released','procurement_fund_release:'||COALESCE(v_release::text,p_purchase_order_id::text),jsonb_build_object('purchase_order_id',p_purchase_order_id,'fund_release_id',v_release,'requesting_official_id',v_po.created_by,'amount',v_total,'amount_minor',v_total_minor,'currency',v_currency),auth.uid(),format('GTR Auto: procurement funds released for PO %s',COALESCE(v_po.document_number,left(p_purchase_order_id::text,8))));
 PERFORM public._procurement_end_rpc(); RETURN p_purchase_order_id;
EXCEPTION WHEN OTHERS THEN PERFORM public._procurement_end_rpc(); RAISE;
END;$$;


--
-- Name: FUNCTION approve_purchase_order(p_purchase_order_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.approve_purchase_order(p_purchase_order_id uuid) IS 'Approve submitted PO; insert-once fund release (ON CONFLICT DO NOTHING — never rewrite amount/amount_minor).';


--
-- Name: approve_stock_reconciliation(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_stock_reconciliation(p_reconciliation_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_recon public.stock_reconciliations%ROWTYPE;
BEGIN
  PERFORM public._recon_begin_rpc();
  PERFORM public._require_warehouse_staff();

  SELECT * INTO v_recon
  FROM public.stock_reconciliations
  WHERE id = p_reconciliation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'reconciliation not found: %', p_reconciliation_id;
  END IF;
  IF v_recon.status <> 'pending_approval' THEN
    RAISE EXCEPTION 'reconciliation not pending approval (status=%)', v_recon.status;
  END IF;
  IF v_recon.first_approver_id IS NULL THEN
    RAISE EXCEPTION 'first approver missing';
  END IF;
  IF auth.uid() IS NOT NULL AND auth.uid() = v_recon.first_approver_id THEN
    RAISE EXCEPTION 'second approver must be a different staff user';
  END IF;

  UPDATE public.stock_reconciliations
  SET
    second_approver_id = auth.uid(),
    second_approved_at = now()
  WHERE id = p_reconciliation_id;

  RETURN public._post_stock_reconciliation(p_reconciliation_id);
END;
$$;


--
-- Name: approve_stock_transfer(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_stock_transfer(p_entry_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_entry public.stock_entries%ROWTYPE;
  v_line RECORD;
  v_cost NUMERIC;
  v_currency public.currency_code;
  v_val public.valuation_method;
  v_batch UUID;
  v_batch_code TEXT;
  v_dest_quar BOOLEAN;
BEGIN
  PERFORM public._require_warehouse_staff();

  SELECT * INTO v_entry FROM public.stock_entries WHERE id = p_entry_id FOR UPDATE;
  IF NOT FOUND OR v_entry.entry_type <> 'transfer' THEN
    RAISE EXCEPTION 'transfer not found';
  END IF;
  IF v_entry.status <> 'pending_approval' THEN
    RAISE EXCEPTION 'transfer not pending approval';
  END IF;
  IF v_entry.first_approver_id IS NULL THEN
    RAISE EXCEPTION 'first approver missing';
  END IF;
  IF auth.uid() IS NOT NULL AND auth.uid() = v_entry.first_approver_id THEN
    RAISE EXCEPTION 'second approver must be a different staff user';
  END IF;

  -- Mutate stock only after second signature
  FOR v_line IN
    SELECT * FROM public.stock_entry_lines WHERE stock_entry_id = p_entry_id
  LOOP
    v_val := v_line.valuation_method;
    SELECT unit_cost, currency INTO v_cost, v_currency
    FROM public.stock_levels
    WHERE stock_item_id = v_line.stock_item_id
      AND warehouse_id = v_entry.from_warehouse_id;

    IF v_val = 'FIFO' THEN
      PERFORM public._consume_fifo_batches(
        v_line.stock_item_id, v_entry.from_warehouse_id, v_line.qty_base
      );
    ELSE
      -- AVG: reduce oldest/any batch qty proportionally from available batches
      PERFORM public._consume_fifo_batches(
        v_line.stock_item_id, v_entry.from_warehouse_id, v_line.qty_base
      );
    END IF;

    PERFORM public._adjust_stock_level(
      v_line.stock_item_id, v_entry.from_warehouse_id, -v_line.qty_base,
      v_val, v_cost, COALESCE(v_currency, 'USD')
    );

    v_batch_code := public.next_series_value('BATCH-');
    INSERT INTO public.stock_batches (
      batch_code, stock_item_id, warehouse_id, valuation_method,
      unit_cost, currency, qty_on_hand
    )
    VALUES (
      v_batch_code, v_line.stock_item_id, v_entry.to_warehouse_id, v_val,
      COALESCE(v_cost, 0), COALESCE(v_currency, 'USD'), v_line.qty_base
    )
    RETURNING id INTO v_batch;

    UPDATE public.stock_entry_lines
    SET stock_batch_id = v_batch
    WHERE id = v_line.id;

    PERFORM public._adjust_stock_level(
      v_line.stock_item_id, v_entry.to_warehouse_id, v_line.qty_base,
      v_val, COALESCE(v_cost, 0), COALESCE(v_currency, 'USD')
    );
  END LOOP;

  UPDATE public.stock_entries
  SET
    status = 'posted',
    second_approver_id = auth.uid(),
    second_approved_at = now(),
    posted_at = now()
  WHERE id = p_entry_id;

  PERFORM public.emit_domain_event(
    'transfer_completed',
    'stock_entry:posted:' || p_entry_id::text,
    jsonb_build_object('stock_entry_id', p_entry_id)
  );

  SELECT is_quarantine INTO v_dest_quar
  FROM public.warehouses WHERE id = v_entry.to_warehouse_id;
  IF v_dest_quar THEN
    PERFORM public.emit_domain_event(
      'quarantine_received',
      'stock_entry:quar:' || p_entry_id::text,
      jsonb_build_object('stock_entry_id', p_entry_id)
    );
  END IF;

  RETURN p_entry_id;
END;
$$;


--
-- Name: approve_warranty_claim(uuid, public.warranty_claim_resolution, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_warranty_claim(p_claim_id uuid, p_resolution public.warranty_claim_resolution, p_lines jsonb DEFAULT NULL::jsonb, p_replacement_lines jsonb DEFAULT NULL::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_claim public.warranty_claims%ROWTYPE;
  v_serial public.stock_serials%ROWTYPE;
  v_from_wh UUID;
  v_uom UUID;
  v_return_lines JSONB;
  v_entry UUID;
  v_cn UUID;
  v_main UUID;
BEGIN
  PERFORM public._warranty_begin_rpc();
  PERFORM public._require_warranty_staff();

  IF p_resolution NOT IN ('replacement', 'credit_note', 'return_only') THEN
    RAISE EXCEPTION 'approve resolution must be replacement, credit_note, or return_only';
  END IF;

  SELECT * INTO v_claim FROM public.warranty_claims WHERE id = p_claim_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'warranty claim not found';
  END IF;
  IF v_claim.status <> 'open' THEN
    RAISE EXCEPTION 'only open claims can be approved (status=%)', v_claim.status;
  END IF;

  IF p_resolution = 'credit_note' AND v_claim.sales_invoice_id IS NULL THEN
    RAISE EXCEPTION 'credit_note resolution requires sales_invoice_id on claim';
  END IF;
  IF p_resolution = 'replacement' AND (
    p_replacement_lines IS NULL OR jsonb_array_length(p_replacement_lines) = 0
  ) THEN
    RAISE EXCEPTION 'replacement resolution requires p_replacement_lines';
  END IF;

  SELECT id INTO v_main FROM public.warehouses WHERE code = 'MAIN' AND is_active LIMIT 1;

  -- Physical return -> Quarantine (skip when CN path will receive stock for same lines)
  IF p_resolution <> 'credit_note' THEN
    v_return_lines := p_lines;
    IF v_return_lines IS NULL AND v_claim.stock_serial_id IS NOT NULL THEN
      SELECT * INTO v_serial FROM public.stock_serials WHERE id = v_claim.stock_serial_id;
      SELECT id INTO v_uom FROM public.uoms WHERE code = 'EA';
      v_from_wh := COALESCE(
        v_serial.warehouse_id,
        (SELECT warehouse_id FROM public.sales_invoices WHERE id = v_claim.sales_invoice_id),
        v_main
      );
      IF v_from_wh IS NULL THEN
        RAISE EXCEPTION 'cannot determine source warehouse for return';
      END IF;
      v_return_lines := jsonb_build_array(
        jsonb_build_object(
          'stock_item_id', v_serial.stock_item_id,
          'uom_id', v_uom,
          'qty', 1,
          'valuation_method', 'FIFO'
        )
      );
    ELSIF v_return_lines IS NULL AND v_claim.stock_item_id IS NOT NULL THEN
      SELECT id INTO v_uom FROM public.uoms WHERE code = 'EA';
      v_from_wh := COALESCE(
        (SELECT warehouse_id FROM public.sales_invoices WHERE id = v_claim.sales_invoice_id),
        v_main
      );
      v_return_lines := jsonb_build_array(
        jsonb_build_object(
          'stock_item_id', v_claim.stock_item_id,
          'uom_id', v_uom,
          'qty', 1,
          'valuation_method', 'FIFO'
        )
      );
    END IF;

    IF v_return_lines IS NOT NULL THEN
      IF v_from_wh IS NULL THEN
        v_from_wh := COALESCE(
          (SELECT warehouse_id FROM public.sales_invoices WHERE id = v_claim.sales_invoice_id),
          v_main
        );
      END IF;
      v_entry := public.post_return_to_quarantine(
        v_from_wh,
        format('Warranty return %s', v_claim.document_number),
        v_return_lines
      );
      UPDATE public.warranty_claims
      SET quarantine_stock_entry_id = v_entry
      WHERE id = p_claim_id;

      IF v_claim.stock_serial_id IS NOT NULL THEN
        UPDATE public.stock_serials
        SET status = 'quarantine',
            warehouse_id = (
              SELECT id FROM public.warehouses WHERE is_quarantine AND is_active ORDER BY code LIMIT 1
            )
        WHERE id = v_claim.stock_serial_id;
        PERFORM public.emit_domain_event(
          'serial_moved',
          'warranty:quar:serial:' || v_claim.stock_serial_id::text || ':' || p_claim_id::text,
          jsonb_build_object(
            'warranty_claim_id', p_claim_id,
            'stock_serial_id', v_claim.stock_serial_id,
            'quarantine_stock_entry_id', v_entry
          )
        );
      END IF;
    END IF;
  END IF;

  IF p_resolution = 'credit_note' THEN
    IF p_lines IS NULL OR jsonb_array_length(p_lines) = 0 THEN
      RAISE EXCEPTION 'credit_note resolution requires p_lines';
    END IF;
    v_cn := public.post_return_credit_note(v_claim.sales_invoice_id, p_lines);
    UPDATE public.warranty_claims SET credit_note_id = v_cn WHERE id = p_claim_id;

    IF v_claim.stock_serial_id IS NOT NULL THEN
      UPDATE public.stock_serials
      SET status = 'quarantine',
          warehouse_id = (
            SELECT id FROM public.warehouses WHERE is_quarantine AND is_active ORDER BY code LIMIT 1
          )
      WHERE id = v_claim.stock_serial_id;
      PERFORM public.emit_domain_event(
        'serial_moved',
        'warranty:cn:serial:' || v_claim.stock_serial_id::text || ':' || p_claim_id::text,
        jsonb_build_object(
          'warranty_claim_id', p_claim_id,
          'credit_note_id', v_cn,
          'stock_serial_id', v_claim.stock_serial_id
        )
      );
    END IF;
  END IF;

  IF p_resolution = 'replacement' THEN
    v_entry := public.post_stock_issue(
      COALESCE(
        (SELECT warehouse_id FROM public.sales_invoices WHERE id = v_claim.sales_invoice_id),
        v_main
      ),
      format('Warranty replacement %s', v_claim.document_number),
      p_replacement_lines
    );
    UPDATE public.warranty_claims
    SET replacement_stock_entry_id = v_entry
    WHERE id = p_claim_id;
  END IF;

  UPDATE public.warranty_claims
  SET
    status = 'approved',
    resolution = p_resolution,
    decided_by = auth.uid(),
    decided_at = now()
  WHERE id = p_claim_id;

  PERFORM public.emit_domain_event(
    'warranty_claim_approved',
    'warranty:approved:' || p_claim_id::text,
    jsonb_build_object(
      'warranty_claim_id', p_claim_id,
      'resolution', p_resolution,
      'credit_note_id', v_cn,
      'quarantine_stock_entry_id', (
        SELECT quarantine_stock_entry_id FROM public.warranty_claims WHERE id = p_claim_id
      ),
      'replacement_stock_entry_id', (
        SELECT replacement_stock_entry_id FROM public.warranty_claims WHERE id = p_claim_id
      )
    )
  );

  RETURN p_claim_id;
END;
$$;


--
-- Name: archive_hr_role(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.archive_hr_role(p_role_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_held INT;
BEGIN
  IF NOT public.has_staff_role(ARRAY['admin']::public.staff_role[]) THEN
    RAISE EXCEPTION 'admin role required to archive organogram roles';
  END IF;

  SELECT COUNT(*)::int INTO v_held
  FROM public.employees e
  WHERE e.hr_role_id = p_role_id AND e.status = 'active';

  IF v_held > 0 THEN
    RAISE EXCEPTION 'reassign % active employee(s) before archiving this role', v_held;
  END IF;

  IF EXISTS (SELECT 1 FROM public.hr_roles c WHERE c.parent_role_id = p_role_id AND c.is_active) THEN
    RAISE EXCEPTION 'archive or reparent child roles first';
  END IF;

  UPDATE public.hr_roles
  SET is_active = false, archived_at = now(), updated_at = now()
  WHERE id = p_role_id;

  RETURN p_role_id;
END;
$$;


--
-- Name: assign_delivery_job(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assign_delivery_job(p_delivery_job_id uuid, p_assignee_user_id uuid, p_override boolean DEFAULT false) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_job public.delivery_jobs%ROWTYPE;
BEGIN
  PERFORM public._logistics_begin_rpc();
  PERFORM public._require_dispatcher_staff();

  IF p_assignee_user_id IS NULL THEN
    RAISE EXCEPTION 'assignee_user_id required';
  END IF;

  SELECT * INTO v_job FROM public.delivery_jobs WHERE id = p_delivery_job_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'delivery job not found';
  END IF;
  IF v_job.status IN ('completed', 'failed') THEN
    RAISE EXCEPTION 'cannot assign terminal delivery job';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.staff_roles
    WHERE user_id = p_assignee_user_id AND role = 'driver'
  ) THEN
    RAISE EXCEPTION 'assignee must have driver staff role';
  END IF;

  IF NOT COALESCE(p_override, false)
     AND NOT public._driver_eligible_for_assign(p_assignee_user_id) THEN
    RAISE EXCEPTION
      'assignee not eligible (need available/on_duty, capacity, shift); use override=true';
  END IF;

  UPDATE public.delivery_jobs
  SET
    assignee_user_id = p_assignee_user_id,
    updated_at = now()
  WHERE id = p_delivery_job_id;

  RETURN p_delivery_job_id;
END;
$$;


--
-- Name: assign_staff_role(uuid, public.staff_role); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assign_staff_role(p_user_id uuid, p_role public.staff_role) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_canonical_role public.staff_role;
BEGIN
  IF NOT (
    auth.role() = 'service_role'
    OR public.has_staff_role(ARRAY['admin']::public.staff_role[])
  ) THEN
    RAISE EXCEPTION 'admin role required to assign staff roles';
  END IF;

  SELECT role INTO v_canonical_role
  FROM public.canonical_staff_accounts
  WHERE user_id = p_user_id AND is_active;
  IF FOUND AND p_role IS DISTINCT FROM v_canonical_role THEN
    RAISE EXCEPTION 'canonical staff % may only hold role %', p_user_id, v_canonical_role;
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = p_user_id) THEN
    RAISE EXCEPTION 'profile not found: %', p_user_id;
  END IF;

  INSERT INTO public.staff_roles (user_id, role)
  VALUES (p_user_id, p_role)
  ON CONFLICT (user_id, role) DO NOTHING;
END;
$$;


--
-- Name: attach_finance_requisition_receipt(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.attach_finance_requisition_receipt(p_requisition_id uuid, p_storage_path text, p_content_type text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE v_row public.finance_requisitions%ROWTYPE; v_path TEXT:=trim(both '/' FROM coalesce(p_storage_path,'')); v_id UUID; BEGIN IF auth.uid() IS NULL AND auth.role()<>'service_role' THEN RAISE EXCEPTION 'not authenticated'; END IF; SELECT * INTO v_row FROM public.finance_requisitions WHERE id=p_requisition_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'requisition not found: %',p_requisition_id; END IF; IF v_row.requested_by<>auth.uid() AND NOT public.has_staff_role(ARRAY['admin','finance']::public.staff_role[]) AND auth.role()<>'service_role' THEN RAISE EXCEPTION 'not allowed to attach receipt'; END IF; IF left(v_path,length('petty-cash-receipts/'))='petty-cash-receipts/' THEN v_path:=substr(v_path,length('petty-cash-receipts/')+1); END IF; IF public._finance_req_id_from_receipt_path(v_path) IS DISTINCT FROM p_requisition_id THEN RAISE EXCEPTION 'storage path must start with requisition id'; END IF; IF NOT EXISTS(SELECT 1 FROM storage.objects o WHERE o.bucket_id='petty-cash-receipts' AND o.name=v_path) THEN RAISE EXCEPTION 'receipt object missing in petty-cash-receipts at %',v_path; END IF; INSERT INTO public.finance_requisition_receipts(requisition_id,storage_path,content_type,created_by) VALUES(p_requisition_id,v_path,nullif(trim(p_content_type),''),auth.uid()) RETURNING id INTO v_id; RETURN v_id; END; $$;


--
-- Name: attach_goods_receipt_invoice(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.attach_goods_receipt_invoice(p_goods_receipt_id uuid, p_storage_path text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_grn public.goods_receipts%ROWTYPE; v_path TEXT; v_prefix TEXT;
BEGIN
 PERFORM public._procurement_begin_rpc();
 IF NOT public.has_staff_role(ARRAY['admin','warehouse','finance']::public.staff_role[]) THEN RAISE EXCEPTION 'not authorized'; END IF;
 IF p_storage_path IS NULL OR length(trim(p_storage_path))=0 THEN RAISE EXCEPTION 'storage path required'; END IF;
 v_path:=trim(both FROM p_storage_path); v_path:=trim(both '/' FROM v_path);
 IF v_path ~ '\.\.' OR v_path ~ '//' OR position('\' IN v_path)>0 THEN RAISE EXCEPTION 'invalid invoice storage path'; END IF;
 IF left(v_path,length('procurement-invoices/'))='procurement-invoices/' THEN v_path:=substr(v_path,length('procurement-invoices/')+1); v_path:=trim(both '/' FROM v_path); END IF;
 IF v_path IS NULL OR length(v_path)=0 OR position('/' IN v_path)=0 THEN RAISE EXCEPTION 'invoice path must be {purchase_order_id}/{filename}'; END IF;
 SELECT * INTO v_grn FROM public.goods_receipts WHERE id=p_goods_receipt_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'goods receipt not found'; END IF;
 IF v_grn.status IS DISTINCT FROM 'draft' THEN RAISE EXCEPTION 'invoice attach only allowed on draft goods receipts (status=%)',v_grn.status; END IF;
 v_prefix:=v_grn.purchase_order_id::text||'/';
 IF left(v_path,length(v_prefix)) IS DISTINCT FROM v_prefix THEN RAISE EXCEPTION 'invoice path must start with % (got %)',v_prefix,v_path; END IF;
 IF length(substr(v_path,length(v_prefix)+1))=0 THEN RAISE EXCEPTION 'invoice path must include a filename under the PO folder'; END IF;
 IF NOT EXISTS(SELECT 1 FROM storage.objects o WHERE o.bucket_id='procurement-invoices' AND o.name=v_path) THEN RAISE EXCEPTION 'invoice object missing in procurement-invoices bucket at %',v_path; END IF;
 UPDATE public.goods_receipts SET supplier_invoice_path=v_path,supplier_invoice_uploaded_at=now(),updated_at=now() WHERE id=p_goods_receipt_id AND status='draft';
 IF NOT FOUND THEN RAISE EXCEPTION 'goods receipt not found or no longer draft'; END IF;
 PERFORM public._procurement_end_rpc(); RETURN p_goods_receipt_id;
EXCEPTION WHEN OTHERS THEN PERFORM public._procurement_end_rpc(); RAISE;
END;$$;


--
-- Name: FUNCTION attach_goods_receipt_invoice(p_goods_receipt_id uuid, p_storage_path text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.attach_goods_receipt_invoice(p_goods_receipt_id uuid, p_storage_path text) IS 'Staff attach supplier invoice path to draft GRN only; path must exist under procurement-invoices as {purchase_order_id}/{filename} (web upload compatible).';


--
-- Name: attach_pos_cart_till_session(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.attach_pos_cart_till_session(p_cart_id uuid, p_session_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE s public.pos_till_sessions%ROWTYPE;
BEGIN
 PERFORM public._require_sales_staff();
 SELECT * INTO s FROM public.pos_till_sessions WHERE id=p_session_id FOR UPDATE;
 IF NOT FOUND OR s.status<>'open' OR s.operator_user_id<>auth.uid() THEN RAISE EXCEPTION 'active operator till session required'; END IF;
 UPDATE public.pos_carts SET till_session_id=p_session_id,updated_at=now()
 WHERE id=p_cart_id AND status='open' AND warehouse_id=s.warehouse_id AND created_by=auth.uid();
 IF NOT FOUND THEN RAISE EXCEPTION 'open cart at till warehouse required'; END IF; RETURN p_cart_id;
END $$;


--
-- Name: attach_pos_fulfillment_to_cart(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.attach_pos_fulfillment_to_cart(p_request_id uuid, p_cart_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE r public.pos_fulfillment_requests%ROWTYPE; c public.pos_carts%ROWTYPE;
BEGIN
 PERFORM public._require_sales_staff();
 SELECT * INTO r FROM public.pos_fulfillment_requests WHERE id=p_request_id FOR UPDATE;
 IF NOT FOUND OR r.invoice_id IS NOT NULL
    OR NOT ((r.kind='backorder' AND r.status IN('requested','ready')) OR (r.kind='branch_transfer' AND r.status='ready')) THEN
  RAISE EXCEPTION 'an open back-order or arrived transfer without a sale is required';
 END IF;
 SELECT * INTO c FROM public.pos_carts WHERE id=p_cart_id;
 IF NOT FOUND OR c.status<>'open' THEN RAISE EXCEPTION 'open sale required'; END IF;
 UPDATE public.pos_fulfillment_requests
 SET cart_id=p_cart_id, customer_id=COALESCE(customer_id,c.customer_id), updated_at=now()
 WHERE id=p_request_id;
 RETURN p_request_id;
END $$;


--
-- Name: attendance_hours_in_period(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.attendance_hours_in_period(p_employee_id uuid, p_period_start timestamp with time zone, p_period_end timestamp with time zone) RETURNS numeric
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_hours NUMERIC := 0;
  v_in TIMESTAMPTZ;
  v_is_hr BOOLEAN;
  v_self UUID;
  r RECORD;
BEGIN
  v_is_hr := (
    auth.role() = 'service_role'
    OR public.has_staff_role(ARRAY['admin', 'hr']::public.staff_role[])
  );
  v_self := public.current_employee_id();

  IF NOT v_is_hr AND (v_self IS NULL OR v_self IS DISTINCT FROM p_employee_id) THEN
    RAISE EXCEPTION 'admin/hr role or own employee record required to read attendance hours';
  END IF;

  IF p_period_end < p_period_start THEN
    RAISE EXCEPTION 'period_end must be >= period_start';
  END IF;

  FOR r IN
    SELECT event_type, occurred_at
    FROM public.attendance_events
    WHERE employee_id = p_employee_id
      AND occurred_at >= p_period_start
      AND occurred_at < p_period_end
    ORDER BY occurred_at ASC, created_at ASC
  LOOP
    IF r.event_type = 'clock_in' THEN
      v_in := r.occurred_at;
    ELSIF r.event_type = 'clock_out' AND v_in IS NOT NULL THEN
      v_hours := v_hours + EXTRACT(EPOCH FROM (r.occurred_at - v_in)) / 3600.0;
      v_in := NULL;
    END IF;
  END LOOP;

  RETURN ROUND(v_hours, 4);
END;
$$;


--
-- Name: award_quotation_to_po(uuid, text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.award_quotation_to_po(p_supplier_quotation_id uuid, p_notes text DEFAULT NULL::text, p_expected_date date DEFAULT NULL::date) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_sq public.supplier_quotations%ROWTYPE;
  v_rfq public.rfqs%ROWTYPE;
  v_po UUID;
  v_lines JSONB := '[]'::jsonb;
  v_row RECORD;
BEGIN
  PERFORM public._procurement_begin_rpc();
  PERFORM public._require_procurement_staff();
  PERFORM public._assert_procurement_period_open();

  SELECT * INTO v_sq FROM public.supplier_quotations WHERE id = p_supplier_quotation_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'quotation not found: %', p_supplier_quotation_id;
  END IF;
  IF v_sq.status <> 'submitted' THEN
    RAISE EXCEPTION 'quotation must be submitted before award';
  END IF;

  SELECT * INTO v_rfq FROM public.rfqs WHERE id = v_sq.rfq_id;
  IF v_rfq.status <> 'submitted' THEN
    RAISE EXCEPTION 'RFQ must be submitted';
  END IF;
  IF v_rfq.awarded_quotation_id IS NOT NULL THEN
    RAISE EXCEPTION 'RFQ already awarded';
  END IF;

  FOR v_row IN
    SELECT sql.*
    FROM public.supplier_quotation_lines sql
    WHERE sql.supplier_quotation_id = p_supplier_quotation_id
    ORDER BY sql.line_no
  LOOP
    v_lines := v_lines || jsonb_build_array(
      jsonb_build_object(
        'stock_item_id', v_row.stock_item_id,
        'uom_id', v_row.uom_id,
        'qty', v_row.qty,
        'unit_price', v_row.unit_price,
        'currency', v_row.currency
      )
    );
  END LOOP;

  v_po := public.create_purchase_order(
    v_sq.supplier_id,
    v_rfq.warehouse_id,
    v_sq.currency,
    v_sq.exchange_rate_applied,
    v_lines,
    COALESCE(p_notes, format('Awarded from %s', COALESCE(v_sq.document_number, v_sq.id::text))),
    p_expected_date,
    NULL
  );

  UPDATE public.purchase_orders
  SET rfq_id = v_rfq.id, awarded_quotation_id = p_supplier_quotation_id
  WHERE id = v_po;

  UPDATE public.rfqs
  SET awarded_quotation_id = p_supplier_quotation_id, updated_at = now()
  WHERE id = v_rfq.id;

  PERFORM public._procurement_end_rpc();
  RETURN v_po;
EXCEPTION
  WHEN OTHERS THEN
    PERFORM public._procurement_end_rpc();
    RAISE;
END;
$$;


--
-- Name: begin_delivery_card_terminal_payment(uuid, uuid, text, numeric, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.begin_delivery_card_terminal_payment(p_delivery_job_id uuid, p_terminal_id uuid, p_device_id text, p_amount numeric, p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE j public.delivery_jobs%ROWTYPE;i public.sales_invoices%ROWTYPE;t public.pos_card_terminals%ROWTYPE;a public.pos_card_terminal_attempts%ROWTYPE;v_due NUMERIC;v_ref TEXT;
BEGIN
 SELECT * INTO a FROM public.pos_card_terminal_attempts WHERE request_id=p_request_id; IF FOUND THEN RETURN private.pos_card_terminal_attempt_payload(a.id); END IF;
 SELECT * INTO j FROM public.delivery_jobs WHERE id=p_delivery_job_id FOR UPDATE;
 IF NOT FOUND OR j.status<>'dispatched' OR j.assignee_user_id IS DISTINCT FROM auth.uid() OR NOT public.has_staff_role(ARRAY['driver']::public.staff_role[]) THEN RAISE EXCEPTION 'assigned dispatched driver job required'; END IF;
 SELECT si.* INTO i FROM public.delivery_notes dn JOIN public.sales_invoices si ON si.id=dn.sales_invoice_id WHERE dn.id=j.delivery_note_id FOR UPDATE OF si;
 IF i.delivery_payment_method NOT IN('card_on_delivery','cash_or_card_on_delivery') THEN RAISE EXCEPTION 'this delivery is not authorized for card collection'; END IF;
 v_due:=greatest(round(i.total-i.amount_paid,2),0); IF COALESCE(p_amount,0)<=0 OR p_amount>v_due+0.01 THEN RAISE EXCEPTION 'card amount must be >0 and <= delivery balance %',v_due; END IF;
 SELECT * INTO t FROM public.pos_card_terminals WHERE id=p_terminal_id;
 IF NOT FOUND OR NOT t.is_active OR NOT t.allow_delivery OR (t.device_id IS NOT NULL AND t.device_id<>p_device_id) OR (t.warehouse_id IS NOT NULL AND t.warehouse_id<>i.warehouse_id) THEN
  RAISE EXCEPTION 'delivery-enabled swipe machine assigned to this device/warehouse required'; END IF;
 IF EXISTS(SELECT 1 FROM public.pos_card_terminal_attempts x WHERE x.delivery_job_id=j.id AND x.status IN('initiated','approved','unknown')) THEN RAISE EXCEPTION 'reconcile the unresolved delivery card payment before charging again'; END IF;
 v_ref:='GTR-DCT-'||replace(p_request_id::text,'-','');
 INSERT INTO public.pos_card_terminal_attempts(request_id,operation,terminal_id,delivery_job_id,source_invoice_id,amount,currency,external_ref,created_by)
 VALUES(p_request_id,'purchase',t.id,j.id,i.id,round(p_amount,2),i.currency,v_ref,auth.uid()) RETURNING * INTO a;
 RETURN private.pos_card_terminal_attempt_payload(a.id);
END $$;


--
-- Name: begin_pos_card_terminal_purchase(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.begin_pos_card_terminal_purchase(p_order_id uuid, p_terminal_id uuid, p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE o public.commerce_orders%ROWTYPE; c public.pos_carts%ROWTYPE; s public.pos_till_sessions%ROWTYPE;
 t public.pos_card_terminals%ROWTYPE; a public.pos_card_terminal_attempts%ROWTYPE; v_ref TEXT;
BEGIN
 PERFORM public._require_payments_staff();
 IF p_order_id IS NULL OR p_terminal_id IS NULL OR p_request_id IS NULL THEN RAISE EXCEPTION 'order, terminal and request ids required'; END IF;
 SELECT * INTO a FROM public.pos_card_terminal_attempts WHERE request_id=p_request_id;
 IF FOUND THEN
  IF a.operation<>'purchase' OR a.commerce_order_id<>p_order_id OR a.terminal_id<>p_terminal_id THEN RAISE EXCEPTION 'terminal request id belongs to another operation'; END IF;
  RETURN private.pos_card_terminal_attempt_payload(a.id);
 END IF;
 SELECT * INTO o FROM public.commerce_orders WHERE id=p_order_id FOR UPDATE;
 IF NOT FOUND OR o.sales_invoice_id IS NOT NULL OR o.settled_payment_entry_id IS NOT NULL THEN RAISE EXCEPTION 'unsettled commerce order required'; END IF;
 IF o.reservation_expires_at IS NULL OR o.reservation_expires_at<=now() THEN RAISE EXCEPTION 'commerce reservation expired'; END IF;
 IF o.state NOT IN('awaiting_payment','payment_failed','payment_processing') THEN RAISE EXCEPTION 'card terminal cannot start in order state %',o.state; END IF;
 SELECT * INTO c FROM public.pos_carts WHERE id=o.cart_id;
 IF NOT FOUND OR c.created_by<>auth.uid() OR c.till_session_id IS NULL THEN RAISE EXCEPTION 'current operator cart and till required'; END IF;
 SELECT * INTO s FROM public.pos_till_sessions WHERE id=c.till_session_id;
 IF NOT FOUND OR s.status<>'open' OR s.operator_user_id<>auth.uid() OR s.warehouse_id<>o.warehouse_id THEN RAISE EXCEPTION 'active operator till required'; END IF;
 SELECT * INTO t FROM public.pos_card_terminals WHERE id=p_terminal_id;
 IF NOT FOUND OR NOT t.is_active THEN RAISE EXCEPTION 'active card terminal required'; END IF;
 IF t.warehouse_id IS NOT NULL AND t.warehouse_id<>o.warehouse_id THEN RAISE EXCEPTION 'card terminal is assigned to another warehouse'; END IF;
 IF t.device_id IS NOT NULL AND t.device_id<>s.device_id THEN RAISE EXCEPTION 'card terminal is assigned to another till device'; END IF;
 IF o.state='payment_processing' THEN
  IF o.active_payment_provider IS DISTINCT FROM 'card_terminal' THEN RAISE EXCEPTION 'another payment provider is already processing'; END IF;
  SELECT * INTO a FROM public.pos_card_terminal_attempts WHERE id=o.active_payment_intent_id;
  IF FOUND AND a.status IN('initiated','approved','unknown') THEN
   RAISE EXCEPTION 'existing card terminal attempt % is unresolved; reconcile it before charging again',a.id;
  END IF;
 END IF;
 v_ref:='GTR-CT-'||replace(p_request_id::text,'-','');
 INSERT INTO public.pos_card_terminal_attempts(request_id,operation,terminal_id,commerce_order_id,amount,currency,external_ref,created_by)
 VALUES(p_request_id,'purchase',p_terminal_id,p_order_id,o.total,o.currency,v_ref,auth.uid()) RETURNING * INTO a;
 UPDATE public.commerce_orders SET state='payment_processing',active_payment_provider='card_terminal',active_payment_intent_id=a.id,
  payment_exception=NULL,updated_at=now() WHERE id=o.id;
 PERFORM private.enqueue_commerce_event('commerce:'||o.id::text||':card-terminal:'||a.id::text,
  'commerce.card_terminal_started',o.id,jsonb_build_object('attempt_id',a.id,'terminal_id',p_terminal_id,'external_ref',v_ref));
 RETURN private.pos_card_terminal_attempt_payload(a.id);
END $$;


--
-- Name: begin_pos_card_terminal_refund(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.begin_pos_card_terminal_refund(p_invoice_id uuid, p_terminal_id uuid, p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE i public.sales_invoices%ROWTYPE; t public.pos_card_terminals%ROWTYPE; p public.pos_card_terminal_attempts%ROWTYPE;
 a public.pos_card_terminal_attempts%ROWTYPE; v_pe UUID; v_ref TEXT;
BEGIN
 IF NOT (public.is_pos_approver() OR public.has_staff_role(ARRAY['finance']::public.staff_role[])) THEN RAISE EXCEPTION 'POS manager or finance approval required'; END IF;
 SELECT * INTO a FROM public.pos_card_terminal_attempts WHERE request_id=p_request_id;
 IF FOUND THEN
  IF a.operation<>'refund' OR a.source_invoice_id<>p_invoice_id OR a.terminal_id<>p_terminal_id THEN RAISE EXCEPTION 'terminal request id belongs to another operation'; END IF;
  RETURN private.pos_card_terminal_attempt_payload(a.id);
 END IF;
 SELECT * INTO i FROM public.sales_invoices WHERE id=p_invoice_id FOR UPDATE;
 IF NOT FOUND OR i.status<>'posted' OR i.doc_type<>'invoice' THEN RAISE EXCEPTION 'posted sales invoice required'; END IF;
 IF EXISTS(SELECT 1 FROM public.finance_refunds f WHERE f.original_invoice_id=i.id) THEN RAISE EXCEPTION 'finance refund already posted for invoice'; END IF;
 -- The refund returns the whole sale to the card; a sale already partly returned is refunded through returns.
 IF EXISTS(SELECT 1 FROM public.sales_invoices cn WHERE cn.return_against_id=i.id AND cn.doc_type='credit_note' AND cn.status='posted') THEN
  RAISE EXCEPTION 'part of this sale was already returned; refund the rest through a return';
 END IF;
 SELECT pe.id INTO v_pe FROM public.payment_entries pe JOIN public.payment_allocations pa ON pa.payment_entry_id=pe.id
 WHERE pa.sales_invoice_id=i.id AND pe.status='posted' AND pe.tender='card_terminal' AND pa.amount+0.01>=i.total ORDER BY pe.posted_at DESC LIMIT 1;
 IF v_pe IS NULL THEN RAISE EXCEPTION 'invoice was not fully settled through a card terminal'; END IF;
 SELECT * INTO p FROM public.pos_card_terminal_attempts WHERE payment_entry_id=v_pe AND invoice_id=i.id AND operation='purchase' AND status='settled' ORDER BY finalized_at DESC LIMIT 1;
 IF NOT FOUND THEN RAISE EXCEPTION 'source card terminal purchase evidence not found'; END IF;
 IF EXISTS(SELECT 1 FROM public.pos_card_terminal_attempts x WHERE x.source_invoice_id=i.id AND x.operation='refund' AND x.status IN('initiated','approved','unknown','settled')) THEN
  RAISE EXCEPTION 'an existing card terminal refund must be reconciled before another refund';
 END IF;
 SELECT * INTO t FROM public.pos_card_terminals WHERE id=p_terminal_id;
 IF NOT FOUND OR NOT t.is_active THEN RAISE EXCEPTION 'active card terminal required'; END IF;
 IF t.warehouse_id IS NOT NULL AND t.warehouse_id<>i.warehouse_id THEN RAISE EXCEPTION 'refund terminal is assigned to another warehouse'; END IF;
 v_ref:='GTR-CTRF-'||replace(p_request_id::text,'-','');
 INSERT INTO public.pos_card_terminal_attempts(request_id,operation,terminal_id,source_invoice_id,parent_attempt_id,amount,currency,external_ref,created_by)
 VALUES(p_request_id,'refund',p_terminal_id,i.id,p.id,i.total,i.currency,v_ref,auth.uid()) RETURNING * INTO a;
 RETURN private.pos_card_terminal_attempt_payload(a.id);
END $$;


--
-- Name: begin_pos_card_terminal_reversal(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.begin_pos_card_terminal_reversal(p_purchase_attempt_id uuid, p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE p public.pos_card_terminal_attempts%ROWTYPE; a public.pos_card_terminal_attempts%ROWTYPE; o public.commerce_orders%ROWTYPE; v_ref TEXT;
BEGIN
 PERFORM public._require_payments_staff();
 SELECT * INTO a FROM public.pos_card_terminal_attempts WHERE request_id=p_request_id;
 IF FOUND THEN
  IF a.operation<>'reversal' OR a.parent_attempt_id<>p_purchase_attempt_id THEN RAISE EXCEPTION 'terminal request id belongs to another operation'; END IF;
  RETURN private.pos_card_terminal_attempt_payload(a.id);
 END IF;
 SELECT * INTO p FROM public.pos_card_terminal_attempts WHERE id=p_purchase_attempt_id FOR UPDATE;
 IF NOT FOUND OR p.operation<>'purchase' OR p.status<>'approved' OR p.payment_entry_id IS NOT NULL OR p.invoice_id IS NOT NULL THEN
  RAISE EXCEPTION 'approved, unfinalized purchase attempt required for reversal';
 END IF;
 IF p.created_by<>auth.uid() AND NOT public.is_pos_approver() THEN RAISE EXCEPTION 'purchase operator or POS manager required'; END IF;
 SELECT * INTO o FROM public.commerce_orders WHERE id=p.commerce_order_id FOR UPDATE;
 IF NOT FOUND OR o.settled_payment_entry_id IS NOT NULL THEN RAISE EXCEPTION 'settled order cannot use terminal reversal; use refund flow'; END IF;
 IF EXISTS(SELECT 1 FROM public.pos_card_terminal_attempts x WHERE x.parent_attempt_id=p.id AND x.operation='reversal' AND x.status IN('initiated','approved','unknown')) THEN
  RAISE EXCEPTION 'an unresolved reversal already exists for this purchase';
 END IF;
 v_ref:='GTR-CTRV-'||replace(p_request_id::text,'-','');
 INSERT INTO public.pos_card_terminal_attempts(request_id,operation,terminal_id,commerce_order_id,parent_attempt_id,amount,currency,external_ref,created_by)
 VALUES(p_request_id,'reversal',p.terminal_id,p.commerce_order_id,p.id,p.amount,p.currency,v_ref,auth.uid()) RETURNING * INTO a;
 UPDATE public.commerce_orders SET state='payment_processing',active_payment_provider='card_terminal',active_payment_intent_id=a.id,
  payment_exception='CARD_TERMINAL_REVERSAL_PENDING',updated_at=now() WHERE id=o.id;
 RETURN private.pos_card_terminal_attempt_payload(a.id);
END $$;


--
-- Name: begin_pos_card_terminal_split_refund(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.begin_pos_card_terminal_split_refund(p_refund_id uuid, p_terminal_id uuid, p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE r public.pos_split_refund_requests%ROWTYPE; l public.pos_split_payment_legs%ROWTYPE; p public.pos_card_terminal_attempts%ROWTYPE;
 a public.pos_card_terminal_attempts%ROWTYPE; t public.pos_card_terminals%ROWTYPE; s public.pos_split_payment_sessions%ROWTYPE; v_ref TEXT; v_amount NUMERIC;
BEGIN
 IF NOT (public.is_pos_approver() OR public.has_staff_role(ARRAY['finance']::public.staff_role[])) THEN RAISE EXCEPTION 'manager or finance approval required'; END IF;
 SELECT * INTO a FROM public.pos_card_terminal_attempts WHERE request_id=p_request_id; IF FOUND THEN RETURN private.pos_card_terminal_attempt_payload(a.id); END IF;
 SELECT * INTO r FROM public.pos_split_refund_requests WHERE id=p_refund_id FOR UPDATE; IF NOT FOUND OR r.status<>'pending' THEN RAISE EXCEPTION 'approved pending split refund required'; END IF;
 SELECT * INTO l FROM public.pos_split_payment_legs WHERE id=r.leg_id FOR UPDATE; IF l.tender<>'card_terminal' OR l.card_terminal_attempt_id IS NULL THEN RAISE EXCEPTION 'card-terminal split leg required'; END IF;
 SELECT * INTO p FROM public.pos_card_terminal_attempts WHERE id=l.card_terminal_attempt_id; IF NOT FOUND OR p.terminal_transaction_id IS NULL THEN RAISE EXCEPTION 'original terminal transaction evidence required'; END IF;
 SELECT * INTO t FROM public.pos_card_terminals WHERE id=p_terminal_id; SELECT * INTO s FROM public.pos_split_payment_sessions WHERE id=r.session_id;
 IF t.id IS NULL OR NOT t.is_active THEN RAISE EXCEPTION 'active card terminal required'; END IF;
 v_amount:=round(r.gross_amount-r.approved_customer_fee,2); IF v_amount<=0 THEN RAISE EXCEPTION 'net customer refund must be > 0'; END IF;
 v_ref:='GTR-CTSR-'||replace(p_request_id::text,'-','');
 INSERT INTO public.pos_card_terminal_attempts(request_id,operation,terminal_id,parent_attempt_id,split_leg_id,split_refund_request_id,amount,currency,external_ref,created_by)
 VALUES(p_request_id,'refund',p_terminal_id,p.id,l.id,r.id,v_amount,s.currency,v_ref,auth.uid()) RETURNING * INTO a;
 RETURN private.pos_card_terminal_attempt_payload(a.id);
END $$;


--
-- Name: begin_pos_split_card_terminal_leg(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.begin_pos_split_card_terminal_leg(p_leg_id uuid, p_terminal_id uuid, p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE l public.pos_split_payment_legs%ROWTYPE; s public.pos_split_payment_sessions%ROWTYPE; o public.commerce_orders%ROWTYPE;
 c public.pos_carts%ROWTYPE; ts public.pos_till_sessions%ROWTYPE; t public.pos_card_terminals%ROWTYPE; a public.pos_card_terminal_attempts%ROWTYPE; v_ref TEXT;
BEGIN
 PERFORM public._require_payments_staff(); SELECT * INTO a FROM public.pos_card_terminal_attempts WHERE request_id=p_request_id;
 IF FOUND THEN RETURN private.pos_card_terminal_attempt_payload(a.id); END IF;
 SELECT * INTO l FROM public.pos_split_payment_legs WHERE id=p_leg_id FOR UPDATE;
 IF NOT FOUND OR l.tender<>'card_terminal' OR l.status<>'planned' THEN RAISE EXCEPTION 'planned card-terminal split leg required'; END IF;
 SELECT * INTO s FROM public.pos_split_payment_sessions WHERE id=l.session_id FOR UPDATE; SELECT * INTO o FROM public.commerce_orders WHERE id=s.commerce_order_id FOR UPDATE;
 SELECT * INTO c FROM public.pos_carts WHERE id=o.cart_id; SELECT * INTO ts FROM public.pos_till_sessions WHERE id=c.till_session_id;
 IF c.created_by<>auth.uid() OR ts.status<>'open' OR ts.operator_user_id<>auth.uid() THEN RAISE EXCEPTION 'active operator till required'; END IF;
 SELECT * INTO t FROM public.pos_card_terminals WHERE id=p_terminal_id;
 IF NOT FOUND OR NOT t.is_active OR (t.warehouse_id IS NOT NULL AND t.warehouse_id<>o.warehouse_id) OR (t.device_id IS NOT NULL AND t.device_id<>ts.device_id) THEN
  RAISE EXCEPTION 'active swipe machine assigned to this warehouse/device required'; END IF;
 v_ref:='GTR-CTS-'||replace(p_request_id::text,'-','');
 INSERT INTO public.pos_card_terminal_attempts(request_id,operation,terminal_id,commerce_order_id,split_leg_id,amount,currency,external_ref,created_by)
 VALUES(p_request_id,'purchase',p_terminal_id,o.id,l.id,l.requested_amount,s.currency,v_ref,auth.uid()) RETURNING * INTO a;
 UPDATE public.pos_split_payment_legs SET status='pending',card_terminal_attempt_id=a.id,external_reference=v_ref,updated_at=now() WHERE id=l.id;
 UPDATE public.commerce_orders SET state='payment_processing',active_payment_provider='card_terminal',active_payment_intent_id=a.id,payment_exception=NULL,updated_at=now() WHERE id=o.id;
 PERFORM private.refresh_pos_split_payment_session(s.id); RETURN private.pos_card_terminal_attempt_payload(a.id);
END $$;


--
-- Name: build_qr_payload(text, text, public.valuation_method); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.build_qr_payload(p_oem text, p_batch_code text, p_valuation public.valuation_method) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  SELECT format(
    'gtr://part/%s?batch=%s&valuation=%s',
    p_oem,
    p_batch_code,
    p_valuation::text
  );
$$;


--
-- Name: cancel_auth_challenge(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_auth_challenge(p_kind text, p_challenge_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_kind text := lower(trim(coalesce(p_kind,'')));
  v_count integer;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'service_role required';
  end if;
  if p_challenge_id is null then return false; end if;
  if v_kind='auth_otp' then
    update public.auth_otp_challenges
      set expires_at=least(expires_at,clock_timestamp())
      where id=p_challenge_id and consumed_at is null;
  elsif v_kind='password_reset' then
    update public.password_reset_challenges
      set expires_at=least(expires_at,clock_timestamp())
      where id=p_challenge_id and consumed_at is null;
  else
    raise exception 'invalid challenge kind';
  end if;
  get diagnostics v_count = row_count;
  return v_count > 0;
end;
$$;


--
-- Name: cancel_consignment_entry(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_consignment_entry(p_entry_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_hdr public.consignment_entries%ROWTYPE;
  v_line RECORD;
  v_qty_base NUMERIC;
  v_cost NUMERIC;
  v_price NUMERIC;
  v_rev_total NUMERIC := 0;
  v_rev_je UUID;
  v_batch_code TEXT;
  v_level_cost NUMERIC;
BEGIN
  PERFORM public._require_consignment_staff();

  SELECT * INTO v_hdr FROM public.consignment_entries WHERE id = p_entry_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'consignment entry not found: %', p_entry_id;
  END IF;
  IF v_hdr.status = 'cancelled' THEN
    RETURN p_entry_id;
  END IF;
  IF v_hdr.status NOT IN ('draft', 'submitted') THEN
    RAISE EXCEPTION 'only draft/submitted consignment entries can be cancelled';
  END IF;

  IF v_hdr.status = 'draft' THEN
    PERFORM set_config('gtr.consignment_rpc', 'on', true);
    UPDATE public.consignment_entries
    SET status = 'cancelled', cancelled_at = now(), updated_at = now()
    WHERE id = p_entry_id;
    RETURN p_entry_id;
  END IF;

  IF public.is_period_locked(CURRENT_DATE) THEN
    RAISE EXCEPTION 'accounting period is locked for today';
  END IF;

  -- Reverse stock / consignment qty (mirror of submit)
  FOR v_line IN
    SELECT * FROM public.consignment_entry_lines
    WHERE consignment_entry_id = p_entry_id
    ORDER BY line_no
  LOOP
    v_qty_base := public.convert_to_base_uom(v_line.stock_item_id, v_line.uom_id, v_line.qty);
    v_cost := v_line.unit_cost;
    v_price := v_line.unit_price;

    CASE v_hdr.purpose
      WHEN 'receive' THEN
        PERFORM public._adjust_consignment_level(
          'supplier_owned', v_hdr.supplier_id, NULL,
          v_line.stock_item_id, v_hdr.warehouse_id,
          -v_qty_base, v_cost, v_line.currency
        );
      WHEN 'return_to_supplier' THEN
        PERFORM public._adjust_consignment_level(
          'supplier_owned', v_hdr.supplier_id, NULL,
          v_line.stock_item_id, v_hdr.warehouse_id,
          v_qty_base, v_cost, v_line.currency
        );
      WHEN 'place_at_customer' THEN
        SELECT unit_cost INTO v_level_cost
        FROM public.consignment_stock_levels
        WHERE kind = 'customer_held'
          AND customer_id = v_hdr.customer_id
          AND stock_item_id = v_line.stock_item_id
          AND warehouse_id = v_hdr.warehouse_id;
        v_cost := COALESCE(NULLIF(v_cost, 0), v_level_cost, 0);
        PERFORM public._adjust_consignment_level(
          'customer_held', NULL, v_hdr.customer_id,
          v_line.stock_item_id, v_hdr.warehouse_id,
          -v_qty_base, v_cost, v_line.currency
        );
        v_batch_code := public.next_series_value('BATCH-');
        INSERT INTO public.stock_batches (
          batch_code, stock_item_id, warehouse_id, valuation_method,
          unit_cost, currency, qty_on_hand
        ) VALUES (
          v_batch_code, v_line.stock_item_id, v_hdr.warehouse_id, 'FIFO',
          v_cost, v_line.currency, v_qty_base
        );
        PERFORM public._adjust_stock_level(
          v_line.stock_item_id, v_hdr.warehouse_id, v_qty_base,
          'FIFO', v_cost, v_line.currency
        );
      WHEN 'return_from_customer' THEN
        SELECT unit_cost INTO v_level_cost
        FROM public.stock_levels
        WHERE stock_item_id = v_line.stock_item_id AND warehouse_id = v_hdr.warehouse_id;
        v_cost := COALESCE(NULLIF(v_cost, 0), v_level_cost, 0);
        PERFORM public._consume_fifo_batches(
          v_line.stock_item_id, v_hdr.warehouse_id, v_qty_base
        );
        PERFORM public._adjust_stock_level(
          v_line.stock_item_id, v_hdr.warehouse_id, -v_qty_base,
          'FIFO', v_cost, v_line.currency
        );
        PERFORM public._adjust_consignment_level(
          'customer_held', NULL, v_hdr.customer_id,
          v_line.stock_item_id, v_hdr.warehouse_id,
          v_qty_base, v_cost, v_line.currency
        );
      WHEN 'take_ownership' THEN
        SELECT unit_cost INTO v_level_cost
        FROM public.stock_levels
        WHERE stock_item_id = v_line.stock_item_id AND warehouse_id = v_hdr.warehouse_id;
        v_cost := COALESCE(NULLIF(v_cost, 0), v_level_cost, 0);
        PERFORM public._consume_fifo_batches(
          v_line.stock_item_id, v_hdr.warehouse_id, v_qty_base
        );
        PERFORM public._adjust_stock_level(
          v_line.stock_item_id, v_hdr.warehouse_id, -v_qty_base,
          'FIFO', v_cost, v_line.currency
        );
        PERFORM public._adjust_consignment_level(
          'supplier_owned', v_hdr.supplier_id, NULL,
          v_line.stock_item_id, v_hdr.warehouse_id,
          v_qty_base, v_cost, v_line.currency
        );
      WHEN 'recognize_sale' THEN
        SELECT unit_cost INTO v_level_cost
        FROM public.consignment_stock_levels
        WHERE kind = 'customer_held'
          AND customer_id = v_hdr.customer_id
          AND stock_item_id = v_line.stock_item_id
          AND warehouse_id = v_hdr.warehouse_id;
        v_cost := COALESCE(NULLIF(v_cost, 0), v_level_cost, v_line.unit_cost, 0);
        PERFORM public._adjust_consignment_level(
          'customer_held', NULL, v_hdr.customer_id,
          v_line.stock_item_id, v_hdr.warehouse_id,
          v_qty_base, v_cost, v_line.currency
        );
        v_rev_total := v_rev_total + round(v_qty_base * v_price, 2);
      ELSE
        RAISE EXCEPTION 'unsupported consignment purpose: %', v_hdr.purpose;
    END CASE;
  END LOOP;

  IF v_hdr.journal_entry_id IS NOT NULL THEN
    v_rev_je := public._reverse_journal_inventory(
      v_hdr.journal_entry_id,
      format('Cancel consignment %s', v_hdr.document_number)
    );
  END IF;

  IF v_hdr.purpose = 'recognize_sale' AND v_rev_total > 0 THEN
    UPDATE public.customers
    SET open_balance = open_balance - v_rev_total, updated_at = now()
    WHERE id = v_hdr.customer_id;
  END IF;

  PERFORM set_config('gtr.consignment_rpc', 'on', true);

  UPDATE public.consignment_entries
  SET
    status = 'cancelled',
    cancelled_at = now(),
    reversal_journal_entry_id = v_rev_je,
    updated_at = now()
  WHERE id = p_entry_id;

  RETURN p_entry_id;
END;
$$;


--
-- Name: cancel_delivery_note(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_delivery_note(p_delivery_note_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_dn public.delivery_notes%ROWTYPE;
  v_line RECORD;
  v_batch_code TEXT;
  v_rev UUID;
BEGIN
  PERFORM public._logistics_begin_rpc();
  PERFORM public._require_logistics_staff();

  SELECT * INTO v_dn FROM public.delivery_notes WHERE id = p_delivery_note_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'delivery note not found';
  END IF;

  IF v_dn.status = 'draft' THEN
    UPDATE public.delivery_notes
    SET status = 'cancelled', cancelled_at = now(), updated_at = now()
    WHERE id = p_delivery_note_id;
    RETURN p_delivery_note_id;
  END IF;

  IF v_dn.status <> 'submitted' THEN
    RAISE EXCEPTION 'only draft/submitted DNs can be cancelled (status=%)', v_dn.status;
  END IF;

  IF public.is_period_locked(CURRENT_DATE) THEN
    RAISE EXCEPTION 'accounting period is locked for today';
  END IF;

  FOR v_line IN
    SELECT * FROM public.delivery_note_lines WHERE delivery_note_id = p_delivery_note_id
  LOOP
    v_batch_code := public.next_series_value('BATCH-');
    INSERT INTO public.stock_batches (
      batch_code, stock_item_id, warehouse_id, valuation_method,
      unit_cost, currency, qty_on_hand
    )
    VALUES (
      v_batch_code,
      v_line.stock_item_id,
      v_dn.warehouse_id,
      'FIFO',
      v_line.unit_cost,
      v_line.currency,
      v_line.qty_base
    );

    PERFORM public._adjust_stock_level(
      v_line.stock_item_id,
      v_dn.warehouse_id,
      v_line.qty_base,
      'FIFO',
      v_line.unit_cost,
      v_line.currency
    );

    UPDATE public.sales_invoice_lines
    SET qty_fulfilled = GREATEST(qty_fulfilled - v_line.qty_base, 0)
    WHERE id = v_line.sales_invoice_line_id;
  END LOOP;

  IF v_dn.cogs_journal_entry_id IS NOT NULL THEN
    v_rev := public._reverse_journal_inventory(
      v_dn.cogs_journal_entry_id,
      format('Cancel DN %s', COALESCE(v_dn.document_number, p_delivery_note_id::text))
    );
  END IF;

  UPDATE public.delivery_notes
  SET
    status = 'cancelled',
    reverse_journal_entry_id = v_rev,
    cancelled_at = now(),
    updated_at = now()
  WHERE id = p_delivery_note_id;

  RETURN p_delivery_note_id;
END;
$$;


--
-- Name: cancel_finance_requisition(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_finance_requisition(p_requisition_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row public.finance_requisitions%ROWTYPE;
BEGIN
  SELECT * INTO v_row
  FROM public.finance_requisitions
  WHERE id = p_requisition_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'requisition not found: %', p_requisition_id;
  END IF;

  IF NOT (
    auth.role() = 'service_role'
    OR public.has_staff_role(ARRAY['admin', 'finance']::public.staff_role[])
    OR v_row.requested_by = auth.uid()
  ) THEN
    RAISE EXCEPTION 'not allowed to cancel this requisition';
  END IF;

  IF v_row.status NOT IN ('draft', 'submitted', 'rejected') THEN
    RAISE EXCEPTION 'cannot cancel requisition in status %', v_row.status;
  END IF;

  PERFORM public._finance_req_rpc_enter();

  UPDATE public.finance_requisitions
  SET
    status = 'cancelled',
    cancelled_at = now(),
    cancelled_by = auth.uid(),
    updated_at = now()
  WHERE id = p_requisition_id;

  RETURN p_requisition_id;
END;
$$;


--
-- Name: cancel_goods_receipt(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_goods_receipt(p_goods_receipt_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_st public.procurement_doc_status;
BEGIN
  PERFORM public._procurement_begin_rpc();
  PERFORM public._require_procurement_staff();
  PERFORM public._assert_procurement_period_open();

  SELECT status INTO v_st FROM public.goods_receipts WHERE id = p_goods_receipt_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'goods receipt not found: %', p_goods_receipt_id;
  END IF;
  IF v_st = 'cancelled' THEN
    PERFORM public._procurement_end_rpc();
    RETURN p_goods_receipt_id;
  END IF;
  IF v_st <> 'draft' THEN
    RAISE EXCEPTION 'submitted GRNs are immutable; reverse stock separately';
  END IF;

  UPDATE public.goods_receipts
  SET status = 'cancelled', cancelled_at = now(), updated_at = now()
  WHERE id = p_goods_receipt_id;

  PERFORM public._procurement_end_rpc();
  RETURN p_goods_receipt_id;
EXCEPTION
  WHEN OTHERS THEN
    PERFORM public._procurement_end_rpc();
    RAISE;
END;
$$;


--
-- Name: cancel_landed_cost_voucher(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_landed_cost_voucher(p_landed_cost_voucher_id uuid, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_lcv public.landed_cost_vouchers%ROWTYPE;
  v_row RECORD;
  v_rev UUID;
BEGIN
  PERFORM public._procurement_begin_rpc();
  PERFORM public._require_procurement_finance();
  PERFORM public._assert_procurement_period_open();

  SELECT * INTO v_lcv FROM public.landed_cost_vouchers WHERE id = p_landed_cost_voucher_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'landed cost voucher not found: %', p_landed_cost_voucher_id;
  END IF;
  IF v_lcv.status = 'cancelled' THEN
    PERFORM public._procurement_end_rpc();
    RETURN p_landed_cost_voucher_id;
  END IF;
  IF v_lcv.status <> 'submitted' THEN
    RAISE EXCEPTION 'only submitted landed cost vouchers can be cancelled';
  END IF;

  FOR v_row IN
    SELECT * FROM public.landed_cost_allocations
    WHERE landed_cost_voucher_id = p_landed_cost_voucher_id
  LOOP
    UPDATE public.stock_batches
    SET unit_cost = v_row.prior_unit_cost
    WHERE id = v_row.stock_batch_id;
  END LOOP;

  IF v_lcv.journal_entry_id IS NOT NULL THEN
    v_rev := public._reverse_journal_inventory(
      v_lcv.journal_entry_id,
      COALESCE(p_notes, format('Cancel %s', v_lcv.document_number))
    );
  END IF;

  UPDATE public.landed_cost_vouchers
  SET
    status = 'cancelled',
    reversal_journal_entry_id = v_rev,
    cancelled_at = now(),
    notes = COALESCE(p_notes, notes),
    updated_at = now()
  WHERE id = p_landed_cost_voucher_id;

  PERFORM public._procurement_end_rpc();
  RETURN p_landed_cost_voucher_id;
EXCEPTION
  WHEN OTHERS THEN
    PERFORM public._procurement_end_rpc();
    RAISE;
END;
$$;


--
-- Name: cancel_material_request(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_material_request(p_material_request_id uuid, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_st public.procurement_doc_status;
  v_open NUMERIC;
BEGIN
  PERFORM public._procurement_begin_rpc();
  PERFORM public._require_procurement_staff();
  PERFORM public._assert_procurement_period_open();

  SELECT status INTO v_st FROM public.material_requests WHERE id = p_material_request_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'material request not found: %', p_material_request_id;
  END IF;
  IF v_st IN ('cancelled', 'rejected') THEN
    PERFORM public._procurement_end_rpc();
    RETURN p_material_request_id;
  END IF;

  SELECT COALESCE(SUM(qty - qty_converted), 0) INTO v_open
  FROM public.material_request_lines
  WHERE material_request_id = p_material_request_id;

  IF v_st IN ('submitted', 'approved') AND v_open < (
    SELECT COALESCE(SUM(qty), 0) FROM public.material_request_lines WHERE material_request_id = p_material_request_id
  ) THEN
    RAISE EXCEPTION 'cannot cancel MR with converted lines';
  END IF;

  UPDATE public.material_requests
  SET
    status = 'cancelled',
    cancelled_at = now(),
    notes = COALESCE(p_notes, notes),
    updated_at = now()
  WHERE id = p_material_request_id;

  PERFORM public._procurement_end_rpc();
  RETURN p_material_request_id;
EXCEPTION
  WHEN OTHERS THEN
    PERFORM public._procurement_end_rpc();
    RAISE;
END;
$$;


--
-- Name: cancel_payment_entry(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_payment_entry(p_payment_entry_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_pe public.payment_entries%ROWTYPE;
  v_rev UUID;
  v_alloc RECORD;
  v_sc UUID;
BEGIN
  PERFORM public._require_payments_staff();
  PERFORM public._payments_rpc_enter();

  SELECT * INTO v_pe FROM public.payment_entries WHERE id = p_payment_entry_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'payment entry not found: %', p_payment_entry_id;
  END IF;
  IF v_pe.status = 'cancelled' THEN
    RETURN p_payment_entry_id;
  END IF;
  IF v_pe.status = 'draft' THEN
    UPDATE public.payment_entries
    SET status = 'cancelled', cancelled_at = now(), updated_at = now()
    WHERE id = p_payment_entry_id;
    RETURN p_payment_entry_id;
  END IF;
  IF v_pe.status <> 'posted' THEN
    RAISE EXCEPTION 'cannot cancel payment in status %', v_pe.status;
  END IF;

  v_rev := public.reverse_journal(
    v_pe.journal_entry_id,
    format('Reversal of payment %s', COALESCE(v_pe.document_number, p_payment_entry_id::text))
  );

  FOR v_alloc IN
    SELECT * FROM public.payment_allocations WHERE payment_entry_id = p_payment_entry_id
  LOOP
    UPDATE public.sales_invoices
    SET amount_paid = GREATEST(0, amount_paid - v_alloc.amount)
    WHERE id = v_alloc.sales_invoice_id;

    UPDATE public.customers
    SET open_balance = open_balance + v_alloc.amount, updated_at = now()
    WHERE id = v_pe.customer_id;
  END LOOP;

  IF v_pe.store_credit_issued > 0 THEN
    SELECT id INTO v_sc
    FROM public.store_credit_ledger
    WHERE payment_entry_id = p_payment_entry_id AND movement = 'issue'
    ORDER BY created_at DESC
    LIMIT 1;

    IF v_sc IS NOT NULL THEN
      PERFORM public._append_store_credit(
        v_pe.customer_id, 'reverse', v_pe.store_credit_issued, v_pe.currency,
        v_pe.exchange_rate_applied, p_payment_entry_id, v_rev,
        'Cancel payment overpay credit', v_sc
      );
    END IF;
  END IF;

  IF v_pe.tender = 'store_credit' THEN
    SELECT id INTO v_sc
    FROM public.store_credit_ledger
    WHERE payment_entry_id = p_payment_entry_id AND movement = 'redeem'
    ORDER BY created_at DESC
    LIMIT 1;

    IF v_sc IS NOT NULL THEN
      PERFORM public._append_store_credit(
        v_pe.customer_id, 'reverse', v_pe.amount, v_pe.currency,
        v_pe.exchange_rate_applied, p_payment_entry_id, v_rev,
        'Cancel payment store credit redeem', v_sc
      );
    END IF;
  END IF;

  UPDATE public.payment_entries
  SET
    status = 'cancelled',
    reversal_journal_entry_id = v_rev,
    cancelled_at = now(),
    updated_at = now()
  WHERE id = p_payment_entry_id;

  RETURN p_payment_entry_id;
END;
$$;


--
-- Name: cancel_payroll_run(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_payroll_run(p_payroll_run_id uuid, p_reason text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_run public.payroll_runs%ROWTYPE;
BEGIN
  PERFORM public._payroll_begin_rpc();
  PERFORM public._require_hr_staff();

  SELECT * INTO v_run FROM public.payroll_runs WHERE id = p_payroll_run_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'payroll run not found: %', p_payroll_run_id;
  END IF;
  IF v_run.status = 'cancelled' THEN
    RAISE EXCEPTION 'payroll run already cancelled';
  END IF;

  -- Void/reverse pattern: flip status only; never edit submitted money lines
  UPDATE public.payroll_runs
  SET
    status = 'cancelled',
    cancelled_at = now(),
    cancel_reason = p_reason,
    updated_at = now()
  WHERE id = p_payroll_run_id;

  RETURN p_payroll_run_id;
END;
$$;


--
-- Name: cancel_pos_commerce_checkout(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_pos_commerce_checkout(p_order_id uuid, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE s public.pos_split_payment_sessions%ROWTYPE;
BEGIN
 SELECT * INTO s FROM public.pos_split_payment_sessions WHERE commerce_order_id=p_order_id FOR UPDATE;
 IF FOUND AND EXISTS(SELECT 1 FROM public.pos_split_payment_legs WHERE session_id=s.id AND status IN('held','pending','unknown','captured','refund_review','refund_pending')) THEN
  RAISE EXCEPTION 'split payment has locked/in-flight money; use split cancellation/refund recovery';
 END IF;
 RETURN public.cancel_pos_commerce_checkout_legacy(p_order_id,p_reason);
END $$;


--
-- Name: cancel_pos_commerce_checkout_legacy(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_pos_commerce_checkout_legacy(p_order_id uuid, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE o public.commerce_orders%ROWTYPE; v_status TEXT;
BEGIN
 PERFORM public._require_sales_staff(); SELECT * INTO o FROM public.commerce_orders WHERE id=p_order_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'commerce order not found'; END IF;
 IF o.settled_payment_entry_id IS NOT NULL THEN RAISE EXCEPTION 'settled order cannot be cancelled'; END IF;
 IF o.active_payment_provider='ecocash' THEN SELECT status::text INTO v_status FROM public.ecocash_payment_intents WHERE id=o.active_payment_intent_id;
 ELSIF o.active_payment_provider='paynow' THEN SELECT status::text INTO v_status FROM public.paynow_payment_intents WHERE id=o.active_payment_intent_id;
 ELSIF o.active_payment_provider='contipay' THEN SELECT status::text INTO v_status FROM public.contipay_payment_intents WHERE id=o.active_payment_intent_id;
 ELSIF o.active_payment_provider='card_terminal' THEN SELECT status::text INTO v_status FROM public.pos_card_terminal_attempts WHERE id=o.active_payment_intent_id;
 END IF;
 IF o.active_payment_provider='card_terminal' AND v_status IN('initiated','approved','unknown') THEN
  RAISE EXCEPTION 'card terminal outcome is unresolved; reconcile or reverse it before releasing stock';
 END IF;
 IF o.active_payment_provider<>'card_terminal' AND v_status IN('pending','authorized') THEN RAISE EXCEPTION 'provider payment still pending; confirm failure/cancellation before releasing stock'; END IF;
 PERFORM private.release_commerce_order(o.id,'cancelled',COALESCE(NULLIF(trim(p_reason),''),'POS checkout cancelled'));
 RETURN o.id;
END $$;


--
-- Name: cancel_pos_fulfillment_request(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_pos_fulfillment_request(p_request_id uuid, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE r public.pos_fulfillment_requests%ROWTYPE;
BEGIN
 PERFORM public._require_sales_staff(); SELECT * INTO r FROM public.pos_fulfillment_requests WHERE id=p_request_id FOR UPDATE;
 IF NOT FOUND OR r.status IN('collected','cancelled','rejected') THEN RAISE EXCEPTION 'active fulfillment request required'; END IF;
 IF r.status='awaiting_transfer_approval' THEN RAISE EXCEPTION 'warehouse transfer already submitted; reject/cancel via warehouse control'; END IF;
 UPDATE public.inventory_reservations SET state='released',released_at=now() WHERE pos_fulfillment_request_id=p_request_id AND state IN('active','allocated');
 UPDATE public.pos_fulfillment_requests SET status='cancelled',cancelled_at=now(),notes=concat_ws(E'\n',notes,p_notes),updated_at=now() WHERE id=p_request_id;
 RETURN p_request_id;
END $$;


--
-- Name: cancel_purchase_order(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_purchase_order(p_purchase_order_id uuid, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_st public.procurement_doc_status;
  v_recv NUMERIC;
  v_po public.purchase_orders%ROWTYPE;
  v_rel RECORD;
  v_restore_value NUMERIC := 0;
BEGIN
  PERFORM public._procurement_begin_rpc();
  PERFORM public._require_procurement_staff();
  PERFORM public._assert_procurement_period_open();

  SELECT * INTO v_po FROM public.purchase_orders WHERE id = p_purchase_order_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'purchase order not found: %', p_purchase_order_id;
  END IF;
  v_st := v_po.status;

  IF v_st IN ('cancelled', 'rejected') THEN
    PERFORM public._procurement_end_rpc();
    RETURN p_purchase_order_id;
  END IF;

  SELECT COALESCE(SUM(qty_received), 0) INTO v_recv
  FROM public.purchase_order_lines
  WHERE purchase_order_id = p_purchase_order_id;

  IF v_recv > 0 THEN
    RAISE EXCEPTION 'cannot cancel PO with receipts';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.goods_receipts gr
    WHERE gr.purchase_order_id = p_purchase_order_id
      AND gr.status = 'submitted'
  ) THEN
    RAISE EXCEPTION 'cannot cancel PO with submitted GRNs';
  END IF;

  IF v_po.blanket_parent_id IS NOT NULL THEN
    PERFORM 1 FROM public.purchase_orders WHERE id = v_po.blanket_parent_id FOR UPDATE;

    FOR v_rel IN
      SELECT pol.qty_ordered, pol.blanket_parent_line_id
      FROM public.purchase_order_lines pol
      WHERE pol.purchase_order_id = p_purchase_order_id
        AND pol.blanket_parent_line_id IS NOT NULL
    LOOP
      UPDATE public.purchase_order_lines
      SET qty_released = qty_released - v_rel.qty_ordered
      WHERE id = v_rel.blanket_parent_line_id;

      UPDATE public.purchase_orders
      SET
        blanket_value_released = GREATEST(0, blanket_value_released - (v_rel.qty_ordered * (
          SELECT unit_price FROM public.purchase_order_lines WHERE id = v_rel.blanket_parent_line_id
        ))),
        updated_at = now()
      WHERE id = v_po.blanket_parent_id;
    END LOOP;
  END IF;

  UPDATE public.purchase_orders
  SET
    status = 'cancelled',
    cancelled_at = now(),
    notes = COALESCE(p_notes, notes),
    updated_at = now()
  WHERE id = p_purchase_order_id;

  PERFORM public._procurement_end_rpc();
  RETURN p_purchase_order_id;
EXCEPTION
  WHEN OTHERS THEN
    PERFORM public._procurement_end_rpc();
    RAISE;
END;
$$;


--
-- Name: cancel_rfq(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_rfq(p_rfq_id uuid, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_st public.procurement_doc_status;
  v_awarded UUID;
BEGIN
  PERFORM public._procurement_begin_rpc();
  PERFORM public._require_procurement_staff();
  PERFORM public._assert_procurement_period_open();

  SELECT status, awarded_quotation_id INTO v_st, v_awarded FROM public.rfqs WHERE id = p_rfq_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'RFQ not found: %', p_rfq_id;
  END IF;
  IF v_st = 'cancelled' THEN
    PERFORM public._procurement_end_rpc();
    RETURN p_rfq_id;
  END IF;
  IF v_awarded IS NOT NULL THEN
    RAISE EXCEPTION 'cannot cancel RFQ after award';
  END IF;

  UPDATE public.rfqs
  SET status = 'cancelled', cancelled_at = now(), notes = COALESCE(p_notes, notes), updated_at = now()
  WHERE id = p_rfq_id;

  PERFORM public._procurement_end_rpc();
  RETURN p_rfq_id;
EXCEPTION
  WHEN OTHERS THEN
    PERFORM public._procurement_end_rpc();
    RAISE;
END;
$$;


--
-- Name: cancel_stock_reconciliation(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_stock_reconciliation(p_reconciliation_id uuid, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_recon public.stock_reconciliations%ROWTYPE;
  v_line RECORD;
  v_delta NUMERIC;
  v_batch UUID;
  v_batch_code TEXT;
  v_rev UUID;
BEGIN
  PERFORM public._recon_begin_rpc();
  PERFORM public._require_warehouse_staff();

  SELECT * INTO v_recon
  FROM public.stock_reconciliations
  WHERE id = p_reconciliation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'reconciliation not found: %', p_reconciliation_id;
  END IF;
  IF v_recon.status <> 'posted' THEN
    RAISE EXCEPTION 'only posted reconciliations can be cancelled (status=%)', v_recon.status;
  END IF;

  IF public.is_period_locked(CURRENT_DATE) THEN
    RAISE EXCEPTION 'accounting period is locked for today';
  END IF;

  FOR v_line IN
    SELECT *
    FROM public.stock_reconciliation_lines
    WHERE stock_reconciliation_id = p_reconciliation_id
      AND variance_qty <> 0
  LOOP
    v_delta := -v_line.variance_qty;

    IF v_delta > 0 THEN
      v_batch_code := public.next_series_value('BATCH-');
      INSERT INTO public.stock_batches (
        batch_code, stock_item_id, warehouse_id, valuation_method,
        unit_cost, currency, qty_on_hand
      )
      VALUES (
        v_batch_code,
        v_line.stock_item_id,
        v_recon.warehouse_id,
        v_line.valuation_method,
        v_line.unit_cost,
        v_line.currency,
        v_delta
      )
      RETURNING id INTO v_batch;

      PERFORM public._adjust_stock_level(
        v_line.stock_item_id,
        v_recon.warehouse_id,
        v_delta,
        v_line.valuation_method,
        v_line.unit_cost,
        v_line.currency
      );
    ELSIF v_delta < 0 THEN
      PERFORM public._consume_fifo_batches(
        v_line.stock_item_id,
        v_recon.warehouse_id,
        abs(v_delta)
      );

      PERFORM public._adjust_stock_level(
        v_line.stock_item_id,
        v_recon.warehouse_id,
        v_delta,
        v_line.valuation_method,
        v_line.unit_cost,
        v_line.currency
      );
    END IF;
  END LOOP;

  IF v_recon.journal_entry_id IS NOT NULL THEN
    v_rev := public._reverse_journal_inventory(
      v_recon.journal_entry_id,
      COALESCE(
        p_notes,
        format('Cancel stock reconciliation %s', COALESCE(v_recon.document_number, p_reconciliation_id::text))
      )
    );
  END IF;

  UPDATE public.stock_reconciliations
  SET
    status = 'cancelled',
    reversal_journal_entry_id = v_rev,
    notes = COALESCE(p_notes, notes)
  WHERE id = p_reconciliation_id;

  PERFORM public.emit_domain_event(
    'stock_reconciliation_cancelled',
    'stock_reconciliation:cancelled:' || p_reconciliation_id::text,
    jsonb_build_object(
      'stock_reconciliation_id', p_reconciliation_id,
      'reversal_journal_entry_id', v_rev
    )
  );

  RETURN p_reconciliation_id;
END;
$$;


--
-- Name: cancel_supplier_quotation(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_supplier_quotation(p_supplier_quotation_id uuid, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_sq public.supplier_quotations%ROWTYPE;
BEGIN
  PERFORM public._procurement_begin_rpc();
  SELECT * INTO v_sq FROM public.supplier_quotations WHERE id = p_supplier_quotation_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'quotation not found: %', p_supplier_quotation_id;
  END IF;

  IF v_sq.status = 'cancelled' THEN
    PERFORM public._procurement_end_rpc();
    RETURN p_supplier_quotation_id;
  END IF;

  IF v_sq.supplier_id = public.current_supplier_id() THEN
    IF v_sq.status <> 'draft' THEN
      RAISE EXCEPTION 'suppliers can only cancel draft quotations';
    END IF;
  ELSE
    PERFORM public._require_procurement_staff();
    PERFORM public._assert_procurement_period_open();
  END IF;

  UPDATE public.supplier_quotations
  SET status = 'cancelled', cancelled_at = now(), notes = COALESCE(p_notes, notes), updated_at = now()
  WHERE id = p_supplier_quotation_id;

  PERFORM public._procurement_end_rpc();
  RETURN p_supplier_quotation_id;
EXCEPTION
  WHEN OTHERS THEN
    PERFORM public._procurement_end_rpc();
    RAISE;
END;
$$;


--
-- Name: canonical_staff_drift(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_staff_drift() RETURNS TABLE(user_id uuid, email text, role public.staff_role, auth_present boolean, email_matches boolean, email_confirmed boolean, provisioned_via_hr boolean, profile_present boolean, is_staff boolean, role_matches boolean, no_extra_roles boolean, in_sync boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
  SELECT
    c.user_id,
    c.email,
    c.role,
    u.id IS NOT NULL AS auth_present,
    COALESCE(lower(u.email) = c.email, false) AS email_matches,
    COALESCE(u.email_confirmed_at IS NOT NULL, false) AS email_confirmed,
    COALESCE(u.raw_app_meta_data ->> 'gtr_provisioned_via' = 'hr_onboarding', false) AS provisioned_via_hr,
    p.id IS NOT NULL AS profile_present,
    COALESCE(p.is_staff, false) AS is_staff,
    EXISTS (
      SELECT 1 FROM public.staff_roles sr
      WHERE sr.user_id = c.user_id AND sr.role = c.role
    ) AS role_matches,
    NOT EXISTS (
      SELECT 1 FROM public.staff_roles sr
      WHERE sr.user_id = c.user_id AND sr.role <> c.role
    ) AS no_extra_roles,
    (
      u.id IS NOT NULL
      AND lower(u.email) = c.email
      AND u.email_confirmed_at IS NOT NULL
      AND u.raw_app_meta_data ->> 'gtr_provisioned_via' = 'hr_onboarding'
      AND p.id IS NOT NULL
      AND p.is_staff IS TRUE
      AND EXISTS (
        SELECT 1 FROM public.staff_roles sr
        WHERE sr.user_id = c.user_id AND sr.role = c.role
      )
      AND NOT EXISTS (
        SELECT 1 FROM public.staff_roles sr
        WHERE sr.user_id = c.user_id AND sr.role <> c.role
      )
    ) AS in_sync
  FROM public.canonical_staff_accounts c
  LEFT JOIN auth.users u ON u.id = c.user_id
  LEFT JOIN public.profiles p ON p.id = c.user_id
  WHERE c.is_active
  ORDER BY c.email;
$$;


--
-- Name: FUNCTION canonical_staff_drift(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.canonical_staff_drift() IS 'Server-only authority gate: verifies canonical staff Auth/profile/role state without exposing secrets.';


--
-- Name: capture_delivery_line_cost_basis(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.capture_delivery_line_cost_basis() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_old_cost numeric:=COALESCE(OLD.unit_cost,0);
  v_new_cost numeric:=COALESCE(NEW.unit_cost,0);
  v_delta numeric;
  v_existing numeric;
  v_fulfilled numeric;
  v_new_total numeric;
BEGIN
  IF NEW.sales_invoice_line_id IS NULL OR COALESCE(NEW.qty_base,0)<=0 THEN
    RETURN NEW;
  END IF;
  IF v_old_cost IS NOT DISTINCT FROM v_new_cost THEN
    RETURN NEW;
  END IF;

  SELECT sil.cost_total_basis,sil.qty_fulfilled
    INTO v_existing,v_fulfilled
  FROM public.sales_invoice_lines sil
  WHERE sil.id=NEW.sales_invoice_line_id
  FOR UPDATE;
  IF NOT FOUND THEN RETURN NEW; END IF;

  v_delta:=round((v_new_cost-v_old_cost)*NEW.qty_base,4);
  v_new_total:=GREATEST(0,COALESCE(v_existing,0)+v_delta);

  UPDATE public.sales_invoice_lines
  SET cost_total_basis=v_new_total,
      unit_cost_basis=CASE
        WHEN COALESCE(v_fulfilled,0)+NEW.qty_base>0
          THEN round(v_new_total/(COALESCE(v_fulfilled,0)+NEW.qty_base),6)
        ELSE NULL
      END
  WHERE id=NEW.sales_invoice_line_id;
  RETURN NEW;
END;
$$;


--
-- Name: capture_return_refund_exchange_rate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.capture_return_refund_exchange_rate() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE v_rate numeric; v_currency public.currency_code;
BEGIN
  SELECT si.exchange_rate_applied,si.currency INTO v_rate,v_currency
  FROM public.sales_invoices si WHERE si.id=NEW.source_invoice_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'source invoice required for refund'; END IF;
  NEW.exchange_rate_applied:=CASE WHEN v_currency='USD' THEN COALESCE(v_rate,1) ELSE v_rate END;
  IF NEW.exchange_rate_applied IS NULL OR NEW.exchange_rate_applied<=0 THEN
    RAISE EXCEPTION 'valid source invoice exchange rate required for refund';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: capture_sales_invoice_line_cost_basis(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.capture_sales_invoice_line_cost_basis() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_doc_type public.sales_doc_type;
  v_wh uuid;
  v_cost numeric;
BEGIN
  IF NEW.is_core_charge OR NOT COALESCE(NEW.issues_stock,true) OR COALESCE(NEW.qty_fulfilled,0)<=0 THEN
    RETURN NEW;
  END IF;
  IF NEW.unit_cost_basis IS NOT NULL AND NEW.cost_total_basis>0 THEN
    RETURN NEW;
  END IF;

  SELECT si.doc_type,si.warehouse_id INTO v_doc_type,v_wh
  FROM public.sales_invoices si WHERE si.id=NEW.invoice_id;
  IF v_doc_type IS DISTINCT FROM 'invoice'::public.sales_doc_type THEN
    RETURN NEW;
  END IF;

  SELECT sl.unit_cost INTO v_cost
  FROM public.stock_levels sl
  WHERE sl.stock_item_id=NEW.stock_item_id AND sl.warehouse_id=v_wh;

  NEW.unit_cost_basis:=COALESCE(v_cost,0);
  NEW.cost_total_basis:=round(COALESCE(v_cost,0)*COALESCE(NEW.qty_fulfilled,0),4);
  RETURN NEW;
END;
$$;


--
-- Name: catalog_commerce_stock_for_oems(text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.catalog_commerce_stock_for_oems(p_oems text[]) RETURNS TABLE(normalized_oem text, stock_item_id uuid, oem_part_number text, description text, saleable_qty numeric, reorder_point numeric, unit_price numeric, currency text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
WITH wanted AS (
  SELECT DISTINCT upper(regexp_replace(x,'[^A-Z0-9]','','g')) normalized_oem
  FROM unnest(coalesce(p_oems,array[]::text[])) u(x)
  WHERE coalesce(trim(x),'')<>''
),
stock AS (
  SELECT
    si.id,
    si.oem_part_number::text,
    si.description,
    si.reorder_point,
    upper(regexp_replace(si.oem_part_number::text,'[^A-Z0-9]','','g')) normalized_oem,
    coalesce(sum(CASE WHEN w.is_active AND NOT w.is_quarantine THEN sl.quantity ELSE 0 END),0) saleable_qty
  FROM public.stock_items si
  LEFT JOIN public.stock_levels sl ON sl.stock_item_id=si.id
  LEFT JOIN public.warehouses w ON w.id=sl.warehouse_id
  JOIN wanted x ON x.normalized_oem=upper(regexp_replace(si.oem_part_number::text,'[^A-Z0-9]','','g'))
  GROUP BY si.id,si.oem_part_number,si.description,si.reorder_point
)
SELECT
  s.normalized_oem,
  s.id,
  s.oem_part_number,
  s.description,
  s.saleable_qty,
  CASE
    WHEN auth.role()='service_role'
      OR public.has_staff_role(ARRAY['admin','warehouse','finance','sales']::public.staff_role[])
    THEN s.reorder_point
    ELSE NULL::numeric
  END AS reorder_point,
  pli.unit_price,
  pl.currency::text
FROM stock s
LEFT JOIN LATERAL (
  SELECT pli0.unit_price,pli0.price_list_id
  FROM public.price_list_items pli0
  JOIN public.price_lists pl0 ON pl0.id=pli0.price_list_id
  WHERE pli0.stock_item_id=s.id AND pl0.is_active=true
  ORDER BY pl0.is_default DESC,(pl0.code='RETAIL') DESC,pl0.created_at ASC
  LIMIT 1
) pli ON true
LEFT JOIN public.price_lists pl ON pl.id=pli.price_list_id;
$$;


--
-- Name: catalog_offline_current_release_public(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.catalog_offline_current_release_public() RETURNS TABLE(release_id uuid, version text, schema_version integer, r2_object_key text, encrypted_size_bytes bigint, encrypted_sha256 text, sqlite_page_size integer, encryption_format text, vehicle_count bigint, section_count bigint, diagram_count bigint, fitment_count bigint, image_count bigint, source_release text, published_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select id,version,schema_version,r2_object_key,encrypted_size_bytes,encrypted_sha256,sqlite_page_size,encryption_format,vehicle_count,section_count,diagram_count,fitment_count,image_count,source_release,published_at
  from public.catalog_offline_releases where maker_slug='nissan' and is_current and published_at is not null order by published_at desc limit 1
$$;


--
-- Name: catalog_offline_current_release_secret(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.catalog_offline_current_release_secret() RETURNS TABLE(release_id uuid, version text, schema_version integer, r2_object_key text, encrypted_size_bytes bigint, encrypted_sha256 text, sqlite_page_size integer, encryption_format text, vehicle_count bigint, section_count bigint, diagram_count bigint, fitment_count bigint, image_count bigint, source_release text, content_key_b64 text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'vault'
    AS $$
declare v public.catalog_offline_releases%rowtype;
begin
  select * into v
  from public.catalog_offline_releases
  where maker_slug='nissan' and is_current and published_at is not null
  order by published_at desc
  limit 1;
  if not found then
    raise exception 'offline Nissan catalog release unavailable';
  end if;
  return query
  select v.id, v.version, v.schema_version, v.r2_object_key,
         v.encrypted_size_bytes, v.encrypted_sha256, v.sqlite_page_size,
         v.encryption_format, v.vehicle_count, v.section_count, v.diagram_count,
         v.fitment_count, v.image_count, v.source_release,
         ds.decrypted_secret
  from vault.decrypted_secrets ds
  where ds.name = v.key_secret_name
  limit 1;
  if not found then
    raise exception 'offline Nissan catalog key unavailable';
  end if;
end;
$$;


--
-- Name: catalog_offline_device_is_revoked(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.catalog_offline_device_is_revoked(p_release_id uuid, p_user_id uuid, p_device_key_sha256 text, p_app_flavor text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce((select revoked_at is not null from public.catalog_offline_device_grants where release_id=p_release_id and user_id=p_user_id and device_key_sha256=p_device_key_sha256 and app_flavor=p_app_flavor),false)
$$;


--
-- Name: catalog_offline_record_device_grant(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.catalog_offline_record_device_grant(p_release_id uuid, p_user_id uuid, p_device_key_sha256 text, p_app_flavor text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if p_app_flavor not in ('phone','tablet') then raise exception 'invalid app flavor'; end if;
  insert into public.catalog_offline_device_grants(release_id,user_id,device_key_sha256,app_flavor)
  values(p_release_id,p_user_id,p_device_key_sha256,p_app_flavor)
  on conflict(release_id,user_id,device_key_sha256,app_flavor)
  do update set last_granted_at=now(), revoked_at=null;
end;$$;


--
-- Name: catalog_r2_presign_batch(text, text, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.catalog_r2_presign_batch(p_build_token text, p_object_kind text, p_offset integer DEFAULT 0, p_limit integer DEFAULT 200, p_expires integer DEFAULT 900) RETURNS TABLE(scope_key text, object_key text, sha256 text, row_count integer, bytes bigint, content_encoding text, url text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_release uuid;
BEGIN
  IF encode(extensions.digest(COALESCE(p_build_token,''),'sha256'),'hex') <> 'd8338aceaf5fcf41c4bfd0eb968c14e614344ebe590f6ab4cd5183c1dc1f4a4c' THEN RAISE EXCEPTION 'invalid build token'; END IF;
  IF p_object_kind NOT IN ('vehicle_search','vehicle_fitment','section_parts','diagram_parts','diagram_image') THEN RAISE EXCEPTION 'unsupported kind'; END IF;
  SELECT id INTO v_release FROM public.catalog_releases WHERE maker_slug='nissan' AND is_current AND published_at IS NOT NULL ORDER BY published_at DESC LIMIT 1;
  IF v_release IS NULL THEN RAISE EXCEPTION 'current Nissan release missing'; END IF;
  RETURN QUERY
  SELECT o.scope_key,o.object_key,o.sha256,o.row_count,o.bytes,o.content_encoding,public.catalog_r2_presign_get(o.object_key,p_expires)
  FROM public.catalog_r2_serving_objects o
  WHERE o.release_id=v_release AND o.maker_slug='nissan' AND o.object_kind=p_object_kind
  ORDER BY o.scope_key,o.object_key
  OFFSET GREATEST(COALESCE(p_offset,0),0)
  LIMIT GREATEST(1,LEAST(COALESCE(p_limit,200),500));
END; $$;


--
-- Name: FUNCTION catalog_r2_presign_batch(p_build_token text, p_object_kind text, p_offset integer, p_limit integer, p_expires integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.catalog_r2_presign_batch(p_build_token text, p_object_kind text, p_offset integer, p_limit integer, p_expires integer) IS 'Temporary token-gated release bootstrap channel; returns expiring R2 URLs, never credentials.';


--
-- Name: catalog_r2_presign_get(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.catalog_r2_presign_get(p_object_key text, p_expires integer DEFAULT 600) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'vault'
    AS $$
DECLARE
  account_id text;
  access_key text;
  secret_key text;
  bucket text;
  host text;
  canonical_uri text;
  amz_date text;
  date_stamp text;
  scope text;
  credential text;
  canonical_query text;
  canonical_headers text;
  canonical_request text;
  string_to_sign text;
BEGIN
  IF p_object_key IS NULL OR trim(p_object_key) = '' THEN RAISE EXCEPTION 'object key required'; END IF;
  p_expires := GREATEST(60, LEAST(COALESCE(p_expires,600), 3600));
  SELECT decrypted_secret INTO account_id FROM vault.decrypted_secrets WHERE name='catalog_r2_account_id';
  SELECT decrypted_secret INTO access_key FROM vault.decrypted_secrets WHERE name='catalog_r2_access_key_id';
  SELECT decrypted_secret INTO secret_key FROM vault.decrypted_secrets WHERE name='catalog_r2_secret_access_key';
  SELECT decrypted_secret INTO bucket FROM vault.decrypted_secrets WHERE name='catalog_r2_bucket';
  IF account_id IS NULL OR access_key IS NULL OR secret_key IS NULL OR bucket IS NULL THEN RAISE EXCEPTION 'R2 Vault configuration incomplete'; END IF;
  host := account_id || '.r2.cloudflarestorage.com';
  canonical_uri := '/' || public._aws_uri_encode(bucket, true) || '/' || public._aws_uri_encode(trim(p_object_key), false);
  amz_date := to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYYMMDD"T"HH24MISS"Z"');
  date_stamp := substring(amz_date from 1 for 8);
  scope := date_stamp || '/auto/s3/aws4_request';
  credential := access_key || '/' || scope;
  canonical_query := 'X-Amz-Algorithm=AWS4-HMAC-SHA256' || '&X-Amz-Credential=' || public._aws_uri_encode(credential, true) || '&X-Amz-Date=' || amz_date || '&X-Amz-Expires=' || p_expires::text || '&X-Amz-SignedHeaders=host';
  canonical_headers := 'host:' || host || E'\n';
  canonical_request := 'GET' || E'\n' || canonical_uri || E'\n' || canonical_query || E'\n' || canonical_headers || E'\n' || 'host' || E'\n' || 'UNSIGNED-PAYLOAD';
  string_to_sign := 'AWS4-HMAC-SHA256' || E'\n' || amz_date || E'\n' || scope || E'\n' || encode(extensions.digest(canonical_request, 'sha256'), 'hex');
  RETURN 'https://' || host || canonical_uri || '?' || canonical_query || '&X-Amz-Signature=' || encode(
    extensions.hmac(convert_to(string_to_sign,'UTF8'), extensions.hmac(convert_to('aws4_request','UTF8'), extensions.hmac(convert_to('s3','UTF8'), extensions.hmac(convert_to('auto','UTF8'), extensions.hmac(convert_to(date_stamp,'UTF8'), convert_to('AWS4' || secret_key,'UTF8'), 'sha256'), 'sha256'), 'sha256'), 'sha256'), 'sha256'), 'hex');
END;
$$;


--
-- Name: FUNCTION catalog_r2_presign_get(p_object_key text, p_expires integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.catalog_r2_presign_get(p_object_key text, p_expires integer) IS 'Release tooling only: short-lived R2 GET URL generated from Vault without exporting credentials.';


--
-- Name: catalog_r2_presign_list(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.catalog_r2_presign_list(p_prefix text DEFAULT ''::text, p_expires integer DEFAULT 600) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'vault'
    AS $$
DECLARE
  account_id text; access_key text; secret_key text; bucket text;
  host text; canonical_uri text; amz_date text; date_stamp text; scope text; credential text;
  canonical_query text; canonical_headers text; canonical_request text; string_to_sign text;
BEGIN
  p_expires := GREATEST(60, LEAST(COALESCE(p_expires,600),3600));
  SELECT decrypted_secret INTO account_id FROM vault.decrypted_secrets WHERE name='catalog_r2_account_id';
  SELECT decrypted_secret INTO access_key FROM vault.decrypted_secrets WHERE name='catalog_r2_access_key_id';
  SELECT decrypted_secret INTO secret_key FROM vault.decrypted_secrets WHERE name='catalog_r2_secret_access_key';
  SELECT decrypted_secret INTO bucket FROM vault.decrypted_secrets WHERE name='catalog_r2_bucket';
  IF account_id IS NULL OR access_key IS NULL OR secret_key IS NULL OR bucket IS NULL THEN RAISE EXCEPTION 'R2 Vault configuration incomplete'; END IF;
  host := account_id || '.r2.cloudflarestorage.com';
  canonical_uri := '/' || public._aws_uri_encode(bucket,true);
  amz_date := to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYYMMDD"T"HH24MISS"Z"');
  date_stamp := substring(amz_date from 1 for 8); scope := date_stamp || '/auto/s3/aws4_request'; credential := access_key || '/' || scope;
  canonical_query := 'X-Amz-Algorithm=AWS4-HMAC-SHA256' || '&X-Amz-Credential=' || public._aws_uri_encode(credential,true)
    || '&X-Amz-Date=' || amz_date || '&X-Amz-Expires=' || p_expires::text || '&X-Amz-SignedHeaders=host'
    || '&list-type=2&max-keys=1000&prefix=' || public._aws_uri_encode(COALESCE(p_prefix,''),true);
  canonical_headers := 'host:' || host || E'\n';
  canonical_request := 'GET' || E'\n' || canonical_uri || E'\n' || canonical_query || E'\n' || canonical_headers || E'\n' || 'host' || E'\n' || 'UNSIGNED-PAYLOAD';
  string_to_sign := 'AWS4-HMAC-SHA256' || E'\n' || amz_date || E'\n' || scope || E'\n' || encode(extensions.digest(canonical_request,'sha256'),'hex');
  RETURN 'https://' || host || canonical_uri || '?' || canonical_query || '&X-Amz-Signature=' || encode(
    extensions.hmac(convert_to(string_to_sign,'UTF8'),
      extensions.hmac(convert_to('aws4_request','UTF8'),
        extensions.hmac(convert_to('s3','UTF8'),
          extensions.hmac(convert_to('auto','UTF8'),
            extensions.hmac(convert_to(date_stamp,'UTF8'),convert_to('AWS4'||secret_key,'UTF8'),'sha256'),'sha256'),'sha256'),'sha256'),'sha256'),'hex');
END; $$;


--
-- Name: catalog_r2_presign_list_after(text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.catalog_r2_presign_list_after(p_prefix text, p_start_after text DEFAULT ''::text, p_max_keys integer DEFAULT 1000, p_expires integer DEFAULT 600) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'vault'
    AS $$ DECLARE account_id text; access_key text; secret_key text; bucket text; host text; canonical_uri text; amz_date text; date_stamp text; scope text; credential text; canonical_query text; canonical_headers text; canonical_request text; string_to_sign text; BEGIN p_max_keys:=GREATEST(1,LEAST(COALESCE(p_max_keys,1000),1000)); p_expires:=GREATEST(60,LEAST(COALESCE(p_expires,600),3600)); SELECT decrypted_secret INTO account_id FROM vault.decrypted_secrets WHERE name='catalog_r2_account_id'; SELECT decrypted_secret INTO access_key FROM vault.decrypted_secrets WHERE name='catalog_r2_access_key_id'; SELECT decrypted_secret INTO secret_key FROM vault.decrypted_secrets WHERE name='catalog_r2_secret_access_key'; SELECT decrypted_secret INTO bucket FROM vault.decrypted_secrets WHERE name='catalog_r2_bucket'; IF account_id IS NULL OR access_key IS NULL OR secret_key IS NULL OR bucket IS NULL THEN RAISE EXCEPTION 'R2 Vault configuration incomplete'; END IF; host:=account_id||'.r2.cloudflarestorage.com'; canonical_uri:='/'||public._aws_uri_encode(bucket,true); amz_date:=to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYYMMDD"T"HH24MISS"Z"'); date_stamp:=substring(amz_date from 1 for 8); scope:=date_stamp||'/auto/s3/aws4_request'; credential:=access_key||'/'||scope; canonical_query:='X-Amz-Algorithm=AWS4-HMAC-SHA256'||'&X-Amz-Credential='||public._aws_uri_encode(credential,true)||'&X-Amz-Date='||amz_date||'&X-Amz-Expires='||p_expires::text||'&X-Amz-SignedHeaders=host'||'&list-type=2&max-keys='||p_max_keys::text||'&prefix='||public._aws_uri_encode(COALESCE(p_prefix,''),true); IF COALESCE(p_start_after,'')<>'' THEN canonical_query:=canonical_query||'&start-after='||public._aws_uri_encode(p_start_after,true); END IF; canonical_headers:='host:'||host||E'\n'; canonical_request:='GET'||E'\n'||canonical_uri||E'\n'||canonical_query||E'\n'||canonical_headers||E'\n'||'host'||E'\n'||'UNSIGNED-PAYLOAD'; string_to_sign:='AWS4-HMAC-SHA256'||E'\n'||amz_date||E'\n'||scope||E'\n'||encode(extensions.digest(canonical_request,'sha256'),'hex'); RETURN 'https://'||host||canonical_uri||'?'||canonical_query||'&X-Amz-Signature='||encode(extensions.hmac(convert_to(string_to_sign,'UTF8'),extensions.hmac(convert_to('aws4_request','UTF8'),extensions.hmac(convert_to('s3','UTF8'),extensions.hmac(convert_to('auto','UTF8'),extensions.hmac(convert_to(date_stamp,'UTF8'),convert_to('AWS4'||secret_key,'UTF8'),'sha256'),'sha256'),'sha256'),'sha256'),'sha256'),'hex'); END; $$;


--
-- Name: catalog_r2_presign_list_page(text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.catalog_r2_presign_list_page(p_prefix text, p_continuation_token text DEFAULT NULL::text, p_max_keys integer DEFAULT 1000, p_expires integer DEFAULT 600) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'vault'
    AS $$
DECLARE
  account_id text;
  access_key text;
  secret_key text;
  bucket text;
  host text;
  canonical_uri text;
  amz_date text;
  date_stamp text;
  scope text;
  credential text;
  service_query text;
  canonical_query text;
  canonical_headers text;
  canonical_request text;
  string_to_sign text;
BEGIN
  IF p_prefix IS NULL THEN p_prefix := ''; END IF;
  p_max_keys := GREATEST(1, LEAST(COALESCE(p_max_keys,1000),1000));
  p_expires := GREATEST(60, LEAST(COALESCE(p_expires,600),3600));
  SELECT decrypted_secret INTO account_id FROM vault.decrypted_secrets WHERE name='catalog_r2_account_id';
  SELECT decrypted_secret INTO access_key FROM vault.decrypted_secrets WHERE name='catalog_r2_access_key_id';
  SELECT decrypted_secret INTO secret_key FROM vault.decrypted_secrets WHERE name='catalog_r2_secret_access_key';
  SELECT decrypted_secret INTO bucket FROM vault.decrypted_secrets WHERE name='catalog_r2_bucket';
  IF account_id IS NULL OR access_key IS NULL OR secret_key IS NULL OR bucket IS NULL THEN
    RAISE EXCEPTION 'R2 Vault configuration incomplete';
  END IF;
  host := account_id || '.r2.cloudflarestorage.com';
  canonical_uri := '/' || public._aws_uri_encode(bucket, true) || '/';
  amz_date := to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYYMMDD"T"HH24MISS"Z"');
  date_stamp := substring(amz_date from 1 for 8);
  scope := date_stamp || '/auto/s3/aws4_request';
  credential := access_key || '/' || scope;
  service_query := CASE WHEN NULLIF(p_continuation_token,'') IS NOT NULL
      THEN 'continuation-token=' || public._aws_uri_encode(p_continuation_token, true) || '&'
      ELSE '' END
    || 'list-type=2'
    || '&max-keys=' || p_max_keys::text
    || '&prefix=' || public._aws_uri_encode(p_prefix, true);
  canonical_query := 'X-Amz-Algorithm=AWS4-HMAC-SHA256'
    || '&X-Amz-Credential=' || public._aws_uri_encode(credential, true)
    || '&X-Amz-Date=' || amz_date
    || '&X-Amz-Expires=' || p_expires::text
    || '&X-Amz-SignedHeaders=host'
    || '&' || service_query;
  canonical_headers := 'host:' || host || E'\n';
  canonical_request := 'GET' || E'\n' || canonical_uri || E'\n' || canonical_query || E'\n'
    || canonical_headers || E'\n' || 'host' || E'\n' || 'UNSIGNED-PAYLOAD';
  string_to_sign := 'AWS4-HMAC-SHA256' || E'\n' || amz_date || E'\n' || scope || E'\n'
    || encode(extensions.digest(canonical_request, 'sha256'), 'hex');
  RETURN 'https://' || host || canonical_uri || '?' || canonical_query || '&X-Amz-Signature=' || encode(
    extensions.hmac(
      convert_to(string_to_sign,'UTF8'),
      extensions.hmac(
        convert_to('aws4_request','UTF8'),
        extensions.hmac(
          convert_to('s3','UTF8'),
          extensions.hmac(
            convert_to('auto','UTF8'),
            extensions.hmac(convert_to(date_stamp,'UTF8'),convert_to('AWS4'||secret_key,'UTF8'),'sha256'),
            'sha256'
          ),'sha256'
        ),'sha256'
      ),'sha256'
    ),'hex'
  );
END;
$$;


--
-- Name: FUNCTION catalog_r2_presign_list_page(p_prefix text, p_continuation_token text, p_max_keys integer, p_expires integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.catalog_r2_presign_list_page(p_prefix text, p_continuation_token text, p_max_keys integer, p_expires integer) IS 'Release tooling only: short-lived R2 ListObjectsV2 URL generated from Vault without exporting credentials.';


