--

CREATE FUNCTION public.catalog_r2_presign_prefixes(p_prefix text DEFAULT ''::text, p_expires integer DEFAULT 600) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'vault'
    AS $$
DECLARE account_id text; access_key text; secret_key text; bucket text; host text; canonical_uri text; amz_date text; date_stamp text; scope text; credential text; canonical_query text; canonical_headers text; canonical_request text; string_to_sign text;
BEGIN
 p_expires:=GREATEST(60,LEAST(COALESCE(p_expires,600),3600));
 SELECT decrypted_secret INTO account_id FROM vault.decrypted_secrets WHERE name='catalog_r2_account_id';
 SELECT decrypted_secret INTO access_key FROM vault.decrypted_secrets WHERE name='catalog_r2_access_key_id';
 SELECT decrypted_secret INTO secret_key FROM vault.decrypted_secrets WHERE name='catalog_r2_secret_access_key';
 SELECT decrypted_secret INTO bucket FROM vault.decrypted_secrets WHERE name='catalog_r2_bucket';
 IF account_id IS NULL OR access_key IS NULL OR secret_key IS NULL OR bucket IS NULL THEN RAISE EXCEPTION 'R2 Vault configuration incomplete'; END IF;
 host:=account_id||'.r2.cloudflarestorage.com'; canonical_uri:='/'||public._aws_uri_encode(bucket,true);
 amz_date:=to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYYMMDD"T"HH24MISS"Z"'); date_stamp:=substring(amz_date from 1 for 8); scope:=date_stamp||'/auto/s3/aws4_request'; credential:=access_key||'/'||scope;
 canonical_query:='X-Amz-Algorithm=AWS4-HMAC-SHA256'||'&X-Amz-Credential='||public._aws_uri_encode(credential,true)||'&X-Amz-Date='||amz_date||'&X-Amz-Expires='||p_expires::text||'&X-Amz-SignedHeaders=host&delimiter=%2F&list-type=2&max-keys=1000&prefix='||public._aws_uri_encode(COALESCE(p_prefix,''),true);
 canonical_headers:='host:'||host||E'\n'; canonical_request:='GET'||E'\n'||canonical_uri||E'\n'||canonical_query||E'\n'||canonical_headers||E'\n'||'host'||E'\n'||'UNSIGNED-PAYLOAD'; string_to_sign:='AWS4-HMAC-SHA256'||E'\n'||amz_date||E'\n'||scope||E'\n'||encode(extensions.digest(canonical_request,'sha256'),'hex');
 RETURN 'https://'||host||canonical_uri||'?'||canonical_query||'&X-Amz-Signature='||encode(extensions.hmac(convert_to(string_to_sign,'UTF8'),extensions.hmac(convert_to('aws4_request','UTF8'),extensions.hmac(convert_to('s3','UTF8'),extensions.hmac(convert_to('auto','UTF8'),extensions.hmac(convert_to(date_stamp,'UTF8'),convert_to('AWS4'||secret_key,'UTF8'),'sha256'),'sha256'),'sha256'),'sha256'),'sha256'),'hex');
END; $$;


--
-- Name: catalog_r2_runtime_config(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.catalog_r2_runtime_config() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'vault'
    AS $$
declare v jsonb;
begin
  if auth.role() <> 'service_role' then raise exception 'service_role required'; end if;
  select jsonb_build_object(
    'account_id', max(decrypted_secret) filter (where name='catalog_r2_account_id'),
    'access_key_id', max(decrypted_secret) filter (where name='catalog_r2_access_key_id'),
    'secret_access_key', max(decrypted_secret) filter (where name='catalog_r2_secret_access_key'),
    'bucket', max(decrypted_secret) filter (where name='catalog_r2_bucket'),
    'endpoint', max(decrypted_secret) filter (where name='catalog_r2_endpoint')
  ) into v from vault.decrypted_secrets
  where name in ('catalog_r2_account_id','catalog_r2_access_key_id','catalog_r2_secret_access_key','catalog_r2_bucket','catalog_r2_endpoint');
  if coalesce(v->>'account_id','')='' or coalesce(v->>'access_key_id','')='' or coalesce(v->>'secret_access_key','')='' or coalesce(v->>'bucket','')='' then
    raise exception 'R2 runtime credentials are not configured';
  end if;
  return v;
end;
$$;


--
-- Name: catalog_r2_vehicle_master_list(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.catalog_r2_vehicle_master_list() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', r2_scope_key,
    'r2_scope_key', r2_scope_key,
    'maker_slug', maker_slug,
    'model', model,
    'chassis_code', chassis_code,
    'engine_code', engine_code,
    'year_start', year_start,
    'year_end', year_end,
    'sales_region', sales_region,
    'display_name', trim(concat_ws(' · ', 'Nissan ' || model, chassis_code, engine_code, case when year_start is not null or year_end is not null then concat(coalesce(year_start::text,''),'–',coalesce(year_end::text,'')) else null end)),
    'source_release_version', source_release_version
  ) order by model, year_start, chassis_code, engine_code, r2_scope_key), '[]'::jsonb)
  from public.catalog_r2_vehicle_master;
$$;


--
-- Name: catalog_r2_vehicle_master; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.catalog_r2_vehicle_master (
    r2_scope_key text NOT NULL,
    maker_slug text DEFAULT 'nissan'::text NOT NULL,
    model text NOT NULL,
    chassis_code text NOT NULL,
    engine_code text NOT NULL,
    year_start integer,
    year_end integer,
    sales_region text,
    source_release_version text DEFAULT 'v2-storage-2026-09'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT catalog_r2_vehicle_master_check CHECK (((year_start IS NULL) OR (year_end IS NULL) OR (year_end >= year_start))),
    CONSTRAINT catalog_r2_vehicle_master_maker_slug_check CHECK ((maker_slug = 'nissan'::text)),
    CONSTRAINT catalog_r2_vehicle_master_r2_scope_key_check CHECK ((r2_scope_key ~ '^VM-[0-9a-f]{28}$'::text))
);


--
-- Name: catalog_seed_vehicle_master(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.catalog_seed_vehicle_master(p_build_token text) RETURNS SETOF public.catalog_r2_vehicle_master
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  IF encode(extensions.digest(COALESCE(p_build_token,''),'sha256'),'hex') <> 'd8338aceaf5fcf41c4bfd0eb968c14e614344ebe590f6ab4cd5183c1dc1f4a4c' THEN RAISE EXCEPTION 'invalid build token'; END IF;
  RETURN QUERY SELECT * FROM public.catalog_r2_vehicle_master WHERE maker_slug='nissan' ORDER BY model,year_start,chassis_code,engine_code;
END; $$;


--
-- Name: catalog_v2_ingest_r2_serving_objects_batch(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.catalog_v2_ingest_r2_serving_objects_batch(p_rows jsonb) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_role text := coalesce(auth.jwt() ->> 'role', current_setting('request.jwt.claim.role', true), '');
  v_count bigint;
begin
  if v_role is distinct from 'service_role' then raise exception 'service_role required'; end if;
  if jsonb_typeof(p_rows) <> 'array' then raise exception 'p_rows must be a JSON array'; end if;
  insert into public.catalog_r2_serving_objects (release_id,maker_slug,object_kind,scope_key,object_key,sha256,row_count,bytes,content_type,content_encoding,metadata,updated_at)
  select (r->>'release_id')::uuid,lower(coalesce(nullif(trim(r->>'maker_slug'),''),'nissan')),trim(r->>'object_kind'),trim(r->>'scope_key'),trim(r->>'object_key'),nullif(lower(trim(r->>'sha256')),''),coalesce((r->>'row_count')::integer,0),coalesce((r->>'bytes')::bigint,0),coalesce(nullif(trim(r->>'content_type'),''),'application/json'),nullif(trim(r->>'content_encoding'),''),coalesce(r->'metadata','{}'::jsonb),now()
  from jsonb_array_elements(p_rows) as x(r)
  where nullif(trim(r->>'release_id'),'') is not null and nullif(trim(r->>'object_kind'),'') is not null and nullif(trim(r->>'scope_key'),'') is not null and nullif(trim(r->>'object_key'),'') is not null
  on conflict (release_id,object_kind,scope_key) do update set maker_slug=excluded.maker_slug,object_key=excluded.object_key,sha256=excluded.sha256,row_count=excluded.row_count,bytes=excluded.bytes,content_type=excluded.content_type,content_encoding=excluded.content_encoding,metadata=excluded.metadata,updated_at=now();
  get diagnostics v_count = row_count;
  return v_count;
end;
$$;


--
-- Name: chat_messages_after_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_messages_after_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE public.chat_threads
  SET
    last_message_at = NEW.created_at,
    updated_at = now()
  WHERE id = NEW.thread_id;

  INSERT INTO public.chat_participants (thread_id, user_id, role, last_read_at)
  VALUES (
    NEW.thread_id,
    NEW.sender_user_id,
    CASE
      WHEN NEW.sender_kind = 'staff' THEN 'staff'::public.chat_participant_role
      ELSE 'customer'::public.chat_participant_role
    END,
    NEW.created_at
  )
  ON CONFLICT (thread_id, user_id) DO UPDATE
  SET last_read_at = EXCLUDED.last_read_at;

  RETURN NEW;
END;
$$;


--
-- Name: chat_messages_immutable_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_messages_immutable_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    RAISE EXCEPTION 'chat_messages are immutable';
  END IF;
  IF TG_OP = 'DELETE' AND auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'chat_messages cannot be deleted by clients';
  END IF;
  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: chat_threads_protect_columns(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_threads_protect_columns() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  IF NEW.customer_user_id IS DISTINCT FROM OLD.customer_user_id
     OR NEW.customer_id IS DISTINCT FROM OLD.customer_id
     OR NEW.kind IS DISTINCT FROM OLD.kind
     OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'chat_threads identity columns are immutable';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: chat_threads_touch_updated(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_threads_touch_updated() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;


--
-- Name: chat_unread_count(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_unread_count(p_thread_id uuid DEFAULT NULL::uuid) RETURNS bigint
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COUNT(*)::bigint
  FROM public.chat_messages m
  JOIN public.chat_threads t ON t.id = m.thread_id
  LEFT JOIN public.chat_participants p
    ON p.thread_id = m.thread_id AND p.user_id = auth.uid()
  WHERE public._can_select_chat_thread(t)
    AND (p_thread_id IS NULL OR m.thread_id = p_thread_id)
    AND m.sender_user_id IS DISTINCT FROM auth.uid()
    AND (p.last_read_at IS NULL OR m.created_at > p.last_read_at);
$$;


--
-- Name: check_whatsapp_bot_rate_limit(text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_whatsapp_bot_rate_limit(p_wa_from text, p_max_requests integer DEFAULT 20, p_window_seconds integer DEFAULT 60) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_from text := regexp_replace(trim(coalesce(p_wa_from, '')), '\D', '', 'g');
  v_max int := LEAST(200, GREATEST(1, COALESCE(p_max_requests, 20)));
  v_window int := LEAST(3600, GREATEST(10, COALESCE(p_window_seconds, 60)));
  v_row public.whatsapp_bot_rate_limits%ROWTYPE;
  v_now timestamptz := clock_timestamp();
  v_allowed boolean;
  v_remaining int;
  v_retry int := 0;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'service_role required';
  END IF;

  IF v_from = '' THEN
    RAISE EXCEPTION 'wa_from required';
  END IF;

  INSERT INTO public.whatsapp_bot_rate_limits (
    wa_from, window_started_at, request_count, updated_at
  )
  VALUES (v_from, v_now, 0, v_now)
  ON CONFLICT (wa_from) DO NOTHING;

  SELECT * INTO STRICT v_row
  FROM public.whatsapp_bot_rate_limits
  WHERE wa_from = v_from
  FOR UPDATE;

  IF v_row.window_started_at + make_interval(secs => v_window) <= v_now THEN
    UPDATE public.whatsapp_bot_rate_limits
    SET
      window_started_at = v_now,
      request_count = 1,
      updated_at = v_now
    WHERE wa_from = v_from;
    v_allowed := true;
    v_remaining := v_max - 1;
  ELSIF v_row.request_count >= v_max THEN
    v_allowed := false;
    v_remaining := 0;
    v_retry := GREATEST(
      1,
      CEIL(
        EXTRACT(
          EPOCH FROM (
            v_row.window_started_at + make_interval(secs => v_window) - v_now
          )
        )
      )::int
    );
  ELSE
    UPDATE public.whatsapp_bot_rate_limits
    SET
      request_count = request_count + 1,
      updated_at = v_now
    WHERE wa_from = v_from;
    v_allowed := true;
    v_remaining := v_max - (v_row.request_count + 1);
  END IF;

  RETURN jsonb_build_object(
    'allowed', v_allowed,
    'remaining', GREATEST(0, v_remaining),
    'retry_after_seconds', v_retry,
    'max_requests', v_max,
    'window_seconds', v_window
  );
END;
$$;


--
-- Name: FUNCTION check_whatsapp_bot_rate_limit(p_wa_from text, p_max_requests integer, p_window_seconds integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.check_whatsapp_bot_rate_limit(p_wa_from text, p_max_requests integer, p_window_seconds integer) IS 'Consume one WhatsApp bot request for wa_from; returns allowed/remaining/retry_after. service_role only.';


