    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$ SELECT public.prepare_customer_checkout(p_cart_id,p_cart_id,interval '20 minutes'); $$;


--
-- Name: FUNCTION checkout_customer_cart(p_cart_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.checkout_customer_cart(p_cart_id uuid) IS 'Backward-compatible storefront checkout: stage immutable commerce order + reserve stock. Does not post invoice/journal or issue stock.';


