--
-- Name: checkout_customer_cart_v2(uuid, public.delivery_payment_method); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checkout_customer_cart_v2(p_cart_id uuid, p_delivery_payment_method public.delivery_payment_method DEFAULT 'prepay'::public.delivery_payment_method) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE c public.pos_carts%ROWTYPE; v_id UUID;
BEGIN
 PERFORM public._storefront_rpc_enter();
 BEGIN
  PERFORM public._assert_customer_owns_open_cart(p_cart_id);
  SELECT * INTO c FROM public.pos_carts WHERE id=p_cart_id FOR UPDATE;
  IF c.fulfillment_mode<>'dispatch' AND p_delivery_payment_method<>'prepay' THEN RAISE EXCEPTION 'pay-on-delivery requires dispatch fulfillment'; END IF;
  UPDATE public.pos_carts SET delivery_payment_method=p_delivery_payment_method,updated_at=now() WHERE id=c.id;
  v_id:=public.checkout_pos_cart(p_cart_id);
  UPDATE public.sales_invoices SET delivery_payment_method=p_delivery_payment_method WHERE id=v_id;
 EXCEPTION WHEN OTHERS THEN PERFORM public._storefront_rpc_exit(); RAISE; END;
 PERFORM public._storefront_rpc_exit(); RETURN v_id;
END $$;


--
-- Name: checkout_pos_cart(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checkout_pos_cart(p_cart_id uuid, p_receipt_email text DEFAULT NULL::text, p_receipt_whatsapp_e164 text DEFAULT NULL::text, p_receipt_phone_e164 text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_prev text := COALESCE(current_setting('app.pos_posting', true), '');
  v_result uuid;
BEGIN
  -- Role checks stay in _checkout_pos_cart_core; this only marks its ledger posting as internal.
  PERFORM set_config('app.pos_posting', '1', true);
  v_result := public._checkout_pos_cart_core(p_cart_id, p_receipt_email, p_receipt_whatsapp_e164, p_receipt_phone_e164);
  PERFORM set_config('app.pos_posting', v_prev, true);
  RETURN v_result;
END;
$$;


--
-- Name: FUNCTION checkout_pos_cart(p_cart_id uuid, p_receipt_email text, p_receipt_whatsapp_e164 text, p_receipt_phone_e164 text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.checkout_pos_cart(p_cart_id uuid, p_receipt_email text, p_receipt_whatsapp_e164 text, p_receipt_phone_e164 text) IS 'POS entry point. Logic lives in _checkout_pos_cart_core; change that, not this wrapper (see 20261001110000).';


--
-- Name: checkout_pos_cart_on_account(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checkout_pos_cart_on_account(p_cart_id uuid, p_receipt_email text DEFAULT NULL::text, p_receipt_whatsapp_e164 text DEFAULT NULL::text, p_receipt_phone_e164 text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_cart public.pos_carts%ROWTYPE; v_cust public.customers%ROWTYPE; v_total numeric; v_invoice uuid; v_owing numeric;
BEGIN
  PERFORM public._require_payments_staff();
  PERFORM public._require_cart_mutate(p_cart_id);
  SELECT * INTO v_cart FROM public.pos_carts WHERE id=p_cart_id FOR UPDATE;
  IF NOT FOUND OR v_cart.status<>'open' THEN RAISE EXCEPTION 'open cart required'; END IF;
  IF v_cart.customer_id IS NULL THEN RAISE EXCEPTION 'registered customer required for on-account checkout'; END IF;
  SELECT * INTO v_cust FROM public.customers WHERE id=v_cart.customer_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'customer not found'; END IF;
  PERFORM private.assert_customer_not_suspended(v_cust.id);
  IF v_cust.credit_hold THEN RAISE EXCEPTION 'customer is on credit hold'; END IF;
  IF COALESCE(v_cust.credit_limit,0)<=0 THEN RAISE EXCEPTION 'customer has no approved credit limit'; END IF;
  IF v_cart.currency IS DISTINCT FROM v_cust.currency THEN
    RAISE EXCEPTION 'on-account cart currency % must match customer account currency %',v_cart.currency,v_cust.currency;
  END IF;
  SELECT COALESCE(sum(line_total),0) INTO v_total FROM public.pos_cart_lines WHERE cart_id=p_cart_id;
  IF v_total<=0 THEN RAISE EXCEPTION 'cart total must be > 0'; END IF;
  -- Owing is every unpaid posted invoice in any currency, converted to the account currency at each
  -- invoice's own rate (customers.open_balance mixes currencies).
  v_owing := (private.customer_exposure(v_cust.id)->>'total')::numeric;
  IF v_owing IS NULL THEN RAISE EXCEPTION 'cannot check credit: no ZiG exchange rate set'; END IF;
  IF v_owing+v_total>v_cust.credit_limit THEN
    RAISE EXCEPTION 'insufficient customer credit: owing % %, cart %, limit %',v_cust.currency,v_owing,v_total,v_cust.credit_limit;
  END IF;

  PERFORM public._sales_checkout_accounting_enter();
  BEGIN
    v_invoice:=public.checkout_pos_cart(p_cart_id,p_receipt_email,p_receipt_whatsapp_e164,p_receipt_phone_e164);
  EXCEPTION WHEN OTHERS THEN
    PERFORM public._sales_checkout_accounting_exit();
    RAISE;
  END;
  PERFORM public._sales_checkout_accounting_exit();

  IF NOT EXISTS(SELECT 1 FROM public.sales_invoices si WHERE si.id=v_invoice AND si.status='posted' AND si.doc_type='invoice') THEN
    RAISE EXCEPTION 'on-account checkout did not produce a posted invoice';
  END IF;
  PERFORM public.emit_domain_event('pos_credit_sale_authorized','pos:credit:'||v_invoice::text,
    jsonb_build_object('invoice_id',v_invoice,'cart_id',p_cart_id,'customer_id',v_cart.customer_id,'amount',v_total,'currency',v_cart.currency,'credit_limit',v_cust.credit_limit,'open_balance_before',v_owing),
    auth.uid(),format('POS on-account sale authorized: %s %s',v_total,v_cart.currency));
  RETURN v_invoice;
END;
$$;


--
-- Name: checkout_pos_cart_with_tenders(uuid, jsonb, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checkout_pos_cart_with_tenders(p_cart_id uuid, p_tenders jsonb, p_receipt_email text DEFAULT NULL::text, p_receipt_whatsapp_e164 text DEFAULT NULL::text, p_receipt_phone_e164 text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_inv uuid; v_status text;
BEGIN
  PERFORM public._require_payments_staff();
  PERFORM public._require_cart_mutate(p_cart_id);
  IF p_tenders IS NULL OR jsonb_typeof(p_tenders)<>'array' OR jsonb_array_length(p_tenders)<1 THEN
    RAISE EXCEPTION 'p_tenders required for split-bill checkout';
  END IF;
  UPDATE public.pos_carts c
  SET customer_id=COALESCE(c.customer_id,public.ensure_pos_walkin_customer()),updated_at=now()
  WHERE c.id=p_cart_id AND c.customer_id IS NULL;

  PERFORM public._sales_checkout_accounting_enter();
  BEGIN
    v_inv:=public.checkout_pos_cart(p_cart_id,p_receipt_email,p_receipt_whatsapp_e164,p_receipt_phone_e164);
  EXCEPTION WHEN OTHERS THEN
    PERFORM public._sales_checkout_accounting_exit();
    RAISE;
  END;
  PERFORM public._sales_checkout_accounting_exit();

  SELECT status::text INTO v_status FROM public.sales_invoices WHERE id=v_inv;
  IF v_status='on_hold' THEN RETURN v_inv; END IF;
  PERFORM public.settle_invoice_tenders(v_inv,p_tenders);
  RETURN v_inv;
END;
$$;


--
-- Name: claim_chat_thread(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_chat_thread(p_thread_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public.has_staff_role(public._chat_staff_roles()) THEN
    RAISE EXCEPTION 'admin, sales, or warehouse role required to claim chat';
  END IF;

  UPDATE public.chat_threads
  SET
    status = 'assigned',
    assigned_to = auth.uid(),
    assigned_at = now(),
    updated_at = now()
  WHERE id = p_thread_id
    AND status IN ('open', 'assigned');

  IF NOT FOUND THEN
    RAISE EXCEPTION 'thread not found or not claimable';
  END IF;

  INSERT INTO public.chat_participants (thread_id, user_id, role, last_read_at)
  VALUES (p_thread_id, auth.uid(), 'staff', now())
  ON CONFLICT (thread_id, user_id) DO NOTHING;
END;
$$;


--
-- Name: claim_hr_auth_provision(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_hr_auth_provision(p_employee_id uuid, p_claim_token text, p_ttl_seconds integer DEFAULT 120) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_emp public.employees%ROWTYPE;
  v_ttl INT := GREATEST(COALESCE(p_ttl_seconds, 120), 30);
  v_token TEXT := NULLIF(trim(COALESCE(p_claim_token, '')), '');
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'service_role required';
  END IF;
  IF p_employee_id IS NULL OR v_token IS NULL THEN
    RAISE EXCEPTION 'employee_id and claim_token required';
  END IF;

  DELETE FROM public.hr_auth_provision_locks
  WHERE expires_at < now();

  SELECT * INTO v_emp
  FROM public.employees
  WHERE id = p_employee_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_found');
  END IF;
  IF v_emp.status = 'terminated' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'terminated');
  END IF;
  IF v_emp.user_id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'already_linked',
      'user_id', v_emp.user_id
    );
  END IF;

  DELETE FROM public.hr_auth_provision_locks
  WHERE employee_id = p_employee_id
    AND expires_at < now();

  BEGIN
    INSERT INTO public.hr_auth_provision_locks (
      employee_id, claim_token, claimed_at, expires_at
    ) VALUES (
      p_employee_id, v_token, now(), now() + make_interval(secs => v_ttl)
    );
  EXCEPTION
    WHEN unique_violation THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'in_flight');
  END;

  RETURN jsonb_build_object(
    'ok', true,
    'employee_id', v_emp.id,
    'email', v_emp.email,
    'phone_e164', v_emp.phone_e164,
    'full_name', v_emp.full_name,
    'employee_code', v_emp.employee_code
  );
END;
$$;


--
-- Name: claim_pos_scan_session(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_pos_scan_session(p_pairing_code text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_code TEXT := trim(COALESCE(p_pairing_code, ''));
  v_sess public.pos_scan_sessions%ROWTYPE;
BEGIN
  PERFORM public._require_sales_staff();
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authenticated user required';
  END IF;
  IF v_code !~ '^[0-9]{6}$' THEN
    RAISE EXCEPTION 'invalid pairing code';
  END IF;

  PERFORM public._expire_stale_pos_scan_sessions(NULL);

  SELECT * INTO v_sess
  FROM public.pos_scan_sessions
  WHERE pairing_code = v_code AND status = 'open'
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'pairing code not found or not open';
  END IF;
  IF v_sess.expires_at <= now() THEN
    UPDATE public.pos_scan_sessions
    SET status = 'expired', updated_at = now()
    WHERE id = v_sess.id;
    RAISE EXCEPTION 'pairing code expired';
  END IF;

  -- Same-user claim only (no cross-rep)
  IF v_sess.owner_user_id IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'cross-rep claim not allowed; claim with the cart owner account';
  END IF;

  UPDATE public.pos_scan_sessions
  SET
    status = 'claimed',
    scanner_user_id = auth.uid(),
    claimed_at = now(),
    updated_at = now()
  WHERE id = v_sess.id;

  RETURN v_sess.id;
END;
$_$;


--
-- Name: customer_receipt_outbox; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.customer_receipt_outbox (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    document_type text NOT NULL,
    document_id uuid NOT NULL,
    channel public.receipt_channel NOT NULL,
    recipient text NOT NULL,
    summary_body text NOT NULL,
    pdf_storage_path text,
    download_url text,
    status public.receipt_outbox_status DEFAULT 'pending'::public.receipt_outbox_status NOT NULL,
    attempt_count integer DEFAULT 0 NOT NULL,
    last_error text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    sent_at timestamp with time zone,
    receipt_pdf_artifact_id uuid,
    claimed_at timestamp with time zone,
    CONSTRAINT customer_receipt_outbox_document_type_check CHECK ((document_type = ANY (ARRAY['sales_invoice'::text, 'credit_note'::text])))
);


--
-- Name: claim_receipt_outbox_batch(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_receipt_outbox_batch(p_limit integer DEFAULT 50) RETURNS SETOF public.customer_receipt_outbox
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_limit INT := LEAST(100, GREATEST(1, COALESCE(p_limit, 50)));
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'service_role required';
  END IF;

  -- Reclaim workers that died mid-send (default 15 minutes).
  UPDATE public.customer_receipt_outbox
  SET
    status = 'failed',
    last_error = left(
      COALESCE(last_error || '; ', '') || 'reclaimed: stuck in sending',
      2000
    ),
    claimed_at = NULL
  WHERE status = 'sending'
    AND COALESCE(claimed_at, created_at) < now() - interval '15 minutes';

  RETURN QUERY
  WITH picked AS (
    SELECT o.id
    FROM public.customer_receipt_outbox o
    WHERE o.status IN ('pending', 'failed')
      AND o.download_url IS NOT NULL
      AND o.attempt_count < 8
    ORDER BY o.created_at
    LIMIT v_limit
    FOR UPDATE OF o SKIP LOCKED
  )
  UPDATE public.customer_receipt_outbox o
  SET
    status = 'sending',
    attempt_count = o.attempt_count + 1,
    last_error = NULL,
    claimed_at = now()
  FROM picked
  WHERE o.id = picked.id
  RETURNING o.*;
END;
$$;


