    CONSTRAINT sms_outbox_channel_check CHECK ((channel = ANY (ARRAY['sms'::text, 'whatsapp'::text])))
);


--
-- Name: claim_sms_outbox_batch(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_sms_outbox_batch(p_limit integer DEFAULT 50) RETURNS SETOF public.sms_outbox
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_limit INT := LEAST(100, GREATEST(1, COALESCE(p_limit, 50)));
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'service_role required';
  END IF;

  UPDATE public.sms_outbox
  SET
    status = 'failed',
    last_error = left(
      COALESCE(last_error || '; ', '') || 'reclaimed: stuck in sending',
      2000
    ),
    claimed_at = NULL
  WHERE status = 'sending'
    AND COALESCE(claimed_at, created_at) < now() - interval '15 minutes';

  RETURN QUERY
  WITH picked AS (
    SELECT o.id
    FROM public.sms_outbox o
    WHERE o.status IN ('pending', 'failed')
      AND o.attempt_count < 8
    ORDER BY o.created_at
