  )
  UPDATE public.sms_outbox o
  SET
    status = 'sending',
    attempt_count = o.attempt_count + 1,
    last_error = NULL,
    claimed_at = now()
  FROM picked
  WHERE o.id = picked.id
  RETURNING o.*;
END;
$$;


--
-- Name: clear_bank_matches(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.clear_bank_matches(p_match_ids uuid[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_count INT := 0;
  v_id UUID;
  v_line UUID;
BEGIN
  IF NOT (
    auth.role() = 'service_role'
    OR public.has_staff_role(ARRAY['admin', 'finance']::public.staff_role[])
  ) THEN
    RAISE EXCEPTION 'finance or admin role required';
  END IF;

  FOREACH v_id IN ARRAY p_match_ids
  LOOP
    SELECT statement_line_id INTO v_line
    FROM public.bank_recon_matches
    WHERE id = v_id;

    IF v_line IS NULL THEN
      CONTINUE;
    END IF;

    UPDATE public.bank_statement_lines
    SET status = 'cleared'
    WHERE id = v_line;

    v_count := v_count + 1;
  END LOOP;

  RETURN v_count;
END;
$$;


