    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not authenticated';
  END IF;
  UPDATE public.profiles
  SET must_change_password = false, updated_at = now()
  WHERE id = auth.uid();
END;
$$;


--
-- Name: clock_attendance(uuid, public.attendance_event_type, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.clock_attendance(p_employee_id uuid, p_event_type public.attendance_event_type, p_occurred_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id UUID;
  v_emp public.employees%ROWTYPE;
  v_when TIMESTAMPTZ := COALESCE(p_occurred_at, now());
  v_is_hr BOOLEAN;
  v_self UUID;
BEGIN
  v_is_hr := (
    auth.role() = 'service_role'
    OR public.has_staff_role(ARRAY['admin', 'hr']::public.staff_role[])
  );
  v_self := public.current_employee_id();

  IF NOT v_is_hr AND (v_self IS NULL OR v_self IS DISTINCT FROM p_employee_id) THEN
    RAISE EXCEPTION 'admin/hr role or own employee record required to clock attendance';
  END IF;

  SELECT * INTO v_emp FROM public.employees WHERE id = p_employee_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'employee not found: %', p_employee_id;
  END IF;
  IF v_emp.status <> 'active' THEN
    RAISE EXCEPTION 'employee % is not active', p_employee_id;
  END IF;

  INSERT INTO public.attendance_events (
    employee_id, event_type, occurred_at, source, notes, recorded_by
  )
  VALUES (
    p_employee_id, p_event_type, v_when, 'manual', p_notes, auth.uid()
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


--
-- Name: close_account_period(uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.close_account_period(p_period_id uuid, p_physical_count numeric DEFAULT NULL::numeric, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row public.account_period_balances%ROWTYPE;
  v_activity NUMERIC(18, 2);
  v_closing NUMERIC(18, 2);
  v_variance NUMERIC(18, 2);
BEGIN
  SELECT * INTO v_row
  FROM public.account_period_balances
  WHERE id = p_period_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'account period not found: %', p_period_id;
  END IF;

  IF NOT (
    auth.role() = 'service_role'
    OR public.has_staff_role(ARRAY['admin', 'finance']::public.staff_role[])
    OR (
      v_row.account_code = '1120'
      AND public.has_staff_role(
        ARRAY['admin', 'finance', 'sales', 'warehouse']::public.staff_role[]
      )
    )
  ) THEN
    RAISE EXCEPTION 'finance or admin role required (sales/warehouse may close 1120 only)';
  END IF;

  IF v_row.account_code = '1110'
     AND NOT (
       auth.role() = 'service_role'
       OR public.has_staff_role(ARRAY['admin', 'finance']::public.staff_role[])
     )
  THEN
    RAISE EXCEPTION 'petty cash 1110 is finance-only';
  END IF;

  IF v_row.status = 'closed' THEN
    RAISE EXCEPTION 'account period already closed: %', p_period_id;
  END IF;

  SELECT COALESCE(SUM(l.debit - l.credit), 0)
  INTO v_activity
  FROM public.journal_entry_lines l
  JOIN public.journal_entries e ON e.id = l.journal_entry_id
  WHERE e.status = 'posted'
    AND l.account_code = v_row.account_code
    AND e.currency = v_row.currency
    AND e.entry_date BETWEEN v_row.period_start AND v_row.period_end;

  v_closing := v_row.opening_balance + v_activity;

  IF p_physical_count IS NOT NULL THEN
    v_variance := p_physical_count - v_closing;
  ELSE
    v_variance := NULL;
  END IF;

  PERFORM public._finance_period_rpc_enter();

  UPDATE public.account_period_balances
  SET
    status = 'closed',
    closing_balance = v_closing,
    closed_at = now(),
    closed_by = auth.uid(),
    physical_count = p_physical_count,
    variance = v_variance,
    notes = CASE
      WHEN nullif(trim(p_notes), '') IS NULL THEN notes
      WHEN notes IS NULL OR notes = '' THEN nullif(trim(p_notes), '')
      ELSE notes || E'\n' || nullif(trim(p_notes), '')
    END
  WHERE id = p_period_id;

  RETURN p_period_id;
END;
$$;


--
-- Name: FUNCTION close_account_period(p_period_id uuid, p_physical_count numeric, p_notes text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.close_account_period(p_period_id uuid, p_physical_count numeric, p_notes text) IS 'Close account period. Finance/admin any; sales/warehouse may close 1120 only. 1110 finance-only.';


--
-- Name: close_chat_thread(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.close_chat_thread(p_thread_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row public.chat_threads;
BEGIN
  SELECT * INTO v_row FROM public.chat_threads WHERE id = p_thread_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'thread not found';
  END IF;

  IF NOT (
    v_row.customer_user_id = auth.uid()
    OR public.has_staff_role(public._chat_staff_roles())
  ) THEN
    RAISE EXCEPTION 'not allowed to close this thread';
  END IF;

  IF v_row.status = 'closed' THEN
    RETURN;
  END IF;

  UPDATE public.chat_threads
  SET
    status = 'closed',
    closed_at = now(),
    closed_by = auth.uid(),
    updated_at = now()
  WHERE id = p_thread_id;
END;
$$;


--
-- Name: close_pos_till_session(uuid, numeric, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.close_pos_till_session(p_session_id uuid, p_counted_cash numeric, p_variance_reason_code text DEFAULT NULL::text, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE s public.pos_till_sessions%ROWTYPE; v_expected NUMERIC; v_var NUMERIC; p public.pos_approval_policies%ROWTYPE; v_pending BOOLEAN;
BEGIN
 PERFORM public._require_sales_staff(); SELECT * INTO s FROM public.pos_till_sessions WHERE id=p_session_id FOR UPDATE;
 IF NOT FOUND OR s.status<>'open' THEN RAISE EXCEPTION 'open till session required'; END IF;
 IF s.operator_user_id<>auth.uid() THEN RAISE EXCEPTION 'only the current till operator can perform blind close count'; END IF;
 IF COALESCE(p_counted_cash,-1)<0 THEN RAISE EXCEPTION 'counted cash must be >= 0'; END IF;
 v_expected:=public.pos_till_expected_cash(p_session_id); v_var:=round(p_counted_cash-v_expected,2);
 SELECT * INTO p FROM public.pos_approval_policies WHERE action='till_variance';
 v_pending:=abs(v_var)>COALESCE(p.threshold_value,0) OR (COALESCE(p.always_require_manager,false) AND abs(v_var)>0.009);
 IF abs(v_var)>0.009 AND trim(COALESCE(p_variance_reason_code,''))='' THEN RAISE EXCEPTION 'variance reason required'; END IF;
 UPDATE public.pos_till_sessions SET expected_cash=v_expected,counted_cash=round(p_counted_cash,2),variance=v_var,
   variance_reason_code=NULLIF(trim(COALESCE(p_variance_reason_code,'')),''),close_notes=p_notes,
   status=CASE WHEN v_pending THEN 'variance_pending'::public.pos_till_session_status ELSE 'closed'::public.pos_till_session_status END,
   closed_at=CASE WHEN v_pending THEN NULL ELSE now() END,updated_at=now() WHERE id=p_session_id;
 INSERT INTO public.pos_till_session_events(session_id,event_type,actor_user_id,detail) VALUES
 (p_session_id,CASE WHEN v_pending THEN 'close_submitted' ELSE 'closed' END,auth.uid(),
  jsonb_build_object('expected_cash',v_expected,'counted_cash',round(p_counted_cash,2),'variance',v_var,'reason_code',p_variance_reason_code));
 RETURN jsonb_build_object('session_id',p_session_id,'expected_cash',v_expected,'counted_cash',round(p_counted_cash,2),'variance',v_var,
   'status',CASE WHEN v_pending THEN 'variance_pending' ELSE 'closed' END);
END $$;


--
-- Name: close_warranty_claim(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.close_warranty_claim(p_claim_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_status public.warranty_claim_status;
BEGIN
  PERFORM public._warranty_begin_rpc();
  PERFORM public._require_warranty_staff();

  SELECT status INTO v_status FROM public.warranty_claims WHERE id = p_claim_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'warranty claim not found';
  END IF;

  IF v_status = 'closed' THEN
    RETURN p_claim_id;
  END IF;

  IF v_status NOT IN ('approved', 'rejected') THEN
    RAISE EXCEPTION 'only approved or rejected claims can be closed (status=%)', v_status;
  END IF;

  UPDATE public.warranty_claims
  SET status = 'closed', closed_at = now()
  WHERE id = p_claim_id;

  PERFORM public.emit_domain_event(
    'warranty_claim_closed',
    'warranty:closed:' || p_claim_id::text,
    jsonb_build_object('warranty_claim_id', p_claim_id)
  );

  RETURN p_claim_id;
END;
$$;


--
-- Name: collect_delivery_cash(uuid, numeric, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.collect_delivery_cash(p_delivery_job_id uuid, p_amount numeric, p_request_id uuid, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE j public.delivery_jobs%ROWTYPE;i public.sales_invoices%ROWTYPE;v_due NUMERIC;v_pe UUID;v_existing public.delivery_cash_collections%ROWTYPE;
BEGIN
 SELECT * INTO v_existing FROM public.delivery_cash_collections WHERE request_id=p_request_id;
 IF FOUND THEN RETURN jsonb_build_object('collection_id',v_existing.id,'payment_entry_id',v_existing.payment_entry_id,'amount',v_existing.amount,'currency',v_existing.currency); END IF;
 SELECT * INTO j FROM public.delivery_jobs WHERE id=p_delivery_job_id FOR UPDATE;
 IF NOT FOUND OR j.status<>'dispatched' OR j.assignee_user_id IS DISTINCT FROM auth.uid() OR NOT public.has_staff_role(ARRAY['driver']::public.staff_role[]) THEN
  RAISE EXCEPTION 'assigned dispatched driver job required'; END IF;
 SELECT si.* INTO i FROM public.delivery_notes dn JOIN public.sales_invoices si ON si.id=dn.sales_invoice_id WHERE dn.id=j.delivery_note_id FOR UPDATE OF si;
 IF i.delivery_payment_method NOT IN('cash_on_delivery','cash_or_card_on_delivery') THEN RAISE EXCEPTION 'this delivery is not authorized for cash collection'; END IF;
 v_due:=greatest(round(i.total-i.amount_paid,2),0); IF v_due<=0 THEN RAISE EXCEPTION 'invoice has no balance due'; END IF;
 IF COALESCE(p_amount,0)<=0 OR p_amount>v_due+0.01 THEN RAISE EXCEPTION 'cash amount must be >0 and <= delivery balance %',v_due; END IF;
 PERFORM set_config('app.delivery_payment_rpc','1',true);
 v_pe:=public.create_payment_entry(i.customer_id,'cash',round(p_amount,2),i.currency,i.exchange_rate_applied,
  concat_ws(' · ','Cash on delivery '||COALESCE(i.document_number,i.id::text),p_notes));
 PERFORM public.allocate_payment(v_pe,jsonb_build_array(jsonb_build_object('sales_invoice_id',i.id,'amount',round(p_amount,2))));
 PERFORM public.post_payment_entry(v_pe);
 PERFORM set_config('app.delivery_payment_rpc','',true);
 INSERT INTO public.delivery_cash_collections(request_id,delivery_job_id,sales_invoice_id,payment_entry_id,amount,currency,collected_by,notes)
 VALUES(p_request_id,j.id,i.id,v_pe,round(p_amount,2),i.currency,auth.uid(),p_notes) RETURNING * INTO v_existing;
 RETURN jsonb_build_object('collection_id',v_existing.id,'payment_entry_id',v_pe,'amount',v_existing.amount,'currency',v_existing.currency,
  'balance_due',greatest(v_due-v_existing.amount,0));
EXCEPTION WHEN OTHERS THEN PERFORM set_config('app.delivery_payment_rpc','',true); RAISE;
END $$;


--
-- Name: collect_pos_commerce_order(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.collect_pos_commerce_order(p_order_id uuid, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE o public.commerce_orders%ROWTYPE; i public.sales_invoices%ROWTYPE;
BEGIN
 PERFORM public._require_sales_staff(); SELECT * INTO o FROM public.commerce_orders WHERE id=p_order_id FOR UPDATE;
 IF NOT FOUND OR o.fulfillment_mode<>'immediate' OR o.state NOT IN('paid','dispatch_ready','account_invoiced') OR o.sales_invoice_id IS NULL
  THEN RAISE EXCEPTION 'eligible pickup order required'; END IF;
 SELECT * INTO i FROM public.sales_invoices WHERE id=o.sales_invoice_id;
 IF NOT FOUND OR i.status<>'posted' THEN RAISE EXCEPTION 'posted invoice required'; END IF;
 IF o.state<>'account_invoiced' AND i.amount_paid+0.01<i.total THEN RAISE EXCEPTION 'fully paid invoice required'; END IF;
 UPDATE public.commerce_orders SET state='delivered',updated_at=now() WHERE id=o.id;
 PERFORM private.enqueue_commerce_event('commerce:'||o.id::text||':counter-collected','commerce.order_collected',o.id,
  jsonb_build_object('sales_invoice_id',o.sales_invoice_id,'notes',p_notes,'collected_by',auth.uid(),'account_credit',o.state='account_invoiced'));
 RETURN o.id;
END $$;


--
-- Name: collect_pos_fulfillment_request(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.collect_pos_fulfillment_request(p_request_id uuid, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE r public.pos_fulfillment_requests%ROWTYPE; i public.sales_invoices%ROWTYPE;
BEGIN
 PERFORM public._require_sales_staff(); SELECT * INTO r FROM public.pos_fulfillment_requests WHERE id=p_request_id FOR UPDATE;
 IF NOT FOUND OR r.status<>'ready' THEN RAISE EXCEPTION 'ready fulfillment request required'; END IF;
 IF r.invoice_id IS NOT NULL THEN SELECT * INTO i FROM public.sales_invoices WHERE id=r.invoice_id;
  IF NOT FOUND OR i.status<>'posted' OR COALESCE(i.amount_paid,0)+0.01<i.total THEN RAISE EXCEPTION 'order must be fully paid before collection'; END IF;
 END IF;
 IF r.invoice_id IS NULL AND (r.kind<>'branch_transfer' OR r.customer_id IS NOT NULL) THEN RAISE EXCEPTION 'sale/invoice must be linked before customer collection'; END IF;
 UPDATE public.inventory_reservations SET state='released',released_at=now() WHERE pos_fulfillment_request_id=p_request_id AND state IN('active','allocated');
 UPDATE public.pos_fulfillment_requests SET status='collected',collected_at=now(),notes=concat_ws(E'\n',notes,p_notes),updated_at=now() WHERE id=p_request_id;
 RETURN p_request_id;
END $$;


--
-- Name: complete_hr_credential_outbox(uuid, boolean, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_hr_credential_outbox(p_id uuid, p_success boolean, p_error text DEFAULT NULL::text, p_provider_message_id text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'service_role required';
  END IF;

  -- Redact plaintext temp password from body after delivery attempt.
  UPDATE public.hr_credential_outbox
  SET
    status = CASE
      WHEN COALESCE(p_success, false) THEN 'sent'::public.hr_credential_outbox_status
      ELSE 'failed'::public.hr_credential_outbox_status
    END,
    attempt_count = attempt_count + 1,
    last_error = CASE WHEN COALESCE(p_success, false) THEN NULL ELSE left(COALESCE(p_error, 'send failed'), 500) END,
    provider_message_id = COALESCE(p_provider_message_id, provider_message_id),
    sent_at = CASE WHEN COALESCE(p_success, false) THEN now() ELSE sent_at END,
    claimed_at = NULL,
    body = '[redacted after delivery attempt]'
  WHERE id = p_id;
END;
$$;


--
-- Name: complete_hr_onboarding(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_hr_onboarding(p_draft_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_draft public.hr_onboarding_drafts%ROWTYPE;
  v_payload JSONB;
  v_full_name TEXT;
  v_email TEXT;
  v_phone TEXT;
  v_grade_id UUID;
  v_grade_code TEXT;
  v_hr_role_id UUID;
  v_emp_id UUID;
  v_emp_code TEXT;
  v_user_id UUID;
  v_temp_hint TEXT;
  v_staff_role public.staff_role;
BEGIN
  IF NOT public.has_staff_role(ARRAY['admin', 'hr']::public.staff_role[]) THEN
    RAISE EXCEPTION 'hr or admin role required';
  END IF;

  SELECT * INTO v_draft
  FROM public.hr_onboarding_drafts
  WHERE id = p_draft_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'onboarding draft not found: %', p_draft_id;
  END IF;
  IF v_draft.completed_at IS NOT NULL THEN
    RAISE EXCEPTION 'onboarding already completed';
  END IF;

  v_payload := COALESCE(v_draft.payload, '{}'::jsonb);
  v_full_name := nullif(trim(COALESCE(v_payload->>'full_name', '')), '');
  v_email := nullif(trim(COALESCE(v_payload->>'email', '')), '');
  v_phone := nullif(trim(COALESCE(v_payload->>'phone_e164', '')), '');
  v_grade_id := NULLIF(v_payload->>'grade_id', '')::uuid;
  v_hr_role_id := NULLIF(v_payload->>'hr_role_id', '')::uuid;
  v_user_id := NULLIF(v_payload->>'user_id', '')::uuid;

  IF v_full_name IS NULL THEN
    RAISE EXCEPTION 'payload.full_name required to complete onboarding';
  END IF;
  IF v_grade_id IS NULL THEN
    RAISE EXCEPTION 'payload.grade_id required for GTR employee number';
  END IF;
  IF v_draft.banking_json IS NULL THEN
    RAISE EXCEPTION 'banking_json required before completion';
  END IF;

  SELECT code INTO v_grade_code FROM public.hr_grades WHERE id = v_grade_id AND is_active;
  IF v_grade_code IS NULL THEN
    RAISE EXCEPTION 'active grade not found: %', v_grade_id;
  END IF;

  IF v_hr_role_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.hr_roles WHERE id = v_hr_role_id AND is_active
  ) THEN
    RAISE EXCEPTION 'active hr_role not found: %', v_hr_role_id;
  END IF;

  v_staff_role := public.resolve_hr_onboarding_staff_role(v_payload, v_hr_role_id);

  v_emp_code := public.next_employee_code_for_grade(v_grade_code);
  v_temp_hint := encode(extensions.gen_random_bytes(9), 'base64');

  IF v_draft.employee_id IS NULL THEN
    INSERT INTO public.employees (
      employee_code, full_name, user_id, email, phone_e164, hire_date,
      hr_role_id, grade_id, status
    ) VALUES (
      v_emp_code,
      v_full_name,
      v_user_id,
      v_email,
      v_phone,
      COALESCE((v_payload->>'hire_date')::date, CURRENT_DATE),
      v_hr_role_id,
      v_grade_id,
      'active'
    )
    RETURNING id INTO v_emp_id;
  ELSE
    v_emp_id := v_draft.employee_id;
    UPDATE public.employees
    SET
      employee_code = v_emp_code,
      full_name = v_full_name,
      email = COALESCE(v_email, email),
      phone_e164 = COALESCE(v_phone, phone_e164),
      hr_role_id = COALESCE(v_hr_role_id, hr_role_id),
      grade_id = v_grade_id,
      user_id = COALESCE(v_user_id, user_id),
      updated_at = now()
    WHERE id = v_emp_id;
  END IF;

  IF v_user_id IS NOT NULL THEN
    UPDATE public.profiles
    SET must_change_password = true, updated_at = now()
    WHERE id = v_user_id;

    PERFORM public.apply_hr_onboarding_staff_role(v_user_id, v_staff_role);
  END IF;

  UPDATE public.hr_onboarding_drafts
  SET
    employee_id = v_emp_id,
    stage = 'credentials',
    completed_at = now(),
    updated_by = auth.uid(),
    updated_at = now(),
    payload = v_payload || jsonb_build_object(
      'employee_code', v_emp_code,
      'completed', true,
      'staff_role', v_staff_role::text
    )
  WHERE id = p_draft_id;

  RETURN jsonb_build_object(
    'draft_id', p_draft_id,
    'employee_id', v_emp_id,
    'employee_code', v_emp_code,
    'email', v_email,
    'phone_e164', v_phone,
    'user_id', v_user_id,
    'staff_role', v_staff_role::text,
    'must_change_password', v_user_id IS NOT NULL,
    'temp_password_hint', v_temp_hint,
    'message', 'Create/link auth user via hr-onboarding-create-auth Edge when user_id absent; staff_role assigned on link.'
  );
END;
$$;


--
-- Name: complete_pos_split_refund(uuid, text, numeric, numeric, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_pos_split_refund(p_refund_id uuid, p_provider_ref text, p_actual_provider_fee numeric DEFAULT 0, p_actual_transfer_fee numeric DEFAULT 0, p_actual_customer_fee numeric DEFAULT 0, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE r public.pos_split_refund_requests%ROWTYPE; l public.pos_split_payment_legs%ROWTYPE; pe public.payment_entries%ROWTYPE;
 s public.pos_split_payment_sessions%ROWTYPE; v_fee NUMERIC; v_customer_fee NUMERIC; v_net NUMERIC; v_acct TEXT; v_journal UUID; v_remaining INTEGER; v_allocated NUMERIC:=0;
BEGIN
 IF NOT (auth.role()='service_role' OR public.is_pos_approver() OR public.has_staff_role(ARRAY['finance']::public.staff_role[])) THEN RAISE EXCEPTION 'manager, finance, or service role required'; END IF;
 SELECT * INTO r FROM public.pos_split_refund_requests WHERE id=p_refund_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'split refund request not found'; END IF;
 IF r.status='settled' THEN RETURN private.pos_split_payment_payload(r.session_id); END IF;
 IF r.status NOT IN('pending','review','failed') THEN RAISE EXCEPTION 'refund cannot settle in status %',r.status; END IF;
 SELECT * INTO l FROM public.pos_split_payment_legs WHERE id=r.leg_id FOR UPDATE; SELECT * INTO pe FROM public.payment_entries WHERE id=l.payment_entry_id FOR UPDATE;
 SELECT * INTO s FROM public.pos_split_payment_sessions WHERE id=r.session_id FOR UPDATE;
 IF pe.status<>'posted' THEN RAISE EXCEPTION 'posted split receipt required'; END IF;
 SELECT COALESCE(SUM(amount),0) INTO v_allocated FROM public.payment_allocations WHERE payment_entry_id=pe.id;
 IF v_allocated+r.gross_amount>pe.amount+0.01 THEN RAISE EXCEPTION 'refund plus applied amount exceeds captured receipt'; END IF;
 v_fee:=round(COALESCE(p_actual_provider_fee,0)+COALESCE(p_actual_transfer_fee,0),2); v_customer_fee:=round(COALESCE(p_actual_customer_fee,0),2);
 IF v_fee<0 OR v_customer_fee<0 OR v_customer_fee>r.gross_amount THEN RAISE EXCEPTION 'invalid actual refund fees'; END IF;
 IF v_customer_fee>0 AND r.fee_policy<>'customer_bears' THEN RAISE EXCEPTION 'customer fee deduction not approved by refund policy'; END IF;
 v_net:=round(r.gross_amount-v_customer_fee,2); v_acct:=public.gl_account_for_payment_tender(l.tender);
 PERFORM public._payments_rpc_enter();
 v_journal:=public.post_journal_entry(CURRENT_DATE,format('POS split refund %s',r.id),s.currency,1,
  jsonb_build_array(jsonb_build_object('account_code','2215','debit',r.gross_amount,'credit',0,'currency',s.currency),
   jsonb_build_object('account_code','6250','debit',v_fee,'credit',0,'currency',s.currency),
   jsonb_build_object('account_code',v_acct,'debit',0,'credit',v_net+v_fee,'currency',s.currency),
   jsonb_build_object('account_code','4250','debit',0,'credit',v_customer_fee,'currency',s.currency)));
 IF v_allocated<=0.001 AND abs(r.gross_amount-pe.amount)<=0.01 THEN
  UPDATE public.payment_entries SET status='cancelled',reversal_journal_entry_id=v_journal,cancelled_at=now(),updated_at=now() WHERE id=pe.id;
 END IF;
 UPDATE public.pos_split_refund_requests SET status='settled',actual_provider_fee=COALESCE(p_actual_provider_fee,0),actual_transfer_fee=COALESCE(p_actual_transfer_fee,0),
  actual_customer_fee=v_customer_fee,net_customer_refund=v_net,provider_ref=NULLIF(trim(COALESCE(p_provider_ref,'')),''),settled_by=auth.uid(),settled_at=now(),
  notes=concat_ws(E'\n',notes,p_notes),failure_reason=NULL,updated_at=now() WHERE id=r.id;
 UPDATE public.pos_split_payment_legs SET status=CASE WHEN v_allocated>0.001 THEN 'allocated'::public.pos_split_payment_leg_status ELSE 'refunded'::public.pos_split_payment_leg_status END,
  provider_ref=COALESCE(NULLIF(trim(COALESCE(p_provider_ref,'')),''),provider_ref),refunded_at=now(),updated_at=now() WHERE id=l.id;
 SELECT count(*) INTO v_remaining FROM public.pos_split_refund_requests WHERE session_id=s.id AND status NOT IN('settled','cancelled');
 IF s.final_invoice_id IS NOT NULL THEN
  UPDATE public.pos_split_payment_sessions SET status=CASE WHEN v_remaining=0 THEN 'settled'::public.pos_split_payment_session_status ELSE 'refund_pending'::public.pos_split_payment_session_status END,
   refunded_amount=(SELECT COALESCE(SUM(gross_amount) FILTER(WHERE status='settled'),0) FROM public.pos_split_refund_requests WHERE session_id=s.id),updated_at=now() WHERE id=s.id;
 ELSIF v_remaining=0 THEN
  UPDATE public.pos_split_payment_sessions SET status='refunded',refunded_amount=(SELECT COALESCE(SUM(gross_amount),0) FROM public.pos_split_refund_requests WHERE session_id=s.id),updated_at=now() WHERE id=s.id;
 ELSE UPDATE public.pos_split_payment_sessions SET status='refund_pending',updated_at=now() WHERE id=s.id; END IF;
 PERFORM public.emit_domain_event('refund_issued','pos-split:refund:'||r.id::text,jsonb_build_object('split_refund_id',r.id,'leg_id',l.id,'gross_amount',r.gross_amount,
  'net_customer_refund',v_net,'provider_fee',COALESCE(p_actual_provider_fee,0),'transfer_fee',COALESCE(p_actual_transfer_fee,0),'customer_fee',v_customer_fee,'tender',l.tender,'provider_ref',p_provider_ref),
  auth.uid(),format('GTR Auto: split refund settled %s %s net',v_net,s.currency));
 RETURN private.pos_split_payment_payload(s.id);
END $$;


--
-- Name: complete_receipt_outbox(uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_receipt_outbox(p_id uuid, p_success boolean, p_error text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'service_role required';
  END IF;

  IF p_success THEN
    UPDATE public.customer_receipt_outbox
    SET
      status = 'sent',
      last_error = NULL,
      sent_at = now(),
      claimed_at = NULL
    WHERE id = p_id
      AND status IS DISTINCT FROM 'sent';
  ELSE
    UPDATE public.customer_receipt_outbox
    SET
      status = 'failed',
      last_error = left(COALESCE(p_error, 'send failed'), 2000),
      claimed_at = NULL
    WHERE id = p_id
      AND status IS DISTINCT FROM 'sent';
  END IF;
END;
$$;


--
-- Name: complete_return_refund_manual(uuid, public.payment_tender, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_return_refund_manual(p_return_request_id uuid, p_tender public.payment_tender, p_settlement_reference text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_ref public.return_refund_requests%ROWTYPE; v_gl text; v_journal uuid;
BEGIN
  IF NOT (auth.role()='service_role' OR public.has_staff_role(ARRAY['admin','finance']::public.staff_role[])) THEN
    RAISE EXCEPTION 'finance or admin role required';
  END IF;
  IF p_tender NOT IN ('cash'::public.payment_tender,'bank'::public.payment_tender) THEN
    RAISE EXCEPTION 'manual return refund supports cash or bank only; provider refunds require verified provider completion';
  END IF;
  IF NULLIF(trim(COALESCE(p_settlement_reference,'')),'') IS NULL THEN RAISE EXCEPTION 'settlement reference required'; END IF;
  SELECT * INTO v_ref FROM public.return_refund_requests WHERE return_request_id=p_return_request_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'pending refund not found'; END IF;
  IF v_ref.status='completed' THEN RETURN v_ref.id; END IF;
  IF v_ref.status NOT IN ('pending','failed') THEN RAISE EXCEPTION 'refund cannot settle in status %',v_ref.status; END IF;
  v_gl:=public.gl_account_for_payment_tender(p_tender);
  v_journal:=public.post_journal_entry(CURRENT_DATE,format('Return refund %s %s',p_tender,p_settlement_reference),v_ref.currency,v_ref.exchange_rate_applied,
    jsonb_build_array(
      jsonb_build_object('account_code','2220','debit',v_ref.amount,'credit',0,'currency',v_ref.currency),
      jsonb_build_object('account_code',v_gl,'debit',0,'credit',v_ref.amount,'currency',v_ref.currency)
    ));
  UPDATE public.return_refund_requests
  SET method=CASE WHEN p_tender='cash' THEN 'cash'::public.return_resolution_method ELSE 'bank'::public.return_resolution_method END,
      status='completed',settlement_reference=trim(p_settlement_reference),processed_by=auth.uid(),processed_at=now(),failure_reason=NULL,updated_at=now()
  WHERE id=v_ref.id;
  UPDATE public.customer_return_requests SET status='completed',updated_at=now() WHERE id=p_return_request_id;
  PERFORM public.emit_domain_event('refund_completed','return:refund:manual:'||v_ref.id::text,
    jsonb_build_object('refund_request_id',v_ref.id,'return_request_id',p_return_request_id,'method',p_tender,'reference',p_settlement_reference,'amount',v_ref.amount),auth.uid(),NULL);
  RETURN v_ref.id;
END;
$$;


--
-- Name: complete_sms_outbox(uuid, boolean, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_sms_outbox(p_id uuid, p_success boolean, p_error text DEFAULT NULL::text, p_provider_message_id text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'service_role required';
  END IF;

  IF p_success THEN
    UPDATE public.sms_outbox
    SET
      status = 'sent',
      last_error = NULL,
      sent_at = now(),
      provider_message_id = COALESCE(p_provider_message_id, provider_message_id),
      claimed_at = NULL
    WHERE id = p_id
      AND status IS DISTINCT FROM 'sent';
  ELSE
    UPDATE public.sms_outbox
    SET
      status = 'failed',
      last_error = left(COALESCE(p_error, 'SMS send failed'), 2000),
      claimed_at = NULL
    WHERE id = p_id
      AND status IS DISTINCT FROM 'sent';
  END IF;
END;
$$;


--
-- Name: compute_payroll_run(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compute_payroll_run(p_payroll_run_id uuid, p_employee_ids uuid[] DEFAULT NULL::uuid[]) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_run public.payroll_runs%ROWTYPE;
  v_emp RECORD;
  v_struct public.salary_structures%ROWTYPE;
  v_hours NUMERIC;
  v_gross NUMERIC;
  v_line_no INT := 0;
  v_start TIMESTAMPTZ;
  v_end TIMESTAMPTZ;
BEGIN
  PERFORM public._payroll_begin_rpc();
  PERFORM public._require_hr_staff();

  SELECT * INTO v_run FROM public.payroll_runs WHERE id = p_payroll_run_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'payroll run not found: %', p_payroll_run_id;
  END IF;
  IF v_run.status <> 'draft' THEN
    RAISE EXCEPTION 'only draft payroll runs can be computed';
  END IF;

  -- Clear prior draft lines (cascade deductions)
  DELETE FROM public.payroll_lines WHERE payroll_run_id = p_payroll_run_id;

  v_start := v_run.period_start::timestamptz;
  v_end := (v_run.period_end + 1)::timestamptz;

  FOR v_emp IN
    SELECT e.*
    FROM public.employees e
    WHERE e.status = 'active'
      AND (p_employee_ids IS NULL OR e.id = ANY (p_employee_ids))
    ORDER BY e.employee_code
  LOOP
    SELECT * INTO v_struct
    FROM public.salary_structures s
    WHERE s.employee_id = v_emp.id
      AND s.is_active
      AND s.currency = v_run.currency
      AND s.effective_from <= v_run.period_end
      AND COALESCE(s.effective_to, '9999-12-31'::date) >= v_run.period_start
    ORDER BY s.effective_from DESC
    LIMIT 1;

    IF NOT FOUND THEN
      CONTINUE;
    END IF;

    v_hours := public.attendance_hours_in_period(v_emp.id, v_start, v_end);

    IF v_struct.pay_type = 'hourly' THEN
      v_gross := ROUND(v_hours * v_struct.rate, 4);
    ELSE
      -- Fixed salary for the period (hours informational only)
      v_gross := ROUND(v_struct.rate, 4);
    END IF;

    IF v_gross <= 0 AND v_hours <= 0 THEN
      CONTINUE;
    END IF;

    v_line_no := v_line_no + 1;
    INSERT INTO public.payroll_lines (
      payroll_run_id, employee_id, line_no, hours_worked, pay_type,
      rate_applied, gross_amount, deductions_amount, net_amount,
      currency, exchange_rate, salary_structure_id
    )
    VALUES (
      p_payroll_run_id, v_emp.id, v_line_no, v_hours, v_struct.pay_type,
      v_struct.rate, v_gross, 0, v_gross,
      v_run.currency, v_run.exchange_rate, v_struct.id
    );
  END LOOP;

  PERFORM public._refresh_payroll_run_totals(p_payroll_run_id);
  RETURN p_payroll_run_id;
END;
$$;


--
-- Name: compute_petty_cash_replenish_amount(public.currency_code, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compute_petty_cash_replenish_amount(p_currency public.currency_code DEFAULT 'USD'::public.currency_code, p_as_of date DEFAULT CURRENT_DATE) RETURNS numeric
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_fund VARCHAR(10);
  v_last_id UUID;
  v_last_date DATE;
  v_last_posted TIMESTAMPTZ;
  v_amount NUMERIC(18, 2);
BEGIN
  IF NOT (
    auth.role() = 'service_role'
    OR public.has_staff_role(ARRAY['admin', 'finance']::public.staff_role[])
  ) THEN
    RAISE EXCEPTION 'finance or admin role required';
  END IF;

  v_fund := public.petty_cash_funding_account_code();

  -- Last float/replenish: Dr 1110 / Cr funding (1100)
  SELECT e.id, e.entry_date, e.posted_at
  INTO v_last_id, v_last_date, v_last_posted
  FROM public.journal_entries e
  WHERE e.status = 'posted'
    AND e.currency = p_currency
    AND e.entry_date <= COALESCE(p_as_of, CURRENT_DATE)
    AND EXISTS (
      SELECT 1 FROM public.journal_entry_lines d
      WHERE d.journal_entry_id = e.id
        AND d.account_code = '1110'
        AND d.debit > 0
    )
    AND EXISTS (
      SELECT 1 FROM public.journal_entry_lines c
      WHERE c.journal_entry_id = e.id
        AND c.account_code = v_fund
        AND c.credit > 0
    )
  ORDER BY e.entry_date DESC, e.posted_at DESC NULLS LAST, e.ctid DESC
  LIMIT 1;

  -- Sum spends (credits to 1110) after that float.
  -- Tie-break with ctid: now() is txn-stable so same-batch posts share posted_at.
  SELECT COALESCE(SUM(l.credit), 0)
  INTO v_amount
  FROM public.journal_entry_lines l
  JOIN public.journal_entries e ON e.id = l.journal_entry_id
  WHERE e.status = 'posted'
    AND e.currency = p_currency
    AND l.account_code = '1110'
    AND l.credit > 0
    AND e.entry_date <= COALESCE(p_as_of, CURRENT_DATE)
    AND (
      v_last_id IS NULL
      OR e.entry_date > v_last_date
      OR (
        e.entry_date = v_last_date
        AND e.posted_at > v_last_posted
      )
      OR (
        e.entry_date = v_last_date
        AND e.posted_at IS NOT DISTINCT FROM v_last_posted
        AND e.ctid > (
          SELECT j.ctid FROM public.journal_entries j WHERE j.id = v_last_id
        )
      )
    );

  RETURN COALESCE(v_amount, 0);
END;
$$;


--
-- Name: confirm_pick_lines(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_pick_lines(p_pick_list_id uuid, p_lines jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_pick public.pick_lists%ROWTYPE;
  v_elem JSONB;
  v_line_id UUID;
  v_inv_line UUID;
  v_qty NUMERIC;
  v_qty_base NUMERIC;
  v_pl public.pick_list_lines%ROWTYPE;
  v_open NUMERIC;
BEGIN
  PERFORM public._logistics_begin_rpc();
  PERFORM public._require_logistics_staff();

  SELECT * INTO v_pick FROM public.pick_lists WHERE id = p_pick_list_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'pick list not found';
  END IF;
  IF v_pick.status <> 'draft' THEN
    RAISE EXCEPTION 'only draft pick lists can be confirmed (status=%)', v_pick.status;
  END IF;

  IF p_lines IS NULL OR jsonb_typeof(p_lines) <> 'array' OR jsonb_array_length(p_lines) = 0 THEN
    RAISE EXCEPTION 'confirm_pick_lines requires lines array';
  END IF;

  FOR v_elem IN SELECT * FROM jsonb_array_elements(p_lines)
  LOOP
    v_line_id := NULLIF(v_elem ->> 'pick_list_line_id', '')::uuid;
    v_inv_line := NULLIF(v_elem ->> 'sales_invoice_line_id', '')::uuid;
    v_qty := (v_elem ->> 'qty_picked')::numeric;
    IF v_qty IS NULL OR v_qty < 0 THEN
      RAISE EXCEPTION 'qty_picked required (>= 0)';
    END IF;

    IF v_line_id IS NOT NULL THEN
      SELECT * INTO v_pl FROM public.pick_list_lines WHERE id = v_line_id AND pick_list_id = p_pick_list_id;
    ELSIF v_inv_line IS NOT NULL THEN
      SELECT * INTO v_pl
      FROM public.pick_list_lines
      WHERE pick_list_id = p_pick_list_id AND sales_invoice_line_id = v_inv_line;
    ELSE
      RAISE EXCEPTION 'pick_list_line_id or sales_invoice_line_id required';
    END IF;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'pick list line not found';
    END IF;

    v_qty_base := public.convert_to_base_uom(v_pl.stock_item_id, v_pl.uom_id, v_qty);

    -- Open vs invoice fulfilled (ignore this pick's prior qty_picked)
    SELECT GREATEST(
      sil.qty_base - sil.qty_fulfilled - COALESCE((
        SELECT SUM(pll.qty_base_picked)
        FROM public.pick_list_lines pll
        JOIN public.pick_lists pl ON pl.id = pll.pick_list_id
        WHERE pll.sales_invoice_line_id = v_pl.sales_invoice_line_id
          AND pl.status IN ('draft', 'done')
          AND pll.id <> v_pl.id
      ), 0),
      0
    )
    INTO v_open
    FROM public.sales_invoice_lines sil
    WHERE sil.id = v_pl.sales_invoice_line_id;

    IF v_qty_base > v_open THEN
      RAISE EXCEPTION 'over-pick denied: open=% requested=% for line %',
        v_open, v_qty_base, v_pl.sales_invoice_line_id;
    END IF;

    IF v_qty_base > v_pl.qty_base_requested THEN
      RAISE EXCEPTION 'qty_picked exceeds qty_requested on pick line';
    END IF;

    UPDATE public.pick_list_lines
    SET qty_picked = v_qty, qty_base_picked = v_qty_base
    WHERE id = v_pl.id;
  END LOOP;

  UPDATE public.pick_lists
  SET status = 'done', confirmed_at = now(), updated_at = now()
  WHERE id = p_pick_list_id;

  RETURN p_pick_list_id;
END;
$$;


--
-- Name: convert_material_request_to_po(uuid, uuid, public.currency_code, numeric, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.convert_material_request_to_po(p_material_request_id uuid, p_supplier_id uuid, p_currency public.currency_code, p_exchange_rate numeric, p_line_ids uuid[] DEFAULT NULL::uuid[]) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_mr public.material_requests%ROWTYPE;
  v_po UUID;
  v_lines JSONB := '[]'::jsonb;
  v_row RECORD;
  v_po_line UUID;
  v_remaining NUMERIC;
BEGIN
  PERFORM public._procurement_begin_rpc();
  PERFORM public._require_procurement_staff();
  PERFORM public._assert_procurement_period_open();

  SELECT * INTO v_mr FROM public.material_requests WHERE id = p_material_request_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'material request not found: %', p_material_request_id;
  END IF;
  IF v_mr.status <> 'approved' THEN
    RAISE EXCEPTION 'material request must be approved before conversion (status=%)', v_mr.status;
  END IF;

  FOR v_row IN
    SELECT mrl.*
    FROM public.material_request_lines mrl
    WHERE mrl.material_request_id = p_material_request_id
      AND mrl.qty > mrl.qty_converted
      AND (p_line_ids IS NULL OR mrl.id = ANY (p_line_ids))
    ORDER BY mrl.line_no
  LOOP
    v_remaining := v_row.qty - v_row.qty_converted;
    IF v_remaining <= 0 THEN
      CONTINUE;
    END IF;

    v_lines := v_lines || jsonb_build_array(
      jsonb_build_object(
        'stock_item_id', v_row.stock_item_id,
        'uom_id', v_row.uom_id,
        'qty', v_remaining,
        'unit_price', COALESCE(
          (SELECT pli.unit_price
           FROM public.price_list_items pli
           JOIN public.price_lists pl ON pl.id = pli.price_list_id
           WHERE pl.code = 'B2B' AND pli.stock_item_id = v_row.stock_item_id
           LIMIT 1),
          0
        ),
        'currency', p_currency,
        'material_request_line_id', v_row.id
      )
    );
  END LOOP;

  IF jsonb_array_length(v_lines) = 0 THEN
    RAISE EXCEPTION 'no open MR lines to convert';
  END IF;

  v_po := public.create_purchase_order(
    p_supplier_id,
    v_mr.warehouse_id,
    p_currency,
    p_exchange_rate,
    v_lines,
    format('Converted from %s', COALESCE(v_mr.document_number, v_mr.id::text)),
    v_mr.needed_by,
    p_material_request_id
  );

  FOR v_row IN
    SELECT mrl.*
    FROM public.material_request_lines mrl
    WHERE mrl.material_request_id = p_material_request_id
      AND mrl.qty > mrl.qty_converted
      AND (p_line_ids IS NULL OR mrl.id = ANY (p_line_ids))
    ORDER BY mrl.line_no
  LOOP
    v_remaining := v_row.qty - v_row.qty_converted;
    SELECT pol.id INTO v_po_line
    FROM public.purchase_order_lines pol
    WHERE pol.purchase_order_id = v_po
      AND pol.material_request_line_id = v_row.id
    LIMIT 1;

    IF v_po_line IS NULL THEN
      RAISE EXCEPTION 'orphan PO line mapping for MR line %', v_row.id;
    END IF;

    UPDATE public.material_request_lines
    SET
      qty_converted = qty_converted + v_remaining,
      purchase_order_line_id = v_po_line
    WHERE id = v_row.id;
  END LOOP;

  IF EXISTS (
    SELECT 1
    FROM public.purchase_order_lines pol
    WHERE pol.purchase_order_id = v_po
      AND pol.material_request_line_id IS NULL
  ) THEN
    RAISE EXCEPTION 'PO contains lines without MR linkage';
  END IF;

  PERFORM public._procurement_end_rpc();
  RETURN v_po;
EXCEPTION
  WHEN OTHERS THEN
    PERFORM public._procurement_end_rpc();
    RAISE;
END;
$$;


--
-- Name: convert_pos_quotation_to_cart(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.convert_pos_quotation_to_cart(p_quotation_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_q public.pos_quotations%ROWTYPE;
  v_cart_id UUID;
  v_src public.pos_quotation_lines%ROWTYPE;
  v_line_map JSONB := '{}'::jsonb;
  v_new_id UUID;
  v_parent UUID;
BEGIN
  PERFORM public._require_sales_staff();
  SELECT * INTO v_q FROM public.pos_quotations WHERE id = p_quotation_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'quotation not found: %', p_quotation_id;
  END IF;
  IF v_q.status NOT IN ('issued', 'sent') THEN
    RAISE EXCEPTION 'quotation cannot be converted (status=%)', v_q.status;
  END IF;
  IF v_q.valid_until IS NOT NULL AND v_q.valid_until < CURRENT_DATE THEN
    UPDATE public.pos_quotations
    SET status = 'expired', updated_at = now()
    WHERE id = p_quotation_id;
    RAISE EXCEPTION 'quotation expired on %', v_q.valid_until;
  END IF;
  IF v_q.converted_cart_id IS NOT NULL THEN
    RAISE EXCEPTION 'quotation already converted';
  END IF;

  INSERT INTO public.pos_carts (
    customer_id, warehouse_id, currency, exchange_rate_applied,
    status, created_by
  ) VALUES (
    v_q.customer_id, v_q.warehouse_id, v_q.currency, v_q.exchange_rate_applied,
    'open', auth.uid()
  )
  RETURNING id INTO v_cart_id;

  FOR v_src IN
    SELECT * FROM public.pos_quotation_lines
    WHERE quotation_id = p_quotation_id AND parent_line_id IS NULL
    ORDER BY sort_order, created_at
  LOOP
    INSERT INTO public.pos_cart_lines (
      cart_id, stock_item_id, is_core_charge, uom_id,
      qty, qty_base, unit_price, line_total
    ) VALUES (
      v_cart_id, v_src.stock_item_id, v_src.is_core_charge, v_src.uom_id,
      v_src.qty, v_src.qty_base, v_src.unit_price, v_src.line_total
    )
    RETURNING id INTO v_new_id;
    v_line_map := v_line_map || jsonb_build_object(v_src.id::text, v_new_id::text);
  END LOOP;

  FOR v_src IN
    SELECT * FROM public.pos_quotation_lines
    WHERE quotation_id = p_quotation_id AND parent_line_id IS NOT NULL
    ORDER BY sort_order, created_at
  LOOP
    v_parent := NULLIF(v_line_map ->> v_src.parent_line_id::text, '')::UUID;
    INSERT INTO public.pos_cart_lines (
      cart_id, stock_item_id, parent_line_id, is_core_charge, uom_id,
      qty, qty_base, unit_price, line_total
    ) VALUES (
      v_cart_id, v_src.stock_item_id, v_parent, v_src.is_core_charge, v_src.uom_id,
      v_src.qty, v_src.qty_base, v_src.unit_price, v_src.line_total
    );
  END LOOP;

  UPDATE public.pos_quotations
  SET
    status = 'converted',
    converted_cart_id = v_cart_id,
    updated_at = now()
  WHERE id = p_quotation_id;

  PERFORM public._log_pos_action(
    'quotation_converted',
    'pos_quotations',
    p_quotation_id,
    jsonb_build_object('status', v_q.status),
    jsonb_build_object('status', 'converted', 'cart_id', v_cart_id),
    NULL
  );

  RETURN v_cart_id;
END;
$$;


--
-- Name: convert_to_base_uom(uuid, uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.convert_to_base_uom(p_stock_item_id uuid, p_from_uom_id uuid, p_qty numeric) RETURNS numeric
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_base UUID;
  v_factor NUMERIC;
BEGIN
  SELECT base_uom_id INTO v_base FROM public.stock_items WHERE id = p_stock_item_id;
  IF v_base IS NULL THEN
    RAISE EXCEPTION 'stock item missing base_uom: %', p_stock_item_id;
  END IF;
  IF p_from_uom_id = v_base THEN
    RETURN p_qty;
  END IF;

  SELECT factor INTO v_factor
  FROM public.item_uom_conversions
  WHERE stock_item_id = p_stock_item_id
    AND from_uom_id = p_from_uom_id
    AND to_uom_id = v_base;

  IF v_factor IS NULL THEN
    -- try inverse: base → from means factor is base per from, so qty_base = qty / factor
    SELECT factor INTO v_factor
    FROM public.item_uom_conversions
    WHERE stock_item_id = p_stock_item_id
      AND from_uom_id = v_base
      AND to_uom_id = p_from_uom_id;
    IF v_factor IS NULL THEN
      RAISE EXCEPTION 'no UOM conversion for item % from %', p_stock_item_id, p_from_uom_id;
    END IF;
    RETURN round(p_qty / v_factor, 3);
  END IF;

  RETURN round(p_qty * v_factor, 3);
END;
$$;


--
-- Name: create_blanket_purchase_order(uuid, uuid, public.currency_code, numeric, numeric, jsonb, text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_blanket_purchase_order(p_supplier_id uuid, p_warehouse_id uuid, p_currency public.currency_code, p_exchange_rate numeric, p_blanket_max_value numeric, p_lines jsonb, p_notes text DEFAULT NULL::text, p_expected_date date DEFAULT NULL::date) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_po UUID;
  v_line JSONB;
  v_no INT := 0;
  v_rate NUMERIC;
BEGIN
  PERFORM public._procurement_begin_rpc();
  PERFORM public._require_procurement_staff();

  IF p_blanket_max_value IS NULL OR p_blanket_max_value < 0 THEN
    RAISE EXCEPTION 'blanket_max_value required';
  END IF;
  IF p_lines IS NULL OR jsonb_array_length(p_lines) = 0 THEN
    RAISE EXCEPTION 'blanket lines required';
  END IF;

  v_rate := CASE
    WHEN p_currency = 'USD' THEN COALESCE(p_exchange_rate, 1)
    ELSE p_exchange_rate
  END;
  IF p_currency = 'ZIG' AND (v_rate IS NULL OR v_rate <= 0) THEN
    RAISE EXCEPTION 'positive exchange_rate required for ZIG';
  END IF;

  INSERT INTO public.purchase_orders (
    document_number, supplier_id, warehouse_id, currency, exchange_rate_applied,
    expected_date, notes, created_by, is_blanket, blanket_max_value
  )
  VALUES (
    public.next_series_value('BPO-'),
    p_supplier_id,
    p_warehouse_id,
    p_currency,
    v_rate,
    p_expected_date,
    p_notes,
    auth.uid(),
    true,
    p_blanket_max_value
  )
  RETURNING id INTO v_po;

  FOR v_line IN SELECT * FROM jsonb_array_elements(p_lines)
  LOOP
    v_no := v_no + 1;
    INSERT INTO public.purchase_order_lines (
      purchase_order_id, line_no, stock_item_id, uom_id, qty_ordered, unit_price, currency
    )
    VALUES (
      v_po,
      v_no,
      (v_line ->> 'stock_item_id')::uuid,
      (v_line ->> 'uom_id')::uuid,
      (v_line ->> 'qty')::numeric,
      (v_line ->> 'unit_price')::numeric,
      COALESCE((v_line ->> 'currency')::public.currency_code, p_currency)
    );
  END LOOP;

  PERFORM public._procurement_end_rpc();
  RETURN v_po;
EXCEPTION
  WHEN OTHERS THEN
    PERFORM public._procurement_end_rpc();
    RAISE;
END;
$$;


--
-- Name: create_blanket_release(uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_blanket_release(p_blanket_purchase_order_id uuid, p_lines jsonb, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_blanket public.purchase_orders%ROWTYPE;
  v_release UUID;
  v_line JSONB;
  v_no INT := 0;
  v_parent_line public.purchase_order_lines%ROWTYPE;
  v_release_value NUMERIC := 0;
  v_total_release NUMERIC := 0;
  v_qty NUMERIC;
BEGIN
  PERFORM public._procurement_begin_rpc();
  PERFORM public._require_procurement_staff();
  PERFORM public._assert_procurement_period_open();

  SELECT * INTO v_blanket FROM public.purchase_orders WHERE id = p_blanket_purchase_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'blanket PO not found: %', p_blanket_purchase_order_id;
  END IF;
  IF NOT v_blanket.is_blanket THEN
    RAISE EXCEPTION 'purchase order is not a blanket contract';
  END IF;
  IF v_blanket.status <> 'approved' THEN
    RAISE EXCEPTION 'blanket PO must be approved before release (status=%)', v_blanket.status;
  END IF;

  IF p_lines IS NULL OR jsonb_array_length(p_lines) = 0 THEN
    RAISE EXCEPTION 'release lines required';
  END IF;

  FOR v_line IN SELECT * FROM jsonb_array_elements(p_lines)
  LOOP
    v_qty := (v_line ->> 'qty')::numeric;
    IF v_qty IS NULL OR v_qty <= 0 THEN
      RAISE EXCEPTION 'release qty must be positive';
    END IF;

    SELECT * INTO v_parent_line
    FROM public.purchase_order_lines
    WHERE id = (v_line ->> 'blanket_line_id')::uuid
      AND purchase_order_id = p_blanket_purchase_order_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'blanket line not found: %', v_line ->> 'blanket_line_id';
    END IF;

    IF v_parent_line.qty_released + v_qty > v_parent_line.qty_ordered THEN
      RAISE EXCEPTION 'release exceeds remaining qty on line %', v_parent_line.line_no;
    END IF;

    v_release_value := v_qty * v_parent_line.unit_price;
    v_total_release := v_total_release + v_release_value;
  END LOOP;

  IF v_blanket.blanket_value_released + v_total_release > v_blanket.blanket_max_value THEN
    RAISE EXCEPTION 'release exceeds remaining blanket value';
  END IF;

  INSERT INTO public.purchase_orders (
    document_number, supplier_id, warehouse_id, currency, exchange_rate_applied,
    notes, created_by, blanket_parent_id
  )
  VALUES (
    public.next_series_value('PO-'),
    v_blanket.supplier_id,
    v_blanket.warehouse_id,
    v_blanket.currency,
    v_blanket.exchange_rate_applied,
    p_notes,
    auth.uid(),
    p_blanket_purchase_order_id
  )
  RETURNING id INTO v_release;

  FOR v_line IN SELECT * FROM jsonb_array_elements(p_lines)
  LOOP
    v_qty := (v_line ->> 'qty')::numeric;

    SELECT * INTO v_parent_line
    FROM public.purchase_order_lines
    WHERE id = (v_line ->> 'blanket_line_id')::uuid
      AND purchase_order_id = p_blanket_purchase_order_id
    FOR UPDATE;

    v_no := v_no + 1;
    INSERT INTO public.purchase_order_lines (
      purchase_order_id, line_no, stock_item_id, uom_id,
      qty_ordered, unit_price, currency, blanket_parent_line_id
    )
    VALUES (
      v_release,
      v_no,
      v_parent_line.stock_item_id,
      v_parent_line.uom_id,
      v_qty,
      v_parent_line.unit_price,
      v_parent_line.currency,
      v_parent_line.id
    );

    UPDATE public.purchase_order_lines
    SET qty_released = qty_released + v_qty
    WHERE id = v_parent_line.id;
  END LOOP;

  UPDATE public.purchase_orders
  SET blanket_value_released = blanket_value_released + v_total_release, updated_at = now()
  WHERE id = p_blanket_purchase_order_id;

  PERFORM public._procurement_end_rpc();
  RETURN v_release;
EXCEPTION
  WHEN OTHERS THEN
    PERFORM public._procurement_end_rpc();
    RAISE;
END;
$$;


--
-- Name: create_consignment_entry_draft(public.consignment_kind, public.consignment_entry_purpose, uuid, uuid, uuid, public.currency_code, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_consignment_entry_draft(p_kind public.consignment_kind, p_purpose public.consignment_entry_purpose, p_warehouse_id uuid, p_supplier_id uuid DEFAULT NULL::uuid, p_customer_id uuid DEFAULT NULL::uuid, p_currency public.currency_code DEFAULT 'USD'::public.currency_code, p_exchange_rate numeric DEFAULT 1, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id UUID;
  v_rate NUMERIC;
BEGIN
  PERFORM public._require_consignment_staff();

  IF p_kind = 'supplier_owned' THEN
    IF p_supplier_id IS NULL OR p_customer_id IS NOT NULL THEN
      RAISE EXCEPTION 'supplier_owned requires supplier_id and no customer_id';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.suppliers WHERE id = p_supplier_id AND is_active) THEN
      RAISE EXCEPTION 'supplier not found or inactive';
    END IF;
  ELSE
    IF p_customer_id IS NULL OR p_supplier_id IS NOT NULL THEN
      RAISE EXCEPTION 'customer_held requires customer_id and no supplier_id';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.customers WHERE id = p_customer_id) THEN
      RAISE EXCEPTION 'customer not found';
    END IF;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.warehouses WHERE id = p_warehouse_id AND is_active AND NOT is_quarantine
  ) THEN
    RAISE EXCEPTION 'warehouse must be active non-quarantine';
  END IF;

  v_rate := CASE
    WHEN p_currency = 'USD' THEN COALESCE(p_exchange_rate, 1)
    ELSE p_exchange_rate
  END;
  IF p_currency <> 'USD' AND (v_rate IS NULL OR v_rate <= 0) THEN
    RAISE EXCEPTION 'exchange_rate_applied required for non-USD';
  END IF;

  PERFORM set_config('gtr.consignment_rpc', 'on', true);

  INSERT INTO public.consignment_entries (
    document_number, status, kind, purpose, supplier_id, customer_id,
    warehouse_id, currency, exchange_rate_applied, notes, created_by
  )
  VALUES (
    public.next_series_value('CNS-'),
    'draft',
    p_kind,
    p_purpose,
    p_supplier_id,
    p_customer_id,
    p_warehouse_id,
    p_currency,
    v_rate,
    p_notes,
    auth.uid()
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


--
-- Name: create_contipay_intent(text, public.contipay_method, numeric, public.currency_code, numeric, uuid, public.currency_code, numeric, numeric, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_contipay_intent(p_external_ref text, p_method public.contipay_method, p_amount numeric, p_currency public.currency_code DEFAULT 'USD'::public.currency_code, p_exchange_rate numeric DEFAULT 1, p_customer_id uuid DEFAULT NULL::uuid, p_settlement_currency public.currency_code DEFAULT NULL::public.currency_code, p_settlement_amount numeric DEFAULT NULL::numeric, p_settlement_exchange_rate numeric DEFAULT NULL::numeric, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id UUID;
BEGIN
  PERFORM public._require_payments_staff();
  PERFORM public._payments_rpc_enter();

  IF p_external_ref IS NULL OR length(trim(p_external_ref)) = 0 THEN
    RAISE EXCEPTION 'external_ref required';
  END IF;
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION 'amount must be > 0';
  END IF;

  INSERT INTO public.contipay_payment_intents (
    external_ref, method, customer_id, amount, currency, exchange_rate_applied,
    settlement_currency, settlement_amount, settlement_exchange_rate,
    metadata, created_by
  )
  VALUES (
    trim(p_external_ref),
    p_method,
    p_customer_id,
    p_amount,
    p_currency,
    CASE WHEN p_currency = 'USD' THEN COALESCE(p_exchange_rate, 1) ELSE p_exchange_rate END,
    p_settlement_currency,
    p_settlement_amount,
    p_settlement_exchange_rate,
    COALESCE(p_metadata, '{}'::jsonb),
    auth.uid()
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


--
-- Name: create_customer_cart(uuid, public.currency_code, public.fulfillment_mode, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_customer_cart(p_warehouse_id uuid, p_currency public.currency_code DEFAULT 'USD'::public.currency_code, p_fulfillment_mode public.fulfillment_mode DEFAULT 'dispatch'::public.fulfillment_mode, p_exchange_rate numeric DEFAULT 1) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_cust uuid := public._current_customer_id();
  v_id uuid;
  v_rate numeric;
BEGIN
  IF v_cust IS NULL THEN
    RAISE EXCEPTION 'customer profile required';
  END IF;
  IF p_warehouse_id IS NULL THEN
    RAISE EXCEPTION 'warehouse_id required';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.warehouses w
    WHERE w.id = p_warehouse_id
      AND w.is_active = true
      AND COALESCE(w.is_quarantine, false) = false
  ) THEN
    RAISE EXCEPTION 'saleable warehouse not found or inactive';
  END IF;

  IF p_currency = 'USD'::public.currency_code THEN
    v_rate := 1;
  ELSIF p_currency = 'ZIG'::public.currency_code THEN
    v_rate := public.get_zig_exchange_rate(CURRENT_DATE);
    IF v_rate IS NULL OR v_rate <= 0 THEN
      RAISE EXCEPTION 'ZiG sales unavailable: no authoritative exchange rate configured';
    END IF;
  ELSE
    RAISE EXCEPTION 'unsupported cart currency: %', p_currency;
  END IF;

  -- p_exchange_rate is retained only for API compatibility; commercial FX is server authoritative.
  INSERT INTO public.pos_carts(
    document_number, customer_id, warehouse_id, currency,
    exchange_rate_applied, fulfillment_mode, channel, created_by
  )
  VALUES(
    public.next_series_value('CART-'), v_cust, p_warehouse_id, p_currency,
    v_rate, COALESCE(p_fulfillment_mode, 'dispatch'::public.fulfillment_mode),
    'storefront', auth.uid()
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


--
-- Name: create_customer_contipay_intent(uuid, public.contipay_method, text, numeric, public.currency_code, numeric, numeric, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_customer_contipay_intent(p_sales_invoice_id uuid, p_method public.contipay_method, p_external_ref text DEFAULT NULL::text, p_amount numeric DEFAULT NULL::numeric, p_settlement_currency public.currency_code DEFAULT NULL::public.currency_code, p_settlement_amount numeric DEFAULT NULL::numeric, p_settlement_exchange_rate numeric DEFAULT NULL::numeric, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_cust uuid := public._current_customer_id();
  v_order public.commerce_orders%ROWTYPE;
  v_inv public.sales_invoices%ROWTYPE;
  v_open numeric;
  v_amount numeric;
  v_ref text;
  v_id uuid;
BEGIN
  IF v_cust IS NULL THEN RAISE EXCEPTION 'customer profile required'; END IF;

  SELECT * INTO v_order
  FROM public.commerce_orders
  WHERE id=p_sales_invoice_id AND customer_id=v_cust
  FOR UPDATE;

  IF FOUND THEN
    IF v_order.settled_payment_entry_id IS NOT NULL THEN RAISE EXCEPTION 'commerce order already paid'; END IF;
    IF v_order.reservation_expires_at IS NULL OR v_order.reservation_expires_at<=now() THEN
      PERFORM private.release_commerce_order(v_order.id,'payment_expired','payment attempted after reservation expiry');
      RAISE EXCEPTION 'checkout reservation expired; rebuild checkout';
    END IF;
    IF v_order.state NOT IN ('awaiting_payment','payment_processing','payment_failed') THEN RAISE EXCEPTION 'commerce order cannot accept payment in state %',v_order.state; END IF;

    v_amount:=COALESCE(p_amount,v_order.total);
    IF abs(v_amount-v_order.total)>0.001 THEN RAISE EXCEPTION 'commerce checkout requires full payment of %',v_order.total; END IF;

    v_id := private.active_commerce_payment_intent(v_order.id,'contipay');
    IF v_id IS NOT NULL THEN RETURN v_id; END IF;

    v_ref:=COALESCE(NULLIF(trim(p_external_ref),''),'CP-ORD-'||v_order.id::text||'-'||gen_random_uuid()::text);
    INSERT INTO public.contipay_payment_intents(
      external_ref,method,customer_id,amount,currency,exchange_rate_applied,
      settlement_currency,settlement_amount,settlement_exchange_rate,
      commerce_order_id,metadata,created_by
    ) VALUES(
      v_ref,p_method,v_order.customer_id,v_amount,v_order.currency,v_order.exchange_rate_applied,
      p_settlement_currency,p_settlement_amount,p_settlement_exchange_rate,
      v_order.id,COALESCE(p_metadata,'{}'::jsonb)||jsonb_build_object('commerce_order_id',v_order.id,'channel','storefront'),auth.uid()
    ) RETURNING id INTO v_id;

    UPDATE public.commerce_orders
    SET state='payment_processing',active_payment_provider='contipay',active_payment_intent_id=v_id,updated_at=now()
    WHERE id=v_order.id;

    PERFORM private.enqueue_commerce_event(
      'commerce:'||v_order.id::text||':contipay:'||v_id::text,
      'commerce.payment_intent_created',v_order.id,
      jsonb_build_object('provider','contipay','intent_id',v_id)
    );
    RETURN v_id;
  END IF;

  v_inv:=public._assert_customer_owns_invoice(p_sales_invoice_id);
  IF v_inv.doc_type<>'invoice' OR v_inv.status<>'posted' THEN RAISE EXCEPTION 'only posted invoices can receive payment intents'; END IF;
  v_open:=v_inv.total-v_inv.amount_paid;
  IF v_open<=0 THEN RAISE EXCEPTION 'invoice has no open balance'; END IF;
  v_amount:=COALESCE(p_amount,v_open);
  IF v_amount<=0 OR v_amount>v_open THEN RAISE EXCEPTION 'invalid payment amount'; END IF;
  v_ref:=COALESCE(NULLIF(trim(p_external_ref),''),'CP-CUST-'||v_inv.id::text||'-'||gen_random_uuid()::text);

  INSERT INTO public.contipay_payment_intents(
    external_ref,method,customer_id,amount,currency,exchange_rate_applied,
    settlement_currency,settlement_amount,settlement_exchange_rate,metadata,created_by
  ) VALUES(
    v_ref,p_method,v_inv.customer_id,v_amount,v_inv.currency,v_inv.exchange_rate_applied,
    p_settlement_currency,p_settlement_amount,p_settlement_exchange_rate,
    COALESCE(p_metadata,'{}'::jsonb)||jsonb_build_object('sales_invoice_id',v_inv.id,'channel','storefront'),auth.uid()
  ) RETURNING id INTO v_id;
  RETURN v_id;
END;
$$;


--
-- Name: create_customer_ecocash_intent(uuid, text, text, text, numeric, text, public.currency_code, numeric, numeric, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_customer_ecocash_intent(p_sales_invoice_id uuid, p_payer_msisdn text, p_payer_mode text DEFAULT 'other'::text, p_external_ref text DEFAULT NULL::text, p_amount numeric DEFAULT NULL::numeric, p_channel text DEFAULT 'web'::text, p_settlement_currency public.currency_code DEFAULT NULL::public.currency_code, p_settlement_amount numeric DEFAULT NULL::numeric, p_settlement_exchange_rate numeric DEFAULT NULL::numeric, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_cust uuid := public._current_customer_id();
  v_order public.commerce_orders%ROWTYPE;
  v_inv public.sales_invoices%ROWTYPE;
  v_open numeric;
  v_amount numeric;
  v_ref text;
  v_id uuid;
  v_msisdn text;
BEGIN
  IF v_cust IS NULL THEN RAISE EXCEPTION 'customer profile required'; END IF;
  IF p_payer_mode IS NULL OR p_payer_mode NOT IN ('whatsapp','saved','other','pos_entered','profile') THEN RAISE EXCEPTION 'invalid payer_mode'; END IF;
  IF p_channel IS NULL OR p_channel NOT IN ('whatsapp_flow','web','pos','ios','android_customer','api') THEN RAISE EXCEPTION 'invalid channel'; END IF;

  v_msisdn:=regexp_replace(trim(COALESCE(p_payer_msisdn,'')),'[^0-9]','','g');
  IF v_msisdn~'^0[0-9]{9}$' THEN v_msisdn:='263'||substr(v_msisdn,2); END IF;
  IF v_msisdn!~'^263[0-9]{9}$' THEN RAISE EXCEPTION 'payer_msisdn must normalize to 263XXXXXXXXX'; END IF;

  SELECT * INTO v_order
  FROM public.commerce_orders
  WHERE id=p_sales_invoice_id AND customer_id=v_cust
  FOR UPDATE;

  IF FOUND THEN
    IF v_order.settled_payment_entry_id IS NOT NULL THEN RAISE EXCEPTION 'commerce order already paid'; END IF;
    IF v_order.reservation_expires_at IS NULL OR v_order.reservation_expires_at<=now() THEN
      PERFORM private.release_commerce_order(v_order.id,'payment_expired','payment attempted after reservation expiry');
      RAISE EXCEPTION 'checkout reservation expired; rebuild checkout';
    END IF;
    IF v_order.state NOT IN ('awaiting_payment','payment_processing','payment_failed') THEN RAISE EXCEPTION 'commerce order cannot accept payment in state %',v_order.state; END IF;

    v_amount:=COALESCE(p_amount,v_order.total);
    IF abs(v_amount-v_order.total)>0.001 THEN RAISE EXCEPTION 'commerce checkout requires full payment of %',v_order.total; END IF;

    v_id := private.active_commerce_payment_intent(v_order.id,'ecocash');
    IF v_id IS NOT NULL THEN RETURN v_id; END IF;

    v_ref:=COALESCE(NULLIF(trim(p_external_ref),''),'EC-ORD-'||v_order.id::text||'-'||gen_random_uuid()::text);
    INSERT INTO public.ecocash_payment_intents(
      external_ref,payer_msisdn,payer_mode,channel,customer_id,sales_invoice_id,
      amount,currency,exchange_rate_applied,settlement_currency,settlement_amount,
      settlement_exchange_rate,commerce_order_id,metadata,created_by
    ) VALUES(
      v_ref,v_msisdn,p_payer_mode,p_channel,v_order.customer_id,NULL,
      v_amount,v_order.currency,v_order.exchange_rate_applied,p_settlement_currency,
      p_settlement_amount,p_settlement_exchange_rate,v_order.id,
      COALESCE(p_metadata,'{}'::jsonb)||jsonb_build_object('commerce_order_id',v_order.id,'channel',p_channel),auth.uid()
    ) RETURNING id INTO v_id;

    UPDATE public.commerce_orders
    SET state='payment_processing',active_payment_provider='ecocash',active_payment_intent_id=v_id,updated_at=now()
    WHERE id=v_order.id;

    PERFORM private.enqueue_commerce_event(
      'commerce:'||v_order.id::text||':ecocash:'||v_id::text,
      'commerce.payment_intent_created',v_order.id,
      jsonb_build_object('provider','ecocash','intent_id',v_id)
    );
    RETURN v_id;
  END IF;

  v_inv:=public._assert_customer_owns_invoice(p_sales_invoice_id);
  IF v_inv.doc_type<>'invoice' OR v_inv.status<>'posted' THEN RAISE EXCEPTION 'only posted invoices can receive payment intents'; END IF;
  v_open:=v_inv.total-v_inv.amount_paid;
  IF v_open<=0 THEN RAISE EXCEPTION 'invoice has no open balance'; END IF;
  v_amount:=COALESCE(p_amount,v_open);
  IF v_amount<=0 OR v_amount>v_open THEN RAISE EXCEPTION 'invalid payment amount'; END IF;
  v_ref:=COALESCE(NULLIF(trim(p_external_ref),''),'EC-CUST-'||v_inv.id::text||'-'||gen_random_uuid()::text);

  INSERT INTO public.ecocash_payment_intents(
    external_ref,payer_msisdn,payer_mode,channel,customer_id,sales_invoice_id,
    amount,currency,exchange_rate_applied,settlement_currency,settlement_amount,
    settlement_exchange_rate,metadata,created_by
  ) VALUES(
    v_ref,v_msisdn,p_payer_mode,p_channel,v_inv.customer_id,v_inv.id,
    v_amount,v_inv.currency,v_inv.exchange_rate_applied,p_settlement_currency,
    p_settlement_amount,p_settlement_exchange_rate,
    COALESCE(p_metadata,'{}'::jsonb)||jsonb_build_object('sales_invoice_id',v_inv.id,'channel',p_channel),auth.uid()
  ) RETURNING id INTO v_id;
  RETURN v_id;
END;
$_$;


--
-- Name: FUNCTION create_customer_ecocash_intent(p_sales_invoice_id uuid, p_payer_msisdn text, p_payer_mode text, p_external_ref text, p_amount numeric, p_channel text, p_settlement_currency public.currency_code, p_settlement_amount numeric, p_settlement_exchange_rate numeric, p_metadata jsonb); Type: COMMENT; Schema: public; Owner: -
