--
-- Name: create_delivery_job(uuid, uuid, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_delivery_job(p_delivery_note_id uuid, p_assignee_user_id uuid DEFAULT NULL::uuid, p_eta_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_dn public.delivery_notes%ROWTYPE;
  v_job UUID;
BEGIN
  PERFORM public._logistics_begin_rpc();
  PERFORM public._require_dispatcher_staff();

  SELECT * INTO v_dn FROM public.delivery_notes WHERE id = p_delivery_note_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'delivery note not found';
  END IF;
  IF v_dn.status <> 'submitted' THEN
    RAISE EXCEPTION 'delivery job requires submitted DN (status=%)', v_dn.status;
  END IF;

  INSERT INTO public.delivery_jobs (
    document_number, delivery_note_id, assignee_user_id, status,
    eta_at, notes, created_by
  )
  VALUES (
    public.next_series_value('DJ-'),
    p_delivery_note_id,
    p_assignee_user_id,
    'pending',
    p_eta_at,
    p_notes,
    auth.uid()
  )
  RETURNING id INTO v_job;

  RETURN v_job;
END;
$$;


--
-- Name: create_delivery_note(uuid, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_delivery_note(p_sales_invoice_id uuid, p_lines jsonb, p_pick_list_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_inv public.sales_invoices%ROWTYPE;
  v_dn UUID;
  v_elem JSONB;
  v_inv_line UUID;
  v_qty NUMERIC;
  v_qty_base NUMERIC;
  v_line public.sales_invoice_lines%ROWTYPE;
  v_open NUMERIC;
  v_pick public.pick_lists%ROWTYPE;
  v_any BOOLEAN := false;
BEGIN
  PERFORM public._logistics_begin_rpc();
  PERFORM public._require_logistics_staff();

  SELECT * INTO v_inv
  FROM public.sales_invoices
  WHERE id = p_sales_invoice_id AND doc_type = 'invoice' AND status = 'posted'
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'posted sales invoice required';
  END IF;
  IF v_inv.fulfillment_mode <> 'dispatch' THEN
    RAISE EXCEPTION 'delivery notes blocked for immediate fulfillment invoices (no double-issue)';
  END IF;

  IF p_pick_list_id IS NOT NULL THEN
    SELECT * INTO v_pick FROM public.pick_lists WHERE id = p_pick_list_id;
    IF NOT FOUND OR v_pick.sales_invoice_id <> p_sales_invoice_id THEN
      RAISE EXCEPTION 'pick list must belong to invoice';
    END IF;
    IF v_pick.status = 'cancelled' THEN
      RAISE EXCEPTION 'cancelled pick list cannot create DN';
    END IF;
  END IF;

  IF p_lines IS NULL OR jsonb_typeof(p_lines) <> 'array' OR jsonb_array_length(p_lines) = 0 THEN
    RAISE EXCEPTION 'create_delivery_note requires lines array';
  END IF;

  INSERT INTO public.delivery_notes (
    document_number, sales_invoice_id, pick_list_id, warehouse_id,
    currency, exchange_rate_applied, status, created_by
  )
  VALUES (
    public.next_series_value('DN-'),
    p_sales_invoice_id,
    p_pick_list_id,
    v_inv.warehouse_id,
    v_inv.currency,
    v_inv.exchange_rate_applied,
    'draft',
    auth.uid()
  )
  RETURNING id INTO v_dn;

  FOR v_elem IN SELECT * FROM jsonb_array_elements(p_lines)
  LOOP
    v_inv_line := (v_elem ->> 'sales_invoice_line_id')::uuid;
    v_qty := (v_elem ->> 'qty')::numeric;
    IF v_inv_line IS NULL OR v_qty IS NULL OR v_qty <= 0 THEN
      RAISE EXCEPTION 'DN line requires sales_invoice_line_id and qty > 0';
    END IF;

    SELECT * INTO v_line
    FROM public.sales_invoice_lines
    WHERE id = v_inv_line AND invoice_id = p_sales_invoice_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'invoice line % not on invoice', v_inv_line;
    END IF;
    IF v_line.is_core_charge THEN
      RAISE EXCEPTION 'core-charge lines cannot ship on DN';
    END IF;

    v_qty_base := public.convert_to_base_uom(v_line.stock_item_id, v_line.uom_id, v_qty);
    v_open := public._invoice_line_open_qty_base(v_inv_line);
    IF v_qty_base > v_open THEN
      RAISE EXCEPTION 'DN qty exceeds open qty (open=%, requested=%)', v_open, v_qty_base;
    END IF;

    v_any := true;
    INSERT INTO public.delivery_note_lines (
      delivery_note_id, sales_invoice_line_id, stock_item_id, uom_id,
      qty, qty_base, currency
    )
    VALUES (
      v_dn, v_inv_line, v_line.stock_item_id, v_line.uom_id,
      v_qty, v_qty_base, v_inv.currency
    );
  END LOOP;

  IF NOT v_any THEN
    RAISE EXCEPTION 'DN requires at least one line';
  END IF;

  RETURN v_dn;
END;
$$;


--
-- Name: create_ecocash_intent(text, text, numeric, public.currency_code, numeric, text, text, uuid, uuid, uuid, public.currency_code, numeric, numeric, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_ecocash_intent(p_external_ref text, p_payer_msisdn text, p_amount numeric, p_currency public.currency_code DEFAULT 'USD'::public.currency_code, p_exchange_rate numeric DEFAULT 1, p_payer_mode text DEFAULT 'other'::text, p_channel text DEFAULT 'web'::text, p_customer_id uuid DEFAULT NULL::uuid, p_sales_invoice_id uuid DEFAULT NULL::uuid, p_whatsapp_flow_order_id uuid DEFAULT NULL::uuid, p_settlement_currency public.currency_code DEFAULT NULL::public.currency_code, p_settlement_amount numeric DEFAULT NULL::numeric, p_settlement_exchange_rate numeric DEFAULT NULL::numeric, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_id UUID;
  v_msisdn TEXT;
BEGIN
  PERFORM public._require_payments_staff();
  PERFORM public._payments_rpc_enter();

  IF p_external_ref IS NULL OR length(trim(p_external_ref)) = 0 THEN
    RAISE EXCEPTION 'external_ref required';
  END IF;
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION 'amount must be > 0';
  END IF;

  v_msisdn := regexp_replace(trim(COALESCE(p_payer_msisdn, '')), '[^0-9]', '', 'g');
  IF v_msisdn ~ '^0[0-9]{9}$' THEN
    v_msisdn := '263' || substr(v_msisdn, 2);
  END IF;
  IF v_msisdn !~ '^263[0-9]{9}$' THEN
    RAISE EXCEPTION 'payer_msisdn must normalize to 263XXXXXXXXX';
  END IF;

  IF p_payer_mode IS NULL OR p_payer_mode NOT IN (
    'whatsapp', 'saved', 'other', 'pos_entered', 'profile'
  ) THEN
    RAISE EXCEPTION 'invalid payer_mode';
  END IF;
  IF p_channel IS NULL OR p_channel NOT IN (
    'whatsapp_flow', 'web', 'pos', 'ios', 'android_customer', 'api'
  ) THEN
    RAISE EXCEPTION 'invalid channel';
  END IF;

  INSERT INTO public.ecocash_payment_intents (
    external_ref, payer_msisdn, payer_mode, channel, customer_id,
    sales_invoice_id, whatsapp_flow_order_id,
    amount, currency, exchange_rate_applied,
    settlement_currency, settlement_amount, settlement_exchange_rate,
    metadata, created_by
  )
  VALUES (
    trim(p_external_ref),
    v_msisdn,
    p_payer_mode,
    p_channel,
    p_customer_id,
    p_sales_invoice_id,
    p_whatsapp_flow_order_id,
    p_amount,
    p_currency,
    CASE WHEN p_currency = 'USD' THEN COALESCE(p_exchange_rate, 1) ELSE p_exchange_rate END,
    p_settlement_currency,
    p_settlement_amount,
    p_settlement_exchange_rate,
    COALESCE(p_metadata, '{}'::jsonb),
    auth.uid()
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$_$;


--
-- Name: create_employee(text, text, uuid, text, text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_employee(p_employee_code text DEFAULT NULL::text, p_full_name text DEFAULT NULL::text, p_user_id uuid DEFAULT NULL::uuid, p_email text DEFAULT NULL::text, p_phone_e164 text DEFAULT NULL::text, p_hire_date date DEFAULT NULL::date) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id UUID;
  v_code TEXT;
BEGIN
  PERFORM public._require_hr_staff();

  IF p_full_name IS NULL OR length(trim(p_full_name)) = 0 THEN
    RAISE EXCEPTION 'full_name required';
  END IF;

  v_code := COALESCE(NULLIF(trim(p_employee_code), ''), public.next_series_value('EMP-'));

  IF p_user_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.profiles WHERE id = p_user_id
  ) THEN
    RAISE EXCEPTION 'profile not found: %', p_user_id;
  END IF;

  INSERT INTO public.employees (
    employee_code, full_name, user_id, email, phone_e164, hire_date
  )
  VALUES (
    v_code, trim(p_full_name), p_user_id, p_email, p_phone_e164, p_hire_date
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


--
-- Name: create_finance_requisition(public.finance_requisition_type, numeric, public.currency_code, text, text, character varying, character varying, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_finance_requisition(p_req_type public.finance_requisition_type, p_amount numeric, p_currency public.currency_code, p_payee text DEFAULT NULL::text, p_memo text DEFAULT NULL::text, p_expense_account_code character varying DEFAULT '5300'::character varying, p_cash_account_code character varying DEFAULT NULL::character varying, p_exchange_rate numeric DEFAULT NULL::numeric) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE v_id UUID; v_cash VARCHAR(10); v_uid UUID:=auth.uid(); v_expense VARCHAR(10); v_fund VARCHAR(10):=public.petty_cash_funding_account_code(); BEGIN IF v_uid IS NULL THEN RAISE EXCEPTION 'auth.uid() required to create requisition'; END IF; IF NOT (auth.role()='service_role' OR public.is_staff() OR public.has_staff_role(ARRAY['admin','finance','sales','warehouse','dispatcher','hr']::public.staff_role[])) THEN RAISE EXCEPTION 'staff role required to create requisition'; END IF; IF p_amount IS NULL OR p_amount<=0 THEN RAISE EXCEPTION 'amount must be > 0'; END IF; IF p_currency='ZIG' AND (p_exchange_rate IS NULL OR p_exchange_rate<=0) THEN RAISE EXCEPTION 'exchange_rate_applied required for ZIG requisitions'; END IF; IF p_req_type='petty_float' THEN v_cash:='1110'; v_expense:=COALESCE(nullif(trim(p_expense_account_code),''),v_fund); ELSE v_expense:=COALESCE(nullif(trim(p_expense_account_code),''),'5300'); v_cash:=COALESCE(nullif(trim(p_cash_account_code),''),CASE WHEN p_req_type='petty_cash' THEN '1110' ELSE v_fund END); IF p_req_type='payment' AND v_cash='1110' THEN v_cash:=v_fund; END IF; END IF; IF NOT EXISTS(SELECT 1 FROM public.chart_of_accounts c WHERE c.code=v_expense AND c.is_active) THEN RAISE EXCEPTION 'expense account not found: %',v_expense; END IF; IF NOT EXISTS(SELECT 1 FROM public.chart_of_accounts c WHERE c.code=v_cash AND c.is_active) THEN RAISE EXCEPTION 'cash account not found: %',v_cash; END IF; PERFORM public._finance_req_rpc_enter(); INSERT INTO public.finance_requisitions(req_type,status,amount,currency,exchange_rate_applied,payee,memo,expense_account_code,cash_account_code,requested_by) VALUES(p_req_type,'draft',p_amount,p_currency,CASE WHEN p_currency='USD' THEN COALESCE(p_exchange_rate,1) ELSE p_exchange_rate END,nullif(trim(p_payee),''),nullif(trim(p_memo),''),v_expense,v_cash,v_uid) RETURNING id INTO v_id; INSERT INTO public.finance_requisition_lines(requisition_id,line_no,description,expense_account_code,amount) VALUES(v_id,1,COALESCE(nullif(trim(p_memo),''),nullif(trim(p_payee),''),'Requisition'),v_expense,p_amount); RETURN v_id; END; $$;


--
-- Name: create_goods_receipt(uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_goods_receipt(p_purchase_order_id uuid, p_lines jsonb, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_po public.purchase_orders%ROWTYPE;
  v_grn UUID;
  v_line JSONB;
BEGIN
  PERFORM public._procurement_begin_rpc();
  PERFORM public._require_procurement_staff();

  SELECT * INTO v_po FROM public.purchase_orders WHERE id = p_purchase_order_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'purchase order not found: %', p_purchase_order_id;
  END IF;
  IF v_po.status <> 'approved' THEN
    RAISE EXCEPTION 'purchase order must be approved before GRN (status=%)', v_po.status;
  END IF;

  IF p_lines IS NULL OR jsonb_array_length(p_lines) = 0 THEN
    RAISE EXCEPTION 'GRN lines required';
  END IF;

  INSERT INTO public.goods_receipts (
    document_number, purchase_order_id, supplier_id, warehouse_id, notes, created_by
  )
  VALUES (
    public.next_series_value('GRN-'),
    p_purchase_order_id,
    v_po.supplier_id,
    v_po.warehouse_id,
    p_notes,
    auth.uid()
  )
  RETURNING id INTO v_grn;

  FOR v_line IN SELECT * FROM jsonb_array_elements(p_lines)
  LOOP
    IF NOT EXISTS (
      SELECT 1 FROM public.purchase_order_lines pol
      WHERE pol.id = (v_line ->> 'purchase_order_line_id')::uuid
        AND pol.purchase_order_id = p_purchase_order_id
    ) THEN
      RAISE EXCEPTION 'invalid PO line for GRN: %', v_line ->> 'purchase_order_line_id';
    END IF;

    INSERT INTO public.goods_receipt_lines (
      goods_receipt_id,
      purchase_order_line_id,
      stock_item_id,
      uom_id,
      qty,
      unit_cost,
      currency
    )
    SELECT
      v_grn,
      pol.id,
      pol.stock_item_id,
      pol.uom_id,
      (v_line ->> 'qty')::numeric,
      COALESCE((v_line ->> 'unit_cost')::numeric, pol.unit_price),
      COALESCE((v_line ->> 'currency')::public.currency_code, pol.currency)
    FROM public.purchase_order_lines pol
    WHERE pol.id = (v_line ->> 'purchase_order_line_id')::uuid
      AND pol.purchase_order_id = p_purchase_order_id;
  END LOOP;

  PERFORM public._procurement_end_rpc();
  RETURN v_grn;
EXCEPTION
  WHEN OTHERS THEN
    PERFORM public._procurement_end_rpc();
    RAISE;
END;
$$;


--
-- Name: create_hr_grade(text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_hr_grade(p_code text, p_title text, p_sort_order integer DEFAULT 100) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_id UUID;
  v_code TEXT;
BEGIN
  IF NOT public.has_staff_role(ARRAY['admin']::public.staff_role[]) THEN
    RAISE EXCEPTION 'admin role required to create grades';
  END IF;
  v_code := upper(trim(p_code));
  IF v_code !~ '^[A-Z][0-9]+$' THEN
    RAISE EXCEPTION 'grade code must look like A1, B2, C3';
  END IF;

  INSERT INTO public.hr_grades (code, title, sort_order)
  VALUES (v_code, trim(p_title), COALESCE(p_sort_order, 100))
  ON CONFLICT (code) DO UPDATE
  SET title = EXCLUDED.title, sort_order = EXCLUDED.sort_order, is_active = true, updated_at = now()
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$_$;


--
-- Name: create_hr_role(text, uuid, uuid, text, text, text, public.hr_pay_frequency, jsonb, jsonb, uuid[], public.staff_role); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_hr_role(p_title text, p_grade_id uuid, p_parent_role_id uuid DEFAULT NULL::uuid, p_department text DEFAULT NULL::text, p_duties_md text DEFAULT NULL::text, p_remuneration_notes text DEFAULT NULL::text, p_pay_frequency public.hr_pay_frequency DEFAULT 'monthly'::public.hr_pay_frequency, p_module_access jsonb DEFAULT '[]'::jsonb, p_comms_preferences jsonb DEFAULT '{}'::jsonb, p_clause_template_ids uuid[] DEFAULT '{}'::uuid[], p_default_staff_role public.staff_role DEFAULT NULL::public.staff_role) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id UUID;
  v_default public.staff_role := p_default_staff_role;
BEGIN
  IF NOT public.has_staff_role(ARRAY['admin']::public.staff_role[]) THEN
    RAISE EXCEPTION 'admin role required to create organogram roles';
  END IF;
  IF p_title IS NULL OR length(trim(p_title)) = 0 THEN
    RAISE EXCEPTION 'title required';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.hr_grades g WHERE g.id = p_grade_id AND g.is_active) THEN
    RAISE EXCEPTION 'active grade required';
  END IF;
  IF p_parent_role_id IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM public.hr_roles r WHERE r.id = p_parent_role_id AND r.is_active) THEN
    RAISE EXCEPTION 'parent role not found or inactive';
  END IF;

  -- Organogram may set default_staff_role including admin only for admins (caller already admin).
  INSERT INTO public.hr_roles (
    parent_role_id, title, department, grade_id, duties_md, remuneration_notes,
    pay_frequency, module_access, comms_preferences, clause_template_ids,
    default_staff_role, created_by
  )
  VALUES (
    p_parent_role_id, trim(p_title), p_department, p_grade_id, p_duties_md, p_remuneration_notes,
    COALESCE(p_pay_frequency, 'monthly'),
    COALESCE(p_module_access, '[]'::jsonb),
    COALESCE(p_comms_preferences, '{}'::jsonb),
    COALESCE(p_clause_template_ids, '{}'),
    v_default,
    auth.uid()
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


--
-- Name: create_item_kit(uuid, public.kit_sell_mode); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_item_kit(p_stock_item_id uuid, p_sell_mode public.kit_sell_mode DEFAULT 'explode'::public.kit_sell_mode) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE v_id UUID; BEGIN PERFORM public._require_kit_staff(); IF NOT EXISTS(SELECT 1 FROM public.stock_items WHERE id=p_stock_item_id) THEN RAISE EXCEPTION 'stock item not found: %',p_stock_item_id; END IF; INSERT INTO public.item_kits(stock_item_id,sell_mode,created_by) VALUES(p_stock_item_id,COALESCE(p_sell_mode,'explode'),auth.uid()) RETURNING id INTO v_id; RETURN v_id; END; $$;


--
-- Name: create_journal_draft(date, text, public.currency_code, numeric, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_journal_draft(p_entry_date date, p_description text, p_currency public.currency_code, p_exchange_rate numeric, p_lines jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id UUID;
  v_line JSONB;
BEGIN
  IF NOT (
    auth.role() = 'service_role'
    OR public.has_staff_role(ARRAY['admin', 'finance']::public.staff_role[])
    OR public._storefront_rpc_active()
    OR public._pos_posting_active()
  ) THEN
    RAISE EXCEPTION 'finance or admin role required';
  END IF;

  IF public.is_period_locked(p_entry_date) THEN
    RAISE EXCEPTION 'accounting period is locked for date %', p_entry_date;
  END IF;

  INSERT INTO public.journal_entries (
    entry_date, description, currency, exchange_rate_applied, status, posted_by, posted_at
  )
  VALUES (
    COALESCE(p_entry_date, CURRENT_DATE),
    p_description,
    p_currency,
    CASE WHEN p_currency = 'USD' THEN COALESCE(p_exchange_rate, 1) ELSE p_exchange_rate END,
    'draft',
    auth.uid(),
    now()
  )
  RETURNING id INTO v_id;

  IF p_lines IS NULL OR jsonb_typeof(p_lines) <> 'array' OR jsonb_array_length(p_lines) = 0 THEN
    RAISE EXCEPTION 'journal lines required';
  END IF;

  FOR v_line IN SELECT * FROM jsonb_array_elements(p_lines)
  LOOP
    INSERT INTO public.journal_entry_lines (
      journal_entry_id, account_code, debit, credit, currency
    )
    VALUES (
      v_id,
      v_line ->> 'account_code',
      COALESCE((v_line ->> 'debit')::numeric, 0),
      COALESCE((v_line ->> 'credit')::numeric, 0),
      COALESCE((v_line ->> 'currency')::public.currency_code, p_currency)
    );
  END LOOP;

  PERFORM public._assert_journal_balanced(v_id);
  RETURN v_id;
END;
$$;


--
-- Name: create_kit_with_components(text, text, jsonb, text, public.kit_sell_mode); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_kit_with_components(p_oem text, p_title text, p_components jsonb, p_chassis_code text DEFAULT NULL::text, p_sell_mode public.kit_sell_mode DEFAULT 'explode'::public.kit_sell_mode) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE v_oem TEXT; v_title TEXT; v_chassis TEXT; v_uom_ea UUID; v_stock_item_id UUID; v_kit_id UUID; v_comp JSONB; v_comp_id UUID; v_comp_qty NUMERIC; v_comp_uom UUID; v_seen UUID[]:=ARRAY[]::UUID[]; v_count INT:=0; BEGIN PERFORM public._require_kit_staff(); v_oem:=upper(btrim(COALESCE(p_oem,''))); v_title:=btrim(COALESCE(p_title,'')); v_chassis:=NULLIF(upper(btrim(COALESCE(p_chassis_code,''))),''); IF v_oem='' THEN RAISE EXCEPTION 'kit OEM is required'; END IF; IF length(v_oem)>32 THEN RAISE EXCEPTION 'kit OEM must be ≤ 32 characters'; END IF; IF v_title='' THEN RAISE EXCEPTION 'kit title is required'; END IF; IF p_components IS NULL OR jsonb_typeof(p_components)<>'array' THEN RAISE EXCEPTION 'p_components must be a JSON array'; END IF; SELECT id INTO v_uom_ea FROM public.uoms WHERE code='EA' LIMIT 1; IF v_uom_ea IS NULL THEN RAISE EXCEPTION 'EA uom not found'; END IF; FOR v_comp IN SELECT * FROM jsonb_array_elements(p_components) LOOP v_comp_id:=NULLIF(btrim(COALESCE(v_comp->>'stock_item_id','')),'')::UUID; IF v_comp_id IS NULL THEN RAISE EXCEPTION 'each component requires stock_item_id'; END IF; IF v_comp_id=ANY(v_seen) THEN RAISE EXCEPTION 'duplicate component stock_item_id: %',v_comp_id; END IF; v_seen:=array_append(v_seen,v_comp_id); v_count:=v_count+1; END LOOP; IF v_count<2 THEN RAISE EXCEPTION 'kit requires at least 2 components (got %)',v_count; END IF; SELECT id INTO v_stock_item_id FROM public.stock_items WHERE oem_part_number=v_oem; IF v_stock_item_id IS NOT NULL THEN IF EXISTS(SELECT 1 FROM public.item_kits WHERE stock_item_id=v_stock_item_id) THEN RAISE EXCEPTION 'kit already exists for OEM %',v_oem; END IF; UPDATE public.stock_items SET description=v_title,base_uom_id=COALESCE(base_uom_id,v_uom_ea) WHERE id=v_stock_item_id; ELSE INSERT INTO public.stock_items(oem_part_number,description,base_uom_id) VALUES(v_oem,v_title,v_uom_ea) RETURNING id INTO v_stock_item_id; END IF; INSERT INTO public.item_kits(stock_item_id,sell_mode,created_by) VALUES(v_stock_item_id,COALESCE(p_sell_mode,'explode'),auth.uid()) RETURNING id INTO v_kit_id; FOR v_comp IN SELECT * FROM jsonb_array_elements(p_components) LOOP v_comp_id:=(v_comp->>'stock_item_id')::UUID; v_comp_qty:=COALESCE(NULLIF(v_comp->>'qty','')::NUMERIC,1); IF v_comp_qty<=0 THEN RAISE EXCEPTION 'component qty must be > 0'; END IF; IF NOT EXISTS(SELECT 1 FROM public.stock_items WHERE id=v_comp_id) THEN RAISE EXCEPTION 'component stock item not found: %',v_comp_id; END IF; IF v_comp_id=v_stock_item_id THEN RAISE EXCEPTION 'kit cannot include itself as a component'; END IF; IF EXISTS(SELECT 1 FROM public.item_kits k WHERE k.stock_item_id=v_comp_id AND k.is_active) THEN RAISE EXCEPTION 'nested kits as components are not supported'; END IF; SELECT COALESCE(base_uom_id,v_uom_ea) INTO v_comp_uom FROM public.stock_items WHERE id=v_comp_id; INSERT INTO public.item_kit_components(kit_id,component_item_id,qty,uom_id) VALUES(v_kit_id,v_comp_id,v_comp_qty,v_comp_uom); END LOOP; IF v_chassis IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.part_fitment pf WHERE pf.oem_part_number=v_oem AND COALESCE(pf.chassis_code,'')=v_chassis AND COALESCE(pf.engine_code,'')='' AND COALESCE(pf.pnc_code,'')='') THEN INSERT INTO public.part_fitment(oem_part_number,chassis_code) VALUES(v_oem,v_chassis); END IF; RETURN v_kit_id; END; $$;


--
-- Name: create_landed_cost_voucher(uuid, public.currency_code, numeric, jsonb, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_landed_cost_voucher(p_goods_receipt_id uuid, p_currency public.currency_code, p_exchange_rate numeric, p_charges jsonb, p_allocations jsonb, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_lcv UUID;
  v_rate NUMERIC;
  v_charge JSONB;
  v_alloc JSONB;
  v_batch UUID;
  v_prior NUMERIC;
  v_qty NUMERIC;
  v_total_charges NUMERIC := 0;
  v_total_alloc NUMERIC := 0;
BEGIN
  PERFORM public._procurement_begin_rpc();
  PERFORM public._require_procurement_finance();

  IF p_charges IS NULL OR jsonb_array_length(p_charges) = 0 THEN
    RAISE EXCEPTION 'landed cost charges required';
  END IF;
  IF p_allocations IS NULL OR jsonb_array_length(p_allocations) = 0 THEN
    RAISE EXCEPTION 'landed cost allocations required';
  END IF;

  v_rate := CASE
    WHEN p_currency = 'USD' THEN COALESCE(p_exchange_rate, 1)
    ELSE p_exchange_rate
  END;

  INSERT INTO public.landed_cost_vouchers (
    document_number, goods_receipt_id, currency, exchange_rate_applied, notes, created_by
  )
  VALUES (
    public.next_series_value('LCV-'),
    p_goods_receipt_id,
    p_currency,
    v_rate,
    p_notes,
    auth.uid()
  )
  RETURNING id INTO v_lcv;

  FOR v_charge IN SELECT * FROM jsonb_array_elements(p_charges)
  LOOP
    INSERT INTO public.landed_cost_charges (
      landed_cost_voucher_id, charge_type, amount, currency
    )
    VALUES (
      v_lcv,
      v_charge ->> 'charge_type',
      (v_charge ->> 'amount')::numeric,
      COALESCE((v_charge ->> 'currency')::public.currency_code, p_currency)
    );
    v_total_charges := v_total_charges + (v_charge ->> 'amount')::numeric;
  END LOOP;

  FOR v_alloc IN SELECT * FROM jsonb_array_elements(p_allocations)
  LOOP
    v_batch := (v_alloc ->> 'stock_batch_id')::uuid;
    SELECT unit_cost, qty_on_hand INTO v_prior, v_qty
    FROM public.stock_batches WHERE id = v_batch;
    IF NOT FOUND OR v_qty <= 0 THEN
      RAISE EXCEPTION 'invalid batch for allocation: %', v_batch;
    END IF;

    INSERT INTO public.landed_cost_allocations (
      landed_cost_voucher_id, stock_batch_id, allocated_amount,
      prior_unit_cost, qty_on_hand_snapshot
    )
    VALUES (
      v_lcv,
      v_batch,
      (v_alloc ->> 'allocated_amount')::numeric,
      v_prior,
      v_qty
    );
    v_total_alloc := v_total_alloc + (v_alloc ->> 'allocated_amount')::numeric;
  END LOOP;

  IF round(v_total_charges, 4) <> round(v_total_alloc, 4) THEN
    RAISE EXCEPTION 'charge total % must equal allocation total %', v_total_charges, v_total_alloc;
  END IF;

  PERFORM public._procurement_end_rpc();
  RETURN v_lcv;
EXCEPTION
  WHEN OTHERS THEN
    PERFORM public._procurement_end_rpc();
    RAISE;
END;
$$;


--
-- Name: create_material_request(uuid, date, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_material_request(p_warehouse_id uuid, p_needed_by date, p_lines jsonb, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_mr UUID;
  v_line JSONB;
  v_no INT := 0;
BEGIN
  PERFORM public._procurement_begin_rpc();
  PERFORM public._require_procurement_staff();

  IF p_lines IS NULL OR jsonb_array_length(p_lines) = 0 THEN
    RAISE EXCEPTION 'material request lines required';
  END IF;

  INSERT INTO public.material_requests (
    document_number, warehouse_id, needed_by, notes, created_by
  )
  VALUES (
    public.next_series_value('MR-'), p_warehouse_id, p_needed_by, p_notes, auth.uid()
  )
  RETURNING id INTO v_mr;

  FOR v_line IN SELECT * FROM jsonb_array_elements(p_lines)
  LOOP
    v_no := v_no + 1;
    INSERT INTO public.material_request_lines (
      material_request_id, line_no, stock_item_id, uom_id, qty
    )
    VALUES (
      v_mr,
      v_no,
      (v_line ->> 'stock_item_id')::uuid,
      (v_line ->> 'uom_id')::uuid,
      (v_line ->> 'qty')::numeric
    );
  END LOOP;

  PERFORM public._procurement_end_rpc();
  RETURN v_mr;
EXCEPTION
  WHEN OTHERS THEN
    PERFORM public._procurement_end_rpc();
    RAISE;
END;
$$;


--
-- Name: create_mr_from_forecast(uuid[], date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_mr_from_forecast(p_suggestion_ids uuid[], p_needed_by date DEFAULT NULL::date, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_wh uuid;
  v_lines jsonb := '[]'::jsonb;
  v_sug record;
  v_uom uuid;
  v_mr uuid;
  v_ids uuid[];
BEGIN
  PERFORM public._require_procurement_staff();
  PERFORM public._procurement_begin_rpc();

  IF p_suggestion_ids IS NULL OR cardinality(p_suggestion_ids)=0 THEN
    RAISE EXCEPTION 'suggestion ids required';
  END IF;
  v_ids:=p_suggestion_ids;

  SELECT DISTINCT warehouse_id INTO v_wh
  FROM public.forecast_suggestions
  WHERE id=ANY(v_ids) AND status='open';
  IF v_wh IS NULL THEN RAISE EXCEPTION 'no open forecast suggestions for given ids'; END IF;

  IF (
    SELECT count(DISTINCT warehouse_id)
    FROM public.forecast_suggestions
    WHERE id=ANY(v_ids) AND status='open'
  ) > 1 THEN
    RAISE EXCEPTION 'all suggestions must share one warehouse';
  END IF;

  FOR v_sug IN
    SELECT * FROM public.forecast_suggestions
    WHERE id=ANY(v_ids) AND status='open'
    ORDER BY id
  LOOP
    SELECT base_uom_id INTO v_uom FROM public.stock_items WHERE id=v_sug.stock_item_id;
    IF v_uom IS NULL THEN RAISE EXCEPTION 'stock item missing base_uom_id: %',v_sug.stock_item_id; END IF;
    v_lines:=v_lines||jsonb_build_array(jsonb_build_object(
      'stock_item_id',v_sug.stock_item_id,
      'uom_id',v_uom,
      'qty',v_sug.suggested_qty
    ));
  END LOOP;

  v_mr:=public.create_material_request(v_wh,p_needed_by,v_lines,COALESCE(p_notes,'From demand forecast suggestions'));

  UPDATE public.forecast_suggestions
  SET status='converted',material_request_id=v_mr,converted_at=now()
  WHERE id=ANY(v_ids) AND status='open';

  RETURN v_mr;
END;
$$;


--
-- Name: create_payment_entry(uuid, public.payment_tender, numeric, public.currency_code, numeric, text, public.currency_code, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_payment_entry(p_customer_id uuid, p_tender public.payment_tender, p_amount numeric, p_currency public.currency_code DEFAULT 'USD'::public.currency_code, p_exchange_rate numeric DEFAULT 1, p_notes text DEFAULT NULL::text, p_settlement_currency public.currency_code DEFAULT NULL::public.currency_code, p_settlement_amount numeric DEFAULT NULL::numeric, p_settlement_exchange_rate numeric DEFAULT NULL::numeric) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id UUID;
BEGIN
  PERFORM public._require_payments_staff();
  PERFORM public._payments_rpc_enter();

  IF p_customer_id IS NULL THEN
    RAISE EXCEPTION 'customer_id required';
  END IF;
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION 'payment amount must be > 0';
  END IF;
  IF p_currency = 'ZIG' AND (p_exchange_rate IS NULL OR p_exchange_rate <= 0) THEN
    RAISE EXCEPTION 'exchange_rate_applied required for ZIG';
  END IF;

  INSERT INTO public.payment_entries (
    document_number, customer_id, tender, currency, exchange_rate_applied, amount,
    notes, settlement_currency, settlement_amount, settlement_exchange_rate, created_by
  )
  VALUES (
    public.next_series_value('PE-'),
    p_customer_id,
    p_tender,
    p_currency,
    CASE WHEN p_currency = 'USD' THEN COALESCE(p_exchange_rate, 1) ELSE p_exchange_rate END,
    p_amount,
    p_notes,
    p_settlement_currency,
    p_settlement_amount,
    p_settlement_exchange_rate,
    auth.uid()
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


--
-- Name: create_payment_resolution_letter(public.payment_resolution_source_kind, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_payment_resolution_letter(p_source_kind public.payment_resolution_source_kind, p_source_id uuid, p_issue_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE e public.employees%ROWTYPE; v_title TEXT; v_provider TEXT; v_status TEXT; v_amount NUMERIC; v_currency public.currency_code;
 v_ext TEXT; v_pref TEXT; v_txn TEXT; v_rrn TEXT; v_auth TEXT; v_last4 TEXT; v_scheme TEXT; v_failure TEXT; v_order UUID; v_invoice UUID; v_customer UUID;
 v_customer_name TEXT; v_invoice_no TEXT; v_id UUID; a public.pos_card_terminal_attempts%ROWTYPE; l public.pos_split_payment_legs%ROWTYPE; r public.pos_split_refund_requests%ROWTYPE;
BEGIN
 IF NOT (public.is_pos_approver() OR public.has_staff_role(ARRAY['admin','finance']::public.staff_role[])) THEN RAISE EXCEPTION 'manager/finance/admin role required'; END IF;
 SELECT * INTO e FROM public.employees WHERE user_id=auth.uid() AND status='active';
 IF NOT FOUND OR e.signature_storage_path IS NULL OR e.signature_sha256 IS NULL THEN RAISE EXCEPTION 'manager profile signature required before issuing a payment-resolution letter'; END IF;
 SELECT hr.title INTO v_title FROM public.hr_roles hr WHERE hr.id=e.hr_role_id;
 IF p_source_kind='card_terminal' THEN
  SELECT * INTO a FROM public.pos_card_terminal_attempts WHERE id=p_source_id; IF NOT FOUND THEN RAISE EXCEPTION 'card terminal attempt not found'; END IF;
  v_provider:='card_terminal';v_status:=a.status::text;v_amount:=a.amount;v_currency:=a.currency;v_ext:=a.external_ref;v_pref:=a.terminal_transaction_id;
  v_txn:=a.terminal_transaction_id;v_rrn:=a.rrn;v_auth:=a.authorization_code;v_last4:=a.card_last4;v_scheme:=a.card_scheme;v_failure:=COALESCE(a.finalization_error,a.response_message);
  v_order:=a.commerce_order_id;v_invoice:=a.source_invoice_id; IF v_invoice IS NULL THEN v_invoice:=a.invoice_id; END IF;
 ELSIF p_source_kind='split_leg' THEN
  SELECT * INTO l FROM public.pos_split_payment_legs WHERE id=p_source_id; IF NOT FOUND THEN RAISE EXCEPTION 'split payment leg not found'; END IF;
  v_provider:=l.tender::text;v_status:=l.status::text;v_amount:=l.requested_amount;v_ext:=l.external_reference;v_pref:=l.provider_ref;v_failure:=l.status_detail;
  SELECT s.currency,s.commerce_order_id INTO v_currency,v_order FROM public.pos_split_payment_sessions s WHERE s.id=l.session_id;
  IF l.card_terminal_attempt_id IS NOT NULL THEN SELECT terminal_transaction_id,rrn,authorization_code,card_last4,card_scheme INTO v_txn,v_rrn,v_auth,v_last4,v_scheme FROM public.pos_card_terminal_attempts WHERE id=l.card_terminal_attempt_id; END IF;
 ELSIF p_source_kind='split_refund' THEN
  SELECT * INTO r FROM public.pos_split_refund_requests WHERE id=p_source_id; IF NOT FOUND THEN RAISE EXCEPTION 'split refund not found'; END IF;
  SELECT * INTO l FROM public.pos_split_payment_legs WHERE id=r.leg_id; SELECT s.currency,s.commerce_order_id INTO v_currency,v_order FROM public.pos_split_payment_sessions s WHERE s.id=r.session_id;
  v_provider:=l.tender::text;v_status:='refund_'||r.status::text;v_amount:=r.gross_amount;v_ext:=r.external_reference;v_pref:=r.provider_ref;v_failure:=r.failure_reason;
 ELSE
  IF p_source_kind='ecocash' THEN SELECT 'ecocash',status::text,amount,currency,external_ref,provider_ref,failure_reason,commerce_order_id,sales_invoice_id,customer_id INTO v_provider,v_status,v_amount,v_currency,v_ext,v_pref,v_failure,v_order,v_invoice,v_customer FROM public.ecocash_payment_intents WHERE id=p_source_id;
  ELSIF p_source_kind='paynow' THEN SELECT 'paynow',status::text,amount,currency,external_ref,provider_ref,failure_reason,commerce_order_id,NULL::uuid,customer_id INTO v_provider,v_status,v_amount,v_currency,v_ext,v_pref,v_failure,v_order,v_invoice,v_customer FROM public.paynow_payment_intents WHERE id=p_source_id;
  ELSIF p_source_kind='contipay' THEN SELECT 'contipay',status::text,amount,currency,external_ref,provider_ref,failure_reason,commerce_order_id,NULL::uuid,customer_id INTO v_provider,v_status,v_amount,v_currency,v_ext,v_pref,v_failure,v_order,v_invoice,v_customer FROM public.contipay_payment_intents WHERE id=p_source_id; END IF;
  IF v_provider IS NULL THEN RAISE EXCEPTION 'payment intent not found'; END IF;
 END IF;
 IF v_order IS NOT NULL THEN SELECT sales_invoice_id,customer_id INTO v_invoice,v_customer FROM public.commerce_orders WHERE id=v_order; END IF;
 IF v_invoice IS NOT NULL THEN SELECT document_number,customer_id INTO v_invoice_no,v_customer FROM public.sales_invoices WHERE id=v_invoice; END IF;
 IF v_customer IS NOT NULL THEN SELECT display_name INTO v_customer_name FROM public.customers WHERE id=v_customer; END IF;
 INSERT INTO public.payment_resolution_letters(document_number,source_kind,source_id,provider,observed_status,amount,currency,external_reference,provider_reference,
  terminal_transaction_id,rrn,authorization_code,card_last4,card_scheme,failure_detail,commerce_order_id,sales_invoice_id,customer_id,customer_name,invoice_document_number,
  manager_user_id,manager_employee_id,manager_name,manager_title,manager_employee_code,signature_storage_bucket,signature_storage_path,signature_mime_type,signature_sha256,issue_notes)
 VALUES(public.next_series_value('PDL-'),p_source_kind,p_source_id,v_provider,v_status,COALESCE(v_amount,0),COALESCE(v_currency,'USD'),v_ext,v_pref,v_txn,v_rrn,v_auth,v_last4,v_scheme,
  v_failure,v_order,v_invoice,v_customer,v_customer_name,v_invoice_no,auth.uid(),e.id,e.full_name,v_title,e.employee_code,e.signature_storage_bucket,e.signature_storage_path,e.signature_mime_type,e.signature_sha256,p_issue_notes)
 ON CONFLICT(source_kind,source_id,manager_user_id) DO UPDATE SET observed_status=EXCLUDED.observed_status,failure_detail=EXCLUDED.failure_detail,provider_reference=EXCLUDED.provider_reference,
  issue_notes=EXCLUDED.issue_notes,issued_at=now() RETURNING id INTO v_id;
 RETURN v_id;
END $$;


--
-- Name: create_paynow_intent(text, public.paynow_method, numeric, public.currency_code, numeric, uuid, public.currency_code, numeric, numeric, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_paynow_intent(p_external_ref text, p_method public.paynow_method, p_amount numeric, p_currency public.currency_code DEFAULT 'USD'::public.currency_code, p_exchange_rate numeric DEFAULT 1, p_customer_id uuid DEFAULT NULL::uuid, p_settlement_currency public.currency_code DEFAULT NULL::public.currency_code, p_settlement_amount numeric DEFAULT NULL::numeric, p_settlement_exchange_rate numeric DEFAULT NULL::numeric, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id UUID;
BEGIN
  PERFORM public._require_payments_staff();
  PERFORM public._payments_rpc_enter();

  IF p_external_ref IS NULL OR length(trim(p_external_ref)) = 0 THEN
    RAISE EXCEPTION 'external_ref required';
  END IF;
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION 'amount must be > 0';
  END IF;

  INSERT INTO public.paynow_payment_intents (
    external_ref, method, customer_id, amount, currency, exchange_rate_applied,
    settlement_currency, settlement_amount, settlement_exchange_rate,
    metadata, created_by
  )
  VALUES (
    trim(p_external_ref),
    p_method,
    p_customer_id,
    p_amount,
    p_currency,
    CASE WHEN p_currency = 'USD' THEN COALESCE(p_exchange_rate, 1) ELSE p_exchange_rate END,
    p_settlement_currency,
    p_settlement_amount,
    p_settlement_exchange_rate,
    COALESCE(p_metadata, '{}'::jsonb),
    auth.uid()
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


--
-- Name: create_payroll_run(date, date, public.currency_code, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_payroll_run(p_period_start date, p_period_end date, p_currency public.currency_code, p_exchange_rate numeric DEFAULT 1, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id UUID;
BEGIN
  PERFORM public._payroll_begin_rpc();
  PERFORM public._require_hr_staff();

  IF p_period_start IS NULL OR p_period_end IS NULL THEN
    RAISE EXCEPTION 'period_start and period_end required';
  END IF;
  IF p_period_end < p_period_start THEN
    RAISE EXCEPTION 'period_end must be >= period_start';
  END IF;
  IF p_exchange_rate IS NULL OR p_exchange_rate <= 0 THEN
    RAISE EXCEPTION 'exchange_rate must be > 0';
  END IF;

  INSERT INTO public.payroll_runs (
    document_number, period_start, period_end, currency, exchange_rate, notes, created_by
  )
  VALUES (
    public.next_series_value('PR-'),
    p_period_start,
    p_period_end,
    p_currency,
    p_exchange_rate,
    p_notes,
    auth.uid()
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


--
-- Name: create_petty_cash_expense_request(numeric, public.currency_code, text, date, character varying, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_petty_cash_expense_request(p_amount numeric, p_currency public.currency_code, p_description text, p_entry_date date DEFAULT CURRENT_DATE, p_expense_account_code character varying DEFAULT '5300'::character varying, p_exchange_rate numeric DEFAULT NULL::numeric) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE v_id UUID; BEGIN v_id:=public.create_finance_requisition('petty_cash'::public.finance_requisition_type,p_amount,p_currency,NULL,p_description,COALESCE(nullif(trim(p_expense_account_code),''),'5300'),'1110',p_exchange_rate); PERFORM public._finance_req_rpc_enter(); UPDATE public.finance_requisitions SET intended_entry_date=COALESCE(p_entry_date,CURRENT_DATE),updated_at=now() WHERE id=v_id; RETURN v_id; END; $$;


--
-- Name: create_petty_cash_float_request(numeric, public.currency_code, text, date, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_petty_cash_float_request(p_amount numeric, p_currency public.currency_code, p_description text, p_entry_date date DEFAULT CURRENT_DATE, p_exchange_rate numeric DEFAULT NULL::numeric) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE v_id UUID; v_fund VARCHAR(10):=public.petty_cash_funding_account_code(); BEGIN v_id:=public.create_finance_requisition('petty_float'::public.finance_requisition_type,p_amount,p_currency,NULL,p_description,v_fund,'1110',p_exchange_rate); PERFORM public._finance_req_rpc_enter(); UPDATE public.finance_requisitions SET intended_entry_date=COALESCE(p_entry_date,CURRENT_DATE),updated_at=now() WHERE id=v_id; RETURN v_id; END; $$;


--
-- Name: create_pick_list(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_pick_list(p_sales_invoice_id uuid, p_lines jsonb DEFAULT NULL::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_inv public.sales_invoices%ROWTYPE;
  v_pick UUID;
  v_line RECORD;
  v_elem JSONB;
  v_inv_line UUID;
  v_qty NUMERIC;
  v_qty_base NUMERIC;
  v_open NUMERIC;
  v_any BOOLEAN := false;
  v_bin UUID;
BEGIN
  PERFORM public._logistics_begin_rpc();
  PERFORM public._require_logistics_staff();

  SELECT * INTO v_inv
  FROM public.sales_invoices
  WHERE id = p_sales_invoice_id AND doc_type = 'invoice' AND status = 'posted'
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'posted sales invoice required';
  END IF;
  IF v_inv.fulfillment_mode <> 'dispatch' THEN
    RAISE EXCEPTION 'pick lists only for dispatch fulfillment invoices';
  END IF;

  INSERT INTO public.pick_lists (
    document_number, sales_invoice_id, warehouse_id, status, created_by
  )
  VALUES (
    public.next_series_value('PL-'),
    p_sales_invoice_id,
    v_inv.warehouse_id,
    'draft',
    auth.uid()
  )
  RETURNING id INTO v_pick;

  IF p_lines IS NULL OR jsonb_typeof(p_lines) <> 'array' OR jsonb_array_length(p_lines) = 0 THEN
    FOR v_line IN
      SELECT *
      FROM public.sales_invoice_lines
      WHERE invoice_id = p_sales_invoice_id
        AND NOT is_core_charge
        AND COALESCE(issues_stock, true)
        AND qty_base > qty_fulfilled
    LOOP
      v_open := public._invoice_line_open_qty_base(v_line.id);
      IF v_open <= 0 THEN
        CONTINUE;
      END IF;
      v_any := true;

      SELECT sl.bin_id INTO v_bin
      FROM public.stock_levels sl
      WHERE sl.stock_item_id = v_line.stock_item_id
        AND sl.warehouse_id = v_inv.warehouse_id;

      INSERT INTO public.pick_list_lines (
        pick_list_id, sales_invoice_line_id, stock_item_id, uom_id,
        qty_requested, qty_base_requested, suggested_bin_id
      )
      VALUES (
        v_pick, v_line.id, v_line.stock_item_id, v_line.uom_id,
        v_open, v_open, v_bin
      );
    END LOOP;
  ELSE
    FOR v_elem IN SELECT * FROM jsonb_array_elements(p_lines)
    LOOP
      v_inv_line := (v_elem ->> 'sales_invoice_line_id')::uuid;
      v_qty := (v_elem ->> 'qty')::numeric;
      IF v_inv_line IS NULL OR v_qty IS NULL OR v_qty <= 0 THEN
        RAISE EXCEPTION 'pick line requires sales_invoice_line_id and qty > 0';
      END IF;

      SELECT * INTO v_line
      FROM public.sales_invoice_lines
      WHERE id = v_inv_line AND invoice_id = p_sales_invoice_id;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'invoice line % not on invoice', v_inv_line;
      END IF;
      IF v_line.is_core_charge THEN
        RAISE EXCEPTION 'core-charge lines cannot be picked';
      END IF;
      IF NOT COALESCE(v_line.issues_stock, true) THEN
        RAISE EXCEPTION 'non-stock kit header lines cannot be picked';
      END IF;

      v_qty_base := public.convert_to_base_uom(v_line.stock_item_id, v_line.uom_id, v_qty);
      v_open := public._invoice_line_open_qty_base(v_inv_line);
      IF v_qty_base > v_open THEN
        RAISE EXCEPTION 'cannot pick more than open qty (open=%, requested=%)', v_open, v_qty_base;
      END IF;

      v_any := true;

      SELECT sl.bin_id INTO v_bin
      FROM public.stock_levels sl
      WHERE sl.stock_item_id = v_line.stock_item_id
        AND sl.warehouse_id = v_inv.warehouse_id;

      INSERT INTO public.pick_list_lines (
        pick_list_id, sales_invoice_line_id, stock_item_id, uom_id,
        qty_requested, qty_base_requested, suggested_bin_id
      )
      VALUES (
        v_pick, v_inv_line, v_line.stock_item_id, v_line.uom_id,
        v_qty, v_qty_base, v_bin
      );
    END LOOP;
  END IF;

  IF NOT v_any THEN
    RAISE EXCEPTION 'no open qty to pick on invoice %', p_sales_invoice_id;
  END IF;

  RETURN v_pick;
END;
$$;


--
-- Name: create_pos_cart(uuid, uuid, public.currency_code); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_pos_cart(p_warehouse_id uuid, p_customer_id uuid DEFAULT NULL::uuid, p_currency public.currency_code DEFAULT 'USD'::public.currency_code) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  RETURN public.create_pos_cart(
    p_warehouse_id,
    p_customer_id,
    p_currency,
    'immediate'::public.fulfillment_mode
  );
END;
$$;


--
-- Name: create_pos_cart(uuid, uuid, public.currency_code, public.fulfillment_mode); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_pos_cart(p_warehouse_id uuid, p_customer_id uuid DEFAULT NULL::uuid, p_currency public.currency_code DEFAULT 'USD'::public.currency_code, p_fulfillment_mode public.fulfillment_mode DEFAULT 'immediate'::public.fulfillment_mode) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_id uuid;
  v_rate numeric;
BEGIN
  PERFORM public._require_sales_staff();

  IF p_warehouse_id IS NULL THEN
    RAISE EXCEPTION 'warehouse_id required';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.warehouses w
    WHERE w.id = p_warehouse_id
      AND w.is_active = true
      AND COALESCE(w.is_quarantine, false) = false
  ) THEN
    RAISE EXCEPTION 'saleable warehouse not found or inactive';
  END IF;

  IF p_customer_id IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM public.customers c WHERE c.id = p_customer_id) THEN
    RAISE EXCEPTION 'customer not found';
  END IF;

  IF p_currency = 'USD'::public.currency_code THEN
    v_rate := 1;
  ELSIF p_currency = 'ZIG'::public.currency_code THEN
    v_rate := public.get_zig_exchange_rate(CURRENT_DATE);
    IF v_rate IS NULL OR v_rate <= 0 THEN
      RAISE EXCEPTION 'ZiG sales unavailable: no authoritative exchange rate configured';
    END IF;
  ELSE
    RAISE EXCEPTION 'unsupported cart currency: %', p_currency;
  END IF;

  INSERT INTO public.pos_carts(
    document_number, customer_id, warehouse_id, currency,
    exchange_rate_applied, fulfillment_mode, created_by
  )
  VALUES(
    public.next_series_value('CART-'), p_customer_id, p_warehouse_id, p_currency,
    v_rate, COALESCE(p_fulfillment_mode, 'immediate'::public.fulfillment_mode), auth.uid()
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


--
-- Name: create_pos_contipay_intent(uuid, public.contipay_method, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_pos_contipay_intent(p_order_id uuid, p_method public.contipay_method, p_external_ref text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE o public.commerce_orders%ROWTYPE; v_id UUID;
BEGIN
 PERFORM public._require_payments_staff(); SELECT * INTO o FROM public.commerce_orders WHERE id=p_order_id FOR UPDATE;
 IF NOT FOUND OR o.settled_payment_entry_id IS NOT NULL THEN RAISE EXCEPTION 'unsettled commerce order required'; END IF;
 IF o.reservation_expires_at IS NULL OR o.reservation_expires_at<=now() THEN RAISE EXCEPTION 'commerce reservation expired'; END IF;
 IF o.state='payment_processing' AND o.active_payment_provider IS DISTINCT FROM 'contipay' THEN RAISE EXCEPTION 'another payment provider is already processing'; END IF;
 SELECT id INTO v_id FROM public.contipay_payment_intents WHERE commerce_order_id=p_order_id AND status IN('pending','authorized') ORDER BY created_at DESC LIMIT 1;
 IF v_id IS NOT NULL THEN RETURN v_id; END IF;
 INSERT INTO public.contipay_payment_intents(external_ref,method,customer_id,amount,currency,exchange_rate_applied,commerce_order_id,metadata,created_by)
 VALUES(trim(p_external_ref),p_method,o.customer_id,o.total,o.currency,o.exchange_rate_applied,o.id,COALESCE(p_metadata,'{}'::jsonb)||jsonb_build_object('pos_commerce_order_id',o.id),auth.uid()) RETURNING id INTO v_id;
 UPDATE public.commerce_orders SET state='payment_processing',active_payment_provider='contipay',active_payment_intent_id=v_id,payment_exception=NULL,updated_at=now() WHERE id=o.id;
 RETURN v_id;
END $$;


--
-- Name: create_pos_customer(text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_pos_customer(p_customer_kind text, p_display_name text, p_business_name text DEFAULT NULL::text, p_email text DEFAULT NULL::text, p_phone_e164 text DEFAULT NULL::text, p_whatsapp_e164 text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id UUID;
  v_kind TEXT := lower(trim(COALESCE(p_customer_kind, 'individual')));
  v_name TEXT := NULLIF(trim(COALESCE(p_display_name, '')), '');
  v_business TEXT := NULLIF(trim(COALESCE(p_business_name, '')), '');
BEGIN
  PERFORM public._require_sales_staff();
  IF v_kind NOT IN ('individual', 'business') THEN RAISE EXCEPTION 'invalid customer kind'; END IF;
  IF v_name IS NULL THEN RAISE EXCEPTION 'customer display name required'; END IF;
  IF v_kind = 'business' AND v_business IS NULL THEN RAISE EXCEPTION 'business name required'; END IF;

  INSERT INTO public.customers (
    customer_kind, display_name, business_name, email, phone_e164, whatsapp_e164
  ) VALUES (
    v_kind, v_name, v_business,
    NULLIF(trim(COALESCE(p_email, '')), ''),
    NULLIF(trim(COALESCE(p_phone_e164, '')), ''),
    NULLIF(trim(COALESCE(p_whatsapp_e164, '')), '')
  ) RETURNING id INTO v_id;
  RETURN v_id;
END;
$$;


--
-- Name: create_pos_ecocash_intent(uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_pos_ecocash_intent(p_order_id uuid, p_payer_msisdn text, p_external_ref text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE o public.commerce_orders%ROWTYPE; v_id UUID; v_msisdn TEXT;
BEGIN
 PERFORM public._require_payments_staff(); SELECT * INTO o FROM public.commerce_orders WHERE id=p_order_id FOR UPDATE;
 IF NOT FOUND OR o.settled_payment_entry_id IS NOT NULL THEN RAISE EXCEPTION 'unsettled commerce order required'; END IF;
 IF o.reservation_expires_at IS NULL OR o.reservation_expires_at<=now() THEN RAISE EXCEPTION 'commerce reservation expired'; END IF;
 IF o.state='payment_processing' AND o.active_payment_provider IS DISTINCT FROM 'ecocash' THEN RAISE EXCEPTION 'another payment provider is already processing'; END IF;
 SELECT id INTO v_id FROM public.ecocash_payment_intents WHERE commerce_order_id=p_order_id AND status IN('pending','authorized') ORDER BY created_at DESC LIMIT 1;
 IF v_id IS NOT NULL THEN RETURN v_id; END IF;
 v_msisdn:=regexp_replace(trim(COALESCE(p_payer_msisdn,'')),'[^0-9]','','g'); IF v_msisdn~'^0[0-9]{9}$' THEN v_msisdn:='263'||substr(v_msisdn,2); END IF;
 IF v_msisdn!~'^263[0-9]{9}$' THEN RAISE EXCEPTION 'payer_msisdn must normalize to 263XXXXXXXXX'; END IF;
 INSERT INTO public.ecocash_payment_intents(external_ref,payer_msisdn,payer_mode,channel,customer_id,amount,currency,exchange_rate_applied,commerce_order_id,metadata,created_by)
 VALUES(trim(p_external_ref),v_msisdn,'pos_entered','pos',o.customer_id,o.total,o.currency,o.exchange_rate_applied,o.id,COALESCE(p_metadata,'{}'::jsonb)||jsonb_build_object('pos_commerce_order_id',o.id),auth.uid()) RETURNING id INTO v_id;
 UPDATE public.commerce_orders SET state='payment_processing',active_payment_provider='ecocash',active_payment_intent_id=v_id,payment_exception=NULL,updated_at=now() WHERE id=o.id;
 RETURN v_id;
END $_$;


--
-- Name: create_pos_fulfillment_request(public.pos_fulfillment_kind, uuid, uuid, numeric, uuid, uuid, uuid, uuid, uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_pos_fulfillment_request(p_kind public.pos_fulfillment_kind, p_stock_item_id uuid, p_uom_id uuid, p_qty numeric, p_source_warehouse_id uuid DEFAULT NULL::uuid, p_destination_warehouse_id uuid DEFAULT NULL::uuid, p_customer_id uuid DEFAULT NULL::uuid, p_cart_id uuid DEFAULT NULL::uuid, p_invoice_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text, p_hold_minutes integer DEFAULT 120) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_id UUID; v_qty_base NUMERIC; v_exp TIMESTAMPTZ; v_avail NUMERIC;
BEGIN
 PERFORM public._require_sales_staff();
 IF COALESCE(p_qty,0)<=0 THEN RAISE EXCEPTION 'qty must be > 0'; END IF;
 IF p_kind='branch_transfer' AND (p_source_warehouse_id IS NULL OR p_destination_warehouse_id IS NULL OR p_source_warehouse_id=p_destination_warehouse_id) THEN
  RAISE EXCEPTION 'branch transfer requires distinct source and destination warehouses';
 END IF;
 IF p_kind IN('alternate_pickup','customer_collection') AND p_source_warehouse_id IS NULL THEN RAISE EXCEPTION 'source warehouse required for stock hold'; END IF;
 v_qty_base:=public.convert_to_base_uom(p_stock_item_id,p_uom_id,p_qty);
 IF p_kind<>'backorder' THEN
  v_avail:=public.get_inventory_available_quantity(p_stock_item_id,p_source_warehouse_id);
  IF v_avail<v_qty_base THEN RAISE EXCEPTION 'insufficient available stock at source warehouse (available %, requested %)',v_avail,v_qty_base; END IF;
  v_exp:=now()+make_interval(mins=>LEAST(GREATEST(COALESCE(p_hold_minutes,120),15),1440));
 END IF;
 INSERT INTO public.pos_fulfillment_requests(document_number,kind,status,stock_item_id,uom_id,qty,source_warehouse_id,destination_warehouse_id,
  customer_id,cart_id,invoice_id,notes,requested_by,expires_at)
 VALUES(public.next_series_value('PFR-'),p_kind,CASE WHEN p_kind='backorder' THEN 'requested'::public.pos_fulfillment_status ELSE 'reserved'::public.pos_fulfillment_status END,
  p_stock_item_id,p_uom_id,p_qty,p_source_warehouse_id,p_destination_warehouse_id,p_customer_id,p_cart_id,p_invoice_id,p_notes,auth.uid(),v_exp)
 RETURNING id INTO v_id;
 IF p_kind<>'backorder' THEN
  INSERT INTO public.inventory_reservations(commerce_order_id,pos_fulfillment_request_id,stock_item_id,warehouse_id,required_qty,reserved_qty,expires_at,state,reservation_reason)
  VALUES(NULL,v_id,p_stock_item_id,p_source_warehouse_id,v_qty_base,v_qty_base,v_exp,'active','pos_'||p_kind::text);
 END IF;
 PERFORM public.emit_domain_event('transfer_pending_approval','pos-fulfillment:'||v_id::text,
  jsonb_build_object('request_id',v_id,'kind',p_kind,'stock_item_id',p_stock_item_id,'qty',p_qty,'source_warehouse_id',p_source_warehouse_id,'destination_warehouse_id',p_destination_warehouse_id));
 RETURN v_id;
END $$;


--
-- Name: create_pos_paynow_intent(uuid, public.paynow_method, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_pos_paynow_intent(p_order_id uuid, p_method public.paynow_method, p_external_ref text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE o public.commerce_orders%ROWTYPE; v_id UUID;
BEGIN
 PERFORM public._require_payments_staff(); SELECT * INTO o FROM public.commerce_orders WHERE id=p_order_id FOR UPDATE;
 IF NOT FOUND OR o.settled_payment_entry_id IS NOT NULL THEN RAISE EXCEPTION 'unsettled commerce order required'; END IF;
 IF o.reservation_expires_at IS NULL OR o.reservation_expires_at<=now() THEN RAISE EXCEPTION 'commerce reservation expired'; END IF;
 IF o.state='payment_processing' AND o.active_payment_provider IS DISTINCT FROM 'paynow' THEN RAISE EXCEPTION 'another payment provider is already processing'; END IF;
 SELECT id INTO v_id FROM public.paynow_payment_intents WHERE commerce_order_id=p_order_id AND status IN('pending','authorized') ORDER BY created_at DESC LIMIT 1;
 IF v_id IS NOT NULL THEN RETURN v_id; END IF;
 INSERT INTO public.paynow_payment_intents(external_ref,method,customer_id,amount,currency,exchange_rate_applied,commerce_order_id,metadata,created_by)
 VALUES(trim(p_external_ref),p_method,o.customer_id,o.total,o.currency,o.exchange_rate_applied,o.id,COALESCE(p_metadata,'{}'::jsonb)||jsonb_build_object('pos_commerce_order_id',o.id),auth.uid()) RETURNING id INTO v_id;
 UPDATE public.commerce_orders SET state='payment_processing',active_payment_provider='paynow',active_payment_intent_id=v_id,payment_exception=NULL,updated_at=now() WHERE id=o.id;
 RETURN v_id;
END $$;


--
-- Name: create_pos_quotation_from_cart(uuid, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_pos_quotation_from_cart(p_cart_id uuid, p_valid_until date DEFAULT NULL::date, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cart public.pos_carts%ROWTYPE;
  v_quote_id UUID;
  v_doc TEXT;
  v_line_map JSONB := '{}'::jsonb;
  v_src public.pos_cart_lines%ROWTYPE;
  v_new_id UUID;
  v_parent UUID;
BEGIN
  PERFORM public._require_cart_mutate(p_cart_id);
  SELECT * INTO v_cart FROM public.pos_carts WHERE id = p_cart_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'cart not found: %', p_cart_id;
  END IF;
  IF v_cart.status <> 'open' THEN
    RAISE EXCEPTION 'only open carts can become quotations (got %)', v_cart.status;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.pos_cart_lines WHERE cart_id = p_cart_id AND is_core_charge = false
  ) THEN
    RAISE EXCEPTION 'quotation requires at least one non-core line';
  END IF;

  v_doc := public.next_series_value('QT-');

  INSERT INTO public.pos_quotations (
    document_number, customer_id, warehouse_id, currency, exchange_rate_applied,
    status, valid_until, notes, source_cart_id, created_by
  ) VALUES (
    v_doc, v_cart.customer_id, v_cart.warehouse_id, v_cart.currency, v_cart.exchange_rate_applied,
    'issued', p_valid_until, p_notes, p_cart_id, auth.uid()
  )
  RETURNING id INTO v_quote_id;

  -- Copy parent (non-core) lines first, then core children.
  FOR v_src IN
    SELECT * FROM public.pos_cart_lines
    WHERE cart_id = p_cart_id AND parent_line_id IS NULL
    ORDER BY created_at
  LOOP
    INSERT INTO public.pos_quotation_lines (
      quotation_id, stock_item_id, is_core_charge, uom_id,
      qty, qty_base, unit_price, line_total, sort_order
    ) VALUES (
      v_quote_id, v_src.stock_item_id, v_src.is_core_charge, v_src.uom_id,
      v_src.qty, v_src.qty_base, v_src.unit_price, v_src.line_total, 0
    )
    RETURNING id INTO v_new_id;
    v_line_map := v_line_map || jsonb_build_object(v_src.id::text, v_new_id::text);
  END LOOP;

  FOR v_src IN
    SELECT * FROM public.pos_cart_lines
    WHERE cart_id = p_cart_id AND parent_line_id IS NOT NULL
    ORDER BY created_at
  LOOP
    v_parent := NULLIF(v_line_map ->> v_src.parent_line_id::text, '')::UUID;
    INSERT INTO public.pos_quotation_lines (
      quotation_id, stock_item_id, parent_line_id, is_core_charge, uom_id,
      qty, qty_base, unit_price, line_total, sort_order
    ) VALUES (
      v_quote_id, v_src.stock_item_id, v_parent, v_src.is_core_charge, v_src.uom_id,
      v_src.qty, v_src.qty_base, v_src.unit_price, v_src.line_total, 1
    );
  END LOOP;

  PERFORM public._log_pos_action(
    'quotation_created',
    'pos_quotations',
    v_quote_id,
    jsonb_build_object('cart_id', p_cart_id),
    jsonb_build_object('document_number', v_doc, 'status', 'issued'),
    p_notes
  );

  RETURN v_quote_id;
END;
$$;


--
-- Name: create_pos_return_case(uuid, public.pos_return_resolution, text, jsonb, text, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_pos_return_case(p_invoice_id uuid, p_resolution public.pos_return_resolution, p_reason_code text, p_lines jsonb, p_notes text DEFAULT NULL::text, p_replacement_lines jsonb DEFAULT NULL::jsonb, p_till_session_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE i public.sales_invoices%ROWTYPE; e JSONB; l public.sales_invoice_lines%ROWTYPE; v_id UUID; v_qty NUMERIC; v_returned NUMERIC;
BEGIN
 PERFORM public._require_sales_staff(); SELECT * INTO i FROM public.sales_invoices WHERE id=p_invoice_id AND status='posted' AND doc_type='invoice';
 IF NOT FOUND THEN RAISE EXCEPTION 'posted source invoice required'; END IF;
 IF trim(COALESCE(p_reason_code,''))='' THEN RAISE EXCEPTION 'return reason required'; END IF;
 IF p_lines IS NULL OR jsonb_typeof(p_lines)<>'array' OR jsonb_array_length(p_lines)=0 THEN RAISE EXCEPTION 'at least one return line required'; END IF;
 IF p_resolution='store_credit' AND i.customer_id IS NULL THEN RAISE EXCEPTION 'store credit requires named customer'; END IF;
 IF p_resolution='replacement' AND (p_replacement_lines IS NULL OR jsonb_typeof(p_replacement_lines)<>'array' OR jsonb_array_length(p_replacement_lines)=0) THEN RAISE EXCEPTION 'replacement lines required'; END IF;
 INSERT INTO public.pos_return_cases(document_number,source_invoice_id,resolution,reason_code,notes,replacement_lines,till_session_id,created_by)
 VALUES(public.next_series_value('RET-'),p_invoice_id,p_resolution,p_reason_code,p_notes,p_replacement_lines,p_till_session_id,auth.uid()) RETURNING id INTO v_id;
 FOR e IN SELECT * FROM jsonb_array_elements(p_lines) LOOP
  SELECT * INTO l FROM public.sales_invoice_lines WHERE id=(e->>'invoice_line_id')::uuid AND invoice_id=p_invoice_id FOR UPDATE;
  IF NOT FOUND OR l.is_core_charge THEN RAISE EXCEPTION 'return line must be a non-core line from source invoice'; END IF;
  v_qty:=COALESCE((e->>'qty')::numeric,0); IF v_qty<=0 THEN RAISE EXCEPTION 'return qty must be > 0'; END IF;
  SELECT COALESCE(SUM(rl.qty),0) INTO v_returned FROM public.pos_return_case_lines rl JOIN public.pos_return_cases rc ON rc.id=rl.return_case_id
   WHERE rl.source_invoice_line_id=l.id AND rc.status='posted';
  IF v_qty>l.qty-v_returned THEN RAISE EXCEPTION 'return qty % exceeds remaining returnable qty %',v_qty,l.qty-v_returned; END IF;
  INSERT INTO public.pos_return_case_lines(return_case_id,source_invoice_line_id,stock_item_id,uom_id,qty,unit_price,condition)
  VALUES(v_id,l.id,l.stock_item_id,l.uom_id,v_qty,l.unit_price,COALESCE(NULLIF(e->>'condition','')::public.pos_return_condition,'opened'));
 END LOOP;
 RETURN v_id;
END $$;


--
-- Name: create_pos_scan_session(uuid, interval); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_pos_scan_session(p_cart_id uuid, p_ttl interval DEFAULT '00:10:00'::interval) RETURNS TABLE(session_id uuid, pairing_code text, expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cart public.pos_carts%ROWTYPE;
  v_code TEXT;
  v_id UUID;
  v_exp TIMESTAMPTZ;
  v_tries INT := 0;
BEGIN
  PERFORM public._require_sales_staff();
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authenticated user required';
  END IF;

  PERFORM public._expire_stale_pos_scan_sessions(p_cart_id);

  SELECT * INTO v_cart FROM public.pos_carts WHERE id = p_cart_id FOR UPDATE;
  IF NOT FOUND OR v_cart.status <> 'open' THEN
    RAISE EXCEPTION 'open cart not found';
  END IF;
  IF COALESCE(v_cart.channel, 'pos') <> 'pos' THEN
    RAISE EXCEPTION 'scan sessions only for POS carts';
  END IF;

  -- Replace any active companion session for this cart
  UPDATE public.pos_scan_sessions
  SET status = 'revoked', revoked_at = now(), updated_at = now()
  WHERE cart_id = p_cart_id AND status IN ('open', 'claimed');

  v_exp := now() + COALESCE(p_ttl, interval '10 minutes');
  IF v_exp <= now() OR v_exp > now() + interval '15 minutes' THEN
    RAISE EXCEPTION 'pairing TTL must be between 0 and 15 minutes';
  END IF;

  LOOP
    v_tries := v_tries + 1;
    IF v_tries > 20 THEN
      RAISE EXCEPTION 'could not allocate pairing code';
    END IF;
    v_code := lpad((floor(random() * 1000000))::integer::text, 6, '0');
    BEGIN
      INSERT INTO public.pos_scan_sessions (
        cart_id, pairing_code, owner_user_id, status, expires_at
      )
      VALUES (
        p_cart_id, v_code, auth.uid(), 'open', v_exp
      )
      RETURNING id INTO v_id;
      EXIT;
    EXCEPTION
      WHEN unique_violation THEN
        CONTINUE;
    END;
  END LOOP;

  session_id := v_id;
  pairing_code := v_code;
  expires_at := v_exp;
  RETURN NEXT;
END;
$$;


--
-- Name: create_pos_split_contipay_intent(uuid, public.contipay_method, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_pos_split_contipay_intent(p_leg_id uuid, p_method public.contipay_method, p_external_ref text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE l public.pos_split_payment_legs%ROWTYPE; s public.pos_split_payment_sessions%ROWTYPE; o public.commerce_orders%ROWTYPE; v_id UUID;
BEGIN
 PERFORM public._require_payments_staff(); SELECT * INTO l FROM public.pos_split_payment_legs WHERE id=p_leg_id FOR UPDATE;
 IF NOT FOUND OR l.tender<>'contipay' OR l.status<>'planned' THEN RAISE EXCEPTION 'planned ContiPay split leg required'; END IF;
 SELECT * INTO s FROM public.pos_split_payment_sessions WHERE id=l.session_id FOR UPDATE; SELECT * INTO o FROM public.commerce_orders WHERE id=s.commerce_order_id FOR UPDATE;
 INSERT INTO public.contipay_payment_intents(external_ref,method,customer_id,amount,currency,exchange_rate_applied,commerce_order_id,metadata,created_by)
 VALUES(trim(p_external_ref),p_method,o.customer_id,l.requested_amount,s.currency,o.exchange_rate_applied,o.id,
  COALESCE(p_metadata,'{}'::jsonb)||jsonb_build_object('pos_commerce_order_id',o.id,'pos_split_leg_id',l.id),auth.uid()) RETURNING id INTO v_id;
 UPDATE public.pos_split_payment_legs SET status='pending',provider_intent_id=v_id,external_reference=trim(p_external_ref),updated_at=now() WHERE id=l.id;
 UPDATE public.commerce_orders SET state='payment_processing',active_payment_provider='contipay',active_payment_intent_id=v_id,payment_exception=NULL,updated_at=now() WHERE id=o.id;
 PERFORM private.refresh_pos_split_payment_session(s.id); RETURN v_id;
END $$;


