--
-- Name: create_purchase_order(uuid, uuid, public.currency_code, numeric, jsonb, text, date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_purchase_order(p_supplier_id uuid, p_warehouse_id uuid, p_currency public.currency_code, p_exchange_rate numeric, p_lines jsonb, p_notes text DEFAULT NULL::text, p_expected_date date DEFAULT NULL::date, p_material_request_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_po UUID;
  v_line JSONB;
  v_no INT := 0;
  v_rate NUMERIC;
BEGIN
  PERFORM public._procurement_begin_rpc();
  PERFORM public._require_procurement_staff();

  IF p_lines IS NULL OR jsonb_array_length(p_lines) = 0 THEN
    RAISE EXCEPTION 'purchase order lines required';
  END IF;

  v_rate := CASE
    WHEN p_currency = 'USD' THEN COALESCE(p_exchange_rate, 1)
    ELSE p_exchange_rate
  END;
  IF p_currency = 'ZIG' AND (v_rate IS NULL OR v_rate <= 0) THEN
    RAISE EXCEPTION 'positive exchange_rate required for ZIG';
  END IF;

  INSERT INTO public.purchase_orders (
    document_number, supplier_id, warehouse_id, material_request_id,
    currency, exchange_rate_applied, expected_date, notes, created_by
  )
  VALUES (
    public.next_series_value('PO-'),
    p_supplier_id,
    p_warehouse_id,
    p_material_request_id,
    p_currency,
    v_rate,
    p_expected_date,
    p_notes,
    auth.uid()
  )
  RETURNING id INTO v_po;

  FOR v_line IN SELECT * FROM jsonb_array_elements(p_lines)
  LOOP
    v_no := v_no + 1;
    INSERT INTO public.purchase_order_lines (
      purchase_order_id, line_no, stock_item_id, uom_id,
      qty_ordered, unit_price, currency, material_request_line_id
    )
    VALUES (
      v_po,
      v_no,
      (v_line ->> 'stock_item_id')::uuid,
      (v_line ->> 'uom_id')::uuid,
      (v_line ->> 'qty')::numeric,
      (v_line ->> 'unit_price')::numeric,
      COALESCE((v_line ->> 'currency')::public.currency_code, p_currency),
      NULLIF(v_line ->> 'material_request_line_id', '')::uuid
    );
  END LOOP;

  PERFORM public._procurement_end_rpc();
  RETURN v_po;
EXCEPTION
  WHEN OTHERS THEN
    PERFORM public._procurement_end_rpc();
    RAISE;
END;
$$;


--
-- Name: create_rfq(uuid, date, jsonb, uuid[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_rfq(p_warehouse_id uuid, p_needed_by date, p_lines jsonb, p_supplier_ids uuid[], p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_rfq UUID;
  v_line JSONB;
  v_no INT := 0;
  v_sup UUID;
BEGIN
  PERFORM public._procurement_begin_rpc();
  PERFORM public._require_procurement_staff();

  IF p_lines IS NULL OR jsonb_array_length(p_lines) = 0 THEN
    RAISE EXCEPTION 'RFQ lines required';
  END IF;
  IF p_supplier_ids IS NULL OR array_length(p_supplier_ids, 1) IS NULL THEN
    RAISE EXCEPTION 'at least one supplier invite required';
  END IF;

  INSERT INTO public.rfqs (document_number, warehouse_id, needed_by, notes, created_by)
  VALUES (public.next_series_value('RFQ-'), p_warehouse_id, p_needed_by, p_notes, auth.uid())
  RETURNING id INTO v_rfq;

  FOR v_line IN SELECT * FROM jsonb_array_elements(p_lines)
  LOOP
    v_no := v_no + 1;
    INSERT INTO public.rfq_lines (rfq_id, line_no, stock_item_id, uom_id, qty)
    VALUES (
      v_rfq,
      v_no,
      (v_line ->> 'stock_item_id')::uuid,
      (v_line ->> 'uom_id')::uuid,
      (v_line ->> 'qty')::numeric
    );
  END LOOP;

  FOREACH v_sup IN ARRAY p_supplier_ids
  LOOP
    INSERT INTO public.rfq_suppliers (rfq_id, supplier_id)
    VALUES (v_rfq, v_sup);
  END LOOP;

  PERFORM public._procurement_end_rpc();
  RETURN v_rfq;
EXCEPTION
  WHEN OTHERS THEN
    PERFORM public._procurement_end_rpc();
    RAISE;
END;
$$;


--
-- Name: create_stock_reconciliation_draft(uuid, public.stock_reconciliation_scope, uuid[], text, public.currency_code, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_stock_reconciliation_draft(p_warehouse_id uuid, p_scope public.stock_reconciliation_scope, p_item_ids uuid[] DEFAULT NULL::uuid[], p_notes text DEFAULT NULL::text, p_currency public.currency_code DEFAULT 'USD'::public.currency_code, p_exchange_rate numeric DEFAULT NULL::numeric) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id UUID;
  v_item UUID;
  v_sys NUMERIC;
  v_cost NUMERIC;
  v_cur public.currency_code;
  v_val public.valuation_method;
BEGIN
  PERFORM public._recon_begin_rpc();
  PERFORM public._require_warehouse_staff();

  IF NOT EXISTS (SELECT 1 FROM public.warehouses WHERE id = p_warehouse_id AND is_active = true) THEN
    RAISE EXCEPTION 'warehouse not found or inactive: %', p_warehouse_id;
  END IF;

  IF p_scope = 'partial' AND (p_item_ids IS NULL OR cardinality(p_item_ids) = 0) THEN
    RAISE EXCEPTION 'partial reconciliation requires item_ids';
  END IF;

  INSERT INTO public.stock_reconciliations (
    warehouse_id, scope, status, document_number, notes,
    created_by, currency, exchange_rate_applied
  )
  VALUES (
    p_warehouse_id,
    p_scope,
    'draft',
    public.next_series_value('SRE-'),
    p_notes,
    auth.uid(),
    p_currency,
    CASE
      WHEN p_currency = 'USD' THEN COALESCE(p_exchange_rate, 1)
      ELSE p_exchange_rate
    END
  )
  RETURNING id INTO v_id;

  IF p_scope = 'full' THEN
    INSERT INTO public.stock_reconciliation_lines (
      stock_reconciliation_id, stock_item_id, system_qty,
      counted_qty, unit_cost, currency, valuation_method
    )
    SELECT
      v_id,
      sl.stock_item_id,
      sl.quantity,
      sl.quantity,
      COALESCE(sl.unit_cost, 0),
      sl.currency,
      sl.valuation_method
    FROM public.stock_levels sl
    WHERE sl.warehouse_id = p_warehouse_id;
  ELSE
    FOREACH v_item IN ARRAY p_item_ids
    LOOP
      SELECT quantity, unit_cost, currency, valuation_method
      INTO v_sys, v_cost, v_cur, v_val
      FROM public.stock_levels
      WHERE stock_item_id = v_item AND warehouse_id = p_warehouse_id;

      INSERT INTO public.stock_reconciliation_lines (
        stock_reconciliation_id, stock_item_id, system_qty,
        counted_qty, unit_cost, currency, valuation_method
      )
      VALUES (
        v_id,
        v_item,
        COALESCE(v_sys, 0),
        COALESCE(v_sys, 0),
        COALESCE(v_cost, 0),
        COALESCE(v_cur, p_currency),
        COALESCE(v_val, 'FIFO')
      );
    END LOOP;
  END IF;

  RETURN v_id;
END;
$$;


--
-- Name: create_stock_transfer(uuid, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_stock_transfer(p_from_warehouse_id uuid, p_to_warehouse_id uuid, p_notes text, p_lines jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_entry UUID;
  v_line JSONB;
  v_item UUID;
  v_uom UUID;
  v_qty NUMERIC;
  v_qty_base NUMERIC;
BEGIN
  PERFORM public._require_warehouse_staff();

  IF p_from_warehouse_id = p_to_warehouse_id THEN
    RAISE EXCEPTION 'from and to warehouses must differ';
  END IF;

  INSERT INTO public.stock_entries (
    entry_type, status, from_warehouse_id, to_warehouse_id,
    notes, created_by, first_approver_id, first_approved_at, document_number
  )
  VALUES (
    'transfer',
    'pending_approval',
    p_from_warehouse_id,
    p_to_warehouse_id,
    p_notes,
    auth.uid(),
    auth.uid(),
    now(),
    public.next_series_value('TRF-')
  )
  RETURNING id INTO v_entry;

  FOR v_line IN SELECT * FROM jsonb_array_elements(p_lines)
  LOOP
    v_item := (v_line ->> 'stock_item_id')::uuid;
    v_uom := (v_line ->> 'uom_id')::uuid;
    v_qty := (v_line ->> 'qty')::numeric;
    v_qty_base := public.convert_to_base_uom(v_item, v_uom, v_qty);

    INSERT INTO public.stock_entry_lines (
      stock_entry_id, stock_item_id, uom_id, qty, qty_base, valuation_method
    )
    VALUES (
      v_entry, v_item, v_uom, v_qty, v_qty_base,
      COALESCE((v_line ->> 'valuation_method')::public.valuation_method, 'FIFO')
    );
  END LOOP;

  PERFORM public.emit_domain_event(
    'transfer_pending_approval',
    'stock_entry:' || v_entry::text,
    jsonb_build_object('stock_entry_id', v_entry)
  );

  RETURN v_entry;
END;
$$;


--
-- Name: create_supplier(text, text, text, text, public.currency_code); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_supplier(p_code text, p_name text, p_email text DEFAULT NULL::text, p_phone_e164 text DEFAULT NULL::text, p_default_currency public.currency_code DEFAULT 'USD'::public.currency_code) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_id uuid;
BEGIN
  IF NOT (
    auth.role() = 'service_role'
    OR public.has_staff_role(ARRAY['admin']::public.staff_role[])
  ) THEN
    RAISE EXCEPTION 'admin role required';
  END IF;

  IF NULLIF(trim(COALESCE(p_code,'')),'') IS NULL THEN
    RAISE EXCEPTION 'supplier code required';
  END IF;
  IF NULLIF(trim(COALESCE(p_name,'')),'') IS NULL THEN
    RAISE EXCEPTION 'supplier name required';
  END IF;

  INSERT INTO public.suppliers(code,name,email,phone_e164,default_currency)
  VALUES(upper(trim(p_code)),trim(p_name),NULLIF(trim(COALESCE(p_email,'')),''),NULLIF(trim(COALESCE(p_phone_e164,'')),''),p_default_currency)
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$$;


--
-- Name: create_warehouse_bin(uuid, text, text, integer, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_warehouse_bin(p_warehouse_id uuid, p_code text, p_name text, p_pick_path_seq integer DEFAULT 100, p_aisle text DEFAULT NULL::text, p_rack text DEFAULT NULL::text, p_shelf text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id UUID;
  v_active BOOLEAN;
BEGIN
  PERFORM public._require_warehouse_staff();

  SELECT is_active INTO v_active FROM public.warehouses WHERE id = p_warehouse_id;
  IF v_active IS NULL THEN
    RAISE EXCEPTION 'warehouse not found';
  END IF;
  IF NOT v_active THEN
    RAISE EXCEPTION 'warehouse is inactive';
  END IF;
  -- Quarantine warehouses may have bins; returns still must use post_return_to_quarantine

  IF p_code IS NULL OR btrim(p_code) = '' THEN
    RAISE EXCEPTION 'bin code required';
  END IF;
  IF p_name IS NULL OR btrim(p_name) = '' THEN
    RAISE EXCEPTION 'bin name required';
  END IF;

  INSERT INTO public.warehouse_bins (
    warehouse_id, code, name, pick_path_seq, aisle, rack, shelf, created_by
  )
  VALUES (
    p_warehouse_id,
    upper(btrim(p_code)),
    btrim(p_name),
    COALESCE(p_pick_path_seq, 100),
    NULLIF(btrim(p_aisle), ''),
    NULLIF(btrim(p_rack), ''),
    NULLIF(btrim(p_shelf), ''),
    auth.uid()
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


--
-- Name: current_employee_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_employee_id() RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT e.id
  FROM public.employees e
  WHERE e.user_id = auth.uid()
