$$;


--
-- Name: current_supplier_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_supplier_id() RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT s.id
  FROM public.suppliers s
  WHERE s.profile_id = COALESCE(
    auth.uid(),
    NULLIF(current_setting('request.jwt.claim.sub', true), '')::uuid
  )
    AND s.is_active
  LIMIT 1;
$$;


--
-- Name: customers_protect_privileged_columns(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customers_protect_privileged_columns() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF auth.role() = 'service_role' OR public.is_staff() THEN
    RETURN NEW;
  END IF;

  IF public._storefront_rpc_active() THEN
    IF NEW.profile_id IS DISTINCT FROM OLD.profile_id
       OR NEW.price_list_id IS DISTINCT FROM OLD.price_list_id
       OR NEW.credit_limit IS DISTINCT FROM OLD.credit_limit
       OR NEW.credit_hold IS DISTINCT FROM OLD.credit_hold
       OR NEW.currency IS DISTINCT FROM OLD.currency
       OR NEW.id IS DISTINCT FROM OLD.id
       OR NEW.last_promotional_message_at IS DISTINCT FROM OLD.last_promotional_message_at
    THEN
      RAISE EXCEPTION 'storefront path may not change commercial control fields';
    END IF;
    RETURN NEW;
  END IF;

  -- Self-service: contact + receipt prefs + marketing_opt_in (not cooldown stamp)
  IF NEW.profile_id IS DISTINCT FROM OLD.profile_id
     OR NEW.price_list_id IS DISTINCT FROM OLD.price_list_id
     OR NEW.credit_limit IS DISTINCT FROM OLD.credit_limit
     OR NEW.credit_hold IS DISTINCT FROM OLD.credit_hold
     OR NEW.open_balance IS DISTINCT FROM OLD.open_balance
     OR NEW.currency IS DISTINCT FROM OLD.currency
     OR NEW.id IS DISTINCT FROM OLD.id
     OR NEW.last_promotional_message_at IS DISTINCT FROM OLD.last_promotional_message_at
  THEN
    RAISE EXCEPTION 'customers may only update contact, receipt, and marketing opt-in fields';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: deactivate_preferred_supplier(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.deactivate_preferred_supplier(p_supplier_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
 IF NOT public.has_staff_role(ARRAY['admin','warehouse','finance']::public.staff_role[]) THEN RAISE EXCEPTION 'not authorized'; END IF;
 UPDATE public.suppliers SET is_preferred=false,is_active=false,updated_at=now() WHERE id=p_supplier_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'supplier not found'; END IF;
 RETURN p_supplier_id;
END;$$;


