--
-- Name: decide_delivery_balance_on_account(uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.decide_delivery_balance_on_account(p_approval_id uuid, p_approve boolean, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE b public.delivery_balance_approvals%ROWTYPE;
BEGIN
 IF NOT (public.has_staff_role(ARRAY['admin','dispatcher','finance']::public.staff_role[]) OR public.is_pos_approver()) THEN
  RAISE EXCEPTION 'dispatcher, finance, admin or approver required'; END IF;
 SELECT * INTO b FROM public.delivery_balance_approvals WHERE id=p_approval_id FOR UPDATE;
 IF NOT FOUND OR b.status<>'pending' THEN RAISE EXCEPTION 'pending request required'; END IF;
 IF b.requested_by = auth.uid() THEN RAISE EXCEPTION 'someone else must decide your own request'; END IF;
 IF NOT p_approve AND trim(COALESCE(p_note,''))='' THEN RAISE EXCEPTION 'say why it is refused'; END IF;
 UPDATE public.delivery_balance_approvals SET status=CASE WHEN p_approve THEN 'approved' ELSE 'refused' END,
  decided_by=auth.uid(),decided_at=now(),decision_note=NULLIF(trim(COALESCE(p_note,'')),''),updated_at=now()
 WHERE id=b.id RETURNING * INTO b;
 RETURN private._delivery_balance_approval_json(b);
END $$;


--
-- Name: decide_leave_request(uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.decide_leave_request(p_request_id uuid, p_approve boolean, p_note text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row public.hr_leave_requests%ROWTYPE;
  v_year INT;
BEGIN
  IF NOT public.has_staff_role(ARRAY['admin', 'hr']::public.staff_role[]) THEN
    RAISE EXCEPTION 'hr or admin role required';
  END IF;

  SELECT * INTO v_row FROM public.hr_leave_requests WHERE id = p_request_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'leave request not found'; END IF;
  IF v_row.status <> 'submitted' THEN
    RAISE EXCEPTION 'only submitted requests can be decided';
  END IF;

  IF p_approve THEN
    v_year := EXTRACT(YEAR FROM v_row.start_date)::INT;
    INSERT INTO public.hr_leave_balances (employee_id, leave_type_id, year, entitlement_days, used_days)
    VALUES (v_row.employee_id, v_row.leave_type_id, v_year, 0, v_row.days)
    ON CONFLICT (employee_id, leave_type_id, year) DO UPDATE
    SET used_days = public.hr_leave_balances.used_days + EXCLUDED.used_days,
        updated_at = now();

    UPDATE public.hr_leave_requests
    SET status = 'approved', decided_by = auth.uid(), decided_at = now(),
        decision_note = p_note, updated_at = now()
    WHERE id = p_request_id;
  ELSE
    UPDATE public.hr_leave_requests
    SET status = 'rejected', decided_by = auth.uid(), decided_at = now(),
        decision_note = p_note, updated_at = now()
    WHERE id = p_request_id;
  END IF;

  RETURN p_request_id;
END;
$$;


--
-- Name: delete_customer_address(uuid); Type: FUNCTION; Schema: public; Owner: -
