-- Name: delete_pos_popular_pin(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_pos_popular_pin(p_item_type text, p_item_key text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_count integer;
BEGIN
  PERFORM public._require_sales_staff();
  DELETE FROM public.pos_operator_popular_pins
  WHERE user_id = auth.uid()
    AND item_type = lower(trim(COALESCE(p_item_type,'')))
    AND item_key = trim(COALESCE(p_item_key,''));
