--
-- Name: delete_stock_item_image(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_stock_item_image(p_image_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_item UUID; v_was_primary BOOLEAN; v_next UUID; BEGIN IF NOT public.has_staff_role(ARRAY['admin','sales','warehouse']::public.staff_role[]) THEN RAISE EXCEPTION 'staff role required'; END IF; SELECT stock_item_id,is_primary INTO v_item,v_was_primary FROM public.stock_item_images WHERE id=p_image_id; IF v_item IS NULL THEN RAISE EXCEPTION 'image not found'; END IF; DELETE FROM public.stock_item_images WHERE id=p_image_id; IF v_was_primary THEN SELECT id INTO v_next FROM public.stock_item_images WHERE stock_item_id=v_item ORDER BY sort_order,created_at LIMIT 1; IF v_next IS NOT NULL THEN UPDATE public.stock_item_images SET is_primary=true WHERE id=v_next; END IF; END IF; RETURN p_image_id; END;$$;


--
-- Name: delivery_geofence_suggestion(uuid, double precision, double precision, double precision, double precision); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delivery_geofence_suggestion(p_delivery_job_id uuid, p_lat double precision, p_lng double precision, p_arrive_radius_m double precision DEFAULT 150, p_complete_radius_m double precision DEFAULT 50) RETURNS TABLE(suggest_arrive boolean, suggest_complete boolean, distance_m double precision)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_job public.delivery_jobs%ROWTYPE;
  v_uid UUID := auth.uid();
  v_allowed BOOLEAN := false;
  v_dist DOUBLE PRECISION;
  v_arrive DOUBLE PRECISION := COALESCE(p_arrive_radius_m, 150);
  v_complete DOUBLE PRECISION := COALESCE(p_complete_radius_m, 50);
BEGIN
  IF p_lat IS NULL OR p_lng IS NULL THEN
    RAISE EXCEPTION 'lat and lng required';
  END IF;
  IF v_arrive < 0 OR v_complete < 0 THEN
    RAISE EXCEPTION 'geofence radii must be >= 0';
  END IF;
  -- Complete radius should not exceed arrive radius
  IF v_complete > v_arrive THEN
    v_complete := v_arrive;
  END IF;

  SELECT * INTO v_job FROM public.delivery_jobs WHERE id = p_delivery_job_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'delivery job not found';
  END IF;

  IF auth.role() = 'service_role'
     OR public.has_staff_role(
       ARRAY['admin', 'warehouse', 'dispatcher']::public.staff_role[]
     ) THEN
    v_allowed := true;
  ELSIF v_uid IS NOT NULL
        AND v_job.assignee_user_id = v_uid
        AND public.has_staff_role(ARRAY['driver']::public.staff_role[]) THEN
    v_allowed := true;
  END IF;

  IF NOT v_allowed THEN
    RAISE EXCEPTION 'assigned driver or dispatcher/warehouse/admin required for geofence suggestion';
  END IF;

  IF v_job.dropoff_lat IS NULL OR v_job.dropoff_lng IS NULL THEN
    RETURN QUERY SELECT false, false, NULL::DOUBLE PRECISION;
    RETURN;
  END IF;

  v_dist := public._haversine_meters(
    p_lat, p_lng, v_job.dropoff_lat, v_job.dropoff_lng
  );

  RETURN QUERY SELECT
    (v_dist IS NOT NULL AND v_dist <= v_arrive),
    (v_dist IS NOT NULL AND v_dist <= v_complete),
    v_dist;
END;
$$;


--
-- Name: disburse_finance_requisition(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.disburse_finance_requisition(p_requisition_id uuid, p_entry_date date DEFAULT CURRENT_DATE) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE v_row public.finance_requisitions%ROWTYPE; v_je UUID; v_desc TEXT; v_rate NUMERIC; v_lines JSONB:='[]'::jsonb; v_line RECORD; v_line_sum NUMERIC(18,2):=0; v_entry_date DATE; v_fund VARCHAR(10); BEGIN SELECT * INTO v_row FROM public.finance_requisitions WHERE id=p_requisition_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'requisition not found: %',p_requisition_id; END IF; IF NOT (auth.role()='service_role' OR public.has_staff_role(ARRAY['admin','finance']::public.staff_role[]) OR (v_row.status='approved' AND v_row.approved_by IS NOT NULL AND v_row.approved_by=auth.uid())) THEN RAISE EXCEPTION 'finance or admin role required to disburse'; END IF; IF v_row.status<>'approved' THEN RAISE EXCEPTION 'disburse requires approved status (got %); cannot skip approval',v_row.status; END IF; IF v_row.journal_entry_id IS NOT NULL THEN RAISE EXCEPTION 'requisition already disbursed'; END IF; IF v_row.currency='ZIG' AND (v_row.exchange_rate_applied IS NULL OR v_row.exchange_rate_applied<=0) THEN RAISE EXCEPTION 'exchange_rate_applied required to disburse ZIG requisition'; END IF; v_entry_date:=COALESCE(v_row.intended_entry_date,p_entry_date,CURRENT_DATE); v_rate:=CASE WHEN v_row.currency='USD' THEN COALESCE(v_row.exchange_rate_applied,1) ELSE v_row.exchange_rate_applied END; v_desc:=format('Disburse %s %s — %s',COALESCE(v_row.document_number,p_requisition_id::text),v_row.req_type::text,COALESCE(v_row.payee,v_row.memo,'requisition')); IF v_row.req_type='petty_float' THEN v_fund:=COALESCE(nullif(trim(v_row.expense_account_code),''),public.petty_cash_funding_account_code()); v_lines:=jsonb_build_array(jsonb_build_object('account_code','1110','debit',v_row.amount,'credit',0,'currency',v_row.currency),jsonb_build_object('account_code',v_fund,'debit',0,'credit',v_row.amount,'currency',v_row.currency)); ELSE FOR v_line IN SELECT line_no,description,expense_account_code,amount FROM public.finance_requisition_lines WHERE requisition_id=p_requisition_id ORDER BY line_no LOOP v_line_sum:=v_line_sum+v_line.amount; v_lines:=v_lines||jsonb_build_array(jsonb_build_object('account_code',v_line.expense_account_code,'debit',v_line.amount,'credit',0,'currency',v_row.currency)); END LOOP; IF jsonb_array_length(v_lines)<1 THEN RAISE EXCEPTION 'cannot disburse requisition without lines'; END IF; IF v_line_sum IS DISTINCT FROM v_row.amount THEN RAISE EXCEPTION 'header amount % does not match line total %',v_row.amount,v_line_sum; END IF; v_lines:=v_lines||jsonb_build_array(jsonb_build_object('account_code',v_row.cash_account_code,'debit',0,'credit',v_row.amount,'currency',v_row.currency)); END IF; v_je:=public.post_journal_entry(v_entry_date,v_desc,v_row.currency,v_rate,v_lines); PERFORM public._finance_req_rpc_enter(); UPDATE public.finance_requisitions SET status='disbursed',disbursed_by=auth.uid(),disbursed_at=now(),journal_entry_id=v_je,payment_entry_id=NULL,updated_at=now() WHERE id=p_requisition_id; RETURN v_je; END; $$;


