--
-- Name: drain_sms_outbox_batch(integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.drain_sms_outbox_batch(p_limit integer DEFAULT 50, p_stub_success boolean DEFAULT true) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row public.sms_outbox%ROWTYPE;
  v_count INT := 0;
  v_limit INT := LEAST(100, GREATEST(1, COALESCE(p_limit, 50)));
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'service_role required';
  END IF;

  FOR v_row IN
    SELECT *
    FROM public.sms_outbox
    WHERE status IN ('pending', 'failed')
      AND attempt_count < 8
    ORDER BY created_at
    LIMIT v_limit
    FOR UPDATE SKIP LOCKED
  LOOP
    IF p_stub_success THEN
      UPDATE public.sms_outbox
      SET
        status = 'sent',
        attempt_count = attempt_count + 1,
        last_error = NULL,
        sent_at = now(),
        provider_message_id = COALESCE(provider_message_id, 'stub-' || id::text),
        claimed_at = NULL
      WHERE id = v_row.id
        AND status IS DISTINCT FROM 'sent';
    ELSE
      UPDATE public.sms_outbox
      SET
        status = 'failed',
        attempt_count = attempt_count + 1,
        last_error = COALESCE(last_error, 'stub SMS gateway failed'),
        claimed_at = NULL
      WHERE id = v_row.id
        AND status IS DISTINCT FROM 'sent';
    END IF;
    v_count := v_count + 1;
  END LOOP;

  RETURN v_count;
END;
$$;


--
-- Name: earn_loyalty_from_spend(uuid, numeric, public.currency_code, numeric, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.earn_loyalty_from_spend(p_customer_id uuid, p_spend_amount numeric, p_currency public.currency_code DEFAULT 'USD'::public.currency_code, p_exchange_rate numeric DEFAULT 1, p_reason text DEFAULT NULL::text, p_sales_invoice_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_settings public.loyalty_program_settings%ROWTYPE;
  v_points NUMERIC;
BEGIN
  PERFORM public._require_loyalty_staff();

  SELECT * INTO v_settings FROM public.loyalty_program_settings WHERE id = 1;
  IF NOT FOUND OR NOT v_settings.is_active THEN
    RAISE EXCEPTION 'loyalty program inactive or missing';
  END IF;
  IF p_spend_amount IS NULL OR p_spend_amount <= 0 THEN
    RAISE EXCEPTION 'spend amount must be > 0';
  END IF;

  v_points := round(p_spend_amount * v_settings.points_per_currency_unit, 2);
  IF v_points <= 0 THEN
    RAISE EXCEPTION 'computed points must be > 0';
  END IF;

  RETURN public.earn_loyalty_points(
    p_customer_id, v_points, p_currency, p_exchange_rate,
    COALESCE(p_reason, format('Loyalty earn from spend %s %s', p_spend_amount, p_currency)),
    p_sales_invoice_id
  );
END;
$$;


--
-- Name: earn_loyalty_points(uuid, numeric, public.currency_code, numeric, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.earn_loyalty_points(p_customer_id uuid, p_points numeric, p_currency public.currency_code DEFAULT 'USD'::public.currency_code, p_exchange_rate numeric DEFAULT 1, p_reason text DEFAULT NULL::text, p_sales_invoice_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_settings public.loyalty_program_settings%ROWTYPE;
  v_money NUMERIC;
  v_rate NUMERIC;
  v_journal UUID;
  v_ledger UUID;
  v_inv public.sales_invoices%ROWTYPE;
BEGIN
  PERFORM public._require_loyalty_staff();
  PERFORM public._loyalty_rpc_enter();

  SELECT * INTO v_settings FROM public.loyalty_program_settings WHERE id = 1;
  IF NOT FOUND OR NOT v_settings.is_active THEN
    RAISE EXCEPTION 'loyalty program inactive or missing';
  END IF;

  IF p_customer_id IS NULL THEN
    RAISE EXCEPTION 'customer_id required';
  END IF;
  IF p_points IS NULL OR p_points <= 0 THEN
    RAISE EXCEPTION 'earn points must be > 0';
  END IF;
  IF p_currency = 'ZIG' AND (p_exchange_rate IS NULL OR p_exchange_rate <= 0) THEN
    RAISE EXCEPTION 'exchange_rate_applied required for ZIG';
  END IF;

  IF p_sales_invoice_id IS NOT NULL THEN
    SELECT * INTO v_inv FROM public.sales_invoices WHERE id = p_sales_invoice_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'sales invoice not found';
    END IF;
    IF v_inv.customer_id IS DISTINCT FROM p_customer_id THEN
      RAISE EXCEPTION 'invoice customer mismatch';
    END IF;
  END IF;

  v_rate := CASE
    WHEN p_currency = 'USD' THEN COALESCE(p_exchange_rate, 1)
    ELSE p_exchange_rate
  END;
  v_money := public._loyalty_money_value(p_points);

  IF v_money > 0 THEN
    v_journal := public.post_journal_entry(
      CURRENT_DATE,
      COALESCE(p_reason, format('Loyalty earn %s pts', p_points)),
      p_currency,
      v_rate,
      jsonb_build_array(
        jsonb_build_object(
          'account_code', '5350',
          'debit', v_money, 'credit', 0, 'currency', p_currency
        ),
        jsonb_build_object(
          'account_code', '2210',
          'debit', 0, 'credit', v_money, 'currency', p_currency
        )
      )
    );
  END IF;

  v_ledger := public._append_loyalty(
    p_customer_id, 'earn', p_points, p_currency, v_rate, v_money,
    p_sales_invoice_id, v_journal,
    COALESCE(p_reason, format('Loyalty earn %s pts', p_points))
  );

  RETURN v_ledger;
END;
$$;


--
-- Name: emit_domain_event(text, text, jsonb, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.emit_domain_event(p_event_code text, p_dedupe_key text, p_payload jsonb DEFAULT '{}'::jsonb, p_actor_user_id uuid DEFAULT auth.uid(), p_message_body text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_event_id uuid;
  v_body text;
  v_desc text;
  v_aggregate_id uuid;
  v_event_type text;
BEGIN
  IF auth.role()='authenticated'
     AND NOT public.is_staff()
     AND NOT public._storefront_rpc_active() THEN
    RAISE EXCEPTION 'Only staff or service role may emit domain events';
  END IF;

  IF NOT EXISTS(
    SELECT 1 FROM public.sms_event_catalog c
    WHERE c.code=p_event_code AND c.is_active
  ) THEN
    IF p_event_code IN ('return_approved','return_rejected','return_received','refund_pending','refund_completed') THEN
      v_aggregate_id:=COALESCE(
        NULLIF(p_payload->>'return_request_id','')::uuid,
        NULLIF(p_payload->>'refund_request_id','')::uuid
      );
      IF v_aggregate_id IS NULL THEN
        RAISE EXCEPTION 'return/refund outbox event requires aggregate id';
      END IF;
      v_event_type:=CASE p_event_code
        WHEN 'return_approved' THEN 'return.approved'
        WHEN 'return_rejected' THEN 'return.rejected'
        WHEN 'return_received' THEN 'return.received'
        WHEN 'refund_pending' THEN 'refund.pending'
        WHEN 'refund_completed' THEN 'refund.completed'
      END;
      RETURN private.enqueue_commerce_event(p_dedupe_key,v_event_type,v_aggregate_id,COALESCE(p_payload,'{}'::jsonb));
    END IF;
    RAISE EXCEPTION 'Unknown or inactive event_code: %',p_event_code;
  END IF;

  INSERT INTO public.domain_events(event_code,dedupe_key,payload,actor_user_id)
  VALUES(p_event_code,p_dedupe_key,COALESCE(p_payload,'{}'::jsonb),p_actor_user_id)
  ON CONFLICT(event_code,dedupe_key) DO NOTHING
  RETURNING id INTO v_event_id;

  IF v_event_id IS NULL THEN
    SELECT id INTO v_event_id FROM public.domain_events
    WHERE event_code=p_event_code AND dedupe_key=p_dedupe_key;
  END IF;

  SELECT description INTO v_desc FROM public.sms_event_catalog WHERE code=p_event_code;
  v_body:=COALESCE(p_message_body,format('GTR Auto: %s (%s)',v_desc,p_event_code));
  INSERT INTO public.sms_outbox(domain_event_id,event_code,recipient_user_id,phone_e164,body)
  SELECT v_event_id,p_event_code,p.user_id,p.phone_e164,v_body
  FROM public.manager_sms_preferences p
  WHERE p.event_code=p_event_code AND p.enabled=true
  ON CONFLICT(domain_event_id,recipient_user_id) DO NOTHING;
  RETURN v_event_id;
END;
$$;


--
-- Name: emit_staff_no_show(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.emit_staff_no_show(p_employee_id uuid, p_window_label text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_emp public.employees%ROWTYPE;
  v_event UUID;
  v_dedupe TEXT;
BEGIN
  PERFORM public._require_hr_staff();

  SELECT * INTO v_emp FROM public.employees WHERE id = p_employee_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'employee not found: %', p_employee_id;
  END IF;

  v_dedupe := format(
    'staff_no_show:%s:%s',
    p_employee_id,
    COALESCE(p_window_label, to_char(CURRENT_DATE, 'YYYY-MM-DD'))
  );

  v_event := public.emit_domain_event(
    'staff_no_show',
    v_dedupe,
    jsonb_build_object(
      'employee_id', p_employee_id,
      'employee_code', v_emp.employee_code,
      'full_name', v_emp.full_name,
      'window', p_window_label
    ),
    auth.uid(),
    format('GTR Auto: staff no-show %s (%s)', v_emp.full_name, v_emp.employee_code)
  );

  RETURN v_event;
END;
$$;


--
-- Name: enforce_auth_edge_rate_limit(text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_auth_edge_rate_limit(p_operation text, p_identifier_hash text, p_ip_hash text DEFAULT NULL::text, p_device_hash text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_op text := lower(trim(coalesce(p_operation, '')));
  v_identifier text := trim(coalesce(p_identifier_hash, ''));
  v_ip text := trim(coalesce(p_ip_hash, ''));
  v_device text := trim(coalesce(p_device_hash, ''));
  v_identifier_max integer;
  v_ip_max integer;
  v_device_max integer;
  v_global_max integer;
  v_window integer := 900;
begin
  if v_identifier = '' then
    raise exception 'identifier hash required';
  end if;

  case v_op
    when 'signup_request' then
      v_identifier_max := 5; v_ip_max := 30; v_device_max := 20; v_global_max := 300;
    when 'signup_verify' then
      v_identifier_max := 20; v_ip_max := 60; v_device_max := 40; v_global_max := 1200;
    when 'login' then
      v_identifier_max := 30; v_ip_max := 90; v_device_max := 60; v_global_max := 1800;
    when 'password_reset_request' then
      v_identifier_max := 5; v_ip_max := 30; v_device_max := 20; v_global_max := 300;
    when 'password_reset_verify' then
      v_identifier_max := 20; v_ip_max := 60; v_device_max := 40; v_global_max := 1200;
    else
      raise exception 'invalid auth edge operation';
  end case;

  perform public._consume_auth_rate_limit('auth_edge:' || v_op || ':identifier', v_identifier, v_identifier_max, v_window);
  if v_ip <> '' then
    perform public._consume_auth_rate_limit('auth_edge:' || v_op || ':ip', v_ip, v_ip_max, v_window);
  end if;
  if v_device <> '' then
    perform public._consume_auth_rate_limit('auth_edge:' || v_op || ':device', v_device, v_device_max, v_window);
  end if;
  perform public._consume_auth_rate_limit('auth_edge:' || v_op || ':global', 'global', v_global_max, 60);

  return jsonb_build_object('allowed', true);
end;
$$;


--
-- Name: enqueue_customer_receipts(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_customer_receipts(p_invoice_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_inv public.sales_invoices%ROWTYPE;
  v_cust public.customers%ROWTYPE;
  v_summary TEXT;
  v_doc_label TEXT;
  v_count INT := 0;
  v_phone TEXT;
  v_email TEXT;
  v_wa TEXT;
BEGIN
  SELECT * INTO v_inv FROM public.sales_invoices WHERE id = p_invoice_id;
  IF NOT FOUND OR v_inv.status <> 'posted' THEN
    RAISE EXCEPTION 'posted invoice/credit note required';
  END IF;

  IF v_inv.customer_id IS NOT NULL THEN
    SELECT * INTO v_cust FROM public.customers WHERE id = v_inv.customer_id;
  END IF;

  v_doc_label := COALESCE(v_inv.document_number, v_inv.id::text);
  v_summary := format(
    'GTR Auto %s %s Total %s %s. Thank you.',
    CASE WHEN v_inv.doc_type = 'credit_note' THEN 'Credit' ELSE 'Sale' END,
    v_doc_label,
    v_inv.total::text,
    v_inv.currency::text
  );
  -- PDF link appended by Phase 13 worker when download_url is set:
  -- summary_body || E'\n' || download_url

  v_phone := COALESCE(v_inv.customer_phone_e164, v_cust.phone_e164);
  v_email := COALESCE(v_inv.customer_email, v_cust.email);
  v_wa := COALESCE(v_inv.customer_whatsapp_e164, v_cust.whatsapp_e164, v_phone);

  IF v_phone IS NOT NULL AND COALESCE(v_cust.sms_receipts, true) THEN
    INSERT INTO public.customer_receipt_outbox (
      document_type, document_id, channel, recipient, summary_body
    )
    VALUES (
      CASE WHEN v_inv.doc_type = 'credit_note' THEN 'credit_note' ELSE 'sales_invoice' END,
      p_invoice_id,
      'sms',
      v_phone,
      v_summary || E'\n[PDF link pending]'
    )
    ON CONFLICT (document_id, channel) DO NOTHING;
    v_count := v_count + 1;
  END IF;

  IF v_email IS NOT NULL AND COALESCE(v_cust.email_receipts, true) THEN
    INSERT INTO public.customer_receipt_outbox (
      document_type, document_id, channel, recipient, summary_body
    )
    VALUES (
      CASE WHEN v_inv.doc_type = 'credit_note' THEN 'credit_note' ELSE 'sales_invoice' END,
      p_invoice_id,
      'email',
      v_email,
      v_summary
    )
    ON CONFLICT (document_id, channel) DO NOTHING;
    v_count := v_count + 1;
  END IF;

  IF v_wa IS NOT NULL AND COALESCE(v_cust.whatsapp_receipts, true) THEN
    INSERT INTO public.customer_receipt_outbox (
      document_type, document_id, channel, recipient, summary_body
    )
    VALUES (
      CASE WHEN v_inv.doc_type = 'credit_note' THEN 'credit_note' ELSE 'sales_invoice' END,
      p_invoice_id,
      'whatsapp',
      v_wa,
      v_summary || E'\n[PDF link pending]'
    )
    ON CONFLICT (document_id, channel) DO NOTHING;
    v_count := v_count + 1;
  END IF;

  IF v_inv.doc_type = 'invoice' THEN
    PERFORM public.emit_domain_event(
      'order_completed',
      'receipt:' || p_invoice_id::text,
      jsonb_build_object('invoice_id', p_invoice_id),
      auth.uid(),
      NULL
    );
  END IF;

  RETURN v_count;
END;
$$;


--
-- Name: enqueue_hr_credential_outbox(uuid, uuid, public.hr_credential_channel, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_hr_credential_outbox(p_employee_id uuid, p_user_id uuid, p_channel public.hr_credential_channel, p_recipient text, p_body text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id UUID;
  v_recipient TEXT := NULLIF(trim(COALESCE(p_recipient, '')), '');
  v_body TEXT := NULLIF(trim(COALESCE(p_body, '')), '');
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'service_role required';
  END IF;

  IF p_employee_id IS NULL OR p_user_id IS NULL THEN
    RAISE EXCEPTION 'employee_id and user_id required';
  END IF;
  IF v_recipient IS NULL OR v_body IS NULL THEN
    RAISE EXCEPTION 'recipient and body required';
  END IF;

  -- Opportunistic scrub of stale plaintext before planting a new body.
  PERFORM public.scrub_hr_credential_outbox_bodies(90);

  INSERT INTO public.hr_credential_outbox (
    employee_id, user_id, channel, recipient, body, status, claimed_at, created_by
  ) VALUES (
    p_employee_id,
    p_user_id,
    p_channel,
    v_recipient,
    v_body,
    'sending'::public.hr_credential_outbox_status,
    now(),
    auth.uid()
  )
  ON CONFLICT (employee_id, channel, user_id) DO UPDATE
  SET
    recipient = EXCLUDED.recipient,
    body = EXCLUDED.body,
    status = 'sending'::public.hr_credential_outbox_status,
    attempt_count = 0,
    last_error = NULL,
    provider_message_id = NULL,
    sent_at = NULL,
    claimed_at = now(),
    created_by = COALESCE(EXCLUDED.created_by, public.hr_credential_outbox.created_by),
    created_at = now()
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


--
-- Name: ensure_customer_for_user(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_customer_for_user(p_uid uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cust UUID;
  v_name TEXT;
  v_email TEXT;
  v_retail UUID;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'service_role required';
  END IF;

  IF p_uid IS NULL THEN
    RAISE EXCEPTION 'p_uid required';
  END IF;

  IF public._storefront_customer_provision_denied(p_uid) THEN
    RAISE EXCEPTION 'staff accounts do not use storefront customer provisioning';
  END IF;

  SELECT c.id INTO v_cust
  FROM public.customers c
  WHERE c.profile_id = p_uid
  LIMIT 1;

  IF v_cust IS NOT NULL THEN
    RETURN v_cust;
  END IF;

  INSERT INTO public.profiles (id, full_name, is_staff)
  VALUES (p_uid, NULL, false)
  ON CONFLICT (id) DO NOTHING;

  SELECT
    nullif(
      btrim(
        COALESCE(
          p.full_name,
          split_part(COALESCE(u.email, ''), '@', 1)
        )
      ),
      ''
    ),
    nullif(u.email, '')
  INTO v_name, v_email
  FROM auth.users u
  LEFT JOIN public.profiles p ON p.id = u.id
  WHERE u.id = p_uid;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'auth user not found: %', p_uid;
  END IF;

  IF v_name IS NULL THEN
    v_name := 'Customer';
  END IF;

  SELECT pl.id INTO v_retail
  FROM public.price_lists pl
  WHERE pl.code = 'RETAIL' AND pl.is_active
  LIMIT 1;

  INSERT INTO public.customers (
    display_name,
    email,
    currency,
    profile_id,
    price_list_id
  )
  VALUES (v_name, v_email, 'USD', p_uid, v_retail)
  ON CONFLICT (profile_id) WHERE (profile_id IS NOT NULL) DO NOTHING
  RETURNING id INTO v_cust;

  IF v_cust IS NULL THEN
    SELECT c.id INTO v_cust
    FROM public.customers c
    WHERE c.profile_id = p_uid
    LIMIT 1;
  END IF;

  RETURN v_cust;
END;
$$;


--
-- Name: FUNCTION ensure_customer_for_user(p_uid uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.ensure_customer_for_user(p_uid uuid) IS 'service_role only: idempotent retail customers row for p_uid. Used by auth-otp complete_signup after Admin createUser (handle_new_user cannot see auth_otp meta).';


--
-- Name: ensure_own_customer(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_own_customer() RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_cust UUID;
  v_name TEXT;
  v_email TEXT;
  v_retail UUID;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not authenticated';
  END IF;

  IF public._storefront_customer_provision_denied(v_uid) THEN
    RAISE EXCEPTION 'staff accounts do not use storefront customer provisioning';
  END IF;

  SELECT c.id INTO v_cust
  FROM public.customers c
  WHERE c.profile_id = v_uid
  LIMIT 1;

  IF v_cust IS NOT NULL THEN
    RETURN v_cust;
  END IF;

  INSERT INTO public.profiles (id, full_name, is_staff)
  VALUES (v_uid, NULL, false)
  ON CONFLICT (id) DO NOTHING;

  SELECT
    nullif(
      btrim(
        COALESCE(
          p.full_name,
          split_part(COALESCE(auth.jwt() ->> 'email', ''), '@', 1)
        )
      ),
      ''
    ),
    nullif(auth.jwt() ->> 'email', '')
  INTO v_name, v_email
  FROM public.profiles p
  WHERE p.id = v_uid;

  IF v_name IS NULL THEN
    v_name := 'Customer';
  END IF;

  SELECT pl.id INTO v_retail
  FROM public.price_lists pl
  WHERE pl.code = 'RETAIL' AND pl.is_active
  LIMIT 1;

  INSERT INTO public.customers (
    display_name,
    email,
    currency,
    profile_id,
    price_list_id
  )
  VALUES (v_name, v_email, 'USD', v_uid, v_retail)
  ON CONFLICT (profile_id) WHERE (profile_id IS NOT NULL) DO NOTHING
  RETURNING id INTO v_cust;

  IF v_cust IS NULL THEN
    SELECT c.id INTO v_cust
    FROM public.customers c
    WHERE c.profile_id = v_uid
    LIMIT 1;
  END IF;

  RETURN v_cust;
END;
$$;


--
-- Name: FUNCTION ensure_own_customer(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.ensure_own_customer() IS 'Idempotent: return customers.id for auth.uid(), inserting a retail row if missing. Staff / employees / HR-onboarded denied. Call after OAuth when _current_customer_id() is null. OTP signup prefers ensure_customer_for_user from Edge.';


--
-- Name: ensure_pos_walkin_customer(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_pos_walkin_customer() RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id UUID;
BEGIN
  -- Sales/payments/admin only — not open to storefront customers.
  PERFORM public._require_payments_staff();

  SELECT id INTO v_id
  FROM public.customers
  WHERE display_name = 'POS Walk-in'
  ORDER BY created_at
  LIMIT 1;

  IF v_id IS NOT NULL THEN
    RETURN v_id;
  END IF;

  INSERT INTO public.customers (display_name, currency, credit_limit, credit_hold)
  VALUES ('POS Walk-in', 'USD', 0, false)
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


