--
-- Name: expire_loyalty_points(uuid, numeric, public.currency_code, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expire_loyalty_points(p_customer_id uuid, p_points numeric, p_currency public.currency_code DEFAULT 'USD'::public.currency_code, p_exchange_rate numeric DEFAULT 1, p_reason text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_money NUMERIC;
  v_rate NUMERIC;
  v_journal UUID;
  v_ledger UUID;
BEGIN
  PERFORM public._require_loyalty_staff();
  PERFORM public._loyalty_rpc_enter();

  IF p_points IS NULL OR p_points <= 0 THEN
    RAISE EXCEPTION 'expire points must be > 0';
  END IF;
  IF p_currency = 'ZIG' AND (p_exchange_rate IS NULL OR p_exchange_rate <= 0) THEN
    RAISE EXCEPTION 'exchange_rate_applied required for ZIG';
  END IF;

  v_rate := CASE
    WHEN p_currency = 'USD' THEN COALESCE(p_exchange_rate, 1)
    ELSE p_exchange_rate
  END;
  v_money := public._loyalty_money_value(p_points);

  -- Release liability back to income (contra expense / break-age)
  -- Use 5350 credit (reduce prior expense) when points expire unused.
  IF v_money > 0 THEN
    v_journal := public.post_journal_entry(
      CURRENT_DATE,
      COALESCE(p_reason, format('Loyalty expire %s pts', p_points)),
      p_currency,
      v_rate,
      jsonb_build_array(
        jsonb_build_object(
          'account_code', '2210',
          'debit', v_money, 'credit', 0, 'currency', p_currency
        ),
        jsonb_build_object(
          'account_code', '5350',
          'debit', 0, 'credit', v_money, 'currency', p_currency
        )
      )
    );
  END IF;

  v_ledger := public._append_loyalty(
    p_customer_id, 'expire', p_points, p_currency, v_rate, v_money,
    NULL, v_journal,
    COALESCE(p_reason, format('Loyalty expire %s pts', p_points))
  );

  RETURN v_ledger;
END;
$$;


--
-- Name: export_payslip(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.export_payslip(p_payroll_line_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_line public.payroll_lines%ROWTYPE;
  v_run public.payroll_runs%ROWTYPE;
  v_id UUID;
  v_path TEXT;
  v_is_hr BOOLEAN;
  v_self UUID;
BEGIN
  PERFORM public._payroll_begin_rpc();

  SELECT * INTO v_line FROM public.payroll_lines WHERE id = p_payroll_line_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'payroll line not found: %', p_payroll_line_id;
  END IF;

  SELECT * INTO v_run FROM public.payroll_runs WHERE id = v_line.payroll_run_id;
  IF v_run.status NOT IN ('submitted', 'cancelled') THEN
    RAISE EXCEPTION 'payslip export requires submitted (or cancelled) payroll run';
  END IF;

  v_is_hr := (
    auth.role() = 'service_role'
    OR public.has_staff_role(ARRAY['admin', 'hr']::public.staff_role[])
  );
  v_self := public.current_employee_id();
  IF NOT v_is_hr AND (v_self IS NULL OR v_self IS DISTINCT FROM v_line.employee_id) THEN
    RAISE EXCEPTION 'admin/hr or own payslip only';
  END IF;

  SELECT id INTO v_id FROM public.payslips WHERE payroll_line_id = p_payroll_line_id;
  IF v_id IS NOT NULL THEN
    RETURN v_id;
  END IF;

  v_path := format('%s/%s.pdf', v_run.id, v_line.employee_id);

  INSERT INTO public.payslips (
    payroll_line_id, payroll_run_id, employee_id,
    storage_bucket, storage_path, mime_type, generated_by
  )
  VALUES (
    p_payroll_line_id, v_run.id, v_line.employee_id,
    'payslips', v_path, 'application/pdf', auth.uid()
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


--
-- Name: fail_delivery_job(uuid, public.delivery_failure_reason, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fail_delivery_job(p_delivery_job_id uuid, p_reason public.delivery_failure_reason, p_notes text DEFAULT NULL::text, p_create_reattempt boolean DEFAULT false) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_job public.delivery_jobs%ROWTYPE;
  v_uid UUID := auth.uid();
  v_allowed BOOLEAN := false;
  v_child UUID;
  v_notes TEXT;
BEGIN
  PERFORM public._logistics_begin_rpc();

  IF p_reason IS NULL THEN
    RAISE EXCEPTION 'failure reason required';
  END IF;

  SELECT * INTO v_job FROM public.delivery_jobs WHERE id = p_delivery_job_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'delivery job not found';
  END IF;
  IF v_job.status IN ('completed', 'failed') THEN
    RAISE EXCEPTION 'terminal delivery job cannot fail again (status=%)', v_job.status;
  END IF;

  IF auth.role() = 'service_role'
     OR public.has_staff_role(
       ARRAY['admin', 'warehouse', 'dispatcher']::public.staff_role[]
     ) THEN
    v_allowed := true;
  ELSIF v_uid IS NOT NULL
        AND v_job.assignee_user_id = v_uid
        AND public.has_staff_role(ARRAY['driver']::public.staff_role[]) THEN
    v_allowed := true;
  END IF;

  IF NOT v_allowed THEN
    RAISE EXCEPTION 'assigned driver or dispatcher/warehouse/admin required to fail job';
  END IF;

  v_notes := COALESCE(NULLIF(trim(p_notes), ''), v_job.notes);

  UPDATE public.delivery_jobs
  SET
    status = 'failed',
    failed_at = now(),
    failure_reason_code = p_reason,
    failure_reason = p_reason::text || CASE
      WHEN p_notes IS NOT NULL AND length(trim(p_notes)) > 0 THEN ': ' || trim(p_notes)
      ELSE ''
    END,
    notes = v_notes,
    updated_at = now()
  WHERE id = p_delivery_job_id;

  UPDATE public.delivery_track_tokens
  SET revoked_at = COALESCE(revoked_at, now())
  WHERE delivery_job_id = p_delivery_job_id
    AND revoked_at IS NULL;

  PERFORM public.emit_domain_event(
    'delivery_failed',
    'delivery_job:failed:' || p_delivery_job_id::text,
    jsonb_build_object(
      'delivery_job_id', p_delivery_job_id,
      'delivery_note_id', v_job.delivery_note_id,
      'status', 'failed',
      'failure_reason_code', p_reason::text
    )
  );

  IF COALESCE(p_create_reattempt, false) THEN
    INSERT INTO public.delivery_jobs (
      document_number,
      delivery_note_id,
      assignee_user_id,
      status,
      notes,
      created_by,
      pickup_lat,
      pickup_lng,
      dropoff_lat,
      dropoff_lng,
      reattempt_of
    )
    VALUES (
      public.next_series_value('DJ-'),
      v_job.delivery_note_id,
      NULL,
      'pending',
      'Reattempt of ' || COALESCE(v_job.document_number, p_delivery_job_id::text),
      auth.uid(),
      v_job.pickup_lat,
      v_job.pickup_lng,
      v_job.dropoff_lat,
      v_job.dropoff_lng,
      p_delivery_job_id
    )
    RETURNING id INTO v_child;

    RETURN v_child;
  END IF;

  RETURN p_delivery_job_id;
END;
$$;


--
-- Name: fail_pos_split_refund(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fail_pos_split_refund(p_refund_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE r public.pos_split_refund_requests%ROWTYPE;
BEGIN
 IF NOT (public.is_pos_approver() OR public.has_staff_role(ARRAY['finance']::public.staff_role[])) THEN RAISE EXCEPTION 'manager or finance approval required'; END IF;
 SELECT * INTO r FROM public.pos_split_refund_requests WHERE id=p_refund_id FOR UPDATE; IF NOT FOUND OR r.status='settled' THEN RAISE EXCEPTION 'unsettled refund request required'; END IF;
 UPDATE public.pos_split_refund_requests SET status='failed',failure_reason=left(COALESCE(p_reason,'refund failed'),500),updated_at=now() WHERE id=r.id;
 UPDATE public.pos_split_payment_legs SET status='refund_review',status_detail=left(COALESCE(p_reason,'refund failed'),500),updated_at=now() WHERE id=r.leg_id;
 UPDATE public.pos_split_payment_sessions SET status='refund_review',updated_at=now() WHERE id=r.session_id;
 RETURN private.pos_split_payment_payload(r.session_id);
END $$;


--
-- Name: finalize_ai_promo_run(uuid, public.ai_promo_run_status, integer, integer, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalize_ai_promo_run(p_run_id uuid, p_status public.ai_promo_run_status, p_candidates integer, p_queued integer, p_gemini_used boolean, p_error text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'service_role required';
  END IF;
  UPDATE public.ai_promo_runs
  SET
    status = p_status,
    candidates_considered = COALESCE(p_candidates, 0),
    messages_queued = COALESCE(p_queued, 0),
    gemini_used = COALESCE(p_gemini_used, false),
    error = p_error,
    finished_at = now()
  WHERE id = p_run_id;
END;
$$;


--
-- Name: finalize_ai_report_run(uuid, public.ai_report_run_status, jsonb, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalize_ai_report_run(p_run_id uuid, p_status public.ai_report_run_status, p_kpi_json jsonb DEFAULT NULL::jsonb, p_narrative text DEFAULT NULL::text, p_error text DEFAULT NULL::text, p_gemini_used boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_sub UUID;
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'service_role required';
  END IF;

  UPDATE public.ai_report_runs
  SET
    status = p_status,
    kpi_json = COALESCE(p_kpi_json, kpi_json),
    narrative = p_narrative,
    error = p_error,
    gemini_used = COALESCE(p_gemini_used, false),
    finished_at = now()
  WHERE id = p_run_id
  RETURNING subscription_id INTO v_sub;

  IF v_sub IS NOT NULL AND p_status IN ('succeeded', 'partial') THEN
    UPDATE public.ai_report_subscriptions
    SET last_run_at = now(), updated_at = now()
    WHERE id = v_sub;
  END IF;
END;
$$;


--
-- Name: finalize_delivery_card_terminal_payment(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalize_delivery_card_terminal_payment(p_attempt_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE a public.pos_card_terminal_attempts%ROWTYPE;j public.delivery_jobs%ROWTYPE;i public.sales_invoices%ROWTYPE;v_due NUMERIC;v_pe UUID;
BEGIN
 SELECT * INTO a FROM public.pos_card_terminal_attempts WHERE id=p_attempt_id FOR UPDATE;
 IF NOT FOUND OR a.operation<>'purchase' OR a.delivery_job_id IS NULL OR a.source_invoice_id IS NULL OR a.status<>'approved' THEN RAISE EXCEPTION 'approved delivery card purchase required'; END IF;
 IF a.created_by IS DISTINCT FROM auth.uid() OR NOT public.has_staff_role(ARRAY['driver']::public.staff_role[]) THEN RAISE EXCEPTION 'delivery card payment belongs to another driver'; END IF;
 SELECT * INTO j FROM public.delivery_jobs WHERE id=a.delivery_job_id FOR UPDATE; IF j.assignee_user_id IS DISTINCT FROM auth.uid() OR j.status<>'dispatched' THEN RAISE EXCEPTION 'assigned dispatched delivery required'; END IF;
 SELECT * INTO i FROM public.sales_invoices WHERE id=a.source_invoice_id FOR UPDATE; v_due:=greatest(round(i.total-i.amount_paid,2),0);
 IF a.amount>v_due+0.01 THEN RAISE EXCEPTION 'approved terminal amount exceeds current invoice balance'; END IF;
 PERFORM set_config('app.delivery_payment_rpc','1',true);
 v_pe:=public.create_payment_entry(i.customer_id,'card_terminal',a.amount,i.currency,i.exchange_rate_applied,
  format('Card on delivery %s · txn %s',COALESCE(i.document_number,i.id::text),a.terminal_transaction_id));
 PERFORM public.allocate_payment(v_pe,jsonb_build_array(jsonb_build_object('sales_invoice_id',i.id,'amount',a.amount)));
 PERFORM public.post_payment_entry(v_pe); PERFORM set_config('app.delivery_payment_rpc','',true);
 UPDATE public.pos_card_terminal_attempts SET status='settled',payment_entry_id=v_pe,invoice_id=i.id,finalization_error=NULL,finalized_by=auth.uid(),finalized_at=now(),updated_at=now() WHERE id=a.id;
 RETURN private.pos_card_terminal_attempt_payload(a.id);
EXCEPTION WHEN OTHERS THEN PERFORM set_config('app.delivery_payment_rpc','',true); RAISE;
END $$;


--
-- Name: finalize_pos_account_credit_order(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalize_pos_account_credit_order(p_order_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE o public.commerce_orders%ROWTYPE; v_inv UUID; v_customer_name TEXT;
BEGIN
 PERFORM public._require_sales_staff();
 SELECT * INTO o FROM public.commerce_orders WHERE id=p_order_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'commerce order not found'; END IF;
 IF o.settled_payment_entry_id IS NOT NULL THEN RAISE EXCEPTION 'order already has payment settlement'; END IF;
 SELECT display_name INTO v_customer_name FROM public.customers WHERE id=o.customer_id;
 IF v_customer_name='POS Walk-in' THEN RAISE EXCEPTION 'walk-in customer cannot use account credit'; END IF;
 IF o.reservation_expires_at IS NULL OR o.reservation_expires_at<=now() THEN RAISE EXCEPTION 'commerce reservation expired'; END IF;
 IF o.state NOT IN('awaiting_payment','payment_failed') THEN RAISE EXCEPTION 'account credit cannot finalize order in state %',o.state; END IF;
 v_inv:=private.finalize_commerce_order(o.id);
 UPDATE public.commerce_orders
 SET state='account_invoiced',settled_provider=NULL,settled_provider_ref=NULL,payment_exception=NULL,updated_at=now()
 WHERE id=o.id;
 PERFORM private.enqueue_commerce_event('commerce:'||o.id::text||':account-invoiced',
  'commerce.account_invoiced',o.id,jsonb_build_object('sales_invoice_id',v_inv,'customer_id',o.customer_id));
 RETURN v_inv;
END $$;


--
-- Name: finalize_pos_card_terminal_purchase(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalize_pos_card_terminal_purchase(p_attempt_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE a public.pos_card_terminal_attempts%ROWTYPE; v_pe UUID; v_inv UUID;
BEGIN
 SELECT * INTO a FROM public.pos_card_terminal_attempts WHERE id=p_attempt_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'card terminal attempt not found'; END IF;
 IF a.split_leg_id IS NULL THEN RETURN public.finalize_pos_card_terminal_purchase_full_legacy(p_attempt_id); END IF;
 PERFORM public._require_payments_staff();
 IF a.created_by<>auth.uid() AND NOT public.is_pos_approver() AND NOT public.has_staff_role(ARRAY['finance']::public.staff_role[]) THEN RAISE EXCEPTION 'card terminal attempt access denied'; END IF;
 IF a.status='settled' THEN RETURN private.pos_card_terminal_attempt_payload(a.id); END IF;
 IF a.status<>'approved' THEN RAISE EXCEPTION 'terminal approval required before split capture'; END IF;
 v_pe:=private.capture_pos_split_external_leg(a.split_leg_id,'card_terminal',a.id,a.terminal_transaction_id,a.amount,a.currency,1,NULL,NULL,NULL);
 SELECT final_invoice_id INTO v_inv FROM public.pos_split_payment_sessions s JOIN public.pos_split_payment_legs l ON l.session_id=s.id WHERE l.id=a.split_leg_id;
 UPDATE public.pos_card_terminal_attempts SET status='settled',payment_entry_id=v_pe,invoice_id=v_inv,finalization_error=NULL,
  finalized_by=auth.uid(),finalized_at=now(),updated_at=now() WHERE id=a.id;
 RETURN private.pos_card_terminal_attempt_payload(a.id);
END $$;


--
-- Name: finalize_pos_card_terminal_purchase_full_legacy(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalize_pos_card_terminal_purchase_full_legacy(p_attempt_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE a public.pos_card_terminal_attempts%ROWTYPE; o public.commerce_orders%ROWTYPE; v_inv UUID; v_pe UUID; v_error TEXT;
BEGIN
 PERFORM public._require_payments_staff(); SELECT * INTO a FROM public.pos_card_terminal_attempts WHERE id=p_attempt_id FOR UPDATE;
 IF NOT FOUND OR a.operation<>'purchase' THEN RAISE EXCEPTION 'purchase card terminal attempt required'; END IF;
 IF a.created_by<>auth.uid() AND NOT public.is_pos_approver() AND NOT public.has_staff_role(ARRAY['finance']::public.staff_role[]) THEN RAISE EXCEPTION 'card terminal attempt access denied'; END IF;
 IF a.status='settled' THEN RETURN private.pos_card_terminal_attempt_payload(a.id); END IF;
 IF a.status<>'approved' THEN RAISE EXCEPTION 'terminal approval required before finalization'; END IF;
 SELECT * INTO o FROM public.commerce_orders WHERE id=a.commerce_order_id FOR UPDATE;
 IF NOT FOUND OR o.settled_payment_entry_id IS NOT NULL OR o.sales_invoice_id IS NOT NULL THEN RAISE EXCEPTION 'order is already finalized by another settlement'; END IF;
 IF abs(o.total-a.amount)>0.01 OR o.currency<>a.currency THEN RAISE EXCEPTION 'terminal approval does not match reserved order amount/currency'; END IF;
 BEGIN
  v_inv:=private.finalize_commerce_order(o.id);
  v_pe:=public.create_payment_entry(o.customer_id,'card_terminal',a.amount,a.currency,o.exchange_rate_applied,
   format('Card terminal %s · txn %s',a.external_ref,a.terminal_transaction_id));
  PERFORM public.allocate_payment(v_pe,jsonb_build_array(jsonb_build_object('sales_invoice_id',v_inv,'amount',a.amount)));
  PERFORM public.post_payment_entry(v_pe);
  UPDATE public.pos_card_terminal_attempts SET status='settled',payment_entry_id=v_pe,invoice_id=v_inv,finalization_error=NULL,
   finalized_by=auth.uid(),finalized_at=now(),updated_at=now() WHERE id=a.id;
  UPDATE public.commerce_orders SET settled_payment_entry_id=v_pe,settled_provider='card_terminal',settled_provider_ref=a.terminal_transaction_id,
   active_payment_provider=NULL,active_payment_intent_id=NULL,payment_exception=NULL,
   state=CASE WHEN fulfillment_mode='dispatch' THEN 'allocation_pending'::public.commerce_order_state ELSE 'paid'::public.commerce_order_state END,
   updated_at=now() WHERE id=o.id;
  PERFORM private.enqueue_commerce_event('commerce:'||o.id::text||':card-terminal-settled:'||a.id::text,
   'commerce.payment_settled',o.id,jsonb_build_object('provider','card_terminal','attempt_id',a.id,'payment_entry_id',v_pe,'sales_invoice_id',v_inv,'terminal_transaction_id',a.terminal_transaction_id));
 EXCEPTION WHEN OTHERS THEN
  v_error:=SQLERRM;
  UPDATE public.pos_card_terminal_attempts SET finalization_error=left(v_error,500),updated_at=now() WHERE id=a.id;
  UPDATE public.commerce_orders SET state='payment_processing',active_payment_provider='card_terminal',active_payment_intent_id=a.id,
   payment_exception='CARD_TERMINAL_APPROVED_NOT_FINALIZED',updated_at=now() WHERE id=o.id;
  RETURN jsonb_build_object('attempt_id',a.id,'order_id',o.id,'status','recovery_required','error',left(v_error,500));
 END;
 RETURN private.pos_card_terminal_attempt_payload(a.id);
END $$;


--
-- Name: finalize_pos_card_terminal_refund(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalize_pos_card_terminal_refund(p_attempt_id uuid, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE a public.pos_card_terminal_attempts%ROWTYPE; v_refund UUID; v_error TEXT; v_lines jsonb;
BEGIN
 IF NOT (public.is_pos_approver() OR public.has_staff_role(ARRAY['finance']::public.staff_role[])) THEN RAISE EXCEPTION 'POS manager or finance approval required'; END IF;
 SELECT * INTO a FROM public.pos_card_terminal_attempts WHERE id=p_attempt_id FOR UPDATE;
 IF NOT FOUND OR a.operation<>'refund' THEN RAISE EXCEPTION 'card terminal refund attempt required'; END IF;
 IF a.status='settled' THEN RETURN private.pos_card_terminal_attempt_payload(a.id); END IF;
 IF a.status<>'approved' THEN RAISE EXCEPTION 'terminal refund approval required before finance finalization'; END IF;
 BEGIN
  -- The machine paid the customer back: every line not yet returned comes back on a credit note
  -- (parts to quarantine), and the money side credits card clearing (Dr 4110 / Cr 1170).
  -- post_finance_refund (direct refund posting) is disabled, so finalising always failed before.
  SELECT jsonb_agg(jsonb_build_object('source_invoice_line_id',l.id,'qty',l.qty)) INTO v_lines
    FROM public.sales_invoice_lines l WHERE l.invoice_id=a.source_invoice_id AND NOT COALESCE(l.is_core_charge,false) AND l.qty>0;
  PERFORM public._sales_checkout_accounting_enter();
  v_refund:=private._post_pos_credit_note(a.source_invoice_id,v_lines,'1170',
    concat_ws(' · ','Card refund '||COALESCE(a.terminal_transaction_id,a.external_ref),p_notes));
  PERFORM public._sales_checkout_accounting_exit();
  IF abs((SELECT total FROM public.sales_invoices WHERE id=v_refund)-a.amount)>0.01 THEN
   RAISE EXCEPTION 'credit note % does not match the % refunded on the card',(SELECT total FROM public.sales_invoices WHERE id=v_refund),a.amount;
  END IF;
  UPDATE public.pos_card_terminal_attempts SET status='settled',credit_note_id=v_refund,finalization_error=NULL,
   finalized_by=auth.uid(),finalized_at=now(),updated_at=now() WHERE id=a.id;
 EXCEPTION WHEN OTHERS THEN
  v_error:=SQLERRM;
  PERFORM public._sales_checkout_accounting_exit();
  UPDATE public.pos_card_terminal_attempts SET finalization_error=left(v_error,500),updated_at=now() WHERE id=a.id;
  RETURN jsonb_build_object('attempt_id',a.id,'invoice_id',a.source_invoice_id,'status','recovery_required','error',left(v_error,500));
 END;
 RETURN private.pos_card_terminal_attempt_payload(a.id);
END $$;


--
-- Name: finalize_pos_card_terminal_split_refund(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalize_pos_card_terminal_split_refund(p_attempt_id uuid, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE a public.pos_card_terminal_attempts%ROWTYPE; r public.pos_split_refund_requests%ROWTYPE; v_payload JSONB;
BEGIN
 IF NOT (public.is_pos_approver() OR public.has_staff_role(ARRAY['finance']::public.staff_role[])) THEN RAISE EXCEPTION 'manager or finance approval required'; END IF;
 SELECT * INTO a FROM public.pos_card_terminal_attempts WHERE id=p_attempt_id FOR UPDATE;
 IF NOT FOUND OR a.operation<>'refund' OR a.split_refund_request_id IS NULL OR a.status<>'approved' THEN RAISE EXCEPTION 'approved split card-terminal refund attempt required'; END IF;
 SELECT * INTO r FROM public.pos_split_refund_requests WHERE id=a.split_refund_request_id;
 v_payload:=public.complete_pos_split_refund(r.id,a.terminal_transaction_id,r.estimated_provider_fee,r.estimated_transfer_fee,r.approved_customer_fee,p_notes);
 UPDATE public.pos_card_terminal_attempts SET status='settled',finalized_by=auth.uid(),finalized_at=now(),updated_at=now() WHERE id=a.id;
 RETURN v_payload;
END $$;


