--
-- Name: forbid_loyalty_ledger_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.forbid_loyalty_ledger_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'loyalty_ledger is append-only';
  END IF;

  IF TG_OP = 'UPDATE' THEN
    IF NEW.document_number IS NOT DISTINCT FROM OLD.document_number
      AND NEW.account_id IS NOT DISTINCT FROM OLD.account_id
      AND NEW.customer_id IS NOT DISTINCT FROM OLD.customer_id
      AND NEW.movement IS NOT DISTINCT FROM OLD.movement
      AND NEW.points IS NOT DISTINCT FROM OLD.points
      AND NEW.money_value IS NOT DISTINCT FROM OLD.money_value
      AND NEW.currency IS NOT DISTINCT FROM OLD.currency
      AND NEW.exchange_rate_applied IS NOT DISTINCT FROM OLD.exchange_rate_applied
      AND NEW.points_balance_after IS NOT DISTINCT FROM OLD.points_balance_after
      AND NEW.sales_invoice_id IS NOT DISTINCT FROM OLD.sales_invoice_id
      AND NEW.journal_entry_id IS NOT DISTINCT FROM OLD.journal_entry_id
      AND NEW.reverses_ledger_id IS NOT DISTINCT FROM OLD.reverses_ledger_id
      AND NEW.reason IS NOT DISTINCT FROM OLD.reason
      AND NEW.created_by IS NOT DISTINCT FROM OLD.created_by
      AND NEW.created_at IS NOT DISTINCT FROM OLD.created_at
      AND (
        OLD.money_value_minor IS NULL
        OR NEW.money_value_minor IS NOT DISTINCT FROM OLD.money_value_minor
      )
    THEN
      RETURN NEW;
    END IF;
    RAISE EXCEPTION 'loyalty_ledger is append-only';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: forbid_posted_journal_line_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.forbid_posted_journal_line_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_status public.journal_status;
  v_entry_id UUID;
BEGIN
  v_entry_id := COALESCE(NEW.journal_entry_id, OLD.journal_entry_id);
  SELECT status INTO v_status FROM public.journal_entries WHERE id = v_entry_id;
  IF v_status = 'posted' THEN
    RAISE EXCEPTION 'Posted journal lines are immutable. Use reverse_journal.';
  END IF;
  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: forbid_posted_journal_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.forbid_posted_journal_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  IF OLD.status = 'posted' THEN
    RAISE EXCEPTION 'Posted journal entries are immutable. Use reverse_journal.';
  END IF;
  IF NEW.status = 'posted' AND OLD.status = 'draft' THEN
    -- Allow post_journal (SECURITY DEFINER) to flip status
    RETURN NEW;
  END IF;
  IF NEW.status IS DISTINCT FROM OLD.status AND NEW.status = 'draft' THEN
    RAISE EXCEPTION 'Cannot un-post a journal entry';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: forbid_store_credit_ledger_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.forbid_store_credit_ledger_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'store_credit_ledger is append-only';
  END IF;

  IF TG_OP = 'UPDATE' THEN
    IF NEW.document_number IS NOT DISTINCT FROM OLD.document_number
      AND NEW.account_id IS NOT DISTINCT FROM OLD.account_id
      AND NEW.customer_id IS NOT DISTINCT FROM OLD.customer_id
      AND NEW.movement IS NOT DISTINCT FROM OLD.movement
      AND NEW.amount IS NOT DISTINCT FROM OLD.amount
      AND NEW.currency IS NOT DISTINCT FROM OLD.currency
      AND NEW.exchange_rate_applied IS NOT DISTINCT FROM OLD.exchange_rate_applied
      AND NEW.balance_after IS NOT DISTINCT FROM OLD.balance_after
      AND NEW.payment_entry_id IS NOT DISTINCT FROM OLD.payment_entry_id
      AND NEW.journal_entry_id IS NOT DISTINCT FROM OLD.journal_entry_id
      AND NEW.reverses_ledger_id IS NOT DISTINCT FROM OLD.reverses_ledger_id
      AND NEW.reason IS NOT DISTINCT FROM OLD.reason
      AND NEW.created_by IS NOT DISTINCT FROM OLD.created_by
      AND NEW.created_at IS NOT DISTINCT FROM OLD.created_at
      AND (OLD.amount_minor IS NULL OR NEW.amount_minor IS NOT DISTINCT FROM OLD.amount_minor)
      AND (
        OLD.balance_after_minor IS NULL
        OR NEW.balance_after_minor IS NOT DISTINCT FROM OLD.balance_after_minor
      )
    THEN
      RETURN NEW;
    END IF;
    RAISE EXCEPTION 'store_credit_ledger is append-only';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: fund_payroll_run(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fund_payroll_run(p_payroll_run_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_run public.payroll_runs%ROWTYPE;
  v_existing public.payroll_run_funding%ROWTYPE;
  v_journal UUID;
  v_payslip_ids UUID[] := ARRAY[]::UUID[];
  v_ps UUID;
  v_line RECORD;
  v_lines JSONB;
BEGIN
  IF NOT (
    auth.role() = 'service_role'
    OR public.has_staff_role(ARRAY['admin','finance']::public.staff_role[])
  ) THEN RAISE EXCEPTION 'finance or admin role required'; END IF;

  SELECT * INTO v_run FROM public.payroll_runs WHERE id = p_payroll_run_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'payroll run not found: %', p_payroll_run_id; END IF;
  IF v_run.status <> 'submitted' THEN RAISE EXCEPTION 'submitted payroll run required'; END IF;

  SELECT * INTO v_existing FROM public.payroll_run_funding WHERE payroll_run_id = p_payroll_run_id;
  IF FOUND THEN
    SELECT COALESCE(array_agg(id ORDER BY id), ARRAY[]::UUID[]) INTO v_payslip_ids
    FROM public.payslips WHERE payroll_run_id = p_payroll_run_id;
    RETURN jsonb_build_object(
      'payroll_run_id', p_payroll_run_id,
      'journal_entry_id', v_existing.journal_entry_id,
      'payslip_ids', to_jsonb(v_payslip_ids),
      'funded_count', cardinality(v_payslip_ids),
      'already_funded', true
    );
  END IF;

  IF v_run.total_gross <= 0 OR v_run.total_net < 0 THEN
    RAISE EXCEPTION 'invalid payroll totals for funding';
  END IF;

  v_lines := jsonb_build_array(
    jsonb_build_object('account_code','5200','debit',v_run.total_gross,'credit',0,'currency',v_run.currency),
    jsonb_build_object('account_code','1100','debit',0,'credit',v_run.total_net,'currency',v_run.currency)
  );
  IF v_run.total_deductions > 0 THEN
    v_lines := v_lines || jsonb_build_array(
      jsonb_build_object('account_code','2150','debit',0,'credit',v_run.total_deductions,'currency',v_run.currency)
    );
  END IF;

  v_journal := public.post_journal_entry(
    COALESCE(v_run.submitted_at::date, CURRENT_DATE),
    format('Payroll funded %s', COALESCE(v_run.document_number, v_run.id::text)),
    v_run.currency,
    v_run.exchange_rate,
    v_lines
  );

  PERFORM public._payroll_begin_rpc();
  FOR v_line IN SELECT id, employee_id FROM public.payroll_lines WHERE payroll_run_id = p_payroll_run_id ORDER BY line_no
  LOOP
    INSERT INTO public.payslips(payroll_line_id,payroll_run_id,employee_id,storage_bucket,storage_path,mime_type,generated_by)
    VALUES(v_line.id,p_payroll_run_id,v_line.employee_id,'payslips',format('%s/%s.pdf',p_payroll_run_id,v_line.employee_id),'application/pdf',auth.uid())
    ON CONFLICT (payroll_line_id) DO UPDATE SET storage_bucket=EXCLUDED.storage_bucket, storage_path=EXCLUDED.storage_path, mime_type=EXCLUDED.mime_type
    RETURNING id INTO v_ps;
    v_payslip_ids := array_append(v_payslip_ids, v_ps);
  END LOOP;

  INSERT INTO public.payroll_run_funding(payroll_run_id,journal_entry_id,funded_by)
  VALUES(p_payroll_run_id,v_journal,auth.uid());

  RETURN jsonb_build_object(
    'payroll_run_id', p_payroll_run_id,
    'journal_entry_id', v_journal,
    'payslip_ids', to_jsonb(v_payslip_ids),
    'funded_count', cardinality(v_payslip_ids),
    'already_funded', false
  );
END;
$$;


--
-- Name: generate_delivery_pod_otp(uuid, interval); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_delivery_pod_otp(p_delivery_job_id uuid, p_ttl interval DEFAULT '00:15:00'::interval) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_job public.delivery_jobs%ROWTYPE;
  v_uid UUID := auth.uid();
  v_allowed BOOLEAN := false;
  v_code TEXT;
  v_hash TEXT;
  v_bytes BYTEA;
  v_n BIGINT;
BEGIN
  PERFORM public._logistics_begin_rpc();

  SELECT * INTO v_job FROM public.delivery_jobs WHERE id = p_delivery_job_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'delivery job not found';
  END IF;
  IF v_job.status <> 'dispatched' THEN
    RAISE EXCEPTION 'POD OTP requires dispatched job (status=%)', v_job.status;
  END IF;

  IF auth.role() = 'service_role'
     OR public.has_staff_role(
       ARRAY['admin', 'warehouse', 'dispatcher']::public.staff_role[]
     ) THEN
    v_allowed := true;
  ELSIF v_uid IS NOT NULL
        AND v_job.assignee_user_id = v_uid
        AND public.has_staff_role(ARRAY['driver']::public.staff_role[]) THEN
    v_allowed := true;
  END IF;

  IF NOT v_allowed THEN
    RAISE EXCEPTION 'assigned driver or dispatcher/warehouse/admin required for POD OTP';
  END IF;

  UPDATE public.delivery_pod_otps
  SET expires_at = least(expires_at, now())
  WHERE delivery_job_id = p_delivery_job_id
    AND verified_at IS NULL
    AND expires_at > now();

  -- Uniform 6-digit code from 4 CSPRNG bytes (not random())
  v_bytes := extensions.gen_random_bytes(4);
  v_n := (
    get_byte(v_bytes, 0)::bigint * 16777216
    + get_byte(v_bytes, 1)::bigint * 65536
    + get_byte(v_bytes, 2)::bigint * 256
    + get_byte(v_bytes, 3)::bigint
  ) % 1000000;
  v_code := lpad(v_n::text, 6, '0');
  v_hash := public._hash_delivery_pod_otp(v_code);

  INSERT INTO public.delivery_pod_otps (
    delivery_job_id, code_hash, expires_at
  )
  VALUES (
    p_delivery_job_id,
    v_hash,
    now() + COALESCE(p_ttl, interval '15 minutes')
  );

  -- Optional SMS to customer â€” never blocks OTP return to driver UI
  PERFORM public._enqueue_delivery_customer_sms(
    p_delivery_job_id,
    'delivery_pod_otp',
    'delivery_pod_otp:' || p_delivery_job_id::text || ':' || v_hash,
    format('GTR Auto: Your delivery confirmation code is %s. Do not share.', v_code)
  );

  -- Kept for the customer's own order page / app (only they can read it), replaced on resend.
  INSERT INTO private.delivery_pod_codes(delivery_job_id, code, expires_at)
  VALUES (p_delivery_job_id, v_code, now() + COALESCE(p_ttl, interval '15 minutes'))
  ON CONFLICT (delivery_job_id) DO UPDATE SET code = EXCLUDED.code, expires_at = EXCLUDED.expires_at, created_at = now();

  -- The code proves the customer received the parts, so the driver never sees it. Back office may
  -- read it out to a customer who has no account or did not get the SMS.
  IF auth.role() = 'service_role'
     OR public.has_staff_role(ARRAY['admin', 'warehouse', 'dispatcher']::public.staff_role[]) THEN
    RETURN v_code;
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: generate_forecast_suggestions(uuid, integer, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_forecast_suggestions(p_warehouse_id uuid, p_horizon_days integer DEFAULT 30, p_default_reorder_qty numeric DEFAULT 10) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row RECORD;
  v_qty NUMERIC;
  v_count INT := 0;
BEGIN
  IF NOT (
    auth.role() = 'service_role'
    OR public.has_staff_role(ARRAY['admin', 'warehouse', 'finance']::public.staff_role[])
  ) THEN
    RAISE EXCEPTION 'warehouse/finance/admin role required';
  END IF;

  IF p_warehouse_id IS NULL THEN
    RAISE EXCEPTION 'warehouse_id required';
  END IF;

  FOR v_row IN
    SELECT
      si.id AS stock_item_id,
      si.base_uom_id,
      si.reorder_point,
      si.reorder_qty,
      COALESCE(sl.quantity, 0) AS on_hand
    FROM public.stock_items si
    LEFT JOIN public.stock_levels sl
      ON sl.stock_item_id = si.id AND sl.warehouse_id = p_warehouse_id
    WHERE si.reorder_point IS NOT NULL
      AND COALESCE(sl.quantity, 0) <= si.reorder_point
  LOOP
    v_qty := COALESCE(v_row.reorder_qty, p_default_reorder_qty);
    IF v_qty IS NULL OR v_qty <= 0 THEN
      v_qty := GREATEST(p_default_reorder_qty, 1);
    END IF;

    INSERT INTO public.forecast_suggestions (
      warehouse_id, stock_item_id, suggested_qty, horizon_days, on_hand, reason
    )
    VALUES (
      p_warehouse_id,
      v_row.stock_item_id,
      v_qty,
      GREATEST(COALESCE(p_horizon_days, 30), 1),
      v_row.on_hand,
      jsonb_build_object(
        'rule', 'reorder_point',
        'reorder_point', v_row.reorder_point,
        'on_hand', v_row.on_hand
      )
    )
    ON CONFLICT (warehouse_id, stock_item_id) WHERE status = 'open'
    DO UPDATE SET
      suggested_qty = EXCLUDED.suggested_qty,
      horizon_days = EXCLUDED.horizon_days,
      on_hand = EXCLUDED.on_hand,
      reason = EXCLUDED.reason,
      created_at = now();

    v_count := v_count + 1;
  END LOOP;

  RETURN v_count;
END;
$$;


--
-- Name: get_business_document_profile(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_business_document_profile() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF NOT (auth.role() = 'service_role' OR public.is_staff()) THEN RAISE EXCEPTION 'staff role required'; END IF;
  RETURN (SELECT to_jsonb(b) - 'updated_by' FROM public.business_document_profile b WHERE b.singleton);
END $$;


--
-- Name: get_catalog_diagram(text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_catalog_diagram(p_maker_slug text, p_model_slug text, p_variant_slug text, p_section_slug text) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_diagram catalog_diagrams%ROWTYPE;
  v_parts jsonb := '[]'::jsonb;
  v_companion jsonb := '[]'::jsonb;
BEGIN
  SELECT * INTO v_diagram
  FROM catalog_diagrams
  WHERE maker_slug = p_maker_slug
    AND model_slug = p_model_slug
    AND variant_slug = p_variant_slug
    AND section_slug = p_section_slug
  ORDER BY slug
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'diagram', null,
      'hotspots', '[]'::jsonb,
      'parts', '[]'::jsonb,
      'companion_parts', '[]'::jsonb
    );
  END IF;

  SELECT COALESCE(jsonb_agg(row_to_json(t)::jsonb ORDER BY t.oem_part_number), '[]'::jsonb)
  INTO v_parts
  FROM (
    SELECT
      pf.oem_part_number,
      pf.pnc_code,
      pf.chassis_code,
      pf.engine_code,
      pf.bbox_x,
      pf.bbox_y,
      pf.bbox_width,
      pf.bbox_height,
      pf.diagram_path,
      pc.category_name,
      pc.subcategory_name,
      pc.pcdb_part_type_id,
      si.id AS stock_item_id,
      si.description AS stock_description
    FROM part_fitment pf
    LEFT JOIN pnc_categories pc ON pc.pnc_code = pf.pnc_code
    LEFT JOIN stock_items si ON si.oem_part_number = pf.oem_part_number
    WHERE pf.diagram_path = v_diagram.storage_path
    LIMIT 500
  ) t;

  SELECT COALESCE(jsonb_agg(row_to_json(c)::jsonb ORDER BY c.callout_ref, c.oem_part_number), '[]'::jsonb)
  INTO v_companion
  FROM (
    SELECT
      itemslist_id,
      callout_ref,
      oem_part_number,
      description,
      quantity,
      external_item_id,
      bbox_x,
      bbox_y,
      bbox_width,
      bbox_height
    FROM catalog_diagram_parts
    WHERE maker_slug = p_maker_slug
      AND model_slug = p_model_slug
      AND variant_slug = p_variant_slug
      AND section_slug = p_section_slug
    LIMIT 500
  ) c;

  RETURN jsonb_build_object(
    'diagram', jsonb_build_object(
      'slug', v_diagram.slug,
      'title', v_diagram.title,
      'storage_path', v_diagram.storage_path,
      'image_url', v_diagram.image_url,
      'width', v_diagram.image_width,
      'height', v_diagram.image_height,
      'diagram_kind', v_diagram.diagram_kind,
      'hotspot_count', v_diagram.hotspot_count
    ),
    'hotspots', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'oem', pf.oem_part_number,
        'pnc_code', pf.pnc_code,
        'itemslist_id', cp.itemslist_id,
        'callout_ref', cp.callout_ref,
        'bbox_x', pf.bbox_x,
        'bbox_y', pf.bbox_y,
        'bbox_width', pf.bbox_width,
        'bbox_height', pf.bbox_height
      ) ORDER BY pf.oem_part_number), '[]'::jsonb)
      FROM part_fitment pf
      LEFT JOIN catalog_diagram_parts cp
        ON cp.diagram_path = pf.diagram_path
        AND cp.oem_part_number = pf.oem_part_number
      WHERE pf.diagram_path = v_diagram.storage_path
        AND pf.bbox_x IS NOT NULL
    ),
    'parts', v_parts,
    'companion_parts', v_companion
  );
END;
$$;


--
-- Name: FUNCTION get_catalog_diagram(p_maker_slug text, p_model_slug text, p_variant_slug text, p_section_slug text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_catalog_diagram(p_maker_slug text, p_model_slug text, p_variant_slug text, p_section_slug text) IS 'Hierarchy-first diagram + hotspots + fitment parts + HTML companion table; joins stock_items when stocked.';


--
-- Name: get_catalog_diagram_by_slug(text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_catalog_diagram_by_slug(p_maker_slug text, p_model_slug text, p_variant_slug text, p_section_slug text, p_diagram_slug text) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_diagram public.catalog_diagrams%ROWTYPE;
  v_parts jsonb := '[]'::jsonb;
BEGIN
  SELECT * INTO v_diagram
  FROM public.catalog_diagrams
  WHERE maker_slug = p_maker_slug
    AND model_slug = p_model_slug
    AND variant_slug = p_variant_slug
    AND section_slug = p_section_slug
    AND slug = p_diagram_slug
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('diagram', null, 'hotspots', '[]'::jsonb, 'parts', '[]'::jsonb);
  END IF;

  SELECT COALESCE(jsonb_agg(row_to_json(t)::jsonb ORDER BY t.oem_part_number), '[]'::jsonb)
  INTO v_parts
  FROM (
    SELECT
      pf.oem_part_number, pf.pnc_code, pf.chassis_code, pf.engine_code,
      pc.category_name, pc.subcategory_name,
      si.id AS stock_item_id, si.description AS stock_description
    FROM public.part_fitment pf
    LEFT JOIN public.pnc_categories pc ON pc.pnc_code = pf.pnc_code
    LEFT JOIN public.stock_items si ON si.oem_part_number = pf.oem_part_number
    WHERE pf.diagram_path = v_diagram.storage_path
    LIMIT 1000
  ) t;

  RETURN jsonb_build_object(
    'diagram', jsonb_build_object(
      'slug', v_diagram.slug,
      'title', v_diagram.title,
      'storage_path', v_diagram.storage_path,
      'image_url', v_diagram.image_url,
      'width', v_diagram.image_width,
      'height', v_diagram.image_height
    ),
    'hotspots', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'oem', pf.oem_part_number,
        'pnc_code', pf.pnc_code,
        'bbox_x', pf.bbox_x, 'bbox_y', pf.bbox_y,
        'bbox_width', pf.bbox_width, 'bbox_height', pf.bbox_height
      ) ORDER BY pf.oem_part_number), '[]'::jsonb)
      FROM public.part_fitment pf
      WHERE pf.diagram_path = v_diagram.storage_path
        AND pf.bbox_x IS NOT NULL
    ),
    'parts', v_parts
  );
END;
$$;


--
-- Name: get_customer_order(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_customer_order(p_invoice_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_inv public.sales_invoices%ROWTYPE;v_dn_status public.delivery_note_status;v_pick_status public.pick_list_status;v_job UUID;
BEGIN
 v_inv:=public._assert_customer_owns_invoice(p_invoice_id);
 SELECT dn.status INTO v_dn_status FROM public.delivery_notes dn WHERE dn.sales_invoice_id=v_inv.id ORDER BY dn.created_at DESC LIMIT 1;
 SELECT pl.status INTO v_pick_status FROM public.pick_lists pl WHERE pl.sales_invoice_id=v_inv.id ORDER BY pl.created_at DESC LIMIT 1;
 SELECT dj.id INTO v_job FROM public.delivery_jobs dj JOIN public.delivery_notes dn ON dn.id=dj.delivery_note_id
  WHERE dn.sales_invoice_id=v_inv.id AND dj.status NOT IN('completed','failed') ORDER BY dj.created_at DESC LIMIT 1;
 RETURN jsonb_build_object('invoice_id',v_inv.id,'document_number',v_inv.document_number,'doc_type',v_inv.doc_type,'status',v_inv.status,
  'fulfillment_mode',v_inv.fulfillment_mode,'delivery_payment_method',v_inv.delivery_payment_method,'currency',v_inv.currency,
  'exchange_rate_applied',v_inv.exchange_rate_applied,'subtotal',v_inv.subtotal,'total',v_inv.total,'amount_paid',v_inv.amount_paid,
  'amount_open',greatest(v_inv.total-v_inv.amount_paid,0),'cart_id',v_inv.cart_id,'posted_at',v_inv.posted_at,
  'pick_list_status',v_pick_status,'delivery_note_status',v_dn_status,'active_delivery_job_id',v_job);
END $$;


--
-- Name: FUNCTION get_customer_order(p_invoice_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_customer_order(p_invoice_id uuid) IS 'Storefront order detail for owning customer. Includes active_delivery_job_id (non-terminal pending|dispatched job on a DN for this invoice; prefers dispatched). No GPS trail or track token. Track via get_delivery_track_point(job_id) as owner.';


--
-- Name: get_customer_suspension(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_customer_suspension(p_customer_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
 IF NOT public.is_staff() THEN RAISE EXCEPTION 'staff required'; END IF;
 RETURN private.customer_suspension_preview(p_customer_id);
END $$;


--
-- Name: get_daily_dashboard(date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_daily_dashboard(p_date date DEFAULT NULL::date, p_warehouse_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
 v_day date := COALESCE(p_date, (now() AT TIME ZONE 'Africa/Harare')::date);
 v_from timestamptz := (v_day::timestamp AT TIME ZONE 'Africa/Harare');
 v_to timestamptz := ((v_day + 1)::timestamp AT TIME ZONE 'Africa/Harare');
 v_lw_from timestamptz := ((v_day - 7)::timestamp AT TIME ZONE 'Africa/Harare');
 v_lw_to timestamptz := ((v_day - 6)::timestamp AT TIME ZONE 'Africa/Harare');
BEGIN
 IF NOT (public.has_staff_role(ARRAY['admin','finance']::public.staff_role[]) OR public.is_pos_approver()) THEN
  RAISE EXCEPTION 'manager, finance or admin required';
 END IF;

 RETURN jsonb_build_object(
  'date', v_day,
  'warehouse_id', p_warehouse_id,
  'warehouse_name', (SELECT w.name FROM public.warehouses w WHERE w.id=p_warehouse_id),
  'generated_at', now(),

  -- Sales (invoices) less returns (credit notes), with gross margin from the cost basis.
  'sales', COALESCE((SELECT jsonb_agg(jsonb_build_object(
     'currency', x.currency, 'invoices', x.n, 'gross', x.gross, 'returns', x.returns, 'net', x.gross - x.returns,
     'cost', x.cost, 'margin', x.gross - x.returns - x.cost,
     'margin_pct', CASE WHEN x.gross - x.returns > 0 THEN round(100 * (x.gross - x.returns - x.cost) / (x.gross - x.returns), 1) END,
     'average_sale', CASE WHEN x.n > 0 THEN round(x.gross / x.n, 2) END,
     'last_week_net', COALESCE((SELECT SUM(CASE WHEN i.doc_type='invoice' THEN i.total ELSE -i.total END) FROM public.sales_invoices i
        WHERE i.status='posted' AND i.currency=x.currency AND i.posted_at>=v_lw_from AND i.posted_at<v_lw_to
          AND (p_warehouse_id IS NULL OR COALESCE((SELECT s0.warehouse_id FROM public.sales_invoices s0 WHERE s0.id=i.return_against_id), i.warehouse_id)=p_warehouse_id)), 0)) ORDER BY x.currency)
   FROM (SELECT i.currency,
           count(*) FILTER (WHERE i.doc_type='invoice') n,
           COALESCE(SUM(i.total) FILTER (WHERE i.doc_type='invoice'),0) gross,
           COALESCE(SUM(i.total) FILTER (WHERE i.doc_type='credit_note'),0) returns,
           COALESCE(SUM((SELECT SUM(COALESCE(l.cost_total_basis,0)) FROM public.sales_invoice_lines l WHERE l.invoice_id=i.id))
             FILTER (WHERE i.doc_type='invoice'),0)
           - COALESCE(SUM((SELECT SUM(COALESCE(l.cost_total_basis,0)) FROM public.sales_invoice_lines l WHERE l.invoice_id=i.id))
             FILTER (WHERE i.doc_type='credit_note'),0) cost
         FROM public.sales_invoices i
         WHERE i.status='posted' AND i.posted_at>=v_from AND i.posted_at<v_to
           AND (p_warehouse_id IS NULL OR COALESCE((SELECT s0.warehouse_id FROM public.sales_invoices s0 WHERE s0.id=i.return_against_id), i.warehouse_id)=p_warehouse_id)
         GROUP BY i.currency) x), '[]'::jsonb),

  -- Where the sales came from.
  'channels', COALESCE((SELECT jsonb_agg(jsonb_build_object('channel', c.channel, 'currency', c.currency, 'invoices', c.n, 'total', c.total)
                         ORDER BY c.currency, c.total DESC)
   FROM (SELECT CASE WHEN i.till_session_id IS NOT NULL THEN 'counter'
                     WHEN i.fulfillment_mode='dispatch' THEN 'delivery'
                     ELSE 'online_pickup' END channel, i.currency, count(*) n, SUM(i.total) total
         FROM public.sales_invoices i
         WHERE i.status='posted' AND i.doc_type='invoice' AND i.posted_at>=v_from AND i.posted_at<v_to
           AND (p_warehouse_id IS NULL OR i.warehouse_id=p_warehouse_id)
         GROUP BY 1,2) c), '[]'::jsonb),

  -- Money taken today, by tender (payments posted today, any invoice date).
  'payments', COALESCE((SELECT jsonb_agg(jsonb_build_object('tender', p.tender, 'currency', p.currency, 'count', p.n, 'amount', p.amount)
                         ORDER BY p.currency, p.amount DESC)
   FROM (SELECT pe.tender::text tender, pe.currency, count(*) n, SUM(pe.amount) amount
         FROM public.payment_entries pe
         WHERE pe.status='posted' AND pe.posted_at>=v_from AND pe.posted_at<v_to
           AND (p_warehouse_id IS NULL OR EXISTS(SELECT 1 FROM public.payment_allocations pa JOIN public.sales_invoices i ON i.id=pa.sales_invoice_id
                                                WHERE pa.payment_entry_id=pe.id AND i.warehouse_id=p_warehouse_id))
         GROUP BY 1,2) p), '[]'::jsonb),

  -- Sold today but not paid (on account / pay on delivery still owed).
  'unpaid_today', COALESCE((SELECT jsonb_agg(jsonb_build_object('currency', u.currency, 'invoices', u.n, 'amount', u.amount))
   FROM (SELECT i.currency, count(*) n, SUM(i.total - COALESCE(i.amount_paid,0)) amount
         FROM public.sales_invoices i
         WHERE i.status='posted' AND i.doc_type='invoice' AND i.posted_at>=v_from AND i.posted_at<v_to
           AND i.total - COALESCE(i.amount_paid,0) > 0.004
           AND (p_warehouse_id IS NULL OR i.warehouse_id=p_warehouse_id)
         GROUP BY 1) u), '[]'::jsonb),

  -- Sales by hour (Harare), for the day's shape.
  'hourly', COALESCE((SELECT jsonb_agg(jsonb_build_object('hour', h.hr, 'currency', h.currency, 'total', h.total) ORDER BY h.currency, h.hr)
   FROM (SELECT extract(hour FROM i.posted_at AT TIME ZONE 'Africa/Harare')::int hr, i.currency, SUM(i.total) total
         FROM public.sales_invoices i
         WHERE i.status='posted' AND i.doc_type='invoice' AND i.posted_at>=v_from AND i.posted_at<v_to
           AND (p_warehouse_id IS NULL OR i.warehouse_id=p_warehouse_id)
         GROUP BY 1,2) h), '[]'::jsonb),

  'top_parts', COALESCE((SELECT jsonb_agg(t ORDER BY (t->>'total')::numeric DESC)
   FROM (SELECT jsonb_build_object('oem_part_number', si.oem_part_number, 'description', si.description, 'currency', i.currency,
                 'qty', SUM(l.qty), 'total', SUM(l.line_total)) t
         FROM public.sales_invoice_lines l JOIN public.sales_invoices i ON i.id=l.invoice_id JOIN public.stock_items si ON si.id=l.stock_item_id
         WHERE i.status='posted' AND i.doc_type='invoice' AND i.posted_at>=v_from AND i.posted_at<v_to AND NOT l.is_core_charge
           AND (p_warehouse_id IS NULL OR i.warehouse_id=p_warehouse_id)
         GROUP BY si.oem_part_number, si.description, i.currency
         ORDER BY SUM(l.line_total) DESC LIMIT 5) q), '[]'::jsonb),

  -- Tills opened today: who, float, and how the close counted.
  'tills', COALESCE((SELECT jsonb_agg(jsonb_build_object(
     'id', s.id, 'warehouse', w.name, 'cashier', p.full_name, 'status', s.status, 'currency', s.currency,
     'opening_float', s.opening_float, 'expected_cash', s.expected_cash, 'counted_cash', s.counted_cash, 'variance', s.variance,
     'approved', s.approved_by IS NOT NULL, 'opened_at', s.opened_at, 'closed_at', s.closed_at,
     'variance_reason', s.variance_reason_code, 'approved_by_name', (SELECT ap.full_name FROM public.profiles ap WHERE ap.id=s.approved_by),
     -- Corrections to the drawer during the day: pay-ins, pay-outs, bank drops, cash refunds.
     'movements', COALESCE((SELECT jsonb_agg(jsonb_build_object('kind', m.kind, 'amount', m.amount, 'reason', m.reason_code, 'notes', m.notes,
          'by', (SELECT mp.full_name FROM public.profiles mp WHERE mp.id=m.actor_user_id), 'at', m.created_at) ORDER BY m.created_at)
        FROM public.pos_till_cash_movements m WHERE m.session_id=s.id), '[]'::jsonb)) ORDER BY s.opened_at)
   FROM public.pos_till_sessions s LEFT JOIN public.warehouses w ON w.id=s.warehouse_id LEFT JOIN public.profiles p ON p.id=s.operator_user_id
   WHERE ((s.opened_at>=v_from AND s.opened_at<v_to) OR (s.status<>'closed' AND s.opened_at<v_to))
     AND (p_warehouse_id IS NULL OR s.warehouse_id=p_warehouse_id)), '[]'::jsonb),

  'deliveries', (SELECT jsonb_build_object(
     'dispatched', count(*) FILTER (WHERE dj.dispatched_at>=v_from AND dj.dispatched_at<v_to),
     'completed', count(*) FILTER (WHERE dj.completed_at>=v_from AND dj.completed_at<v_to),
     'failed', count(*) FILTER (WHERE dj.failed_at>=v_from AND dj.failed_at<v_to),
     'on_the_road', count(*) FILTER (WHERE dj.status='dispatched'),
     'waiting_for_driver', count(*) FILTER (WHERE dj.status='pending'))
   FROM public.delivery_jobs dj JOIN public.delivery_notes dn ON dn.id=dj.delivery_note_id
   LEFT JOIN public.sales_invoices i ON i.id=dn.sales_invoice_id
   WHERE p_warehouse_id IS NULL OR i.warehouse_id=p_warehouse_id),

  'cash_on_delivery', COALESCE((SELECT jsonb_agg(jsonb_build_object('currency', c.currency, 'collected', c.amount, 'collections', c.n))
   FROM (SELECT dc.currency, SUM(dc.amount) amount, count(*) n FROM public.delivery_cash_collections dc
         WHERE dc.collected_at>=v_from AND dc.collected_at<v_to
           AND (p_warehouse_id IS NULL OR EXISTS(SELECT 1 FROM public.sales_invoices i WHERE i.id=dc.sales_invoice_id AND i.warehouse_id=p_warehouse_id))
         GROUP BY 1) c), '[]'::jsonb),

  -- Cash still in drivers' hands (all days): should come in at the end of each run.
  'driver_cash_held', COALESCE((SELECT jsonb_agg(jsonb_build_object('currency', d.currency, 'amount', d.amount, 'drivers', d.drivers, 'oldest_at', d.oldest))
   FROM (SELECT dc.currency, SUM(dc.amount) amount, count(DISTINCT dc.collected_by) drivers, min(dc.collected_at) oldest
         FROM public.delivery_cash_collections dc WHERE dc.handin_id IS NULL GROUP BY 1) d), '[]'::jsonb),

  -- What customers owe (all days), and how much of it is more than 30 days old.
  'owed', COALESCE((SELECT jsonb_agg(jsonb_build_object('currency', o.currency, 'amount', o.amount, 'overdue_30', o.overdue, 'customers', o.customers))
   FROM (SELECT i.currency, SUM(i.total - COALESCE(i.amount_paid,0)) amount,
                COALESCE(SUM(i.total - COALESCE(i.amount_paid,0)) FILTER (WHERE i.posted_at < now() - interval '30 days'),0) overdue,
                count(DISTINCT i.customer_id) customers
         FROM public.sales_invoices i
         WHERE i.status='posted' AND i.doc_type='invoice' AND i.customer_id IS NOT NULL AND i.total - COALESCE(i.amount_paid,0) > 0.004
           AND (p_warehouse_id IS NULL OR i.warehouse_id=p_warehouse_id)
         GROUP BY 1) o), '[]'::jsonb),
  'suspended_customers', (SELECT count(*) FROM public.customer_suspensions cs WHERE cs.status='active'),
  'suspended_today', (SELECT count(*) FROM public.customer_suspensions cs WHERE cs.suspended_at>=v_from AND cs.suspended_at<v_to),

  -- Stock to reorder: at or below the reorder point at this branch (or any branch).
  'low_stock', COALESCE((SELECT jsonb_agg(ls ORDER BY (ls->>'on_hand')::numeric)
   FROM (SELECT jsonb_build_object('oem_part_number', si.oem_part_number, 'description', si.description, 'warehouse', w.name,
                 'on_hand', sl.quantity, 'reorder_point', si.reorder_point, 'reorder_qty', si.reorder_qty) ls
         FROM public.stock_levels sl JOIN public.stock_items si ON si.id=sl.stock_item_id JOIN public.warehouses w ON w.id=sl.warehouse_id
         WHERE si.reorder_point IS NOT NULL AND sl.quantity <= si.reorder_point
           AND (p_warehouse_id IS NULL OR sl.warehouse_id=p_warehouse_id)
         ORDER BY sl.quantity LIMIT 10) q), '[]'::jsonb),
  'low_stock_count', (SELECT count(*) FROM public.stock_levels sl JOIN public.stock_items si ON si.id=sl.stock_item_id
     WHERE si.reorder_point IS NOT NULL AND sl.quantity <= si.reorder_point AND (p_warehouse_id IS NULL OR sl.warehouse_id=p_warehouse_id)),
  'backorders_waiting', (SELECT count(*) FROM public.pos_fulfillment_requests f
     WHERE f.kind='backorder' AND f.status IN('requested','ready') AND f.invoice_id IS NULL
       AND (p_warehouse_id IS NULL OR f.destination_warehouse_id=p_warehouse_id)),

  'approvals_waiting', jsonb_array_length(private.approvals_for(auth.uid()))
 );
END $$;


--
-- Name: get_delivery_balance_approval(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_delivery_balance_approval(p_delivery_job_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE b public.delivery_balance_approvals%ROWTYPE;
BEGIN
 SELECT * INTO b FROM public.delivery_balance_approvals WHERE delivery_job_id=p_delivery_job_id ORDER BY created_at DESC LIMIT 1;
 IF NOT FOUND THEN RETURN NULL; END IF;
 IF NOT (b.requested_by=auth.uid() OR public.has_staff_role(ARRAY['admin','dispatcher','finance']::public.staff_role[]) OR public.is_pos_approver()) THEN
  RAISE EXCEPTION 'not allowed'; END IF;
 RETURN private._delivery_balance_approval_json(b);
END $$;


--
-- Name: get_delivery_card_terminal_recovery(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_delivery_card_terminal_recovery(p_delivery_job_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE j public.delivery_jobs%ROWTYPE; v_attempt UUID;
BEGIN
 SELECT * INTO j FROM public.delivery_jobs WHERE id=p_delivery_job_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'delivery job not found'; END IF;
 IF auth.role()<>'service_role' AND NOT public.has_staff_role(ARRAY['admin']::public.staff_role[]) AND j.assignee_user_id IS DISTINCT FROM auth.uid() THEN
  RAISE EXCEPTION 'not authorized for delivery job settlement';
 END IF;
 SELECT a.id INTO v_attempt
 FROM public.pos_card_terminal_attempts a
 WHERE a.delivery_job_id=j.id AND (a.status IN('initiated','approved','unknown') OR a.finalization_error IS NOT NULL)
 ORDER BY a.created_at DESC LIMIT 1;
 IF v_attempt IS NULL THEN RETURN NULL; END IF;
 RETURN private.pos_card_terminal_attempt_payload(v_attempt);
END $$;


--
-- Name: get_delivery_job_lines(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_delivery_job_lines(p_delivery_job_id uuid) RETURNS TABLE(delivery_job_id uuid, line_id uuid, qty numeric, oem_part_number text, description text, currency public.currency_code, unit_price numeric, line_total numeric, unit_price_minor bigint, line_total_minor bigint, is_core_charge boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE v_job public.delivery_jobs%ROWTYPE; BEGIN IF p_delivery_job_id IS NULL THEN RAISE EXCEPTION 'delivery_job_id required'; END IF; SELECT * INTO v_job FROM public.delivery_jobs WHERE id=p_delivery_job_id; IF NOT FOUND THEN RETURN; END IF; IF auth.role()<>'service_role' AND NOT public.has_staff_role(ARRAY['admin']::public.staff_role[]) AND v_job.assignee_user_id IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'not authorized for delivery job lines'; END IF; RETURN QUERY SELECT v_job.id,dnl.id,dnl.qty,si.oem_part_number,si.description,COALESCE(inv.currency,dnl.currency),sil.unit_price,sil.line_total,COALESCE(sil.unit_price_minor,public._major_to_minor(sil.unit_price)),COALESCE(sil.line_total_minor,public._major_to_minor(sil.line_total)),COALESCE(sil.is_core_charge,false) FROM public.delivery_note_lines dnl JOIN public.sales_invoice_lines sil ON sil.id=dnl.sales_invoice_line_id JOIN public.stock_items si ON si.id=dnl.stock_item_id LEFT JOIN public.sales_invoices inv ON inv.id=sil.invoice_id WHERE dnl.delivery_note_id=v_job.delivery_note_id ORDER BY dnl.created_at ASC,dnl.id ASC; END; $$;


--
-- Name: FUNCTION get_delivery_job_lines(p_delivery_job_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_delivery_job_lines(p_delivery_job_id uuid) IS 'Driver/admin DN/invoice line items for a delivery job; SECURITY DEFINER — sell amounts from invoice lines, not DN COGS.';


--
-- Name: get_delivery_job_payment_context(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_delivery_job_payment_context(p_delivery_job_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE j public.delivery_jobs%ROWTYPE;i public.sales_invoices%ROWTYPE;v_due NUMERIC;
BEGIN
 SELECT * INTO j FROM public.delivery_jobs WHERE id=p_delivery_job_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'delivery job not found'; END IF;
 IF auth.role()<>'service_role' AND NOT public.has_staff_role(ARRAY['admin']::public.staff_role[]) AND j.assignee_user_id IS DISTINCT FROM auth.uid() THEN
  RAISE EXCEPTION 'not authorized for delivery job settlement';
 END IF;
 SELECT si.* INTO i FROM public.delivery_notes dn JOIN public.sales_invoices si ON si.id=dn.sales_invoice_id WHERE dn.id=j.delivery_note_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'delivery invoice not found'; END IF;
 v_due:=greatest(round(i.total-i.amount_paid,2),0);
 RETURN jsonb_build_object(
  'delivery_job_id',j.id,'sales_invoice_id',i.id,'document_number',i.document_number,
  'warehouse_id',i.warehouse_id,'currency',i.currency,'invoice_total',i.total,
  'amount_paid',i.amount_paid,'amount_due',v_due,
  'invoice_total_minor',public._major_to_minor(i.total),'amount_paid_minor',public._major_to_minor(i.amount_paid),
  'amount_due_minor',public._major_to_minor(v_due),'delivery_payment_method',i.delivery_payment_method,
  'may_collect_cash',i.delivery_payment_method IN('cash_on_delivery','cash_or_card_on_delivery'),
  'may_collect_card',i.delivery_payment_method IN('card_on_delivery','cash_or_card_on_delivery'),'job_status',j.status);
END $$;


--
-- Name: get_delivery_job_settlement(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_delivery_job_settlement(p_delivery_job_id uuid) RETURNS TABLE(delivery_job_id uuid, currency public.currency_code, invoice_total numeric, amount_paid numeric, amount_due numeric, invoice_total_minor bigint, amount_paid_minor bigint, amount_due_minor bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE v_job public.delivery_jobs%ROWTYPE; v_inv public.sales_invoices%ROWTYPE; v_due NUMERIC; BEGIN IF p_delivery_job_id IS NULL THEN RAISE EXCEPTION 'delivery_job_id required'; END IF; SELECT * INTO v_job FROM public.delivery_jobs WHERE id=p_delivery_job_id; IF NOT FOUND THEN RETURN; END IF; IF auth.role()<>'service_role' AND NOT public.has_staff_role(ARRAY['admin']::public.staff_role[]) AND v_job.assignee_user_id IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'not authorized for delivery job settlement'; END IF; SELECT si.* INTO v_inv FROM public.delivery_notes dn JOIN public.sales_invoices si ON si.id=dn.sales_invoice_id WHERE dn.id=v_job.delivery_note_id; IF NOT FOUND THEN RETURN; END IF; v_due:=GREATEST(COALESCE(v_inv.total,0)-COALESCE(v_inv.amount_paid,0),0); RETURN QUERY SELECT v_job.id,v_inv.currency,v_inv.total,v_inv.amount_paid,v_due,public._major_to_minor(v_inv.total),public._major_to_minor(v_inv.amount_paid),public._major_to_minor(v_due); END; $$;


--
-- Name: FUNCTION get_delivery_job_settlement(p_delivery_job_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_delivery_job_settlement(p_delivery_job_id uuid) IS 'Driver/admin COD snapshot for a delivery job; SECURITY DEFINER — no sales_invoices SELECT for drivers.';


--
-- Name: get_delivery_track_point(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_delivery_track_point(p_delivery_job_id uuid DEFAULT NULL::uuid, p_token text DEFAULT NULL::text) RETURNS TABLE(delivery_job_id uuid, lat double precision, lng double precision, recorded_at timestamp with time zone, eta_at timestamp with time zone, eta_seconds integer, status public.delivery_job_status)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_job_id UUID;
  v_hash TEXT;
  v_tok public.delivery_track_tokens%ROWTYPE;
  v_job public.delivery_jobs%ROWTYPE;
  v_ok BOOLEAN := false;
BEGIN
  IF p_delivery_job_id IS NULL AND (p_token IS NULL OR length(trim(p_token)) = 0) THEN
    RAISE EXCEPTION 'delivery_job_id or token required';
  END IF;

  IF p_token IS NOT NULL AND length(trim(p_token)) > 0 THEN
    v_hash := public._hash_delivery_track_token(trim(p_token));
    SELECT * INTO v_tok
    FROM public.delivery_track_tokens
    WHERE token_hash = v_hash
    ORDER BY created_at DESC
    LIMIT 1;

    IF NOT FOUND THEN
      RETURN;
    END IF;
    IF v_tok.revoked_at IS NOT NULL OR v_tok.expires_at < now() THEN
      RETURN;
    END IF;
    v_job_id := v_tok.delivery_job_id;
    v_ok := true;
  ELSE
    v_job_id := p_delivery_job_id;
  END IF;

  SELECT * INTO v_job FROM public.delivery_jobs WHERE id = v_job_id;
  IF NOT FOUND THEN
    RETURN;
  END IF;

  -- Active dispatched only — never terminal / pending
  IF v_job.status <> 'dispatched' THEN
    RETURN;
  END IF;

  IF NOT v_ok THEN
    IF auth.role() = 'service_role'
       OR public.has_staff_role(
         ARRAY['admin', 'warehouse', 'dispatcher']::public.staff_role[]
       )
       OR v_job.assignee_user_id = auth.uid()
       OR public._customer_owns_delivery_job(v_job_id) THEN
      v_ok := true;
    END IF;
  END IF;

  IF NOT v_ok THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    v_job.id,
    dl.lat,
    dl.lng,
    dl.recorded_at,
    v_job.eta_at,
    v_job.eta_seconds,
    v_job.status
  FROM public.delivery_locations dl
  WHERE dl.delivery_job_id = v_job.id
  ORDER BY dl.recorded_at DESC, dl.ingested_at DESC
  LIMIT 1;
END;
$$;


--
-- Name: get_exception_report(date, date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_exception_report(p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_warehouse_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
 v_to_day date := COALESCE(p_to, (now() AT TIME ZONE 'Africa/Harare')::date);
 v_from_day date := COALESCE(p_from, v_to_day - 6);
 v_from timestamptz := (v_from_day::timestamp AT TIME ZONE 'Africa/Harare');
 v_to timestamptz := ((v_to_day + 1)::timestamp AT TIME ZONE 'Africa/Harare');
 v_items jsonb;
BEGIN
 IF NOT (public.has_staff_role(ARRAY['admin','finance']::public.staff_role[]) OR public.is_pos_approver()) THEN
  RAISE EXCEPTION 'manager, finance or admin required';
 END IF;
 IF v_to_day - v_from_day > 92 THEN RAISE EXCEPTION 'choose at most 93 days'; END IF;

 WITH ex AS (
  -- POS actions that give value away or undo a sale in progress.
  SELECT a.created_at AS at, a.action AS kind,
         CASE a.action WHEN 'cart_voided' THEN 'medium' WHEN 'cart_line_removed' THEN 'medium'
                       WHEN 'paid_order_repaired' THEN 'high' ELSE 'low' END AS severity,
         -- The sale's cashier; the manager who did or approved it (governed actions run as the manager).
         COALESCE(c.created_by, a.actor_user_id) AS person_id,
         COALESCE(a.approved_by_user_id, CASE WHEN a.actor_user_id IS DISTINCT FROM c.created_by THEN a.actor_user_id END) AS approved_by,
         c.warehouse_id, c.currency::text AS currency,
         CASE a.action
          WHEN 'price_override' THEN (a.before_state->>'line_total')::numeric - (a.after_state->>'line_total')::numeric
          WHEN 'discount_applied' THEN
            COALESCE((SELECT SUM((x->>'line_total')::numeric) FROM jsonb_array_elements(CASE WHEN jsonb_typeof(a.before_state)='array' THEN a.before_state ELSE '[]'::jsonb END) x),0)
          - COALESCE((SELECT SUM((x->>'line_total')::numeric) FROM jsonb_array_elements(CASE WHEN jsonb_typeof(a.after_state)='array' THEN a.after_state
                       WHEN jsonb_typeof(a.after_state)='object' AND a.after_state ? 'lines' THEN a.after_state->'lines' ELSE '[]'::jsonb END) x),0)
          WHEN 'cart_line_removed' THEN (a.before_state->'line'->>'line_total')::numeric
          WHEN 'cart_voided' THEN (SELECT SUM(l.line_total) FROM public.pos_cart_lines l WHERE l.cart_id=c.id)
         END AS amount,
         CASE a.action
          WHEN 'cart_voided' THEN 'Sale voided'
          WHEN 'cart_line_removed' THEN 'Part removed after it was rung up'
          WHEN 'discount_applied' THEN 'Discount '||COALESCE(
             CASE WHEN jsonb_typeof(a.after_state)='object' THEN a.after_state->>'discount_percent' END,
             (SELECT x->>'discount_percent' FROM jsonb_array_elements(CASE WHEN jsonb_typeof(a.after_state)='array' THEN a.after_state ELSE '[]'::jsonb END) x
               WHERE x ? 'discount_percent' LIMIT 1),'?')||'%'
          WHEN 'price_override' THEN 'Price changed from '||(a.before_state->>'unit_price')||' to '||(a.after_state->>'unit_price')
          WHEN 'paid_order_repaired' THEN 'Paid order repaired by hand'
         END ||COALESCE(' · '||replace(a.reason_code,'_',' '),'')
         -- Governed actions write "reason · notes" into notes: keep only the free text.
         ||COALESCE(' · '||NULLIF(regexp_replace(a.notes,'^'||COALESCE(a.reason_code,'')||'( · )?',''),''),'') AS detail,
         '/pos' AS href
  FROM public.pos_action_audit a
  LEFT JOIN public.pos_carts c ON c.id = CASE
     WHEN a.entity_type='pos_carts' THEN a.entity_id
     WHEN a.entity_type='pos_cart_line' THEN (SELECT l.cart_id FROM public.pos_cart_lines l WHERE l.id=a.entity_id)
     WHEN a.entity_type='pos_cart_lines' THEN NULLIF(a.before_state->'line'->>'cart_id','')::uuid
     WHEN a.entity_type='commerce_orders' THEN (SELECT o.cart_id FROM public.commerce_orders o WHERE o.id=a.entity_id) END
  WHERE a.created_at>=v_from AND a.created_at<v_to
    AND a.action IN('cart_voided','cart_line_removed','discount_applied','price_override','paid_order_repaired')

  UNION ALL -- Returns posted (who raised it and which manager approved).
  SELECT r.posted_at, 'return', CASE WHEN r.resolution='cash_refund' THEN 'medium' ELSE 'low' END,
         r.created_by, r.approved_by, i.warehouse_id, i.currency::text,
         (SELECT SUM(round(l.qty*l.unit_price,2)) FROM public.pos_return_case_lines l WHERE l.return_case_id=r.id),
         r.document_number||' · '||replace(r.resolution::text,'_',' ')||COALESCE(' · '||replace(r.reason_code,'_',' '),'')
           ||CASE WHEN r.posted_at - i.posted_at < interval '1 hour' THEN ' · within an hour of the sale' ELSE '' END,
         '/pos'
  FROM public.pos_return_cases r JOIN public.sales_invoices i ON i.id=r.source_invoice_id
  WHERE r.status='posted' AND r.posted_at>=v_from AND r.posted_at<v_to

  UNION ALL -- Tills that did not count out right.
  SELECT COALESCE(s.closed_at,s.updated_at), CASE WHEN s.variance<0 THEN 'till_short' ELSE 'till_over' END,
         CASE WHEN abs(s.variance)>=20 THEN 'high' WHEN abs(s.variance)>=5 THEN 'medium' ELSE 'low' END,
         s.operator_user_id, s.approved_by, s.warehouse_id, s.currency::text, s.variance,
         'Counted '||s.counted_cash||', expected '||s.expected_cash||COALESCE(' · '||replace(s.variance_reason_code,'_',' '),'')
           ||CASE WHEN s.approved_by IS NULL THEN ' · not yet approved' ELSE '' END,
         '/pos'
  FROM public.pos_till_sessions s
  WHERE s.variance IS NOT NULL AND abs(s.variance)>0.009 AND COALESCE(s.closed_at,s.updated_at)>=v_from AND COALESCE(s.closed_at,s.updated_at)<v_to

  UNION ALL -- Driver cash that did not count out right.
  SELECT h.received_at, CASE WHEN h.variance<0 THEN 'driver_cash_short' ELSE 'driver_cash_over' END,
         CASE WHEN abs(h.variance)>=20 THEN 'high' ELSE 'medium' END,
         h.driver_user_id, h.approved_by, NULL::uuid, h.currency::text, h.variance,
         h.document_number||' · counted '||h.received_amount||' of '||h.expected_amount||COALESCE(' · '||replace(h.reason_code,'_',' '),''),
         '/staff/logistics/driver-cash'
  FROM public.driver_cash_handins h
  WHERE h.variance IS NOT NULL AND abs(h.variance)>0.009 AND h.received_at>=v_from AND h.received_at<v_to

  UNION ALL -- Card charges that did not go through, or have no answer.
  SELECT a.created_at, 'card_'||a.status, CASE WHEN a.status='unknown' THEN 'high' ELSE 'low' END,
         a.created_by, NULL::uuid, t.warehouse_id, a.currency::text, a.amount,
         COALESCE(t.label,'card machine')||' · '||a.status||COALESCE(' · '||a.response_message,''),
         '/pos'
  FROM public.pos_card_terminal_attempts a LEFT JOIN public.pos_card_terminals t ON t.id=a.terminal_id
  WHERE a.created_at>=v_from AND a.created_at<v_to AND a.status IN('declined','cancelled','unknown','failed')

  UNION ALL -- Sold below cost.
  SELECT i.posted_at, 'below_cost', 'medium', i.posted_by, NULL::uuid, i.warehouse_id, i.currency::text,
         l.cost_total_basis - l.line_total,
         i.document_number||' · '||si.oem_part_number||' sold for '||l.line_total||', cost '||l.cost_total_basis,
         '/staff/finance'
  FROM public.sales_invoice_lines l JOIN public.sales_invoices i ON i.id=l.invoice_id JOIN public.stock_items si ON si.id=l.stock_item_id
  WHERE i.status='posted' AND i.doc_type='invoice' AND i.posted_at>=v_from AND i.posted_at<v_to
    AND NOT l.is_core_charge AND l.cost_total_basis IS NOT NULL AND l.line_total + 0.005 < l.cost_total_basis

  UNION ALL -- Sales outside trading hours (before 07:00 or from 19:00 Harare).
  SELECT i.posted_at, 'after_hours', 'low', i.posted_by, NULL::uuid, i.warehouse_id, i.currency::text, i.total,
         i.document_number||' at '||to_char(i.posted_at AT TIME ZONE 'Africa/Harare','HH24:MI'),
         '/staff/finance'
  FROM public.sales_invoices i
  WHERE i.status='posted' AND i.doc_type='invoice' AND i.till_session_id IS NOT NULL AND i.posted_at>=v_from AND i.posted_at<v_to
    AND (extract(hour FROM i.posted_at AT TIME ZONE 'Africa/Harare')<7 OR extract(hour FROM i.posted_at AT TIME ZONE 'Africa/Harare')>=19)

  UNION ALL -- Deliveries that failed at the door.
  SELECT dj.failed_at, 'delivery_failed', CASE WHEN COALESCE(dj.failure_reason_code::text,'') IN('refused','customer_absent') THEN 'medium' ELSE 'low' END,
         dj.assignee_user_id, NULL::uuid, i.warehouse_id, i.currency::text, i.total,
         dj.document_number||COALESCE(' · '||replace(dj.failure_reason_code::text,'_',' '),'')||COALESCE(' · '||dj.failure_reason,''),
         '/staff/logistics'
  FROM public.delivery_jobs dj JOIN public.delivery_notes dn ON dn.id=dj.delivery_note_id LEFT JOIN public.sales_invoices i ON i.id=dn.sales_invoice_id
  WHERE dj.status='failed' AND dj.failed_at>=v_from AND dj.failed_at<v_to

  UNION ALL -- Balances left on account by a back-office decision (outside the customer's limit).
  SELECT b.decided_at, 'balance_on_account', 'medium', b.requested_by, b.decided_by, i.warehouse_id, b.currency::text, b.amount,
         COALESCE(c.business_name,c.display_name,'customer')||' · '||b.reason, '/staff/logistics/balances'
  FROM public.delivery_balance_approvals b LEFT JOIN public.customers c ON c.id=b.customer_id LEFT JOIN public.sales_invoices i ON i.id=b.sales_invoice_id
  WHERE b.status='approved' AND b.basis='back_office' AND b.decided_at>=v_from AND b.decided_at<v_to

  UNION ALL -- Stock counts that did not match the books.
  SELECT COALESCE(sr.posted_at,sr.created_at), 'stock_count_difference',
         CASE WHEN abs(rl.variance_qty*COALESCE(rl.unit_cost,0))>=100 THEN 'high' ELSE 'medium' END,
         sr.created_by, sr.second_approver_id, sr.warehouse_id, rl.currency::text, rl.variance_qty*COALESCE(rl.unit_cost,0),
         COALESCE(sr.document_number,'count')||' · '||si.oem_part_number||' counted '||rl.counted_qty||', books '||rl.system_qty
           ||CASE WHEN sr.second_approver_id IS NULL THEN ' · posted by one person (under the two-person limit)' ELSE '' END,
         '/staff/warehouse'
  FROM public.stock_reconciliation_lines rl JOIN public.stock_reconciliations sr ON sr.id=rl.stock_reconciliation_id
  JOIN public.stock_items si ON si.id=rl.stock_item_id
  WHERE abs(COALESCE(rl.variance_qty,0))>0.0001 AND COALESCE(sr.posted_at,sr.created_at)>=v_from AND COALESCE(sr.posted_at,sr.created_at)<v_to
 ), scoped AS (
  SELECT * FROM ex WHERE p_warehouse_id IS NULL OR ex.warehouse_id=p_warehouse_id OR (ex.warehouse_id IS NULL AND ex.kind LIKE 'driver_cash%')
 )
 SELECT jsonb_build_object(
  'from', v_from_day, 'to', v_to_day, 'warehouse_id', p_warehouse_id,
  'warehouse_name', (SELECT w.name FROM public.warehouses w WHERE w.id=p_warehouse_id),
  'items', COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'at', s.at, 'kind', s.kind, 'severity', s.severity,
      'person_id', s.person_id, 'person', (SELECT p.full_name FROM public.profiles p WHERE p.id=s.person_id),
      'approved_by', (SELECT p.full_name FROM public.profiles p WHERE p.id=s.approved_by),
      'warehouse', (SELECT w.name FROM public.warehouses w WHERE w.id=s.warehouse_id),
      'currency', s.currency, 'amount', round(s.amount,2), 'detail', s.detail, 'href', s.href)
     ORDER BY CASE s.severity WHEN 'high' THEN 0 WHEN 'medium' THEN 1 ELSE 2 END, s.at DESC)
    FROM (SELECT * FROM scoped ORDER BY at DESC LIMIT 500) s), '[]'::jsonb),
  'by_kind', COALESCE((SELECT jsonb_agg(jsonb_build_object('kind', k.kind, 'count', k.n, 'currency', k.currency, 'amount', k.amount) ORDER BY k.n DESC)
    FROM (SELECT kind, currency, count(*) n, round(SUM(abs(COALESCE(amount,0))),2) amount FROM scoped GROUP BY kind, currency) k), '[]'::jsonb),
  'by_person', COALESCE((SELECT jsonb_agg(jsonb_build_object('person_id', b.person_id, 'person', (SELECT p.full_name FROM public.profiles p WHERE p.id=b.person_id),
       'count', b.n, 'high', b.high, 'kinds', b.kinds) ORDER BY b.high DESC, b.n DESC)
    FROM (SELECT person_id, count(*) n, count(*) FILTER (WHERE severity='high') high,
                 jsonb_object_agg(kind, kn) kinds
          FROM (SELECT person_id, kind, severity, count(*) OVER (PARTITION BY person_id, kind) kn FROM scoped WHERE person_id IS NOT NULL) z
          GROUP BY person_id) b), '[]'::jsonb)
 ) INTO v_items;
 RETURN v_items;
END $$;


--
-- Name: get_inventory_available_quantity(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_inventory_available_quantity(p_stock_item_id uuid, p_warehouse_id uuid) RETURNS numeric
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
 SELECT GREATEST(COALESCE((SELECT sl.quantity FROM public.stock_levels sl WHERE sl.stock_item_id=p_stock_item_id AND sl.warehouse_id=p_warehouse_id),0)
 - COALESCE((SELECT SUM(GREATEST(r.reserved_qty-r.consumed_qty,0)) FROM public.inventory_reservations r
   WHERE r.stock_item_id=p_stock_item_id AND r.warehouse_id=p_warehouse_id AND r.state IN ('active','allocated')
   AND (r.state='allocated' OR r.expires_at>now())),0),0); $$;


--
-- Name: get_loyalty_balance(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_loyalty_balance(p_customer_id uuid) RETURNS TABLE(customer_id uuid, points_balance numeric, currency public.currency_code, liability_per_point numeric, estimated_liability numeric, estimated_liability_minor bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_ok BOOLEAN;
BEGIN
  v_ok := (
    auth.role() = 'service_role'
    OR public.has_staff_role(ARRAY['admin', 'finance', 'sales']::public.staff_role[])
    OR EXISTS (
      SELECT 1 FROM public.customers c
      WHERE c.id = p_customer_id AND c.profile_id = auth.uid()
    )
  );
  IF NOT v_ok THEN
    RAISE EXCEPTION 'not authorized to read loyalty balance';
  END IF;

  RETURN QUERY
  SELECT
    p_customer_id,
    COALESCE(a.points_balance, 0::numeric),
    COALESCE(a.currency, s.currency),
    s.liability_per_point,
    round(COALESCE(a.points_balance, 0) * s.liability_per_point, 2),
    public._major_to_minor(
      round(COALESCE(a.points_balance, 0) * s.liability_per_point, 2)
    )
  FROM public.loyalty_program_settings s
  LEFT JOIN public.loyalty_accounts a ON a.customer_id = p_customer_id
  WHERE s.id = 1;
END;
$$;


--
-- Name: FUNCTION get_loyalty_balance(p_customer_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_loyalty_balance(p_customer_id uuid) IS 'Loyalty points + estimated liability; dual-read estimated_liability_minor when present (B-MONEY-1).';


--
-- Name: get_my_account_suspension(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_account_suspension() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_cust uuid := public._current_customer_id(); p jsonb;
BEGIN
 IF v_cust IS NULL THEN RETURN NULL; END IF;
 p := private.customer_suspension_preview(v_cust);
 IF p IS NULL THEN RETURN NULL; END IF;
 RETURN jsonb_build_object('suspended',true,'reason',p->>'reason','since',p->'suspended_at',
  'owing',p->'owing','owing_currency',p->'owing_currency','owing_by_currency',p->'owing_by_currency');
END $$;


--
-- Name: get_my_alert_settings(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_alert_settings() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE s public.staff_alert_settings%ROWTYPE;
BEGIN
 IF NOT public.is_staff() THEN RAISE EXCEPTION 'staff only'; END IF;
 SELECT * INTO s FROM public.staff_alert_settings WHERE user_id = auth.uid();
 RETURN jsonb_build_object(
  'phone_e164', COALESCE(s.phone_e164, (SELECT p.phone_e164 FROM public.profiles p WHERE p.id = auth.uid())),
  'channel', COALESCE(s.channel, 'sms'),
  'urgent_approvals', COALESCE(s.urgent_approvals, false),
  'morning_summary', COALESCE(s.morning_summary, false),
  'can_get_summary', public.has_staff_role(ARRAY['admin','finance']::public.staff_role[]) OR public.is_pos_approver(),
  'saved', s.user_id IS NOT NULL);
END $$;


--
-- Name: get_my_delivery_codes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_delivery_codes() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 SELECT COALESCE(jsonb_agg(jsonb_build_object(
   'delivery_job_id', dj.id, 'job_number', dj.document_number, 'sales_invoice_id', si.id,
   'invoice_number', si.document_number, 'code', pc.code, 'expires_at', pc.expires_at) ORDER BY pc.created_at DESC), '[]'::jsonb)
 FROM private.delivery_pod_codes pc
 JOIN public.delivery_jobs dj ON dj.id = pc.delivery_job_id
 JOIN public.delivery_notes dn ON dn.id = dj.delivery_note_id
 JOIN public.sales_invoices si ON si.id = dn.sales_invoice_id
 JOIN public.customers c ON c.id = si.customer_id
 WHERE c.profile_id = auth.uid() AND auth.uid() IS NOT NULL
   AND dj.status = 'dispatched' AND pc.expires_at > now();
$$;


--
-- Name: get_my_driver_cash(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_driver_cash() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
 IF NOT public.has_staff_role(ARRAY['driver']::public.staff_role[]) THEN RAISE EXCEPTION 'driver role required'; END IF;
 RETURN jsonb_build_object(
  'holding', COALESCE((SELECT jsonb_agg(x ORDER BY x->>'currency') FROM (
    SELECT jsonb_build_object('currency',c.currency,'amount',sum(c.amount),'count',count(*),'oldest_at',min(c.collected_at),
      'collections',jsonb_agg(jsonb_build_object('id',c.id,'amount',c.amount,'collected_at',c.collected_at,
        'job_number',(SELECT j.document_number FROM public.delivery_jobs j WHERE j.id=c.delivery_job_id),
        'invoice_number',(SELECT si.document_number FROM public.sales_invoices si WHERE si.id=c.sales_invoice_id)) ORDER BY c.collected_at)) x
    FROM public.delivery_cash_collections c WHERE c.collected_by=auth.uid() AND c.handin_id IS NULL GROUP BY c.currency) t),'[]'::jsonb),
  'owed', COALESCE((SELECT jsonb_agg(jsonb_build_object('currency',o.currency,'amount',o.amount) ORDER BY o.currency)
    FROM (SELECT currency, sum(owed_amount-recovered_amount-written_off_amount) AS amount FROM public.driver_cash_handins
          WHERE driver_user_id=auth.uid() AND owed_amount-recovered_amount-written_off_amount > 0 GROUP BY currency) o),'[]'::jsonb),
  'handins', COALESCE((SELECT jsonb_agg(private._driver_cash_handin_json(h) ORDER BY h.submitted_at DESC)
    FROM (SELECT * FROM public.driver_cash_handins WHERE driver_user_id=auth.uid() ORDER BY submitted_at DESC LIMIT 10) h),'[]'::jsonb));
END $$;


--
-- Name: get_my_manager_signature(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_manager_signature() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE e public.employees%ROWTYPE;
BEGIN
 IF NOT (public.is_pos_approver() OR public.has_staff_role(ARRAY['admin','finance']::public.staff_role[])) THEN RAISE EXCEPTION 'manager/finance/admin role required'; END IF;
 SELECT * INTO e FROM public.employees WHERE user_id=auth.uid() AND status='active';
 IF NOT FOUND THEN RAISE EXCEPTION 'active employee profile required'; END IF;
 RETURN jsonb_build_object('employee_id',e.id,'employee_code',e.employee_code,'full_name',e.full_name,
  'signature_bucket',e.signature_storage_bucket,'signature_path',e.signature_storage_path,'signature_mime_type',e.signature_mime_type,
  'signature_sha256',e.signature_sha256,'signature_captured_at',e.signature_captured_at,'has_signature',e.signature_storage_path IS NOT NULL);
END $$;


--
-- Name: get_my_open_pos_till_session(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_open_pos_till_session(p_device_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE s public.pos_till_sessions%ROWTYPE;
BEGIN
 SELECT * INTO s FROM public.pos_till_sessions
 WHERE status IN('open','variance_pending') AND (operator_user_id=auth.uid() OR (p_device_id IS NOT NULL AND device_id=p_device_id))
 ORDER BY opened_at DESC LIMIT 1;
 IF NOT FOUND THEN RETURN NULL; END IF;
 RETURN to_jsonb(s);
END $$;


--
-- Name: get_my_pos_approver_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_pos_approver_status() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT jsonb_build_object('is_approver', private.pos_approver_source(auth.uid()) IS NOT NULL,
                            'source', private.pos_approver_source(auth.uid()));
$$;


--
-- Name: get_payment_resolution_letter_render_data(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_payment_resolution_letter_render_data(p_letter_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE l public.payment_resolution_letters%ROWTYPE; b public.business_document_profile%ROWTYPE;
BEGIN
 IF NOT (public.is_pos_approver() OR public.has_staff_role(ARRAY['admin','finance']::public.staff_role[])) THEN RAISE EXCEPTION 'manager/finance/admin role required'; END IF;
 SELECT * INTO l FROM public.payment_resolution_letters WHERE id=p_letter_id; IF NOT FOUND THEN RAISE EXCEPTION 'payment-resolution letter not found'; END IF;
 SELECT * INTO b FROM public.business_document_profile WHERE singleton=true;
 RETURN jsonb_build_object('letter',to_jsonb(l),'business',to_jsonb(b));
END $$;


--
-- Name: get_pick_path_hints(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_pick_path_hints(p_warehouse_id uuid, p_stock_item_ids uuid[] DEFAULT NULL::uuid[]) RETURNS TABLE(stock_item_id uuid, oem_part_number character varying, quantity numeric, bin_id uuid, bin_code character varying, bin_name text, pick_path_seq integer, aisle text, rack text, shelf text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT (
    auth.role() = 'service_role'
    OR public.has_staff_role(
      ARRAY['admin', 'warehouse', 'dispatcher']::public.staff_role[]
    )
  ) THEN
    RAISE EXCEPTION 'warehouse, dispatcher, or admin role required';
  END IF;

  RETURN QUERY
  SELECT
    sl.stock_item_id,
    si.oem_part_number,
    sl.quantity,
    wb.id AS bin_id,
    wb.code AS bin_code,
    wb.name AS bin_name,
    wb.pick_path_seq,
    wb.aisle,
    wb.rack,
    wb.shelf
  FROM public.stock_levels sl
  JOIN public.stock_items si ON si.id = sl.stock_item_id
  LEFT JOIN public.warehouse_bins wb
    ON wb.id = sl.bin_id AND wb.is_active
  WHERE sl.warehouse_id = p_warehouse_id
    AND sl.quantity > 0
    AND (
      p_stock_item_ids IS NULL
      OR cardinality(p_stock_item_ids) = 0
      OR sl.stock_item_id = ANY (p_stock_item_ids)
    )
  ORDER BY
    wb.pick_path_seq NULLS LAST,
    wb.code NULLS LAST,
    si.oem_part_number;
END;
$$;


--
-- Name: get_pos_approval_policy(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_pos_approval_policy(p_action text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 SELECT COALESCE((SELECT jsonb_build_object('action',action,'threshold_value',threshold_value,
   'always_require_manager',always_require_manager,'reason_required',reason_required)
   FROM public.pos_approval_policies WHERE action=p_action),'{}'::jsonb);
$$;


--
-- Name: get_pos_card_terminal_attempt(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_pos_card_terminal_attempt(p_attempt_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE a public.pos_card_terminal_attempts%ROWTYPE;
BEGIN
 PERFORM public._require_payments_staff(); SELECT * INTO a FROM public.pos_card_terminal_attempts WHERE id=p_attempt_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'card terminal attempt not found'; END IF;
 IF a.created_by<>auth.uid() AND NOT public.is_pos_approver() AND NOT public.has_staff_role(ARRAY['finance']::public.staff_role[]) THEN RAISE EXCEPTION 'card terminal attempt access denied'; END IF;
 RETURN private.pos_card_terminal_attempt_payload(a.id);
END $$;


--
-- Name: get_pos_invoice_detail(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_pos_invoice_detail(p_invoice_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE i public.sales_invoices%ROWTYPE; v_lines JSONB;
BEGIN
 PERFORM public._require_sales_staff(); SELECT * INTO i FROM public.sales_invoices WHERE id=p_invoice_id AND status='posted';
 IF NOT FOUND THEN RAISE EXCEPTION 'posted invoice not found'; END IF;
 SELECT COALESCE(jsonb_agg(jsonb_build_object(
   'id',l.id,'stock_item_id',l.stock_item_id,'oem_part_number',s.oem_part_number,'description',s.description,'uom_id',l.uom_id,
   'qty',l.qty,'unit_price',l.unit_price,'line_total',l.line_total,'is_core_charge',l.is_core_charge,
   'returnable_qty',CASE WHEN l.is_core_charge THEN GREATEST(l.qty-COALESCE((SELECT SUM(cr.qty) FROM public.pos_core_returns cr WHERE cr.source_core_line_id=l.id),0),0)
     ELSE GREATEST(l.qty-COALESCE((SELECT SUM(rl.qty) FROM public.pos_return_case_lines rl JOIN public.pos_return_cases rc ON rc.id=rl.return_case_id
       WHERE rl.source_invoice_line_id=l.id AND rc.status='posted'),0),0) END
  ) ORDER BY l.is_core_charge,l.created_at),'[]'::jsonb) INTO v_lines
 FROM public.sales_invoice_lines l JOIN public.stock_items s ON s.id=l.stock_item_id WHERE l.invoice_id=p_invoice_id;
 RETURN jsonb_build_object('id',i.id,'document_number',i.document_number,'customer_id',i.customer_id,'warehouse_id',i.warehouse_id,
  'currency',i.currency,'total',i.total,'amount_paid',i.amount_paid,'posted_at',i.posted_at,'till_session_id',i.till_session_id,'lines',v_lines);
END $$;


--
-- Name: get_pos_payment_status(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_pos_payment_status(p_order_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE o public.commerce_orders%ROWTYPE; v_status TEXT; v_failure TEXT; v_ex JSONB;
BEGIN
 PERFORM public._require_sales_staff(); SELECT * INTO o FROM public.commerce_orders WHERE id=p_order_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'commerce order not found'; END IF;
 IF o.active_payment_provider='ecocash' THEN SELECT status::text,failure_reason INTO v_status,v_failure FROM public.ecocash_payment_intents WHERE id=o.active_payment_intent_id;
 ELSIF o.active_payment_provider='paynow' THEN SELECT status::text,failure_reason INTO v_status,v_failure FROM public.paynow_payment_intents WHERE id=o.active_payment_intent_id;
 ELSIF o.active_payment_provider='contipay' THEN SELECT status::text,failure_reason INTO v_status,v_failure FROM public.contipay_payment_intents WHERE id=o.active_payment_intent_id;
 ELSIF o.active_payment_provider='card_terminal' THEN SELECT status::text,COALESCE(finalization_error,response_message) INTO v_status,v_failure FROM public.pos_card_terminal_attempts WHERE id=o.active_payment_intent_id;
 END IF;
 SELECT COALESCE(jsonb_agg(jsonb_build_object('id',e.id,'provider',e.provider,'code',e.exception_code,'detail',e.detail,'resolved_at',e.resolved_at,'resolution',e.resolution,'created_at',e.created_at) ORDER BY e.created_at DESC),'[]'::jsonb)
 INTO v_ex FROM public.commerce_payment_exceptions e WHERE e.commerce_order_id=p_order_id;
 RETURN jsonb_build_object('order_id',o.id,'cart_id',o.cart_id,'state',o.state,'total',o.total,'currency',o.currency,'reservation_expires_at',o.reservation_expires_at,
  'active_provider',o.active_payment_provider,'active_intent_id',o.active_payment_intent_id,'provider_status',v_status,'provider_failure',v_failure,
  'settled_payment_entry_id',o.settled_payment_entry_id,'settled_provider',o.settled_provider,'settled_provider_ref',o.settled_provider_ref,
  'sales_invoice_id',o.sales_invoice_id,'payment_exception',o.payment_exception,'exceptions',v_ex,'finalized_at',o.finalized_at);
END $$;


--
-- Name: get_pos_split_payment(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_pos_split_payment(p_session_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE s public.pos_split_payment_sessions%ROWTYPE; o public.commerce_orders%ROWTYPE;
BEGIN
 PERFORM public._require_payments_staff(); SELECT * INTO s FROM public.pos_split_payment_sessions WHERE id=p_session_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'split payment session not found'; END IF;
 SELECT * INTO o FROM public.commerce_orders WHERE id=s.commerce_order_id;
 IF o.cart_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.pos_carts c WHERE c.id=o.cart_id AND (c.created_by=auth.uid() OR public.is_pos_approver() OR public.has_staff_role(ARRAY['finance']::public.staff_role[]))) THEN
  RAISE EXCEPTION 'split payment access denied'; END IF;
 RETURN private.pos_split_payment_payload(s.id);
END $$;


--
-- Name: get_product_review_stats(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_product_review_stats(p_stock_item_id uuid DEFAULT NULL::uuid, p_oem_part_number text DEFAULT NULL::text) RETURNS TABLE(stock_item_id uuid, avg_rating numeric, review_count bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_item UUID;
BEGIN
  v_item := public._resolve_customer_stock_item(p_stock_item_id, p_oem_part_number);

  RETURN QUERY
  SELECT
    v_item,
    COALESCE(
      (
        SELECT round(avg(r.rating)::numeric, 2)
        FROM public.customer_product_reviews r
        WHERE r.stock_item_id = v_item AND r.status = 'approved'
      ),
      0::numeric
    ) AS avg_rating,
    (
      SELECT count(*)::bigint
      FROM public.customer_product_reviews r
      WHERE r.stock_item_id = v_item AND r.status = 'approved'
    ) AS review_count;
END;
$$;


--
-- Name: get_restock_suggestions(uuid, integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_restock_suggestions(p_warehouse_id uuid DEFAULT NULL::uuid, p_sales_days integer DEFAULT 28, p_lead_days integer DEFAULT 14, p_safety_days integer DEFAULT 7, p_cover_days integer DEFAULT 28) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
 v_days integer := LEAST(GREATEST(COALESCE(p_sales_days,28),7),365);
 v_since timestamptz := now() - make_interval(days => LEAST(GREATEST(COALESCE(p_sales_days,28),7),365));
 v_out jsonb;
BEGIN
 IF NOT (public.has_staff_role(ARRAY['admin','finance','warehouse']::public.staff_role[]) OR public.is_pos_approver()) THEN
  RAISE EXCEPTION 'warehouse, finance, manager or admin required';
 END IF;

 WITH wh AS (
  SELECT w.id, w.name FROM public.warehouses w WHERE w.is_active AND NOT COALESCE(w.is_quarantine,false)
 ), pairs AS (
  -- Every part that is stocked, sold, back-ordered or asked for (lost demand) at a branch.
  SELECT DISTINCT x.stock_item_id, x.warehouse_id FROM (
    SELECT sl.stock_item_id, sl.warehouse_id FROM public.stock_levels sl
    UNION SELECT l.stock_item_id, i.warehouse_id FROM public.sales_invoice_lines l JOIN public.sales_invoices i ON i.id=l.invoice_id
          WHERE i.status='posted' AND i.doc_type='invoice' AND i.posted_at>=v_since
    UNION SELECT f.stock_item_id, f.destination_warehouse_id FROM public.pos_fulfillment_requests f
          WHERE f.kind='backorder' AND f.status='requested'
    UNION SELECT ld.stock_item_id, ld.warehouse_id FROM public.lost_demand ld WHERE ld.created_at>=v_since
  ) x JOIN wh ON wh.id=x.warehouse_id
 ), facts AS (
  SELECT p.stock_item_id, p.warehouse_id, si.oem_part_number, si.description, si.base_uom_id,
   COALESCE(brp.reorder_point, si.reorder_point) AS own_rop, COALESCE(brp.reorder_qty, si.reorder_qty) AS reorder_qty,
   CASE WHEN brp.reorder_point IS NOT NULL THEN 'branch' WHEN si.reorder_point IS NOT NULL THEN 'set' END AS rop_source,
   COALESCE((SELECT SUM(ld.qty) FROM public.lost_demand ld WHERE ld.stock_item_id=p.stock_item_id AND ld.warehouse_id=p.warehouse_id AND ld.created_at>=v_since),0) AS lost,
   COALESCE((SELECT sl.quantity FROM public.stock_levels sl WHERE sl.stock_item_id=p.stock_item_id AND sl.warehouse_id=p.warehouse_id),0) AS on_hand,
   public.get_inventory_available_quantity(p.stock_item_id, p.warehouse_id) AS available,
   COALESCE((SELECT SUM(l.qty_base) FROM public.sales_invoice_lines l JOIN public.sales_invoices i ON i.id=l.invoice_id
             WHERE l.stock_item_id=p.stock_item_id AND i.warehouse_id=p.warehouse_id AND i.status='posted' AND i.doc_type='invoice'
               AND i.posted_at>=v_since AND NOT l.is_core_charge),0) AS sold,
   (SELECT max(i.posted_at) FROM public.sales_invoice_lines l JOIN public.sales_invoices i ON i.id=l.invoice_id
     WHERE l.stock_item_id=p.stock_item_id AND i.warehouse_id=p.warehouse_id AND i.status='posted' AND i.doc_type='invoice') AS last_sold_at,
   COALESCE((SELECT SUM(public.convert_to_base_uom(pl.stock_item_id, pl.uom_id, GREATEST(pl.qty_ordered-COALESCE(pl.qty_received,0),0)))
             FROM public.purchase_order_lines pl JOIN public.purchase_orders po ON po.id=pl.purchase_order_id
             WHERE pl.stock_item_id=p.stock_item_id AND po.warehouse_id=p.warehouse_id AND po.status IN('submitted','approved')),0) AS on_order,
   -- Draft orders are not on their way yet; shown so nobody drafts the same order twice.
   COALESCE((SELECT SUM(public.convert_to_base_uom(pl.stock_item_id, pl.uom_id, pl.qty_ordered))
             FROM public.purchase_order_lines pl JOIN public.purchase_orders po ON po.id=pl.purchase_order_id
             WHERE pl.stock_item_id=p.stock_item_id AND po.warehouse_id=p.warehouse_id AND po.status='draft'),0) AS in_draft,
   COALESCE((SELECT SUM(el.qty_base) FROM public.stock_entry_lines el JOIN public.stock_entries e ON e.id=el.stock_entry_id
             WHERE el.stock_item_id=p.stock_item_id AND e.entry_type='transfer' AND e.status='pending_approval' AND e.to_warehouse_id=p.warehouse_id),0) AS transfer_in,
   COALESCE((SELECT SUM(el.qty_base) FROM public.stock_entry_lines el JOIN public.stock_entries e ON e.id=el.stock_entry_id
             WHERE el.stock_item_id=p.stock_item_id AND e.entry_type='transfer' AND e.status='pending_approval' AND e.from_warehouse_id=p.warehouse_id),0) AS transfer_out,
   COALESCE((SELECT SUM(public.convert_to_base_uom(f.stock_item_id, f.uom_id, f.qty)) FROM public.pos_fulfillment_requests f
             WHERE f.stock_item_id=p.stock_item_id AND f.destination_warehouse_id=p.warehouse_id AND f.kind='backorder' AND f.status='requested'),0) AS backordered,
   sup.supplier_id, sup.supplier_name, sup.unit_cost AS supplier_cost, sup.currency AS supplier_currency,
   -- Lead time actually seen (order submitted -> goods received) beats the quoted one.
   COALESCE((sup.actual->>'days')::numeric, sup.lead_days) AS lead_days,
   CASE WHEN sup.actual IS NOT NULL THEN 'received' WHEN sup.lead_days IS NOT NULL THEN 'quoted' END AS lead_source,
   (sup.actual->>'samples')::int AS lead_samples,
   (SELECT b.unit_cost FROM public.stock_batches b WHERE b.stock_item_id=p.stock_item_id AND b.unit_cost IS NOT NULL ORDER BY b.received_at DESC NULLS LAST LIMIT 1) AS last_cost,
   (SELECT b.currency::text FROM public.stock_batches b WHERE b.stock_item_id=p.stock_item_id AND b.unit_cost IS NOT NULL ORDER BY b.received_at DESC NULLS LAST LIMIT 1) AS last_cost_currency
  FROM pairs p JOIN public.stock_items si ON si.id=p.stock_item_id
  LEFT JOIN public.stock_reorder_points brp ON brp.stock_item_id=p.stock_item_id AND brp.warehouse_id=p.warehouse_id
  LEFT JOIN LATERAL (
   SELECT ps.supplier_id, s.name AS supplier_name, ps.typical_lead_days AS lead_days, ps.last_quoted_unit_cost AS unit_cost, ps.currency::text AS currency,
          private.supplier_lead_days(ps.supplier_id, p.stock_item_id) AS actual
   FROM public.supplier_preferred_skus ps JOIN public.suppliers s ON s.id=ps.supplier_id
   WHERE ps.stock_item_id=p.stock_item_id AND ps.is_active AND s.is_active
   ORDER BY s.is_preferred DESC, ps.last_quoted_unit_cost ASC NULLS LAST LIMIT 1) sup ON true
 ), calc AS (
  SELECT f.*,
   round((f.sold + f.lost) / v_days, 3) AS daily,
   COALESCE(f.own_rop, ceil(((f.sold + f.lost) / v_days) * (COALESCE(f.lead_days, p_lead_days) + p_safety_days))) AS rop,
   f.available + f.on_order + f.transfer_in - f.transfer_out - f.backordered AS position
  FROM facts f
 ), need AS (
  SELECT c.*,
   CASE WHEN (c.daily > 0 OR c.own_rop IS NOT NULL OR c.backordered > 0) AND c.position <= c.rop
        THEN GREATEST(1, ceil(c.rop + GREATEST(COALESCE(c.reorder_qty,0), c.daily * p_cover_days) - c.position)) ELSE 0 END AS qty_needed,
   -- What this branch could give away: free stock above its own reorder point and next cover period.
   GREATEST(0, floor(c.available - c.transfer_out - c.rop - c.daily * p_cover_days)) AS spare
  FROM calc c
 ), plan AS (
  SELECT n.*,
   (SELECT jsonb_build_object('warehouse_id', o.warehouse_id, 'warehouse', w.name, 'spare', o.spare)
      FROM need o JOIN wh w ON w.id=o.warehouse_id
     WHERE o.stock_item_id=n.stock_item_id AND o.warehouse_id<>n.warehouse_id AND o.spare>0
     ORDER BY o.spare DESC LIMIT 1) AS donor
  FROM need n
 )
 SELECT jsonb_build_object(
  'generated_at', now(),
  'settings', jsonb_build_object('sales_days', v_days, 'lead_days', p_lead_days, 'safety_days', p_safety_days, 'cover_days', p_cover_days),
  'suggestions', COALESCE((SELECT jsonb_agg(jsonb_build_object(
     'stock_item_id', p.stock_item_id, 'uom_id', p.base_uom_id, 'oem_part_number', p.oem_part_number, 'description', p.description,
     'warehouse_id', p.warehouse_id, 'warehouse', (SELECT w.name FROM wh w WHERE w.id=p.warehouse_id),
     'on_hand', p.on_hand, 'available', p.available, 'on_order', p.on_order, 'in_draft', p.in_draft, 'transfer_in', p.transfer_in, 'backordered', p.backordered,
     'sold', p.sold, 'lost', p.lost, 'daily', p.daily, 'days_of_cover', CASE WHEN p.daily > 0 THEN round(GREATEST(p.available,0) / p.daily, 1) END,
     'reorder_point', p.rop, 'reorder_point_source', COALESCE(p.rop_source, 'from_sales'), 'reorder_qty', p.reorder_qty,
     'qty_needed', p.qty_needed,
     'transfer_qty', LEAST(p.qty_needed, COALESCE((p.donor->>'spare')::numeric,0)),
     'transfer_from', p.donor,
     'buy_qty', p.qty_needed - LEAST(p.qty_needed, COALESCE((p.donor->>'spare')::numeric,0)),
     'supplier_id', p.supplier_id, 'supplier', p.supplier_name, 'lead_days', COALESCE(p.lead_days, p_lead_days), 'lead_source', COALESCE(p.lead_source, 'default'), 'lead_samples', p.lead_samples,
     'unit_cost', COALESCE(p.supplier_cost, p.last_cost), 'cost_currency', COALESCE(p.supplier_currency, p.last_cost_currency),
     'urgency', CASE WHEN p.available <= 0 OR p.backordered > 0 THEN 'out'
                     WHEN p.daily > 0 AND p.available / p.daily < COALESCE(p.lead_days, p_lead_days) THEN 'before_delivery'
                     ELSE 'low' END)
     ORDER BY CASE WHEN p.available <= 0 OR p.backordered > 0 THEN 0 ELSE 1 END,
              CASE WHEN p.daily > 0 THEN p.available / p.daily ELSE 999999 END, p.oem_part_number)
   FROM plan p WHERE p.qty_needed > 0 AND (p_warehouse_id IS NULL OR p.warehouse_id=p_warehouse_id)), '[]'::jsonb),
  'slow_stock', COALESCE((SELECT jsonb_agg(x ORDER BY (x->>'value')::numeric DESC NULLS LAST) FROM (
     SELECT jsonb_build_object('stock_item_id', p.stock_item_id, 'uom_id', p.base_uom_id, 'oem_part_number', p.oem_part_number, 'description', p.description,
       'warehouse_id', p.warehouse_id, 'warehouse', (SELECT w.name FROM wh w WHERE w.id=p.warehouse_id), 'on_hand', p.on_hand, 'available', p.available,
       'last_sold_at', p.last_sold_at, 'value', round(p.on_hand * COALESCE(p.last_cost,0),2), 'currency', p.last_cost_currency,
       -- Another branch sold it recently: move what it would sell over the cover period there.
       'move_to', mv.dest, 'move_qty', CASE WHEN mv.dest IS NOT NULL THEN LEAST(floor(GREATEST(p.available,0)), GREATEST(1, ceil((mv.dest->>'daily')::numeric * p_cover_days))) END,
       -- Nobody sells it: mark it down, more the longer it has sat.
       'markdown_pct', CASE WHEN mv.dest IS NOT NULL THEN NULL
                            WHEN p.last_sold_at IS NULL OR p.last_sold_at < now() - interval '365 days' THEN 30
                            WHEN p.last_sold_at < now() - interval '180 days' THEN 20 ELSE 10 END) x
     FROM plan p
     LEFT JOIN LATERAL (
      SELECT jsonb_build_object('warehouse_id', o.warehouse_id, 'warehouse', w.name, 'sold', o.sold, 'daily', o.daily) AS dest
        FROM plan o JOIN wh w ON w.id=o.warehouse_id
       WHERE o.stock_item_id=p.stock_item_id AND o.warehouse_id<>p.warehouse_id AND o.daily > 0
       ORDER BY o.daily DESC LIMIT 1) mv ON true
     WHERE p.on_hand > 0 AND (p.last_sold_at IS NULL OR p.last_sold_at < now() - interval '90 days')
       AND (p_warehouse_id IS NULL OR p.warehouse_id=p_warehouse_id)
     ORDER BY p.on_hand * COALESCE(p.last_cost,0) DESC LIMIT 20) q), '[]'::jsonb)
 ) INTO v_out;
 RETURN v_out;
END $$;


--
-- Name: get_zig_exchange_rate(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_zig_exchange_rate(p_as_of date DEFAULT CURRENT_DATE) RETURNS numeric
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_rate NUMERIC;
BEGIN
  SELECT r.rate INTO v_rate
  FROM public.daily_exchange_rates r
  WHERE r.currency = 'ZIG'
    AND r.rate_date <= COALESCE(p_as_of, CURRENT_DATE)
  ORDER BY r.rate_date DESC
  LIMIT 1;

  IF v_rate IS NULL OR v_rate <= 0 THEN
    RETURN NULL;
  END IF;
  RETURN v_rate;
END;
$$;


--
-- Name: gl_account_for_payment_tender(public.payment_tender); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gl_account_for_payment_tender(p_tender public.payment_tender) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_code TEXT;
BEGIN
  SELECT account_code INTO v_code
  FROM public.payment_tender_gl_accounts
  WHERE tender = p_tender;
  IF v_code IS NULL THEN
    RETURN CASE p_tender
      WHEN 'cash' THEN '1120'
      WHEN 'bank' THEN '1100'
      WHEN 'contipay' THEN '1140'
      WHEN 'paynow' THEN '1150'
      WHEN 'ecocash' THEN '1160'
      WHEN 'store_credit' THEN '2200'
      ELSE '1100'
    END;
  END IF;
  RETURN v_code;
END;
$$;


--
-- Name: guard_consignment_entry_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_consignment_entry_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status IS DISTINCT FROM 'draft' THEN
      RAISE EXCEPTION 'consignment_entries: new rows must be draft; use RPCs';
    END IF;
    IF current_setting('gtr.consignment_rpc', true) IS DISTINCT FROM 'on' THEN
      RAISE EXCEPTION 'consignment_entries: use create_consignment_entry_draft RPC';
    END IF;
  ELSIF TG_OP = 'UPDATE' THEN
    IF current_setting('gtr.consignment_rpc', true) IS DISTINCT FROM 'on' THEN
      RAISE EXCEPTION 'consignment_entries: use consignment RPCs';
    END IF;
  ELSIF TG_OP = 'DELETE' THEN
    IF current_setting('gtr.consignment_rpc', true) IS DISTINCT FROM 'on' THEN
      RAISE EXCEPTION 'consignment_entries: direct delete forbidden';
    END IF;
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: guard_consignment_entry_lines_draft(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_consignment_entry_lines_draft() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_status public.procurement_doc_status;
BEGIN
  IF current_setting('gtr.consignment_rpc', true) IS DISTINCT FROM 'on' THEN
    RAISE EXCEPTION 'consignment_entry_lines: use consignment RPCs';
  END IF;
  SELECT status INTO v_status
  FROM public.consignment_entries
  WHERE id = COALESCE(NEW.consignment_entry_id, OLD.consignment_entry_id);
  IF v_status IS DISTINCT FROM 'draft' THEN
    RAISE EXCEPTION 'consignment_entry_lines: parent must be draft (status=%)', v_status;
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: guard_delivery_job_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_delivery_job_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  IF public._logistics_rpc_active() THEN
    IF TG_OP = 'DELETE' THEN
      RETURN OLD;
    END IF;
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    RAISE EXCEPTION 'delivery_jobs: use create_delivery_job RPC';
  ELSIF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'delivery_jobs: direct delete not allowed';
  ELSIF TG_OP = 'UPDATE' THEN
    IF OLD.status IN ('completed', 'failed') THEN
      RAISE EXCEPTION 'delivery_jobs: terminal jobs are immutable';
    END IF;
    RAISE EXCEPTION
      'delivery_jobs: use update_delivery_job_status / set_delivery_job_geo / assign RPCs';
  END IF;

  RETURN NULL;
END;
$$;


