  SELECT pl.status INTO v_status
  FROM public.pick_lists pl
  WHERE pl.id = COALESCE(NEW.pick_list_id, OLD.pick_list_id);

  IF v_status IS DISTINCT FROM 'draft' THEN
    RAISE EXCEPTION 'pick_list_lines: parent must be draft (status=%)', v_status;
  END IF;

  RAISE EXCEPTION 'pick_list_lines: use pick list RPCs';
END;
$$;


--
-- Name: guard_pick_list_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_pick_list_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  IF public._logistics_rpc_active() THEN
    IF TG_OP = 'DELETE' THEN
      RETURN OLD;
    END IF;
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    RAISE EXCEPTION 'pick_lists: use create_pick_list RPC';
  ELSIF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'pick_lists: direct delete not allowed';
  ELSIF TG_OP = 'UPDATE' THEN
    IF OLD.status IN ('done', 'cancelled') AND NEW.status IS DISTINCT FROM OLD.status THEN
      RAISE EXCEPTION 'pick_lists: terminal pick lists are immutable';
    END IF;
    RAISE EXCEPTION 'pick_lists: use pick list RPCs for updates';
  END IF;

  RETURN NULL;
END;
$$;


--
-- Name: guard_posted_payment_cancellation_authority(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_posted_payment_cancellation_authority() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF OLD.status='posted'::public.payment_entry_status
     AND NEW.status='cancelled'::public.payment_entry_status
     AND NOT (
       COALESCE(auth.role(),'')='service_role'
       OR public.has_staff_role(ARRAY['admin','finance']::public.staff_role[])
     ) THEN
    RAISE EXCEPTION 'posted payment cancellation requires finance or admin role';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_procurement_doc_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_procurement_doc_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  IF public._procurement_rpc_active() THEN
    IF TG_OP = 'DELETE' THEN
      RETURN OLD;
    END IF;
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF NEW.status IS DISTINCT FROM 'draft' THEN
      RAISE EXCEPTION '%: new rows must be draft; use procurement RPCs', TG_TABLE_NAME;
    END IF;
    RAISE EXCEPTION '%: use procurement RPCs for insert', TG_TABLE_NAME;
  ELSIF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION '%: direct delete not allowed', TG_TABLE_NAME;
  ELSIF TG_OP = 'UPDATE' THEN
    IF OLD.status IN ('cancelled', 'rejected') THEN
      RAISE EXCEPTION '%: % records are immutable', TG_TABLE_NAME, OLD.status;
    END IF;
    RAISE EXCEPTION '%: use procurement RPCs for updates', TG_TABLE_NAME;
  END IF;

  RETURN NULL;
END;
$$;


