--
-- Name: handle_new_user(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_provider TEXT;
  v_name TEXT;
  v_retail UUID;
BEGIN
  INSERT INTO public.profiles (id, full_name, is_staff)
  VALUES (
    NEW.id,
    COALESCE(
      NEW.raw_user_meta_data ->> 'full_name',
      NEW.raw_user_meta_data ->> 'name'
    ),
    false
  )
  ON CONFLICT (id) DO NOTHING;

  v_provider := lower(coalesce(NEW.raw_app_meta_data ->> 'provider', ''));

  -- Google/Apple only. OTP Admin createUser applies custom app_metadata after
  -- AFTER INSERT, so auth_otp must mint via ensure_customer_for_user (Edge).
  IF v_provider IN ('google', 'apple') THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.customers c WHERE c.profile_id = NEW.id
    ) THEN
      SELECT pl.id INTO v_retail
      FROM public.price_lists pl
      WHERE pl.code = 'RETAIL' AND pl.is_active
      LIMIT 1;

      v_name := nullif(
        btrim(
          COALESCE(
            NEW.raw_user_meta_data ->> 'full_name',
            NEW.raw_user_meta_data ->> 'name',
            split_part(COALESCE(NEW.email, ''), '@', 1)
          )
        ),
        ''
      );
      IF v_name IS NULL THEN
        v_name := 'Customer';
      END IF;

      INSERT INTO public.customers (
        display_name,
        email,
        currency,
        profile_id,
        price_list_id
      )
      VALUES (
        v_name,
        NULLIF(NEW.email, ''),
        'USD',
        NEW.id,
        v_retail
      )
      ON CONFLICT (profile_id) WHERE (profile_id IS NOT NULL) DO NOTHING;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION handle_new_user(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.handle_new_user() IS 'After auth.users insert: ensure profiles row; for Google/Apple OAuth also insert a retail customers row (idempotent). OTP signup mints customers via ensure_customer_for_user — do not rely on gtr_provisioned_via here for Admin creates.';


--
-- Name: handover_pos_till_session(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handover_pos_till_session(p_session_id uuid, p_new_operator_user_id uuid, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE s public.pos_till_sessions%ROWTYPE;
BEGIN
 IF NOT public.is_pos_approver() THEN RAISE EXCEPTION 'POS manager approval required'; END IF;
 SELECT * INTO s FROM public.pos_till_sessions WHERE id=p_session_id FOR UPDATE;
 IF NOT FOUND OR s.status<>'open' THEN RAISE EXCEPTION 'open till session required'; END IF;
 IF p_new_operator_user_id IS NULL OR p_new_operator_user_id=s.operator_user_id THEN RAISE EXCEPTION 'different operator required'; END IF;
 IF NOT EXISTS(
  SELECT 1 FROM public.employees e JOIN public.staff_roles sr ON sr.user_id=e.user_id
  WHERE e.user_id=p_new_operator_user_id AND e.status='active' AND sr.role IN('sales','admin')
 ) THEN RAISE EXCEPTION 'active sales/admin operator required'; END IF;
 IF EXISTS(SELECT 1 FROM public.pos_till_sessions WHERE operator_user_id=p_new_operator_user_id AND status IN('open','variance_pending') AND id<>p_session_id) THEN
  RAISE EXCEPTION 'new operator already has an open till';
 END IF;
 UPDATE public.pos_till_sessions SET operator_user_id=p_new_operator_user_id,updated_at=now() WHERE id=p_session_id;
 INSERT INTO public.pos_till_session_events(session_id,event_type,actor_user_id,detail)
 VALUES(p_session_id,'handover',auth.uid(),jsonb_build_object('from_operator_user_id',s.operator_user_id,'to_operator_user_id',p_new_operator_user_id,'notes',p_notes));
 RETURN p_session_id;
END $$;


