--
-- Name: hook_before_user_created(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hook_before_user_created(event jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_provider text;
  v_via text;
begin
  v_provider := lower(coalesce(event->'user'->'app_metadata'->>'provider', ''));
  v_via := coalesce(event->'user'->'app_metadata'->>'gtr_provisioned_via', '');

  if v_provider in ('google', 'apple') then
    return '{}'::jsonb;
  end if;

  -- Canonical path is supabase_auth_edge. auth_otp remains accepted only for
  -- backward compatibility with accounts provisioned before the cutover.
  if v_via in ('supabase_auth_edge', 'auth_otp', 'hr_onboarding') then
    return '{}'::jsonb;
  end if;

  return jsonb_build_object(
    'error',
    jsonb_build_object(
      'message',
      'Public signup is disabled. Use the Nissan GTR Auto Supabase Auth flow or Google/Apple sign-in.',
      'http_code',
      403
    )
  );
end;
$$;


--
-- Name: FUNCTION hook_before_user_created(event jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.hook_before_user_created(event jsonb) IS 'Auth before-user-created hook: allow Google/Apple OAuth and Edge-provisioned email (gtr_provisioned_via=auth_otp|hr_onboarding); reject public GoTrue email signup.';


--
-- Name: ingest_delivery_location(uuid, double precision, double precision, timestamp with time zone, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ingest_delivery_location(p_delivery_job_id uuid, p_lat double precision, p_lng double precision, p_recorded_at timestamp with time zone DEFAULT now(), p_accuracy_m numeric DEFAULT NULL::numeric) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_job public.delivery_jobs%ROWTYPE;
  v_id UUID;
  v_uid UUID := auth.uid();
  v_allowed BOOLEAN := false;
BEGIN
  PERFORM public._logistics_begin_rpc();

  IF auth.role() = 'service_role'
     OR public.has_staff_role(
       ARRAY['admin', 'warehouse', 'dispatcher']::public.staff_role[]
     ) THEN
    v_allowed := true;
  END IF;

  SELECT * INTO v_job FROM public.delivery_jobs WHERE id = p_delivery_job_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'delivery job not found';
  END IF;
  IF v_job.status IN ('completed', 'failed') THEN
    RAISE EXCEPTION 'cannot ingest locations for terminal job';
  END IF;

  -- Assigned driver JWT (role driver + assignee match)
  IF NOT v_allowed
     AND v_uid IS NOT NULL
     AND v_job.assignee_user_id = v_uid
     AND public.has_staff_role(ARRAY['driver']::public.staff_role[]) THEN
    v_allowed := true;
  END IF;

  IF NOT v_allowed THEN
    RAISE EXCEPTION
      'bridge/service, dispatcher/warehouse/admin, or assigned driver required for GPS ingest';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.delivery_locations
    WHERE delivery_job_id = p_delivery_job_id
      AND ingested_at > now() - interval '5 seconds'
  ) THEN
    RAISE EXCEPTION 'ingest rate limit: wait ~5s between points';
  END IF;

  INSERT INTO public.delivery_locations (
    delivery_job_id, lat, lng, accuracy_m, recorded_at, source
  )
  VALUES (
    p_delivery_job_id, p_lat, p_lng, p_accuracy_m,
    COALESCE(p_recorded_at, now()), 'bridge'
  )
  RETURNING id INTO v_id;

  -- Refresh driver_presence last_* for assignee when known
  IF v_job.assignee_user_id IS NOT NULL THEN
    INSERT INTO public.driver_presence AS dp (
      user_id, status, last_lat, last_lng, last_seen_at, updated_at
    )
    VALUES (
      v_job.assignee_user_id,
      'on_duty',
      p_lat,
      p_lng,
      now(),
      now()
    )
    ON CONFLICT (user_id) DO UPDATE
    SET
      last_lat = EXCLUDED.last_lat,
      last_lng = EXCLUDED.last_lng,
      last_seen_at = EXCLUDED.last_seen_at,
      updated_at = now(),
      status = CASE
        WHEN dp.status = 'offline' THEN 'on_duty'::public.driver_presence_status
        ELSE dp.status
      END;
  END IF;

  PERFORM public._recompute_delivery_eta_haversine(p_delivery_job_id, p_lat, p_lng);

  RETURN v_id;
END;
$$;


--
-- Name: insert_ai_promo_delivery(uuid, uuid, public.ai_delivery_channel, text, public.ai_delivery_status, text, text[], text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.insert_ai_promo_delivery(p_run_id uuid, p_customer_id uuid, p_channel public.ai_delivery_channel, p_recipient text, p_status public.ai_delivery_status, p_body_preview text, p_oem_skus text[], p_vehicle_label text, p_provider_ref text DEFAULT NULL::text, p_error text DEFAULT NULL::text, p_gemini_used boolean DEFAULT false) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id UUID;
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'service_role required';
  END IF;
  INSERT INTO public.ai_promo_deliveries (
    run_id, customer_id, channel, recipient, status, body_preview,
    oem_skus, vehicle_label, provider_ref, error, gemini_used, sent_at
  ) VALUES (
    p_run_id, p_customer_id, p_channel, p_recipient, p_status, p_body_preview,
    COALESCE(p_oem_skus, '{}'::text[]), p_vehicle_label, p_provider_ref, p_error,
    COALESCE(p_gemini_used, false),
    CASE WHEN p_status = 'sent' THEN now() ELSE NULL END
  )
  RETURNING id INTO v_id;

  IF p_status = 'sent' THEN
    UPDATE public.customers
    SET last_promotional_message_at = now(), updated_at = now()
    WHERE id = p_customer_id;
  END IF;

  RETURN v_id;
END;
$$;


