--
-- Name: issue_approval_badge(uuid, uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.issue_approval_badge(p_employee_id uuid DEFAULT NULL::uuid, p_user_id uuid DEFAULT NULL::uuid, p_label text DEFAULT NULL::text, p_valid_days integer DEFAULT 365) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_secret text; v_id uuid := gen_random_uuid(); v_expires timestamptz; v_name text; v_code text; v_grade text; v_role text;
BEGIN
  PERFORM private.require_approver_admin();
  IF (p_employee_id IS NULL) = (p_user_id IS NULL) THEN RAISE EXCEPTION 'one badge holder required (employee or user)'; END IF;
  IF private.badge_holder_source(p_employee_id, p_user_id) IS NULL THEN RAISE EXCEPTION 'only a manager or an assigned approver can hold an approval badge'; END IF;
  IF COALESCE(p_valid_days, 0) < 1 OR p_valid_days > 1095 THEN RAISE EXCEPTION 'badge validity must be 1 to 1095 days'; END IF;
  v_secret := translate(encode(extensions.gen_random_bytes(32), 'base64'), '+/=', '-_');
  v_expires := now() + make_interval(days => p_valid_days);
  INSERT INTO public.staff_approval_badges(id, employee_id, user_id, label, token_sha256, issued_by, expires_at)
  VALUES (v_id, p_employee_id, p_user_id, NULLIF(trim(COALESCE(p_label, '')), ''), encode(extensions.digest(v_secret, 'sha256'), 'hex'), auth.uid(), v_expires);
  INSERT INTO public.staff_approver_admin_events(actor_id, event, employee_id, user_id, badge_id, notes)
  VALUES (auth.uid(), 'badge_issued', p_employee_id, p_user_id, v_id, p_label);
  IF p_employee_id IS NOT NULL THEN
    SELECT e.full_name, e.employee_code::text, g.title, r.title INTO v_name, v_code, v_grade, v_role
    FROM public.employees e LEFT JOIN public.hr_grades g ON g.id = e.grade_id LEFT JOIN public.hr_roles r ON r.id = e.hr_role_id
    WHERE e.id = p_employee_id;
  ELSE
    SELECT u.email::text, 'Administrator' INTO v_name, v_role FROM auth.users u WHERE u.id = p_user_id;
  END IF;
  RETURN jsonb_build_object('badge_id', v_id, 'payload', 'GTRMGR1:' || v_id::text || ':' || v_secret, 'expires_at', v_expires,
    'full_name', v_name, 'employee_code', v_code, 'title', COALESCE(v_role, v_grade));
END $$;


--
-- Name: issue_auth_challenge(text, text, text, text, timestamp with time zone, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.issue_auth_challenge(p_kind text, p_channel text, p_identifier text, p_code_hash text, p_expires_at timestamp with time zone, p_ip_hash text DEFAULT NULL::text, p_device_hash text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_kind text := lower(trim(coalesce(p_kind,'')));
  v_channel text := lower(trim(coalesce(p_channel,'')));
  v_identifier text := lower(trim(coalesce(p_identifier,'')));
  v_now timestamptz := clock_timestamp();
  v_last timestamptz;
  v_id uuid;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'service_role required';
  end if;
  if v_kind not in ('auth_otp','password_reset') then raise exception 'invalid challenge kind'; end if;
  if v_channel not in ('email','phone') then raise exception 'invalid challenge channel'; end if;
  if v_identifier='' or coalesce(trim(p_code_hash),'')='' then raise exception 'identifier/code hash required'; end if;
  if p_expires_at is null or p_expires_at <= v_now or p_expires_at > v_now + interval '30 minutes' then
    raise exception 'invalid challenge expiry';
  end if;

  perform public._consume_auth_rate_limit(v_kind||':request:identifier',v_channel||':'||v_identifier,5,900);
  if coalesce(trim(p_ip_hash),'')<>'' then
    perform public._consume_auth_rate_limit(v_kind||':request:ip',trim(p_ip_hash),30,900);
  end if;
  if coalesce(trim(p_device_hash),'')<>'' then
    perform public._consume_auth_rate_limit(v_kind||':request:device',trim(p_device_hash),20,900);
  end if;
  perform public._consume_auth_rate_limit(v_kind||':request:global','global',300,60);

  perform pg_advisory_xact_lock(hashtextextended(v_kind||':'||v_channel||':'||v_identifier,0));

  if v_kind='auth_otp' then
    select max(created_at) into v_last from public.auth_otp_challenges
      where channel=v_channel and identifier=v_identifier;
  else
    select max(created_at) into v_last from public.password_reset_challenges
      where channel=v_channel and identifier=v_identifier;
  end if;
  if v_last is not null and v_last > v_now - interval '60 seconds' then
    raise exception 'AUTH_RESEND_COOLDOWN retry_after_seconds=%', greatest(1,ceil(extract(epoch from (v_last + interval '60 seconds' - v_now)))::integer);
  end if;

  if v_kind='auth_otp' then
    update public.auth_otp_challenges
      set expires_at=least(expires_at,v_now)
      where channel=v_channel and identifier=v_identifier and consumed_at is null and expires_at>v_now;
    insert into public.auth_otp_challenges(channel,identifier,code_hash,expires_at,attempt_count)
      values(v_channel,v_identifier,p_code_hash,p_expires_at,0) returning id into v_id;
  else
    update public.password_reset_challenges
      set expires_at=least(expires_at,v_now)
      where channel=v_channel and identifier=v_identifier and consumed_at is null and expires_at>v_now;
    insert into public.password_reset_challenges(channel,identifier,code_hash,expires_at,attempt_count)
      values(v_channel,v_identifier,p_code_hash,p_expires_at,0) returning id into v_id;
  end if;
  return v_id;
end;
$$;


--
-- Name: issue_store_credit(uuid, numeric, public.currency_code, numeric, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.issue_store_credit(p_customer_id uuid, p_amount numeric, p_currency public.currency_code DEFAULT 'USD'::public.currency_code, p_exchange_rate numeric DEFAULT 1, p_reason text DEFAULT NULL::text, p_debit_account text DEFAULT '1100'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_journal UUID;
  v_ledger UUID;
  v_debit TEXT;
BEGIN
  IF NOT (
    auth.role() = 'service_role'
    OR public.has_staff_role(ARRAY['admin','finance']::public.staff_role[])
    OR public._sales_checkout_accounting_active()
  ) THEN
    RAISE EXCEPTION 'finance or admin role required to issue store credit';
  END IF;
  PERFORM public._payments_rpc_enter();

  IF p_customer_id IS NULL THEN
    RAISE EXCEPTION 'customer_id required';
  END IF;
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION 'issue amount must be > 0';
  END IF;
  IF p_currency='ZIG' AND (p_exchange_rate IS NULL OR p_exchange_rate<=0) THEN
    RAISE EXCEPTION 'exchange_rate_applied required for ZIG';
  END IF;

  v_debit := COALESCE(NULLIF(p_debit_account, ''), '1100');
  IF v_debit NOT IN ('1100', '1200') THEN
    RAISE EXCEPTION 'issue_store_credit debit must be 1100 or 1200';
  END IF;

  v_journal := public.post_journal_entry(
    CURRENT_DATE,
    COALESCE(p_reason, 'Store credit issued'),
    p_currency,
    CASE WHEN p_currency='USD' THEN COALESCE(p_exchange_rate,1) ELSE p_exchange_rate END,
    jsonb_build_array(
      jsonb_build_object('account_code',v_debit,'debit',p_amount,'credit',0,'currency',p_currency),
      jsonb_build_object('account_code','2200','debit',0,'credit',p_amount,'currency',p_currency)
    )
  );

  v_ledger := public._append_store_credit(
    p_customer_id,'issue',p_amount,p_currency,
    CASE WHEN p_currency='USD' THEN COALESCE(p_exchange_rate,1) ELSE p_exchange_rate END,
    NULL,v_journal,COALESCE(p_reason,'Store credit issued')
  );

  PERFORM public.emit_domain_event(
    'refund_issued',
    'sc:issue:' || v_ledger::text,
    jsonb_build_object('ledger_id',v_ledger,'customer_id',p_customer_id,'amount',p_amount,'currency',p_currency),
    auth.uid(),
    format('GTR Auto: store credit issued %s %s',p_amount,p_currency)
  );
  RETURN v_ledger;
END;
$$;


--
-- Name: kpi_ar_aging_snapshot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kpi_ar_aging_snapshot() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_buckets JSONB;
  v_open_customers BIGINT;
  v_open_balance_by_currency JSONB;
BEGIN
  PERFORM public._assert_ai_analytics_staff();

  -- Age unpaid invoice balances by posted_at (aggregates only; no customer ids)
  SELECT COALESCE(jsonb_agg(row_to_json(t)::jsonb ORDER BY t.bucket), '[]'::jsonb)
  INTO v_buckets
  FROM (
    SELECT
      b.bucket,
      b.currency,
      COUNT(*)::bigint AS invoice_count,
      COALESCE(SUM(b.open_amt), 0)::numeric AS open_amount
    FROM (
      SELECT
        si.currency::text AS currency,
        GREATEST(si.total - si.amount_paid, 0)::numeric AS open_amt,
        CASE
          WHEN si.posted_at >= now() - INTERVAL '30 days' THEN '0_30'
          WHEN si.posted_at >= now() - INTERVAL '60 days' THEN '31_60'
          WHEN si.posted_at >= now() - INTERVAL '90 days' THEN '61_90'
          ELSE '90_plus'
        END AS bucket
      FROM public.sales_invoices si
      WHERE si.doc_type = 'invoice'
        AND si.status = 'posted'
        AND (si.total - si.amount_paid) > 0
    ) b
    GROUP BY b.bucket, b.currency
  ) t;

  SELECT COUNT(*)::bigint INTO v_open_customers
  FROM public.customers c
  WHERE c.open_balance > 0;

  SELECT COALESCE(jsonb_agg(row_to_json(t)::jsonb ORDER BY t.currency), '[]'::jsonb)
  INTO v_open_balance_by_currency
  FROM (
    SELECT
      c.currency::text AS currency,
      COUNT(*) FILTER (WHERE c.open_balance > 0)::bigint AS customer_count,
      COALESCE(SUM(c.open_balance), 0)::numeric AS open_balance
    FROM public.customers c
    GROUP BY c.currency
  ) t;

  RETURN jsonb_build_object(
    'as_of', now(),
    'customers_with_open_balance', v_open_customers,
    'customer_open_balance_by_currency', v_open_balance_by_currency,
    'invoice_aging_buckets', v_buckets
  );
END;
$$;


--
-- Name: kpi_credit_holds_summary(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kpi_credit_holds_summary() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_held_customers BIGINT;
  v_on_hold_invoices BIGINT;
  v_on_hold_by_currency JSONB;
BEGIN
  PERFORM public._assert_ai_analytics_staff();

  SELECT COUNT(*)::bigint INTO v_held_customers
  FROM public.customers c
  WHERE c.credit_hold;

  SELECT COUNT(*)::bigint INTO v_on_hold_invoices
  FROM public.sales_invoices si
  WHERE si.status = 'on_hold'
    AND si.doc_type = 'invoice';

  SELECT COALESCE(jsonb_agg(row_to_json(t)::jsonb ORDER BY t.currency), '[]'::jsonb)
  INTO v_on_hold_by_currency
  FROM (
    SELECT
      si.currency::text AS currency,
      COUNT(*)::bigint AS invoice_count,
      COALESCE(SUM(si.total), 0)::numeric AS total
    FROM public.sales_invoices si
    WHERE si.status = 'on_hold'
      AND si.doc_type = 'invoice'
    GROUP BY si.currency
  ) t;

  RETURN jsonb_build_object(
    'customers_on_credit_hold', v_held_customers,
    'invoices_on_hold', v_on_hold_invoices,
    'on_hold_by_currency', v_on_hold_by_currency
  );
END;
$$;


--
-- Name: kpi_finance_performance_v1(timestamp with time zone, timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kpi_finance_performance_v1(p_from timestamp with time zone, p_to timestamp with time zone, p_top_expenses integer DEFAULT 8) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_from_d DATE;
  v_to_d DATE;
  v_income NUMERIC := 0;
  v_expense NUMERIC := 0;
  v_by_type JSONB;
  v_top_expenses JSONB;
  v_sales JSONB;
  v_ar JSONB;
BEGIN
  PERFORM public._assert_ai_finance_staff();
  IF p_from IS NULL OR p_to IS NULL OR p_to <= p_from THEN
    RAISE EXCEPTION 'valid p_from / p_to required';
  END IF;

  v_from_d := (p_from AT TIME ZONE 'UTC')::date;
  v_to_d := ((p_to - INTERVAL '1 second') AT TIME ZONE 'UTC')::date;

  SELECT COALESCE(SUM(amount_usd) FILTER (WHERE account_type = 'income'), 0),
         COALESCE(SUM(-amount_usd) FILTER (WHERE account_type = 'expense'), 0)
  INTO v_income, v_expense
  FROM public.report_profit_and_loss(v_from_d, v_to_d, NULL);

  SELECT COALESCE(jsonb_agg(row_to_json(t)::jsonb ORDER BY t.account_type, t.account_code), '[]'::jsonb)
  INTO v_by_type
  FROM (
    SELECT
      account_code,
      account_name,
      account_type::text,
      amount,
      amount_usd
    FROM public.report_profit_and_loss(v_from_d, v_to_d, NULL)
  ) t;

  SELECT COALESCE(jsonb_agg(row_to_json(t)::jsonb), '[]'::jsonb)
  INTO v_top_expenses
  FROM (
    SELECT
      account_code,
      account_name,
      (-amount_usd)::numeric AS expense_usd
    FROM public.report_profit_and_loss(v_from_d, v_to_d, NULL)
    WHERE account_type = 'expense'
    ORDER BY (-amount_usd) DESC
    LIMIT GREATEST(1, LEAST(COALESCE(p_top_expenses, 8), 25))
  ) t;

  -- Sales / AR reuse analytics helpers (admin|finance pass _assert_ai_analytics_staff)
  v_sales := public.kpi_sales_summary(p_from, p_to);
  v_ar := public.kpi_ar_aging_snapshot();

  RETURN jsonb_build_object(
    'kpi_set', 'finance_performance_v1',
    'period_from', p_from,
    'period_to', p_to,
    'income_usd', v_income,
    'expense_usd', v_expense,
    'net_profit_usd', v_income - v_expense,
    'net_margin_pct', CASE
      WHEN v_income = 0 THEN NULL
      ELSE round(((v_income - v_expense) / NULLIF(v_income, 0)) * 100, 2)
    END,
    'pnl_by_account', v_by_type,
    'top_expense_accounts', v_top_expenses,
    'sales', v_sales,
    'ar_aging', v_ar,
    'note', 'Aggregates only; tax-agnostic; no journal line dumps'
  );
END;
$$;


--
-- Name: kpi_inventory_summary(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kpi_inventory_summary() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_on_hand NUMERIC;
  v_low_stock BIGINT;
  v_stockouts BIGINT;
  v_quarantine NUMERIC;
BEGIN
  PERFORM public._assert_ai_analytics_staff();

  SELECT COALESCE(SUM(sl.quantity), 0)
  INTO v_on_hand
  FROM public.stock_levels sl
  JOIN public.warehouses w ON w.id = sl.warehouse_id
  WHERE w.is_active AND NOT w.is_quarantine;

  SELECT COUNT(*)::bigint
  INTO v_low_stock
  FROM public.stock_items si
  JOIN public.stock_levels sl ON sl.stock_item_id = si.id
  JOIN public.warehouses w ON w.id = sl.warehouse_id
  WHERE w.is_active
    AND NOT w.is_quarantine
    AND si.reorder_point IS NOT NULL
    AND sl.quantity > 0
    AND sl.quantity <= si.reorder_point;

  SELECT COUNT(*)::bigint
  INTO v_stockouts
  FROM public.stock_items si
  JOIN public.stock_levels sl ON sl.stock_item_id = si.id
  JOIN public.warehouses w ON w.id = sl.warehouse_id
  WHERE w.is_active
    AND NOT w.is_quarantine
    AND sl.quantity = 0
    AND (
      si.reorder_point IS NOT NULL
      OR EXISTS (
        SELECT 1
        FROM public.stock_levels sl2
        WHERE sl2.stock_item_id = si.id
          AND sl2.quantity > 0
      )
    );

  SELECT COALESCE(SUM(sl.quantity), 0)
  INTO v_quarantine
  FROM public.stock_levels sl
  JOIN public.warehouses w ON w.id = sl.warehouse_id
  WHERE w.is_active AND w.is_quarantine;

  RETURN jsonb_build_object(
    'on_hand_qty', v_on_hand,
    'low_stock_count', v_low_stock,
    'stockout_count', v_stockouts,
    'quarantine_qty', v_quarantine
  );
END;
$$;


--
-- Name: kpi_open_deliveries_summary(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kpi_open_deliveries_summary() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_open_dns BIGINT;
  v_open_jobs BIGINT;
  v_jobs_by_status JSONB;
BEGIN
  PERFORM public._assert_ai_analytics_staff();

  SELECT COUNT(*)::bigint INTO v_open_dns
  FROM public.delivery_notes dn
  WHERE dn.status = 'draft';

  SELECT COUNT(*)::bigint INTO v_open_jobs
  FROM public.delivery_jobs dj
  WHERE dj.status IN ('pending', 'dispatched');

  SELECT COALESCE(jsonb_agg(row_to_json(t)::jsonb ORDER BY t.status), '[]'::jsonb)
  INTO v_jobs_by_status
  FROM (
    SELECT
      dj.status::text AS status,
      COUNT(*)::bigint AS job_count
    FROM public.delivery_jobs dj
    WHERE dj.status IN ('pending', 'dispatched')
    GROUP BY dj.status
  ) t;

  RETURN jsonb_build_object(
    'open_delivery_notes_draft', v_open_dns,
    'open_delivery_jobs', v_open_jobs,
    'jobs_by_status', v_jobs_by_status
  );
END;
$$;


--
-- Name: kpi_ops_sales_v1(timestamp with time zone, timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kpi_ops_sales_v1(p_from timestamp with time zone, p_to timestamp with time zone, p_top_limit integer DEFAULT 10) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM public._assert_ai_analytics_staff();
  RETURN jsonb_build_object(
    'kpi_set', 'ops_sales_v1',
    'period_from', p_from,
    'period_to', p_to,
    'sales', public.kpi_sales_summary(p_from, p_to),
    'returns', public.kpi_returns_summary(p_from, p_to),
    'top_skus', public.kpi_top_skus(p_from, p_to, p_top_limit),
    'inventory', public.kpi_inventory_summary(),
    'ar_aging', public.kpi_ar_aging_snapshot(),
    'credit_holds', public.kpi_credit_holds_summary(),
    'open_deliveries', public.kpi_open_deliveries_summary()
  );
END;
$$;


--
-- Name: kpi_returns_summary(timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kpi_returns_summary(p_from timestamp with time zone, p_to timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_by_currency JSONB;
  v_cn_count BIGINT;
BEGIN
  PERFORM public._assert_ai_analytics_staff();
  IF p_from IS NULL OR p_to IS NULL OR p_to <= p_from THEN
    RAISE EXCEPTION 'valid p_from / p_to required';
  END IF;

  SELECT COUNT(*)::bigint INTO v_cn_count
  FROM public.sales_invoices si
  WHERE si.doc_type = 'credit_note'
    AND si.status = 'posted'
    AND si.posted_at >= p_from
    AND si.posted_at < p_to;

  SELECT COALESCE(jsonb_agg(row_to_json(t)::jsonb ORDER BY t.currency), '[]'::jsonb)
  INTO v_by_currency
  FROM (
    SELECT
      si.currency::text AS currency,
      COUNT(*)::bigint AS credit_note_count,
      COALESCE(SUM(si.total), 0)::numeric AS returns_total
    FROM public.sales_invoices si
    WHERE si.doc_type = 'credit_note'
      AND si.status = 'posted'
      AND si.posted_at >= p_from
      AND si.posted_at < p_to
    GROUP BY si.currency
  ) t;

  RETURN jsonb_build_object(
    'period_from', p_from,
    'period_to', p_to,
    'credit_note_count', v_cn_count,
    'by_currency', v_by_currency
  );
END;
$$;


--
-- Name: kpi_sales_summary(timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kpi_sales_summary(p_from timestamp with time zone, p_to timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_by_currency JSONB;
  v_order_count BIGINT;
  v_aov JSONB;
BEGIN
  PERFORM public._assert_ai_analytics_staff();
  IF p_from IS NULL OR p_to IS NULL OR p_to <= p_from THEN
    RAISE EXCEPTION 'valid p_from / p_to required';
  END IF;

  SELECT COALESCE(jsonb_agg(row_to_json(t)::jsonb ORDER BY t.currency), '[]'::jsonb)
  INTO v_by_currency
  FROM (
    SELECT
      si.currency::text AS currency,
      COUNT(*)::bigint AS invoice_count,
      COALESCE(SUM(si.total), 0)::numeric AS revenue,
      COALESCE(SUM(si.subtotal), 0)::numeric AS subtotal
    FROM public.sales_invoices si
    WHERE si.doc_type = 'invoice'
      AND si.status = 'posted'
      AND si.posted_at >= p_from
      AND si.posted_at < p_to
    GROUP BY si.currency
  ) t;

  SELECT COUNT(*)::bigint INTO v_order_count
  FROM public.sales_invoices si
  WHERE si.doc_type = 'invoice'
    AND si.status = 'posted'
    AND si.posted_at >= p_from
    AND si.posted_at < p_to;

  SELECT COALESCE(jsonb_agg(row_to_json(t)::jsonb ORDER BY t.currency), '[]'::jsonb)
  INTO v_aov
  FROM (
    SELECT
      si.currency::text AS currency,
      CASE
        WHEN COUNT(*) = 0 THEN 0::numeric
        ELSE ROUND(COALESCE(SUM(si.total), 0) / COUNT(*), 2)
      END AS average_order_value
    FROM public.sales_invoices si
    WHERE si.doc_type = 'invoice'
      AND si.status = 'posted'
      AND si.posted_at >= p_from
      AND si.posted_at < p_to
    GROUP BY si.currency
  ) t;

  RETURN jsonb_build_object(
    'period_from', p_from,
    'period_to', p_to,
    'order_count', v_order_count,
    'by_currency', v_by_currency,
    'average_order_value', v_aov
  );
END;
$$;


--
-- Name: kpi_stores_forecast_v1(uuid, timestamp with time zone, timestamp with time zone, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kpi_stores_forecast_v1(p_warehouse_id uuid, p_from timestamp with time zone DEFAULT (now() - '90 days'::interval), p_to timestamp with time zone DEFAULT now(), p_run_abc boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_abc_count INT := 0;
  v_latest TIMESTAMPTZ;
  v_class_counts JSONB;
  v_tier_a JSONB;
  v_tier_c JSONB;
  v_suggestions JSONB;
  v_on_hand NUMERIC := 0;
  v_low_stock BIGINT := 0;
BEGIN
  PERFORM public._assert_ai_stores_staff();
  IF p_warehouse_id IS NULL THEN
    RAISE EXCEPTION 'warehouse_id required';
  END IF;

  IF COALESCE(p_run_abc, true) THEN
    v_abc_count := public.run_inventory_abc_classification(p_from, p_to);
  END IF;

  SELECT MAX(as_of) INTO v_latest FROM public.inventory_abc_snapshots;

  SELECT COALESCE(jsonb_agg(row_to_json(t)::jsonb ORDER BY t.abc_class), '[]'::jsonb)
  INTO v_class_counts
  FROM (
    SELECT abc_class::text, COUNT(*)::bigint AS sku_count,
           COALESCE(SUM(revenue_usd), 0)::numeric AS revenue_usd
    FROM public.inventory_abc_snapshots
    WHERE as_of = v_latest
    GROUP BY abc_class
  ) t;

  SELECT COALESCE(jsonb_agg(row_to_json(t)::jsonb), '[]'::jsonb)
  INTO v_tier_a
  FROM (
    SELECT
      s.oem_part_number AS oem,
      s.qty_sold,
      s.revenue_usd,
      COALESCE(sl.quantity, 0)::numeric AS on_hand,
      si.reorder_point,
      si.reorder_qty
    FROM public.inventory_abc_snapshots s
    JOIN public.stock_items si ON si.id = s.stock_item_id
    LEFT JOIN public.stock_levels sl
      ON sl.stock_item_id = s.stock_item_id AND sl.warehouse_id = p_warehouse_id
    WHERE s.as_of = v_latest AND s.abc_class = 'A'
    ORDER BY s.revenue_usd DESC
    LIMIT 25
  ) t;

  SELECT COALESCE(jsonb_agg(row_to_json(t)::jsonb), '[]'::jsonb)
  INTO v_tier_c
  FROM (
    SELECT
      s.oem_part_number AS oem,
      s.qty_sold,
      s.revenue_usd,
      COALESCE(sl.quantity, 0)::numeric AS on_hand
    FROM public.inventory_abc_snapshots s
    LEFT JOIN public.stock_levels sl
      ON sl.stock_item_id = s.stock_item_id AND sl.warehouse_id = p_warehouse_id
    WHERE s.as_of = v_latest
      AND s.abc_class = 'C'
      AND COALESCE(sl.quantity, 0) > 0
    ORDER BY COALESCE(sl.quantity, 0) DESC, s.revenue_usd ASC
    LIMIT 25
  ) t;

  SELECT COALESCE(jsonb_agg(row_to_json(t)::jsonb), '[]'::jsonb)
  INTO v_suggestions
  FROM (
    SELECT
      fs.id,
      si.oem_part_number AS oem,
      fs.suggested_qty,
      fs.on_hand,
      fs.horizon_days,
      fs.reason,
      fs.status::text
    FROM public.forecast_suggestions fs
    JOIN public.stock_items si ON si.id = fs.stock_item_id
    WHERE fs.warehouse_id = p_warehouse_id
      AND fs.status = 'open'
    ORDER BY fs.created_at DESC
    LIMIT 50
  ) t;

  SELECT COALESCE(SUM(sl.quantity), 0) INTO v_on_hand
  FROM public.stock_levels sl
  WHERE sl.warehouse_id = p_warehouse_id;

  SELECT COUNT(*)::bigint INTO v_low_stock
  FROM public.stock_items si
  LEFT JOIN public.stock_levels sl
    ON sl.stock_item_id = si.id AND sl.warehouse_id = p_warehouse_id
  WHERE si.reorder_point IS NOT NULL
    AND COALESCE(sl.quantity, 0) <= si.reorder_point;

  RETURN jsonb_build_object(
    'kpi_set', 'stores_forecast_v1',
    'warehouse_id', p_warehouse_id,
    'period_from', p_from,
    'period_to', p_to,
    'abc_rows_written', v_abc_count,
    'abc_as_of', v_latest,
    'abc_class_counts', v_class_counts,
    'tier_a_fast_movers', v_tier_a,
    'tier_c_slow_movers', v_tier_c,
    'open_forecast_suggestions', v_suggestions,
    'warehouse_inventory', jsonb_build_object(
      'on_hand_qty', v_on_hand,
      'low_stock_count', v_low_stock
    )
  );
END;
$$;


--
-- Name: kpi_top_skus(timestamp with time zone, timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kpi_top_skus(p_from timestamp with time zone, p_to timestamp with time zone, p_limit integer DEFAULT 10) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_limit INT := GREATEST(1, LEAST(COALESCE(p_limit, 10), 50));
  v_rows JSONB;
BEGIN
  PERFORM public._assert_ai_analytics_staff();
  IF p_from IS NULL OR p_to IS NULL OR p_to <= p_from THEN
    RAISE EXCEPTION 'valid p_from / p_to required';
  END IF;

  SELECT COALESCE(jsonb_agg(row_to_json(t)::jsonb), '[]'::jsonb)
  INTO v_rows
  FROM (
    SELECT
      si.oem_part_number AS oem,
      COALESCE(SUM(sil.qty_base), 0)::numeric AS qty,
      sil_cur.currency,
      COALESCE(SUM(sil.line_total), 0)::numeric AS revenue
    FROM public.sales_invoice_lines sil
    JOIN public.sales_invoices inv ON inv.id = sil.invoice_id
    JOIN public.stock_items si ON si.id = sil.stock_item_id
    CROSS JOIN LATERAL (SELECT inv.currency::text AS currency) sil_cur
    WHERE inv.doc_type = 'invoice'
      AND inv.status = 'posted'
      AND inv.posted_at >= p_from
      AND inv.posted_at < p_to
      AND NOT sil.is_core_charge
    GROUP BY si.oem_part_number, sil_cur.currency
    ORDER BY SUM(sil.qty_base) DESC, SUM(sil.line_total) DESC
    LIMIT v_limit
  ) t;

  RETURN jsonb_build_object(
    'period_from', p_from,
    'period_to', p_to,
    'limit', v_limit,
    'items', v_rows
  );
END;
$$;


--
-- Name: lift_customer_suspension(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lift_customer_suspension(p_suspension_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE s public.customer_suspensions%ROWTYPE;
BEGIN
 IF NOT (public.has_staff_role(ARRAY['admin']::public.staff_role[]) OR public.is_pos_approver()) THEN
  RAISE EXCEPTION 'a manager must approve lifting a suspension'; END IF;
 IF trim(COALESCE(p_reason,''))='' THEN RAISE EXCEPTION 'say why the suspension is lifted'; END IF;
 SELECT * INTO s FROM public.customer_suspensions WHERE id=p_suspension_id FOR UPDATE;
 IF NOT FOUND OR s.status<>'active' THEN RAISE EXCEPTION 'active suspension required'; END IF;
 -- What the manager accepts is waived from the automatic rules: everything owing now, not just what triggered it.
 UPDATE public.customer_suspensions
 SET status='lifted', lifted_by=auth.uid(), lifted_at=now(), lift_reason=trim(p_reason),
     findings = (SELECT COALESCE(jsonb_agg(DISTINCT x),'[]'::jsonb) FROM jsonb_array_elements(s.findings || private.customer_suspension_findings(s.customer_id)) x)
 WHERE id=s.id RETURNING * INTO s;
 RETURN private._customer_suspension_json(s);
END $$;


--
-- Name: link_employee_auth_user(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.link_employee_auth_user(p_employee_id uuid, p_user_id uuid, p_phone_e164 text DEFAULT NULL::text, p_full_name text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_emp public.employees%ROWTYPE;
  v_staff_role public.staff_role;
  v_draft_payload JSONB;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'service_role required';
  END IF;

  IF p_employee_id IS NULL OR p_user_id IS NULL THEN
    RAISE EXCEPTION 'employee_id and user_id required';
  END IF;

  SELECT * INTO v_emp FROM public.employees WHERE id = p_employee_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'employee not found: %', p_employee_id;
  END IF;

  IF v_emp.user_id IS NOT NULL AND v_emp.user_id IS DISTINCT FROM p_user_id THEN
    RAISE EXCEPTION 'employee already linked to a different user';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.employees e
    WHERE e.user_id = p_user_id AND e.id IS DISTINCT FROM p_employee_id
  ) THEN
    RAISE EXCEPTION 'user already linked to another employee';
  END IF;

  UPDATE public.employees
  SET
    user_id = p_user_id,
    phone_e164 = COALESCE(NULLIF(trim(COALESCE(p_phone_e164, '')), ''), phone_e164),
    full_name = COALESCE(NULLIF(trim(COALESCE(p_full_name, '')), ''), full_name),
    updated_at = now()
  WHERE id = p_employee_id;

  UPDATE public.profiles
  SET
    must_change_password = true,
    phone_e164 = COALESCE(
      NULLIF(trim(COALESCE(p_phone_e164, '')), ''),
      phone_e164
    ),
    full_name = COALESCE(
      NULLIF(trim(COALESCE(p_full_name, '')), ''),
      full_name
    ),
    updated_at = now()
  WHERE id = p_user_id;

  SELECT d.payload INTO v_draft_payload
  FROM public.hr_onboarding_drafts d
  WHERE d.employee_id = p_employee_id
    AND d.completed_at IS NOT NULL
  ORDER BY d.completed_at DESC
  LIMIT 1;

  v_staff_role := public.resolve_hr_onboarding_staff_role(
    COALESCE(v_draft_payload, '{}'::jsonb),
    v_emp.hr_role_id
  );
  PERFORM public.apply_hr_onboarding_staff_role(p_user_id, v_staff_role);

  RETURN p_employee_id;
END;
$$;


--
-- Name: link_supplier_profile(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.link_supplier_profile(p_supplier_id uuid, p_profile_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF NOT (
    auth.role() = 'service_role'
    OR public.has_staff_role(ARRAY['admin']::public.staff_role[])
  ) THEN
    RAISE EXCEPTION 'admin role required';
  END IF;

  IF p_supplier_id IS NULL OR p_profile_id IS NULL THEN
    RAISE EXCEPTION 'supplier_id and profile_id required';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.profiles p WHERE p.id=p_profile_id) THEN
    RAISE EXCEPTION 'profile not found';
  END IF;

  UPDATE public.suppliers
  SET profile_id=p_profile_id,updated_at=now()
  WHERE id=p_supplier_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'supplier not found: %',p_supplier_id;
  END IF;
END;
$$;


--
-- Name: list_approval_badges(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_approval_badges() RETURNS TABLE(badge_id uuid, employee_id uuid, user_id uuid, full_name text, label text, issued_at timestamp with time zone, expires_at timestamp with time zone, revoked_at timestamp with time zone, revoke_reason text, last_used_at timestamp with time zone, use_count integer, status text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.staff_roles sr WHERE sr.user_id = auth.uid() AND sr.role IN ('admin','hr','finance')) THEN
    RAISE EXCEPTION 'admin, HR or finance role required';
  END IF;
  RETURN QUERY
  SELECT b.id, b.employee_id, b.user_id, COALESCE(e.full_name, u.email::text), b.label, b.issued_at, b.expires_at, b.revoked_at, b.revoke_reason,
         b.last_used_at, b.use_count,
         CASE WHEN b.revoked_at IS NOT NULL THEN 'revoked' WHEN b.expires_at <= now() THEN 'expired' ELSE 'active' END
  FROM public.staff_approval_badges b
  LEFT JOIN public.employees e ON e.id = b.employee_id
  LEFT JOIN auth.users u ON u.id = b.user_id
  ORDER BY b.issued_at DESC;
END $$;


--
-- Name: list_approval_trail(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_approval_trail(p_limit integer DEFAULT 200) RETURNS TABLE(at timestamp with time zone, method text, outcome text, action text, manager_name text, requested_by_name text, reason_code text, detail text, device_id text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.staff_roles sr WHERE sr.user_id = auth.uid() AND sr.role IN ('admin','finance','hr')) THEN
    RAISE EXCEPTION 'admin, finance or HR role required';
  END IF;
  RETURN QUERY
  WITH unames AS (
    SELECT u.id, COALESCE((SELECT e.full_name FROM public.employees e WHERE e.user_id = u.id LIMIT 1), u.email::text) AS name FROM auth.users u
  ), trail(t_at, t_method, t_outcome, t_action, t_manager, t_requested_by, t_reason, t_detail, t_device) AS (
    SELECT x.created_at, 'badge'::text, x.outcome, x.action, COALESCE(e.full_name, mu.name), r.name, x.args->>'reason_code',
           COALESCE(x.error, x.args->>'notes'), x.device_id
    FROM public.staff_badge_approvals x
    LEFT JOIN public.employees e ON e.id = x.approver_employee_id
    LEFT JOIN unames mu ON mu.id = x.approver_user_id
    LEFT JOIN unames r ON r.id = x.requested_by
    UNION ALL
    SELECT p.created_at, 'approver_session'::text, 'approved'::text, p.action, m.name, r.name, p.reason_code, p.notes, NULL::text
    FROM public.pos_action_audit p
    LEFT JOIN unames m ON m.id = p.approved_by_user_id
    LEFT JOIN unames r ON r.id = p.actor_user_id
    WHERE p.approved_by_user_id IS NOT NULL AND p.approved_by_user_id = p.actor_user_id
    UNION ALL
    SELECT ev.created_at, 'admin'::text, ev.event, ev.event, a.name, COALESCE(te.full_name, tu.name), NULL::text, ev.notes, NULL::text
    FROM public.staff_approver_admin_events ev
    LEFT JOIN unames a ON a.id = ev.actor_id
    LEFT JOIN public.employees te ON te.id = ev.employee_id
    LEFT JOIN unames tu ON tu.id = ev.user_id
  )
  SELECT * FROM trail ORDER BY 1 DESC LIMIT LEAST(GREATEST(COALESCE(p_limit, 200), 1), 1000);
END $$;


--
-- Name: list_approver_candidates(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_approver_candidates() RETURNS TABLE(holder_type text, employee_id uuid, user_id uuid, full_name text, employee_code text, grade text, role_title text, department text, has_login boolean, is_approver boolean, source text, assigned boolean, active_badges integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.staff_roles sr WHERE sr.user_id = auth.uid() AND sr.role IN ('admin','hr','finance')) THEN
    RAISE EXCEPTION 'admin, HR or finance role required';
  END IF;
  RETURN QUERY
  SELECT 'employee'::text, e.id, e.user_id, e.full_name, e.employee_code::text, g.title, r.title, r.department,
         e.user_id IS NOT NULL,
         private.employee_approver_source(e.id) IS NOT NULL OR (e.user_id IS NOT NULL AND private.pos_approver_source(e.user_id) IS NOT NULL),
         COALESCE(private.employee_approver_source(e.id), private.pos_approver_source(e.user_id)),
         EXISTS (SELECT 1 FROM public.staff_approver_assignments a WHERE a.employee_id = e.id AND a.revoked_at IS NULL),
         (SELECT count(*)::int FROM public.staff_approval_badges b WHERE b.employee_id = e.id AND b.revoked_at IS NULL AND b.expires_at > now())
  FROM public.employees e
  LEFT JOIN public.hr_grades g ON g.id = e.grade_id
  LEFT JOIN public.hr_roles r ON r.id = e.hr_role_id
  WHERE e.status = 'active'
  UNION ALL
  SELECT 'user'::text, NULL::uuid, u.id, u.email::text, NULL::text, NULL::text, 'Administrator'::text, NULL::text, true, true, 'admin_role'::text, false,
         (SELECT count(*)::int FROM public.staff_approval_badges b WHERE b.user_id = u.id AND b.revoked_at IS NULL AND b.expires_at > now())
  FROM auth.users u
  WHERE EXISTS (SELECT 1 FROM public.staff_roles sr WHERE sr.user_id = u.id AND sr.role = 'admin')
    AND NOT EXISTS (SELECT 1 FROM public.employees e WHERE e.user_id = u.id)
  ORDER BY 10 DESC, 4;
END $$;


--
-- Name: list_catalog_diagrams(text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_catalog_diagrams(p_maker_slug text, p_model_slug text, p_variant_slug text, p_section_slug text) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(jsonb_agg(row_to_json(t)::jsonb ORDER BY t.slug), '[]'::jsonb)
  FROM (
    SELECT slug, title, storage_path, image_url
    FROM public.catalog_diagrams
    WHERE maker_slug = p_maker_slug
      AND model_slug = p_model_slug
      AND variant_slug = p_variant_slug
      AND section_slug = p_section_slug
  ) t;
$$;


--
-- Name: list_catalog_makers(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_catalog_makers() RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(jsonb_agg(row_to_json(t)::jsonb ORDER BY t.sort_order, t.name), '[]'::jsonb)
  FROM (
    SELECT m.slug, m.name, m.sort_order,
      (SELECT COUNT(*)::int FROM catalog_models cm WHERE cm.maker_slug = m.slug) AS model_count
    FROM catalog_makers m
  ) t;
$$;


--
-- Name: list_catalog_models(text); Type: FUNCTION; Schema: public; Owner: -
