--
-- Name: list_crm_promo_candidates(integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_crm_promo_candidates(p_limit integer DEFAULT 25, p_force boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_settings public.ai_promo_settings%ROWTYPE;
  v_limit INT := GREATEST(1, LEAST(COALESCE(p_limit, 25), 100));
  v_fallback TEXT[];
  v_rows JSONB := '[]'::jsonb;
BEGIN
  IF auth.role() <> 'service_role'
     AND NOT public.has_staff_role(ARRAY['admin', 'sales']::public.staff_role[])
  THEN
    RAISE EXCEPTION 'sales or admin role required';
  END IF;

  SELECT * INTO v_settings
  FROM public.ai_promo_settings
  ORDER BY updated_at DESC
  LIMIT 1;

  IF v_settings.id IS NULL OR NOT v_settings.active THEN
    RETURN jsonb_build_object(
      'settings_active', false,
      'candidates', '[]'::jsonb
    );
  END IF;

  SELECT COALESCE(array_agg(oem ORDER BY rn), '{}'::text[])
  INTO v_fallback
  FROM (
    SELECT
      si.oem_part_number AS oem,
      ROW_NUMBER() OVER (ORDER BY SUM(sil.qty_base) DESC) AS rn
    FROM public.sales_invoice_lines sil
    JOIN public.sales_invoices inv ON inv.id = sil.invoice_id
    JOIN public.stock_items si ON si.id = sil.stock_item_id
    WHERE inv.doc_type = 'invoice'
      AND inv.status = 'posted'
      AND inv.posted_at >= now() - INTERVAL '90 days'
      AND NOT sil.is_core_charge
    GROUP BY si.oem_part_number
    ORDER BY SUM(sil.qty_base) DESC
    LIMIT v_settings.max_skus_per_message
  ) x;

  SELECT COALESCE(jsonb_agg(row_to_json(t)::jsonb), '[]'::jsonb)
  INTO v_rows
  FROM (
    SELECT
      c.id AS customer_id,
      c.display_name,
      c.email,
      c.phone_e164,
      c.whatsapp_e164,
      lp.last_purchase_at,
      c.last_promotional_message_at,
      gv.vehicle_label,
      gv.make,
      gv.model,
      gv.engine,
      COALESCE(
        (
          SELECT CASE
            WHEN cardinality(arr) > 0 THEN arr
            ELSE v_fallback
          END
          FROM (
            SELECT COALESCE(array_agg(oem), '{}'::text[]) AS arr
            FROM (
              SELECT DISTINCT si.oem_part_number AS oem
              FROM public.part_fitment pf
              JOIN public.stock_items si ON si.oem_part_number = pf.oem_part_number
              WHERE (
                  gv.model IS NOT NULL
                  AND pf.chassis_code IS NOT NULL
                  AND pf.chassis_code ILIKE '%' || gv.model || '%'
                )
                OR (
                  gv.engine IS NOT NULL
                  AND pf.engine_code IS NOT NULL
                  AND pf.engine_code ILIKE '%' || gv.engine || '%'
                )
              LIMIT v_settings.max_skus_per_message
            ) oems
          ) wrapped
        ),
        v_fallback
      ) AS oem_skus
    FROM public.customers c
    JOIN LATERAL (
      SELECT MAX(inv.posted_at) AS last_purchase_at
      FROM public.sales_invoices inv
      WHERE inv.customer_id = c.id
        AND inv.doc_type = 'invoice'
        AND inv.status = 'posted'
    ) lp ON lp.last_purchase_at IS NOT NULL
    LEFT JOIN LATERAL (
      SELECT
        g.make,
        g.model,
        g.engine,
        trim(both ' ' FROM concat_ws(
          ' ',
          NULLIF(g.make, ''),
          NULLIF(g.model, ''),
          NULLIF(g.generation, ''),
          NULLIF(g.engine, '')
        )) AS vehicle_label
      FROM public.customer_garage_vehicles g
      WHERE g.customer_id = c.id
      ORDER BY g.is_primary DESC, g.updated_at DESC
      LIMIT 1
    ) gv ON true
    WHERE c.marketing_opt_in
      AND lp.last_purchase_at < now() - make_interval(days => v_settings.inactivity_days)
      AND (
        COALESCE(p_force, false)
        OR c.last_promotional_message_at IS NULL
        OR c.last_promotional_message_at
          < now() - make_interval(days => v_settings.cooldown_days)
      )
    ORDER BY lp.last_purchase_at ASC
    LIMIT v_limit
  ) t;

  RETURN jsonb_build_object(
    'settings_active', true,
    'inactivity_days', v_settings.inactivity_days,
    'cooldown_days', v_settings.cooldown_days,
    'max_skus_per_message', v_settings.max_skus_per_message,
    'channels', to_jsonb(v_settings.channels),
    'include_llm_copy', v_settings.include_llm_copy,
    'candidates', COALESCE(v_rows, '[]'::jsonb)
  );
END;
$$;


--
-- Name: list_customer_compare_items(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_customer_compare_items() RETURNS TABLE(id uuid, stock_item_id uuid, oem_part_number text, description text, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cust UUID := public._current_customer_id();
BEGIN
  IF v_cust IS NULL THEN
    RAISE EXCEPTION 'customer profile required';
  END IF;

  RETURN QUERY
  SELECT
    c.id,
    c.stock_item_id,
    si.oem_part_number,
    si.description,
    c.created_at
  FROM public.customer_compare_items c
  JOIN public.stock_items si ON si.id = c.stock_item_id
  WHERE c.customer_id = v_cust
  ORDER BY c.created_at DESC;
END;
$$;


--
-- Name: list_customer_suspensions(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_customer_suspensions(p_status text DEFAULT 'active'::text, p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
 IF NOT (public.has_staff_role(ARRAY['admin','finance']::public.staff_role[]) OR public.is_pos_approver()) THEN
  RAISE EXCEPTION 'manager, finance or admin required';
 END IF;
 RETURN COALESCE((SELECT jsonb_agg(private._customer_suspension_json(s) ORDER BY (s.status='active') DESC, s.suspended_at DESC)
  FROM (SELECT * FROM public.customer_suspensions WHERE p_status IS NULL OR status=p_status ORDER BY suspended_at DESC
        LIMIT LEAST(GREATEST(COALESCE(p_limit,100),1),500)) s),'[]'::jsonb);
END $$;


--
-- Name: list_customer_vehicle_master(text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_customer_vehicle_master(p_maker text DEFAULT 'nissan'::text, p_limit integer DEFAULT 1000, p_offset integer DEFAULT 0) RETURNS TABLE(id text, make text, model_family text, model_variant text, chassis_code text, engine_code text, production_year integer, year_start integer, year_end integer, sales_region text, display_name text, vin_prefix text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT
    v.r2_scope_key,
    'Nissan'::TEXT,
    v.model,
    'Nissan ' || v.model,
    v.chassis_code,
    v.engine_code,
    v.year_start,
    v.year_start,
    v.year_end,
    v.sales_region,
    'Nissan ' || v.model || ' · ' || concat_ws(' · ',
      v.chassis_code,
      v.engine_code,
      CASE WHEN v.year_start IS NOT NULL OR v.year_end IS NOT NULL
        THEN concat(v.year_start, '–', v.year_end) END,
      v.sales_region),
    NULL::TEXT
  FROM public.catalog_r2_vehicle_master v
  WHERE v.maker_slug = lower(trim(COALESCE(p_maker, 'nissan')))
  ORDER BY v.model, v.year_start NULLS LAST, v.chassis_code, v.engine_code
  LIMIT GREATEST(1, LEAST(COALESCE(p_limit, 1000), 10000))
  OFFSET GREATEST(0, COALESCE(p_offset, 0));
$$;


--
-- Name: FUNCTION list_customer_vehicle_master(p_maker text, p_limit integer, p_offset integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.list_customer_vehicle_master(p_maker text, p_limit integer, p_offset integer) IS 'Vehicle selector rows from the published catalogue routing table; id = catalog-live-r2 vehicle_id.';


