-- Name: list_delivery_balance_approvals(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_delivery_balance_approvals(p_status text DEFAULT NULL::text, p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
 IF NOT (public.has_staff_role(ARRAY['admin','dispatcher','finance']::public.staff_role[]) OR public.is_pos_approver()) THEN
  RAISE EXCEPTION 'dispatcher, finance, admin or approver required'; END IF;
 RETURN COALESCE((SELECT jsonb_agg(private._delivery_balance_approval_json(b) ORDER BY (b.status='pending') DESC, b.created_at DESC)
  FROM (SELECT * FROM public.delivery_balance_approvals WHERE p_status IS NULL OR status=p_status ORDER BY created_at DESC LIMIT LEAST(GREATEST(COALESCE(p_limit,100),1),500)) b),'[]'::jsonb);
END $$;


--
-- Name: list_delivery_card_terminals(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_delivery_card_terminals(p_warehouse_id uuid, p_device_id text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 SELECT COALESCE(jsonb_agg(jsonb_build_object('id',t.id,'code',t.code,'label',t.label,'acquirer_name',t.acquirer_name,
  'external_terminal_id',t.external_terminal_id,'adapter_key',t.adapter_key,'adapter_config',t.adapter_config,
  'warehouse_id',t.warehouse_id,'device_id',t.device_id,'allow_delivery',t.allow_delivery) ORDER BY t.label,t.code),'[]'::jsonb)
 FROM public.pos_card_terminals t WHERE public.is_staff() AND t.is_active AND t.allow_delivery
  AND (t.warehouse_id IS NULL OR t.warehouse_id=p_warehouse_id) AND (t.device_id IS NULL OR t.device_id=p_device_id);
$$;


--
-- Name: list_driver_cash(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_driver_cash(p_status text DEFAULT NULL::text, p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
 IF NOT (public.has_staff_role(ARRAY['admin','finance','sales','dispatcher']::public.staff_role[]) OR public.is_pos_approver()) THEN
  RAISE EXCEPTION 'cashier, finance, dispatcher or manager required'; END IF;
 RETURN jsonb_build_object(
  'holding', COALESCE((SELECT jsonb_agg(jsonb_build_object('driver_user_id',g.collected_by,
     'driver_name',(SELECT p.full_name FROM public.profiles p WHERE p.id=g.collected_by),
     'currency',g.currency,'amount',g.amount,'count',g.n,'oldest_at',g.oldest_at) ORDER BY g.oldest_at)
   FROM (SELECT c.collected_by, c.currency, sum(c.amount) AS amount, count(*) AS n, min(c.collected_at) AS oldest_at
         FROM public.delivery_cash_collections c WHERE c.handin_id IS NULL GROUP BY c.collected_by, c.currency) g),'[]'::jsonb),
  'owed', COALESCE((SELECT jsonb_agg(private._driver_cash_handin_json(h) ORDER BY h.approved_at)
   FROM public.driver_cash_handins h WHERE h.owed_amount - h.recovered_amount - h.written_off_amount > 0),'[]'::jsonb),
  'handins', COALESCE((SELECT jsonb_agg(private._driver_cash_handin_json(h) ORDER BY
     CASE h.status WHEN 'submitted' THEN 0 WHEN 'variance_pending' THEN 1 ELSE 2 END, h.submitted_at DESC)
   FROM (SELECT * FROM public.driver_cash_handins WHERE p_status IS NULL OR status=p_status
         ORDER BY status IN ('submitted','variance_pending') DESC, submitted_at DESC
         LIMIT LEAST(GREATEST(COALESCE(p_limit,100),1),500)) h),'[]'::jsonb));
END $$;


--
-- Name: ai_report_subscriptions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ai_report_subscriptions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    created_by uuid,
    cadence public.ai_report_cadence DEFAULT 'daily'::public.ai_report_cadence NOT NULL,
    channels public.ai_delivery_channel[] DEFAULT ARRAY['email'::public.ai_delivery_channel] NOT NULL,
    recipient_emails text[] DEFAULT '{}'::text[] NOT NULL,
    recipient_whatsapp_e164 text[] DEFAULT '{}'::text[] NOT NULL,
    include_narrative boolean DEFAULT true NOT NULL,
    kpi_set text DEFAULT 'ops_sales_v1'::text NOT NULL,
    timezone text DEFAULT 'Africa/Harare'::text NOT NULL,
    active boolean DEFAULT true NOT NULL,
    last_run_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ai_report_subscriptions_channels_nonempty CHECK ((cardinality(channels) >= 1)),
    CONSTRAINT ai_report_subscriptions_kpi_set_check CHECK ((kpi_set = ANY (ARRAY['ops_sales_v1'::text, 'finance_performance_v1'::text]))),
    CONSTRAINT ai_report_subscriptions_recipients_check CHECK (((cardinality(recipient_emails) >= 1) OR (cardinality(recipient_whatsapp_e164) >= 1)))
);


--
-- Name: list_due_ai_report_subscriptions(public.ai_report_cadence, timestamp with time zone, boolean, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_due_ai_report_subscriptions(p_cadence public.ai_report_cadence, p_now timestamp with time zone DEFAULT now(), p_force boolean DEFAULT false, p_subscription_id uuid DEFAULT NULL::uuid) RETURNS SETOF public.ai_report_subscriptions
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'service_role required';
  END IF;

  RETURN QUERY
  SELECT s.*
  FROM public.ai_report_subscriptions s
  WHERE s.active
    AND s.cadence = p_cadence
    AND (p_subscription_id IS NULL OR s.id = p_subscription_id)
    AND (
      p_force
      OR s.last_run_at IS NULL
      OR (
        p_cadence = 'daily'
        AND s.last_run_at < (p_now - INTERVAL '20 hours')
      )
      OR (
        p_cadence = 'weekly'
        AND s.last_run_at < (p_now - INTERVAL '6 days')
      )
      OR (
        p_cadence = 'monthly'
        AND s.last_run_at < (p_now - INTERVAL '27 days')
      )
    )
  ORDER BY s.created_at;
END;
$$;


--
-- Name: fleet_vehicles; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.fleet_vehicles (
