    assigned_driver_user_id uuid,
    notes text,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT fleet_vehicles_plate_nonempty CHECK ((length(TRIM(BOTH FROM plate)) > 0))
);


--
-- Name: TABLE fleet_vehicles; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.fleet_vehicles IS 'Company delivery/ops vehicles. Not customer_garage_vehicles; not B2B FLEET price list.';


--
-- Name: list_fleet_vehicles(public.fleet_vehicle_status); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_fleet_vehicles(p_status public.fleet_vehicle_status DEFAULT NULL::public.fleet_vehicle_status) RETURNS SETOF public.fleet_vehicles
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM public._require_fleet_staff();

  RETURN QUERY
  SELECT fv.*
  FROM public.fleet_vehicles fv
  WHERE p_status IS NULL OR fv.status = p_status
  ORDER BY fv.plate;
END;
$$;


--
-- Name: list_master_stock(integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_master_stock(p_limit integer DEFAULT 200, p_query text DEFAULT NULL::text) RETURNS TABLE(stock_item_id uuid, oem_part_number character varying, description text, qty_total numeric, qty_wh1 numeric, qty_wh2 numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
 SELECT m.stock_item_id,m.oem_part_number,m.description,m.qty_total,m.qty_wh1,m.qty_wh2 FROM public.v_master_stock m
 WHERE public.has_staff_role(ARRAY['admin','warehouse','sales','finance']::public.staff_role[]) AND (p_query IS NULL OR m.oem_part_number ILIKE '%'||p_query||'%' OR COALESCE(m.description,'') ILIKE '%'||p_query||'%')
 ORDER BY m.oem_part_number LIMIT GREATEST(1,LEAST(COALESCE(p_limit,200),1000));
$$;


--
-- Name: list_my_approvals(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_my_approvals() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
 RETURN jsonb_build_object(
  'items', private.approvals_for(auth.uid()),
  'alerts', COALESCE((SELECT jsonb_agg(jsonb_build_object('id',n.id,'title',n.title,'body',n.body,'href',n.href,'created_at',n.created_at)
                       ORDER BY n.created_at DESC)
                      FROM public.staff_ops_notifications n
                      WHERE n.recipient_user_id=auth.uid() AND n.kind='approval_waiting' AND n.read_at IS NULL),'[]'::jsonb));
END $$;


--
-- Name: list_online_prep_queue(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_online_prep_queue(p_limit integer DEFAULT 50) RETURNS TABLE(invoice_id uuid, document_number text, posted_at timestamp with time zone, currency public.currency_code, total numeric, pick_list_id uuid, pick_status public.pick_list_status, delivery_job_id uuid, delivery_job_status public.delivery_job_status, assignee_user_id uuid)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_lim INTEGER := greatest(1, least(COALESCE(p_limit, 50), 100));
BEGIN
  IF NOT public.has_staff_role(
    ARRAY['admin', 'sales', 'warehouse', 'dispatcher']::public.staff_role[]
  ) THEN
    RAISE EXCEPTION 'staff role required';
  END IF;

  RETURN QUERY
  SELECT
    si.id,
    si.document_number,
    si.posted_at,
    si.currency,
    si.total,
    pl.id,
    pl.status,
    dj.id,
    dj.status,
    dj.assignee_user_id
  FROM public.sales_invoices si
  JOIN public.pos_carts c ON c.id = si.cart_id AND c.channel = 'storefront'
  LEFT JOIN LATERAL (
    SELECT p.*
    FROM public.pick_lists p
    WHERE p.sales_invoice_id = si.id
      AND p.status <> 'cancelled'
    ORDER BY p.created_at DESC
    LIMIT 1
  ) pl ON true
  LEFT JOIN LATERAL (
    SELECT j.*
    FROM public.delivery_jobs j
    JOIN public.delivery_notes dn ON dn.id = j.delivery_note_id
    WHERE dn.sales_invoice_id = si.id
    ORDER BY j.created_at DESC
    LIMIT 1
  ) dj ON true
  WHERE si.doc_type = 'invoice'
    AND si.status = 'posted'
    AND si.fulfillment_mode = 'dispatch'
    AND (
      pl.id IS NULL
      OR pl.status = 'draft'
      OR dj.id IS NULL
      OR dj.assignee_user_id IS NULL
    )
  ORDER BY si.posted_at DESC NULLS LAST
  LIMIT v_lim;
END;
$$;


--
-- Name: list_payment_resolution_letters(public.payment_resolution_source_kind, uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_payment_resolution_letters(p_source_kind public.payment_resolution_source_kind DEFAULT NULL::public.payment_resolution_source_kind, p_source_id uuid DEFAULT NULL::uuid, p_query text DEFAULT NULL::text, p_limit integer DEFAULT 50) RETURNS TABLE(id uuid, document_number text, source_kind text, source_id uuid, provider text, observed_status text, amount numeric, currency text, customer_name text, invoice_document_number text, manager_name text, manager_title text, issued_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF NOT (public.is_pos_approver() OR public.has_staff_role(ARRAY['admin','finance']::public.staff_role[])) THEN
    RAISE EXCEPTION 'manager/finance/admin role required';
  END IF;
  RETURN QUERY
  SELECT l.id, l.document_number, l.source_kind::text, l.source_id, l.provider, l.observed_status,
         l.amount, l.currency::text, l.customer_name, l.invoice_document_number,
         l.manager_name, l.manager_title, l.issued_at
  FROM public.payment_resolution_letters l
  WHERE (p_source_kind IS NULL OR l.source_kind = p_source_kind)
    AND (p_source_id IS NULL OR l.source_id = p_source_id)
    AND (p_query IS NULL OR trim(p_query) = ''
         OR l.document_number ILIKE '%' || trim(p_query) || '%'
         OR COALESCE(l.invoice_document_number, '') ILIKE '%' || trim(p_query) || '%'
         OR COALESCE(l.customer_name, '') ILIKE '%' || trim(p_query) || '%')
  ORDER BY l.issued_at DESC
  LIMIT LEAST(GREATEST(COALESCE(p_limit, 50), 1), 200);
END $$;


--
-- Name: list_pos_approval_policies(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_pos_approval_policies() RETURNS TABLE(action text, threshold_value numeric, always_require_manager boolean, reason_required boolean, updated_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 SELECT p.action,p.threshold_value,p.always_require_manager,p.reason_required,p.updated_at
 FROM public.pos_approval_policies p ORDER BY p.action;
$$;


--
-- Name: list_pos_approval_reasons(text); Type: FUNCTION; Schema: public; Owner: -
--

