    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 SELECT r.code,r.label,r.requires_notes,r.sort_order
 FROM public.pos_approval_reason_codes r
 WHERE r.action=p_action AND r.is_active
 ORDER BY r.sort_order,r.label;
$$;


--
-- Name: list_pos_card_terminal_recovery(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_pos_card_terminal_recovery(p_limit integer DEFAULT 100) RETURNS TABLE(id uuid, operation text, status text, terminal_id uuid, terminal_label text, commerce_order_id uuid, source_invoice_id uuid, amount numeric, currency text, external_ref text, terminal_transaction_id text, rrn text, authorization_code text, card_last4 text, card_scheme text, response_code text, response_message text, finalization_error text, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 SELECT a.id,a.operation::text,a.status::text,a.terminal_id,t.label,a.commerce_order_id,a.source_invoice_id,a.amount,a.currency::text,a.external_ref,
  a.terminal_transaction_id,a.rrn,a.authorization_code,a.card_last4,a.card_scheme,a.response_code,a.response_message,a.finalization_error,a.created_at,a.updated_at
 FROM public.pos_card_terminal_attempts a JOIN public.pos_card_terminals t ON t.id=a.terminal_id
 WHERE public.has_staff_role(ARRAY['admin','finance','sales']::public.staff_role[])
  AND (a.status IN('initiated','approved','unknown') OR a.finalization_error IS NOT NULL)
 ORDER BY a.updated_at DESC LIMIT LEAST(GREATEST(COALESCE(p_limit,100),1),250);
$$;


--
-- Name: list_pos_card_terminals(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_pos_card_terminals(p_warehouse_id uuid DEFAULT NULL::uuid, p_device_id text DEFAULT NULL::text) RETURNS TABLE(id uuid, code text, label text, acquirer_name text, external_terminal_id text, adapter_key text, adapter_config jsonb, warehouse_id uuid, device_id text, is_active boolean, allow_delivery boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 SELECT t.id,t.code,t.label,t.acquirer_name,t.external_terminal_id,t.adapter_key,t.adapter_config,t.warehouse_id,t.device_id,t.is_active,t.allow_delivery
 FROM public.pos_card_terminals t
 WHERE public.is_staff() AND t.is_active
  AND (p_warehouse_id IS NULL OR t.warehouse_id IS NULL OR t.warehouse_id=p_warehouse_id)
  AND (p_device_id IS NULL OR t.device_id IS NULL OR t.device_id=p_device_id)
 ORDER BY t.label,t.code;
$$;


--
-- Name: list_pos_customer_garage(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_pos_customer_garage(p_customer_id uuid) RETURNS TABLE(id uuid, customer_id uuid, make text, model_slug text, model text, generation text, chassis_code text, engine text, vin text, is_primary boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM public._require_sales_staff();
  RETURN QUERY
  SELECT g.id, g.customer_id, g.make, g.model_slug, g.model, g.generation,
         g.chassis_code, g.engine, g.vin, g.is_primary
