--
-- Name: list_pos_fulfillment_deposits(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_pos_fulfillment_deposits(p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
 PERFORM public._require_sales_staff();
 RETURN COALESCE((SELECT jsonb_agg(private._pos_deposit_json(d) ORDER BY d.created_at) FROM public.pos_fulfillment_deposits d WHERE d.request_id=p_request_id),'[]'::jsonb);
END $$;


--
-- Name: list_pos_fulfillment_requests(text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_pos_fulfillment_requests(p_query text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_limit integer DEFAULT 100) RETURNS TABLE(id uuid, document_number text, kind text, status text, stock_item_id uuid, oem_part_number text, description text, uom_id uuid, qty numeric, source_warehouse_id uuid, source_warehouse_name text, destination_warehouse_id uuid, destination_warehouse_name text, customer_id uuid, cart_id uuid, invoice_id uuid, stock_entry_id uuid, expires_at timestamp with time zone, ready_at timestamp with time zone, collected_at timestamp with time zone, created_at timestamp with time zone, deposits_held jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 SELECT r.id,r.document_number,r.kind::text,r.status::text,r.stock_item_id,s.oem_part_number::text,s.description,r.uom_id,r.qty,
  r.source_warehouse_id,sw.name,r.destination_warehouse_id,dw.name,r.customer_id,r.cart_id,r.invoice_id,r.stock_entry_id,r.expires_at,r.ready_at,r.collected_at,r.created_at,
  COALESCE((SELECT jsonb_agg(jsonb_build_object('currency',x.currency,'amount',x.amount) ORDER BY x.currency)
    FROM (SELECT d.currency, sum(d.amount) AS amount FROM public.pos_fulfillment_deposits d WHERE d.request_id=r.id AND d.status='held' GROUP BY d.currency) x),'[]'::jsonb)
 FROM public.pos_fulfillment_requests r JOIN public.stock_items s ON s.id=r.stock_item_id
 LEFT JOIN public.warehouses sw ON sw.id=r.source_warehouse_id LEFT JOIN public.warehouses dw ON dw.id=r.destination_warehouse_id
 -- Staff only: this list was open to any signed-in user (customers included).
 WHERE (auth.role()='service_role' OR public.has_staff_role(ARRAY['admin','sales','warehouse','dispatcher','finance']::public.staff_role[]) OR public.is_pos_approver())
   AND (p_status IS NULL OR r.status::text=p_status) AND (p_query IS NULL OR trim(p_query)='' OR r.document_number ILIKE '%'||trim(p_query)||'%' OR s.oem_part_number ILIKE '%'||trim(p_query)||'%' OR COALESCE(s.description,'') ILIKE '%'||trim(p_query)||'%')
 ORDER BY r.created_at DESC LIMIT LEAST(GREATEST(COALESCE(p_limit,100),1),250);
$$;


--
-- Name: list_pos_handover_operators(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_pos_handover_operators() RETURNS TABLE(user_id uuid, employee_code text, full_name text, roles text[])
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 SELECT e.user_id,e.employee_code::text,e.full_name,
  ARRAY(SELECT sr.role::text FROM public.staff_roles sr WHERE sr.user_id=e.user_id ORDER BY sr.role::text)
 FROM public.employees e
 WHERE e.status='active' AND e.user_id IS NOT NULL
  AND EXISTS(SELECT 1 FROM public.staff_roles sr WHERE sr.user_id=e.user_id AND sr.role IN('sales','admin'))
 ORDER BY e.full_name,e.employee_code;
$$;


