-- Name: list_pos_popular_pins(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_pos_popular_pins() RETURNS TABLE(item_type text, item_key text, label text, subtitle text, search_query text, maker_slug text, model_slug text, category_name text, subcategory_name text, oem_part_number text, image_url text, updated_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM public._require_sales_staff();
