--
-- Name: list_pos_popular_spares(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_pos_popular_spares(p_days integer DEFAULT 90, p_limit integer DEFAULT 8) RETURNS TABLE(stock_item_id uuid, oem_part_number text, description text, units_sold numeric, saleable_qty numeric, unit_price numeric, currency public.currency_code, image_storage_path text)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM public._require_sales_staff();
  RETURN QUERY
  WITH sold AS (
    SELECT sil.stock_item_id, SUM(sil.qty) AS units_sold
    FROM public.sales_invoice_lines sil
    JOIN public.sales_invoices inv ON inv.id = sil.invoice_id
    WHERE inv.doc_type = 'invoice'
      AND inv.status = 'posted'
      AND COALESCE(inv.posted_at, inv.created_at) >= now() - make_interval(days => GREATEST(1, LEAST(p_days, 365)))
      AND NOT sil.is_core_charge
    GROUP BY sil.stock_item_id
  )
  SELECT
    si.id,
    si.oem_part_number::text,
    si.description,
    sold.units_sold,
    COALESCE(stock.saleable_qty, 0)::numeric,
    price.unit_price,
    price.currency,
    image.storage_path
  FROM sold
  JOIN public.stock_items si ON si.id = sold.stock_item_id
  LEFT JOIN LATERAL (
    SELECT SUM(sl.quantity)::numeric AS saleable_qty
    FROM public.stock_levels sl
    JOIN public.warehouses w ON w.id = sl.warehouse_id
    WHERE sl.stock_item_id = si.id AND w.is_active AND NOT w.is_quarantine
  ) stock ON true
  LEFT JOIN LATERAL (
    SELECT pli.unit_price, pl.currency
    FROM public.price_lists pl
    JOIN public.price_list_items pli ON pli.price_list_id = pl.id
    WHERE pl.is_default AND pl.is_active AND pli.stock_item_id = si.id
    ORDER BY pl.created_at DESC
    LIMIT 1
  ) price ON true
  LEFT JOIN LATERAL (
    SELECT sii.storage_path
    FROM public.stock_item_images sii
    WHERE sii.stock_item_id = si.id
    ORDER BY sii.is_primary DESC, sii.sort_order, sii.created_at
    LIMIT 1
  ) image ON true
  ORDER BY sold.units_sold DESC, si.oem_part_number
  LIMIT GREATEST(1, LEAST(p_limit, 24));
END;
$$;


--
-- Name: FUNCTION list_pos_popular_spares(p_days integer, p_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.list_pos_popular_spares(p_days integer, p_limit integer) IS 'POS best-seller ranking with canonical stock_item_images/product-images primary thumbnail.';


--
-- Name: list_pos_quotations(public.pos_quotation_status, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_pos_quotations(p_status public.pos_quotation_status DEFAULT NULL::public.pos_quotation_status, p_limit integer DEFAULT 50) RETURNS TABLE(id uuid, document_number text, customer_id uuid, warehouse_id uuid, currency public.currency_code, status public.pos_quotation_status, valid_until date, sent_channel text, created_at timestamp with time zone, line_count bigint, total numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM public._require_sales_staff();
  RETURN QUERY
  SELECT
    q.id,
    q.document_number,
    q.customer_id,
    q.warehouse_id,
    q.currency,
    q.status,
    q.valid_until,
    q.sent_channel,
    q.created_at,
    COUNT(l.id)::BIGINT AS line_count,
    COALESCE(SUM(l.line_total) FILTER (WHERE NOT l.is_core_charge), 0)::NUMERIC AS total
  FROM public.pos_quotations q
  LEFT JOIN public.pos_quotation_lines l ON l.quotation_id = q.id
  WHERE (p_status IS NULL OR q.status = p_status)
  GROUP BY q.id
  ORDER BY q.created_at DESC
  LIMIT GREATEST(1, LEAST(COALESCE(p_limit, 50), 200));
END;
$$;


--
-- Name: list_pos_recent_invoices(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_pos_recent_invoices(p_query text DEFAULT NULL::text, p_limit integer DEFAULT 50) RETURNS TABLE(id uuid, document_number text, customer_id uuid, customer_name text, total numeric, currency public.currency_code, posted_at timestamp with time zone, vehicle_model_name text, vehicle_generation text, vehicle_chassis_code text, vehicle_engine_code text)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_query text := NULLIF(trim(p_query), '');
BEGIN
  PERFORM public._require_sales_staff();
  RETURN QUERY
  SELECT
    inv.id,
    inv.document_number,
    inv.customer_id,
    c.display_name,
    inv.total,
    inv.currency,
    COALESCE(inv.posted_at, inv.created_at),
    inv.vehicle_model_name,
    inv.vehicle_generation,
    inv.vehicle_chassis_code,
    inv.vehicle_engine_code
  FROM public.sales_invoices inv
  LEFT JOIN public.customers c ON c.id = inv.customer_id
  WHERE inv.doc_type = 'invoice'
    AND inv.status = 'posted'
    AND (
      v_query IS NULL
      OR inv.document_number ILIKE '%' || v_query || '%'
      OR inv.id::text = v_query
      OR c.display_name ILIKE '%' || v_query || '%'
      OR c.email ILIKE '%' || v_query || '%'
      OR c.phone_e164 ILIKE '%' || v_query || '%'
      OR inv.vehicle_model_name ILIKE '%' || v_query || '%'
      OR inv.vehicle_chassis_code ILIKE '%' || v_query || '%'
      OR inv.vehicle_engine_code ILIKE '%' || v_query || '%'
    )
  ORDER BY COALESCE(inv.posted_at, inv.created_at) DESC
  LIMIT GREATEST(1, LEAST(p_limit, 200));
END;
$$;


--
-- Name: FUNCTION list_pos_recent_invoices(p_query text, p_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.list_pos_recent_invoices(p_query text, p_limit integer) IS 'Operator POS posted invoice search enriched with immutable vehicle snapshot context.';


--
-- Name: list_pos_split_payment_recovery(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_pos_split_payment_recovery(p_limit integer DEFAULT 100) RETURNS TABLE(session_id uuid, order_id uuid, status text, document_number text, customer_name text, total numeric, currency text, updated_at timestamp with time zone, payload jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
 PERFORM public._require_payments_staff();
 RETURN QUERY
 SELECT s.id,s.commerce_order_id,s.status::text,o.document_number,c.display_name,
        s.total_amount,s.currency::text,s.updated_at,private.pos_split_payment_payload(s.id)
 FROM public.pos_split_payment_sessions s
 JOIN public.commerce_orders o ON o.id=s.commerce_order_id
 LEFT JOIN public.customers c ON c.id=o.customer_id
 WHERE s.status IN('partially_captured','leg_pending','fully_committed','finalization_failed','refund_review','refund_pending')
    OR EXISTS(SELECT 1 FROM public.pos_split_refund_requests r WHERE r.session_id=s.id AND r.status NOT IN('settled','cancelled'))
    OR EXISTS(SELECT 1 FROM public.pos_split_payment_legs l WHERE l.session_id=s.id AND l.status IN('pending','unknown','refund_review','refund_pending'))
 ORDER BY s.updated_at DESC
 LIMIT LEAST(GREATEST(COALESCE(p_limit,100),1),250);
END $$;


--
-- Name: list_pos_stock_availability(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_pos_stock_availability(p_stock_item_id uuid) RETURNS TABLE(warehouse_id uuid, warehouse_code text, warehouse_name text, on_hand numeric, reserved numeric, available numeric, transfer_incoming numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 SELECT w.id,w.code::text,w.name,COALESCE(sl.quantity,0),
  COALESCE((SELECT SUM(GREATEST(r.reserved_qty-r.consumed_qty,0)) FROM public.inventory_reservations r
    WHERE r.stock_item_id=p_stock_item_id AND r.warehouse_id=w.id AND r.state IN('active','allocated')
      AND (r.state='allocated' OR r.expires_at IS NULL OR r.expires_at>now())),0),
  public.get_inventory_available_quantity(p_stock_item_id,w.id),
  COALESCE((SELECT SUM(sel.qty_base) FROM public.stock_entries se JOIN public.stock_entry_lines sel ON sel.stock_entry_id=se.id
    WHERE se.entry_type='transfer' AND se.status='pending_approval' AND se.to_warehouse_id=w.id AND sel.stock_item_id=p_stock_item_id),0)
 FROM public.warehouses w LEFT JOIN public.stock_levels sl ON sl.warehouse_id=w.id AND sl.stock_item_id=p_stock_item_id
 WHERE w.is_active AND NOT w.is_quarantine ORDER BY public.get_inventory_available_quantity(p_stock_item_id,w.id) DESC,w.code;
$$;


--
-- Name: list_pos_till_items(uuid, text, boolean, text, text, text, text[], text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_pos_till_items(p_warehouse_id uuid, p_source text, p_in_stock_only boolean DEFAULT true, p_chassis_code text DEFAULT NULL::text, p_engine_code text DEFAULT NULL::text, p_category text DEFAULT NULL::text, p_oems text[] DEFAULT NULL::text[], p_section_key text DEFAULT NULL::text, p_limit integer DEFAULT 80, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_list UUID; v_currency public.currency_code; v_source TEXT; v_limit INT; v_offset INT;
  v_chassis TEXT; v_engine TEXT; v_category TEXT; v_section TEXT; v_items JSONB;
BEGIN
  PERFORM public._require_payments_staff();
  IF p_warehouse_id IS NULL THEN RAISE EXCEPTION 'warehouse_id required'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.warehouses w WHERE w.id=p_warehouse_id AND w.is_active AND NOT w.is_quarantine) THEN RAISE EXCEPTION 'warehouse not found or not saleable'; END IF;
  v_source:=lower(btrim(COALESCE(p_source,'')));
  IF v_source NOT IN('shop_stock','oems','section') THEN RAISE EXCEPTION 'p_source must be shop_stock, oems, or section'; END IF;
  v_limit:=GREATEST(1,LEAST(COALESCE(p_limit,80),500)); v_offset:=GREATEST(0,COALESCE(p_offset,0));
  v_chassis:=NULLIF(upper(btrim(COALESCE(p_chassis_code,''))),''); v_engine:=NULLIF(upper(btrim(COALESCE(p_engine_code,''))),'');
  v_category:=NULLIF(btrim(COALESCE(p_category,'')),''); v_section:=NULLIF(btrim(COALESCE(p_section_key,'')),'');
  SELECT pl.id,pl.currency INTO v_list,v_currency FROM public.price_lists pl WHERE pl.is_default AND pl.is_active LIMIT 1;
  IF v_list IS NULL THEN SELECT pl.id,pl.currency INTO v_list,v_currency FROM public.price_lists pl WHERE pl.code='RETAIL' AND pl.is_active LIMIT 1; END IF;
  IF v_list IS NULL THEN RAISE EXCEPTION 'no active default/RETAIL price list'; END IF;
  IF v_source='oems' AND (p_oems IS NULL OR cardinality(p_oems)=0) THEN RAISE EXCEPTION 'p_oems required when p_source = oems'; END IF;
  IF v_source='section' AND v_section IS NULL THEN RAISE EXCEPTION 'p_section_key required when p_source = section'; END IF;

  WITH base AS (
    SELECT
      si.id AS stock_item_id, si.oem_part_number, si.description, si.base_uom_id AS uom_id,
      COALESCE(pli.unit_price,0)::numeric AS unit_price, COALESCE(pli.core_charge,0)::numeric AS core_charge,
      COALESCE(sl.quantity,0)::numeric AS saleable_qty, COALESCE(sl.currency,v_currency) AS currency, wb.code AS bin_code,
      (SELECT pf.pnc_code FROM public.part_fitment pf WHERE pf.oem_part_number=si.oem_part_number AND pf.pnc_code IS NOT NULL AND btrim(pf.pnc_code)<>'' ORDER BY pf.pnc_code LIMIT 1) AS pnc_code,
      (SELECT pc.category_name FROM public.part_fitment pf JOIN public.pnc_categories pc ON pc.pnc_code=pf.pnc_code WHERE pf.oem_part_number=si.oem_part_number ORDER BY pc.category_name NULLS LAST LIMIT 1) AS category_name,
      (SELECT pf.superseded_by FROM public.part_fitment pf WHERE pf.oem_part_number=si.oem_part_number AND pf.superseded_by IS NOT NULL AND btrim(pf.superseded_by)<>'' ORDER BY pf.superseded_by LIMIT 1) AS superseded_by,
      COALESCE((SELECT array_agg(DISTINCT c ORDER BY c) FROM (SELECT btrim(pf.chassis_code) c FROM public.part_fitment pf WHERE pf.oem_part_number=si.oem_part_number AND pf.chassis_code IS NOT NULL AND btrim(pf.chassis_code)<>'') s),'{}'::text[]) AS chassis_codes,
      COALESCE((SELECT array_agg(DISTINCT e ORDER BY e) FROM (SELECT btrim(pf.engine_code) e FROM public.part_fitment pf WHERE pf.oem_part_number=si.oem_part_number AND pf.engine_code IS NOT NULL AND btrim(pf.engine_code)<>'') s),'{}'::text[]) AS engine_codes,
      CASE WHEN v_source='oems' THEN array_position(ARRAY(SELECT upper(btrim(x)) FROM unnest(p_oems) x),upper(btrim(si.oem_part_number))) ELSE NULL END AS requested_order
    FROM public.stock_items si
    LEFT JOIN public.price_list_items pli ON pli.stock_item_id=si.id AND pli.price_list_id=v_list
    LEFT JOIN public.stock_levels sl ON sl.stock_item_id=si.id AND sl.warehouse_id=p_warehouse_id
    LEFT JOIN public.warehouse_bins wb ON wb.id=sl.bin_id AND wb.is_active
    WHERE si.base_uom_id IS NOT NULL
      AND (v_source<>'shop_stock' OR COALESCE(pli.unit_price,0)>=0)
      AND (NOT COALESCE(p_in_stock_only,true) OR COALESCE(sl.quantity,0)>0)
      AND (v_source<>'oems' OR upper(btrim(si.oem_part_number))=ANY(ARRAY(SELECT upper(btrim(x)) FROM unnest(p_oems) x)))
      AND (v_source<>'section' OR EXISTS(
        SELECT 1 FROM (
          SELECT pf.oem_part_number oem FROM public.part_fitment pf WHERE pf.pnc_code=v_section
          UNION SELECT cdp.oem_part_number FROM public.catalog_diagram_parts cdp WHERE cdp.section_slug=v_section
          UNION SELECT pf.oem_part_number FROM public.catalog_diagrams cd JOIN public.part_fitment pf ON pf.diagram_path=cd.storage_path WHERE cd.section_slug=v_section
        ) sec WHERE upper(btrim(sec.oem))=upper(btrim(si.oem_part_number))
      ))
      AND (v_category IS NULL OR EXISTS(SELECT 1 FROM public.part_fitment pf JOIN public.pnc_categories pc ON pc.pnc_code=pf.pnc_code WHERE pf.oem_part_number=si.oem_part_number AND lower(COALESCE(pc.category_name,'')) LIKE '%'||lower(v_category)||'%'))
      AND (v_chassis IS NULL OR NOT EXISTS(SELECT 1 FROM public.part_fitment pf WHERE pf.oem_part_number=si.oem_part_number AND pf.chassis_code IS NOT NULL AND btrim(pf.chassis_code)<>'') OR EXISTS(SELECT 1 FROM public.part_fitment pf WHERE pf.oem_part_number=si.oem_part_number AND upper(btrim(pf.chassis_code))=v_chassis AND (v_engine IS NULL OR pf.engine_code IS NULL OR btrim(pf.engine_code)='' OR upper(btrim(pf.engine_code))=v_engine)))
  ), page AS (
    SELECT * FROM base ORDER BY requested_order NULLS LAST,oem_part_number LIMIT v_limit OFFSET v_offset
  )
  SELECT COALESCE(jsonb_agg(to_jsonb(page)-'requested_order' ORDER BY requested_order NULLS LAST,oem_part_number),'[]'::jsonb) INTO v_items FROM page;

  RETURN jsonb_build_object('warehouse_id',p_warehouse_id,'source',v_source,'currency',v_currency,'price_list_id',v_list,'limit',v_limit,'offset',v_offset,'items',COALESCE(v_items,'[]'::jsonb));
END;$$;


--
-- Name: FUNCTION list_pos_till_items(p_warehouse_id uuid, p_source text, p_in_stock_only boolean, p_chassis_code text, p_engine_code text, p_category text, p_oems text[], p_section_key text, p_limit integer, p_offset integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.list_pos_till_items(p_warehouse_id uuid, p_source text, p_in_stock_only boolean, p_chassis_code text, p_engine_code text, p_category text, p_oems text[], p_section_key text, p_limit integer, p_offset integer) IS 'Staff TillItem grid SoR. p_source: shop_stock | oems | section. Saleable quantity comes only from stock_levels; returns pricing, bins and fitment metadata.';


--
-- Name: pos_till_sessions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.pos_till_sessions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    device_id text NOT NULL,
    warehouse_id uuid NOT NULL,
    currency public.currency_code NOT NULL,
    operator_user_id uuid NOT NULL,
    opened_by uuid NOT NULL,
    opening_float numeric(18,2) NOT NULL,
    status public.pos_till_session_status DEFAULT 'open'::public.pos_till_session_status NOT NULL,
    expected_cash numeric(18,2),
    counted_cash numeric(18,2),
    variance numeric(18,2),
    variance_reason_code text,
    close_notes text,
    approved_by uuid,
    approved_at timestamp with time zone,
    opened_at timestamp with time zone DEFAULT now() NOT NULL,
    closed_at timestamp with time zone,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT pos_till_sessions_opening_float_check CHECK ((opening_float >= (0)::numeric))
);


--
-- Name: list_pos_till_sessions(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_pos_till_sessions(p_status text DEFAULT NULL::text, p_limit integer DEFAULT 50) RETURNS SETOF public.pos_till_sessions
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 SELECT s.* FROM public.pos_till_sessions s WHERE (p_status IS NULL OR s.status::text=p_status)
  AND (s.operator_user_id=auth.uid() OR public.is_pos_approver() OR public.has_staff_role(ARRAY['finance']::public.staff_role[]))
 ORDER BY s.opened_at DESC LIMIT LEAST(GREATEST(COALESCE(p_limit,50),1),200);
$$;


--
-- Name: list_pos_warranty_claims(text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_pos_warranty_claims(p_query text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_limit integer DEFAULT 100) RETURNS TABLE(id uuid, document_number text, status text, resolution text, sales_invoice_id uuid, invoice_number text, stock_item_id uuid, oem_part_number text, stock_serial_id uuid, serial_number text, customer_id uuid, notes text, reject_reason text, credit_note_id uuid, replacement_stock_entry_id uuid, quarantine_stock_entry_id uuid, created_at timestamp with time zone, decided_at timestamp with time zone, closed_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 SELECT w.id,w.document_number,w.status::text,w.resolution::text,w.sales_invoice_id,i.document_number,w.stock_item_id,si.oem_part_number::text,
  w.stock_serial_id,ss.serial_number,w.customer_id,w.notes,w.reject_reason,w.credit_note_id,w.replacement_stock_entry_id,w.quarantine_stock_entry_id,w.created_at,w.decided_at,w.closed_at
 FROM public.warranty_claims w LEFT JOIN public.sales_invoices i ON i.id=w.sales_invoice_id LEFT JOIN public.stock_items si ON si.id=w.stock_item_id LEFT JOIN public.stock_serials ss ON ss.id=w.stock_serial_id
 WHERE (p_status IS NULL OR w.status::text=p_status) AND (p_query IS NULL OR trim(p_query)='' OR w.document_number ILIKE '%'||trim(p_query)||'%' OR COALESCE(i.document_number,'') ILIKE '%'||trim(p_query)||'%' OR COALESCE(si.oem_part_number,'') ILIKE '%'||trim(p_query)||'%' OR COALESCE(ss.serial_number,'') ILIKE '%'||trim(p_query)||'%')
 ORDER BY w.created_at DESC LIMIT LEAST(GREATEST(COALESCE(p_limit,100),1),250);
$$;


--
-- Name: list_receipt_documents_needing_pdf(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_receipt_documents_needing_pdf(p_limit integer DEFAULT 20) RETURNS TABLE(document_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_limit INT := LEAST(100, GREATEST(1, COALESCE(p_limit, 20)));
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'service_role required';
  END IF;

  RETURN QUERY
  SELECT d.document_id
  FROM (
    SELECT DISTINCT o.document_id AS document_id
    FROM public.customer_receipt_outbox o
    WHERE o.status IN ('pending', 'rendering', 'failed')
      AND o.download_url IS NULL
      AND o.attempt_count < 8
  ) d
  ORDER BY d.document_id
  LIMIT v_limit;
END;
$$;


--
-- Name: staff_ops_notifications; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.staff_ops_notifications (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    kind public.staff_ops_notification_kind NOT NULL,
    sales_invoice_id uuid,
    delivery_job_id uuid,
    recipient_user_id uuid NOT NULL,
    title text NOT NULL,
    body text NOT NULL,
    read_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    ref_key text,
    href text
);


--
-- Name: list_staff_ops_notifications(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_staff_ops_notifications(p_limit integer DEFAULT 40) RETURNS SETOF public.staff_ops_notifications
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_lim INTEGER := greatest(1, least(COALESCE(p_limit, 40), 100));
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication required';
  END IF;
  IF NOT public.has_staff_role(
    ARRAY['admin', 'sales', 'warehouse', 'dispatcher']::public.staff_role[]
  ) THEN
    RAISE EXCEPTION 'staff role required';
  END IF;

  RETURN QUERY
  SELECT n.*
  FROM public.staff_ops_notifications n
  WHERE n.recipient_user_id = auth.uid()
  ORDER BY n.created_at DESC
  LIMIT v_lim;
END;
$$;


--
-- Name: list_staff_product_pages(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_staff_product_pages(p_query text DEFAULT NULL::text, p_limit integer DEFAULT 50) RETURNS TABLE(stock_item_id uuid, oem_part_number text, catalog_title text, unit_price numeric, currency public.currency_code, qty_saleable numeric, discount_kind text, discount_value numeric, discount_description text, primary_image_path text, image_count integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_limit INT:=LEAST(GREATEST(COALESCE(p_limit,50),1),200); v_q TEXT:=NULLIF(trim(COALESCE(p_query,'')),'');
BEGIN
 IF NOT public.has_staff_role(ARRAY['admin','sales','warehouse']::public.staff_role[]) THEN RAISE EXCEPTION 'staff role required'; END IF;
 RETURN QUERY WITH saleable AS(SELECT sl.stock_item_id,SUM(sl.quantity)::numeric qty FROM public.stock_levels sl JOIN public.warehouses w ON w.id=sl.warehouse_id WHERE w.is_active AND NOT w.is_quarantine GROUP BY sl.stock_item_id), retail AS(SELECT pli.stock_item_id,pli.unit_price,pl.currency FROM public.price_list_items pli JOIN public.price_lists pl ON pl.id=pli.price_list_id WHERE pl.is_active AND (pl.is_default OR pl.code='RETAIL')), imgs AS(SELECT i.stock_item_id,COUNT(*)::int image_count,MAX(i.storage_path) FILTER(WHERE i.is_primary) primary_image_path FROM public.stock_item_images i GROUP BY i.stock_item_id)
 SELECT si.id,si.oem_part_number::text,COALESCE(NULLIF(trim(si.description),''),si.oem_part_number)::text,r.unit_price,COALESCE(r.currency,'USD'::public.currency_code),COALESCE(s.qty,0),COALESCE(m.discount_kind,'none'),COALESCE(m.discount_value,0),m.discount_description,imgs.primary_image_path,COALESCE(imgs.image_count,0)
 FROM public.stock_items si LEFT JOIN saleable s ON s.stock_item_id=si.id LEFT JOIN retail r ON r.stock_item_id=si.id LEFT JOIN public.stock_item_shop_merch m ON m.stock_item_id=si.id LEFT JOIN imgs ON imgs.stock_item_id=si.id
 WHERE v_q IS NULL OR si.oem_part_number ILIKE '%'||v_q||'%' OR COALESCE(si.description,'') ILIKE '%'||v_q||'%' ORDER BY si.oem_part_number LIMIT v_limit;
END;$$;


--
-- Name: list_storefront_home_carousel(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_storefront_home_carousel(p_limit integer DEFAULT 8) RETURNS TABLE(stock_item_id uuid, title text, caption text, image_path text, unit_price numeric, currency public.currency_code, qty_saleable numeric, discount_kind text, discount_value numeric, discount_description text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_limit int := LEAST(GREATEST(COALESCE(p_limit, 8), 1), 12);
BEGIN
  RETURN QUERY
  WITH saleable AS (
    SELECT sl.stock_item_id, SUM(sl.quantity)::numeric AS qty
    FROM public.stock_levels sl
    JOIN public.warehouses w ON w.id = sl.warehouse_id
    WHERE w.is_active AND NOT w.is_quarantine
    GROUP BY sl.stock_item_id
  ),
  retail AS (
    SELECT DISTINCT ON (pli.stock_item_id) pli.stock_item_id, pli.unit_price, pl.currency
    FROM public.price_list_items pli
    JOIN public.price_lists pl ON pl.id = pli.price_list_id
    WHERE pl.is_active AND (pl.is_default OR pl.code = 'RETAIL') AND pli.unit_price > 0
    ORDER BY pli.stock_item_id, pl.is_default DESC, pl.code
  ),
  primary_image AS (
    SELECT DISTINCT ON (i.stock_item_id) i.stock_item_id, i.storage_path
    FROM public.stock_item_images i
    ORDER BY i.stock_item_id, i.is_primary DESC, i.sort_order, i.created_at
  )
  SELECT
    si.id,
    COALESCE(NULLIF(trim(si.description), ''), 'Nissan part')::text,
    m.home_carousel_caption,
    img.storage_path,
    r.unit_price,
    r.currency,
    COALESCE(s.qty, 0),
    COALESCE(m.discount_kind, 'none')::text,
    COALESCE(m.discount_value, 0)::numeric,
    m.discount_description
  FROM public.stock_item_shop_merch m
  JOIN public.stock_items si ON si.id = m.stock_item_id
  JOIN retail r ON r.stock_item_id = si.id
  LEFT JOIN saleable s ON s.stock_item_id = si.id
  LEFT JOIN primary_image img ON img.stock_item_id = si.id
  WHERE m.home_carousel_rank IS NOT NULL
  ORDER BY m.home_carousel_rank, si.description
  LIMIT v_limit;
END;
$$;


--
-- Name: list_storefront_home_rails(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_storefront_home_rails(p_limit integer DEFAULT 12) RETURNS TABLE(rail text, oem_part_number text, catalog_title text, qty_saleable numeric, unit_price numeric, currency public.currency_code, created_at timestamp with time zone, reorder_point numeric, discount_kind text, discount_value numeric, discount_description text, stock_item_id uuid)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_limit INT := LEAST(GREATEST(COALESCE(p_limit, 12), 1), 48);
BEGIN
  RETURN QUERY
  WITH saleable AS (
    SELECT sl.stock_item_id, SUM(sl.quantity)::numeric qty
    FROM public.stock_levels sl
    JOIN public.warehouses w ON w.id = sl.warehouse_id
    WHERE w.is_active AND NOT w.is_quarantine
    GROUP BY sl.stock_item_id
    HAVING SUM(sl.quantity) > 0
  ),
  retail AS (
    SELECT pli.stock_item_id, pli.unit_price, pl.currency
    FROM public.price_list_items pli
    JOIN public.price_lists pl ON pl.id = pli.price_list_id
    WHERE pl.is_active AND (pl.is_default OR pl.code = 'RETAIL') AND pli.unit_price > 0
  ),
  base AS (
    SELECT si.id, si.oem_part_number::text oem_part_number,
      COALESCE(NULLIF(trim(si.description), ''), 'Nissan part')::text catalog_title,
      s.qty qty_saleable, r.unit_price, r.currency, si.created_at, si.reorder_point,
      COALESCE(m.discount_kind, 'none')::text discount_kind,
      COALESCE(m.discount_value, 0)::numeric discount_value,
      m.discount_description
    FROM public.stock_items si
    JOIN saleable s ON s.stock_item_id = si.id
    JOIN retail r ON r.stock_item_id = si.id
    LEFT JOIN public.stock_item_shop_merch m ON m.stock_item_id = si.id
  ),
  movers AS (SELECT * FROM base ORDER BY qty_saleable DESC, oem_part_number LIMIT v_limit),
  newest AS (SELECT * FROM base ORDER BY created_at DESC NULLS LAST, oem_part_number LIMIT v_limit),
  featured AS (
    SELECT * FROM (
      SELECT b.*, CASE WHEN b.discount_kind <> 'none' THEN 0 ELSE 1 END feat_rank FROM base b
    ) x
    ORDER BY feat_rank, qty_saleable DESC, oem_part_number LIMIT v_limit
  )
  SELECT 'featured'::text, f.oem_part_number, f.catalog_title, f.qty_saleable, f.unit_price, f.currency, f.created_at, f.reorder_point, f.discount_kind, f.discount_value, f.discount_description, f.id FROM featured f
  UNION ALL SELECT 'movers'::text, m.oem_part_number, m.catalog_title, m.qty_saleable, m.unit_price, m.currency, m.created_at, m.reorder_point, m.discount_kind, m.discount_value, m.discount_description, m.id FROM movers m
  UNION ALL SELECT 'newest'::text, n.oem_part_number, n.catalog_title, n.qty_saleable, n.unit_price, n.currency, n.created_at, n.reorder_point, n.discount_kind, n.discount_value, n.discount_description, n.id FROM newest n;
END;
$$;


--
-- Name: list_zig_exchange_rates(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_zig_exchange_rates(p_limit integer DEFAULT 30) RETURNS TABLE(id uuid, rate_date date, rate numeric, notes text, set_by uuid, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_lim INTEGER := greatest(1, least(COALESCE(p_limit, 30), 100));
BEGIN
  IF NOT (
    auth.role() = 'service_role'
    OR public.has_staff_role(ARRAY['admin', 'finance']::public.staff_role[])
  ) THEN
    RAISE EXCEPTION 'finance or admin role required';
  END IF;

  RETURN QUERY
  SELECT r.id, r.rate_date, r.rate, r.notes, r.set_by, r.created_at
  FROM public.daily_exchange_rates r
  WHERE r.currency = 'ZIG'
  ORDER BY r.rate_date DESC, r.created_at DESC
  LIMIT v_lim;
END;
$$;


--
-- Name: lock_accounting_period(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lock_accounting_period(p_period_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT (
    auth.role() = 'service_role'
    OR public.has_staff_role(ARRAY['admin', 'finance']::public.staff_role[])
  ) THEN
    RAISE EXCEPTION 'finance or admin role required to lock period';
  END IF;

  UPDATE public.accounting_periods
  SET locked_at = now(), locked_by = auth.uid()
  WHERE id = p_period_id
    AND locked_at IS NULL;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'period not found or already locked: %', p_period_id;
  END IF;
END;
$$;


--
-- Name: log_finance_audit(text, text, uuid, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_finance_audit(p_action text, p_entity_type text, p_entity_id uuid, p_before jsonb DEFAULT NULL::jsonb, p_after jsonb DEFAULT NULL::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id UUID;
BEGIN
  IF NOT public.has_staff_role(ARRAY['admin', 'finance']::public.staff_role[]) THEN
    RAISE EXCEPTION 'finance or admin role required';
  END IF;
  INSERT INTO public.finance_audit_log (
    actor_user_id, action, entity_type, entity_id, before_state, after_state
  ) VALUES (
    auth.uid(), p_action, p_entity_type, p_entity_id, p_before, p_after
  )
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$$;


--
-- Name: mark_chat_thread_read(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_chat_thread_read(p_thread_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role public.chat_participant_role;
  v_row public.chat_threads;
BEGIN
  SELECT * INTO v_row FROM public.chat_threads WHERE id = p_thread_id;
  IF NOT FOUND OR NOT public._can_select_chat_thread(v_row) THEN
    RAISE EXCEPTION 'thread not found or not visible';
  END IF;

  IF v_row.customer_user_id = auth.uid() THEN
    v_role := 'customer';
  ELSIF public.has_staff_role(public._chat_staff_roles()) THEN
    v_role := 'staff';
  ELSE
    RAISE EXCEPTION 'not a participant';
  END IF;

  INSERT INTO public.chat_participants (thread_id, user_id, role, last_read_at)
  VALUES (p_thread_id, auth.uid(), v_role, now())
  ON CONFLICT (thread_id, user_id) DO UPDATE
  SET last_read_at = now();
END;
$$;


--
-- Name: mark_contipay_settled(text, text, text, jsonb, public.currency_code, numeric, numeric, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_contipay_settled(p_external_ref text, p_payload_hash text, p_provider_ref text DEFAULT NULL::text, p_allocations jsonb DEFAULT NULL::jsonb, p_settlement_currency public.currency_code DEFAULT NULL::public.currency_code, p_settlement_amount numeric DEFAULT NULL::numeric, p_settlement_exchange_rate numeric DEFAULT NULL::numeric, p_success boolean DEFAULT true, p_failure_reason text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_intent public.contipay_payment_intents%ROWTYPE; v_webhook UUID; v_pe UUID; v_hash TEXT; BEGIN
 PERFORM public._require_payments_staff(); v_hash:=NULLIF(trim(COALESCE(p_payload_hash,'')),''); IF v_hash IS NULL THEN RAISE EXCEPTION 'payload_hash required for webhook idempotency'; END IF;
 INSERT INTO public.contipay_webhook_events(external_ref,payload_hash,processed,result_note) VALUES(p_external_ref,v_hash,false,'received') ON CONFLICT(payload_hash) DO NOTHING RETURNING id INTO v_webhook;
 IF v_webhook IS NULL THEN SELECT COALESCE(payment_entry_id,id) INTO v_pe FROM public.contipay_payment_intents WHERE external_ref=p_external_ref; RETURN v_pe; END IF;
 SELECT * INTO v_intent FROM public.contipay_payment_intents WHERE external_ref=p_external_ref FOR UPDATE; IF NOT FOUND THEN UPDATE public.contipay_webhook_events SET processed=true,result_note='unknown external_ref' WHERE id=v_webhook; RAISE EXCEPTION 'contipay intent not found: %',p_external_ref; END IF;
 UPDATE public.contipay_webhook_events SET intent_id=v_intent.id WHERE id=v_webhook; IF v_intent.status='settled' THEN UPDATE public.contipay_webhook_events SET processed=true,result_note='already settled' WHERE id=v_webhook; RETURN COALESCE(v_intent.payment_entry_id,v_intent.id); END IF;
 IF NOT COALESCE(p_success,true) THEN
  UPDATE public.contipay_payment_intents SET status='failed',failure_reason=p_failure_reason,webhook_payload_hash=v_hash,last_webhook_at=now(),provider_ref=COALESCE(p_provider_ref,provider_ref),updated_at=now() WHERE id=v_intent.id;
  IF v_intent.commerce_order_id IS NOT NULL THEN UPDATE public.commerce_orders SET state='payment_failed',payment_exception=p_failure_reason,updated_at=now() WHERE id=v_intent.commerce_order_id AND settled_payment_entry_id IS NULL AND state IN ('awaiting_payment','payment_processing','payment_failed');
   PERFORM private.enqueue_commerce_event('commerce:'||v_intent.commerce_order_id::text||':contipay-failed:'||v_intent.id::text,'commerce.payment_failed',v_intent.commerce_order_id,jsonb_build_object('provider','contipay','reason',p_failure_reason)); END IF;
  PERFORM public.emit_domain_event('payment_failed','contipay:fail:'||v_intent.id::text||':'||v_hash,jsonb_build_object('intent_id',v_intent.id,'external_ref',p_external_ref,'reason',p_failure_reason),auth.uid(),format('GTR Auto: ContiPay failed %s',p_external_ref));
  UPDATE public.contipay_webhook_events SET processed=true,result_note='marked failed' WHERE id=v_webhook; RETURN v_intent.id; END IF;
 IF v_intent.commerce_order_id IS NOT NULL THEN
  v_pe:=private.settle_commerce_payment(v_intent.commerce_order_id,'contipay',v_intent.id,p_provider_ref,v_intent.amount,v_intent.currency,v_intent.exchange_rate_applied,COALESCE(p_settlement_currency,v_intent.settlement_currency),COALESCE(p_settlement_amount,v_intent.settlement_amount),COALESCE(p_settlement_exchange_rate,v_intent.settlement_exchange_rate));
 ELSE
  IF v_intent.status='cancelled' THEN RAISE EXCEPTION 'cannot settle cancelled ContiPay intent'; END IF; IF v_intent.customer_id IS NULL THEN RAISE EXCEPTION 'settled ContiPay intent requires customer_id'; END IF;
  v_pe:=public.create_payment_entry(v_intent.customer_id,'contipay',v_intent.amount,v_intent.currency,v_intent.exchange_rate_applied,format('ContiPay %s',v_intent.external_ref),COALESCE(p_settlement_currency,v_intent.settlement_currency),COALESCE(p_settlement_amount,v_intent.settlement_amount),COALESCE(p_settlement_exchange_rate,v_intent.settlement_exchange_rate));
  IF p_allocations IS NOT NULL AND jsonb_typeof(p_allocations)='array' AND jsonb_array_length(p_allocations)>0 THEN PERFORM public.allocate_payment(v_pe,p_allocations); END IF; PERFORM public.post_payment_entry(v_pe); END IF;
 UPDATE public.contipay_payment_intents SET status='settled',payment_entry_id=v_pe,provider_ref=COALESCE(p_provider_ref,provider_ref),webhook_payload_hash=v_hash,last_webhook_at=now(),settlement_currency=COALESCE(p_settlement_currency,settlement_currency),settlement_amount=COALESCE(p_settlement_amount,settlement_amount),settlement_exchange_rate=COALESCE(p_settlement_exchange_rate,settlement_exchange_rate),updated_at=now() WHERE id=v_intent.id;
 UPDATE public.contipay_webhook_events SET processed=true,result_note='settled' WHERE id=v_webhook; RETURN v_pe; END; $$;


--
-- Name: mark_ecocash_settled(text, text, text, jsonb, public.currency_code, numeric, numeric, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_ecocash_settled(p_external_ref text, p_payload_hash text, p_provider_ref text DEFAULT NULL::text, p_allocations jsonb DEFAULT NULL::jsonb, p_settlement_currency public.currency_code DEFAULT NULL::public.currency_code, p_settlement_amount numeric DEFAULT NULL::numeric, p_settlement_exchange_rate numeric DEFAULT NULL::numeric, p_success boolean DEFAULT true, p_failure_reason text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_intent public.ecocash_payment_intents%ROWTYPE; v_webhook UUID; v_pe UUID; v_hash TEXT; BEGIN
 PERFORM public._require_payments_staff(); v_hash:=NULLIF(trim(COALESCE(p_payload_hash,'')),''); IF v_hash IS NULL THEN RAISE EXCEPTION 'payload_hash required for webhook idempotency'; END IF;
 INSERT INTO public.ecocash_webhook_events(external_ref,payload_hash,processed,result_note) VALUES(p_external_ref,v_hash,false,'received') ON CONFLICT(payload_hash) DO NOTHING RETURNING id INTO v_webhook;
 IF v_webhook IS NULL THEN SELECT COALESCE(payment_entry_id,id) INTO v_pe FROM public.ecocash_payment_intents WHERE external_ref=p_external_ref; RETURN v_pe; END IF;
 SELECT * INTO v_intent FROM public.ecocash_payment_intents WHERE external_ref=trim(p_external_ref) FOR UPDATE; IF NOT FOUND THEN UPDATE public.ecocash_webhook_events SET processed=true,result_note='unknown external_ref' WHERE id=v_webhook; RAISE EXCEPTION 'ecocash intent not found: %',p_external_ref; END IF;
 UPDATE public.ecocash_webhook_events SET intent_id=v_intent.id WHERE id=v_webhook; IF v_intent.status='settled' THEN UPDATE public.ecocash_webhook_events SET processed=true,result_note='already settled' WHERE id=v_webhook; RETURN COALESCE(v_intent.payment_entry_id,v_intent.id); END IF;
 IF NOT COALESCE(p_success,true) THEN
  UPDATE public.ecocash_payment_intents SET status='failed',failure_reason=p_failure_reason,webhook_payload_hash=v_hash,last_webhook_at=now(),provider_ref=COALESCE(p_provider_ref,provider_ref),updated_at=now() WHERE id=v_intent.id;
  IF v_intent.commerce_order_id IS NOT NULL THEN UPDATE public.commerce_orders SET state='payment_failed',payment_exception=p_failure_reason,updated_at=now() WHERE id=v_intent.commerce_order_id AND settled_payment_entry_id IS NULL AND state IN ('awaiting_payment','payment_processing','payment_failed');
   PERFORM private.enqueue_commerce_event('commerce:'||v_intent.commerce_order_id::text||':ecocash-failed:'||v_intent.id::text,'commerce.payment_failed',v_intent.commerce_order_id,jsonb_build_object('provider','ecocash','reason',p_failure_reason)); END IF;
  IF v_intent.whatsapp_flow_order_id IS NOT NULL THEN UPDATE public.whatsapp_flow_orders SET status='FAILED',payment_reference=COALESCE(p_provider_ref,payment_reference),updated_at=now() WHERE id=v_intent.whatsapp_flow_order_id AND status='PENDING'; END IF;
  UPDATE public.ecocash_webhook_events SET processed=true,result_note='marked failed' WHERE id=v_webhook; RETURN v_intent.id; END IF;
 IF v_intent.commerce_order_id IS NOT NULL THEN
  v_pe:=private.settle_commerce_payment(v_intent.commerce_order_id,'ecocash',v_intent.id,p_provider_ref,v_intent.amount,v_intent.currency,v_intent.exchange_rate_applied,COALESCE(p_settlement_currency,v_intent.settlement_currency),COALESCE(p_settlement_amount,v_intent.settlement_amount),COALESCE(p_settlement_exchange_rate,v_intent.settlement_exchange_rate));
 ELSIF v_intent.customer_id IS NOT NULL AND (p_allocations IS NOT NULL OR v_intent.sales_invoice_id IS NOT NULL OR v_intent.channel IN ('web','pos','ios','android_customer')) THEN
  IF v_intent.status='cancelled' THEN RAISE EXCEPTION 'cannot settle cancelled EcoCash intent'; END IF;
  v_pe:=public.create_payment_entry(v_intent.customer_id,'ecocash',v_intent.amount,v_intent.currency,v_intent.exchange_rate_applied,format('EcoCash %s',v_intent.external_ref),COALESCE(p_settlement_currency,v_intent.settlement_currency),COALESCE(p_settlement_amount,v_intent.settlement_amount),COALESCE(p_settlement_exchange_rate,v_intent.settlement_exchange_rate));
  IF p_allocations IS NOT NULL AND jsonb_typeof(p_allocations)='array' AND jsonb_array_length(p_allocations)>0 THEN PERFORM public.allocate_payment(v_pe,p_allocations);
  ELSIF v_intent.sales_invoice_id IS NOT NULL THEN PERFORM public.allocate_payment(v_pe,jsonb_build_array(jsonb_build_object('sales_invoice_id',v_intent.sales_invoice_id,'amount',v_intent.amount))); END IF; PERFORM public.post_payment_entry(v_pe); END IF;
 UPDATE public.ecocash_payment_intents SET status='settled',payment_entry_id=COALESCE(v_pe,payment_entry_id),provider_ref=COALESCE(p_provider_ref,provider_ref),webhook_payload_hash=v_hash,last_webhook_at=now(),settlement_currency=COALESCE(p_settlement_currency,settlement_currency),settlement_amount=COALESCE(p_settlement_amount,settlement_amount),settlement_exchange_rate=COALESCE(p_settlement_exchange_rate,settlement_exchange_rate),updated_at=now() WHERE id=v_intent.id;
 IF v_intent.whatsapp_flow_order_id IS NOT NULL THEN UPDATE public.whatsapp_flow_orders SET status='PAID',payment_reference=COALESCE(p_provider_ref,payment_reference),updated_at=now() WHERE id=v_intent.whatsapp_flow_order_id AND status IS DISTINCT FROM 'PAID'; END IF;
 UPDATE public.ecocash_webhook_events SET processed=true,result_note='settled' WHERE id=v_webhook; RETURN COALESCE(v_pe,v_intent.id); END; $$;


