--
-- Name: mark_pos_fulfillment_ready(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_pos_fulfillment_ready(p_request_id uuid, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
 PERFORM public._require_sales_staff();
 -- A back-order is ready only when the part is in the branch; it is then held for the customer.
 IF EXISTS(SELECT 1 FROM public.pos_fulfillment_requests WHERE id=p_request_id AND kind='backorder' AND status IN('requested','reserved')) THEN
  PERFORM private.hold_pos_fulfillment_stock(p_request_id);
 END IF;
 UPDATE public.pos_fulfillment_requests SET status='ready',ready_at=now(),notes=concat_ws(E'\n',notes,p_notes),updated_at=now()
 WHERE id=p_request_id AND status IN('requested','reserved') AND kind IN('customer_collection','alternate_pickup','backorder');
 IF NOT FOUND THEN RAISE EXCEPTION 'request cannot be marked ready'; END IF; RETURN p_request_id;
END $$;


--
-- Name: mark_receipt_pdf_ready(uuid, text, text, timestamp with time zone, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_receipt_pdf_ready(p_document_id uuid, p_storage_path text, p_download_token text DEFAULT NULL::text, p_expires_at timestamp with time zone DEFAULT (now() + '7 days'::interval), p_byte_size integer DEFAULT NULL::integer, p_content_sha256 text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_inv public.sales_invoices%ROWTYPE;
  v_token TEXT;
  v_url TEXT;
  v_art UUID;
  v_doc_type TEXT;
BEGIN
  IF NOT (
    auth.role() = 'service_role'
    OR public.has_staff_role(ARRAY['admin', 'sales', 'finance']::public.staff_role[])
  ) THEN
    RAISE EXCEPTION 'staff or service role required for receipt PDF';
  END IF;

  SELECT * INTO v_inv FROM public.sales_invoices WHERE id = p_document_id;
  IF NOT FOUND OR v_inv.status <> 'posted' THEN
    RAISE EXCEPTION 'posted invoice/credit note required';
  END IF;

  IF p_storage_path IS NULL OR length(trim(p_storage_path)) = 0 THEN
    RAISE EXCEPTION 'pdf storage path required';
  END IF;

  -- Reject accidental fiscal/ZIMRA path markers in storage key
  IF p_storage_path ~* '(zimra|fdms|fiscal)' THEN
    RAISE EXCEPTION 'fiscal storage paths are forbidden';
  END IF;

  v_token := COALESCE(NULLIF(trim(p_download_token), ''), replace(gen_random_uuid()::text, '-', ''));
  v_url := 'https://nissangtrauto.co.zw/receipts/' || v_token;
  v_doc_type := CASE WHEN v_inv.doc_type = 'credit_note' THEN 'credit_note' ELSE 'sales_invoice' END;

  INSERT INTO public.receipt_pdf_artifacts (
    document_type, document_id, pdf_storage_path, download_token, download_url,
    signed_url_expires_at, byte_size, content_sha256, generated_by
  )
  VALUES (
    v_doc_type, p_document_id, trim(p_storage_path), v_token, v_url,
    p_expires_at, p_byte_size, p_content_sha256, auth.uid()
  )
  ON CONFLICT (document_id) DO UPDATE
  SET
    pdf_storage_path = EXCLUDED.pdf_storage_path,
    download_token = EXCLUDED.download_token,
    download_url = EXCLUDED.download_url,
    signed_url_expires_at = EXCLUDED.signed_url_expires_at,
    byte_size = COALESCE(EXCLUDED.byte_size, public.receipt_pdf_artifacts.byte_size),
    content_sha256 = COALESCE(EXCLUDED.content_sha256, public.receipt_pdf_artifacts.content_sha256),
    generated_at = now(),
    generated_by = auth.uid()
  RETURNING id INTO v_art;

  UPDATE public.customer_receipt_outbox o
  SET
    pdf_storage_path = trim(p_storage_path),
    download_url = v_url,
    receipt_pdf_artifact_id = v_art,
    summary_body = CASE
      WHEN o.channel IN ('sms', 'whatsapp') THEN
        regexp_replace(o.summary_body, E'\\n\\[PDF link pending\\]$', '')
        || E'\n' || v_url
      ELSE o.summary_body
    END
  WHERE o.document_id = p_document_id
    AND o.status IN ('pending', 'rendering', 'failed');

  RETURN v_art;
END;
$_$;


--
-- Name: mark_staff_ops_notification_read(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_staff_ops_notification_read(p_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication required';
  END IF;

  UPDATE public.staff_ops_notifications
  SET read_at = COALESCE(read_at, now())
  WHERE id = p_id AND recipient_user_id = auth.uid();

  IF NOT FOUND THEN
    RAISE EXCEPTION 'notification not found';
  END IF;
  RETURN p_id;
END;
$$;


--
-- Name: markdown_stock_item(uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.markdown_stock_item(p_stock_item_id uuid, p_percent numeric, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE r record; v_out jsonb := '[]'::jsonb; v_new numeric;
BEGIN
 IF NOT (public.has_staff_role(ARRAY['admin','finance']::public.staff_role[]) OR public.is_pos_approver()) THEN
  RAISE EXCEPTION 'manager, finance or admin required';
 END IF;
 IF COALESCE(p_percent,0) < 1 OR p_percent > 50 THEN RAISE EXCEPTION 'markdown must be between 1%% and 50%%'; END IF;
 IF trim(COALESCE(p_reason,'')) = '' THEN RAISE EXCEPTION 'reason required'; END IF;
 FOR r IN SELECT pli.id, pli.unit_price, pl.code FROM public.price_list_items pli JOIN public.price_lists pl ON pl.id=pli.price_list_id
          WHERE pli.stock_item_id=p_stock_item_id FOR UPDATE OF pli LOOP
  v_new := round(r.unit_price * (100 - p_percent) / 100, 2);
  UPDATE public.price_list_items SET unit_price=v_new WHERE id=r.id;
  INSERT INTO public.price_changes(price_list_item_id, stock_item_id, old_price, new_price, reason, changed_by)
  VALUES (r.id, p_stock_item_id, r.unit_price, v_new, format('Markdown %s%%: %s', p_percent, trim(p_reason)), auth.uid());
  v_out := v_out || jsonb_build_object('price_list', r.code, 'old', r.unit_price, 'new', v_new);
 END LOOP;
 IF jsonb_array_length(v_out) = 0 THEN RAISE EXCEPTION 'this part has no prices to mark down'; END IF;
 RETURN v_out;
END $$;


--
-- Name: mint_delivery_track_token(uuid, interval); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mint_delivery_track_token(p_delivery_job_id uuid, p_ttl interval DEFAULT '48:00:00'::interval) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_job public.delivery_jobs%ROWTYPE;
  v_raw TEXT;
  v_hash TEXT;
BEGIN
  PERFORM public._logistics_begin_rpc();

  IF NOT (
    auth.role() = 'service_role'
    OR public.has_staff_role(
      ARRAY['admin', 'warehouse', 'dispatcher']::public.staff_role[]
    )
  ) THEN
    RAISE EXCEPTION 'dispatcher, warehouse, or admin required to mint track token';
  END IF;

  SELECT * INTO v_job FROM public.delivery_jobs WHERE id = p_delivery_job_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'delivery job not found';
  END IF;
  IF v_job.status IN ('completed', 'failed') THEN
    RAISE EXCEPTION 'cannot mint track token for terminal job';
  END IF;

  -- Revoke prior active tokens for this job
  UPDATE public.delivery_track_tokens
  SET revoked_at = now()
  WHERE delivery_job_id = p_delivery_job_id
    AND revoked_at IS NULL;

  v_raw := encode(extensions.gen_random_bytes(32), 'hex');
  v_hash := public._hash_delivery_track_token(v_raw);

  INSERT INTO public.delivery_track_tokens (
    delivery_job_id, token_hash, expires_at
  )
  VALUES (
    p_delivery_job_id,
    v_hash,
    now() + COALESCE(p_ttl, interval '48 hours')
  );

  RETURN v_raw;
END;
$$;


--
-- Name: FUNCTION mint_delivery_track_token(p_delivery_job_id uuid, p_ttl interval); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.mint_delivery_track_token(p_delivery_job_id uuid, p_ttl interval) IS 'Intentional remint/rotate only. Dispatch already mints via update_delivery_job_status and returns plaintext in jsonb.track_token — reminting revokes that token.';


--
-- Name: moderate_customer_product_review(uuid, public.product_review_status); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.moderate_customer_product_review(p_review_id uuid, p_status public.product_review_status) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id UUID;
  v_prev public.product_review_status;
  v_cust UUID;
  v_profile UUID;
  v_phone TEXT;
  v_item UUID;
  v_oem TEXT;
BEGIN
  IF NOT public.has_staff_role(ARRAY['admin', 'sales']::public.staff_role[]) THEN
    RAISE EXCEPTION 'admin or sales role required to moderate reviews';
  END IF;
  IF p_status IS NULL OR p_status = 'pending' THEN
    RAISE EXCEPTION 'moderate status must be approved or rejected';
  END IF;

  SELECT status, customer_id, stock_item_id
  INTO v_prev, v_cust, v_item
  FROM public.customer_product_reviews
  WHERE id = p_review_id
  FOR UPDATE;

  IF v_cust IS NULL THEN
    RAISE EXCEPTION 'review not found';
  END IF;

  UPDATE public.customer_product_reviews
  SET status = p_status, updated_at = now()
  WHERE id = p_review_id
  RETURNING id INTO v_id;

  IF p_status = 'approved' AND v_prev IS DISTINCT FROM 'approved' THEN
    SELECT c.profile_id,
           COALESCE(
             NULLIF(trim(COALESCE(c.phone_e164, '')), ''),
             NULLIF(trim(COALESCE(p.phone_e164, '')), ''),
             NULLIF(trim(COALESCE(c.whatsapp_e164, '')), '')
           ),
           si.oem_part_number
    INTO v_profile, v_phone, v_oem
    FROM public.customers c
    LEFT JOIN public.profiles p ON p.id = c.profile_id
    LEFT JOIN public.stock_items si ON si.id = v_item
    WHERE c.id = v_cust;

    IF v_profile IS NOT NULL THEN
      PERFORM public._enqueue_customer_sms(
        'review_approved',
        'review:approved:' || v_id::text,
        v_profile,
        v_phone,
        jsonb_build_object(
          'review_id', v_id,
          'customer_id', v_cust,
          'stock_item_id', v_item,
          'oem_part_number', v_oem
        ),
        format(
          'GTR Auto: your review for %s was approved.',
          COALESCE(v_oem, 'a product')
        )
      );
    END IF;

    BEGIN
      PERFORM public.emit_domain_event(
        'review_approved',
        'review:approved:staff:' || v_id::text,
        jsonb_build_object('review_id', v_id, 'stock_item_id', v_item)
      );
    EXCEPTION
      WHEN OTHERS THEN
        NULL;
    END;
  END IF;

  RETURN v_id;
END;
$$;


--
-- Name: my_default_landing(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_default_landing() RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
