--
-- Name: next_employee_code_for_grade(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.next_employee_code_for_grade(p_grade_code text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_code TEXT;
  v_prefix TEXT;
BEGIN
  v_code := upper(trim(COALESCE(p_grade_code, '')));
  IF v_code !~ '^[A-Z][0-9]+$' THEN
    RAISE EXCEPTION 'invalid grade code for employee number: %', p_grade_code;
  END IF;
  v_prefix := 'GTR' || v_code;

  INSERT INTO public.naming_series (prefix, current_value, pad_length, description)
  VALUES (v_prefix, 0, 3, format('Employee numbers grade %s', v_code))
  ON CONFLICT (prefix) DO UPDATE
  SET pad_length = 3;

  RETURN public.next_series_value(v_prefix);
END;
$_$;


--
-- Name: next_series_value(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.next_series_value(p_prefix text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_next BIGINT;
  v_pad INT;
BEGIN
  IF p_prefix IS NULL OR length(trim(p_prefix)) = 0 THEN
    RAISE EXCEPTION 'naming series prefix required';
  END IF;

  INSERT INTO public.naming_series (prefix, current_value)
  VALUES (p_prefix, 0)
  ON CONFLICT (prefix) DO NOTHING;

  SELECT current_value + 1, pad_length
  INTO v_next, v_pad
  FROM public.naming_series
  WHERE prefix = p_prefix
  FOR UPDATE;

  UPDATE public.naming_series
  SET current_value = v_next, updated_at = now()
  WHERE prefix = p_prefix;

  RETURN p_prefix || lpad(v_next::text, v_pad, '0');
END;
$$;


--
-- Name: open_account_period(character varying, public.currency_code, date, date, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.open_account_period(p_account_code character varying, p_currency public.currency_code, p_period_start date, p_period_end date, p_opening_balance numeric DEFAULT 0, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id UUID;
  v_code TEXT;
BEGIN
  v_code := btrim(COALESCE(p_account_code, ''));

  IF NOT (
    auth.role() = 'service_role'
    OR public.has_staff_role(ARRAY['admin', 'finance']::public.staff_role[])
    OR (
      v_code = '1120'
      AND public.has_staff_role(
        ARRAY['admin', 'finance', 'sales', 'warehouse']::public.staff_role[]
      )
    )
  ) THEN
    RAISE EXCEPTION 'finance or admin role required (sales/warehouse may open 1120 only)';
  END IF;

  IF v_code = '1110'
     AND NOT (
       auth.role() = 'service_role'
       OR public.has_staff_role(ARRAY['admin', 'finance']::public.staff_role[])
     )
  THEN
    RAISE EXCEPTION 'petty cash 1110 is finance-only';
  END IF;

  IF p_account_code IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.chart_of_accounts c WHERE c.code = p_account_code AND c.is_active
  ) THEN
    RAISE EXCEPTION 'active account required: %', p_account_code;
  END IF;

  IF p_period_start IS NULL OR p_period_end IS NULL OR p_period_end < p_period_start THEN
    RAISE EXCEPTION 'invalid period range';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.account_period_balances ap
    WHERE ap.account_code = p_account_code
      AND ap.currency = p_currency
      AND ap.status = 'open'
  ) THEN
    RAISE EXCEPTION 'open period already exists for % %', p_account_code, p_currency;
  END IF;

  PERFORM public._finance_period_rpc_enter();

  INSERT INTO public.account_period_balances (
    account_code, currency, period_start, period_end,
    opening_balance, status, opened_by, notes
  )
  VALUES (
    p_account_code,
    p_currency,
    p_period_start,
    p_period_end,
    COALESCE(p_opening_balance, 0),
    'open',
    auth.uid(),
    nullif(trim(p_notes), '')
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


--
-- Name: FUNCTION open_account_period(p_account_code character varying, p_currency public.currency_code, p_period_start date, p_period_end date, p_opening_balance numeric, p_notes text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.open_account_period(p_account_code character varying, p_currency public.currency_code, p_period_start date, p_period_end date, p_opening_balance numeric, p_notes text) IS 'Open account period. Finance/admin any CoA; sales/warehouse may open 1120 cash-sales till only. 1110 petty finance-only.';


--
-- Name: open_pos_till_session(uuid, text, numeric, public.currency_code); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.open_pos_till_session(p_warehouse_id uuid, p_device_id text, p_opening_float numeric, p_currency public.currency_code DEFAULT 'USD'::public.currency_code) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_id UUID;
BEGIN
 PERFORM public._require_sales_staff();
 IF trim(COALESCE(p_device_id,''))='' THEN RAISE EXCEPTION 'device_id required'; END IF;
 IF COALESCE(p_opening_float,-1)<0 THEN RAISE EXCEPTION 'opening_float must be >= 0'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.warehouses WHERE id=p_warehouse_id AND is_active) THEN RAISE EXCEPTION 'active warehouse required'; END IF;
 IF EXISTS(SELECT 1 FROM public.pos_till_sessions WHERE (device_id=trim(p_device_id) OR operator_user_id=auth.uid()) AND status IN('open','variance_pending')) THEN
   RAISE EXCEPTION 'device or operator already has an open till session';
 END IF;
 INSERT INTO public.pos_till_sessions(device_id,warehouse_id,currency,operator_user_id,opened_by,opening_float)
 VALUES(trim(p_device_id),p_warehouse_id,p_currency,auth.uid(),auth.uid(),round(p_opening_float,2)) RETURNING id INTO v_id;
 INSERT INTO public.pos_till_session_events(session_id,event_type,actor_user_id,detail)
 VALUES(v_id,'opened',auth.uid(),jsonb_build_object('opening_float',round(p_opening_float,2),'currency',p_currency,'warehouse_id',p_warehouse_id));
 RETURN v_id;
END $$;


--
-- Name: open_pos_warranty_claim(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.open_pos_warranty_claim(p_sales_invoice_id uuid, p_invoice_line_id uuid, p_stock_serial_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE l public.sales_invoice_lines%ROWTYPE; s public.stock_serials%ROWTYPE; v_id UUID;
BEGIN
 PERFORM public._require_warranty_staff();
 SELECT * INTO l FROM public.sales_invoice_lines WHERE id=p_invoice_line_id AND invoice_id=p_sales_invoice_id AND NOT is_core_charge;
 IF NOT FOUND THEN RAISE EXCEPTION 'non-core source invoice line required'; END IF;
 IF p_stock_serial_id IS NOT NULL THEN
  SELECT * INTO s FROM public.stock_serials WHERE id=p_stock_serial_id;
  IF NOT FOUND OR s.stock_item_id<>l.stock_item_id THEN RAISE EXCEPTION 'serial does not match claimed invoice item'; END IF;
 END IF;
 v_id:=public.open_warranty_claim(p_stock_serial_id,p_sales_invoice_id,NULL,p_notes);
 UPDATE public.warranty_claims SET stock_item_id=l.stock_item_id WHERE id=v_id;
 RETURN v_id;
END $$;


--
-- Name: open_warranty_claim(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.open_warranty_claim(p_stock_serial_id uuid DEFAULT NULL::uuid, p_sales_invoice_id uuid DEFAULT NULL::uuid, p_stock_batch_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id UUID;
  v_serial public.stock_serials%ROWTYPE;
  v_inv public.sales_invoices%ROWTYPE;
  v_item UUID;
  v_customer UUID;
  v_currency public.currency_code;
BEGIN
  PERFORM public._warranty_begin_rpc();
  PERFORM public._require_warranty_staff();

  IF p_stock_serial_id IS NULL AND p_sales_invoice_id IS NULL THEN
    RAISE EXCEPTION 'warranty claim requires stock_serial_id and/or sales_invoice_id';
  END IF;

  IF p_stock_serial_id IS NOT NULL THEN
    SELECT * INTO v_serial FROM public.stock_serials WHERE id = p_stock_serial_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'serial not found';
    END IF;
    IF v_serial.status IN ('quarantine', 'scrapped') THEN
      RAISE EXCEPTION 'serial % is % - cannot open warranty claim', p_stock_serial_id, v_serial.status;
    END IF;
    IF EXISTS (
      SELECT 1 FROM public.warranty_claims
      WHERE stock_serial_id = p_stock_serial_id AND status = 'open'
    ) THEN
      RAISE EXCEPTION 'open warranty claim already exists for serial %', p_stock_serial_id;
    END IF;
    v_item := v_serial.stock_item_id;
  END IF;

  IF p_sales_invoice_id IS NOT NULL THEN
    SELECT * INTO v_inv
    FROM public.sales_invoices
    WHERE id = p_sales_invoice_id AND doc_type = 'invoice' AND status = 'posted';
    IF NOT FOUND THEN
      RAISE EXCEPTION 'posted sales invoice required for invoice linkage';
    END IF;
    v_customer := v_inv.customer_id;
    v_currency := v_inv.currency;
    IF v_item IS NULL THEN
      SELECT stock_item_id INTO v_item
      FROM public.sales_invoice_lines
      WHERE invoice_id = p_sales_invoice_id AND NOT is_core_charge
      ORDER BY created_at
      LIMIT 1;
    END IF;
  END IF;

  INSERT INTO public.warranty_claims (
    document_number, status, stock_serial_id, sales_invoice_id,
    stock_batch_id, stock_item_id, customer_id, currency, notes, created_by
  )
  VALUES (
    public.next_series_value('WC-'), 'open', p_stock_serial_id, p_sales_invoice_id,
    p_stock_batch_id, v_item, v_customer, v_currency, p_notes, auth.uid()
  )
  RETURNING id INTO v_id;

  PERFORM public.emit_domain_event(
    'warranty_claim_opened',
    'warranty:open:' || v_id::text,
    jsonb_build_object(
      'warranty_claim_id', v_id,
      'stock_serial_id', p_stock_serial_id,
      'sales_invoice_id', p_sales_invoice_id
    )
  );

  RETURN v_id;
END;
$$;


--
-- Name: optimize_driver_stops(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.optimize_driver_stops(p_driver_user_id uuid) RETURNS TABLE(delivery_job_id uuid, route_sequence integer, distance_m double precision)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_lat DOUBLE PRECISION;
  v_lng DOUBLE PRECISION;
  v_cur_lat DOUBLE PRECISION;
  v_cur_lng DOUBLE PRECISION;
  v_seq INTEGER := 0;
  v_next UUID;
  v_next_dist DOUBLE PRECISION;
  v_next_lat DOUBLE PRECISION;
  v_next_lng DOUBLE PRECISION;
  v_remaining UUID[];
  v_id UUID;
  v_jlat DOUBLE PRECISION;
  v_jlng DOUBLE PRECISION;
  v_d DOUBLE PRECISION;
  v_results UUID[] := ARRAY[]::UUID[];
  v_dists DOUBLE PRECISION[] := ARRAY[]::DOUBLE PRECISION[];
BEGIN
  PERFORM public._logistics_begin_rpc();

  IF p_driver_user_id IS NULL THEN
    RAISE EXCEPTION 'driver_user_id required';
  END IF;

  IF NOT (
    auth.role() = 'service_role'
    OR public.has_staff_role(
      ARRAY['admin', 'warehouse', 'dispatcher']::public.staff_role[]
    )
    OR (
      auth.uid() = p_driver_user_id
      AND public.has_staff_role(ARRAY['driver']::public.staff_role[])
    )
  ) THEN
    RAISE EXCEPTION 'dispatcher/warehouse/admin or self driver required for optimize_driver_stops';
  END IF;

  SELECT dp.last_lat, dp.last_lng
  INTO v_lat, v_lng
  FROM public.driver_presence dp
  WHERE dp.user_id = p_driver_user_id;

  SELECT array_agg(dj.id ORDER BY dj.created_at)
  INTO v_remaining
  FROM public.delivery_jobs dj
  WHERE dj.assignee_user_id = p_driver_user_id
    AND dj.status IN ('pending', 'dispatched');

  IF v_remaining IS NULL OR cardinality(v_remaining) = 0 THEN
    RETURN;
  END IF;

  -- Seed origin: presence, else first job pickup, else first dropoff
  IF v_lat IS NULL OR v_lng IS NULL THEN
    SELECT COALESCE(dj.pickup_lat, dj.dropoff_lat),
           COALESCE(dj.pickup_lng, dj.dropoff_lng)
    INTO v_lat, v_lng
    FROM public.delivery_jobs dj
    WHERE dj.id = v_remaining[1];
  END IF;

  v_cur_lat := v_lat;
  v_cur_lng := v_lng;

  WHILE cardinality(v_remaining) > 0 LOOP
    v_next := NULL;
    v_next_dist := NULL;
    v_next_lat := NULL;
    v_next_lng := NULL;

    FOREACH v_id IN ARRAY v_remaining LOOP
      SELECT COALESCE(dj.dropoff_lat, dj.pickup_lat),
             COALESCE(dj.dropoff_lng, dj.pickup_lng)
      INTO v_jlat, v_jlng
      FROM public.delivery_jobs dj
      WHERE dj.id = v_id;

      v_d := public._haversine_meters(v_cur_lat, v_cur_lng, v_jlat, v_jlng);

      IF v_next IS NULL
         OR (v_d IS NOT NULL AND (v_next_dist IS NULL OR v_d < v_next_dist))
         OR (v_d IS NULL AND v_next_dist IS NULL AND v_next > v_id) THEN
        v_next := v_id;
        v_next_dist := v_d;
        v_next_lat := v_jlat;
        v_next_lng := v_jlng;
      END IF;
    END LOOP;

    v_seq := v_seq + 1;
    v_results := array_append(v_results, v_next);
    v_dists := array_append(v_dists, v_next_dist);

    UPDATE public.delivery_jobs
    SET route_sequence = v_seq, updated_at = now()
    WHERE id = v_next;

    v_remaining := array_remove(v_remaining, v_next);
    IF v_next_lat IS NOT NULL AND v_next_lng IS NOT NULL THEN
      v_cur_lat := v_next_lat;
      v_cur_lng := v_next_lng;
    END IF;
  END LOOP;

  FOR v_seq IN 1 .. cardinality(v_results) LOOP
    delivery_job_id := v_results[v_seq];
    route_sequence := v_seq;
    distance_m := v_dists[v_seq];
    RETURN NEXT;
  END LOOP;
END;
$$;


--
-- Name: park_pos_cart(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.park_pos_cart(p_cart_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cart public.pos_carts%ROWTYPE;
BEGIN
  PERFORM public._require_cart_mutate(p_cart_id);

  SELECT * INTO v_cart FROM public.pos_carts WHERE id = p_cart_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'cart not found: %', p_cart_id;
  END IF;
  IF v_cart.status <> 'open' THEN
    RAISE EXCEPTION 'only open carts can be parked (got %)', v_cart.status;
  END IF;

  UPDATE public.pos_carts
  SET status = 'parked', updated_at = now()
  WHERE id = p_cart_id;

  RETURN p_cart_id;
END;
$$;


--
-- Name: payslip_render_payload(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.payslip_render_payload(p_payroll_line_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_line public.payroll_lines%ROWTYPE;
  v_run public.payroll_runs%ROWTYPE;
  v_emp public.employees%ROWTYPE;
  v_ps public.payslips%ROWTYPE;
  v_deductions JSONB;
  v_self UUID;
BEGIN
  SELECT * INTO v_line FROM public.payroll_lines WHERE id=p_payroll_line_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'payroll line not found: %',p_payroll_line_id; END IF;
  SELECT * INTO v_run FROM public.payroll_runs WHERE id=v_line.payroll_run_id;
  SELECT * INTO v_emp FROM public.employees WHERE id=v_line.employee_id;
  SELECT * INTO v_ps FROM public.payslips WHERE payroll_line_id=p_payroll_line_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'payslip metadata not found for payroll line %',p_payroll_line_id; END IF;

  v_self := public.current_employee_id();
  IF NOT (
    auth.role()='service_role'
    OR public.has_staff_role(ARRAY['admin','hr']::public.staff_role[])
    OR v_self IS NOT DISTINCT FROM v_line.employee_id
  ) THEN RAISE EXCEPTION 'admin/hr or own payslip only'; END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object('label',d.label,'amount',d.amount) ORDER BY d.created_at,d.id),'[]'::jsonb)
  INTO v_deductions FROM public.payroll_deduction_lines d WHERE d.payroll_line_id=p_payroll_line_id;

  RETURN jsonb_build_object(
    'storeName','Nissan GTR Auto',
    'employeeName',v_emp.full_name,
    'employeeCode',v_emp.employee_code,
    'periodStart',v_run.period_start,
    'periodEnd',v_run.period_end,
    'currency',v_run.currency,
    'grossPay',v_line.gross_amount,
    'manualDeductions',v_deductions,
    'netPay',v_line.net_amount,
    'storageBucket',v_ps.storage_bucket,
    'storagePath',v_ps.storage_path
  );
END;
$$;


--
-- Name: petty_cash_funding_account_code(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.petty_cash_funding_account_code() RETURNS character varying
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(
    (
      SELECT CASE
        WHEN jsonb_typeof(s.value_json) = 'string' THEN nullif(s.value_json #>> '{}', '')
        WHEN jsonb_typeof(s.value_json) = 'object' THEN nullif(s.value_json ->> 'code', '')
        ELSE NULL
      END
      FROM public.app_settings s
      WHERE s.key = 'finance.petty_cash_funding_account_code'
    ),
    '1100'
  )::varchar(10);
$$;


--
-- Name: pos_action_requires_manager(text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pos_action_requires_manager(p_action text, p_value numeric DEFAULT 0) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 SELECT COALESCE((SELECT always_require_manager OR COALESCE(p_value,0) > threshold_value
   FROM public.pos_approval_policies WHERE action=p_action), true);
$$;


--
-- Name: pos_badge_approve(text, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pos_badge_approve(p_badge text, p_action text, p_args jsonb DEFAULT '{}'::jsonb, p_device_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  b public.staff_approval_badges%ROWTYPE;
  v_parts text[]; v_secret text; v_grant uuid; v_result jsonb; v_name text; v_holder_user uuid;
  v_err text; v_reject text; a jsonb := COALESCE(p_args, '{}'::jsonb);
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'sign in required'; END IF;
  IF p_action NOT IN ('discount','price_override','void_sale','refund','cash_out','till_variance','till_handover','repair_paid_order',
                      'split_refund_approve','split_refund_complete','split_refund_fail',
                      'return_post','core_return','warranty_approve','warranty_reject','card_refund_begin','card_refund_finish') THEN
    RAISE EXCEPTION 'unknown action %', p_action;
  END IF;
  IF (SELECT count(*) FROM public.staff_badge_approvals x
      WHERE x.requested_by = auth.uid() AND x.outcome = 'rejected' AND x.created_at > now() - interval '15 minutes') >= 5 THEN
    RAISE EXCEPTION 'too many rejected badge scans; try again in 15 minutes or ask the approver to sign in';
  END IF;

  v_parts := string_to_array(trim(COALESCE(p_badge, '')), ':');
  IF array_length(v_parts, 1) = 3 AND v_parts[1] = 'GTRMGR1' AND v_parts[2] ~ '^[0-9a-f-]{36}$' THEN
    v_secret := v_parts[3];
    SELECT * INTO b FROM public.staff_approval_badges WHERE id = v_parts[2]::uuid FOR UPDATE;
  END IF;
  v_reject := CASE
    WHEN b.id IS NULL THEN 'not an approval badge'
    WHEN b.token_sha256 <> encode(extensions.digest(v_secret, 'sha256'), 'hex') THEN 'badge not recognised'
    WHEN b.revoked_at IS NOT NULL THEN 'badge revoked'
    WHEN b.expires_at <= now() THEN 'badge expired'
    WHEN private.badge_holder_source(b.employee_id, b.user_id) IS NULL THEN 'badge holder is no longer an approver'
    ELSE NULL END;
  IF v_reject IS NOT NULL THEN
    INSERT INTO public.staff_badge_approvals(badge_id, approver_employee_id, approver_user_id, requested_by, action, args, device_id, outcome, error)
    VALUES (b.id, b.employee_id, b.user_id, auth.uid(), p_action, a, p_device_id, 'rejected', v_reject);
    RETURN jsonb_build_object('ok', false, 'error', v_reject);
  END IF;
  v_holder_user := COALESCE(b.user_id, (SELECT e.user_id FROM public.employees e WHERE e.id = b.employee_id));
  SELECT COALESCE(e.full_name, u.email::text) INTO v_name
  FROM (SELECT 1) one LEFT JOIN public.employees e ON e.id = b.employee_id LEFT JOIN auth.users u ON u.id = b.user_id;

  BEGIN
    INSERT INTO private.staff_badge_grants(txid, requested_by, approver_employee_id, approver_user_id, badge_id)
    VALUES (txid_current(), auth.uid(), b.employee_id, v_holder_user, b.id) RETURNING id INTO v_grant;
    PERFORM set_config('gtr.pos_badge_grant', v_grant::text, true);

    v_result := CASE p_action
      WHEN 'discount' THEN to_jsonb(public.apply_pos_cart_discount_governed((a->>'cart_id')::uuid, (a->>'percent')::numeric, a->>'reason_code', a->>'notes'))
      WHEN 'price_override' THEN to_jsonb(public.apply_pos_line_price_override_governed((a->>'line_id')::uuid, (a->>'unit_price')::numeric, a->>'reason_code', a->>'notes'))
      WHEN 'void_sale' THEN to_jsonb(public.void_pos_cart_governed((a->>'cart_id')::uuid, a->>'reason_code', a->>'notes'))
      WHEN 'refund' THEN to_jsonb(public.post_pos_refund_governed((a->>'invoice_id')::uuid, a->>'reason_code', a->>'notes'))
      WHEN 'cash_out' THEN to_jsonb(public.record_pos_till_cash_movement((a->>'session_id')::uuid, (a->>'kind')::public.pos_till_cash_movement_kind,
                                     (a->>'amount')::numeric, a->>'reason_code', a->>'notes'))
      WHEN 'till_variance' THEN to_jsonb(public.approve_pos_till_variance((a->>'session_id')::uuid, a->>'reason_code', a->>'notes'))
      WHEN 'till_handover' THEN to_jsonb(public.handover_pos_till_session((a->>'session_id')::uuid, (a->>'new_operator_user_id')::uuid, a->>'notes'))
      WHEN 'repair_paid_order' THEN to_jsonb(public.repair_pos_paid_order((a->>'order_id')::uuid, a->>'notes'))
      WHEN 'split_refund_approve' THEN public.approve_pos_split_refund((a->>'refund_id')::uuid, COALESCE(a->>'fee_policy', 'business_absorbs'),
                                     (a->>'estimated_provider_fee')::numeric, (a->>'estimated_transfer_fee')::numeric,
                                     COALESCE((a->>'customer_fee')::numeric, 0), COALESCE((a->>'expected_days')::integer, 3), a->>'notes')
      WHEN 'split_refund_complete' THEN public.complete_pos_split_refund((a->>'refund_id')::uuid, a->>'provider_ref',
                                     (a->>'actual_provider_fee')::numeric, (a->>'actual_transfer_fee')::numeric,
                                     (a->>'actual_customer_fee')::numeric, a->>'notes')
      WHEN 'split_refund_fail' THEN public.fail_pos_split_refund((a->>'refund_id')::uuid, a->>'reason')
      WHEN 'return_post' THEN to_jsonb(public.post_pos_return_case((a->>'return_case_id')::uuid))
      WHEN 'core_return' THEN to_jsonb(public.post_pos_core_return((a->>'invoice_id')::uuid, (a->>'core_line_id')::uuid, (a->>'qty')::numeric,
                                     (a->>'resolution')::public.pos_core_return_resolution, a->>'reason_code', (a->>'till_session_id')::uuid, a->>'notes'))
      WHEN 'warranty_approve' THEN to_jsonb(public.approve_pos_warranty_claim((a->>'claim_id')::uuid, (a->>'resolution')::public.warranty_claim_resolution,
                                     a->'lines', a->'replacement_lines'))
      WHEN 'warranty_reject' THEN to_jsonb(public.reject_pos_warranty_claim((a->>'claim_id')::uuid, a->>'reason'))
      WHEN 'card_refund_begin' THEN public.begin_pos_card_terminal_refund((a->>'invoice_id')::uuid, (a->>'terminal_id')::uuid, (a->>'request_id')::uuid)
      WHEN 'card_refund_finish' THEN public.finalize_pos_card_terminal_refund((a->>'attempt_id')::uuid, a->>'notes')
    END;

    -- The governed functions stamp auth.uid() as approver; under a badge the approver is its holder.
    UPDATE public.pos_action_audit SET approved_by_user_id = v_holder_user, approved_by_employee_id = b.employee_id
    WHERE created_at = now() AND actor_user_id = auth.uid() AND approved_by_user_id = auth.uid();
    DELETE FROM private.staff_badge_grants WHERE id = v_grant;
  EXCEPTION WHEN OTHERS THEN
    v_err := SQLERRM;
  END;
  PERFORM set_config('gtr.pos_badge_grant', '', true);

  IF v_err IS NOT NULL THEN
    INSERT INTO public.staff_badge_approvals(badge_id, approver_employee_id, approver_user_id, requested_by, action, args, device_id, outcome, error)
    VALUES (b.id, b.employee_id, b.user_id, auth.uid(), p_action, a, p_device_id, 'failed', v_err);
    RETURN jsonb_build_object('ok', false, 'error', v_err, 'manager_name', v_name);
  END IF;
  UPDATE public.staff_approval_badges SET last_used_at = now(), use_count = use_count + 1 WHERE id = b.id;
  INSERT INTO public.staff_badge_approvals(badge_id, approver_employee_id, approver_user_id, requested_by, action, args, device_id, outcome, result)
  VALUES (b.id, b.employee_id, b.user_id, auth.uid(), p_action, a, p_device_id, 'approved', jsonb_build_object('value', v_result));
  RETURN jsonb_build_object('ok', true, 'manager_name', v_name, 'result', v_result);
END $_$;


--
-- Name: pos_till_expected_cash(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pos_till_expected_cash(p_session_id uuid) RETURNS numeric
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE s public.pos_till_sessions%ROWTYPE; v_cash NUMERIC:=0; v_split_cash NUMERIC:=0; v_direct NUMERIC:=0; v_in NUMERIC:=0; v_out NUMERIC:=0;
BEGIN
 PERFORM public._require_sales_staff(); SELECT * INTO s FROM public.pos_till_sessions WHERE id=p_session_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'till session not found'; END IF;
 IF s.operator_user_id<>auth.uid() AND NOT public.is_pos_approver() AND NOT public.has_staff_role(ARRAY['finance']::public.staff_role[]) THEN RAISE EXCEPTION 'till session access denied'; END IF;
 SELECT COALESCE(SUM(a.amount),0) INTO v_cash FROM public.payment_allocations a JOIN public.payment_entries p ON p.id=a.payment_entry_id JOIN public.sales_invoices i ON i.id=a.sales_invoice_id
 WHERE i.till_session_id=p_session_id AND p.status='posted' AND p.tender='cash';
 SELECT COALESCE(SUM(greatest(l.requested_amount-COALESCE((SELECT SUM(a.amount) FROM public.payment_allocations a WHERE a.payment_entry_id=l.payment_entry_id),0),0)),0)
 INTO v_split_cash FROM public.pos_split_payment_legs l JOIN public.pos_split_payment_sessions ps ON ps.id=l.session_id JOIN public.commerce_orders o ON o.id=ps.commerce_order_id
 JOIN public.pos_carts c ON c.id=o.cart_id WHERE c.till_session_id=p_session_id AND l.tender='cash' AND l.status IN('captured','refund_review','refund_pending');
 SELECT COALESCE(SUM(i.total),0) INTO v_direct FROM public.sales_invoices i WHERE i.till_session_id=p_session_id AND i.status='posted' AND i.doc_type='invoice' AND i.customer_id IS NULL
  AND NOT EXISTS(SELECT 1 FROM public.payment_allocations a WHERE a.sales_invoice_id=i.id);
 SELECT COALESCE(SUM(amount),0) INTO v_in FROM public.pos_till_cash_movements WHERE session_id=p_session_id AND kind='cash_in';
 SELECT COALESCE(SUM(amount),0) INTO v_out FROM public.pos_till_cash_movements WHERE session_id=p_session_id AND kind IN('cash_out','petty_cash','bank_drop','cash_refund');
 RETURN round(s.opening_float+v_cash+v_split_cash+v_direct+v_in-v_out,2);
END $$;


--
-- Name: post_chat_message(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_chat_message(p_thread_id uuid, p_body text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row public.chat_threads;
  v_kind public.chat_sender_kind;
  v_id UUID;
  v_body TEXT := NULLIF(btrim(COALESCE(p_body, '')), '');
BEGIN
  IF v_body IS NULL THEN
    RAISE EXCEPTION 'message body required';
  END IF;

  SELECT * INTO v_row FROM public.chat_threads WHERE id = p_thread_id;
  IF NOT FOUND OR NOT public._can_select_chat_thread(v_row) THEN
    RAISE EXCEPTION 'thread not found or not visible';
  END IF;
  IF v_row.status = 'closed' THEN
    RAISE EXCEPTION 'thread is closed';
  END IF;

  IF v_row.customer_user_id = auth.uid() AND NOT public.is_staff() THEN
    v_kind := 'customer';
  ELSIF public.has_staff_role(public._chat_staff_roles()) THEN
    v_kind := 'staff';
  ELSE
    RAISE EXCEPTION 'not allowed to post';
  END IF;

  INSERT INTO public.chat_messages (thread_id, sender_user_id, sender_kind, body)
  VALUES (p_thread_id, auth.uid(), v_kind, v_body)
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


