--
-- Name: post_journal(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_journal(p_entry_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_date DATE;
  v_status public.journal_status;
  v_doc TEXT;
BEGIN
  IF NOT (
    auth.role() = 'service_role'
    OR public.has_staff_role(ARRAY['admin', 'finance']::public.staff_role[])
    OR public._storefront_rpc_active()
    OR public._pos_posting_active()
  ) THEN
    RAISE EXCEPTION 'finance or admin role required';
  END IF;

  SELECT entry_date, status INTO v_date, v_status
  FROM public.journal_entries
  WHERE id = p_entry_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'journal entry not found: %', p_entry_id;
  END IF;
  IF v_status = 'posted' THEN
    RETURN p_entry_id;
  END IF;
  IF public.is_period_locked(v_date) THEN
    RAISE EXCEPTION 'accounting period is locked for date %', v_date;
  END IF;

  PERFORM public._assert_journal_balanced(p_entry_id);
  v_doc := public.next_series_value('JV-');

  UPDATE public.journal_entries
  SET
    status = 'posted',
    posted_at = now(),
    posted_by = COALESCE(auth.uid(), posted_by),
    document_number = COALESCE(document_number, v_doc)
  WHERE id = p_entry_id;

  RETURN p_entry_id;
END;
$$;


--
-- Name: post_journal_entry(date, text, public.currency_code, numeric, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_journal_entry(p_entry_date date, p_description text, p_currency public.currency_code, p_exchange_rate numeric, p_lines jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id UUID;
BEGIN
  v_id := public.create_journal_draft(
    p_entry_date, p_description, p_currency, p_exchange_rate, p_lines
  );
  RETURN public.post_journal(v_id);
END;
$$;


