-- Name: post_opening_balances(date, public.currency_code, numeric, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_opening_balances(p_as_of date, p_currency public.currency_code, p_exchange_rate numeric, p_lines jsonb) RETURNS uuid
