END;
$$;


--
-- Name: post_payment_entry(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_payment_entry(p_payment_entry_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_pe public.payment_entries%ROWTYPE;
  v_alloc RECORD;
  v_sum NUMERIC := 0;
  v_overpay NUMERIC;
  v_cash_acct TEXT;
  v_lines JSONB := '[]'::jsonb;
  v_journal UUID;
  v_inv public.sales_invoices%ROWTYPE;
  v_open NUMERIC;
  v_event TEXT;
  v_all_cleared BOOLEAN := true;
BEGIN
  PERFORM public._require_payments_staff();
  PERFORM public._payments_rpc_enter();

  SELECT * INTO v_pe FROM public.payment_entries WHERE id = p_payment_entry_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'payment entry not found: %', p_payment_entry_id;
  END IF;
  IF v_pe.status = 'posted' THEN
    RETURN p_payment_entry_id;
  END IF;
  IF v_pe.status <> 'draft' THEN
    RAISE EXCEPTION 'only draft payments can be posted';
  END IF;

  SELECT COALESCE(SUM(amount), 0) INTO v_sum
  FROM public.payment_allocations
  WHERE payment_entry_id = p_payment_entry_id;

  IF v_sum <= 0 AND v_pe.tender <> 'store_credit' THEN
    RAISE EXCEPTION 'payment requires at least one allocation';
  END IF;
  IF v_sum > v_pe.amount + 0.001 THEN
    RAISE EXCEPTION 'allocations exceed payment amount';
  END IF;

  FOR v_alloc IN
    SELECT * FROM public.payment_allocations WHERE payment_entry_id = p_payment_entry_id
  LOOP
    SELECT * INTO v_inv FROM public.sales_invoices WHERE id = v_alloc.sales_invoice_id FOR UPDATE;
    v_open := v_inv.total - v_inv.amount_paid;
    IF v_alloc.amount > v_open + 0.001 THEN
      RAISE EXCEPTION 'over-allocate denied at post: invoice %', v_inv.document_number;
    END IF;
  END LOOP;

  IF v_pe.tender = 'store_credit' THEN
    PERFORM public._append_store_credit(
      v_pe.customer_id, 'redeem', v_pe.amount, v_pe.currency,
      v_pe.exchange_rate_applied, p_payment_entry_id, NULL,
      format('Redeem on %s', COALESCE(v_pe.document_number, p_payment_entry_id::text))
    );
    v_cash_acct := public.gl_account_for_payment_tender('store_credit'::public.payment_tender);
  ELSE
    v_cash_acct := public.gl_account_for_payment_tender(v_pe.tender);
  END IF;

  v_overpay := round(v_pe.amount - v_sum, 2);
  v_lines := jsonb_build_array(
    jsonb_build_object(
      'account_code', v_cash_acct,
      'debit', v_pe.amount, 'credit', 0, 'currency', v_pe.currency
    )
  );
  IF v_sum > 0 THEN
    v_lines := v_lines || jsonb_build_array(
      jsonb_build_object(
        'account_code', '1200',
        'debit', 0, 'credit', v_sum, 'currency', v_pe.currency
      )
    );
  END IF;
  IF v_overpay > 0 THEN
    v_lines := v_lines || jsonb_build_array(
      jsonb_build_object(
        'account_code', '2200',
        'debit', 0, 'credit', v_overpay, 'currency', v_pe.currency
      )
    );
  END IF;

  v_journal := public.post_journal_entry(
    CURRENT_DATE,
    format('Payment %s', COALESCE(v_pe.document_number, p_payment_entry_id::text)),
    v_pe.currency,
    v_pe.exchange_rate_applied,
    v_lines
  );

  IF v_overpay > 0 THEN
    PERFORM public._append_store_credit(
      v_pe.customer_id, 'issue', v_overpay, v_pe.currency,
      v_pe.exchange_rate_applied, p_payment_entry_id, v_journal,
      'Overpay → store credit'
    );
    PERFORM public.emit_domain_event(
      'refund_issued',
      'sc:overpay:' || p_payment_entry_id::text,
      jsonb_build_object(
        'payment_entry_id', p_payment_entry_id,
        'amount', v_overpay,
        'currency', v_pe.currency
      ),
      auth.uid(),
      format('GTR Auto: store credit issued %s %s', v_overpay, v_pe.currency)
    );
  END IF;

  FOR v_alloc IN
    SELECT * FROM public.payment_allocations WHERE payment_entry_id = p_payment_entry_id
  LOOP
    UPDATE public.sales_invoices
    SET amount_paid = amount_paid + v_alloc.amount
    WHERE id = v_alloc.sales_invoice_id
    RETURNING * INTO v_inv;

    IF v_inv.amount_paid + 0.001 < v_inv.total THEN
      v_all_cleared := false;
    END IF;

    UPDATE public.customers
    SET open_balance = GREATEST(0, open_balance - v_alloc.amount),
        updated_at = now()
    WHERE id = v_pe.customer_id;
  END LOOP;

  UPDATE public.payment_entries
  SET
    status = 'posted',
    journal_entry_id = v_journal,
    store_credit_issued = COALESCE(v_overpay, 0),
    posted_by = auth.uid(),
    posted_at = now(),
    updated_at = now()
  WHERE id = p_payment_entry_id;

  IF v_all_cleared AND v_sum > 0 AND v_overpay = 0 THEN
    v_event := 'payment_received';
  ELSIF v_sum > 0 AND NOT v_all_cleared THEN
    v_event := 'payment_partial';
  ELSE
    v_event := 'payment_received';
  END IF;

  PERFORM public.emit_domain_event(
    v_event,
    'payment:' || v_event || ':' || p_payment_entry_id::text,
    jsonb_build_object(
      'payment_entry_id', p_payment_entry_id,
      'amount', v_pe.amount,
      'allocated', v_sum,
      'currency', v_pe.currency,
      'tender', v_pe.tender,
      'gl_account', v_cash_acct
    ),
    auth.uid(),
    format('GTR Auto: %s %s %s', v_event, v_pe.amount, v_pe.currency)
  );

  RETURN p_payment_entry_id;
END;
$$;


--
-- Name: post_pos_core_return(uuid, uuid, numeric, public.pos_core_return_resolution, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_pos_core_return(p_invoice_id uuid, p_source_core_line_id uuid, p_qty numeric, p_resolution public.pos_core_return_resolution, p_reason_code text, p_till_session_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE i public.sales_invoices%ROWTYPE; l public.sales_invoice_lines%ROWTYPE; v_prev NUMERIC; v_amt NUMERIC; v_j UUID; v_cn UUID; v_id UUID; v_sc UUID; v_stock UUID;
 v_lines JSONB; v_till UUID;
BEGIN
 IF NOT public.is_pos_approver() THEN RAISE EXCEPTION 'POS manager approval required'; END IF;
 SELECT * INTO i FROM public.sales_invoices WHERE id=p_invoice_id AND status='posted' AND doc_type='invoice' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'posted source invoice required'; END IF;
 SELECT * INTO l FROM public.sales_invoice_lines WHERE id=p_source_core_line_id AND invoice_id=p_invoice_id AND is_core_charge FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'core-charge invoice line required'; END IF;
 IF COALESCE(p_qty,0)<=0 THEN RAISE EXCEPTION 'core return qty must be > 0'; END IF;
 SELECT COALESCE(SUM(qty),0) INTO v_prev FROM public.pos_core_returns WHERE source_core_line_id=l.id;
 IF p_qty>l.qty-v_prev THEN RAISE EXCEPTION 'core return qty exceeds remaining eligible core qty'; END IF;
 IF trim(COALESCE(p_reason_code,''))='' THEN RAISE EXCEPTION 'core return reason required'; END IF;
 v_amt:=round(p_qty*l.unit_price,2); v_till:=COALESCE(p_till_session_id,i.till_session_id);
 IF p_resolution='account_credit' AND i.customer_id IS NULL THEN RAISE EXCEPTION 'account credit requires named customer'; END IF;
 IF p_resolution='store_credit' AND i.customer_id IS NULL THEN RAISE EXCEPTION 'store credit requires named customer'; END IF;
 IF p_resolution='cash_refund' AND v_till IS NULL THEN RAISE EXCEPTION 'cash core refund requires active till session'; END IF;
 v_j:=public.post_journal_entry(CURRENT_DATE,format('Core return against %s',i.document_number),i.currency,i.exchange_rate_applied,
  CASE p_resolution
   WHEN 'cash_refund' THEN jsonb_build_array(jsonb_build_object('account_code','4200','debit',v_amt,'credit',0,'currency',i.currency),jsonb_build_object('account_code','1100','debit',0,'credit',v_amt,'currency',i.currency))
   WHEN 'account_credit' THEN jsonb_build_array(jsonb_build_object('account_code','4200','debit',v_amt,'credit',0,'currency',i.currency),jsonb_build_object('account_code','1200','debit',0,'credit',v_amt,'currency',i.currency))
   ELSE jsonb_build_array(jsonb_build_object('account_code','4200','debit',v_amt,'credit',0,'currency',i.currency),jsonb_build_object('account_code','2200','debit',0,'credit',v_amt,'currency',i.currency)) END);
 IF p_resolution='account_credit' THEN UPDATE public.customers SET open_balance=open_balance-v_amt,updated_at=now() WHERE id=i.customer_id;
 ELSIF p_resolution='store_credit' THEN v_sc:=public._append_store_credit(i.customer_id,'issue',v_amt,i.currency,i.exchange_rate_applied,NULL,v_j,format('Core return %s',i.document_number));
 END IF;
 INSERT INTO public.sales_invoices(doc_type,status,document_number,customer_id,warehouse_id,currency,exchange_rate_applied,subtotal,total,amount_paid,return_against_id,journal_entry_id,
  customer_phone_e164,customer_email,customer_whatsapp_e164,posted_by,posted_at,till_session_id)
 VALUES('credit_note','posted',public.next_series_value('CN-'),i.customer_id,i.warehouse_id,i.currency,i.exchange_rate_applied,v_amt,v_amt,0,p_invoice_id,v_j,
  i.customer_phone_e164,i.customer_email,i.customer_whatsapp_e164,auth.uid(),now(),v_till) RETURNING id INTO v_cn;
 INSERT INTO public.sales_invoice_lines(invoice_id,stock_item_id,parent_line_id,is_core_charge,uom_id,qty,qty_base,unit_price,line_total,qty_fulfilled)
 VALUES(v_cn,l.stock_item_id,NULL,true,l.uom_id,p_qty,public.convert_to_base_uom(l.stock_item_id,l.uom_id,p_qty),l.unit_price,v_amt,public.convert_to_base_uom(l.stock_item_id,l.uom_id,p_qty));
 v_lines:=jsonb_build_array(jsonb_build_object('stock_item_id',l.stock_item_id,'uom_id',l.uom_id,'qty',p_qty,'unit_price',0,'currency',i.currency));
 v_stock:=private.receive_external_return_to_quarantine(v_lines,format('Core returned against %s',i.document_number));
 INSERT INTO public.pos_core_returns(document_number,source_invoice_id,source_core_line_id,qty,amount,resolution,reason_code,notes,till_session_id,credit_note_id,quarantine_stock_entry_id,journal_entry_id,store_credit_ledger_id,posted_by)
 VALUES(public.next_series_value('CORE-'),p_invoice_id,p_source_core_line_id,p_qty,v_amt,p_resolution,p_reason_code,p_notes,v_till,v_cn,v_stock,v_j,v_sc,auth.uid()) RETURNING id INTO v_id;
 IF p_resolution='cash_refund' THEN PERFORM public.record_pos_till_cash_movement(v_till,'cash_refund',v_amt,'customer_refund',concat_ws(' · ','Core return',p_notes),NULL); END IF;
 PERFORM public._log_pos_action('core_return_posted','pos_core_returns',v_id,NULL,jsonb_build_object('invoice_id',p_invoice_id,'amount',v_amt,'resolution',p_resolution,'credit_note_id',v_cn),p_notes);
 UPDATE public.pos_action_audit SET reason_code=p_reason_code,approved_by_user_id=auth.uid(),approval_policy_action='core_return'
 WHERE id=(SELECT id FROM public.pos_action_audit WHERE entity_type='pos_core_returns' AND entity_id=v_id ORDER BY created_at DESC LIMIT 1);
 RETURN v_id;
END $$;


--
-- Name: post_pos_refund(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_pos_refund(p_invoice_id uuid, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_prev text := COALESCE(current_setting('app.pos_posting', true), '');
  v_result uuid;
BEGIN
  -- Role checks stay in _post_pos_refund_core; this only marks its ledger posting as internal.
  PERFORM set_config('app.pos_posting', '1', true);
  v_result := public._post_pos_refund_core(p_invoice_id, p_notes);
  PERFORM set_config('app.pos_posting', v_prev, true);
  RETURN v_result;
END;
$$;


--
-- Name: FUNCTION post_pos_refund(p_invoice_id uuid, p_notes text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.post_pos_refund(p_invoice_id uuid, p_notes text) IS 'POS entry point. Logic lives in _post_pos_refund_core; change that, not this wrapper (see 20261001110000).';


--
-- Name: post_pos_refund_governed(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_pos_refund_governed(p_invoice_id uuid, p_reason_code text, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v UUID;
BEGIN
 PERFORM private.require_pos_reason('refund_full_invoice',p_reason_code);
 IF public.pos_action_requires_manager('refund_full_invoice',0)
    AND NOT public.is_pos_approver() THEN
  RAISE EXCEPTION 'POS manager approval required';
 END IF;
 v:=public.post_pos_refund(p_invoice_id,concat_ws(' · ',p_reason_code,p_notes));
 UPDATE public.pos_action_audit
 SET reason_code=p_reason_code,
     approved_by_user_id=CASE WHEN public.is_pos_approver() THEN auth.uid() ELSE NULL END,
     approval_policy_action='refund_full_invoice'
 WHERE id=(SELECT id FROM public.pos_action_audit
   WHERE action='refund_posted' AND entity_id=v ORDER BY created_at DESC LIMIT 1);
 RETURN v;
END $$;


--
-- Name: post_pos_return_case(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_pos_return_case(p_return_case_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE c public.pos_return_cases%ROWTYPE; i public.sales_invoices%ROWTYPE; v_lines JSONB; v_src_lines JSONB; v_cn UUID; v_amount NUMERIC:=0;
 v_adj UUID; v_sc UUID; v_repl UUID; v_claim UUID; v_first_item UUID; v_current NUMERIC; r RECORD; v_till UUID; v_paid_out NUMERIC;
 v_prev_accounting text := COALESCE(current_setting('app.sales_checkout_accounting',true),'');
BEGIN
 IF NOT public.is_pos_approver() THEN RAISE EXCEPTION 'POS manager approval required'; END IF;
 SELECT * INTO c FROM public.pos_return_cases WHERE id=p_return_case_id FOR UPDATE;
 IF NOT FOUND OR c.status<>'draft' THEN RAISE EXCEPTION 'draft return case required'; END IF;
 SELECT * INTO i FROM public.sales_invoices WHERE id=c.source_invoice_id AND status='posted' AND doc_type='invoice' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'posted source invoice required'; END IF;
 -- A manager approved this return: its credit note, payout journal and store credit are part of the
 -- sale's own accounting, so a manager without the finance role can post them.
 PERFORM public._sales_checkout_accounting_enter();
 FOR r IN SELECT rl.source_invoice_line_id,rl.qty,sl.qty sold_qty FROM public.pos_return_case_lines rl JOIN public.sales_invoice_lines sl ON sl.id=rl.source_invoice_line_id WHERE rl.return_case_id=p_return_case_id LOOP
  SELECT COALESCE(SUM(x.qty),0) INTO v_current FROM public.pos_return_case_lines x JOIN public.pos_return_cases xc ON xc.id=x.return_case_id
   WHERE x.source_invoice_line_id=r.source_invoice_line_id AND xc.status='posted';
  IF r.qty+v_current>r.sold_qty THEN RAISE EXCEPTION 'return quantity exceeds remaining sold quantity'; END IF;
 END LOOP;
 SELECT COALESCE(jsonb_agg(jsonb_build_object('stock_item_id',l.stock_item_id,'uom_id',l.uom_id,'qty',l.qty,'unit_price',l.unit_price,'currency',i.currency)),'[]'::jsonb),
        COALESCE(jsonb_agg(jsonb_build_object('source_invoice_line_id',l.source_invoice_line_id,'qty',l.qty)),'[]'::jsonb),
        COALESCE(SUM(round(l.qty*l.unit_price,2)),0),min(l.stock_item_id::text)::uuid
 INTO v_lines,v_src_lines,v_amount,v_first_item FROM public.pos_return_case_lines l WHERE l.return_case_id=p_return_case_id;
 IF jsonb_array_length(v_lines)=0 THEN RAISE EXCEPTION 'return case has no lines'; END IF;
 v_till:=COALESCE(c.till_session_id,i.till_session_id);

 IF c.resolution IN('credit_note','cash_refund','store_credit') THEN
  IF c.resolution IN('credit_note','store_credit') AND i.customer_id IS NULL THEN
   RAISE EXCEPTION '% requires named customer',replace(c.resolution::text,'_',' ');
  END IF;
  IF c.resolution='cash_refund' AND v_till IS NULL THEN RAISE EXCEPTION 'cash refund requires active till session'; END IF;
  -- The credit note is valued from the source lines (discounts included): that value is what goes back.
  v_cn:=private._post_pos_credit_note(c.source_invoice_id,v_src_lines,
    CASE WHEN c.resolution='cash_refund' AND i.customer_id IS NULL THEN '1100' ELSE '1200' END,
    format('Return %s credit note against %s',c.document_number,COALESCE(i.document_number,i.id::text)));
  SELECT total INTO v_amount FROM public.sales_invoices WHERE id=v_cn;
  IF c.resolution IN('cash_refund','store_credit') THEN
   -- Money only goes back for what was paid: an unpaid (account) sale is settled by the credit note.
   SELECT COALESCE(SUM(cn.total),0) INTO v_paid_out FROM public.pos_return_cases pc JOIN public.sales_invoices cn ON cn.id=pc.credit_note_id
    WHERE pc.source_invoice_id=i.id AND pc.status='posted' AND pc.resolution IN('cash_refund','store_credit');
   IF v_amount+v_paid_out>COALESCE(i.amount_paid,i.total)+0.005 THEN
    RAISE EXCEPTION 'refund exceeds amount paid on the sale; use credit note';
   END IF;
  END IF;
  IF c.resolution='cash_refund' THEN
   IF i.customer_id IS NOT NULL THEN
    v_adj:=public.post_journal_entry(CURRENT_DATE,format('Cash payout for return %s',c.document_number),i.currency,i.exchange_rate_applied,
      jsonb_build_array(jsonb_build_object('account_code','1200','debit',v_amount,'credit',0,'currency',i.currency),jsonb_build_object('account_code','1100','debit',0,'credit',v_amount,'currency',i.currency)));
    UPDATE public.customers SET open_balance=open_balance+v_amount,updated_at=now() WHERE id=i.customer_id;
   END IF;
   PERFORM public.record_pos_till_cash_movement(v_till,'cash_refund',v_amount,'customer_refund',c.notes,NULL);
  ELSIF c.resolution='store_credit' THEN
   v_sc:=public.issue_store_credit(i.customer_id,v_amount,i.currency,i.exchange_rate_applied,format('Return %s store credit',c.document_number),'1200');
   UPDATE public.customers SET open_balance=open_balance+v_amount,updated_at=now() WHERE id=i.customer_id;
  END IF;
 ELSIF c.resolution='replacement' THEN
  PERFORM private.receive_external_return_to_quarantine(v_lines,format('Return %s replacement received',c.document_number));
  v_repl:=private.issue_pos_replacement_stock(i.warehouse_id,c.replacement_lines,format('Return %s replacement issued',c.document_number));
 ELSIF c.resolution='warranty' THEN
  IF jsonb_array_length(v_lines)<>1 THEN RAISE EXCEPTION 'warranty submission supports one claimed item per case'; END IF;
  v_claim:=public.open_warranty_claim(NULL,c.source_invoice_id,NULL,concat_ws(' · ',c.document_number,c.notes));
  UPDATE public.warranty_claims SET stock_item_id=v_first_item WHERE id=v_claim;
 ELSE RAISE EXCEPTION 'unsupported return resolution'; END IF;

 UPDATE public.pos_return_cases SET status='posted',credit_note_id=v_cn,warranty_claim_id=v_claim,replacement_stock_entry_id=v_repl,
  adjustment_journal_entry_id=v_adj,store_credit_ledger_id=v_sc,approved_by=auth.uid(),approved_at=now(),posted_at=now(),updated_at=now()
 WHERE id=p_return_case_id;
 PERFORM public._log_pos_action('return_posted','pos_return_cases',p_return_case_id,NULL,
  jsonb_build_object('resolution',c.resolution,'amount',v_amount,'credit_note_id',v_cn,'warranty_claim_id',v_claim,'replacement_stock_entry_id',v_repl),c.notes);
 UPDATE public.pos_action_audit SET reason_code=c.reason_code,approved_by_user_id=auth.uid(),approval_policy_action='return_post'
 WHERE id=(SELECT id FROM public.pos_action_audit WHERE entity_type='pos_return_cases' AND entity_id=p_return_case_id ORDER BY created_at DESC LIMIT 1);
 PERFORM set_config('app.sales_checkout_accounting',v_prev_accounting,true);
 RETURN p_return_case_id;
END $$;


--
-- Name: post_return_credit_note(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_return_credit_note(p_invoice_id uuid, p_lines jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$ BEGIN
  RAISE EXCEPTION 'legacy direct return posting disabled; use request/review/receive return workflow';
END; $$;


--
-- Name: post_return_to_quarantine(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_return_to_quarantine(p_from_warehouse_id uuid, p_notes text, p_lines jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_quar UUID;
  v_is_quar BOOLEAN;
BEGIN
  PERFORM public._require_warehouse_staff();

  SELECT id INTO v_quar
  FROM public.warehouses
  WHERE is_quarantine = true AND is_active = true
  ORDER BY code
  LIMIT 1;

  IF v_quar IS NULL THEN
    RAISE EXCEPTION 'no quarantine warehouse configured';
  END IF;

  SELECT is_quarantine INTO v_is_quar
  FROM public.warehouses WHERE id = p_from_warehouse_id;

  -- If already in quarantine, still allow receipt-style adjust into QUAR via transfer path
  IF p_from_warehouse_id = v_quar THEN
    RAISE EXCEPTION 'source is already quarantine; use receipt/issue instead';
  END IF;

  -- Force destination quarantine — never MAIN/saleable
  RETURN public.create_stock_transfer(
    p_from_warehouse_id,
    v_quar,
    COALESCE(p_notes, 'Return to Quarantine'),
    p_lines
  );
END;
$$;


--
-- Name: post_stock_issue(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_stock_issue(p_from_warehouse_id uuid, p_notes text, p_lines jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_entry UUID;
  v_line JSONB;
  v_item UUID;
  v_uom UUID;
  v_qty NUMERIC;
  v_qty_base NUMERIC;
  v_cost NUMERIC;
  v_currency public.currency_code;
  v_val public.valuation_method;
  v_is_quar BOOLEAN;
  v_serial UUID;
BEGIN
  PERFORM public._require_warehouse_staff();

  SELECT is_quarantine INTO v_is_quar
  FROM public.warehouses WHERE id = p_from_warehouse_id;
  IF COALESCE(v_is_quar, false) THEN
    RAISE EXCEPTION 'issue source must be saleable warehouse, not quarantine';
  END IF;

  INSERT INTO public.stock_entries (
    entry_type, status, from_warehouse_id, notes, created_by,
    posted_at, document_number
  )
  VALUES (
    'issue', 'posted', p_from_warehouse_id, p_notes, auth.uid(),
    now(), public.next_series_value('ISS-')
  )
  RETURNING id INTO v_entry;

  FOR v_line IN SELECT * FROM jsonb_array_elements(p_lines)
  LOOP
    v_item := (v_line ->> 'stock_item_id')::uuid;
    v_uom := (v_line ->> 'uom_id')::uuid;
    v_qty := (v_line ->> 'qty')::numeric;
    v_qty_base := public.convert_to_base_uom(v_item, v_uom, v_qty);
    v_val := COALESCE((v_line ->> 'valuation_method')::public.valuation_method, 'FIFO');

    SELECT unit_cost, currency INTO v_cost, v_currency
    FROM public.stock_levels
    WHERE stock_item_id = v_item AND warehouse_id = p_from_warehouse_id;

    PERFORM public._consume_fifo_batches(v_item, p_from_warehouse_id, v_qty_base);
    PERFORM public._adjust_stock_level(
      v_item, p_from_warehouse_id, -v_qty_base, v_val,
      COALESCE(v_cost, 0), COALESCE(v_currency, 'USD')
    );

    INSERT INTO public.stock_entry_lines (
      stock_entry_id, stock_item_id, uom_id, qty, qty_base,
      unit_cost, currency, valuation_method
    )
    VALUES (
      v_entry, v_item, v_uom, v_qty, v_qty_base,
      COALESCE(v_cost, 0), COALESCE(v_currency, 'USD'), v_val
    );

    IF v_line ? 'replacement_serial_id' THEN
      v_serial := (v_line ->> 'replacement_serial_id')::uuid;
      UPDATE public.stock_serials
      SET status = 'sold', warehouse_id = NULL
      WHERE id = v_serial AND stock_item_id = v_item AND status = 'in_stock';
      IF FOUND THEN
        PERFORM public.emit_domain_event(
          'serial_moved',
          'warranty:issue:serial:' || v_serial::text || ':' || v_entry::text,
          jsonb_build_object(
            'stock_serial_id', v_serial,
            'stock_entry_id', v_entry,
            'reason', 'warranty_replacement'
          )
        );
      END IF;
    END IF;
  END LOOP;

  RETURN v_entry;
END;
$$;


--
-- Name: post_stock_receipt(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_stock_receipt(p_to_warehouse_id uuid, p_notes text, p_lines jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_entry UUID;
  v_line JSONB;
  v_line_id UUID;
  v_item UUID;
  v_uom UUID;
  v_qty NUMERIC;
  v_qty_base NUMERIC;
  v_cost NUMERIC;
  v_currency public.currency_code;
  v_val public.valuation_method;
  v_batch UUID;
  v_batch_code TEXT;
  v_oem TEXT;
  v_requires BOOLEAN;
  v_serial TEXT;
  v_wh_quar BOOLEAN;
  v_bin UUID;
BEGIN
  PERFORM public._require_warehouse_staff();

  SELECT is_quarantine INTO v_wh_quar FROM public.warehouses WHERE id = p_to_warehouse_id;
  IF v_wh_quar IS NULL THEN
    RAISE EXCEPTION 'warehouse not found';
  END IF;

  INSERT INTO public.stock_entries (
    entry_type, status, to_warehouse_id, notes, created_by, document_number
  )
  VALUES (
    'receipt',
    'draft',
    p_to_warehouse_id,
    p_notes,
    auth.uid(),
    public.next_series_value('RCV-')
  )
  RETURNING id INTO v_entry;

  IF p_lines IS NULL OR jsonb_array_length(p_lines) = 0 THEN
    RAISE EXCEPTION 'receipt lines required';
  END IF;

  FOR v_line IN SELECT * FROM jsonb_array_elements(p_lines)
  LOOP
    v_item := (v_line ->> 'stock_item_id')::uuid;
    v_uom := (v_line ->> 'uom_id')::uuid;
    v_qty := (v_line ->> 'qty')::numeric;
    v_cost := COALESCE((v_line ->> 'unit_cost')::numeric, 0);
    v_currency := COALESCE((v_line ->> 'currency')::public.currency_code, 'USD');
    v_val := COALESCE((v_line ->> 'valuation_method')::public.valuation_method, 'FIFO');
    v_bin := NULLIF(v_line ->> 'bin_id', '')::uuid;
    v_qty_base := public.convert_to_base_uom(v_item, v_uom, v_qty);

    PERFORM public._assert_bin_in_warehouse(v_bin, p_to_warehouse_id);

    SELECT oem_part_number, requires_serial
    INTO v_oem, v_requires
    FROM public.stock_items WHERE id = v_item;

    v_batch_code := public.next_series_value('BATCH-');

    INSERT INTO public.stock_batches (
      batch_code, stock_item_id, warehouse_id, valuation_method,
      unit_cost, currency, qty_on_hand
    )
    VALUES (
      v_batch_code, v_item, p_to_warehouse_id, v_val, v_cost, v_currency, v_qty_base
    )
    RETURNING id INTO v_batch;

    INSERT INTO public.stock_entry_lines (
      stock_entry_id, stock_item_id, uom_id, qty, qty_base,
      unit_cost, currency, valuation_method, stock_batch_id, bin_id
    )
    VALUES (
      v_entry, v_item, v_uom, v_qty, v_qty_base,
      v_cost, v_currency, v_val, v_batch, v_bin
    )
    RETURNING id INTO v_line_id;

    PERFORM public._adjust_stock_level(
      v_item, p_to_warehouse_id, v_qty_base, v_val, v_cost, v_currency
    );

    IF v_bin IS NOT NULL THEN
      UPDATE public.stock_levels
      SET bin_id = v_bin, updated_at = now()
      WHERE stock_item_id = v_item AND warehouse_id = p_to_warehouse_id;
    END IF;

    INSERT INTO public.inventory_qr_codes (
      oem_part_number, batch_id, valuation_method, stock_item_id,
      stock_batch_id, stock_entry_line_id, payload
    )
    VALUES (
      v_oem,
      v_batch_code,
      v_val,
      v_item,
      v_batch,
      v_line_id,
      public.build_qr_payload(v_oem, v_batch_code, v_val)
    )
    ON CONFLICT (oem_part_number, batch_id) DO UPDATE
    SET payload = EXCLUDED.payload,
        stock_batch_id = EXCLUDED.stock_batch_id,
        stock_entry_line_id = EXCLUDED.stock_entry_line_id;

    IF v_requires THEN
      IF v_line -> 'serials' IS NULL OR jsonb_array_length(v_line -> 'serials') = 0 THEN
        RAISE EXCEPTION 'serials required for item %', v_oem;
      END IF;
      IF jsonb_array_length(v_line -> 'serials') <> round(v_qty_base)::int THEN
        RAISE EXCEPTION 'serial count must equal base qty for item %', v_oem;
      END IF;
      FOR v_serial IN SELECT jsonb_array_elements_text(v_line -> 'serials')
      LOOP
        INSERT INTO public.stock_serials (
          serial_number, stock_item_id, stock_batch_id, warehouse_id,
          stock_entry_line_id, status
        )
        VALUES (
          v_serial, v_item, v_batch, p_to_warehouse_id, v_line_id,
          CASE WHEN v_wh_quar THEN 'quarantine' ELSE 'in_stock' END
        );
      END LOOP;
    END IF;
  END LOOP;

  UPDATE public.stock_entries
  SET status = 'posted', posted_at = now()
  WHERE id = v_entry;

  PERFORM public.emit_domain_event(
    'stock_received',
    'stock_entry:' || v_entry::text,
    jsonb_build_object('stock_entry_id', v_entry, 'warehouse_id', p_to_warehouse_id)
  );

  RETURN v_entry;
END;
$$;


--
-- Name: prepare_customer_checkout(uuid, uuid, interval); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prepare_customer_checkout(p_cart_id uuid, p_checkout_request_id uuid, p_reservation_ttl interval DEFAULT '00:20:00'::interval) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_cust uuid := public._current_customer_id();
  v_cart public.pos_carts%ROWTYPE;
  v_order public.commerce_orders%ROWTYPE;
  v_order_id uuid;
  v_existing uuid;
  v_existing_cart uuid;
  v_exp timestamptz;
  v_subtotal numeric;
  v_snapshot jsonb;
  v_line record;
  v_physical numeric;
  v_reserved numeric;
BEGIN
  IF v_cust IS NULL THEN RAISE EXCEPTION 'customer profile required'; END IF;
  IF p_checkout_request_id IS NULL THEN RAISE EXCEPTION 'checkout_request_id required'; END IF;
  IF p_reservation_ttl IS NULL OR p_reservation_ttl < interval '2 minutes' OR p_reservation_ttl > interval '60 minutes' THEN
    RAISE EXCEPTION 'reservation TTL must be between 2 and 60 minutes';
  END IF;

  SELECT id, cart_id INTO v_existing, v_existing_cart
  FROM public.commerce_orders
  WHERE customer_id = v_cust AND checkout_request_id = p_checkout_request_id;

  IF v_existing IS NOT NULL THEN
    IF v_existing_cart IS DISTINCT FROM p_cart_id THEN
      RAISE EXCEPTION 'checkout_request_id already used for a different cart';
    END IF;
    RETURN v_existing;
  END IF;

  SELECT * INTO v_cart
  FROM public.pos_carts
  WHERE id = p_cart_id
  FOR UPDATE;

  IF NOT FOUND OR v_cart.customer_id IS DISTINCT FROM v_cust OR v_cart.channel <> 'storefront' OR v_cart.status <> 'open' THEN
    RAISE EXCEPTION 'owned open storefront cart required';
  END IF;

  IF v_cart.checkout_order_id IS NOT NULL THEN
    SELECT * INTO v_order
    FROM public.commerce_orders
    WHERE id = v_cart.checkout_order_id
    FOR UPDATE;

    IF FOUND THEN
      IF v_order.finalized_at IS NULL
         AND v_order.state IN ('awaiting_payment','payment_processing','payment_failed')
         AND (v_order.reservation_expires_at IS NULL OR v_order.reservation_expires_at > now()) THEN
        RETURN v_order.id;
      END IF;

      IF v_order.finalized_at IS NULL
         AND v_order.settled_payment_entry_id IS NULL
         AND v_order.state IN ('awaiting_payment','payment_processing','payment_failed') THEN
        PERFORM private.release_commerce_order(v_order.id,'payment_expired','reservation TTL expired before retry');
        SELECT * INTO v_cart FROM public.pos_carts WHERE id=p_cart_id FOR UPDATE;
      END IF;
    END IF;
  END IF;

  SELECT COALESCE(SUM(line_total),0) INTO v_subtotal
  FROM public.pos_cart_lines
  WHERE cart_id = p_cart_id;

  IF v_subtotal <= 0 THEN RAISE EXCEPTION 'cart must contain a payable item'; END IF;

  SELECT jsonb_build_object(
    'schema_version',1,
    'cart_id',v_cart.id,
    'customer_id',v_cart.customer_id,
    'warehouse_id',v_cart.warehouse_id,
    'currency',v_cart.currency,
    'exchange_rate_applied',v_cart.exchange_rate_applied,
    'fulfillment_mode',v_cart.fulfillment_mode,
    'subtotal',v_subtotal,
    'total',v_subtotal,
    'captured_at',now(),
    'lines',COALESCE(jsonb_agg(jsonb_build_object(
      'line_id',l.id,
      'stock_item_id',l.stock_item_id,
      'uom_id',l.uom_id,
      'qty',l.qty,
      'qty_base',l.qty_base,
      'unit_price',l.unit_price,
      'line_total',l.line_total,
      'is_core_charge',l.is_core_charge,
      'issues_stock',l.issues_stock,
      'kit_id',l.kit_id,
      'kit_line_kind',l.kit_line_kind
    ) ORDER BY l.created_at,l.id),'[]'::jsonb)
  ) INTO v_snapshot
  FROM public.pos_cart_lines l
  WHERE l.cart_id=p_cart_id;

  v_exp := now() + p_reservation_ttl;

  INSERT INTO public.commerce_orders(
    customer_id,cart_id,checkout_request_id,warehouse_id,fulfillment_mode,
    currency,exchange_rate_applied,subtotal,total,state,checkout_snapshot,reservation_expires_at
  ) VALUES(
    v_cust,p_cart_id,p_checkout_request_id,v_cart.warehouse_id,v_cart.fulfillment_mode,
    v_cart.currency,v_cart.exchange_rate_applied,v_subtotal,v_subtotal,'checkout_pending',v_snapshot,v_exp
  ) RETURNING id INTO v_order_id;

  FOR v_line IN
    SELECT stock_item_id,SUM(qty_base)::numeric required_qty
    FROM public.pos_cart_lines
    WHERE cart_id=p_cart_id AND COALESCE(issues_stock,true)=true AND is_core_charge=false
    GROUP BY stock_item_id
    ORDER BY stock_item_id
  LOOP
    SELECT quantity INTO v_physical
    FROM public.stock_levels
    WHERE stock_item_id=v_line.stock_item_id AND warehouse_id=v_cart.warehouse_id
    FOR UPDATE;
    v_physical := COALESCE(v_physical,0);

    SELECT COALESCE(SUM(GREATEST(r.reserved_qty-r.consumed_qty,0)),0)
    INTO v_reserved
    FROM public.inventory_reservations r
    WHERE r.stock_item_id=v_line.stock_item_id
      AND r.warehouse_id=v_cart.warehouse_id
      AND r.state IN ('active','allocated')
      AND (r.state='allocated' OR r.expires_at>now());

    IF v_physical-v_reserved < v_line.required_qty THEN
      RAISE EXCEPTION 'insufficient available stock for item %: physical %, reserved %, required %',
        v_line.stock_item_id,v_physical,v_reserved,v_line.required_qty;
    END IF;

    INSERT INTO public.inventory_reservations(
      commerce_order_id,stock_item_id,warehouse_id,required_qty,reserved_qty,
      expires_at,state,reservation_reason
    ) VALUES(
      v_order_id,v_line.stock_item_id,v_cart.warehouse_id,v_line.required_qty,v_line.required_qty,
      v_exp,'active','checkout_payment_hold'
    );
  END LOOP;

  UPDATE public.commerce_orders SET state='awaiting_payment',updated_at=now() WHERE id=v_order_id;
  UPDATE public.pos_carts SET checkout_locked_at=now(),checkout_order_id=v_order_id,updated_at=now() WHERE id=p_cart_id;

  PERFORM private.enqueue_commerce_event(
    'commerce:'||v_order_id::text||':prepared',
    'commerce.checkout_prepared',
    v_order_id,
    jsonb_build_object('cart_id',p_cart_id,'expires_at',v_exp,'total',v_subtotal)
  );

  RETURN v_order_id;
EXCEPTION WHEN unique_violation THEN
  SELECT id, cart_id INTO v_existing, v_existing_cart
  FROM public.commerce_orders
  WHERE customer_id=v_cust AND checkout_request_id=p_checkout_request_id;

  IF v_existing IS NOT NULL THEN
    IF v_existing_cart IS DISTINCT FROM p_cart_id THEN
      RAISE EXCEPTION 'checkout_request_id already used for a different cart';
    END IF;
    RETURN v_existing;
  END IF;
  RAISE;
END;
$$;


--
-- Name: prepare_pos_commerce_checkout(uuid, uuid, interval); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prepare_pos_commerce_checkout(p_cart_id uuid, p_checkout_request_id uuid, p_reservation_ttl interval DEFAULT '00:20:00'::interval) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE c public.pos_carts%ROWTYPE; o public.commerce_orders%ROWTYPE; v_order UUID; v_customer UUID; r RECORD; v_available NUMERIC; v_existing UUID; s public.pos_till_sessions%ROWTYPE;
BEGIN
 PERFORM public._require_sales_staff();
 IF p_checkout_request_id IS NULL THEN RAISE EXCEPTION 'checkout_request_id required'; END IF;
 IF p_reservation_ttl IS NULL OR p_reservation_ttl<interval '2 minutes' OR p_reservation_ttl>interval '60 minutes' THEN RAISE EXCEPTION 'reservation TTL must be between 2 and 60 minutes'; END IF;
 SELECT * INTO c FROM public.pos_carts WHERE id=p_cart_id FOR UPDATE;
 IF NOT FOUND OR c.status<>'open' THEN RAISE EXCEPTION 'open POS cart required'; END IF;
 IF c.created_by IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'POS cart belongs to another operator'; END IF;
 IF c.till_session_id IS NULL THEN RAISE EXCEPTION 'open till session required before payment'; END IF;
 SELECT * INTO s FROM public.pos_till_sessions WHERE id=c.till_session_id FOR UPDATE;
 IF NOT FOUND OR s.status<>'open' OR s.operator_user_id<>auth.uid() OR s.warehouse_id<>c.warehouse_id THEN RAISE EXCEPTION 'active operator till session at cart warehouse required'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.pos_cart_lines WHERE cart_id=p_cart_id) THEN RAISE EXCEPTION 'cart has no lines'; END IF;
 IF c.checkout_order_id IS NOT NULL THEN
  SELECT * INTO o FROM public.commerce_orders WHERE id=c.checkout_order_id FOR UPDATE;
  IF FOUND AND o.finalized_at IS NULL AND o.state IN('awaiting_payment','payment_processing','payment_failed') AND o.reservation_expires_at>now() THEN RETURN o.id; END IF;
  IF FOUND AND o.finalized_at IS NULL AND o.state IN('awaiting_payment','payment_processing','payment_failed') THEN PERFORM private.release_commerce_order(o.id,'payment_expired','POS checkout reservation expired before retry'); END IF;
  SELECT * INTO c FROM public.pos_carts WHERE id=p_cart_id FOR UPDATE;
 END IF;
 SELECT id INTO v_existing FROM public.commerce_orders WHERE checkout_request_id=p_checkout_request_id AND cart_id=p_cart_id;
 IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
 v_customer:=c.customer_id;
 IF v_customer IS NULL THEN v_customer:=public.ensure_pos_walkin_customer(); UPDATE public.pos_carts SET customer_id=v_customer,updated_at=now() WHERE id=p_cart_id; END IF;
 INSERT INTO public.commerce_orders(customer_id,cart_id,checkout_request_id,warehouse_id,fulfillment_mode,currency,exchange_rate_applied,subtotal,total,state,checkout_snapshot,reservation_expires_at)
 SELECT v_customer,c.id,p_checkout_request_id,c.warehouse_id,c.fulfillment_mode,c.currency,c.exchange_rate_applied,
  COALESCE(SUM(l.line_total),0),COALESCE(SUM(l.line_total),0),'checkout_pending',
  jsonb_build_object('cart_id',c.id,'till_session_id',c.till_session_id,'customer_id',v_customer,'warehouse_id',c.warehouse_id,'currency',c.currency,'fulfillment_mode',c.fulfillment_mode,
   'lines',COALESCE(jsonb_agg(jsonb_build_object('line_id',l.id,'stock_item_id',l.stock_item_id,'uom_id',l.uom_id,'qty',l.qty,'qty_base',l.qty_base,'unit_price',l.unit_price,'line_total',l.line_total,'is_core_charge',l.is_core_charge) ORDER BY l.created_at),'[]'::jsonb)),
  now()+p_reservation_ttl
 FROM public.pos_cart_lines l WHERE l.cart_id=c.id GROUP BY c.id,c.warehouse_id,c.fulfillment_mode,c.currency,c.exchange_rate_applied,c.till_session_id
 RETURNING id INTO v_order;
 FOR r IN SELECT stock_item_id,SUM(qty_base)::numeric required_qty FROM public.pos_cart_lines WHERE cart_id=p_cart_id AND COALESCE(issues_stock,true)=true AND NOT is_core_charge GROUP BY stock_item_id ORDER BY stock_item_id LOOP
  v_available:=public.get_inventory_available_quantity(r.stock_item_id,c.warehouse_id)
   -- Parts held for this customer (back-order / transfer attached to this sale) are theirs to buy.
   + COALESCE((SELECT SUM(GREATEST(ir.reserved_qty-ir.consumed_qty,0)) FROM public.inventory_reservations ir
       JOIN public.pos_fulfillment_requests fr ON fr.id=ir.pos_fulfillment_request_id
      WHERE fr.cart_id=c.id AND ir.stock_item_id=r.stock_item_id AND ir.warehouse_id=c.warehouse_id
        AND ir.state='active' AND (ir.expires_at IS NULL OR ir.expires_at>now())),0);
  IF v_available<r.required_qty THEN RAISE EXCEPTION 'insufficient available stock for item % (available %, required %)',r.stock_item_id,v_available,r.required_qty; END IF;
  INSERT INTO public.inventory_reservations(commerce_order_id,stock_item_id,warehouse_id,required_qty,reserved_qty,expires_at,state,reservation_reason)
  VALUES(v_order,r.stock_item_id,c.warehouse_id,r.required_qty,r.required_qty,now()+p_reservation_ttl,'active','pos_checkout_payment_hold');
 END LOOP;
 UPDATE public.commerce_orders SET state='awaiting_payment',updated_at=now() WHERE id=v_order;
 UPDATE public.pos_carts SET checkout_locked_at=now(),checkout_order_id=v_order,updated_at=now() WHERE id=p_cart_id;
 PERFORM private.enqueue_commerce_event('commerce:'||v_order::text||':pos-prepared','commerce.checkout_prepared',v_order,jsonb_build_object('cart_id',p_cart_id,'till_session_id',c.till_session_id));
 RETURN v_order;
EXCEPTION WHEN unique_violation THEN
 SELECT id INTO v_existing FROM public.commerce_orders WHERE checkout_request_id=p_checkout_request_id AND cart_id=p_cart_id; IF v_existing IS NOT NULL THEN RETURN v_existing; END IF; RAISE;
END $$;


--
-- Name: prepare_pos_commerce_checkout_v2(uuid, uuid, interval, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prepare_pos_commerce_checkout_v2(p_cart_id uuid, p_checkout_request_id uuid, p_reservation_ttl interval DEFAULT '00:20:00'::interval, p_receipt_email text DEFAULT NULL::text, p_receipt_whatsapp_e164 text DEFAULT NULL::text, p_receipt_phone_e164 text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_order UUID;
BEGIN
 v_order:=public.prepare_pos_commerce_checkout(p_cart_id,p_checkout_request_id,p_reservation_ttl);
 UPDATE public.commerce_orders
 SET checkout_snapshot=checkout_snapshot||jsonb_strip_nulls(jsonb_build_object(
  'receipt_email',NULLIF(trim(COALESCE(p_receipt_email,'')),''),
  'receipt_whatsapp_e164',NULLIF(trim(COALESCE(p_receipt_whatsapp_e164,'')),''),
  'receipt_phone_e164',NULLIF(trim(COALESCE(p_receipt_phone_e164,'')),'')
 )),updated_at=now()
 WHERE id=v_order;
 RETURN v_order;
END $$;


--
-- Name: process_receipt_outbox_batch(integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_receipt_outbox_batch(p_limit integer DEFAULT 50, p_stub_success boolean DEFAULT true) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row public.customer_receipt_outbox%ROWTYPE;
  v_count INT := 0;
  v_limit INT := LEAST(100, GREATEST(1, COALESCE(p_limit, 50)));
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'service_role required';
  END IF;

  FOR v_row IN
    SELECT *
    FROM public.customer_receipt_outbox
    WHERE status IN ('pending', 'failed')
      AND download_url IS NOT NULL
      AND attempt_count < 8
    ORDER BY created_at
    LIMIT v_limit
    FOR UPDATE SKIP LOCKED
  LOOP
    IF v_row.status = 'sent' THEN
      CONTINUE;
    END IF;

    IF p_stub_success THEN
      UPDATE public.customer_receipt_outbox
      SET
        status = 'sent',
        attempt_count = attempt_count + 1,
        last_error = NULL,
        sent_at = now(),
        claimed_at = NULL
      WHERE id = v_row.id
        AND status IS DISTINCT FROM 'sent';
    ELSE
      UPDATE public.customer_receipt_outbox
      SET
        status = 'failed',
        attempt_count = attempt_count + 1,
        last_error = COALESCE(last_error, 'stub send failed'),
        claimed_at = NULL
      WHERE id = v_row.id
        AND status IS DISTINCT FROM 'sent';
    END IF;

    v_count := v_count + 1;
  END LOOP;

  RETURN v_count;
END;
$$;


--
-- Name: protect_canonical_staff_role(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_canonical_staff_role() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role public.staff_role;
BEGIN
  IF TG_OP = 'INSERT' THEN
    SELECT role INTO v_role FROM public.canonical_staff_accounts
    WHERE user_id = NEW.user_id AND is_active;
    IF FOUND AND NEW.role IS DISTINCT FROM v_role THEN
      RAISE EXCEPTION 'canonical staff % may only hold role %', NEW.user_id, v_role;
    END IF;
    RETURN NEW;
  END IF;

  IF TG_OP = 'DELETE' THEN
    SELECT role INTO v_role FROM public.canonical_staff_accounts
    WHERE user_id = OLD.user_id AND is_active;
    IF FOUND AND OLD.role = v_role
       AND current_user IN ('anon','authenticated','authenticator','service_role') THEN
      RAISE EXCEPTION 'cannot remove authoritative canonical staff role';
    END IF;
    RETURN OLD;
  END IF;
  -- staff_roles is not expected to update its PK, but fail closed if it does.
  SELECT role INTO v_role FROM public.canonical_staff_accounts
  WHERE user_id = OLD.user_id AND is_active;
  IF FOUND AND (NEW.user_id IS DISTINCT FROM OLD.user_id OR NEW.role IS DISTINCT FROM v_role) THEN
    RAISE EXCEPTION 'cannot mutate authoritative canonical staff role';
  END IF;
  SELECT role INTO v_role FROM public.canonical_staff_accounts
  WHERE user_id = NEW.user_id AND is_active;
  IF FOUND AND NEW.role IS DISTINCT FROM v_role THEN
    RAISE EXCEPTION 'canonical staff % may only hold role %', NEW.user_id, v_role;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: protect_profile_staff_flag(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_profile_staff_flag() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  -- Only non-client roles (e.g. postgres / migration / SECURITY DEFINER owner) may change is_staff.
  IF TG_OP = 'INSERT' THEN
    IF NEW.is_staff IS TRUE
       AND current_user IN ('authenticated', 'anon', 'authenticator') THEN
      RAISE EXCEPTION 'is_staff cannot be set on insert; use assign_staff_role';
    END IF;
    NEW.updated_at := now();
    RETURN NEW;
  END IF;

  IF NEW.is_staff IS DISTINCT FROM OLD.is_staff
     AND current_user IN ('authenticated', 'anon', 'authenticator') THEN
    RAISE EXCEPTION 'is_staff can only change via staff role assignment';
  END IF;

  NEW.updated_at := now();
  RETURN NEW;
END;
$$;


--
-- Name: pull_pos_offline_snapshot(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pull_pos_offline_snapshot(p_warehouse_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_list UUID;
  v_currency public.currency_code;
  v_items JSONB;
BEGIN
  PERFORM public._require_payments_staff();

  IF p_warehouse_id IS NULL THEN
    RAISE EXCEPTION 'warehouse_id required';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.warehouses w
    WHERE w.id = p_warehouse_id AND w.is_active AND NOT w.is_quarantine
  ) THEN
    RAISE EXCEPTION 'warehouse not found or not saleable';
  END IF;

  SELECT pl.id, pl.currency INTO v_list, v_currency
  FROM public.price_lists pl
  WHERE pl.is_default AND pl.is_active
  LIMIT 1;

  IF v_list IS NULL THEN
    SELECT pl.id, pl.currency INTO v_list, v_currency
    FROM public.price_lists pl
    WHERE pl.code = 'RETAIL' AND pl.is_active
    LIMIT 1;
  END IF;

  IF v_list IS NULL THEN
    RAISE EXCEPTION 'no active default/RETAIL price list';
  END IF;

  SELECT COALESCE(jsonb_agg(row_to_json(x)::jsonb ORDER BY x.oem_part_number), '[]'::jsonb)
  INTO v_items
  FROM (
    SELECT
      si.id AS stock_item_id,
      si.oem_part_number,
      si.description,
      si.base_uom_id AS uom_id,
      COALESCE(pli.unit_price, 0)::numeric AS unit_price,
      COALESCE(pli.core_charge, 0)::numeric AS core_charge,
      COALESCE(sl.quantity, 0)::numeric AS saleable_qty,
      COALESCE(sl.currency, v_currency) AS currency
    FROM public.stock_items si
    JOIN public.price_list_items pli
      ON pli.stock_item_id = si.id AND pli.price_list_id = v_list
    LEFT JOIN public.stock_levels sl
      ON sl.stock_item_id = si.id AND sl.warehouse_id = p_warehouse_id
    WHERE si.base_uom_id IS NOT NULL
      AND pli.unit_price >= 0
  ) x;

  RETURN jsonb_build_object(
    'warehouse_id', p_warehouse_id,
    'pulled_at', now(),
    'price_list_id', v_list,
    'currency', v_currency,
    'items', v_items
  );
END;
$$;


--
-- Name: FUNCTION pull_pos_offline_snapshot(p_warehouse_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.pull_pos_offline_snapshot(p_warehouse_id uuid) IS 'Staff pull of retail catalog + warehouse qty for encrypted tablet offline POS cache.';


--
-- Name: purge_delivery_locations(interval); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purge_delivery_locations(p_older_than interval DEFAULT '90 days'::interval) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_count INT;
BEGIN
  IF NOT (
    auth.role() = 'service_role'
    OR public.has_staff_role(ARRAY['admin']::public.staff_role[])
  ) THEN
    RAISE EXCEPTION 'admin or service_role required to purge delivery locations';
  END IF;

  PERFORM public._logistics_begin_rpc();

  DELETE FROM public.delivery_locations
  WHERE ingested_at < now() - p_older_than;

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


--
-- Name: raise_delivery_panic(uuid, double precision, double precision); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.raise_delivery_panic(p_delivery_job_id uuid DEFAULT NULL::uuid, p_lat double precision DEFAULT NULL::double precision, p_lng double precision DEFAULT NULL::double precision) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_id UUID;
  v_job public.delivery_jobs%ROWTYPE;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'authentication required';
  END IF;

  IF NOT (
    auth.role() = 'service_role'
    OR public.has_staff_role(ARRAY['driver']::public.staff_role[])
  ) THEN
    RAISE EXCEPTION 'driver role required to raise panic';
  END IF;

  IF p_delivery_job_id IS NOT NULL THEN
    SELECT * INTO v_job FROM public.delivery_jobs WHERE id = p_delivery_job_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'delivery job not found';
    END IF;
    IF auth.role() IS DISTINCT FROM 'service_role'
       AND v_job.assignee_user_id IS DISTINCT FROM v_uid THEN
      RAISE EXCEPTION 'panic job must be assigned to caller';
    END IF;
  END IF;

  INSERT INTO public.panic_events (
    driver_user_id, delivery_job_id, lat, lng
  )
  VALUES (
    v_uid, p_delivery_job_id, p_lat, p_lng
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


--
-- Name: receive_customer_return(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.receive_customer_return(p_return_request_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_req public.customer_return_requests%ROWTYPE;
  v_src public.sales_invoices%ROWTYPE;
  v_quar uuid;
  v_cn uuid;
  r record;
  v_source_line public.sales_invoice_lines%ROWTYPE;
  v_prior_returned numeric;
  v_total numeric:=0;
  v_cost_total numeric:=0;
  v_prior_ar_credit numeric:=0;
  v_invoice_open numeric:=0;
  v_ar_credit numeric:=0;
  v_refund_due numeric:=0;
  v_journal uuid;
  v_lines jsonb;
  v_refund uuid;
BEGIN
  IF NOT (auth.role()='service_role' OR public.has_staff_role(ARRAY['admin','warehouse']::public.staff_role[])) THEN
    RAISE EXCEPTION 'warehouse or admin role required to receive returns';
  END IF;
  SELECT * INTO v_req FROM public.customer_return_requests WHERE id=p_return_request_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'return request not found'; END IF;
  IF v_req.status<>'approved' THEN RAISE EXCEPTION 'approved return request required'; END IF;
  IF v_req.credit_note_id IS NOT NULL THEN RETURN v_req.credit_note_id; END IF;

  SELECT * INTO v_src FROM public.sales_invoices WHERE id=v_req.source_invoice_id FOR UPDATE;
  IF NOT FOUND OR v_src.doc_type<>'invoice' OR v_src.status<>'posted' THEN RAISE EXCEPTION 'posted source invoice required'; END IF;
  SELECT id INTO v_quar FROM public.warehouses WHERE is_active AND is_quarantine ORDER BY code LIMIT 1;
  IF v_quar IS NULL THEN RAISE EXCEPTION 'active quarantine warehouse required'; END IF;

  INSERT INTO public.sales_invoices(
    doc_type,status,document_number,customer_id,warehouse_id,currency,exchange_rate_applied,
    return_against_id,customer_phone_e164,customer_email,customer_whatsapp_e164,posted_by,posted_at
  ) VALUES(
    'credit_note','draft',public.next_series_value('CN-'),v_src.customer_id,v_quar,v_src.currency,v_src.exchange_rate_applied,
    v_src.id,v_src.customer_phone_e164,v_src.customer_email,v_src.customer_whatsapp_e164,auth.uid(),now()
  ) RETURNING id INTO v_cn;

  FOR r IN
    SELECT * FROM public.customer_return_request_lines WHERE return_request_id=p_return_request_id ORDER BY created_at,id
  LOOP
    SELECT * INTO v_source_line FROM public.sales_invoice_lines WHERE id=r.source_invoice_line_id FOR UPDATE;
    IF NOT FOUND OR v_source_line.invoice_id<>v_src.id THEN RAISE EXCEPTION 'source invoice line changed'; END IF;
    SELECT COALESCE(sum(sil.qty_base),0) INTO v_prior_returned
    FROM public.sales_invoice_lines sil
    JOIN public.sales_invoices cn ON cn.id=sil.invoice_id
    WHERE sil.return_against_line_id=v_source_line.id AND cn.doc_type='credit_note' AND cn.status='posted';
    IF r.qty_base>GREATEST(v_source_line.qty_fulfilled-v_prior_returned,0)+0.0001 THEN
      RAISE EXCEPTION 'return quantity no longer available for source line %',v_source_line.id;
    END IF;

    INSERT INTO public.sales_invoice_lines(
      invoice_id,stock_item_id,uom_id,qty,qty_base,unit_price,line_total,qty_fulfilled,
      issues_stock,unit_cost_basis,cost_total_basis,return_against_line_id
    ) VALUES(
      v_cn,r.stock_item_id,r.uom_id,r.qty,r.qty_base,r.unit_price_snapshot,r.line_total_snapshot,r.qty_base,
      true,r.unit_cost_basis,r.cost_total_basis,r.source_invoice_line_id
    );

    PERFORM public._adjust_stock_level(r.stock_item_id,v_quar,r.qty_base,'FIFO',r.unit_cost_basis,v_src.currency);
    INSERT INTO public.stock_batches(batch_code,stock_item_id,warehouse_id,valuation_method,unit_cost,currency,qty_on_hand)
    VALUES(public.next_series_value('BATCH-'),r.stock_item_id,v_quar,'FIFO',r.unit_cost_basis,v_src.currency,r.qty_base);
    v_total:=v_total+r.line_total_snapshot;
    v_cost_total:=v_cost_total+r.cost_total_basis;
  END LOOP;

  IF v_total<=0 THEN RAISE EXCEPTION 'return has no credit value'; END IF;
  SELECT COALESCE(sum(rr.ar_credit_amount),0) INTO v_prior_ar_credit
  FROM public.customer_return_requests rr
  WHERE rr.source_invoice_id=v_src.id AND rr.id<>p_return_request_id
    AND rr.status IN ('received','refund_pending','completed');
  v_invoice_open:=GREATEST(v_src.total-COALESCE(v_src.amount_paid,0)-v_prior_ar_credit,0);
  v_ar_credit:=LEAST(v_total,v_invoice_open);
  v_refund_due:=GREATEST(v_total-v_ar_credit,0);

  v_lines:=jsonb_build_array(jsonb_build_object('account_code','4110','debit',round(v_total,2),'credit',0,'currency',v_src.currency));
  IF v_ar_credit>0 THEN
    v_lines:=v_lines||jsonb_build_array(jsonb_build_object('account_code','1200','debit',0,'credit',round(v_ar_credit,2),'currency',v_src.currency));
  END IF;
  IF v_refund_due>0 THEN
    v_lines:=v_lines||jsonb_build_array(jsonb_build_object('account_code','2220','debit',0,'credit',round(v_refund_due,2),'currency',v_src.currency));
  END IF;
  IF v_cost_total>0 THEN
    v_lines:=v_lines||jsonb_build_array(
      jsonb_build_object('account_code','1310','debit',round(v_cost_total,2),'credit',0,'currency',v_src.currency),
      jsonb_build_object('account_code','5100','debit',0,'credit',round(v_cost_total,2),'currency',v_src.currency)
    );
  END IF;

  v_journal:=public.post_journal_entry(CURRENT_DATE,format('Return CN against %s',COALESCE(v_src.document_number,v_src.id::text)),v_src.currency,v_src.exchange_rate_applied,v_lines);
  UPDATE public.sales_invoices SET status='posted',subtotal=round(v_total,2),total=round(v_total,2),journal_entry_id=v_journal,posted_at=now() WHERE id=v_cn;
  IF v_src.customer_id IS NOT NULL AND v_ar_credit>0 THEN
    UPDATE public.customers SET open_balance=GREATEST(0,open_balance-v_ar_credit),updated_at=now() WHERE id=v_src.customer_id;
  END IF;

  IF v_refund_due>0 THEN
    INSERT INTO public.return_refund_requests(return_request_id,credit_note_id,customer_id,source_invoice_id,amount,currency,method)
    VALUES(p_return_request_id,v_cn,v_req.customer_id,v_src.id,round(v_refund_due,2),v_src.currency,v_req.preferred_resolution)
    RETURNING id INTO v_refund;
  END IF;

  UPDATE public.customer_return_requests
  SET status=CASE WHEN v_refund_due>0 THEN 'refund_pending'::public.customer_return_status ELSE 'completed'::public.customer_return_status END,
      credit_note_id=v_cn,ar_credit_amount=round(v_ar_credit,2),refund_due_amount=round(v_refund_due,2),
      received_by=auth.uid(),received_at=now(),updated_at=now()
  WHERE id=p_return_request_id;

  PERFORM public.emit_domain_event('return_received','return:received:'||p_return_request_id::text,
    jsonb_build_object('return_request_id',p_return_request_id,'credit_note_id',v_cn,'ar_credit',v_ar_credit,'refund_due',v_refund_due),auth.uid(),NULL);
  IF v_refund_due>0 THEN
    PERFORM public.emit_domain_event('refund_pending','return:refund:'||p_return_request_id::text,
      jsonb_build_object('return_request_id',p_return_request_id,'refund_request_id',v_refund,'amount',v_refund_due,'currency',v_src.currency),auth.uid(),NULL);
  END IF;
  PERFORM public.enqueue_customer_receipts(v_cn);
  RETURN v_cn;
END;
$$;


--
-- Name: receive_driver_cash_handin(uuid, numeric, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.receive_driver_cash_handin(p_handin_id uuid, p_counted_amount numeric, p_reason_code text DEFAULT NULL::text, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE h public.driver_cash_handins%ROWTYPE; v_var numeric;
BEGIN
 IF NOT (public.has_staff_role(ARRAY['admin','finance','sales','dispatcher']::public.staff_role[]) OR public.is_pos_approver()) THEN
  RAISE EXCEPTION 'cashier, finance or dispatcher required to receive driver cash'; END IF;
 IF COALESCE(p_counted_amount,-1) < 0 THEN RAISE EXCEPTION 'counted amount must be >= 0'; END IF;
 SELECT * INTO h FROM public.driver_cash_handins WHERE id=p_handin_id FOR UPDATE;
 IF NOT FOUND OR h.status<>'submitted' THEN RAISE EXCEPTION 'hand-in waiting to be received required'; END IF;
 IF h.driver_user_id=auth.uid() THEN RAISE EXCEPTION 'someone else must receive your cash'; END IF;
 v_var := round(p_counted_amount - h.expected_amount, 2);
 IF abs(v_var) > 0.009 AND trim(COALESCE(p_reason_code,''))='' THEN RAISE EXCEPTION 'reason required for a cash difference'; END IF;
 IF abs(v_var) > 0.009 AND NOT EXISTS(SELECT 1 FROM public.pos_approval_reason_codes WHERE action='driver_cash_variance' AND code=p_reason_code AND is_active) THEN
  RAISE EXCEPTION 'unknown reason %', p_reason_code; END IF;
 UPDATE public.driver_cash_handins SET received_amount=round(p_counted_amount,2), variance=v_var,
  status=CASE WHEN abs(v_var) > 0.009 THEN 'variance_pending' ELSE 'received' END,
  reason_code=NULLIF(trim(COALESCE(p_reason_code,'')),''), receiver_notes=NULLIF(trim(COALESCE(p_notes,'')),''),
  received_by=auth.uid(), received_at=now()
 WHERE id=h.id RETURNING * INTO h;
 RETURN private._driver_cash_handin_json(h);
END $$;


--
-- Name: record_driver_cash_recovery(uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_driver_cash_recovery(p_handin_id uuid, p_amount numeric, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE h public.driver_cash_handins%ROWTYPE; v_j uuid; v_out numeric;
BEGIN
 IF NOT (public.has_staff_role(ARRAY['admin','finance','sales']::public.staff_role[]) OR public.is_pos_approver()) THEN
  RAISE EXCEPTION 'cashier, finance or manager required to take a repayment'; END IF;
 SELECT * INTO h FROM public.driver_cash_handins WHERE id=p_handin_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'hand-in not found'; END IF;
 IF h.driver_user_id=auth.uid() THEN RAISE EXCEPTION 'someone else must take your repayment'; END IF;
 v_out := h.owed_amount - h.recovered_amount - h.written_off_amount;
 IF v_out <= 0 THEN RAISE EXCEPTION 'nothing is owed on %', h.document_number; END IF;
 IF COALESCE(p_amount,0) <= 0 OR round(p_amount,2) > v_out THEN RAISE EXCEPTION 'amount must be between 0.01 and % %', h.currency, v_out; END IF;
 v_j := private._driver_cash_journal(h, '1120', '1250', p_amount, 'repaid by the driver');
 INSERT INTO public.driver_cash_recoveries(handin_id, kind, amount, currency, journal_entry_id, notes, recorded_by)
 VALUES (h.id, 'cash', round(p_amount,2), h.currency, v_j, NULLIF(trim(COALESCE(p_notes,'')),''), auth.uid());
 UPDATE public.driver_cash_handins SET recovered_amount = recovered_amount + round(p_amount,2) WHERE id=h.id RETURNING * INTO h;
 RETURN private._driver_cash_handin_json(h);
END $$;


--
-- Name: record_lost_demand(uuid, uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_lost_demand(p_stock_item_id uuid, p_warehouse_id uuid, p_qty numeric, p_note text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_id uuid;
BEGIN
 IF NOT (public.has_staff_role(ARRAY['admin','sales','warehouse']::public.staff_role[]) OR public.is_pos_approver()) THEN
  RAISE EXCEPTION 'counter staff required';
 END IF;
 IF COALESCE(p_qty,0) <= 0 OR p_qty > 1000 THEN RAISE EXCEPTION 'quantity must be between 1 and 1000'; END IF;
 IF NOT EXISTS (SELECT 1 FROM public.warehouses w WHERE w.id=p_warehouse_id AND w.is_active) THEN RAISE EXCEPTION 'branch not found'; END IF;
 INSERT INTO public.lost_demand(stock_item_id, warehouse_id, qty, note, created_by)
 VALUES (p_stock_item_id, p_warehouse_id, p_qty, NULLIF(trim(COALESCE(p_note,'')),''), auth.uid()) RETURNING id INTO v_id;
 RETURN v_id;
END $$;


--
-- Name: record_pos_card_terminal_result(uuid, uuid, text, text, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_pos_card_terminal_result(p_actor_user_id uuid, p_attempt_id uuid, p_outcome text, p_terminal_transaction_id text DEFAULT NULL::text, p_rrn text DEFAULT NULL::text, p_authorization_code text DEFAULT NULL::text, p_card_last4 text DEFAULT NULL::text, p_card_scheme text DEFAULT NULL::text, p_response_code text DEFAULT NULL::text, p_response_message text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE a public.pos_card_terminal_attempts%ROWTYPE;v_status public.pos_card_terminal_attempt_status;parent public.pos_card_terminal_attempts%ROWTYPE;v_actor_ok BOOLEAN:=false;
BEGIN
 IF auth.role()<>'service_role' THEN PERFORM public._require_payments_staff(); END IF;
 SELECT * INTO a FROM public.pos_card_terminal_attempts WHERE id=p_attempt_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'card terminal attempt not found'; END IF;
 v_actor_ok:=EXISTS(SELECT 1 FROM public.staff_roles sr WHERE sr.user_id=p_actor_user_id AND sr.role IN('admin','finance','sales'));
 IF a.delivery_job_id IS NOT NULL THEN v_actor_ok:=v_actor_ok OR (a.created_by=p_actor_user_id AND EXISTS(SELECT 1 FROM public.staff_roles sr WHERE sr.user_id=p_actor_user_id AND sr.role='driver')); END IF;
 IF NOT v_actor_ok THEN RAISE EXCEPTION 'active authorized terminal actor required'; END IF;
 IF a.created_by<>p_actor_user_id AND NOT EXISTS(SELECT 1 FROM public.staff_roles sr WHERE sr.user_id=p_actor_user_id AND sr.role IN('admin','finance')) THEN RAISE EXCEPTION 'card terminal attempt access denied'; END IF;
 IF p_outcome NOT IN('approved','declined','cancelled','unknown','failed') THEN RAISE EXCEPTION 'unsupported terminal outcome'; END IF; v_status:=p_outcome::public.pos_card_terminal_attempt_status;
 IF a.status IN('settled','reversed') THEN RETURN private.pos_card_terminal_attempt_payload(a.id); END IF;
 IF a.status='approved' AND v_status<>'approved' THEN RAISE EXCEPTION 'approved terminal result cannot be downgraded; reverse or finalize it'; END IF;
 IF a.status NOT IN('initiated','unknown','approved') THEN IF a.status=v_status THEN RETURN private.pos_card_terminal_attempt_payload(a.id); END IF; RAISE EXCEPTION 'terminal result cannot transition from % to %',a.status,v_status; END IF;
 IF p_card_last4 IS NOT NULL AND p_card_last4!~'^[0-9]{4}$' THEN RAISE EXCEPTION 'card_last4 must contain exactly four digits'; END IF;
 IF length(COALESCE(p_terminal_transaction_id,''))>96 OR length(COALESCE(p_rrn,''))>64 OR length(COALESCE(p_authorization_code,''))>32 OR length(COALESCE(p_card_scheme,''))>32 OR length(COALESCE(p_response_code,''))>32 OR length(COALESCE(p_response_message,''))>240 THEN RAISE EXCEPTION 'terminal result field exceeds safe length'; END IF;
 IF v_status='approved' AND (trim(COALESCE(p_terminal_transaction_id,''))='' OR (trim(COALESCE(p_rrn,''))='' AND trim(COALESCE(p_authorization_code,''))='')) THEN RAISE EXCEPTION 'approved result requires terminal transaction id plus RRN or authorization code'; END IF;
 UPDATE public.pos_card_terminal_attempts SET status=v_status,terminal_transaction_id=COALESCE(NULLIF(trim(COALESCE(p_terminal_transaction_id,'')),''),terminal_transaction_id),
  rrn=COALESCE(NULLIF(trim(COALESCE(p_rrn,'')),''),rrn),authorization_code=COALESCE(NULLIF(trim(COALESCE(p_authorization_code,'')),''),authorization_code),
  card_last4=COALESCE(NULLIF(trim(COALESCE(p_card_last4,'')),''),card_last4),card_scheme=COALESCE(NULLIF(trim(COALESCE(p_card_scheme,'')),''),card_scheme),
  response_code=COALESCE(NULLIF(trim(COALESCE(p_response_code,'')),''),response_code),response_message=COALESCE(NULLIF(trim(COALESCE(p_response_message,'')),''),response_message),
  result_recorded_by=p_actor_user_id,result_recorded_at=now(),approved_at=CASE WHEN v_status='approved' THEN COALESCE(approved_at,now()) ELSE approved_at END,updated_at=now() WHERE id=a.id RETURNING * INTO a;
 IF a.delivery_job_id IS NULL THEN
  IF a.operation='purchase' THEN
   IF v_status='unknown' THEN UPDATE public.commerce_orders SET state='payment_processing',active_payment_provider='card_terminal',active_payment_intent_id=a.id,payment_exception='CARD_TERMINAL_OUTCOME_UNKNOWN',updated_at=now() WHERE id=a.commerce_order_id;
   ELSIF v_status='approved' THEN UPDATE public.commerce_orders SET state='payment_processing',active_payment_provider='card_terminal',active_payment_intent_id=a.id,payment_exception=NULL,updated_at=now() WHERE id=a.commerce_order_id;
   ELSE UPDATE public.commerce_orders SET state='payment_failed',active_payment_provider=NULL,active_payment_intent_id=NULL,payment_exception=NULL,updated_at=now() WHERE id=a.commerce_order_id AND settled_payment_entry_id IS NULL; END IF;
  ELSIF a.operation='reversal' THEN
   SELECT * INTO parent FROM public.pos_card_terminal_attempts WHERE id=a.parent_attempt_id FOR UPDATE;
   IF v_status='approved' THEN UPDATE public.pos_card_terminal_attempts SET status='reversed',finalized_by=p_actor_user_id,finalized_at=now(),updated_at=now() WHERE id=parent.id; UPDATE public.pos_card_terminal_attempts SET status='settled',finalized_by=p_actor_user_id,finalized_at=now(),updated_at=now() WHERE id=a.id;
   ELSIF v_status='unknown' THEN UPDATE public.commerce_orders SET state='payment_processing',active_payment_provider='card_terminal',active_payment_intent_id=a.id,payment_exception='CARD_TERMINAL_REVERSAL_UNKNOWN',updated_at=now() WHERE id=parent.commerce_order_id;
   END IF;
  END IF;
 END IF;
 RETURN private.pos_card_terminal_attempt_payload(a.id);
EXCEPTION WHEN unique_violation THEN RAISE EXCEPTION 'terminal transaction id was already recorded; reconcile existing attempt instead of charging again';
END $_$;


--
-- Name: record_pos_till_cash_movement(uuid, public.pos_till_cash_movement_kind, numeric, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_pos_till_cash_movement(p_session_id uuid, p_kind public.pos_till_cash_movement_kind, p_amount numeric, p_reason_code text, p_notes text DEFAULT NULL::text, p_finance_refund_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE s public.pos_till_sessions%ROWTYPE; v_id UUID;
BEGIN
 PERFORM public._require_sales_staff(); SELECT * INTO s FROM public.pos_till_sessions WHERE id=p_session_id FOR UPDATE;
 IF NOT FOUND OR s.status<>'open' THEN RAISE EXCEPTION 'open till session required'; END IF;
 IF s.operator_user_id<>auth.uid() AND NOT public.is_pos_approver() THEN RAISE EXCEPTION 'current operator or manager required'; END IF;
 IF p_kind IN('cash_out','petty_cash','bank_drop','cash_refund') AND NOT public.is_pos_approver() THEN RAISE EXCEPTION 'manager approval required for cash-out movement'; END IF;
 IF COALESCE(p_amount,0)<=0 THEN RAISE EXCEPTION 'amount must be > 0'; END IF;
 IF trim(COALESCE(p_reason_code,''))='' THEN RAISE EXCEPTION 'reason_code required'; END IF;
 INSERT INTO public.pos_till_cash_movements(session_id,kind,amount,reason_code,notes,finance_refund_id,actor_user_id)
 VALUES(p_session_id,p_kind,round(p_amount,2),trim(p_reason_code),p_notes,p_finance_refund_id,auth.uid()) RETURNING id INTO v_id;
 INSERT INTO public.pos_till_session_events(session_id,event_type,actor_user_id,detail)
 VALUES(p_session_id,'cash_movement',auth.uid(),jsonb_build_object('movement_id',v_id,'kind',p_kind,'amount',round(p_amount,2),'reason_code',p_reason_code));
 RETURN v_id;
END $$;


--
-- Name: record_staff_login_attempt(text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_staff_login_attempt(p_identifier text, p_success boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_raw text;
  v_hash text;
  v_uid uuid := auth.uid();
  v_role text := auth.role();
  v_matches_self boolean := false;
BEGIN
  v_raw := lower(trim(COALESCE(p_identifier, '')));
  IF v_raw = '' THEN
    RETURN;
  END IF;

  IF v_role IS DISTINCT FROM 'service_role' THEN
    IF v_uid IS NULL THEN
      RAISE EXCEPTION 'authenticated session required for login audit';
    END IF;
    IF COALESCE(p_success, false) IS NOT TRUE THEN
      RAISE EXCEPTION 'failed login attempts must be recorded by the trusted auth service';
    END IF;

    SELECT EXISTS (
      SELECT 1
      FROM public.employees e
      LEFT JOIN auth.users u ON u.id = e.user_id
      WHERE e.user_id = v_uid
        AND e.status = 'active'
        AND (
          (
            position('@' IN v_raw) > 0
            AND (
              lower(COALESCE(e.email, '')) = v_raw
              OR lower(COALESCE(u.email, '')) = v_raw
            )
          )
          OR (
            v_raw ~ '^\+?[0-9]{7,15}$'
            AND regexp_replace(COALESCE(e.phone_e164, ''), '[^0-9+]', '', 'g')
                = regexp_replace(v_raw, '[^0-9+]', '', 'g')
          )
          OR (
            position('@' IN v_raw) = 0
            AND v_raw !~ '^\+?[0-9]{7,15}$'
            AND lower(COALESCE(e.employee_code, '')) = v_raw
          )
        )
    ) INTO v_matches_self;

    IF NOT v_matches_self THEN
      RAISE EXCEPTION 'login audit identifier does not belong to current staff user';
    END IF;
  END IF;

  v_hash := encode(extensions.digest(convert_to(v_raw, 'UTF8'), 'sha256'), 'hex');

  INSERT INTO public.staff_login_failures (identifier_hash, success)
  VALUES (v_hash, COALESCE(p_success, false));

  IF p_success THEN
    DELETE FROM public.staff_login_failures
    WHERE identifier_hash = v_hash
      AND success = false
      AND attempted_at > now() - interval '15 minutes';
  END IF;
END;
$_$;


--
-- Name: FUNCTION record_staff_login_attempt(p_identifier text, p_success boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.record_staff_login_attempt(p_identifier text, p_success boolean) IS 'Trusted login-audit mutation. service_role may record outcomes; authenticated staff may record only their own successful login. Anonymous clients cannot mutate lockout state.';


--
-- Name: redeem_loyalty_points(uuid, numeric, public.currency_code, numeric, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.redeem_loyalty_points(p_customer_id uuid, p_points numeric, p_currency public.currency_code DEFAULT 'USD'::public.currency_code, p_exchange_rate numeric DEFAULT 1, p_sales_invoice_id uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_settings public.loyalty_program_settings%ROWTYPE;
  v_money NUMERIC;
  v_rate NUMERIC;
  v_journal UUID;
  v_ledger UUID;
  v_inv public.sales_invoices%ROWTYPE;
  v_open NUMERIC;
BEGIN
  PERFORM public._require_loyalty_staff();
  PERFORM public._loyalty_rpc_enter();

  SELECT * INTO v_settings FROM public.loyalty_program_settings WHERE id = 1;
  IF NOT FOUND OR NOT v_settings.is_active THEN
    RAISE EXCEPTION 'loyalty program inactive or missing';
  END IF;

  IF p_customer_id IS NULL THEN
    RAISE EXCEPTION 'customer_id required';
  END IF;
  IF p_points IS NULL OR p_points <= 0 THEN
    RAISE EXCEPTION 'redeem points must be > 0';
  END IF;
  IF p_sales_invoice_id IS NULL THEN
    RAISE EXCEPTION 'sales_invoice_id required to redeem loyalty against AR';
  END IF;
  IF p_currency = 'ZIG' AND (p_exchange_rate IS NULL OR p_exchange_rate <= 0) THEN
    RAISE EXCEPTION 'exchange_rate_applied required for ZIG';
  END IF;

  SELECT * INTO v_inv
  FROM public.sales_invoices
  WHERE id = p_sales_invoice_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'sales invoice not found';
  END IF;
  IF v_inv.status <> 'posted' OR v_inv.doc_type <> 'invoice' THEN
    RAISE EXCEPTION 'only posted sales invoices can receive loyalty redemption';
  END IF;
  IF v_inv.customer_id IS DISTINCT FROM p_customer_id THEN
    RAISE EXCEPTION 'invoice customer mismatch';
  END IF;
  IF v_inv.currency <> p_currency THEN
    RAISE EXCEPTION 'loyalty redeem currency must match invoice (%)', v_inv.currency;
  END IF;

  v_rate := CASE
    WHEN p_currency = 'USD' THEN COALESCE(p_exchange_rate, 1)
    ELSE p_exchange_rate
  END;
  v_money := public._loyalty_money_value(p_points);

  v_open := v_inv.total - v_inv.amount_paid;
  IF v_money > v_open + 0.001 THEN
    RAISE EXCEPTION 'loyalty money_value % exceeds invoice open %', v_money, v_open;
  END IF;

  -- Liability draw-down against AR
  v_journal := public.post_journal_entry(
    CURRENT_DATE,
    COALESCE(p_reason, format('Loyalty redeem %s pts', p_points)),
    p_currency,
    v_rate,
    jsonb_build_array(
      jsonb_build_object(
        'account_code', '2210',
        'debit', v_money, 'credit', 0, 'currency', p_currency
      ),
      jsonb_build_object(
        'account_code', '1200',
        'debit', 0, 'credit', v_money, 'currency', p_currency
      )
    )
  );

  v_ledger := public._append_loyalty(
    p_customer_id, 'redeem', p_points, p_currency, v_rate, v_money,
    p_sales_invoice_id, v_journal,
    COALESCE(p_reason, format('Loyalty redeem %s pts', p_points))
  );

  UPDATE public.sales_invoices
  SET amount_paid = amount_paid + v_money
  WHERE id = v_inv.id;

  UPDATE public.customers
  SET
    open_balance = GREATEST(0, open_balance - v_money),
    updated_at = now()
  WHERE id = p_customer_id;

  RETURN v_ledger;
END;
$$;


--
-- Name: redeem_store_credit(uuid, numeric, public.currency_code, numeric, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.redeem_store_credit(p_customer_id uuid, p_amount numeric, p_currency public.currency_code DEFAULT 'USD'::public.currency_code, p_exchange_rate numeric DEFAULT 1, p_sales_invoice_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_pe UUID;
  v_alloc JSONB;
BEGIN
  -- Convenience: create + allocate + post a store_credit payment entry
  v_pe := public.create_payment_entry(
    p_customer_id, 'store_credit', p_amount, p_currency, p_exchange_rate, p_notes
  );

  IF p_sales_invoice_id IS NOT NULL THEN
    v_alloc := jsonb_build_array(
      jsonb_build_object('sales_invoice_id', p_sales_invoice_id, 'amount', p_amount)
    );
    PERFORM public.allocate_payment(v_pe, v_alloc);
  ELSE
    RAISE EXCEPTION 'sales_invoice_id required to redeem store credit against AR';
  END IF;

  RETURN public.post_payment_entry(v_pe);
END;
$$;


--
-- Name: refund_pos_fulfillment_deposit(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refund_pos_fulfillment_deposit(p_deposit_id uuid, p_till_session_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE d public.pos_fulfillment_deposits%ROWTYPE; r public.pos_fulfillment_requests%ROWTYPE; s public.pos_till_sessions%ROWTYPE; v_j uuid;
BEGIN
 IF NOT public.is_pos_approver() THEN RAISE EXCEPTION 'POS manager approval required'; END IF;
 SELECT * INTO d FROM public.pos_fulfillment_deposits WHERE id=p_deposit_id FOR UPDATE;
 IF NOT FOUND OR d.status<>'held' THEN RAISE EXCEPTION 'deposit held for the customer required'; END IF;
 SELECT * INTO r FROM public.pos_fulfillment_requests WHERE id=d.request_id;
 IF r.status::text NOT IN ('cancelled','rejected') THEN RAISE EXCEPTION 'cancel % before refunding its deposit', r.document_number; END IF;
 IF trim(COALESCE(p_notes,''))='' THEN RAISE EXCEPTION 'say why the deposit is refunded'; END IF;
 IF d.tender='cash' THEN
  SELECT * INTO s FROM public.pos_till_sessions WHERE id=p_till_session_id FOR UPDATE;
  IF NOT FOUND OR s.status<>'open' THEN RAISE EXCEPTION 'open till required to pay a cash refund'; END IF;
  IF s.currency<>d.currency THEN RAISE EXCEPTION 'this till counts % cash', s.currency; END IF;
 END IF;
 -- Refused (store credit overdraw) when the customer has already spent the deposit.
 BEGIN
  PERFORM public._payments_rpc_enter();
  PERFORM public._append_store_credit(d.customer_id, 'reverse', d.amount, d.currency, d.exchange_rate_applied, NULL, NULL,
    format('Refund of deposit %s', d.document_number), d.store_credit_ledger_id);
 EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'the customer has already used this deposit as store credit (%)', SQLERRM;
 END;
 PERFORM public._sales_checkout_accounting_enter();
 v_j := public.post_journal_entry(CURRENT_DATE, format('Refund of deposit %s on %s', d.document_number, r.document_number), d.currency, d.exchange_rate_applied,
   jsonb_build_array(
     jsonb_build_object('account_code', '2200', 'debit', d.amount, 'credit', 0),
     jsonb_build_object('account_code', public.gl_account_for_payment_tender(d.tender), 'debit', 0, 'credit', d.amount)));
 PERFORM public._sales_checkout_accounting_exit();
 IF d.tender='cash' THEN
  INSERT INTO public.pos_till_cash_movements(session_id,kind,amount,reason_code,notes,actor_user_id)
  VALUES (s.id,'cash_refund',d.amount,'customer_refund',format('Refund of deposit %s: %s', d.document_number, trim(p_notes)),auth.uid());
  INSERT INTO public.pos_till_session_events(session_id,event_type,actor_user_id,detail)
  VALUES (s.id,'cash_movement',auth.uid(),jsonb_build_object('kind','cash_refund','amount',d.amount,'reason_code','customer_refund','deposit',d.document_number));
 END IF;
 UPDATE public.pos_fulfillment_deposits SET status='refunded', refund_journal_entry_id=v_j, refund_till_session_id=CASE WHEN d.tender='cash' THEN s.id END,
  refund_notes=trim(p_notes), refunded_by=auth.uid(), refunded_at=now() WHERE id=d.id RETURNING * INTO d;
 RETURN private._pos_deposit_json(d);
EXCEPTION WHEN OTHERS THEN PERFORM public._sales_checkout_accounting_exit(); RAISE;
END $$;


--
-- Name: register_delivery_card_terminal_device_key(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.register_delivery_card_terminal_device_key(p_terminal_id uuid, p_device_id text, p_public_key_spki_base64 text, p_key_sha256 text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
 v_id UUID;
 v_bytes BYTEA;
 v_terminal public.pos_card_terminals%ROWTYPE;
BEGIN
 IF NOT public.has_staff_role(ARRAY['driver']::public.staff_role[]) THEN
  RAISE EXCEPTION 'driver role required';
 END IF;
 IF trim(COALESCE(p_device_id,''))='' OR trim(COALESCE(p_public_key_spki_base64,''))='' OR COALESCE(p_key_sha256,'')!~'^[0-9a-f]{64}$' THEN
  RAISE EXCEPTION 'device id, public key and sha256 required';
 END IF;
 SELECT * INTO v_terminal FROM public.pos_card_terminals WHERE id=p_terminal_id AND is_active FOR UPDATE;
 IF NOT FOUND OR NOT v_terminal.allow_delivery THEN
  RAISE EXCEPTION 'active delivery-enabled terminal required';
 END IF;
 IF v_terminal.device_id IS NULL OR v_terminal.device_id<>trim(p_device_id) THEN
  RAISE EXCEPTION 'terminal must be admin-assigned to this delivery device before pairing';
 END IF;
 BEGIN
  v_bytes:=decode(p_public_key_spki_base64,'base64');
 EXCEPTION WHEN OTHERS THEN
  RAISE EXCEPTION 'public key must be base64 SPKI';
 END;
 IF octet_length(v_bytes)<200 OR octet_length(v_bytes)>1024 THEN
  RAISE EXCEPTION 'unexpected public key size';
 END IF;
 IF encode(extensions.digest(v_bytes,'sha256'),'hex')<>lower(p_key_sha256) THEN
  RAISE EXCEPTION 'public key sha256 mismatch';
 END IF;

 UPDATE public.pos_card_terminal_device_keys
 SET is_active=false,revoked_at=now()
 WHERE terminal_id=p_terminal_id AND device_id=trim(p_device_id)
   AND is_active AND revoked_at IS NULL;
 INSERT INTO public.pos_card_terminal_device_keys(
  terminal_id,device_id,public_key_spki_base64,key_sha256,is_active,created_by,revoked_at
 ) VALUES(
  p_terminal_id,trim(p_device_id),trim(p_public_key_spki_base64),lower(p_key_sha256),true,auth.uid(),NULL
 )
 ON CONFLICT(terminal_id,device_id,key_sha256) DO UPDATE SET
  public_key_spki_base64=EXCLUDED.public_key_spki_base64,
  is_active=true,revoked_at=NULL,created_by=auth.uid()
 RETURNING id INTO v_id;
 RETURN v_id;
END $_$;


--
-- Name: register_my_manager_signature(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.register_my_manager_signature(p_storage_path text, p_mime_type text, p_sha256 text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE e public.employees%ROWTYPE; v_path TEXT;
BEGIN
 IF NOT (public.is_pos_approver() OR public.has_staff_role(ARRAY['admin','finance']::public.staff_role[])) THEN RAISE EXCEPTION 'manager/finance/admin role required'; END IF;
 SELECT * INTO e FROM public.employees WHERE user_id=auth.uid() AND status='active' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'active employee profile required'; END IF;
 v_path:=trim(COALESCE(p_storage_path,''));
 IF v_path='' OR split_part(v_path,'/',1)<>auth.uid()::text THEN RAISE EXCEPTION 'signature path must be owned by current manager'; END IF;
 IF p_mime_type NOT IN('image/png','image/jpeg') OR COALESCE(p_sha256,'')!~'^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'valid PNG/JPEG signature and sha256 required'; END IF;
 IF NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='staff-signatures' AND name=v_path) THEN RAISE EXCEPTION 'uploaded signature object not found'; END IF;
 UPDATE public.employees SET signature_storage_bucket='staff-signatures',signature_storage_path=v_path,signature_mime_type=p_mime_type,
  signature_sha256=lower(p_sha256),signature_captured_at=now(),signature_updated_by=auth.uid(),updated_at=now() WHERE id=e.id;
 RETURN public.get_my_manager_signature();
END $_$;


--
-- Name: register_pos_card_terminal_device_key(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.register_pos_card_terminal_device_key(p_terminal_id uuid, p_device_id text, p_public_key_spki_base64 text, p_key_sha256 text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE v_id UUID; v_bytes BYTEA;
BEGIN
 IF NOT public.has_staff_role(ARRAY['admin']::public.staff_role[]) THEN RAISE EXCEPTION 'admin role required'; END IF;
 IF trim(COALESCE(p_device_id,''))='' OR trim(COALESCE(p_public_key_spki_base64,''))='' OR COALESCE(p_key_sha256,'')!~'^[0-9a-f]{64}$' THEN
  RAISE EXCEPTION 'device id, public key and sha256 required';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM public.pos_card_terminals WHERE id=p_terminal_id AND is_active) THEN RAISE EXCEPTION 'active terminal required'; END IF;
 BEGIN v_bytes:=decode(p_public_key_spki_base64,'base64'); EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'public key must be base64 SPKI'; END;
 IF octet_length(v_bytes)<200 OR octet_length(v_bytes)>1024 THEN RAISE EXCEPTION 'unexpected public key size'; END IF;
 IF encode(extensions.digest(v_bytes,'sha256'),'hex')<>lower(p_key_sha256) THEN RAISE EXCEPTION 'public key sha256 mismatch'; END IF;
 UPDATE public.pos_card_terminal_device_keys SET is_active=false,revoked_at=now()
 WHERE terminal_id=p_terminal_id AND device_id=trim(p_device_id) AND is_active AND revoked_at IS NULL;
 INSERT INTO public.pos_card_terminal_device_keys(terminal_id,device_id,public_key_spki_base64,key_sha256,is_active,created_by,revoked_at)
 VALUES(p_terminal_id,trim(p_device_id),trim(p_public_key_spki_base64),lower(p_key_sha256),true,auth.uid(),NULL)
 ON CONFLICT(terminal_id,device_id,key_sha256) DO UPDATE SET
  public_key_spki_base64=EXCLUDED.public_key_spki_base64,is_active=true,revoked_at=NULL,created_by=auth.uid()
 RETURNING id INTO v_id;
 RETURN v_id;
END $_$;


--
-- Name: register_stock_item_image(uuid, text, boolean, smallint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.register_stock_item_image(p_stock_item_id uuid, p_storage_path text, p_is_primary boolean DEFAULT false, p_sort_order smallint DEFAULT 0) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_id UUID; v_path TEXT:=trim(COALESCE(p_storage_path,'')); v_primary BOOLEAN:=COALESCE(p_is_primary,false);
BEGIN
 IF NOT public.has_staff_role(ARRAY['admin','sales','warehouse']::public.staff_role[]) THEN RAISE EXCEPTION 'staff role required'; END IF;
 IF p_stock_item_id IS NULL OR v_path='' THEN RAISE EXCEPTION 'stock_item_id and storage_path required'; END IF;
 IF public._stock_item_id_from_product_image_path(v_path) IS DISTINCT FROM p_stock_item_id THEN RAISE EXCEPTION 'storage_path must start with {stock_item_id}/'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.stock_items WHERE id=p_stock_item_id) THEN RAISE EXCEPTION 'unknown stock_item_id'; END IF;
 IF v_primary THEN UPDATE public.stock_item_images SET is_primary=false WHERE stock_item_id=p_stock_item_id AND is_primary; ELSIF NOT EXISTS(SELECT 1 FROM public.stock_item_images WHERE stock_item_id=p_stock_item_id) THEN v_primary:=true; END IF;
 INSERT INTO public.stock_item_images(stock_item_id,storage_path,is_primary,sort_order,created_by) VALUES(p_stock_item_id,v_path,v_primary,COALESCE(p_sort_order,0),auth.uid()) ON CONFLICT(stock_item_id,storage_path) DO UPDATE SET is_primary=EXCLUDED.is_primary,sort_order=EXCLUDED.sort_order RETURNING id INTO v_id;
 RETURN v_id;
END;$$;


--
-- Name: reject_finance_requisition(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_finance_requisition(p_requisition_id uuid, p_reason text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_status public.finance_requisition_status;
BEGIN
  IF NOT (
    auth.role() = 'service_role'
    OR public.has_staff_role(ARRAY['admin', 'finance']::public.staff_role[])
  ) THEN
    RAISE EXCEPTION 'finance or admin role required to reject';
  END IF;

  SELECT status INTO v_status
  FROM public.finance_requisitions
  WHERE id = p_requisition_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'requisition not found: %', p_requisition_id;
  END IF;
  IF v_status NOT IN ('submitted', 'approved') THEN
    RAISE EXCEPTION 'only submitted/approved requisitions can be rejected (status=%)', v_status;
  END IF;

  PERFORM public._finance_req_rpc_enter();

  UPDATE public.finance_requisitions
  SET
    status = 'rejected',
    rejected_by = auth.uid(),
    rejected_at = now(),
    rejection_reason = nullif(trim(p_reason), ''),
    updated_at = now()
  WHERE id = p_requisition_id;

  RETURN p_requisition_id;
END;
$$;


--
-- Name: reject_material_request(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_material_request(p_material_request_id uuid, p_reason text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_st public.procurement_doc_status;
  v_converted NUMERIC;
BEGIN
  PERFORM public._procurement_begin_rpc();
  PERFORM public._require_procurement_finance();
  PERFORM public._assert_procurement_period_open();

  SELECT status INTO v_st
  FROM public.material_requests
  WHERE id = p_material_request_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'material request not found: %', p_material_request_id;
  END IF;
  IF v_st NOT IN ('submitted', 'approved') THEN
    RAISE EXCEPTION 'only submitted/approved material requests can be rejected (status=%)', v_st;
  END IF;

  SELECT COALESCE(SUM(qty_converted), 0) INTO v_converted
  FROM public.material_request_lines
  WHERE material_request_id = p_material_request_id;

  IF v_converted > 0 THEN
    RAISE EXCEPTION 'cannot reject MR with converted lines';
  END IF;

  UPDATE public.material_requests
  SET
    status = 'rejected',
    rejected_by = auth.uid(),
    rejected_at = now(),
    rejection_reason = nullif(trim(p_reason), ''),
    updated_at = now()
  WHERE id = p_material_request_id;

  PERFORM public._procurement_end_rpc();
  RETURN p_material_request_id;
EXCEPTION
  WHEN OTHERS THEN
    PERFORM public._procurement_end_rpc();
    RAISE;
END;
$$;


--
-- Name: reject_pos_warranty_claim(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_pos_warranty_claim(p_claim_id uuid, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
 IF NOT public.is_pos_approver() THEN RAISE EXCEPTION 'POS manager approval required'; END IF;
 IF trim(COALESCE(p_reason,''))='' THEN RAISE EXCEPTION 'rejection reason required'; END IF;
 RETURN public.reject_warranty_claim(p_claim_id,p_reason);
END $$;


--
-- Name: reject_purchase_order(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_purchase_order(p_purchase_order_id uuid, p_reason text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_po public.purchase_orders%ROWTYPE;
  v_recv NUMERIC;
BEGIN
  PERFORM public._procurement_begin_rpc();
  PERFORM public._require_procurement_finance();
  PERFORM public._assert_procurement_period_open();

  SELECT * INTO v_po
  FROM public.purchase_orders
  WHERE id = p_purchase_order_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'purchase order not found: %', p_purchase_order_id;
  END IF;
  IF v_po.status NOT IN ('submitted', 'approved') THEN
    RAISE EXCEPTION 'only submitted/approved purchase orders can be rejected (status=%)', v_po.status;
  END IF;

  SELECT COALESCE(SUM(qty_received), 0) INTO v_recv
  FROM public.purchase_order_lines
  WHERE purchase_order_id = p_purchase_order_id;

  IF v_recv > 0 THEN
    RAISE EXCEPTION 'cannot reject PO with receipts';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.goods_receipts gr
    WHERE gr.purchase_order_id = p_purchase_order_id
      AND gr.status = 'submitted'
  ) THEN
    RAISE EXCEPTION 'cannot reject PO with submitted GRNs';
  END IF;

  UPDATE public.purchase_orders
  SET
    status = 'rejected',
    rejected_by = auth.uid(),
    rejected_at = now(),
    rejection_reason = nullif(trim(p_reason), ''),
    updated_at = now()
  WHERE id = p_purchase_order_id;

  PERFORM public._procurement_end_rpc();
  RETURN p_purchase_order_id;
EXCEPTION
  WHEN OTHERS THEN
    PERFORM public._procurement_end_rpc();
    RAISE;
END;
$$;


--
-- Name: reject_stock_transfer(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_stock_transfer(p_entry_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_first UUID;
BEGIN
  PERFORM public._require_warehouse_staff();
  SELECT first_approver_id INTO v_first
  FROM public.stock_entries
  WHERE id = p_entry_id AND entry_type = 'transfer' AND status = 'pending_approval'
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'pending transfer not found';
  END IF;
  IF auth.uid() IS NOT NULL AND auth.uid() = v_first THEN
    RAISE EXCEPTION 'second approver must be a different staff user';
  END IF;

  UPDATE public.stock_entries
  SET status = 'rejected',
      second_approver_id = auth.uid(),
      second_approved_at = now()
  WHERE id = p_entry_id;

  PERFORM public.emit_domain_event(
    'transfer_rejected',
    'stock_entry:rejected:' || p_entry_id::text,
    jsonb_build_object('stock_entry_id', p_entry_id)
  );

  RETURN p_entry_id;
END;
$$;


--
-- Name: reject_warranty_claim(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_warranty_claim(p_claim_id uuid, p_reason text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_status public.warranty_claim_status;
BEGIN
  PERFORM public._warranty_begin_rpc();
  PERFORM public._require_warranty_staff();

  SELECT status INTO v_status FROM public.warranty_claims WHERE id = p_claim_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'warranty claim not found';
  END IF;
  IF v_status <> 'open' THEN
    RAISE EXCEPTION 'only open claims can be rejected (status=%)', v_status;
  END IF;

  UPDATE public.warranty_claims
  SET
    status = 'rejected',
    resolution = 'reject_only',
    reject_reason = p_reason,
    decided_by = auth.uid(),
    decided_at = now()
  WHERE id = p_claim_id;

  PERFORM public.emit_domain_event(
    'warranty_claim_rejected',
    'warranty:rejected:' || p_claim_id::text,
    jsonb_build_object('warranty_claim_id', p_claim_id, 'reason', p_reason)
  );

  RETURN p_claim_id;
END;
$$;


--
-- Name: release_hr_auth_provision(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_hr_auth_provision(p_employee_id uuid, p_claim_token text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_token TEXT := NULLIF(trim(COALESCE(p_claim_token, '')), '');
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'service_role required';
  END IF;
  IF p_employee_id IS NULL OR v_token IS NULL THEN
    RETURN false;
  END IF;
  DELETE FROM public.hr_auth_provision_locks
  WHERE employee_id = p_employee_id
    AND claim_token = v_token;
  RETURN FOUND;
END;
$$;


--
-- Name: remove_customer_compare_item(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.remove_customer_compare_item(p_stock_item_id uuid DEFAULT NULL::uuid, p_oem_part_number text DEFAULT NULL::text, p_compare_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cust UUID := public._current_customer_id();
  v_item UUID;
  v_deleted INT := 0;
BEGIN
  IF v_cust IS NULL THEN
    RAISE EXCEPTION 'customer profile required';
  END IF;

  IF p_compare_id IS NOT NULL THEN
    DELETE FROM public.customer_compare_items
    WHERE id = p_compare_id AND customer_id = v_cust;
    GET DIAGNOSTICS v_deleted = ROW_COUNT;
    IF v_deleted = 0 THEN
      RAISE EXCEPTION 'compare item not found';
    END IF;
    RETURN;
  END IF;

  v_item := public._resolve_customer_stock_item(p_stock_item_id, p_oem_part_number);

  DELETE FROM public.customer_compare_items
  WHERE customer_id = v_cust AND stock_item_id = v_item;
  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  IF v_deleted = 0 THEN
    RAISE EXCEPTION 'compare item not found';
  END IF;
END;
$$;


--
-- Name: remove_customer_wishlist_item(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.remove_customer_wishlist_item(p_stock_item_id uuid DEFAULT NULL::uuid, p_oem_part_number text DEFAULT NULL::text, p_wishlist_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cust UUID := public._current_customer_id();
  v_item UUID;
  v_deleted INT := 0;
BEGIN
  IF v_cust IS NULL THEN
    RAISE EXCEPTION 'customer profile required';
  END IF;

  IF p_wishlist_id IS NOT NULL THEN
    DELETE FROM public.customer_wishlist_items
    WHERE id = p_wishlist_id AND customer_id = v_cust;
    GET DIAGNOSTICS v_deleted = ROW_COUNT;
    IF v_deleted = 0 THEN
      RAISE EXCEPTION 'wishlist item not found';
    END IF;
    RETURN;
  END IF;

  v_item := public._resolve_customer_stock_item(p_stock_item_id, p_oem_part_number);

  DELETE FROM public.customer_wishlist_items
  WHERE customer_id = v_cust AND stock_item_id = v_item;
  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  IF v_deleted = 0 THEN
    RAISE EXCEPTION 'wishlist item not found';
  END IF;
END;
$$;


--
-- Name: remove_kit_component(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.remove_kit_component(p_kit_id uuid, p_component_item_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE v_remaining INT; BEGIN PERFORM public._require_kit_staff(); DELETE FROM public.item_kit_components WHERE kit_id=p_kit_id AND component_item_id=p_component_item_id; IF NOT FOUND THEN RAISE EXCEPTION 'kit component not found'; END IF; SELECT count(*)::int INTO v_remaining FROM public.item_kit_components WHERE kit_id=p_kit_id; IF v_remaining<2 THEN RAISE EXCEPTION 'kit must retain at least 2 components (remaining: %)',v_remaining; END IF; END; $$;


--
-- Name: repair_pos_paid_order(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.repair_pos_paid_order(p_order_id uuid, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE o public.commerce_orders%ROWTYPE; pe public.payment_entries%ROWTYPE; r RECORD; v_other NUMERIC; v_inv UUID; v_redeem UUID;
BEGIN
 IF NOT (public.is_pos_approver() OR public.has_staff_role(ARRAY['finance']::public.staff_role[])) THEN RAISE EXCEPTION 'manager or finance approval required'; END IF;
 SELECT * INTO o FROM public.commerce_orders WHERE id=p_order_id FOR UPDATE;
 IF NOT FOUND OR o.sales_invoice_id IS NOT NULL OR o.settled_payment_entry_id IS NULL OR o.state<>'allocation_pending' THEN RAISE EXCEPTION 'paid-but-unfinalized commerce order required'; END IF;
 SELECT * INTO pe FROM public.payment_entries WHERE id=o.settled_payment_entry_id FOR UPDATE;
 IF NOT FOUND OR pe.status<>'posted' OR pe.store_credit_issued+0.01<o.total THEN RAISE EXCEPTION 'unapplied posted provider receipt required for safe repair'; END IF;
 FOR r IN SELECT * FROM public.inventory_reservations WHERE commerce_order_id=o.id FOR UPDATE LOOP
  SELECT COALESCE(SUM(GREATEST(x.reserved_qty-x.consumed_qty,0)),0) INTO v_other FROM public.inventory_reservations x
   WHERE x.stock_item_id=r.stock_item_id AND x.warehouse_id=r.warehouse_id AND x.id<>r.id AND x.state IN('active','allocated') AND (x.state='allocated' OR x.expires_at IS NULL OR x.expires_at>now());
  IF COALESCE((SELECT quantity FROM public.stock_levels WHERE stock_item_id=r.stock_item_id AND warehouse_id=r.warehouse_id),0)-v_other<r.required_qty THEN
   RAISE EXCEPTION 'cannot repair paid order: stock no longer available for item %',r.stock_item_id;
  END IF;
 END LOOP;
 UPDATE public.inventory_reservations SET state='active',reserved_qty=required_qty,consumed_qty=0,expires_at=now()+interval '20 minutes',released_at=NULL WHERE commerce_order_id=o.id;
 UPDATE public.commerce_orders SET state='payment_failed',reservation_expires_at=now()+interval '20 minutes',updated_at=now() WHERE id=o.id;
 v_inv:=private.finalize_commerce_order(o.id);
 v_redeem:=public.redeem_store_credit(o.customer_id,o.total,o.currency,o.exchange_rate_applied,v_inv,concat_ws(' · ','Recovery of captured provider payment',p_notes));
 UPDATE public.commerce_orders SET state=CASE WHEN fulfillment_mode='dispatch' THEN 'allocation_pending'::public.commerce_order_state ELSE 'paid'::public.commerce_order_state END,
  payment_exception=NULL,updated_at=now() WHERE id=o.id;
 UPDATE public.commerce_payment_exceptions SET resolved_at=now(),resolution=concat_ws(' · ','order repaired; unapplied receipt redeemed to finalized invoice',p_notes)
 WHERE commerce_order_id=o.id AND resolved_at IS NULL AND exception_code='PAID_ORDER_FINALIZATION_FAILED';
 PERFORM public._log_pos_action('paid_order_repaired','commerce_orders',o.id,to_jsonb(o),(SELECT to_jsonb(x) FROM public.commerce_orders x WHERE x.id=o.id),p_notes);
 RETURN v_inv;
END $$;


--
-- Name: replay_offline_pos_sale(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.replay_offline_pos_sale(p_client_sale_id uuid, p_payload jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_existing UUID;
  v_warehouse UUID;
  v_currency public.currency_code;
  v_rate NUMERIC;
  v_device TEXT;
  v_lines JSONB;
  v_tenders JSONB;
  v_line JSONB;
  v_tender JSONB;
  v_cart UUID;
  v_inv UUID;
  v_stock UUID;
  v_uom UUID;
  v_qty NUMERIC;
  v_expected NUMERIC;
  v_price NUMERIC;
  v_hash TEXT;
  v_email TEXT;
  v_wa TEXT;
  v_phone TEXT;
  v_amt NUMERIC;
  v_tender_code TEXT;
  v_vehicle JSONB;
  v_vehicle_contexts JSONB;
  v_vehicle_context JSONB;
BEGIN
  PERFORM public._require_payments_staff();

  IF p_client_sale_id IS NULL THEN
    RAISE EXCEPTION 'client_sale_id required';
  END IF;
  IF p_payload IS NULL OR jsonb_typeof(p_payload) <> 'object' THEN
    RAISE EXCEPTION 'payload object required';
  END IF;

  SELECT r.invoice_id INTO v_existing
  FROM public.pos_offline_sale_receipts r
  WHERE r.client_sale_id = p_client_sale_id;

  IF v_existing IS NOT NULL THEN
    RETURN v_existing;
  END IF;

  v_warehouse := (p_payload->>'warehouse_id')::uuid;
  IF v_warehouse IS NULL THEN
    RAISE EXCEPTION 'warehouse_id required in payload';
  END IF;

  v_currency := COALESCE(
    (p_payload->>'currency')::public.currency_code,
    'USD'::public.currency_code
  );
  v_rate := COALESCE((p_payload->>'exchange_rate')::numeric, 1);
  IF v_rate IS NULL OR v_rate <= 0 THEN
    RAISE EXCEPTION 'exchange_rate must be > 0';
  END IF;

  v_device := NULLIF(trim(COALESCE(p_payload->>'device_id', '')), '');
  v_lines := p_payload->'lines';
  v_tenders := p_payload->'tenders';
  v_vehicle := p_payload->'vehicle';
  v_vehicle_contexts := COALESCE(p_payload->'vehicle_contexts', '[]'::jsonb);
  IF jsonb_typeof(v_vehicle_contexts) <> 'array' THEN
    RAISE EXCEPTION 'vehicle_contexts must be an array';
  END IF;

  IF v_lines IS NULL OR jsonb_typeof(v_lines) <> 'array' OR jsonb_array_length(v_lines) < 1 THEN
    RAISE EXCEPTION 'lines required';
  END IF;
  IF v_tenders IS NULL OR jsonb_typeof(v_tenders) <> 'array' OR jsonb_array_length(v_tenders) < 1 THEN
    RAISE EXCEPTION 'tenders required';
  END IF;

  FOR v_tender IN SELECT * FROM jsonb_array_elements(v_tenders)
  LOOP
    v_tender_code := lower(trim(COALESCE(v_tender->>'tender', '')));
    IF v_tender_code IS DISTINCT FROM 'cash' THEN
      RAISE EXCEPTION 'offline_tender_not_allowed: % (cash only)', v_tender_code;
    END IF;
    v_amt := (v_tender->>'amount')::numeric;
    IF v_amt IS NULL OR v_amt <= 0 THEN
      RAISE EXCEPTION 'tender amount must be > 0';
    END IF;
  END LOOP;

  v_email := NULLIF(trim(COALESCE(p_payload->>'receipt_email', '')), '');
  v_wa := NULLIF(trim(COALESCE(p_payload->>'receipt_whatsapp_e164', '')), '');
  v_phone := NULLIF(trim(COALESCE(p_payload->>'receipt_phone_e164', '')), '');

  v_hash := encode(
    extensions.digest(convert_to(p_payload::text, 'UTF8'), 'sha256'),
    'hex'
  );

  v_cart := public.create_pos_cart(
    v_warehouse,
    NULL,
    v_currency,
    'immediate'::public.fulfillment_mode
  );

  IF v_cart IS NULL THEN
    RAISE EXCEPTION 'create_pos_cart failed';
  END IF;

  UPDATE public.pos_carts
  SET exchange_rate_applied = v_rate, updated_at = now()
  WHERE id = v_cart;

  FOR v_vehicle_context IN SELECT * FROM jsonb_array_elements(v_vehicle_contexts)
  LOOP
    IF jsonb_typeof(v_vehicle_context) = 'object'
       AND NULLIF(trim(COALESCE(v_vehicle_context->>'model_slug', '')), '') IS NOT NULL THEN
      PERFORM public.set_pos_cart_vehicle(
        v_cart,
        v_vehicle_context->>'model_slug',
        v_vehicle_context->>'model_name',
        v_vehicle_context->>'generation',
        v_vehicle_context->>'chassis_code',
        v_vehicle_context->>'engine_code'
      );
    END IF;
  END LOOP;

  IF v_vehicle IS NOT NULL AND jsonb_typeof(v_vehicle) = 'object'
     AND NULLIF(trim(COALESCE(v_vehicle->>'model_slug', '')), '') IS NOT NULL THEN
    PERFORM public.set_pos_cart_vehicle(
      v_cart,
      v_vehicle->>'model_slug',
      v_vehicle->>'model_name',
      v_vehicle->>'generation',
      v_vehicle->>'chassis_code',
      v_vehicle->>'engine_code'
    );
  END IF;

  FOR v_line IN SELECT * FROM jsonb_array_elements(v_lines)
  LOOP
    v_stock := (v_line->>'stock_item_id')::uuid;
    v_uom := (v_line->>'uom_id')::uuid;
    v_qty := (v_line->>'qty')::numeric;
    v_expected := (v_line->>'expected_unit_price')::numeric;

    IF v_stock IS NULL OR v_uom IS NULL THEN
      RAISE EXCEPTION 'line stock_item_id and uom_id required';
    END IF;
    IF v_qty IS NULL OR v_qty <= 0 THEN
      RAISE EXCEPTION 'line qty must be > 0';
    END IF;

    SELECT r.unit_price INTO v_price
    FROM public.resolve_item_price(NULL, v_stock) r;

    IF v_expected IS NOT NULL AND abs(COALESCE(v_price, 0) - v_expected) > 0.05 THEN
      RAISE EXCEPTION 'offline_price_conflict: item % expected % got %',
        v_stock, v_expected, v_price;
    END IF;

    PERFORM public.add_cart_line(v_cart, v_stock, v_uom, v_qty);
  END LOOP;

  v_inv := public.checkout_pos_cart_with_tenders(
    v_cart,
    v_tenders,
    v_email,
    v_wa,
    v_phone
  );

  INSERT INTO public.pos_offline_sale_receipts (
    client_sale_id,
    invoice_id,
    actor_user_id,
    device_id,
    warehouse_id,
    currency,
    payload_hash
  ) VALUES (
    p_client_sale_id,
    v_inv,
    auth.uid(),
    v_device,
    v_warehouse,
    v_currency,
    v_hash
  );

  RETURN v_inv;
EXCEPTION
  WHEN unique_violation THEN
    SELECT r.invoice_id INTO v_existing
    FROM public.pos_offline_sale_receipts r
    WHERE r.client_sale_id = p_client_sale_id;
    IF v_existing IS NOT NULL THEN
      RETURN v_existing;
    END IF;
    RAISE;
END;
$$;


--
-- Name: FUNCTION replay_offline_pos_sale(p_client_sale_id uuid, p_payload jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.replay_offline_pos_sale(p_client_sale_id uuid, p_payload jsonb) IS 'Idempotent offline POS replay with complete Nissan multi-vehicle history; cash only; validated against current EPC and price authority.';


--
-- Name: report_account_register(character varying, date, date, public.currency_code); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_account_register(p_account_code character varying, p_from date, p_to date, p_currency public.currency_code DEFAULT NULL::public.currency_code) RETURNS TABLE(entry_date date, document_number text, description text, debit numeric, credit numeric, running_balance numeric, currency public.currency_code, journal_entry_id uuid)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_opening NUMERIC(18, 2) := 0;
BEGIN
  IF NOT (
    auth.role() = 'service_role'
    OR public.has_staff_role(ARRAY['admin', 'finance']::public.staff_role[])
  ) THEN
    RAISE EXCEPTION 'finance or admin role required';
  END IF;

  IF p_account_code IS NULL OR p_from IS NULL OR p_to IS NULL OR p_to < p_from THEN
    RAISE EXCEPTION 'account, from, and to required (to >= from)';
  END IF;

  SELECT COALESCE(SUM(l.debit - l.credit), 0)
  INTO v_opening
  FROM public.journal_entry_lines l
  JOIN public.journal_entries e ON e.id = l.journal_entry_id
  WHERE e.status = 'posted'
    AND l.account_code = p_account_code
    AND e.entry_date < p_from
    AND (p_currency IS NULL OR e.currency = p_currency);

  RETURN QUERY
  WITH moves AS (
    SELECT
      e.entry_date AS entry_date,
      e.document_number AS document_number,
      e.description AS description,
      COALESCE(SUM(l.debit), 0) AS debit,
      COALESCE(SUM(l.credit), 0) AS credit,
      e.currency AS currency,
      e.id AS journal_entry_id
    FROM public.journal_entry_lines l
    JOIN public.journal_entries e ON e.id = l.journal_entry_id
    WHERE e.status = 'posted'
      AND l.account_code = p_account_code
      AND e.entry_date BETWEEN p_from AND p_to
      AND (p_currency IS NULL OR e.currency = p_currency)
    GROUP BY e.id, e.entry_date, e.document_number, e.description, e.currency
  )
  SELECT
    m.entry_date,
    m.document_number,
    m.description,
    m.debit,
    m.credit,
    v_opening + SUM(m.debit - m.credit) OVER (
      ORDER BY m.entry_date, m.document_number NULLS LAST, m.journal_entry_id
      ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
    ) AS running_balance,
    m.currency,
    m.journal_entry_id
  FROM moves m
  ORDER BY m.entry_date, m.document_number NULLS LAST, m.journal_entry_id;
END;
$$;


--
-- Name: report_balance_sheet(date, public.currency_code); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_balance_sheet(p_as_of date DEFAULT CURRENT_DATE, p_currency public.currency_code DEFAULT NULL::public.currency_code) RETURNS TABLE(account_code character varying, account_name text, account_type public.account_type, balance numeric, balance_usd numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT (
    auth.role() = 'service_role'
    OR public.has_staff_role(ARRAY['admin', 'finance']::public.staff_role[])
  ) THEN
    RAISE EXCEPTION 'finance or admin role required';
  END IF;

  RETURN QUERY
  SELECT
    c.code,
    c.name,
    c.account_type,
    CASE
      WHEN c.account_type IN ('asset', 'expense') THEN COALESCE(SUM(l.debit - l.credit), 0)
      ELSE COALESCE(SUM(l.credit - l.debit), 0)
    END,
    CASE
      WHEN c.account_type IN ('asset', 'expense') THEN COALESCE(SUM(
        public._line_usd_equiv(l.debit, e.currency, e.exchange_rate_applied)
        - public._line_usd_equiv(l.credit, e.currency, e.exchange_rate_applied)
      ), 0)
      ELSE COALESCE(SUM(
        public._line_usd_equiv(l.credit, e.currency, e.exchange_rate_applied)
        - public._line_usd_equiv(l.debit, e.currency, e.exchange_rate_applied)
      ), 0)
    END
  FROM public.chart_of_accounts c
  LEFT JOIN public.journal_entry_lines l ON l.account_code = c.code
  LEFT JOIN public.journal_entries e
    ON e.id = l.journal_entry_id
   AND e.status = 'posted'
   AND e.entry_date <= p_as_of
   AND (p_currency IS NULL OR e.currency = p_currency)
  WHERE c.account_type IN ('asset', 'liability', 'equity')
  GROUP BY c.code, c.name, c.account_type
  ORDER BY c.code;
END;
$$;


--
-- Name: report_cash_flow(date, date, public.currency_code); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_cash_flow(p_from date, p_to date, p_currency public.currency_code DEFAULT NULL::public.currency_code) RETURNS TABLE(section text, label text, amount_usd numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT (
    auth.role() = 'service_role'
    OR public.has_staff_role(ARRAY['admin', 'finance']::public.staff_role[])
  ) THEN
    RAISE EXCEPTION 'finance or admin role required';
  END IF;

  RETURN QUERY
  WITH cash_moves AS (
    SELECT
      COALESCE(SUM(
        public._line_usd_equiv(l.debit - l.credit, e.currency, e.exchange_rate_applied)
      ), 0) AS net_cash_usd
    FROM public.journal_entry_lines l
    JOIN public.journal_entries e ON e.id = l.journal_entry_id
    WHERE e.status = 'posted'
      AND e.entry_date BETWEEN p_from AND p_to
      AND l.account_code = '1100'
      AND (p_currency IS NULL OR e.currency = p_currency)
  ),
  pl AS (
    SELECT COALESCE(SUM(r.amount_usd), 0) AS net_income_usd
    FROM public.report_profit_and_loss(p_from, p_to, p_currency) r
  )
  SELECT 'operating'::text, 'Net income (P&L proxy)'::text, (SELECT net_income_usd FROM pl)
  UNION ALL
  SELECT 'operating', 'Net change in cash (1100)', (SELECT net_cash_usd FROM cash_moves)
  UNION ALL
  SELECT 'investing', 'Not classified (Phase 3 heuristic)', 0::numeric
  UNION ALL
  SELECT 'financing', 'Not classified (Phase 3 heuristic)', 0::numeric;
END;
$$;


--
-- Name: report_profit_and_loss(date, date, public.currency_code); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_profit_and_loss(p_from date, p_to date, p_currency public.currency_code DEFAULT NULL::public.currency_code) RETURNS TABLE(account_code character varying, account_name text, account_type public.account_type, amount numeric, amount_usd numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT (
    auth.role() = 'service_role'
    OR public.has_staff_role(ARRAY['admin', 'finance']::public.staff_role[])
  ) THEN
    RAISE EXCEPTION 'finance or admin role required';
  END IF;

  RETURN QUERY
  SELECT
    c.code,
    c.name,
    c.account_type,
    COALESCE(SUM(l.credit - l.debit), 0),
    COALESCE(SUM(
      public._line_usd_equiv(l.credit, e.currency, e.exchange_rate_applied)
      - public._line_usd_equiv(l.debit, e.currency, e.exchange_rate_applied)
    ), 0)
  FROM public.chart_of_accounts c
  JOIN public.journal_entry_lines l ON l.account_code = c.code
  JOIN public.journal_entries e ON e.id = l.journal_entry_id
  WHERE e.status = 'posted'
    AND e.entry_date BETWEEN p_from AND p_to
    AND c.account_type IN ('income', 'expense')
    AND (p_currency IS NULL OR e.currency = p_currency)
  GROUP BY c.code, c.name, c.account_type
  ORDER BY c.code;
END;
$$;


--
-- Name: report_trial_balance(date, public.currency_code); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_trial_balance(p_as_of date DEFAULT CURRENT_DATE, p_currency public.currency_code DEFAULT NULL::public.currency_code) RETURNS TABLE(account_code character varying, account_name text, account_type public.account_type, debit numeric, credit numeric, debit_usd numeric, credit_usd numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT (
    auth.role() = 'service_role'
    OR public.has_staff_role(ARRAY['admin', 'finance']::public.staff_role[])
  ) THEN
    RAISE EXCEPTION 'finance or admin role required';
  END IF;

  RETURN QUERY
  SELECT
    c.code,
    c.name,
    c.account_type,
    COALESCE(SUM(l.debit), 0),
    COALESCE(SUM(l.credit), 0),
    COALESCE(SUM(public._line_usd_equiv(l.debit, e.currency, e.exchange_rate_applied)), 0),
    COALESCE(SUM(public._line_usd_equiv(l.credit, e.currency, e.exchange_rate_applied)), 0)
  FROM public.chart_of_accounts c
  LEFT JOIN public.journal_entry_lines l ON l.account_code = c.code
  LEFT JOIN public.journal_entries e
    ON e.id = l.journal_entry_id
   AND e.status = 'posted'
   AND e.entry_date <= p_as_of
   AND (p_currency IS NULL OR e.currency = p_currency)
  GROUP BY c.code, c.name, c.account_type
  ORDER BY c.code;
END;
$$;


--
-- Name: request_customer_return(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_customer_return(p_invoice_id uuid, p_lines jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_customer uuid:=public._current_customer_id();
  v_inv public.sales_invoices%ROWTYPE;
  v_req uuid;
  v_elem jsonb;
  v_src public.sales_invoice_lines%ROWTYPE;
  v_line_id uuid;
  v_item uuid;
  v_uom uuid;
  v_qty numeric;
  v_qty_base numeric;
  v_reserved numeric;
  v_match_count integer;
BEGIN
  IF v_customer IS NULL THEN RAISE EXCEPTION 'customer profile required'; END IF;
  SELECT * INTO v_inv FROM public.sales_invoices
  WHERE id=p_invoice_id AND customer_id=v_customer FOR UPDATE;
  IF NOT FOUND OR v_inv.doc_type<>'invoice' OR v_inv.status<>'posted' THEN
    RAISE EXCEPTION 'owned posted invoice required';
  END IF;
  IF p_lines IS NULL OR jsonb_typeof(p_lines)<>'array' OR jsonb_array_length(p_lines)=0 THEN
    RAISE EXCEPTION 'return lines required';
  END IF;

  INSERT INTO public.customer_return_requests(customer_id,source_invoice_id,requested_by)
  VALUES(v_customer,p_invoice_id,auth.uid()) RETURNING id INTO v_req;

  FOR v_elem IN SELECT * FROM jsonb_array_elements(p_lines)
  LOOP
    v_line_id:=NULLIF(v_elem->>'sales_invoice_line_id','')::uuid;
    v_qty:=NULLIF(v_elem->>'qty','')::numeric;
    IF v_qty IS NULL OR v_qty<=0 THEN RAISE EXCEPTION 'each return line requires qty > 0'; END IF;

    IF v_line_id IS NOT NULL THEN
      SELECT * INTO v_src FROM public.sales_invoice_lines
      WHERE id=v_line_id AND invoice_id=p_invoice_id;
    ELSE
      v_item:=NULLIF(v_elem->>'stock_item_id','')::uuid;
      v_uom:=NULLIF(v_elem->>'uom_id','')::uuid;
      IF v_item IS NULL OR v_uom IS NULL THEN
        RAISE EXCEPTION 'sales_invoice_line_id or stock_item_id/uom_id required';
      END IF;
      SELECT count(*) INTO v_match_count FROM public.sales_invoice_lines
      WHERE invoice_id=p_invoice_id AND stock_item_id=v_item AND uom_id=v_uom AND NOT is_core_charge;
      IF v_match_count<>1 THEN RAISE EXCEPTION 'return line is ambiguous; sales_invoice_line_id required'; END IF;
      SELECT * INTO v_src FROM public.sales_invoice_lines
      WHERE invoice_id=p_invoice_id AND stock_item_id=v_item AND uom_id=v_uom AND NOT is_core_charge
      LIMIT 1;
    END IF;

    IF NOT FOUND OR v_src.is_core_charge THEN RAISE EXCEPTION 'returnable invoice line not found'; END IF;
    IF NOT COALESCE(v_src.issues_stock,true) THEN
      RAISE EXCEPTION 'non-stock/exploded-kit header returns require staff-assisted workflow';
    END IF;
    IF COALESCE(v_src.qty_fulfilled,0)<=0 THEN RAISE EXCEPTION 'unfulfilled items cannot be returned'; END IF;
    IF v_src.unit_cost_basis IS NULL THEN RAISE EXCEPTION 'invoice line cost basis missing; return requires finance review'; END IF;

    v_qty_base:=public.convert_to_base_uom(v_src.stock_item_id,v_src.uom_id,v_qty);
    SELECT COALESCE(sum(rl.qty_base),0) INTO v_reserved
    FROM public.customer_return_request_lines rl
    JOIN public.customer_return_requests rr ON rr.id=rl.return_request_id
    WHERE rl.source_invoice_line_id=v_src.id AND rr.status NOT IN ('rejected','cancelled');

    IF v_qty_base>GREATEST(v_src.qty_fulfilled-v_reserved,0)+0.0001 THEN
      RAISE EXCEPTION 'return quantity exceeds fulfilled unreturned quantity';
    END IF;

    INSERT INTO public.customer_return_request_lines(
      return_request_id,source_invoice_line_id,stock_item_id,uom_id,qty,qty_base,
      unit_price_snapshot,line_total_snapshot,unit_cost_basis,cost_total_basis
    ) VALUES(
      v_req,v_src.id,v_src.stock_item_id,v_src.uom_id,v_qty,v_qty_base,
      v_src.unit_price,round(v_src.unit_price*v_qty,2),v_src.unit_cost_basis,
      round(v_src.unit_cost_basis*v_qty_base,4)
    );
  END LOOP;

  PERFORM private.enqueue_commerce_event(
    'return:req:'||v_req::text,'return.requested',v_req,
    jsonb_build_object('return_request_id',v_req,'invoice_id',p_invoice_id,'customer_id',v_customer)
  );
  RETURN v_req;
END;
$$;


--
-- Name: request_delivery_balance_on_account(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_delivery_balance_on_account(p_delivery_job_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE j public.delivery_jobs%ROWTYPE; i public.sales_invoices%ROWTYPE; c public.customers%ROWTYPE;
  v_due numeric; v_exposure numeric; b public.delivery_balance_approvals%ROWTYPE; v_auto boolean := false;
BEGIN
 SELECT * INTO j FROM public.delivery_jobs WHERE id=p_delivery_job_id FOR UPDATE;
 IF NOT FOUND OR j.status<>'dispatched' OR j.assignee_user_id IS DISTINCT FROM auth.uid() OR NOT public.has_staff_role(ARRAY['driver']::public.staff_role[]) THEN
  RAISE EXCEPTION 'assigned dispatched driver job required'; END IF;
 IF trim(COALESCE(p_reason,''))='' THEN RAISE EXCEPTION 'say why the customer cannot pay the rest'; END IF;
 SELECT si.* INTO i FROM public.delivery_notes dn JOIN public.sales_invoices si ON si.id=dn.sales_invoice_id WHERE dn.id=j.delivery_note_id;
 IF NOT FOUND OR i.delivery_payment_method NOT IN('cash_on_delivery','card_on_delivery','cash_or_card_on_delivery') THEN
  RAISE EXCEPTION 'this delivery is not cash or card on delivery'; END IF;
 IF EXISTS(SELECT 1 FROM public.pos_card_terminal_attempts a WHERE a.delivery_job_id=j.id AND a.status IN('initiated','approved','unknown')) THEN
  RAISE EXCEPTION 'finish the card payment on this delivery first'; END IF;
 v_due:=greatest(round(i.total-i.amount_paid,2),0);
 IF v_due<=0.004 THEN RAISE EXCEPTION 'nothing is owed on this delivery'; END IF;
 -- One open request per delivery: a repeat returns it (or replaces a pending one whose balance changed).
 SELECT * INTO b FROM public.delivery_balance_approvals WHERE delivery_job_id=j.id AND status IN('pending','auto_approved','approved') FOR UPDATE;
 IF FOUND THEN
  IF b.status<>'pending' AND v_due<=b.amount+0.01 THEN RETURN private._delivery_balance_approval_json(b); END IF;
  UPDATE public.delivery_balance_approvals SET status='cancelled',updated_at=now() WHERE id=b.id;
 END IF;
 IF i.customer_id IS NOT NULL THEN
  SELECT * INTO c FROM public.customers WHERE id=i.customer_id;
  v_exposure := (private.customer_exposure(i.customer_id)->>'total')::numeric;
  -- Limit and exposure are in the account currency; an unconvertible exposure goes to the back office.
  v_auto := v_exposure IS NOT NULL AND i.currency=c.currency AND NOT COALESCE(c.credit_hold,false)
    AND COALESCE(c.credit_limit,0)>0 AND v_exposure<=c.credit_limit+0.01;
 END IF;
 INSERT INTO public.delivery_balance_approvals(delivery_job_id,sales_invoice_id,customer_id,amount,currency,reason,status,basis,credit_limit,exposure,decided_at)
 VALUES(j.id,i.id,i.customer_id,v_due,i.currency,trim(p_reason),CASE WHEN v_auto THEN 'auto_approved' ELSE 'pending' END,
  CASE WHEN v_auto THEN 'credit_limit' ELSE 'back_office' END,c.credit_limit,v_exposure,CASE WHEN v_auto THEN now() END)
 RETURNING * INTO b;
 RETURN private._delivery_balance_approval_json(b);
END $$;


--
-- Name: request_pos_split_cancellation(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_pos_split_cancellation(p_session_id uuid, p_reason text, p_fee_policy text DEFAULT 'manual_review'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE s public.pos_split_payment_sessions%ROWTYPE; l public.pos_split_payment_legs%ROWTYPE;
BEGIN
 PERFORM public._require_sales_staff(); IF p_fee_policy NOT IN('business_absorbs','customer_bears','manual_review') THEN RAISE EXCEPTION 'unsupported refund fee policy'; END IF;
 PERFORM private.refresh_pos_split_payment_session(p_session_id); SELECT * INTO s FROM public.pos_split_payment_sessions WHERE id=p_session_id FOR UPDATE;
 IF s.status='settled' THEN RAISE EXCEPTION 'settled sale must use the posted invoice return/refund workflow'; END IF;
 IF EXISTS(SELECT 1 FROM public.pos_split_payment_legs WHERE session_id=s.id AND status IN('pending','unknown')) THEN RAISE EXCEPTION 'reconcile every in-flight payment before cancelling the split sale'; END IF;
 UPDATE public.pos_split_payment_legs SET status='cancelled',updated_at=now() WHERE session_id=s.id AND status IN('planned','failed','held');
 FOR l IN SELECT * FROM public.pos_split_payment_legs WHERE session_id=s.id AND status='captured' FOR UPDATE LOOP
  INSERT INTO public.pos_split_refund_requests(session_id,leg_id,gross_amount,fee_policy,external_reference,notes,created_by)
  VALUES(s.id,l.id,l.requested_amount,p_fee_policy,'GTR-SPLIT-REFUND-'||l.id::text,p_reason,auth.uid()) ON CONFLICT(leg_id) DO NOTHING;
  UPDATE public.pos_split_payment_legs SET status='refund_review',status_detail='Refund requires explicit manager/provider confirmation',updated_at=now() WHERE id=l.id;
 END LOOP;
 PERFORM private.release_commerce_order(s.commerce_order_id,'cancelled',concat_ws(' · ','POS split cancelled; captured funds retained in refund liability',p_reason));
 IF EXISTS(SELECT 1 FROM public.pos_split_payment_legs WHERE session_id=s.id AND status='refund_review') THEN
  UPDATE public.pos_split_payment_sessions SET status='refund_review',cancelled_at=now(),updated_at=now() WHERE id=s.id;
 ELSE UPDATE public.pos_split_payment_sessions SET status='cancelled',cancelled_at=now(),updated_at=now() WHERE id=s.id; END IF;
 RETURN private.pos_split_payment_payload(s.id);
END $$;


--
-- Name: resolve_auth_user(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_auth_user(p_email text DEFAULT NULL::text, p_phone_e164 text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_email text := lower(trim(coalesce(p_email, '')));
  v_phone text := trim(coalesce(p_phone_e164, ''));
  v_email_uid uuid;
  v_phone_uid uuid;
begin
  if coalesce(auth.jwt()->>'role', '') <> 'service_role' then
    raise exception 'service_role required';
  end if;

  if v_email <> '' then
    select u.id into v_email_uid
    from auth.users u
    where lower(u.email) = v_email
    order by u.created_at asc
    limit 1;
  end if;

  if v_phone <> '' then
    select u.id into v_phone_uid
    from auth.users u
    where u.phone = v_phone
    order by u.created_at asc
    limit 1;
  end if;

  if v_email <> '' and v_phone <> ''
     and v_email_uid is not null and v_phone_uid is not null
     and v_email_uid <> v_phone_uid then
    raise exception 'AUTH_IDENTIFIER_CONFLICT';
  end if;

  return coalesce(v_email_uid, v_phone_uid);
end;
$$;


--
-- Name: resolve_customer_for_receipt_contacts(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_customer_for_receipt_contacts(p_email text DEFAULT NULL::text, p_whatsapp_e164 text DEFAULT NULL::text, p_phone_e164 text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_email TEXT := public._normalize_receipt_email(p_email);
  v_wa TEXT := public._normalize_e164(p_whatsapp_e164);
  v_phone TEXT := public._normalize_e164(p_phone_e164);
  v_ids UUID[];
BEGIN
  IF v_email IS NULL AND v_wa IS NULL AND v_phone IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT array_agg(DISTINCT c.id)
  INTO v_ids
  FROM public.customers c
  LEFT JOIN public.price_lists pl ON pl.id = c.price_list_id
  WHERE (
      c.profile_id IS NOT NULL
      OR COALESCE(pl.code, 'RETAIL') <> 'RETAIL'
    )
    AND (
      (v_email IS NOT NULL AND lower(trim(COALESCE(c.email, ''))) = v_email)
      OR (v_phone IS NOT NULL AND (
        public._normalize_e164(c.phone_e164) = v_phone
        OR public._normalize_e164(c.whatsapp_e164) = v_phone
      ))
      OR (v_wa IS NOT NULL AND (
        public._normalize_e164(c.whatsapp_e164) = v_wa
        OR public._normalize_e164(c.phone_e164) = v_wa
      ))
    );

  IF v_ids IS NULL OR cardinality(v_ids) <> 1 THEN
    RETURN NULL;
  END IF;
  RETURN v_ids[1];
END;
$$;


--
-- Name: resolve_hr_onboarding_staff_role(jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_hr_onboarding_staff_role(p_payload jsonb, p_hr_role_id uuid DEFAULT NULL::uuid) RETURNS public.staff_role
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_payload JSONB := COALESCE(p_payload, '{}'::jsonb);
  v_explicit public.staff_role;
  v_default public.staff_role;
  v_title TEXT;
  v_dept TEXT;
  v_modules TEXT;
  v_hay TEXT;
  v_role_id UUID;
BEGIN
  v_explicit := public._parse_staff_role_text(v_payload->>'staff_role');
  IF v_explicit IS NOT NULL THEN
    IF v_explicit = 'admin'::public.staff_role
       AND auth.role() IS DISTINCT FROM 'service_role'
       AND NOT public.has_staff_role(ARRAY['admin']::public.staff_role[]) THEN
      RAISE EXCEPTION 'admin staff_role requires an admin caller';
    END IF;
    RETURN v_explicit;
  END IF;

  v_role_id := COALESCE(
    p_hr_role_id,
    NULLIF(v_payload->>'hr_role_id', '')::uuid
  );

  IF v_role_id IS NOT NULL THEN
    SELECT r.default_staff_role, r.title, r.department, COALESCE(r.module_access::text, '')
    INTO v_default, v_title, v_dept, v_modules
    FROM public.hr_roles r
    WHERE r.id = v_role_id AND r.is_active;

    IF v_default IS NOT NULL THEN
      IF v_default = 'admin'::public.staff_role
         AND auth.role() IS DISTINCT FROM 'service_role'
         AND NOT public.has_staff_role(ARRAY['admin']::public.staff_role[]) THEN
        -- Skip unsafe organogram default; fall through to heuristic.
        NULL;
      ELSE
        RETURN v_default;
      END IF;
    END IF;
  ELSE
    v_title := NULL;
    v_dept := NULL;
    v_modules := '';
  END IF;

  v_hay := lower(
    trim(COALESCE(v_title, '')) || ' ' ||
    trim(COALESCE(v_dept, '')) || ' ' ||
    COALESCE(v_modules, '') || ' ' ||
    trim(COALESCE(v_payload->>'role_title', ''))
  );

  IF v_hay ~ '(driver|delivery|fleet|courier)' THEN
    RETURN 'driver'::public.staff_role;
  END IF;
  IF v_hay ~ '(warehouse|inventory|receiving|stock)' THEN
    RETURN 'warehouse'::public.staff_role;
  END IF;
  IF v_hay ~ '(finance|account|bookkeep|payroll)' THEN
    RETURN 'finance'::public.staff_role;
  END IF;
  IF v_hay ~ '(^|[^a-z])hr([^a-z]|$)|human.?resource|people.?ops' THEN
    RETURN 'hr'::public.staff_role;
  END IF;
  IF v_hay ~ '(dispatch)' THEN
    RETURN 'dispatcher'::public.staff_role;
  END IF;
  IF v_hay ~ '(sales|pos|till|counter|cashier|retail)' THEN
    RETURN 'sales'::public.staff_role;
  END IF;

  -- Safe shop-floor default — never admin.
  RETURN 'sales'::public.staff_role;
END;
$_$;


--
-- Name: FUNCTION resolve_hr_onboarding_staff_role(p_payload jsonb, p_hr_role_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.resolve_hr_onboarding_staff_role(p_payload jsonb, p_hr_role_id uuid) IS 'Maps onboarding payload / organogram default / title heuristics → staff_role. Never grants admin via heuristic; admin only from explicit field + admin caller.';


--
-- Name: resolve_item_price(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_item_price(p_customer_id uuid, p_stock_item_id uuid) RETURNS TABLE(unit_price numeric, core_charge numeric, currency public.currency_code)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_list uuid;
  v_currency public.currency_code := 'USD';
  v_unit_price numeric;
  v_core_charge numeric;
  v_row_currency public.currency_code;
  v_allowed boolean := false;
BEGIN
  IF p_stock_item_id IS NULL THEN
    RAISE EXCEPTION 'stock_item_id required';
  END IF;

  IF p_customer_id IS NOT NULL THEN
    v_allowed := (
      auth.role()='service_role'
      OR public.has_staff_role(ARRAY['admin','sales']::public.staff_role[])
      OR EXISTS (
        SELECT 1 FROM public.customers c
        WHERE c.id=p_customer_id AND c.profile_id=auth.uid()
      )
    );
    IF NOT v_allowed THEN
      RAISE EXCEPTION 'not authorized to resolve customer-specific pricing';
    END IF;

    SELECT o.unit_price,COALESCE(o.core_charge,0),c.currency
    INTO v_unit_price,v_core_charge,v_row_currency
    FROM public.customer_price_overrides o
    JOIN public.customers c ON c.id=o.customer_id
    WHERE o.customer_id=p_customer_id AND o.stock_item_id=p_stock_item_id;

    IF FOUND THEN
      unit_price:=v_unit_price;
      core_charge:=v_core_charge;
      currency:=v_row_currency;
      RETURN NEXT;
      RETURN;
    END IF;

    SELECT c.price_list_id,c.currency
    INTO v_list,v_currency
    FROM public.customers c
    WHERE c.id=p_customer_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'customer not found';
    END IF;
  END IF;

  IF v_list IS NULL THEN
    SELECT pl.id,pl.currency
    INTO v_list,v_currency
    FROM public.price_lists pl
    WHERE pl.is_default AND pl.is_active
    ORDER BY pl.created_at ASC
    LIMIT 1;
  END IF;

  IF v_list IS NULL THEN
    SELECT pl.id,pl.currency
    INTO v_list,v_currency
    FROM public.price_lists pl
    WHERE pl.code='RETAIL' AND pl.is_active
    ORDER BY pl.created_at ASC
    LIMIT 1;
  END IF;

  IF v_list IS NULL THEN
    RAISE EXCEPTION 'no active public/default price list configured';
  END IF;

  SELECT pli.unit_price,COALESCE(pli.core_charge,0),pl.currency
  INTO v_unit_price,v_core_charge,v_row_currency
  FROM public.price_list_items pli
  JOIN public.price_lists pl ON pl.id=pli.price_list_id
  WHERE pli.price_list_id=v_list AND pli.stock_item_id=p_stock_item_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'no price for stock item % on price list',p_stock_item_id;
  END IF;

  unit_price:=v_unit_price;
  core_charge:=v_core_charge;
  currency:=v_row_currency;
  RETURN NEXT;
END;
$$;


--
-- Name: resolve_password_reset_user(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_password_reset_user(p_email text DEFAULT NULL::text, p_phone_e164 text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare
  v_email text := lower(trim(coalesce(p_email,'')));
  v_phone text := trim(coalesce(p_phone_e164,''));
  v_email_uid uuid;
  v_phone_uid uuid;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'service_role required';
  end if;

  if v_email <> '' then
    select u.id into v_email_uid
    from auth.users u
    where lower(u.email)=v_email
    order by u.created_at asc
    limit 1;
  end if;

  if v_phone <> '' then
    select p.id into v_phone_uid
    from public.profiles p
    where p.phone_e164=v_phone
    order by p.created_at asc
    limit 1;
  end if;

  if v_email <> '' and v_phone <> '' then
    if v_email_uid is not null and v_phone_uid is not null and v_email_uid=v_phone_uid then
      return v_email_uid;
    end if;
    return null;
  end if;

  return coalesce(v_email_uid,v_phone_uid);
end;
$$;


--
-- Name: resolve_staff_login_email(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_staff_login_email(p_identifier text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_raw TEXT;
  v_hash TEXT;
  v_recent INT;
  v_email TEXT;
  v_emp public.employees%ROWTYPE;
BEGIN
  v_raw := lower(trim(COALESCE(p_identifier, '')));
  IF v_raw = '' THEN
    RAISE EXCEPTION 'invalid credentials';
  END IF;

  v_hash := encode(extensions.digest(convert_to(v_raw, 'UTF8'), 'sha256'), 'hex');

  SELECT COUNT(*)::INT INTO v_recent
  FROM public.staff_login_resolve_attempts
  WHERE identifier_hash = v_hash
    AND attempted_at > now() - interval '15 minutes';

  IF v_recent >= 12 THEN
    RAISE EXCEPTION 'invalid credentials';
  END IF;

  -- Prefer employee_code (emp#) when no @ and not phone-like.
  IF position('@' IN v_raw) > 0 THEN
    SELECT e.* INTO v_emp
    FROM public.employees e
    WHERE e.status = 'active'
      AND (
        lower(COALESCE(e.email, '')) = v_raw
        OR EXISTS (
          SELECT 1 FROM auth.users u
          WHERE u.id = e.user_id AND lower(u.email) = v_raw
        )
      )
    LIMIT 1;
  ELSIF v_raw ~ '^\+?[0-9]{7,15}$' THEN
    SELECT e.* INTO v_emp
    FROM public.employees e
    WHERE e.status = 'active'
      AND regexp_replace(COALESCE(e.phone_e164, ''), '[^0-9+]', '', 'g')
          = regexp_replace(v_raw, '[^0-9+]', '', 'g')
    LIMIT 1;
  ELSE
    SELECT e.* INTO v_emp
    FROM public.employees e
    WHERE e.status = 'active'
      AND lower(e.employee_code) = v_raw
    LIMIT 1;
  END IF;

  IF NOT FOUND OR v_emp.user_id IS NULL THEN
    INSERT INTO public.staff_login_resolve_attempts (identifier_hash, success)
    VALUES (v_hash, false);
    RAISE EXCEPTION 'invalid credentials';
  END IF;

  SELECT lower(u.email) INTO v_email
  FROM auth.users u
  WHERE u.id = v_emp.user_id;

  IF v_email IS NULL OR v_email = '' THEN
    v_email := lower(NULLIF(trim(COALESCE(v_emp.email, '')), ''));
  END IF;

  IF v_email IS NULL OR v_email = '' THEN
    INSERT INTO public.staff_login_resolve_attempts (identifier_hash, success)
    VALUES (v_hash, false);
    RAISE EXCEPTION 'invalid credentials';
  END IF;

  INSERT INTO public.staff_login_resolve_attempts (identifier_hash, success)
  VALUES (v_hash, true);

  RETURN v_email;
END;
$_$;


--
-- Name: FUNCTION resolve_staff_login_email(p_identifier text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.resolve_staff_login_email(p_identifier text) IS 'Pre-auth staff identifier → GoTrue email. emp#|email|phone. Active employees only. Non-enumerating.';


--
-- Name: resolve_stock_item_by_oem(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_stock_item_by_oem(p_oem text) RETURNS uuid
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$ SELECT id FROM public.stock_items WHERE oem_part_number=upper(trim(p_oem)) LIMIT 1; $$;


--
-- Name: resume_pos_cart(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resume_pos_cart(p_cart_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cart public.pos_carts%ROWTYPE;
BEGIN
  PERFORM public._require_cart_mutate(p_cart_id);

  SELECT * INTO v_cart FROM public.pos_carts WHERE id = p_cart_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'cart not found: %', p_cart_id;
  END IF;
  IF v_cart.status <> 'parked' THEN
    RAISE EXCEPTION 'only parked carts can be resumed (got %)', v_cart.status;
  END IF;

  UPDATE public.pos_carts
  SET status = 'open', updated_at = now()
  WHERE id = p_cart_id;

  RETURN p_cart_id;
END;
$$;


--
-- Name: retry_pos_split_finalization(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.retry_pos_split_finalization(p_session_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE s public.pos_split_payment_sessions%ROWTYPE; o public.commerce_orders%ROWTYPE;
BEGIN
  PERFORM public._require_payments_staff();
  SELECT * INTO s FROM public.pos_split_payment_sessions WHERE id = p_session_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'split payment session not found'; END IF;
  SELECT * INTO o FROM public.commerce_orders WHERE id = s.commerce_order_id;
  IF o.cart_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.pos_carts c WHERE c.id = o.cart_id
       AND (c.created_by = auth.uid() OR public.is_pos_approver() OR public.has_staff_role(ARRAY['finance']::public.staff_role[]))) THEN
    RAISE EXCEPTION 'split payment access denied';
  END IF;
  IF s.status NOT IN ('finalization_failed', 'fully_committed') THEN
    RAISE EXCEPTION 'only a fully paid split sale that did not post can be retried (status %)', s.status;
  END IF;
  -- Back to fully_committed (or leg_pending if something is in flight) before posting again.
  UPDATE public.pos_split_payment_sessions SET status = 'fully_committed', updated_at = now() WHERE id = s.id;
  PERFORM private.refresh_pos_split_payment_session(s.id);
  IF (SELECT status FROM public.pos_split_payment_sessions WHERE id = s.id) <> 'fully_committed' THEN
    RETURN private.pos_split_payment_payload(s.id);
  END IF;
  RETURN private.finalize_pos_split_payment_session(s.id);
END $$;


--
-- Name: reverse_journal(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reverse_journal(p_entry_id uuid, p_description text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_src public.journal_entries%ROWTYPE;
  v_new_id UUID;
  v_line RECORD;
  v_desc TEXT;
BEGIN
  IF NOT (
    auth.role() = 'service_role'
    OR public.has_staff_role(ARRAY['admin', 'finance']::public.staff_role[])
  ) THEN
    RAISE EXCEPTION 'finance or admin role required';
  END IF;

  SELECT * INTO v_src FROM public.journal_entries WHERE id = p_entry_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'journal entry not found: %', p_entry_id;
  END IF;
  IF v_src.status <> 'posted' THEN
    RAISE EXCEPTION 'only posted journals can be reversed';
  END IF;
  IF public.is_period_locked(CURRENT_DATE) THEN
    RAISE EXCEPTION 'accounting period is locked for today';
  END IF;

  v_desc := COALESCE(p_description, format('Reversal of %s', COALESCE(v_src.document_number, v_src.id::text)));

  INSERT INTO public.journal_entries (
    entry_date, description, currency, exchange_rate_applied,
    status, is_reversal, reverses_entry_id, posted_by, posted_at, document_number
  )
  VALUES (
    CURRENT_DATE,
    v_desc,
    v_src.currency,
    v_src.exchange_rate_applied,
    'draft',
    true,
    v_src.id,
    auth.uid(),
    now(),
    public.next_series_value('JV-')
  )
  RETURNING id INTO v_new_id;

  FOR v_line IN
    SELECT account_code, debit, credit, currency
    FROM public.journal_entry_lines
    WHERE journal_entry_id = p_entry_id
  LOOP
    INSERT INTO public.journal_entry_lines (
      journal_entry_id, account_code, debit, credit, currency
    )
    VALUES (
      v_new_id, v_line.account_code, v_line.credit, v_line.debit, v_line.currency
    );
  END LOOP;

  RETURN public.post_journal(v_new_id);
END;
$$;


--
-- Name: reverse_loyalty_movement(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reverse_loyalty_movement(p_ledger_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row public.loyalty_ledger%ROWTYPE;
  v_rev_je UUID;
  v_ledger UUID;
  v_prior_rev UUID;
BEGIN
  PERFORM public._require_loyalty_staff();
  PERFORM public._loyalty_rpc_enter();

  SELECT * INTO v_row FROM public.loyalty_ledger WHERE id = p_ledger_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'loyalty ledger not found: %', p_ledger_id;
  END IF;
  IF v_row.movement = 'reverse' THEN
    RAISE EXCEPTION 'cannot reverse a reverse row';
  END IF;

  SELECT id INTO v_prior_rev
  FROM public.loyalty_ledger
  WHERE reverses_ledger_id = p_ledger_id
  LIMIT 1;
  IF v_prior_rev IS NOT NULL THEN
    RAISE EXCEPTION 'loyalty movement already reversed';
  END IF;

  IF v_row.journal_entry_id IS NOT NULL THEN
    v_rev_je := public.reverse_journal(
      v_row.journal_entry_id,
      format('Reversal of loyalty %s', COALESCE(v_row.document_number, p_ledger_id::text))
    );
  END IF;

  -- Undo AR application on redeem
  IF v_row.movement = 'redeem' AND v_row.sales_invoice_id IS NOT NULL THEN
    UPDATE public.sales_invoices
    SET amount_paid = GREATEST(0, amount_paid - v_row.money_value)
    WHERE id = v_row.sales_invoice_id;

    UPDATE public.customers
    SET
      open_balance = open_balance + v_row.money_value,
      updated_at = now()
    WHERE id = v_row.customer_id;
  END IF;

  v_ledger := public._append_loyalty(
    v_row.customer_id, 'reverse', v_row.points, v_row.currency,
    v_row.exchange_rate_applied, v_row.money_value,
    v_row.sales_invoice_id, v_rev_je,
    format('Reverse %s', COALESCE(v_row.document_number, p_ledger_id::text)),
    p_ledger_id
  );

  RETURN v_ledger;
END;
$$;


--
-- Name: review_customer_return(uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.review_customer_return(p_return_request_id uuid, p_approve boolean, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_req public.customer_return_requests%ROWTYPE;
BEGIN
  IF NOT (auth.role()='service_role' OR public.has_staff_role(ARRAY['admin','sales']::public.staff_role[])) THEN
    RAISE EXCEPTION 'sales or admin role required';
  END IF;
  SELECT * INTO v_req FROM public.customer_return_requests WHERE id=p_return_request_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'return request not found'; END IF;
  IF v_req.status<>'requested' THEN RAISE EXCEPTION 'only requested returns can be reviewed'; END IF;

  UPDATE public.customer_return_requests
  SET status=CASE WHEN COALESCE(p_approve,false) THEN 'approved'::public.customer_return_status ELSE 'rejected'::public.customer_return_status END,
      review_notes=p_notes,reviewed_by=auth.uid(),reviewed_at=now(),updated_at=now()
  WHERE id=p_return_request_id;
  PERFORM public.emit_domain_event(
    CASE WHEN COALESCE(p_approve,false) THEN 'return_approved' ELSE 'return_rejected' END,
    'return:review:'||p_return_request_id::text,
    jsonb_build_object('return_request_id',p_return_request_id,'approved',COALESCE(p_approve,false)),auth.uid(),NULL
  );
  RETURN p_return_request_id;
END;
$$;


--
-- Name: revoke_approval_badge(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revoke_approval_badge(p_badge_id uuid, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE b public.staff_approval_badges%ROWTYPE;
BEGIN
  PERFORM private.require_approver_admin();
  IF trim(COALESCE(p_reason, '')) = '' THEN RAISE EXCEPTION 'revocation reason required'; END IF;
  UPDATE public.staff_approval_badges SET revoked_at = now(), revoked_by = auth.uid(), revoke_reason = trim(p_reason)
  WHERE id = p_badge_id AND revoked_at IS NULL RETURNING * INTO b;
  IF b.id IS NULL THEN RAISE EXCEPTION 'active badge not found'; END IF;
  INSERT INTO public.staff_approver_admin_events(actor_id, event, employee_id, user_id, badge_id, notes)
  VALUES (auth.uid(), 'badge_revoked', b.employee_id, b.user_id, p_badge_id, trim(p_reason));
  RETURN p_badge_id;
END $$;


--
-- Name: revoke_pos_scan_session(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revoke_pos_scan_session(p_session_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_sess public.pos_scan_sessions%ROWTYPE;
BEGIN
  PERFORM public._require_sales_staff();

  SELECT * INTO v_sess
  FROM public.pos_scan_sessions
  WHERE id = p_session_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'scan session not found';
  END IF;

  IF v_sess.owner_user_id IS DISTINCT FROM auth.uid()
     AND NOT public.has_staff_role(ARRAY['admin']::public.staff_role[]) THEN
    RAISE EXCEPTION 'only session owner or admin may revoke';
  END IF;

  IF v_sess.status IN ('revoked', 'expired') THEN
    RETURN v_sess.id;
  END IF;

  UPDATE public.pos_scan_sessions
  SET status = 'revoked', revoked_at = now(), updated_at = now()
  WHERE id = p_session_id;

  RETURN p_session_id;
END;
$$;


--
-- Name: revoke_staff_role(uuid, public.staff_role); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revoke_staff_role(p_user_id uuid, p_role public.staff_role) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_canonical_role public.staff_role;
BEGIN
  IF NOT (
    auth.role() = 'service_role'
    OR public.has_staff_role(ARRAY['admin']::public.staff_role[])
  ) THEN
    RAISE EXCEPTION 'admin role required to revoke staff roles';
  END IF;

  SELECT role INTO v_canonical_role
  FROM public.canonical_staff_accounts
  WHERE user_id = p_user_id AND is_active;
  IF FOUND AND p_role = v_canonical_role THEN
    RAISE EXCEPTION 'cannot revoke authoritative canonical staff role';
  END IF;

  DELETE FROM public.staff_roles
  WHERE user_id = p_user_id AND role = p_role;
END;
$$;


--
-- Name: rollback_delivery_cost_basis_on_cancel(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rollback_delivery_cost_basis_on_cancel() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  r record;
  v_remaining numeric;
  v_fulfilled numeric;
BEGIN
  IF OLD.status IS DISTINCT FROM 'submitted'::public.delivery_note_status
     OR NEW.status IS DISTINCT FROM 'cancelled'::public.delivery_note_status THEN
    RETURN NEW;
  END IF;

  FOR r IN
    SELECT dnl.sales_invoice_line_id,dnl.qty_base,COALESCE(dnl.unit_cost,0) AS unit_cost
    FROM public.delivery_note_lines dnl
    WHERE dnl.delivery_note_id=NEW.id AND dnl.sales_invoice_line_id IS NOT NULL
  LOOP
    SELECT GREATEST(0,COALESCE(sil.cost_total_basis,0)-round(r.unit_cost*r.qty_base,4)),
           COALESCE(sil.qty_fulfilled,0)
      INTO v_remaining,v_fulfilled
    FROM public.sales_invoice_lines sil
    WHERE sil.id=r.sales_invoice_line_id
    FOR UPDATE;

    UPDATE public.sales_invoice_lines
    SET cost_total_basis=v_remaining,
        unit_cost_basis=CASE WHEN v_fulfilled>0 THEN round(v_remaining/v_fulfilled,6) ELSE NULL END
    WHERE id=r.sales_invoice_line_id;
  END LOOP;
  RETURN NEW;
END;
$$;


--
-- Name: run_due_payroll_schedules(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.run_due_payroll_schedules(p_as_of timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_sched public.hr_payslip_schedules%ROWTYPE;
  v_due_at TIMESTAMPTZ;
  v_end DATE;
  v_start DATE;
  v_run UUID;
  v_fund JSONB;
  v_results JSONB := '[]'::jsonb;
BEGIN
  IF NOT (auth.role()='service_role' OR public.has_staff_role(ARRAY['admin']::public.staff_role[])) THEN
    RAISE EXCEPTION 'service role or admin required';
  END IF;

  FOR v_sched IN
    SELECT * FROM public.hr_payslip_schedules
    WHERE is_active AND next_run_at IS NOT NULL AND next_run_at <= COALESCE(p_as_of,now())
    ORDER BY next_run_at, pay_frequency
    FOR UPDATE
  LOOP
    v_due_at := v_sched.next_run_at;
    v_end := v_due_at::date - 1;
    IF v_sched.pay_frequency='weekly' THEN
      v_start := v_end - 6;
    ELSIF v_sched.pay_frequency='fortnightly' THEN
      -- Existing canonical cron is semi-monthly (1st/15th) despite the legacy enum name.
      -- Use complete non-overlapping windows: 15th..month-end, then 1st..14th.
      IF EXTRACT(DAY FROM v_due_at)::int = 15 THEN
        v_start := date_trunc('month', v_due_at)::date;
      ELSE
        v_start := (date_trunc('month', v_due_at) - interval '1 month' + interval '14 days')::date;
      END IF;
    ELSE
      v_start := (v_due_at::date - interval '1 month')::date;
    END IF;

    BEGIN
      v_run := public.run_scheduled_payroll_for_frequency(v_sched.pay_frequency,v_start,v_end,'USD',1);
      PERFORM public.submit_payroll_run(v_run);
      v_fund := public.fund_payroll_run(v_run);
      UPDATE public.hr_payslip_schedules
      SET last_run_at=v_due_at, next_run_at=public._next_payroll_schedule_at(pay_frequency,v_due_at + interval '1 second')
      WHERE id=v_sched.id;
      v_results := v_results || jsonb_build_array(jsonb_build_object('pay_frequency',v_sched.pay_frequency,'payroll_run_id',v_run,'ok',true,'fund',v_fund));
    EXCEPTION WHEN OTHERS THEN
      v_results := v_results || jsonb_build_array(jsonb_build_object('pay_frequency',v_sched.pay_frequency,'ok',false,'error',SQLERRM));
    END;
  END LOOP;

  RETURN jsonb_build_object('as_of',COALESCE(p_as_of,now()),'results',v_results);
END;
$$;


--
-- Name: run_inventory_abc_classification(timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.run_inventory_abc_classification(p_from timestamp with time zone, p_to timestamp with time zone) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_total NUMERIC := 0;
  v_cum NUMERIC := 0;
  v_count INT := 0;
  v_as_of TIMESTAMPTZ := now();
  r RECORD;
  v_class public.inventory_abc_class;
  v_share NUMERIC;
BEGIN
  PERFORM public._assert_ai_stores_staff();
  IF p_from IS NULL OR p_to IS NULL OR p_to <= p_from THEN
    RAISE EXCEPTION 'valid p_from / p_to required';
  END IF;

  DELETE FROM public.inventory_abc_snapshots
  WHERE as_of > now() - INTERVAL '1 minute';

  SELECT COALESCE(SUM(
    sil.line_total / NULLIF(COALESCE(inv.exchange_rate_applied, 1), 0)
  ), 0)
  INTO v_total
  FROM public.sales_invoice_lines sil
  JOIN public.sales_invoices inv ON inv.id = sil.invoice_id
  WHERE inv.doc_type = 'invoice'
    AND inv.status = 'posted'
    AND inv.posted_at >= p_from
    AND inv.posted_at < p_to
    AND NOT sil.is_core_charge;

  IF v_total IS NULL OR v_total <= 0 THEN
    RETURN 0;
  END IF;

  FOR r IN
    SELECT
      si.id AS stock_item_id,
      si.oem_part_number,
      COALESCE(SUM(sil.qty_base), 0)::numeric AS qty_sold,
      COALESCE(SUM(
        sil.line_total / NULLIF(COALESCE(inv.exchange_rate_applied, 1), 0)
      ), 0)::numeric AS revenue_usd
    FROM public.sales_invoice_lines sil
    JOIN public.sales_invoices inv ON inv.id = sil.invoice_id
    JOIN public.stock_items si ON si.id = sil.stock_item_id
    WHERE inv.doc_type = 'invoice'
      AND inv.status = 'posted'
      AND inv.posted_at >= p_from
      AND inv.posted_at < p_to
      AND NOT sil.is_core_charge
    GROUP BY si.id, si.oem_part_number
    HAVING COALESCE(SUM(
      sil.line_total / NULLIF(COALESCE(inv.exchange_rate_applied, 1), 0)
    ), 0) > 0
    ORDER BY revenue_usd DESC
  LOOP
    v_share := r.revenue_usd / v_total;
    -- Class by cumulative share *before* this SKU so a single 90% seller is still A
    IF v_cum < 0.80 THEN
      v_class := 'A';
    ELSIF v_cum < 0.95 THEN
      v_class := 'B';
    ELSE
      v_class := 'C';
    END IF;
    v_cum := v_cum + v_share;

    INSERT INTO public.inventory_abc_snapshots (
      as_of, period_start, period_end, stock_item_id, oem_part_number,
      qty_sold, revenue_usd, revenue_share, cumulative_share, abc_class
    ) VALUES (
      v_as_of, p_from, p_to, r.stock_item_id, r.oem_part_number,
      r.qty_sold, r.revenue_usd, v_share, v_cum, v_class
    );
    v_count := v_count + 1;
  END LOOP;

  RETURN v_count;
END;
$$;


--
-- Name: run_scheduled_payroll_for_frequency(public.hr_pay_frequency, date, date, public.currency_code, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.run_scheduled_payroll_for_frequency(p_frequency public.hr_pay_frequency, p_period_start date, p_period_end date, p_currency public.currency_code DEFAULT 'USD'::public.currency_code, p_exchange_rate numeric DEFAULT 1) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_run UUID;
  v_emps UUID[];
BEGIN
  IF NOT (
    auth.role() = 'service_role'
    OR public.has_staff_role(ARRAY['admin', 'hr']::public.staff_role[])
  ) THEN
    RAISE EXCEPTION 'hr or admin role required';
  END IF;

  SELECT COALESCE(array_agg(e.id), ARRAY[]::UUID[])
  INTO v_emps
  FROM public.employees e
  JOIN public.hr_roles r ON r.id = e.hr_role_id
  WHERE e.status = 'active'
    AND r.is_active
    AND r.pay_frequency = p_frequency;

  IF cardinality(v_emps) = 0 THEN
    RAISE EXCEPTION 'no active employees for pay_frequency %', p_frequency;
  END IF;

  v_run := public.create_payroll_run(
    p_period_start, p_period_end, p_currency, COALESCE(p_exchange_rate, 1)
  );
  PERFORM public.compute_payroll_run(v_run, v_emps);

  UPDATE public.hr_payslip_schedules
  SET last_run_at = now()
  WHERE pay_frequency = p_frequency;

  RETURN v_run;
END;
$$;


--
-- Name: save_hr_onboarding_stage(uuid, public.hr_onboarding_stage, jsonb, jsonb, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_hr_onboarding_stage(p_draft_id uuid DEFAULT NULL::uuid, p_stage public.hr_onboarding_stage DEFAULT 'personal'::public.hr_onboarding_stage, p_payload jsonb DEFAULT '{}'::jsonb, p_banking_json jsonb DEFAULT NULL::jsonb, p_health_json jsonb DEFAULT NULL::jsonb, p_employee_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id UUID;
BEGIN
  IF NOT public.has_staff_role(ARRAY['admin', 'hr']::public.staff_role[]) THEN
    RAISE EXCEPTION 'hr or admin role required';
  END IF;

  IF p_draft_id IS NULL THEN
    INSERT INTO public.hr_onboarding_drafts (
      stage, payload, banking_json, health_json, employee_id,
      created_by, updated_by
    ) VALUES (
      p_stage,
      COALESCE(p_payload, '{}'::jsonb),
      p_banking_json,
      p_health_json,
      p_employee_id,
      auth.uid(),
      auth.uid()
    )
    RETURNING id INTO v_id;
    RETURN v_id;
  END IF;

  UPDATE public.hr_onboarding_drafts
  SET
    stage = p_stage,
    payload = COALESCE(p_payload, payload),
    banking_json = CASE
      WHEN p_banking_json IS NOT NULL THEN p_banking_json
      ELSE banking_json
    END,
    health_json = CASE
      WHEN p_health_json IS NOT NULL THEN p_health_json
      ELSE health_json
    END,
    employee_id = COALESCE(p_employee_id, employee_id),
    updated_by = auth.uid(),
    updated_at = now()
  WHERE id = p_draft_id
    AND completed_at IS NULL
  RETURNING id INTO v_id;

  IF v_id IS NULL THEN
    RAISE EXCEPTION 'onboarding draft not found or already completed: %', p_draft_id;
  END IF;
  RETURN v_id;
END;
$$;


--
-- Name: scrub_hr_credential_outbox_bodies(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.scrub_hr_credential_outbox_bodies(p_max_age_seconds integer DEFAULT 90) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_age INT := GREATEST(COALESCE(p_max_age_seconds, 90), 30);
  v_n INT := 0;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'service_role required';
  END IF;

  UPDATE public.hr_credential_outbox
  SET
    body = '[redacted — pending body window exceeded]',
    status = CASE
      WHEN status IN (
        'pending'::public.hr_credential_outbox_status,
        'sending'::public.hr_credential_outbox_status
      ) THEN 'failed'::public.hr_credential_outbox_status
      ELSE status
    END,
    last_error = CASE
      WHEN status IN (
        'pending'::public.hr_credential_outbox_status,
        'sending'::public.hr_credential_outbox_status
      ) THEN left(
        COALESCE(last_error, 'credential body scrubbed after max pending window'),
        500
      )
      ELSE last_error
    END,
    claimed_at = NULL
  WHERE body IS DISTINCT FROM '[redacted after delivery attempt]'
    AND body IS DISTINCT FROM '[redacted — pending body window exceeded]'
    AND body NOT LIKE '[redacted%'
    AND created_at < now() - make_interval(secs => v_age);

  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END;
$$;


--
-- Name: FUNCTION scrub_hr_credential_outbox_bodies(p_max_age_seconds integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.scrub_hr_credential_outbox_bodies(p_max_age_seconds integer) IS 'Redacts plaintext hr_credential_outbox.body older than p_max_age_seconds; marks stuck pending/sending as failed.';


--
-- Name: search_catalog(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_catalog(p_mode text, p_query text) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_mode text := lower(trim(p_mode));
  v_query text := trim(p_query);
  v_tsquery tsquery;
  v_vin_prefix text;
  v_results jsonb := '[]'::jsonb;
BEGIN
  IF v_query IS NULL OR v_query = '' THEN
    RETURN jsonb_build_object('mode', v_mode, 'query', v_query, 'results', v_results);
  END IF;

  IF v_mode = 'part' THEN
    v_tsquery := plainto_tsquery('simple', v_query);
    SELECT COALESCE(jsonb_agg(row_to_json(t)::jsonb ORDER BY t.oem_part_number), '[]'::jsonb)
    INTO v_results
    FROM (
      SELECT DISTINCT ON (pf.oem_part_number)
        'part'::text AS type,
        pf.oem_part_number,
        pf.pnc_code,
        pf.chassis_code,
        pf.engine_code,
        pf.superseded_by,
        pf.diagram_path,
        pc.category_name,
        pc.subcategory_name,
        xref.oe_number AS matched_oe_number,
        xref.brand AS matched_brand
      FROM public.part_fitment pf
      LEFT JOIN public.pnc_categories pc ON pc.pnc_code = pf.pnc_code
      LEFT JOIN public.oe_cross_refs xref
        ON xref.oem_part_number = pf.oem_part_number
       AND upper(xref.oe_number) = upper(v_query)
      WHERE pf.search_vector @@ v_tsquery
         OR upper(pf.oem_part_number) = upper(v_query)
         OR upper(pf.superseded_by) = upper(v_query)
         OR EXISTS (
           SELECT 1 FROM public.oe_cross_refs x
           WHERE x.oem_part_number = pf.oem_part_number
             AND upper(x.oe_number) = upper(v_query)
         )
      ORDER BY pf.oem_part_number
      LIMIT 50
    ) t;

  ELSIF v_mode = 'vin' THEN
    v_vin_prefix := upper(substring(v_query FROM 1 FOR 11));
    SELECT COALESCE(jsonb_agg(row_to_json(t)::jsonb), '[]'::jsonb)
    INTO v_results
    FROM (
      SELECT
        'vehicle'::text AS type,
        vm.vin_prefix,
        vm.model_variant,
        vm.chassis_code,
        vm.engine_code,
        vm.production_year,
        (
          SELECT COALESCE(jsonb_agg(jsonb_build_object(
            'type', 'part',
            'oem_part_number', pf.oem_part_number,
            'pnc_code', pf.pnc_code,
            'chassis_code', pf.chassis_code,
            'engine_code', pf.engine_code,
            'superseded_by', pf.superseded_by,
            'diagram_path', pf.diagram_path,
            'category_name', pc.category_name,
            'subcategory_name', pc.subcategory_name
          ) ORDER BY pf.oem_part_number), '[]'::jsonb)
          FROM public.part_fitment pf
          LEFT JOIN public.pnc_categories pc ON pc.pnc_code = pf.pnc_code
          WHERE pf.chassis_code = vm.chassis_code
            AND (vm.engine_code IS NULL OR pf.engine_code = vm.engine_code)
          LIMIT 40
        ) AS fitments
      FROM public.vehicle_master vm
      WHERE upper(coalesce(vm.vin_prefix, '')) <> ''
        AND (
          v_vin_prefix LIKE upper(vm.vin_prefix) || '%'
          OR upper(vm.vin_prefix) LIKE v_vin_prefix || '%'
        )
      LIMIT 20
    ) t;

  ELSIF v_mode = 'model' THEN
    v_tsquery := plainto_tsquery('simple', v_query);
    SELECT COALESCE(jsonb_agg(row_to_json(t)::jsonb ORDER BY t.model_variant), '[]'::jsonb)
    INTO v_results
    FROM (
      SELECT
        'vehicle'::text AS type,
        vm.vin_prefix,
        vm.model_variant,
        vm.chassis_code,
        vm.engine_code,
        vm.production_year
      FROM public.vehicle_master vm
      WHERE vm.search_vector @@ v_tsquery
         OR lower(vm.model_variant) LIKE '%' || lower(v_query) || '%'
         OR lower(coalesce(vm.chassis_code, '')) LIKE '%' || lower(v_query) || '%'
         OR lower(coalesce(vm.engine_code, '')) LIKE '%' || lower(v_query) || '%'
      ORDER BY vm.model_variant
      LIMIT 50
    ) t;

  ELSIF v_mode = 'pnc' THEN
    v_tsquery := plainto_tsquery('simple', v_query);
    SELECT COALESCE(jsonb_agg(row_to_json(t)::jsonb ORDER BY t.pnc_code), '[]'::jsonb)
    INTO v_results
    FROM (
      SELECT
        'pnc'::text AS type,
        pc.pnc_code,
        pc.category_name,
        pc.subcategory_name,
        (
          SELECT COALESCE(jsonb_agg(jsonb_build_object(
            'type', 'part',
            'oem_part_number', pf.oem_part_number,
            'pnc_code', pf.pnc_code,
            'chassis_code', pf.chassis_code,
            'engine_code', pf.engine_code,
            'superseded_by', pf.superseded_by,
            'diagram_path', pf.diagram_path
          ) ORDER BY pf.oem_part_number), '[]'::jsonb)
          FROM public.part_fitment pf
          WHERE pf.pnc_code = pc.pnc_code
          LIMIT 40
        ) AS fitments
      FROM public.pnc_categories pc
      WHERE pc.search_vector @@ v_tsquery
         OR pc.pnc_code = v_query
         OR lower(pc.category_name) LIKE '%' || lower(v_query) || '%'
         OR lower(coalesce(pc.subcategory_name, '')) LIKE '%' || lower(v_query) || '%'
      ORDER BY pc.pnc_code
      LIMIT 50
    ) t;

  ELSE
    RAISE EXCEPTION 'search_catalog: unsupported mode % (expected part|vin|model|pnc)', p_mode;
  END IF;

  RETURN jsonb_build_object('mode', v_mode, 'query', v_query, 'results', v_results);
END;
$$;


--
-- Name: FUNCTION search_catalog(p_mode text, p_query text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.search_catalog(p_mode text, p_query text) IS 'Interim 4-way catalog search via PostgreSQL FTS. Meilisearch indexing deferred.';


--
-- Name: search_pos_stock_items(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_pos_stock_items(p_query text, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_query TEXT := trim(COALESCE(p_query, ''));
  v_limit INTEGER := GREATEST(1, LEAST(COALESCE(p_limit, 50), 100));
  v_words TEXT[];
  v_results JSONB;
BEGIN
  PERFORM public._require_sales_staff();

  IF char_length(v_query) < 2 THEN
    RETURN jsonb_build_object('mode', 'part', 'query', v_query, 'results', '[]'::jsonb);
  END IF;

  -- Each word must appear in the part number or the description ("oil filter navara").
  v_words := ARRAY(
    SELECT replace(replace(replace(w, '\', '\\'), '%', '\%'), '_', '\_')
    FROM regexp_split_to_table(v_query, '\s+') AS w
    WHERE w <> ''
  );

  SELECT COALESCE(jsonb_agg(row_to_json(t)::jsonb ORDER BY t.rank, t.oem_part_number), '[]'::jsonb)
  INTO v_results
  FROM (
    SELECT
      'part'::TEXT AS type,
      si.oem_part_number::TEXT AS oem_part_number,
      si.description,
      CASE
        WHEN upper(si.oem_part_number) = upper(v_query) THEN 0
        WHEN upper(si.oem_part_number) LIKE upper(v_words[1]) || '%' THEN 1
        ELSE 2
      END AS rank
    FROM public.stock_items si
    WHERE NOT EXISTS (
      SELECT 1 FROM unnest(v_words) AS w
      WHERE NOT (
        si.oem_part_number ILIKE '%' || w || '%'
        OR COALESCE(si.description, '') ILIKE '%' || w || '%'
      )
    )
    ORDER BY rank, si.oem_part_number
    LIMIT v_limit
  ) t;

  RETURN jsonb_build_object('mode', 'part', 'query', v_query, 'results', v_results);
END;
$$;


--
-- Name: FUNCTION search_pos_stock_items(p_query text, p_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.search_pos_stock_items(p_query text, p_limit integer) IS 'POS counter search over stock_items by part number and description words (sales/warehouse/admin). Merged client-side with search_catalog part hits.';


--
-- Name: search_pos_vehicle_spares(text, text, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_pos_vehicle_spares(p_model_slug text, p_chassis_code text, p_engine_code text, p_query text, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_query text := trim(COALESCE(p_query, ''));
  v_limit integer := GREATEST(1, LEAST(COALESCE(p_limit, 50), 100));
  v_results jsonb;
BEGIN
  PERFORM public._require_sales_staff();
  IF NOT EXISTS (
    SELECT 1 FROM public.catalog_variants v
    WHERE v.maker_slug = 'nissan'
      AND v.model_slug = trim(p_model_slug)
      AND v.chassis_code = trim(p_chassis_code)
      AND v.engine_code = trim(p_engine_code)
  ) THEN
    RAISE EXCEPTION 'vehicle selection is not present in Nissan catalog';
  END IF;

  SELECT COALESCE(jsonb_agg(row_to_json(t)::jsonb ORDER BY t.oem_part_number), '[]'::jsonb)
  INTO v_results
  FROM (
    SELECT DISTINCT ON (pf.oem_part_number)
      'part'::text AS type,
      pf.oem_part_number,
      si.description,
      pf.pnc_code,
      pc.category_name,
      pc.subcategory_name,
      pf.chassis_code,
      pf.engine_code
    FROM public.part_fitment pf
    LEFT JOIN public.stock_items si ON si.oem_part_number = pf.oem_part_number
    LEFT JOIN public.pnc_categories pc ON pc.pnc_code = pf.pnc_code
    WHERE pf.chassis_code = trim(p_chassis_code)
      AND (pf.engine_code IS NULL OR pf.engine_code = trim(p_engine_code))
      AND (
        v_query = ''
        OR pf.oem_part_number ILIKE '%' || v_query || '%'
        OR COALESCE(si.description, '') ILIKE '%' || v_query || '%'
        OR COALESCE(pf.pnc_code, '') ILIKE '%' || v_query || '%'
        OR COALESCE(pc.category_name, '') ILIKE '%' || v_query || '%'
        OR COALESCE(pc.subcategory_name, '') ILIKE '%' || v_query || '%'
        OR COALESCE(pf.superseded_by, '') ILIKE '%' || v_query || '%'
      )
    ORDER BY pf.oem_part_number, (pf.engine_code = trim(p_engine_code)) DESC
    LIMIT v_limit
  ) t;

  RETURN jsonb_build_object(
    'mode', 'part',
    'query', v_query,
    'vehicle', jsonb_build_object(
      'model_slug', trim(p_model_slug),
      'chassis_code', trim(p_chassis_code),
      'engine_code', trim(p_engine_code)
    ),
    'results', v_results
  );
END;
$$;


--
-- Name: FUNCTION search_pos_vehicle_spares(p_model_slug text, p_chassis_code text, p_engine_code text, p_query text, p_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.search_pos_vehicle_spares(p_model_slug text, p_chassis_code text, p_engine_code text, p_query text, p_limit integer) IS 'Fitment-scoped POS spare search for selected Nissan model/chassis/engine.';


--
-- Name: send_pos_quotation(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.send_pos_quotation(p_quotation_id uuid, p_channel text, p_contact text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_q public.pos_quotations%ROWTYPE;
  v_channel TEXT;
BEGIN
  PERFORM public._require_sales_staff();
  v_channel := lower(trim(COALESCE(p_channel, '')));
  IF v_channel NOT IN ('print', 'email', 'sms', 'whatsapp') THEN
    RAISE EXCEPTION 'channel must be print|email|sms|whatsapp';
  END IF;

  SELECT * INTO v_q FROM public.pos_quotations WHERE id = p_quotation_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'quotation not found: %', p_quotation_id;
  END IF;
  IF v_q.status NOT IN ('issued', 'sent') THEN
    RAISE EXCEPTION 'only issued/sent quotations can be sent (got %)', v_q.status;
  END IF;
  IF v_channel <> 'print'
     AND nullif(trim(COALESCE(p_contact, '')), '') IS NULL THEN
    RAISE EXCEPTION 'contact required for channel %', v_channel;
  END IF;

  UPDATE public.pos_quotations
  SET
    status = 'sent',
    sent_at = now(),
    sent_channel = v_channel,
    sent_contact = nullif(trim(COALESCE(p_contact, '')), ''),
    updated_at = now()
  WHERE id = p_quotation_id;

  PERFORM public._log_pos_action(
    'quotation_sent',
    'pos_quotations',
    p_quotation_id,
    jsonb_build_object('status', v_q.status),
    jsonb_build_object('status', 'sent', 'channel', v_channel, 'contact', p_contact),
    NULL
  );

  RETURN p_quotation_id;
END;
$$;


--
-- Name: set_approver_assignment(uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_approver_assignment(p_employee_id uuid, p_assigned boolean, p_notes text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  PERFORM private.require_approver_admin();
  IF NOT EXISTS (SELECT 1 FROM public.employees e WHERE e.id = p_employee_id AND e.status = 'active') THEN
    RAISE EXCEPTION 'active employee required';
  END IF;
  IF p_assigned THEN
    INSERT INTO public.staff_approver_assignments(employee_id, granted_by, notes) VALUES (p_employee_id, auth.uid(), p_notes)
    ON CONFLICT (employee_id) DO UPDATE SET granted_by = auth.uid(), granted_at = now(), notes = p_notes, revoked_at = NULL, revoked_by = NULL;
  ELSE
    UPDATE public.staff_approver_assignments SET revoked_at = now(), revoked_by = auth.uid() WHERE employee_id = p_employee_id AND revoked_at IS NULL;
  END IF;
  INSERT INTO public.staff_approver_admin_events(actor_id, event, employee_id, notes)
  VALUES (auth.uid(), CASE WHEN p_assigned THEN 'assigned' ELSE 'unassigned' END, p_employee_id, p_notes);
  RETURN p_assigned;
END $$;


--
-- Name: set_branch_reorder_point(uuid, uuid, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_branch_reorder_point(p_stock_item_id uuid, p_warehouse_id uuid, p_reorder_point numeric, p_reorder_qty numeric DEFAULT NULL::numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
 IF NOT (public.has_staff_role(ARRAY['admin','finance','warehouse']::public.staff_role[]) OR public.is_pos_approver()) THEN
  RAISE EXCEPTION 'warehouse, finance, manager or admin required';
 END IF;
 IF p_reorder_point IS NULL THEN
  DELETE FROM public.stock_reorder_points WHERE stock_item_id=p_stock_item_id AND warehouse_id=p_warehouse_id;
  RETURN jsonb_build_object('stock_item_id', p_stock_item_id, 'warehouse_id', p_warehouse_id, 'reorder_point', NULL);
 END IF;
 IF p_reorder_point < 0 OR (p_reorder_qty IS NOT NULL AND p_reorder_qty <= 0) THEN RAISE EXCEPTION 'reorder point must be 0 or more, reorder quantity more than 0'; END IF;
 INSERT INTO public.stock_reorder_points(stock_item_id, warehouse_id, reorder_point, reorder_qty, updated_by, updated_at)
 VALUES (p_stock_item_id, p_warehouse_id, p_reorder_point, p_reorder_qty, auth.uid(), now())
 ON CONFLICT (stock_item_id, warehouse_id) DO UPDATE SET reorder_point=EXCLUDED.reorder_point, reorder_qty=EXCLUDED.reorder_qty, updated_by=auth.uid(), updated_at=now();
 RETURN jsonb_build_object('stock_item_id', p_stock_item_id, 'warehouse_id', p_warehouse_id, 'reorder_point', p_reorder_point, 'reorder_qty', p_reorder_qty);
END $$;


--
-- Name: set_business_document_profile(text, text, text, text, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_business_document_profile(p_legal_name text, p_trading_name text, p_domain text, p_city text DEFAULT NULL::text, p_country text DEFAULT NULL::text, p_address_line1 text DEFAULT NULL::text, p_address_line2 text DEFAULT NULL::text, p_phone_e164 text DEFAULT NULL::text, p_email text DEFAULT NULL::text, p_registration_number text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
 IF NOT public.has_staff_role(ARRAY['admin']::public.staff_role[]) THEN RAISE EXCEPTION 'admin role required'; END IF;
 UPDATE public.business_document_profile SET legal_name=trim(p_legal_name),trading_name=trim(p_trading_name),domain=trim(p_domain),
  city=NULLIF(trim(COALESCE(p_city,'')),''),country=NULLIF(trim(COALESCE(p_country,'')),''),address_line1=NULLIF(trim(COALESCE(p_address_line1,'')),''),
  address_line2=NULLIF(trim(COALESCE(p_address_line2,'')),''),phone_e164=NULLIF(trim(COALESCE(p_phone_e164,'')),''),email=NULLIF(trim(COALESCE(p_email,'')),''),
  registration_number=NULLIF(trim(COALESCE(p_registration_number,'')),''),updated_by=auth.uid(),updated_at=now() WHERE singleton=true;
 RETURN (SELECT to_jsonb(x) FROM public.business_document_profile x WHERE singleton=true);
END $$;


--
-- Name: set_customer_cart_delivery_payment_method(uuid, public.delivery_payment_method); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_customer_cart_delivery_payment_method(p_cart_id uuid, p_method public.delivery_payment_method) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE c public.pos_carts%ROWTYPE;
BEGIN
 PERFORM public._storefront_rpc_enter();
 SELECT * INTO c FROM public.pos_carts WHERE id=p_cart_id FOR UPDATE;
 IF NOT FOUND OR c.status<>'open' THEN RAISE EXCEPTION 'open cart required'; END IF;
 PERFORM public._assert_customer_owns_open_cart(p_cart_id);
 IF c.fulfillment_mode<>'dispatch' AND p_method<>'prepay' THEN RAISE EXCEPTION 'pay-on-delivery is available only for dispatch orders'; END IF;
 UPDATE public.pos_carts SET delivery_payment_method=p_method,updated_at=now() WHERE id=c.id;
 RETURN c.id;
END $$;


--
-- Name: set_customer_cart_line_qty(uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_customer_cart_line_qty(p_line_id uuid, p_qty numeric) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cart_id uuid;
  v_result uuid;
BEGIN
  SELECT cart_id INTO v_cart_id
  FROM public.pos_cart_lines
  WHERE id = p_line_id;
  IF v_cart_id IS NULL THEN
    RAISE EXCEPTION 'cart line not found';
  END IF;

  PERFORM public._storefront_rpc_enter();
  BEGIN
    PERFORM public._assert_customer_owns_open_cart(v_cart_id);
    v_result := public.set_pos_cart_line_qty(p_line_id, p_qty);
  EXCEPTION
    WHEN OTHERS THEN
      PERFORM public._storefront_rpc_exit();
      RAISE;
  END;
  PERFORM public._storefront_rpc_exit();
  RETURN v_result;
END;
$$;


--
-- Name: set_customer_credit(uuid, numeric, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_customer_credit(p_customer_id uuid, p_credit_limit numeric DEFAULT NULL::numeric, p_credit_hold boolean DEFAULT NULL::boolean) RETURNS TABLE(customer_id uuid, credit_limit numeric, credit_hold boolean, open_balance numeric, currency public.currency_code, credit_limit_minor bigint, open_balance_minor bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_limit NUMERIC;
  v_hold BOOLEAN;
BEGIN
  IF NOT public.has_staff_role(ARRAY['admin', 'sales', 'finance']::public.staff_role[]) THEN
    RAISE EXCEPTION 'admin, sales, or finance role required to set customer credit';
  END IF;
  IF p_customer_id IS NULL THEN
    RAISE EXCEPTION 'customer_id required';
  END IF;
  IF p_credit_limit IS NULL AND p_credit_hold IS NULL THEN
    RAISE EXCEPTION 'provide p_credit_limit and/or p_credit_hold';
  END IF;
  IF p_credit_limit IS NOT NULL AND p_credit_limit < 0 THEN
    RAISE EXCEPTION 'credit_limit must be >= 0';
  END IF;

  SELECT c.credit_limit, c.credit_hold
  INTO v_limit, v_hold
  FROM public.customers c
  WHERE c.id = p_customer_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'customer not found';
  END IF;

  v_limit := COALESCE(p_credit_limit, v_limit);
  v_hold := COALESCE(p_credit_hold, v_hold);

  UPDATE public.customers c
  SET
    credit_limit = v_limit,
    credit_hold = v_hold,
    updated_at = now()
  WHERE c.id = p_customer_id;

  RETURN QUERY
  SELECT
    c.id,
    c.credit_limit,
    c.credit_hold,
    c.open_balance,
    c.currency,
    c.credit_limit_minor,
    c.open_balance_minor
  FROM public.customers c
  WHERE c.id = p_customer_id;
END;
$$;


--
-- Name: FUNCTION set_customer_credit(p_customer_id uuid, p_credit_limit numeric, p_credit_hold boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.set_customer_credit(p_customer_id uuid, p_credit_limit numeric, p_credit_hold boolean) IS 'Staff-only credit_limit / credit_hold mutator. Returns majors + *_minor for dual-read (B-MONEY-1).';


--
-- Name: set_customer_marketing_opt_in(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_customer_marketing_opt_in(p_customer_id uuid, p_opt_in boolean) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id UUID;
BEGIN
  IF NOT public.has_staff_role(ARRAY['admin', 'sales', 'hr']::public.staff_role[]) THEN
    RAISE EXCEPTION 'admin, sales, or hr role required';
  END IF;

  UPDATE public.customers
  SET marketing_opt_in = COALESCE(p_opt_in, false),
      updated_at = now()
  WHERE id = p_customer_id
  RETURNING id INTO v_id;

  IF v_id IS NULL THEN
    RAISE EXCEPTION 'customer not found: %', p_customer_id;
  END IF;
  RETURN v_id;
END;
$$;


--
-- Name: set_delivery_job_geo(uuid, double precision, double precision, double precision, double precision); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_delivery_job_geo(p_delivery_job_id uuid, p_pickup_lat double precision DEFAULT NULL::double precision, p_pickup_lng double precision DEFAULT NULL::double precision, p_dropoff_lat double precision DEFAULT NULL::double precision, p_dropoff_lng double precision DEFAULT NULL::double precision) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_job public.delivery_jobs%ROWTYPE;
BEGIN
  PERFORM public._logistics_begin_rpc();
  PERFORM public._require_dispatcher_staff();

  IF p_delivery_job_id IS NULL THEN
    RAISE EXCEPTION 'delivery_job_id required';
  END IF;

  -- Pair integrity: lat/lng must both be null or both set
  IF (p_pickup_lat IS NULL) <> (p_pickup_lng IS NULL) THEN
    RAISE EXCEPTION 'pickup_lat and pickup_lng must both be set or both null';
  END IF;
  IF (p_dropoff_lat IS NULL) <> (p_dropoff_lng IS NULL) THEN
    RAISE EXCEPTION 'dropoff_lat and dropoff_lng must both be set or both null';
  END IF;

  IF p_pickup_lat IS NOT NULL AND (p_pickup_lat < -90 OR p_pickup_lat > 90) THEN
    RAISE EXCEPTION 'pickup_lat out of range';
  END IF;
  IF p_pickup_lng IS NOT NULL AND (p_pickup_lng < -180 OR p_pickup_lng > 180) THEN
    RAISE EXCEPTION 'pickup_lng out of range';
  END IF;
  IF p_dropoff_lat IS NOT NULL AND (p_dropoff_lat < -90 OR p_dropoff_lat > 90) THEN
    RAISE EXCEPTION 'dropoff_lat out of range';
  END IF;
  IF p_dropoff_lng IS NOT NULL AND (p_dropoff_lng < -180 OR p_dropoff_lng > 180) THEN
    RAISE EXCEPTION 'dropoff_lng out of range';
  END IF;

  SELECT * INTO v_job FROM public.delivery_jobs WHERE id = p_delivery_job_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'delivery job not found';
  END IF;
  IF v_job.status IN ('completed', 'failed') THEN
    RAISE EXCEPTION 'cannot set geo on terminal delivery job (status=%)', v_job.status;
  END IF;

  UPDATE public.delivery_jobs
  SET
    pickup_lat = p_pickup_lat,
    pickup_lng = p_pickup_lng,
    dropoff_lat = p_dropoff_lat,
    dropoff_lng = p_dropoff_lng,
    updated_at = now()
  WHERE id = p_delivery_job_id;

  RETURN p_delivery_job_id;
END;
$$;


--
-- Name: FUNCTION set_delivery_job_geo(p_delivery_job_id uuid, p_pickup_lat double precision, p_pickup_lng double precision, p_dropoff_lat double precision, p_dropoff_lng double precision); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.set_delivery_job_geo(p_delivery_job_id uuid, p_pickup_lat double precision, p_pickup_lng double precision, p_dropoff_lat double precision, p_dropoff_lng double precision) IS 'Dispatcher/admin/warehouse: set pickup/dropoff coords for suggest + ETA. Null pair clears that endpoint. Blocked on terminal jobs.';


--
-- Name: set_driver_presence(public.driver_presence_status, integer, timestamp with time zone, timestamp with time zone, double precision, double precision); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_driver_presence(p_status public.driver_presence_status, p_capacity integer DEFAULT NULL::integer, p_shift_starts_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_shift_ends_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_last_lat double precision DEFAULT NULL::double precision, p_last_lng double precision DEFAULT NULL::double precision) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'authentication required';
  END IF;

  IF NOT (
    auth.role() = 'service_role'
    OR public.has_staff_role(ARRAY['driver']::public.staff_role[])
  ) THEN
    RAISE EXCEPTION 'driver role required to set presence';
  END IF;

  IF p_capacity IS NOT NULL AND p_capacity < 0 THEN
    RAISE EXCEPTION 'capacity must be >= 0';
  END IF;

  INSERT INTO public.driver_presence AS dp (
    user_id, status, capacity, shift_starts_at, shift_ends_at,
    last_lat, last_lng, last_seen_at, updated_at
  )
  VALUES (
    v_uid,
    p_status,
    COALESCE(p_capacity, 1),
    p_shift_starts_at,
    p_shift_ends_at,
    p_last_lat,
    p_last_lng,
    CASE WHEN p_last_lat IS NOT NULL THEN now() ELSE NULL END,
    now()
  )
  ON CONFLICT (user_id) DO UPDATE
  SET
    status = EXCLUDED.status,
    capacity = COALESCE(p_capacity, dp.capacity),
    shift_starts_at = COALESCE(p_shift_starts_at, dp.shift_starts_at),
    shift_ends_at = COALESCE(p_shift_ends_at, dp.shift_ends_at),
    last_lat = COALESCE(p_last_lat, dp.last_lat),
    last_lng = COALESCE(p_last_lng, dp.last_lng),
    last_seen_at = CASE
      WHEN p_last_lat IS NOT NULL THEN now()
      ELSE dp.last_seen_at
    END,
    updated_at = now();

  RETURN v_uid;
END;
$$;


--
-- Name: set_finance_requisition_lines(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_finance_requisition_lines(p_requisition_id uuid, p_lines jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row public.finance_requisitions%ROWTYPE;
  v_elem JSONB;
  v_line_no INT := 0;
  v_total NUMERIC(18, 2) := 0;
  v_first_expense VARCHAR(10);
  v_desc TEXT;
  v_expense VARCHAR(10);
  v_amount NUMERIC;
BEGIN
  SELECT * INTO v_row
  FROM public.finance_requisitions
  WHERE id = p_requisition_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'requisition not found: %', p_requisition_id;
  END IF;

  IF NOT (
    auth.role() = 'service_role'
    OR public.has_staff_role(ARRAY['admin', 'finance']::public.staff_role[])
    OR v_row.requested_by = auth.uid()
  ) THEN
    RAISE EXCEPTION 'not allowed to edit this requisition';
  END IF;

  IF v_row.status <> 'draft' THEN
    RAISE EXCEPTION 'only draft requisitions can change lines (status=%)', v_row.status;
  END IF;

  IF p_lines IS NULL OR jsonb_typeof(p_lines) <> 'array' OR jsonb_array_length(p_lines) < 1 THEN
    RAISE EXCEPTION 'at least one requisition line is required';
  END IF;

  PERFORM public._finance_req_rpc_enter();

  DELETE FROM public.finance_requisition_lines WHERE requisition_id = p_requisition_id;

  FOR v_elem IN SELECT * FROM jsonb_array_elements(p_lines)
  LOOP
    v_line_no := v_line_no + 1;
    v_expense := nullif(trim(COALESCE(v_elem->>'expense_account_code', '')), '');
    v_amount := (v_elem->>'amount')::NUMERIC;
    v_desc := nullif(trim(COALESCE(v_elem->>'description', '')), '');

    IF v_expense IS NULL THEN
      RAISE EXCEPTION 'line %: expense_account_code required', v_line_no;
    END IF;
    IF v_amount IS NULL OR v_amount <= 0 THEN
      RAISE EXCEPTION 'line %: amount must be > 0', v_line_no;
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM public.chart_of_accounts c
      WHERE c.code = v_expense AND c.is_active
    ) THEN
      RAISE EXCEPTION 'line %: expense account not found: %', v_line_no, v_expense;
    END IF;

    IF v_first_expense IS NULL THEN
      v_first_expense := v_expense;
    END IF;
    v_total := v_total + v_amount;

    INSERT INTO public.finance_requisition_lines (
      requisition_id, line_no, description, expense_account_code, amount
    ) VALUES (
      p_requisition_id, v_line_no, v_desc, v_expense, v_amount
    );
  END LOOP;

  UPDATE public.finance_requisitions
  SET
    amount = v_total,
    expense_account_code = v_first_expense,
    updated_at = now()
  WHERE id = p_requisition_id;

  RETURN p_requisition_id;
END;
$$;


--
-- Name: set_fleet_vehicle_status(uuid, public.fleet_vehicle_status); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_fleet_vehicle_status(p_id uuid, p_status public.fleet_vehicle_status) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id UUID;
BEGIN
  PERFORM public._fleet_begin_rpc();
  PERFORM public._require_fleet_staff();

  IF p_status IS NULL THEN
    RAISE EXCEPTION 'status is required';
  END IF;

  UPDATE public.fleet_vehicles
  SET status = p_status
  WHERE id = p_id
  RETURNING id INTO v_id;

  IF v_id IS NULL THEN
