  END IF;

  RETURN v_id;
END;
$$;


--
-- Name: set_loyalty_program_settings(numeric, numeric, public.currency_code, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_loyalty_program_settings(p_points_per_currency_unit numeric DEFAULT NULL::numeric, p_liability_per_point numeric DEFAULT NULL::numeric, p_currency public.currency_code DEFAULT NULL::public.currency_code, p_is_active boolean DEFAULT NULL::boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT (
    auth.role() = 'service_role'
    OR public.has_staff_role(ARRAY['admin', 'finance']::public.staff_role[])
  ) THEN
    RAISE EXCEPTION 'admin or finance role required to update loyalty settings';
  END IF;

  PERFORM public._loyalty_rpc_enter();

