--
-- Name: set_pos_cart_customer(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_pos_cart_customer(p_cart_id uuid, p_customer_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM public._require_sales_staff();
  IF p_customer_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.customers WHERE id = p_customer_id) THEN
    RAISE EXCEPTION 'customer not found';
  END IF;
  UPDATE public.pos_carts
  SET customer_id = p_customer_id, updated_at = now()
  WHERE id = p_cart_id AND status = 'open';
  IF NOT FOUND THEN RAISE EXCEPTION 'open cart not found'; END IF;
  RETURN p_cart_id;
END;
$$;


--
-- Name: FUNCTION set_pos_cart_customer(p_cart_id uuid, p_customer_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.set_pos_cart_customer(p_cart_id uuid, p_customer_id uuid) IS 'Changes named customer on an open POS cart without recreating sale lines.';


--
-- Name: set_pos_cart_line_qty(uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_pos_cart_line_qty(p_line_id uuid, p_qty numeric) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_line public.pos_cart_lines%ROWTYPE;
  v_cart public.pos_carts%ROWTYPE;
  v_child public.pos_cart_lines%ROWTYPE;
  v_child_qty numeric;
  v_component_per_kit numeric;
  v_before jsonb;
  v_after jsonb;
BEGIN
  IF p_line_id IS NULL THEN
    RAISE EXCEPTION 'line_id required';
  END IF;
  IF p_qty IS NULL OR p_qty < 0 THEN
    RAISE EXCEPTION 'qty must be >= 0';
  END IF;

  SELECT * INTO v_line
  FROM public.pos_cart_lines
  WHERE id = p_line_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'cart line not found';
  END IF;
  IF v_line.parent_line_id IS NOT NULL OR v_line.is_core_charge OR v_line.kit_line_kind = 'component' THEN
    RAISE EXCEPTION 'dependent cart lines cannot be edited directly';
  END IF;
  IF COALESCE(v_line.qty_fulfilled, 0) <> 0 THEN
    RAISE EXCEPTION 'fulfilled cart line cannot be edited';
  END IF;

  PERFORM public._require_cart_mutate(v_line.cart_id);

  SELECT * INTO v_cart
  FROM public.pos_carts
  WHERE id = v_line.cart_id
  FOR UPDATE;

  IF NOT FOUND OR v_cart.status <> 'open' THEN
    RAISE EXCEPTION 'owned open cart required';
  END IF;
  IF v_cart.checkout_order_id IS NOT NULL THEN
    RAISE EXCEPTION 'cart is locked by checkout; cancel or expire the reservation before editing';
  END IF;

  SELECT jsonb_build_object(
    'line', to_jsonb(v_line),
    'children', COALESCE(jsonb_agg(to_jsonb(c) ORDER BY c.created_at) FILTER (WHERE c.id IS NOT NULL), '[]'::jsonb)
  )
  INTO v_before
  FROM public.pos_cart_lines c
  WHERE c.parent_line_id = v_line.id;

  IF p_qty = 0 THEN
    DELETE FROM public.pos_cart_lines WHERE parent_line_id = v_line.id;
    DELETE FROM public.pos_cart_lines WHERE id = v_line.id;
    UPDATE public.pos_carts SET updated_at = now() WHERE id = v_line.cart_id;

    PERFORM public._log_pos_action(
      'cart_line_removed',
      'pos_cart_lines',
      v_line.id,
      v_before,
      jsonb_build_object('removed', true),
      NULL
    );
    RETURN v_line.id;
  END IF;

  UPDATE public.pos_cart_lines
  SET qty = p_qty,
      qty_base = public.convert_to_base_uom(v_line.stock_item_id, v_line.uom_id, p_qty),
      line_total = round(v_line.unit_price * p_qty, 2)
  WHERE id = v_line.id;

  FOR v_child IN
    SELECT *
    FROM public.pos_cart_lines
    WHERE parent_line_id = v_line.id
    ORDER BY created_at
    FOR UPDATE
  LOOP
    IF v_child.is_core_charge THEN
      v_child_qty := p_qty;
    ELSIF v_child.kit_line_kind = 'component' THEN
      SELECT kc.qty
      INTO v_component_per_kit
      FROM public.item_kit_components kc
      WHERE kc.kit_id = v_line.kit_id
        AND kc.component_item_id = v_child.stock_item_id
        AND kc.uom_id = v_child.uom_id
      ORDER BY kc.created_at
      LIMIT 1;

      IF v_component_per_kit IS NULL OR v_component_per_kit <= 0 THEN
        RAISE EXCEPTION 'kit BOM mismatch for dependent component %', v_child.id;
      END IF;
      v_child_qty := v_component_per_kit * p_qty;
    ELSE
      RAISE EXCEPTION 'unexpected dependent cart line %', v_child.id;
    END IF;

    UPDATE public.pos_cart_lines
    SET qty = v_child_qty,
        qty_base = public.convert_to_base_uom(v_child.stock_item_id, v_child.uom_id, v_child_qty),
        line_total = round(v_child.unit_price * v_child_qty, 2)
    WHERE id = v_child.id;
  END LOOP;

  UPDATE public.pos_carts SET updated_at = now() WHERE id = v_line.cart_id;

  SELECT jsonb_build_object(
    'line', to_jsonb(l),
    'children', COALESCE(jsonb_agg(to_jsonb(c) ORDER BY c.created_at) FILTER (WHERE c.id IS NOT NULL), '[]'::jsonb)
  )
  INTO v_after
  FROM public.pos_cart_lines l
  LEFT JOIN public.pos_cart_lines c ON c.parent_line_id = l.id
  WHERE l.id = v_line.id
  GROUP BY l.id;

  PERFORM public._log_pos_action(
    'cart_line_qty_changed',
    'pos_cart_lines',
    v_line.id,
    v_before,
    v_after,
    NULL
  );

  RETURN v_line.id;
END;
$$;


--
-- Name: set_pos_cart_vehicle(uuid, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_pos_cart_vehicle(p_cart_id uuid, p_model_slug text DEFAULT NULL::text, p_model_name text DEFAULT NULL::text, p_generation text DEFAULT NULL::text, p_chassis_code text DEFAULT NULL::text, p_engine_code text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_model_slug text := NULLIF(trim(p_model_slug), '');
  v_model_name text := NULLIF(trim(p_model_name), '');
  v_generation text := NULLIF(trim(p_generation), '');
  v_chassis text := NULLIF(trim(p_chassis_code), '');
  v_engine text := NULLIF(trim(p_engine_code), '');
  v_context jsonb;
BEGIN
  PERFORM public._require_sales_staff();
  IF NOT EXISTS (SELECT 1 FROM public.pos_carts WHERE id = p_cart_id AND status = 'open') THEN
    RAISE EXCEPTION 'open cart not found';
  END IF;

  IF v_model_slug IS NOT NULL THEN
    IF v_chassis IS NULL OR v_engine IS NULL THEN
      RAISE EXCEPTION 'model, generation/chassis and engine are required together';
    END IF;
    IF NOT EXISTS (
      SELECT 1
      FROM public.catalog_models m
      JOIN public.catalog_variants v
        ON v.maker_slug = m.maker_slug AND v.model_slug = m.slug
      WHERE m.maker_slug = 'nissan'
        AND m.slug = v_model_slug
        AND v.chassis_code = v_chassis
        AND v.engine_code = v_engine
    ) THEN
      RAISE EXCEPTION 'selected Nissan model/generation/engine is not in the catalog';
    END IF;

    v_context := jsonb_build_object(
      'model_slug', v_model_slug,
      'model_name', v_model_name,
      'generation', v_generation,
      'chassis_code', v_chassis,
      'engine_code', v_engine
    );
  END IF;

  UPDATE public.pos_carts c
  SET vehicle_model_slug = v_model_slug,
      vehicle_model_name = CASE WHEN v_model_slug IS NULL THEN NULL ELSE v_model_name END,
      vehicle_generation = CASE WHEN v_model_slug IS NULL THEN NULL ELSE v_generation END,
      vehicle_chassis_code = CASE WHEN v_model_slug IS NULL THEN NULL ELSE v_chassis END,
      vehicle_engine_code = CASE WHEN v_model_slug IS NULL THEN NULL ELSE v_engine END,
      vehicle_contexts = CASE
        WHEN v_context IS NULL THEN c.vehicle_contexts
        WHEN EXISTS (
          SELECT 1 FROM jsonb_array_elements(COALESCE(c.vehicle_contexts, '[]'::jsonb)) e
          WHERE e->>'model_slug' = v_model_slug
            AND e->>'chassis_code' = v_chassis
            AND e->>'engine_code' = v_engine
        ) THEN c.vehicle_contexts
        ELSE COALESCE(c.vehicle_contexts, '[]'::jsonb) || jsonb_build_array(v_context)
      END,
      updated_at = now()
  WHERE c.id = p_cart_id;

  RETURN p_cart_id;
END;
$$;


--
-- Name: FUNCTION set_pos_cart_vehicle(p_cart_id uuid, p_model_slug text, p_model_name text, p_generation text, p_chassis_code text, p_engine_code text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.set_pos_cart_vehicle(p_cart_id uuid, p_model_slug text, p_model_name text, p_generation text, p_chassis_code text, p_engine_code text) IS 'Set/clear active Nissan fitment while append-preserving unique multi-vehicle sale history.';


--
-- Name: set_stock_item_primary_image(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_stock_item_primary_image(p_image_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_item UUID; BEGIN IF NOT public.has_staff_role(ARRAY['admin','sales','warehouse']::public.staff_role[]) THEN RAISE EXCEPTION 'staff role required'; END IF; SELECT stock_item_id INTO v_item FROM public.stock_item_images WHERE id=p_image_id; IF v_item IS NULL THEN RAISE EXCEPTION 'image not found'; END IF; UPDATE public.stock_item_images SET is_primary=false WHERE stock_item_id=v_item AND is_primary; UPDATE public.stock_item_images SET is_primary=true WHERE id=p_image_id; RETURN p_image_id; END;$$;


--
-- Name: set_stock_level_bin(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_stock_level_bin(p_stock_item_id uuid, p_warehouse_id uuid, p_bin_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id UUID;
BEGIN
  PERFORM public._require_warehouse_staff();
  PERFORM public._assert_bin_in_warehouse(p_bin_id, p_warehouse_id);

  UPDATE public.stock_levels
  SET bin_id = p_bin_id, updated_at = now()
  WHERE stock_item_id = p_stock_item_id AND warehouse_id = p_warehouse_id
  RETURNING id INTO v_id;

  IF v_id IS NULL THEN
    RAISE EXCEPTION 'stock level not found for item % warehouse %',
      p_stock_item_id, p_warehouse_id;
  END IF;

  RETURN v_id;
END;
$$;


--
-- Name: set_storefront_home_carousel(uuid, smallint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_storefront_home_carousel(p_stock_item_id uuid, p_rank smallint, p_caption text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caption text := NULLIF(trim(COALESCE(p_caption, '')), '');
BEGIN
  IF NOT public.has_staff_role(ARRAY['admin', 'sales']::public.staff_role[]) THEN
    RAISE EXCEPTION 'admin or sales role required';
  END IF;
  IF p_stock_item_id IS NULL
     OR NOT EXISTS (SELECT 1 FROM public.stock_items WHERE id = p_stock_item_id) THEN
    RAISE EXCEPTION 'unknown stock_item_id';
  END IF;
  IF p_rank IS NOT NULL AND (p_rank < 1 OR p_rank > 12) THEN
    RAISE EXCEPTION 'carousel position must be 1..12';
  END IF;
  IF v_caption IS NOT NULL AND char_length(v_caption) > 120 THEN
    RAISE EXCEPTION 'caption must be 120 characters or fewer';
  END IF;

  INSERT INTO public.stock_item_shop_merch (
    stock_item_id, home_carousel_rank, home_carousel_caption, updated_at, updated_by
  ) VALUES (
    p_stock_item_id, p_rank, CASE WHEN p_rank IS NULL THEN NULL ELSE v_caption END, now(), auth.uid()
  )
  ON CONFLICT (stock_item_id) DO UPDATE
    SET home_carousel_rank = EXCLUDED.home_carousel_rank,
        home_carousel_caption = EXCLUDED.home_carousel_caption,
        updated_at = now(),
        updated_by = auth.uid();
  RETURN p_stock_item_id;
END;
$$;


--
-- Name: set_wishlist_notify_when_in_stock(boolean, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_wishlist_notify_when_in_stock(p_notify boolean, p_stock_item_id uuid DEFAULT NULL::uuid, p_oem_part_number text DEFAULT NULL::text, p_wishlist_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cust UUID := public._current_customer_id();
  v_item UUID;
  v_id UUID;
BEGIN
  IF v_cust IS NULL THEN
    RAISE EXCEPTION 'customer profile required';
  END IF;
  IF p_notify IS NULL THEN
    RAISE EXCEPTION 'notify flag required';
  END IF;

  IF p_wishlist_id IS NOT NULL THEN
    UPDATE public.customer_wishlist_items
    SET notify_when_in_stock = p_notify
    WHERE id = p_wishlist_id AND customer_id = v_cust
    RETURNING id INTO v_id;
    IF v_id IS NULL THEN
      RAISE EXCEPTION 'wishlist item not found';
    END IF;
    RETURN v_id;
  END IF;

  v_item := public._resolve_customer_stock_item(p_stock_item_id, p_oem_part_number);

  UPDATE public.customer_wishlist_items
  SET notify_when_in_stock = p_notify
  WHERE customer_id = v_cust AND stock_item_id = v_item
  RETURNING id INTO v_id;

  IF v_id IS NULL THEN
    RAISE EXCEPTION 'wishlist item not found';
  END IF;
  RETURN v_id;
END;
$$;


--
-- Name: set_zig_exchange_rate(numeric, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_zig_exchange_rate(p_rate numeric, p_rate_date date DEFAULT CURRENT_DATE, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id UUID;
  v_date DATE := COALESCE(p_rate_date, CURRENT_DATE);
BEGIN
  IF NOT (
    auth.role() = 'service_role'
    OR public.has_staff_role(ARRAY['admin', 'finance']::public.staff_role[])
  ) THEN
    RAISE EXCEPTION 'finance or admin role required';
  END IF;

  IF p_rate IS NULL OR p_rate <= 0 THEN
    RAISE EXCEPTION 'rate must be > 0 (ZiG per 1 USD)';
  END IF;

  INSERT INTO public.daily_exchange_rates (
    currency, rate_date, rate, notes, set_by
  )
  VALUES (
    'ZIG', v_date, p_rate, nullif(trim(p_notes), ''), auth.uid()
  )
  ON CONFLICT (currency, rate_date) DO UPDATE
  SET
    rate = EXCLUDED.rate,
    notes = EXCLUDED.notes,
    set_by = EXCLUDED.set_by,
    created_at = now()
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


--
-- Name: settle_commerce_manual_payment(uuid, uuid, public.payment_tender, text, public.currency_code, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.settle_commerce_manual_payment(p_order_id uuid, p_payment_request_id uuid, p_tender public.payment_tender, p_reference text DEFAULT NULL::text, p_settlement_currency public.currency_code DEFAULT NULL::public.currency_code, p_settlement_amount numeric DEFAULT NULL::numeric, p_settlement_exchange_rate numeric DEFAULT NULL::numeric) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_order public.commerce_orders%ROWTYPE;
  v_request public.commerce_manual_payment_requests%ROWTYPE;
  v_pe UUID;
  v_reference TEXT;
BEGIN
  PERFORM public._require_payments_staff();
  IF p_order_id IS NULL OR p_payment_request_id IS NULL THEN
    RAISE EXCEPTION 'order_id and payment_request_id required';
  END IF;
  IF p_tender NOT IN ('cash','bank') THEN
    RAISE EXCEPTION 'manual commerce settlement supports cash or bank only';
  END IF;

  INSERT INTO public.commerce_manual_payment_requests(id,commerce_order_id,tender,reference)
  VALUES(p_payment_request_id,p_order_id,p_tender,NULLIF(trim(COALESCE(p_reference,'')),''))
  ON CONFLICT(id) DO NOTHING;

  SELECT * INTO v_request
  FROM public.commerce_manual_payment_requests
  WHERE id=p_payment_request_id
  FOR UPDATE;

  IF v_request.commerce_order_id IS DISTINCT FROM p_order_id
     OR v_request.tender IS DISTINCT FROM p_tender THEN
    RAISE EXCEPTION 'payment request id was already used for a different order or tender';
  END IF;
  IF v_request.payment_entry_id IS NOT NULL THEN
    RETURN v_request.payment_entry_id;
  END IF;

  SELECT * INTO v_order
  FROM public.commerce_orders
  WHERE id=p_order_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'commerce order not found'; END IF;

  IF v_order.settled_payment_entry_id IS NOT NULL THEN
    RAISE EXCEPTION 'commerce order is already settled; do not accept another manual payment';
  END IF;
  IF v_order.reservation_expires_at IS NULL OR v_order.reservation_expires_at <= now() THEN
    RAISE EXCEPTION 'commerce reservation expired; rebuild checkout before accepting payment';
  END IF;
  IF v_order.state NOT IN ('awaiting_payment','payment_failed') THEN
    RAISE EXCEPTION 'manual payment cannot be accepted while order is in state %', v_order.state;
  END IF;

  v_reference:=COALESCE(
    NULLIF(trim(COALESCE(p_reference,'')),''),
    'MANUAL-'||p_payment_request_id::text
  );
  v_pe:=private.settle_commerce_payment(
    v_order.id,
    p_tender::text,
    p_payment_request_id,
    v_reference,
    v_order.total,
    v_order.currency,
    v_order.exchange_rate_applied,
    p_settlement_currency,
    p_settlement_amount,
    p_settlement_exchange_rate
  );

  UPDATE public.commerce_manual_payment_requests
    SET payment_entry_id=v_pe,
        reference=v_reference,
        completed_at=now()
    WHERE id=p_payment_request_id;
  RETURN v_pe;
END;
$$;


--
-- Name: FUNCTION settle_commerce_manual_payment(p_order_id uuid, p_payment_request_id uuid, p_tender public.payment_tender, p_reference text, p_settlement_currency public.currency_code, p_settlement_amount numeric, p_settlement_exchange_rate numeric); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.settle_commerce_manual_payment(p_order_id uuid, p_payment_request_id uuid, p_tender public.payment_tender, p_reference text, p_settlement_currency public.currency_code, p_settlement_amount numeric, p_settlement_exchange_rate numeric) IS 'Idempotent staff cash/bank settlement for a live reserved commerce order. Rejects expired, already-settled, or provider-processing orders before cash/bank is accepted; successful settlement finalizes and posts atomically.';


--
-- Name: settle_invoice_tenders(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.settle_invoice_tenders(p_invoice_id uuid, p_tenders jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_prev text := COALESCE(current_setting('app.pos_posting', true), '');
  v_result uuid;
BEGIN
  -- Role checks stay in _settle_invoice_tenders_core; this only marks its ledger posting as internal.
  PERFORM set_config('app.pos_posting', '1', true);
  v_result := public._settle_invoice_tenders_core(p_invoice_id, p_tenders);
  PERFORM set_config('app.pos_posting', v_prev, true);
  RETURN v_result;
END;
$$;


--
-- Name: FUNCTION settle_invoice_tenders(p_invoice_id uuid, p_tenders jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.settle_invoice_tenders(p_invoice_id uuid, p_tenders jsonb) IS 'POS entry point. Logic lives in _settle_invoice_tenders_core; change that, not this wrapper (see 20261001110000).';


--
-- Name: settle_pos_commerce_tenders(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.settle_pos_commerce_tenders(p_order_id uuid, p_payment_request_id uuid, p_tenders jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE o public.commerce_orders%ROWTYPE; e JSONB; v_tender public.payment_tender; v_amt NUMERIC; v_sum NUMERIC:=0;
 v_inv UUID; v_pe UUID; v_first UUID; v_ids JSONB:='[]'::jsonb; v_distinct INTEGER; v_provider TEXT;
 existing public.pos_commerce_tender_settlements%ROWTYPE;
BEGIN
 PERFORM public._require_payments_staff();
 IF p_order_id IS NULL OR p_payment_request_id IS NULL THEN RAISE EXCEPTION 'order and payment request ids required'; END IF;
 IF p_tenders IS NULL OR jsonb_typeof(p_tenders)<>'array' OR jsonb_array_length(p_tenders)=0 THEN RAISE EXCEPTION 'non-empty tenders array required'; END IF;
 SELECT * INTO existing FROM public.pos_commerce_tender_settlements WHERE payment_request_id=p_payment_request_id;
 IF FOUND THEN
  IF existing.commerce_order_id<>p_order_id THEN RAISE EXCEPTION 'payment request id already belongs to another order'; END IF;
  IF existing.completed_at IS NOT NULL THEN
   RETURN jsonb_build_object('order_id',p_order_id,'invoice_id',existing.invoice_id,'payment_entry_ids',existing.payment_entry_ids,
    'state',(SELECT state FROM public.commerce_orders WHERE id=p_order_id));
  END IF;
 END IF;
 SELECT * INTO o FROM public.commerce_orders WHERE id=p_order_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'commerce order not found'; END IF;
 IF o.settled_payment_entry_id IS NOT NULL THEN RAISE EXCEPTION 'commerce order already settled'; END IF;
 IF o.reservation_expires_at IS NULL OR o.reservation_expires_at<=now() THEN RAISE EXCEPTION 'commerce reservation expired'; END IF;
 IF o.state NOT IN('awaiting_payment','payment_failed') THEN RAISE EXCEPTION 'manual tenders cannot settle order in state %',o.state; END IF;
 FOR e IN SELECT * FROM jsonb_array_elements(p_tenders) LOOP
  v_tender:=(e->>'tender')::public.payment_tender;
  IF v_tender NOT IN('cash','bank','store_credit') THEN RAISE EXCEPTION 'digital tender % must use provider intent/webhook settlement',v_tender; END IF;
  v_amt:=round(COALESCE((e->>'amount')::numeric,0),2);
  IF v_amt<=0 THEN RAISE EXCEPTION 'tender amount must be > 0'; END IF;
  v_sum:=v_sum+v_amt;
 END LOOP;
 IF abs(v_sum-o.total)>0.01 THEN RAISE EXCEPTION 'manual tenders sum % must equal order total %',v_sum,o.total; END IF;
 INSERT INTO public.pos_commerce_tender_settlements(payment_request_id,commerce_order_id,tender_snapshot,created_by)
 VALUES(p_payment_request_id,p_order_id,p_tenders,auth.uid()) ON CONFLICT(payment_request_id) DO NOTHING;
 v_inv:=private.finalize_commerce_order(o.id);
 FOR e IN SELECT * FROM jsonb_array_elements(p_tenders) LOOP
  v_tender:=(e->>'tender')::public.payment_tender; v_amt:=round((e->>'amount')::numeric,2);
  v_pe:=public.create_payment_entry(o.customer_id,v_tender,v_amt,o.currency,o.exchange_rate_applied,
    format('POS reserve-first %s %s',v_tender,o.id));
  PERFORM public.allocate_payment(v_pe,jsonb_build_array(jsonb_build_object('sales_invoice_id',v_inv,'amount',v_amt)));
  PERFORM public.post_payment_entry(v_pe);
  IF v_first IS NULL THEN v_first:=v_pe; END IF;
  v_ids:=v_ids||jsonb_build_array(v_pe);
 END LOOP;
 SELECT count(DISTINCT x->>'tender') INTO v_distinct FROM jsonb_array_elements(p_tenders) x;
 v_provider:=CASE WHEN v_distinct=1 THEN (p_tenders->0->>'tender') ELSE 'manual_split' END;
 UPDATE public.commerce_orders SET settled_payment_entry_id=v_first,settled_provider=v_provider,
  settled_provider_ref='POS-MANUAL-'||p_payment_request_id::text,payment_exception=NULL,
  state=CASE WHEN fulfillment_mode='dispatch' THEN 'allocation_pending'::public.commerce_order_state ELSE 'paid'::public.commerce_order_state END,
  updated_at=now() WHERE id=o.id;
 UPDATE public.pos_commerce_tender_settlements SET invoice_id=v_inv,payment_entry_ids=v_ids,completed_at=now()
 WHERE payment_request_id=p_payment_request_id;
 PERFORM private.enqueue_commerce_event('commerce:'||o.id::text||':manual-settled:'||p_payment_request_id::text,
  'commerce.payment_settled',o.id,jsonb_build_object('provider',v_provider,'payment_entry_ids',v_ids,'sales_invoice_id',v_inv));
 RETURN jsonb_build_object('order_id',o.id,'invoice_id',v_inv,'payment_entry_ids',v_ids,
  'state',(SELECT state FROM public.commerce_orders WHERE id=o.id));
END $$;


--
-- Name: settle_return_refund_store_credit(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.settle_return_refund_store_credit(p_return_request_id uuid, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_ref public.return_refund_requests%ROWTYPE; v_journal uuid; v_ledger uuid;
BEGIN
  IF NOT (auth.role()='service_role' OR public.has_staff_role(ARRAY['admin','finance']::public.staff_role[])) THEN
    RAISE EXCEPTION 'finance or admin role required';
  END IF;
  SELECT * INTO v_ref FROM public.return_refund_requests WHERE return_request_id=p_return_request_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'pending refund not found'; END IF;
  IF v_ref.status='completed' THEN RETURN v_ref.id; END IF;
  IF v_ref.status NOT IN ('pending','failed') THEN RAISE EXCEPTION 'refund cannot settle in status %',v_ref.status; END IF;
  PERFORM public._payments_rpc_enter();
  v_journal:=public.post_journal_entry(CURRENT_DATE,COALESCE(p_notes,'Return refund converted to store credit'),v_ref.currency,v_ref.exchange_rate_applied,
    jsonb_build_array(
      jsonb_build_object('account_code','2220','debit',v_ref.amount,'credit',0,'currency',v_ref.currency),
      jsonb_build_object('account_code','2200','debit',0,'credit',v_ref.amount,'currency',v_ref.currency)
    ));
  v_ledger:=public._append_store_credit(v_ref.customer_id,'issue',v_ref.amount,v_ref.currency,v_ref.exchange_rate_applied,NULL,v_journal,COALESCE(p_notes,'Return refund converted to store credit'));
  UPDATE public.return_refund_requests SET method='store_credit',status='completed',processed_by=auth.uid(),processed_at=now(),failure_reason=NULL,updated_at=now() WHERE id=v_ref.id;
  UPDATE public.customer_return_requests SET status='completed',updated_at=now() WHERE id=p_return_request_id;
  PERFORM public.emit_domain_event('refund_completed','return:refund:store-credit:'||v_ref.id::text,
    jsonb_build_object('refund_request_id',v_ref.id,'return_request_id',p_return_request_id,'method','store_credit','ledger_id',v_ledger,'amount',v_ref.amount),auth.uid(),NULL);
  RETURN v_ref.id;
END;
$$;


--
-- Name: staff_login_is_locked(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_login_is_locked(p_identifier text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_raw TEXT;
  v_hash TEXT;
  v_fails INT;
BEGIN
  v_raw := lower(trim(COALESCE(p_identifier, '')));
  IF v_raw = '' THEN
    RETURN false;
  END IF;
  v_hash := encode(extensions.digest(convert_to(v_raw, 'UTF8'), 'sha256'), 'hex');

  SELECT COUNT(*)::INT INTO v_fails
  FROM public.staff_login_failures
  WHERE identifier_hash = v_hash
    AND success = false
    AND attempted_at > now() - interval '15 minutes';

  RETURN v_fails >= 5;
END;
$$;


--
-- Name: FUNCTION staff_login_is_locked(p_identifier text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.staff_login_is_locked(p_identifier text) IS 'True when ≥5 failed password attempts in 15 minutes for identifier hash.';


--
-- Name: start_chat_thread(public.chat_thread_kind, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_chat_thread(p_kind public.chat_thread_kind DEFAULT 'support'::public.chat_thread_kind, p_subject text DEFAULT NULL::text, p_body text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_thread_id UUID;
  v_customer_id UUID;
  v_body TEXT := NULLIF(btrim(COALESCE(p_body, '')), '');
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication required';
  END IF;
  IF public.is_staff() THEN
    RAISE EXCEPTION 'staff cannot start customer chat threads via this RPC';
  END IF;

  v_customer_id := public._current_customer_id();

  INSERT INTO public.chat_threads (
    customer_user_id, customer_id, kind, status, subject, last_message_at
  ) VALUES (
    auth.uid(),
    v_customer_id,
    COALESCE(p_kind, 'support'),
    'open',
    NULLIF(btrim(COALESCE(p_subject, '')), ''),
    CASE WHEN v_body IS NOT NULL THEN now() ELSE NULL END
  )
  RETURNING id INTO v_thread_id;

  INSERT INTO public.chat_participants (thread_id, user_id, role, last_read_at)
  VALUES (v_thread_id, auth.uid(), 'customer', now());

  IF v_body IS NOT NULL THEN
    INSERT INTO public.chat_messages (thread_id, sender_user_id, sender_kind, body)
    VALUES (v_thread_id, auth.uid(), 'customer', v_body);
  END IF;

  RETURN v_thread_id;
END;
$$;


--
-- Name: start_pos_split_payment(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_pos_split_payment(p_order_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE o public.commerce_orders%ROWTYPE; c public.pos_carts%ROWTYPE; s public.pos_split_payment_sessions%ROWTYPE; t public.pos_till_sessions%ROWTYPE;
BEGIN
 PERFORM public._require_payments_staff();
 SELECT * INTO o FROM public.commerce_orders WHERE id=p_order_id FOR UPDATE;
 IF NOT FOUND OR o.sales_invoice_id IS NOT NULL OR o.settled_payment_entry_id IS NOT NULL OR o.state NOT IN('awaiting_payment','payment_processing','payment_failed') THEN
  RAISE EXCEPTION 'unsettled reserve-first commerce order required'; END IF;
 SELECT * INTO c FROM public.pos_carts WHERE id=o.cart_id;
 IF NOT FOUND OR c.created_by<>auth.uid() OR c.till_session_id IS NULL THEN RAISE EXCEPTION 'current operator cart and till required'; END IF;
 SELECT * INTO t FROM public.pos_till_sessions WHERE id=c.till_session_id;
 IF NOT FOUND OR t.status<>'open' OR t.operator_user_id<>auth.uid() THEN RAISE EXCEPTION 'active operator till required'; END IF;
 SELECT * INTO s FROM public.pos_split_payment_sessions WHERE commerce_order_id=o.id;
 IF NOT FOUND THEN
  INSERT INTO public.pos_split_payment_sessions(commerce_order_id,total_amount,currency,created_by,updated_by)
  VALUES(o.id,o.total,o.currency,auth.uid(),auth.uid()) RETURNING * INTO s;
 END IF;
 UPDATE public.commerce_orders SET state='payment_processing',reservation_expires_at=greatest(COALESCE(reservation_expires_at,now()),now()+interval '60 minutes'),updated_at=now() WHERE id=o.id;
 UPDATE public.inventory_reservations SET expires_at=greatest(COALESCE(expires_at,now()),now()+interval '60 minutes') WHERE commerce_order_id=o.id AND state='active';
 RETURN private.refresh_pos_split_payment_session(s.id);
END $$;


--
-- Name: store_catalog_r2_credentials_once(text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.store_catalog_r2_credentials_once(p_account_id text, p_access_key_id text, p_secret_access_key text, p_bucket text, p_endpoint text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'vault'
    AS $$
declare
  v_name text;
  v_value text;
  v_existing uuid;
begin
  if auth.role() <> 'service_role' then raise exception 'service_role required'; end if;
  if nullif(trim(p_account_id),'') is null or nullif(trim(p_access_key_id),'') is null or nullif(trim(p_secret_access_key),'') is null or nullif(trim(p_bucket),'') is null then
    raise exception 'complete R2 credential set required';
  end if;
  for v_name, v_value in
    select * from (values
      ('catalog_r2_account_id', trim(p_account_id)),
      ('catalog_r2_access_key_id', trim(p_access_key_id)),
      ('catalog_r2_secret_access_key', trim(p_secret_access_key)),
      ('catalog_r2_bucket', trim(p_bucket)),
      ('catalog_r2_endpoint', nullif(trim(coalesce(p_endpoint,'')),''))
    ) x(name,value)
  loop
    if v_value is null then continue; end if;
    select id into v_existing from vault.secrets where name=v_name limit 1;
    if v_existing is null then
      perform vault.create_secret(v_value, v_name, 'Nissan GTR Auto live R2 runtime credential migrated server-to-server', null);
    else
      perform vault.update_secret(v_existing, v_value, v_name, 'Nissan GTR Auto live R2 runtime credential migrated server-to-server', null);
    end if;
  end loop;
end;
$$;


--
-- Name: submit_consignment_entry(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_consignment_entry(p_entry_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_hdr public.consignment_entries%ROWTYPE;
  v_line RECORD;
  v_qty_base NUMERIC;
  v_cost NUMERIC;
  v_price NUMERIC;
  v_inv_total NUMERIC := 0;
  v_cogs_total NUMERIC := 0;
  v_rev_total NUMERIC := 0;
  v_journal UUID;
  v_lines JSONB := '[]'::jsonb;
  v_batch_code TEXT;
  v_level_cost NUMERIC;
BEGIN
  PERFORM public._require_consignment_staff();

  SELECT * INTO v_hdr FROM public.consignment_entries WHERE id = p_entry_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'consignment entry not found: %', p_entry_id;
  END IF;
  IF v_hdr.status <> 'draft' THEN
    RAISE EXCEPTION 'only draft consignment entries can be submitted (status=%)', v_hdr.status;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.consignment_entry_lines WHERE consignment_entry_id = p_entry_id
  ) THEN
    RAISE EXCEPTION 'consignment entry has no lines';
  END IF;

  IF public.is_period_locked(CURRENT_DATE) THEN
    RAISE EXCEPTION 'accounting period is locked for today';
  END IF;

  FOR v_line IN
    SELECT * FROM public.consignment_entry_lines
    WHERE consignment_entry_id = p_entry_id
    ORDER BY line_no
  LOOP
    v_qty_base := public.convert_to_base_uom(v_line.stock_item_id, v_line.uom_id, v_line.qty);
    v_cost := v_line.unit_cost;
    v_price := v_line.unit_price;

    CASE v_hdr.purpose
      WHEN 'receive' THEN
        -- Supplier-owned memo qty only — no stock_levels, no journal, no revenue
        PERFORM public._adjust_consignment_level(
          'supplier_owned', v_hdr.supplier_id, NULL,
          v_line.stock_item_id, v_hdr.warehouse_id,
          v_qty_base, v_cost, v_line.currency
        );

      WHEN 'return_to_supplier' THEN
        PERFORM public._adjust_consignment_level(
          'supplier_owned', v_hdr.supplier_id, NULL,
          v_line.stock_item_id, v_hdr.warehouse_id,
          -v_qty_base, v_cost, v_line.currency
        );

      WHEN 'place_at_customer' THEN
        -- Reclass owned inventory MAIN → 1320; still our asset; no revenue
        SELECT unit_cost INTO v_level_cost
        FROM public.stock_levels
        WHERE stock_item_id = v_line.stock_item_id AND warehouse_id = v_hdr.warehouse_id;
        v_cost := COALESCE(NULLIF(v_cost, 0), v_level_cost, 0);

        PERFORM public._consume_fifo_batches(
          v_line.stock_item_id, v_hdr.warehouse_id, v_qty_base
        );
        PERFORM public._adjust_stock_level(
          v_line.stock_item_id, v_hdr.warehouse_id, -v_qty_base,
          'FIFO', v_cost, v_line.currency
        );
        PERFORM public._adjust_consignment_level(
          'customer_held', NULL, v_hdr.customer_id,
          v_line.stock_item_id, v_hdr.warehouse_id,
          v_qty_base, v_cost, v_line.currency
        );
        v_inv_total := v_inv_total + round(v_qty_base * v_cost, 2);

      WHEN 'return_from_customer' THEN
        SELECT unit_cost INTO v_level_cost
        FROM public.consignment_stock_levels
        WHERE kind = 'customer_held'
          AND customer_id = v_hdr.customer_id
          AND stock_item_id = v_line.stock_item_id
          AND warehouse_id = v_hdr.warehouse_id;
        v_cost := COALESCE(NULLIF(v_cost, 0), v_level_cost, 0);

        PERFORM public._adjust_consignment_level(
          'customer_held', NULL, v_hdr.customer_id,
          v_line.stock_item_id, v_hdr.warehouse_id,
          -v_qty_base, v_cost, v_line.currency
        );
        v_batch_code := public.next_series_value('BATCH-');
        INSERT INTO public.stock_batches (
          batch_code, stock_item_id, warehouse_id, valuation_method,
          unit_cost, currency, qty_on_hand
        ) VALUES (
          v_batch_code, v_line.stock_item_id, v_hdr.warehouse_id, 'FIFO',
          v_cost, v_line.currency, v_qty_base
        );
        PERFORM public._adjust_stock_level(
          v_line.stock_item_id, v_hdr.warehouse_id, v_qty_base,
          'FIFO', v_cost, v_line.currency
        );
        v_inv_total := v_inv_total + round(v_qty_base * v_cost, 2);

      WHEN 'take_ownership' THEN
        -- Purchase into owned inventory — AP only; NEVER revenue
        PERFORM public._adjust_consignment_level(
          'supplier_owned', v_hdr.supplier_id, NULL,
          v_line.stock_item_id, v_hdr.warehouse_id,
          -v_qty_base, v_cost, v_line.currency
        );
        v_batch_code := public.next_series_value('BATCH-');
        INSERT INTO public.stock_batches (
          batch_code, stock_item_id, warehouse_id, valuation_method,
          unit_cost, currency, qty_on_hand
        ) VALUES (
          v_batch_code, v_line.stock_item_id, v_hdr.warehouse_id, 'FIFO',
          v_cost, v_line.currency, v_qty_base
        );
        PERFORM public._adjust_stock_level(
          v_line.stock_item_id, v_hdr.warehouse_id, v_qty_base,
          'FIFO', v_cost, v_line.currency
        );
        v_inv_total := v_inv_total + round(v_qty_base * v_cost, 2);

      WHEN 'recognize_sale' THEN
        -- ONLY path that credits 4100 Parts Sales Revenue
        SELECT unit_cost INTO v_level_cost
        FROM public.consignment_stock_levels
        WHERE kind = 'customer_held'
          AND customer_id = v_hdr.customer_id
          AND stock_item_id = v_line.stock_item_id
          AND warehouse_id = v_hdr.warehouse_id;
        v_cost := COALESCE(NULLIF(v_cost, 0), v_level_cost, 0);

        PERFORM public._adjust_consignment_level(
          'customer_held', NULL, v_hdr.customer_id,
          v_line.stock_item_id, v_hdr.warehouse_id,
          -v_qty_base, v_cost, v_line.currency
        );
        v_cogs_total := v_cogs_total + round(v_qty_base * v_cost, 2);
        v_rev_total := v_rev_total + round(v_qty_base * v_price, 2);

      ELSE
        RAISE EXCEPTION 'unsupported consignment purpose: %', v_hdr.purpose;
    END CASE;
  END LOOP;

  -- Journals (append-only via _post_journal_entry_inventory)
  IF v_hdr.purpose = 'place_at_customer' AND v_inv_total > 0 THEN
    v_journal := public._post_journal_entry_inventory(
      CURRENT_DATE,
      format('Consignment place %s', v_hdr.document_number),
      v_hdr.currency,
      v_hdr.exchange_rate_applied,
      jsonb_build_array(
        jsonb_build_object('account_code', '1320', 'debit', v_inv_total, 'credit', 0, 'currency', v_hdr.currency),
        jsonb_build_object('account_code', '1300', 'debit', 0, 'credit', v_inv_total, 'currency', v_hdr.currency)
      )
    );
  ELSIF v_hdr.purpose = 'return_from_customer' AND v_inv_total > 0 THEN
    v_journal := public._post_journal_entry_inventory(
      CURRENT_DATE,
      format('Consignment return %s', v_hdr.document_number),
      v_hdr.currency,
      v_hdr.exchange_rate_applied,
      jsonb_build_array(
        jsonb_build_object('account_code', '1300', 'debit', v_inv_total, 'credit', 0, 'currency', v_hdr.currency),
        jsonb_build_object('account_code', '1320', 'debit', 0, 'credit', v_inv_total, 'currency', v_hdr.currency)
      )
    );
  ELSIF v_hdr.purpose = 'take_ownership' AND v_inv_total > 0 THEN
    v_journal := public._post_journal_entry_inventory(
      CURRENT_DATE,
      format('Consignment take ownership %s', v_hdr.document_number),
      v_hdr.currency,
      v_hdr.exchange_rate_applied,
      jsonb_build_array(
        jsonb_build_object('account_code', '1300', 'debit', v_inv_total, 'credit', 0, 'currency', v_hdr.currency),
        jsonb_build_object('account_code', '2100', 'debit', 0, 'credit', v_inv_total, 'currency', v_hdr.currency)
      )
    );
  ELSIF v_hdr.purpose = 'recognize_sale' THEN
    IF v_rev_total <= 0 THEN
      RAISE EXCEPTION 'recognize_sale requires positive revenue total';
    END IF;
    v_lines := jsonb_build_array(
      jsonb_build_object('account_code', '1200', 'debit', v_rev_total, 'credit', 0, 'currency', v_hdr.currency),
      jsonb_build_object('account_code', '4100', 'debit', 0, 'credit', v_rev_total, 'currency', v_hdr.currency)
    );
    IF v_cogs_total > 0 THEN
      v_lines := v_lines || jsonb_build_array(
        jsonb_build_object('account_code', '5100', 'debit', v_cogs_total, 'credit', 0, 'currency', v_hdr.currency),
        jsonb_build_object('account_code', '1320', 'debit', 0, 'credit', v_cogs_total, 'currency', v_hdr.currency)
      );
    END IF;
    v_journal := public._post_journal_entry_inventory(
      CURRENT_DATE,
      format('Consignment sale %s', v_hdr.document_number),
      v_hdr.currency,
      v_hdr.exchange_rate_applied,
      v_lines
    );

    UPDATE public.customers
    SET open_balance = open_balance + v_rev_total, updated_at = now()
    WHERE id = v_hdr.customer_id;
  END IF;
  -- receive / return_to_supplier: intentionally no journal (not our inventory)

  PERFORM set_config('gtr.consignment_rpc', 'on', true);

  UPDATE public.consignment_entries
  SET
    status = 'submitted',
    submitted_at = now(),
    journal_entry_id = v_journal,
    updated_at = now()
  WHERE id = p_entry_id;

  RETURN p_entry_id;
END;
$$;


--
-- Name: submit_customer_product_review(smallint, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_customer_product_review(p_rating smallint, p_body text DEFAULT ''::text, p_stock_item_id uuid DEFAULT NULL::uuid, p_oem_part_number text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cust UUID := public._current_customer_id();
  v_item UUID;
  v_id UUID;
BEGIN
  IF v_cust IS NULL THEN
    RAISE EXCEPTION 'customer profile required';
  END IF;
  IF p_rating IS NULL OR p_rating < 1 OR p_rating > 5 THEN
    RAISE EXCEPTION 'rating must be 1..5';
  END IF;
  IF p_body IS NOT NULL AND char_length(p_body) > 4000 THEN
    RAISE EXCEPTION 'review body must be at most 4000 characters';
  END IF;

  v_item := public._resolve_customer_stock_item(p_stock_item_id, p_oem_part_number);

  INSERT INTO public.customer_product_reviews (
    customer_id, stock_item_id, rating, body, status
  )
  VALUES (
    v_cust,
    v_item,
    p_rating,
    COALESCE(p_body, ''),
    'pending'
  )
  ON CONFLICT (customer_id, stock_item_id) DO UPDATE
  SET
    rating = EXCLUDED.rating,
    body = EXCLUDED.body,
    status = 'pending',
    updated_at = now()
  WHERE public.customer_product_reviews.status IN ('pending', 'rejected')
  RETURNING id INTO v_id;

  IF v_id IS NULL THEN
    RAISE EXCEPTION 'cannot replace an approved review; contact support';
  END IF;

  RETURN v_id;
END;
$$;


--
-- Name: submit_delivery_note(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_delivery_note(p_delivery_note_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_order_id UUID; v_result UUID; BEGIN
 PERFORM public._logistics_begin_rpc(); PERFORM public._require_logistics_staff();
 SELECT co.id INTO v_order_id FROM public.delivery_notes dn JOIN public.commerce_orders co ON co.sales_invoice_id=dn.sales_invoice_id WHERE dn.id=p_delivery_note_id;
 IF v_order_id IS NOT NULL THEN PERFORM set_config('app.commerce_fulfill_order_id',v_order_id::text,true); END IF;
 BEGIN v_result:=public.submit_delivery_note_integrity_v1(p_delivery_note_id); EXCEPTION WHEN OTHERS THEN PERFORM set_config('app.commerce_fulfill_order_id','',true); RAISE; END;
 PERFORM set_config('app.commerce_fulfill_order_id','',true); RETURN v_result; END; $$;


--
-- Name: submit_delivery_note_integrity_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_delivery_note_integrity_v1(p_delivery_note_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_dn public.delivery_notes%ROWTYPE;
  v_inv public.sales_invoices%ROWTYPE;
  v_line RECORD;
  v_open NUMERIC;
  v_unit_cost NUMERIC;
  v_currency public.currency_code;
  v_cogs NUMERIC := 0;
  v_entry UUID;
  v_journal UUID;
BEGIN
  PERFORM public._logistics_begin_rpc();
  PERFORM public._require_logistics_staff();

  SELECT * INTO v_dn FROM public.delivery_notes WHERE id = p_delivery_note_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'delivery note not found';
  END IF;
  IF v_dn.status <> 'draft' THEN
    RAISE EXCEPTION 'only draft DNs can be submitted (status=%)', v_dn.status;
  END IF;

  SELECT * INTO v_inv
  FROM public.sales_invoices
  WHERE id = v_dn.sales_invoice_id
  FOR UPDATE;
  IF v_inv.fulfillment_mode <> 'dispatch' THEN
    RAISE EXCEPTION 'submit blocked: immediate invoices must not re-issue stock via DN';
  END IF;
  IF v_inv.status <> 'posted' OR v_inv.doc_type <> 'invoice' THEN
    RAISE EXCEPTION 'posted invoice required';
  END IF;

  FOR v_line IN
    SELECT * FROM public.delivery_note_lines WHERE delivery_note_id = p_delivery_note_id
  LOOP
    -- Open excluding this draft DN's own reservation
    SELECT GREATEST(
      sil.qty_base - sil.qty_fulfilled - COALESCE((
        SELECT SUM(dnl.qty_base)
        FROM public.delivery_note_lines dnl
        JOIN public.delivery_notes dn ON dn.id = dnl.delivery_note_id
        WHERE dnl.sales_invoice_line_id = sil.id
          AND dn.status = 'draft'
          AND dn.id <> p_delivery_note_id
      ), 0),
      0
    )
    INTO v_open
    FROM public.sales_invoice_lines sil
    WHERE sil.id = v_line.sales_invoice_line_id;

    IF v_line.qty_base > v_open THEN
      RAISE EXCEPTION 'DN submit over-ship denied: open=% ship=%', v_open, v_line.qty_base;
    END IF;

    SELECT unit_cost, currency INTO v_unit_cost, v_currency
    FROM public.stock_levels
    WHERE stock_item_id = v_line.stock_item_id AND warehouse_id = v_dn.warehouse_id;

    UPDATE public.delivery_note_lines
    SET unit_cost = COALESCE(v_unit_cost, 0),
        currency = COALESCE(v_currency, v_dn.currency)
    WHERE id = v_line.id;

    PERFORM public._consume_fifo_batches(
      v_line.stock_item_id, v_dn.warehouse_id, v_line.qty_base
    );
    PERFORM public._adjust_stock_level(
      v_line.stock_item_id, v_dn.warehouse_id, -v_line.qty_base,
      'FIFO', COALESCE(v_unit_cost, 0), COALESCE(v_currency, v_dn.currency)
    );

    v_cogs := v_cogs + COALESCE(v_unit_cost, 0) * v_line.qty_base;

    UPDATE public.sales_invoice_lines
    SET qty_fulfilled = qty_fulfilled + v_line.qty_base
    WHERE id = v_line.sales_invoice_line_id;
  END LOOP;

  -- Stock entry header for audit trail (levels already adjusted above)
  INSERT INTO public.stock_entries (
    entry_type, status, from_warehouse_id, notes, created_by,
    posted_at, document_number
  )
  VALUES (
    'issue', 'posted', v_dn.warehouse_id,
    format('DN %s', COALESCE(v_dn.document_number, p_delivery_note_id::text)),
    auth.uid(), now(), public.next_series_value('ISS-')
  )
  RETURNING id INTO v_entry;

  FOR v_line IN
    SELECT * FROM public.delivery_note_lines WHERE delivery_note_id = p_delivery_note_id
  LOOP
    INSERT INTO public.stock_entry_lines (
      stock_entry_id, stock_item_id, uom_id, qty, qty_base,
      unit_cost, currency, valuation_method
    )
    VALUES (
      v_entry, v_line.stock_item_id, v_line.uom_id, v_line.qty, v_line.qty_base,
      v_line.unit_cost, v_line.currency, 'FIFO'
    );
  END LOOP;

  IF v_cogs > 0 THEN
    v_journal := public._post_journal_entry_inventory(
      CURRENT_DATE,
      format('COGS DN %s', COALESCE(v_dn.document_number, p_delivery_note_id::text)),
      v_dn.currency,
      v_dn.exchange_rate_applied,
      jsonb_build_array(
        jsonb_build_object(
          'account_code', '5100',
          'debit', round(v_cogs, 2), 'credit', 0, 'currency', v_dn.currency
        ),
        jsonb_build_object(
          'account_code', '1300',
          'debit', 0, 'credit', round(v_cogs, 2), 'currency', v_dn.currency
        )
      )
    );
  END IF;

  UPDATE public.delivery_notes
  SET
    status = 'submitted',
    stock_entry_id = v_entry,
    cogs_journal_entry_id = v_journal,
    submitted_by = auth.uid(),
    submitted_at = now(),
    updated_at = now()
  WHERE id = p_delivery_note_id;

  RETURN p_delivery_note_id;
END;
$$;


--
-- Name: submit_delivery_pod(uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_delivery_pod(p_delivery_job_id uuid, p_pod_photo_path text, p_pod_signature_path text, p_otp_code text, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_job public.delivery_jobs%ROWTYPE;
  v_uid UUID := auth.uid();
  v_allowed BOOLEAN := false;
  v_back_office BOOLEAN := false;
  v_inv public.sales_invoices%ROWTYPE;
  v_due NUMERIC;
  v_photo TEXT;
  v_sig TEXT;
BEGIN
  PERFORM public._logistics_begin_rpc();

  IF p_pod_photo_path IS NULL OR length(trim(p_pod_photo_path)) = 0
     OR p_pod_signature_path IS NULL OR length(trim(p_pod_signature_path)) = 0 THEN
    RAISE EXCEPTION 'pod_photo_path and pod_signature_path are required';
  END IF;

  IF p_otp_code IS NULL OR length(trim(p_otp_code)) = 0 THEN
    RAISE EXCEPTION 'POD OTP code required; use generate_delivery_pod_otp then verify';
  END IF;

  SELECT * INTO v_job FROM public.delivery_jobs WHERE id = p_delivery_job_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'delivery job not found';
  END IF;
  IF v_job.status IN ('completed', 'failed') THEN
    RAISE EXCEPTION 'terminal delivery job cannot accept POD';
  END IF;
  IF v_job.status <> 'dispatched' THEN
    RAISE EXCEPTION 'POD requires dispatched job (status=%)', v_job.status;
  END IF;

  IF auth.role() = 'service_role'
     OR public.has_staff_role(
       ARRAY['admin', 'warehouse', 'dispatcher']::public.staff_role[]
     ) THEN
    v_allowed := true;
    v_back_office := true;
  ELSIF v_uid IS NOT NULL
        AND v_job.assignee_user_id = v_uid
        AND public.has_staff_role(ARRAY['driver']::public.staff_role[]) THEN
    v_allowed := true;
  END IF;

  IF NOT v_allowed THEN
    RAISE EXCEPTION 'assigned driver or dispatcher/warehouse/admin required for POD';
  END IF;

  -- Cash / card on delivery: the driver cannot complete while the invoice still has a balance the
  -- driver is meant to collect, or while a card charge on the machine is unresolved (it may have taken
  -- money). Dispatch, warehouse and admin may complete anyway (e.g. the balance goes on account).
  IF NOT v_back_office THEN
    SELECT si.* INTO v_inv
    FROM public.delivery_notes dn
    JOIN public.sales_invoices si ON si.id = dn.sales_invoice_id
    WHERE dn.id = v_job.delivery_note_id;
    IF FOUND AND v_inv.delivery_payment_method IN ('cash_on_delivery','card_on_delivery','cash_or_card_on_delivery') THEN
      v_due := greatest(round(v_inv.total - v_inv.amount_paid, 2), 0);
      -- A balance the customer could not pay may stay on account once approved (credit check or dispatch).
      IF v_due > 0.004 AND NOT EXISTS (
        SELECT 1 FROM public.delivery_balance_approvals b
        WHERE b.delivery_job_id = p_delivery_job_id AND b.status IN ('auto_approved','approved')
          AND v_due <= b.amount + 0.01
      ) THEN
        RAISE EXCEPTION 'collect % % before completing this delivery (cash or card on delivery)', v_inv.currency, v_due;
      END IF;
    END IF;
    IF EXISTS (
      SELECT 1 FROM public.pos_card_terminal_attempts a
      WHERE a.delivery_job_id = p_delivery_job_id AND a.status IN ('initiated','approved','unknown')
    ) THEN
      RAISE EXCEPTION 'finish the card payment on this delivery before completing it';
    END IF;
  END IF;

  -- High: bind paths to this job + require objects in delivery-pods
  v_photo := public._assert_delivery_pod_object_for_job(
    p_delivery_job_id, p_pod_photo_path, 'photo'
  );
  v_sig := public._assert_delivery_pod_object_for_job(
    p_delivery_job_id, p_pod_signature_path, 'signature'
  );

  -- Verify OTP (raises on failure); unlocks complete. The driver app checks the code with
  -- verify_delivery_pod_otp first (and may submit later from its offline queue): a code already
  -- verified for this job is accepted.
  IF NOT EXISTS (
    SELECT 1 FROM public.delivery_pod_otps o
    WHERE o.delivery_job_id = p_delivery_job_id
      AND o.verified_at IS NOT NULL
      AND o.code_hash = public._hash_delivery_pod_otp(p_otp_code)
  ) THEN
    PERFORM public.verify_delivery_pod_otp(p_delivery_job_id, p_otp_code);
  END IF;
  DELETE FROM private.delivery_pod_codes WHERE delivery_job_id = p_delivery_job_id;

  UPDATE public.delivery_jobs
  SET
    pod_photo_path = v_photo,
    pod_signature_path = v_sig,
    notes = COALESCE(p_notes, notes),
    status = 'completed',
    completed_at = now(),
    completed_via = 'pod',
    updated_at = now()
  WHERE id = p_delivery_job_id;

  UPDATE public.delivery_track_tokens
  SET revoked_at = COALESCE(revoked_at, now())
  WHERE delivery_job_id = p_delivery_job_id
    AND revoked_at IS NULL;

  PERFORM public.emit_domain_event(
    'delivery_completed',
    'delivery_job:completed:' || p_delivery_job_id::text,
    jsonb_build_object(
      'delivery_job_id', p_delivery_job_id,
      'delivery_note_id', v_job.delivery_note_id,
      'status', 'completed',
      'completed_via', 'pod'
    )
  );

  RETURN p_delivery_job_id;
END;
$$;


--
-- Name: submit_driver_cash_handin(public.currency_code, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_driver_cash_handin(p_currency public.currency_code, p_declared_amount numeric, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE h public.driver_cash_handins%ROWTYPE; v_expected numeric; v_count integer;
BEGIN
 IF NOT public.has_staff_role(ARRAY['driver']::public.staff_role[]) THEN RAISE EXCEPTION 'driver role required'; END IF;
 IF COALESCE(p_declared_amount,-1) < 0 THEN RAISE EXCEPTION 'declared amount must be >= 0'; END IF;
 IF EXISTS(SELECT 1 FROM public.driver_cash_handins WHERE driver_user_id=auth.uid() AND currency=p_currency AND status='submitted') THEN
  RAISE EXCEPTION 'your last % hand-in is still waiting to be received', p_currency; END IF;
 SELECT COALESCE(sum(amount),0), count(*) INTO v_expected, v_count FROM public.delivery_cash_collections
 WHERE collected_by=auth.uid() AND currency=p_currency AND handin_id IS NULL;
 IF v_count=0 THEN RAISE EXCEPTION 'no % cash to hand in', p_currency; END IF;
 INSERT INTO public.driver_cash_handins(document_number,driver_user_id,currency,expected_amount,declared_amount,collection_count,status,driver_notes)
 VALUES(public.next_series_value('DCH-'),auth.uid(),p_currency,round(v_expected,2),round(p_declared_amount,2),v_count,'submitted',NULLIF(trim(COALESCE(p_notes,'')),''))
 RETURNING * INTO h;
 UPDATE public.delivery_cash_collections SET handin_id=h.id WHERE collected_by=auth.uid() AND currency=p_currency AND handin_id IS NULL;
 RETURN private._driver_cash_handin_json(h);
END $$;


--
-- Name: submit_finance_requisition(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_finance_requisition(p_requisition_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row public.finance_requisitions%ROWTYPE;
  v_line_sum NUMERIC(18, 2);
  v_line_count INT;
  v_needed INT;
BEGIN
  SELECT * INTO v_row
  FROM public.finance_requisitions
  WHERE id = p_requisition_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'requisition not found: %', p_requisition_id;
  END IF;

  IF NOT (
    auth.role() = 'service_role'
    OR public.has_staff_role(ARRAY['admin', 'finance']::public.staff_role[])
    OR v_row.requested_by = auth.uid()
  ) THEN
    RAISE EXCEPTION 'not allowed to submit this requisition';
  END IF;

  IF v_row.status <> 'draft' THEN
    RAISE EXCEPTION 'only draft requisitions can be submitted (status=%)', v_row.status;
  END IF;

  SELECT COUNT(*), COALESCE(SUM(amount), 0)
  INTO v_line_count, v_line_sum
  FROM public.finance_requisition_lines
  WHERE requisition_id = p_requisition_id;

  IF v_line_count < 1 THEN
    RAISE EXCEPTION 'cannot submit requisition without lines';
  END IF;
  IF v_line_sum IS DISTINCT FROM v_row.amount THEN
    RAISE EXCEPTION 'header amount % does not match line total %', v_row.amount, v_line_sum;
  END IF;

  v_needed := public._finance_req_required_approvals(
    v_row.req_type,
    v_row.currency,
    v_row.amount
  );

  PERFORM public._finance_req_rpc_enter();

  UPDATE public.finance_requisitions
  SET
    status = 'submitted',
    submitted_at = now(),
    document_number = COALESCE(document_number, public.next_series_value('FREQ-')),
    required_approvals = v_needed,
    approval_count = 0,
    approved_by = NULL,
    approved_at = NULL,
    updated_at = now()
  WHERE id = p_requisition_id;

  INSERT INTO public.finance_audit_log (
    actor_user_id, action, entity_type, entity_id, before_state, after_state
  ) VALUES (
    auth.uid(),
    'requisition_submitted',
    'finance_requisitions',
    p_requisition_id,
    jsonb_build_object('status', 'draft', 'amount', v_row.amount),
    jsonb_build_object(
      'status', 'submitted',
      'required_approvals', v_needed,
      'document_number', COALESCE(v_row.document_number, 'pending')
    )
  );

  RETURN p_requisition_id;
END;
$$;


--
-- Name: submit_goods_receipt(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_goods_receipt(p_goods_receipt_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_grn public.goods_receipts%ROWTYPE;
  v_receipt_lines JSONB := '[]'::jsonb;
  v_row RECORD;
  v_entry UUID;
  v_var_pct NUMERIC;
  v_tolerance CONSTANT NUMERIC := 0.05;
  v_mismatch BOOLEAN := false;
BEGIN
  PERFORM public._procurement_begin_rpc();
  PERFORM public._require_procurement_staff();
  PERFORM public._assert_procurement_period_open();

  SELECT * INTO v_grn FROM public.goods_receipts WHERE id = p_goods_receipt_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'goods receipt not found: %', p_goods_receipt_id;
  END IF;
  IF v_grn.status <> 'draft' THEN
    RAISE EXCEPTION 'only draft GRNs can be submitted';
  END IF;

  FOR v_row IN
    SELECT grl.*, pol.unit_price AS po_unit_price, pol.qty_ordered, pol.qty_received
    FROM public.goods_receipt_lines grl
    JOIN public.purchase_order_lines pol ON pol.id = grl.purchase_order_line_id
    WHERE grl.goods_receipt_id = p_goods_receipt_id
  LOOP
    IF v_row.qty_received + v_row.qty > v_row.qty_ordered THEN
      RAISE EXCEPTION 'over-receipt on PO line %', v_row.purchase_order_line_id;
    END IF;

    IF v_row.po_unit_price > 0 THEN
      v_var_pct := abs(v_row.unit_cost - v_row.po_unit_price) / v_row.po_unit_price;
      IF v_var_pct > v_tolerance THEN
        v_mismatch := true;
      END IF;
    END IF;

    v_receipt_lines := v_receipt_lines || jsonb_build_array(
      jsonb_build_object(
        'stock_item_id', v_row.stock_item_id,
        'uom_id', v_row.uom_id,
        'qty', v_row.qty,
        'unit_cost', v_row.unit_cost,
        'currency', v_row.currency,
        'valuation_method', 'FIFO'
      )
    );
  END LOOP;

  v_entry := public.post_stock_receipt(
    v_grn.warehouse_id,
    COALESCE(v_grn.notes, 'GRN ' || v_grn.document_number),
    v_receipt_lines
  );

  FOR v_row IN
    SELECT grl.*, pol.unit_price AS po_unit_price
    FROM public.goods_receipt_lines grl
    JOIN public.purchase_order_lines pol ON pol.id = grl.purchase_order_line_id
    WHERE grl.goods_receipt_id = p_goods_receipt_id
    ORDER BY grl.created_at, grl.id
  LOOP
    UPDATE public.goods_receipt_lines grl
    SET
      stock_entry_line_id = (
        SELECT sel.id
        FROM public.stock_entry_lines sel
        WHERE sel.stock_entry_id = v_entry
          AND sel.stock_item_id = grl.stock_item_id
          AND sel.qty = grl.qty
          AND sel.id NOT IN (
            SELECT g2.stock_entry_line_id
            FROM public.goods_receipt_lines g2
            WHERE g2.goods_receipt_id = p_goods_receipt_id
              AND g2.stock_entry_line_id IS NOT NULL
          )
        ORDER BY sel.created_at
        LIMIT 1
      ),
      price_variance_pct = CASE
        WHEN v_row.po_unit_price > 0 THEN
          abs(grl.unit_cost - v_row.po_unit_price) / v_row.po_unit_price
        ELSE NULL
      END
    WHERE grl.id = v_row.id;

    UPDATE public.purchase_order_lines pol
    SET qty_received = qty_received + v_row.qty
    WHERE pol.id = v_row.purchase_order_line_id;
  END LOOP;

  UPDATE public.goods_receipts
  SET
    status = 'submitted',
    stock_entry_id = v_entry,
    submitted_at = now(),
    updated_at = now()
  WHERE id = p_goods_receipt_id;

  IF v_mismatch THEN
    PERFORM public.emit_domain_event(
      'supplier_mismatch',
      'goods_receipt:' || p_goods_receipt_id::text,
      jsonb_build_object(
        'goods_receipt_id', p_goods_receipt_id,
        'purchase_order_id', v_grn.purchase_order_id,
        'tolerance_pct', v_tolerance
      )
    );
  END IF;

  PERFORM public.emit_domain_event(
    'po_received',
    'goods_receipt:' || p_goods_receipt_id::text,
    jsonb_build_object(
      'goods_receipt_id', p_goods_receipt_id,
      'purchase_order_id', v_grn.purchase_order_id,
      'stock_entry_id', v_entry
    )
  );

  PERFORM public._procurement_end_rpc();
  RETURN p_goods_receipt_id;
EXCEPTION
  WHEN OTHERS THEN
    PERFORM public._procurement_end_rpc();
    RAISE;
END;
$$;


--
-- Name: submit_landed_cost_voucher(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_landed_cost_voucher(p_landed_cost_voucher_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_lcv public.landed_cost_vouchers%ROWTYPE;
  v_total NUMERIC := 0;
  v_row RECORD;
  v_journal UUID;
  v_delta NUMERIC;
BEGIN
  PERFORM public._procurement_begin_rpc();
  PERFORM public._require_procurement_finance();
  PERFORM public._assert_procurement_period_open();

  SELECT * INTO v_lcv FROM public.landed_cost_vouchers WHERE id = p_landed_cost_voucher_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'landed cost voucher not found: %', p_landed_cost_voucher_id;
  END IF;
  IF v_lcv.status <> 'draft' THEN
    RAISE EXCEPTION 'only draft landed cost vouchers can be submitted';
  END IF;

  SELECT COALESCE(SUM(amount), 0) INTO v_total
  FROM public.landed_cost_charges
  WHERE landed_cost_voucher_id = p_landed_cost_voucher_id;

  FOR v_row IN
    SELECT * FROM public.landed_cost_allocations
    WHERE landed_cost_voucher_id = p_landed_cost_voucher_id
  LOOP
    v_delta := v_row.allocated_amount / v_row.qty_on_hand_snapshot;
    UPDATE public.stock_batches
    SET unit_cost = round(v_row.prior_unit_cost + v_delta, 4)
    WHERE id = v_row.stock_batch_id;
  END LOOP;

  v_journal := public._post_journal_entry_inventory(
    CURRENT_DATE,
    format('Landed cost %s', v_lcv.document_number),
    v_lcv.currency,
    v_lcv.exchange_rate_applied,
    jsonb_build_array(
      jsonb_build_object(
        'account_code', '1300',
        'debit', v_total,
        'credit', 0,
        'currency', v_lcv.currency
      ),
      jsonb_build_object(
        'account_code', '2100',
        'debit', 0,
        'credit', v_total,
        'currency', v_lcv.currency
      )
    )
  );

  UPDATE public.landed_cost_vouchers
  SET
    status = 'submitted',
    journal_entry_id = v_journal,
    submitted_at = now(),
    updated_at = now()
  WHERE id = p_landed_cost_voucher_id;

  PERFORM public._procurement_end_rpc();
  RETURN p_landed_cost_voucher_id;
EXCEPTION
  WHEN OTHERS THEN
    PERFORM public._procurement_end_rpc();
    RAISE;
END;
$$;


--
-- Name: submit_leave_request(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_leave_request(p_request_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row public.hr_leave_requests%ROWTYPE;
BEGIN
  SELECT * INTO v_row FROM public.hr_leave_requests WHERE id = p_request_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'leave request not found'; END IF;
  IF v_row.status <> 'draft' THEN RAISE EXCEPTION 'only draft requests can be submitted'; END IF;

  IF NOT (
    public.has_staff_role(ARRAY['admin', 'hr']::public.staff_role[])
    OR EXISTS (
      SELECT 1 FROM public.employees e
      WHERE e.id = v_row.employee_id AND e.user_id = auth.uid()
    )
  ) THEN
    RAISE EXCEPTION 'not allowed to submit this leave request';
  END IF;

  UPDATE public.hr_leave_requests
  SET status = 'submitted', submitted_at = now(), updated_at = now()
  WHERE id = p_request_id;
  RETURN p_request_id;
END;
$$;


