--
-- Name: submit_payroll_run(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_payroll_run(p_payroll_run_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_run public.payroll_runs%ROWTYPE;
  v_line_count INT;
BEGIN
  PERFORM public._payroll_begin_rpc();
  PERFORM public._require_hr_staff();

  SELECT * INTO v_run FROM public.payroll_runs WHERE id = p_payroll_run_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'payroll run not found: %', p_payroll_run_id;
  END IF;
  IF v_run.status <> 'draft' THEN
    RAISE EXCEPTION 'only draft payroll runs can be submitted';
  END IF;

  SELECT COUNT(*) INTO v_line_count
  FROM public.payroll_lines WHERE payroll_run_id = p_payroll_run_id;
  IF v_line_count = 0 THEN
    RAISE EXCEPTION 'payroll run has no lines; compute first';
  END IF;

  -- Enforce tax-free formula at submit
  IF v_run.total_net IS DISTINCT FROM (v_run.total_gross - v_run.total_deductions) THEN
    RAISE EXCEPTION 'payroll net must equal gross − manual deductions';
  END IF;

  UPDATE public.payroll_runs
  SET status = 'submitted', submitted_at = now(), updated_at = now()
  WHERE id = p_payroll_run_id;

  PERFORM public.emit_domain_event(
    'payroll_run_ready',
    format('payroll_run_ready:%s', p_payroll_run_id),
    jsonb_build_object(
      'payroll_run_id', p_payroll_run_id,
      'document_number', v_run.document_number,
      'period_start', v_run.period_start,
      'period_end', v_run.period_end,
      'currency', v_run.currency,
      'exchange_rate', v_run.exchange_rate,
      'total_gross', v_run.total_gross,
      'total_deductions', v_run.total_deductions,
      'total_net', v_run.total_net
    ),
    auth.uid(),
    format(
      'GTR Auto: payroll %s ready (gross %s %s − manual %s = net %s)',
      v_run.document_number,
      v_run.total_gross,
      v_run.currency,
      v_run.total_deductions,
      v_run.total_net
    )
  );

  RETURN p_payroll_run_id;
END;
$$;


--
-- Name: submit_pos_till_denominated_close(uuid, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_pos_till_denominated_close(p_session_id uuid, p_denominations jsonb, p_variance_reason_code text DEFAULT NULL::text, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE s public.pos_till_sessions%ROWTYPE; e JSONB; v_denom NUMERIC; v_qty INTEGER; v_total NUMERIC:=0;
BEGIN
 PERFORM public._require_sales_staff(); SELECT * INTO s FROM public.pos_till_sessions WHERE id=p_session_id FOR UPDATE;
 IF NOT FOUND OR s.status<>'open' OR s.operator_user_id<>auth.uid() THEN RAISE EXCEPTION 'open operator till session required'; END IF;
 IF p_denominations IS NULL OR jsonb_typeof(p_denominations)<>'array' OR jsonb_array_length(p_denominations)=0 THEN RAISE EXCEPTION 'denomination count required'; END IF;
 DELETE FROM public.pos_till_count_lines WHERE session_id=p_session_id;
 FOR e IN SELECT * FROM jsonb_array_elements(p_denominations) LOOP
  v_denom:=COALESCE((e->>'denomination')::numeric,0); v_qty:=COALESCE((e->>'quantity')::integer,-1);
  IF v_denom<=0 OR v_qty<0 THEN RAISE EXCEPTION 'invalid denomination count'; END IF;
  INSERT INTO public.pos_till_count_lines(session_id,denomination,quantity,amount,counted_by)
  VALUES(p_session_id,v_denom,v_qty,round(v_denom*v_qty,2),auth.uid()); v_total:=v_total+round(v_denom*v_qty,2);
 END LOOP;
 RETURN public.close_pos_till_session(p_session_id,v_total,p_variance_reason_code,p_notes);
END $$;


