  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.supplier_quotation_lines WHERE supplier_quotation_id = p_supplier_quotation_id
  ) THEN
    RAISE EXCEPTION 'quotation lines required';
  END IF;

  UPDATE public.supplier_quotations
  SET status = 'submitted', submitted_at = now(), updated_at = now()
  WHERE id = p_supplier_quotation_id;

  PERFORM public._procurement_end_rpc();
  RETURN p_supplier_quotation_id;
EXCEPTION
  WHEN OTHERS THEN
    PERFORM public._procurement_end_rpc();
    RAISE;
END;
$$;


--
-- Name: suggest_delivery_assignees(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.suggest_delivery_assignees(p_delivery_job_id uuid, p_limit integer DEFAULT 5) RETURNS TABLE(user_id uuid, status public.driver_presence_status, distance_m double precision, capacity integer, open_jobs integer, last_lat double precision, last_lng double precision, last_seen_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_pickup_lat DOUBLE PRECISION;
  v_pickup_lng DOUBLE PRECISION;
  v_lim INTEGER := greatest(1, least(COALESCE(p_limit, 5), 50));
BEGIN
  PERFORM public._require_dispatcher_staff();

  SELECT dj.pickup_lat, dj.pickup_lng
  INTO v_pickup_lat, v_pickup_lng
  FROM public.delivery_jobs dj
  WHERE dj.id = p_delivery_job_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'delivery job not found';
  END IF;

  RETURN QUERY
  SELECT
    dp.user_id,
    dp.status,
    public._haversine_meters(
      v_pickup_lat, v_pickup_lng, dp.last_lat, dp.last_lng
    ) AS distance_m,
    dp.capacity,
    public._driver_open_job_count(dp.user_id) AS open_jobs,
    dp.last_lat,
    dp.last_lng,
    dp.last_seen_at
  FROM public.driver_presence dp
  JOIN public.staff_roles sr
    ON sr.user_id = dp.user_id AND sr.role = 'driver'
  WHERE dp.status IN ('available', 'on_duty')
    AND public._driver_shift_active(dp.shift_starts_at, dp.shift_ends_at, now())
    AND public._driver_open_job_count(dp.user_id) < dp.capacity
  ORDER BY
    (public._haversine_meters(
      v_pickup_lat, v_pickup_lng, dp.last_lat, dp.last_lng
    ) IS NULL) ASC,
    public._haversine_meters(
      v_pickup_lat, v_pickup_lng, dp.last_lat, dp.last_lng
    ) ASC NULLS LAST,
    dp.last_seen_at DESC NULLS LAST
  LIMIT v_lim;
END;
$$;


--
-- Name: suspend_customer(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.suspend_customer(p_customer_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE s public.customer_suspensions%ROWTYPE;
BEGIN
 IF NOT (public.has_staff_role(ARRAY['admin','finance']::public.staff_role[]) OR public.is_pos_approver()) THEN
  RAISE EXCEPTION 'admin, finance or manager required to suspend a customer'; END IF;
 IF trim(COALESCE(p_reason,''))='' THEN RAISE EXCEPTION 'reason required'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.customers WHERE id=p_customer_id) THEN RAISE EXCEPTION 'customer not found'; END IF;
 IF EXISTS(SELECT 1 FROM public.customer_suspensions WHERE customer_id=p_customer_id AND status='active') THEN
  RAISE EXCEPTION 'customer is already suspended'; END IF;
 INSERT INTO public.customer_suspensions(customer_id,status,source,reason,findings,suspended_by)
 VALUES(p_customer_id,'active','manual',trim(p_reason),private.customer_suspension_findings(p_customer_id),auth.uid())
 RETURNING * INTO s;
 RETURN private._customer_suspension_json(s);
END $$;


--
-- Name: sync_profile_is_staff(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_profile_is_staff() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id UUID;
BEGIN
  v_user_id := COALESCE(NEW.user_id, OLD.user_id);
  -- Runs as function owner → protect_profile_staff_flag allows is_staff change.
  UPDATE public.profiles p
  SET
    is_staff = EXISTS (
      SELECT 1 FROM public.staff_roles sr WHERE sr.user_id = v_user_id
    ),
    updated_at = now()
  WHERE p.id = v_user_id;
  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: take_pos_fulfillment_deposit(uuid, numeric, public.currency_code, public.payment_tender, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.take_pos_fulfillment_deposit(p_request_id uuid, p_amount numeric, p_currency public.currency_code, p_tender public.payment_tender, p_till_session_id uuid DEFAULT NULL::uuid, p_reference text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE r public.pos_fulfillment_requests%ROWTYPE; s public.pos_till_sessions%ROWTYPE; d public.pos_fulfillment_deposits%ROWTYPE;
        v_rate numeric; v_doc text; v_j uuid; v_sc uuid; v_ref text := NULLIF(trim(COALESCE(p_reference,'')),'');
BEGIN
 PERFORM public._require_sales_staff();
 SELECT * INTO r FROM public.pos_fulfillment_requests WHERE id=p_request_id FOR UPDATE;
 IF NOT FOUND OR r.status::text IN ('collected','cancelled','rejected') THEN RAISE EXCEPTION 'open back-order or transfer required'; END IF;
 IF r.customer_id IS NULL THEN RAISE EXCEPTION 'a deposit needs a registered customer on the request'; END IF;
 IF COALESCE(p_amount,0) <= 0 THEN RAISE EXCEPTION 'deposit must be more than 0'; END IF;
 IF p_tender NOT IN ('cash','bank','ecocash') THEN RAISE EXCEPTION 'take a deposit in cash, by bank transfer or EcoCash'; END IF;
 IF p_tender = 'cash' THEN
  SELECT * INTO s FROM public.pos_till_sessions WHERE id=p_till_session_id FOR UPDATE;
  IF NOT FOUND OR s.status<>'open' THEN RAISE EXCEPTION 'open till required for a cash deposit'; END IF;
  IF s.operator_user_id<>auth.uid() AND NOT public.is_pos_approver() THEN RAISE EXCEPTION 'use your own till'; END IF;
  IF s.currency<>p_currency THEN RAISE EXCEPTION 'this till counts % cash', s.currency; END IF;
 ELSIF v_ref IS NULL THEN RAISE EXCEPTION 'payment reference required for a % deposit', p_tender;
 END IF;
 v_rate := CASE WHEN p_currency='USD' THEN 1 ELSE public.get_zig_exchange_rate(CURRENT_DATE) END;
 IF v_rate IS NULL THEN RAISE EXCEPTION 'set today''s ZiG exchange rate first'; END IF;
 v_doc := public.next_series_value('DEP-');
 PERFORM public._sales_checkout_accounting_enter();
 v_j := public.post_journal_entry(CURRENT_DATE, format('Deposit %s on %s', v_doc, r.document_number), p_currency, v_rate,
   jsonb_build_array(
     jsonb_build_object('account_code', public.gl_account_for_payment_tender(p_tender), 'debit', round(p_amount,2), 'credit', 0),
     jsonb_build_object('account_code', '2200', 'debit', 0, 'credit', round(p_amount,2))));
 PERFORM public._sales_checkout_accounting_exit();
 PERFORM public._payments_rpc_enter();  -- store credit accounts change only inside the payments context
 v_sc := public._append_store_credit(r.customer_id, 'issue', round(p_amount,2), p_currency, v_rate, NULL, v_j,
   format('Deposit %s on %s', v_doc, r.document_number));
 IF p_tender = 'cash' THEN
  INSERT INTO public.pos_till_cash_movements(session_id,kind,amount,reason_code,notes,actor_user_id)
  VALUES (s.id,'cash_in',round(p_amount,2),'backorder_deposit',format('Deposit %s on %s', v_doc, r.document_number),auth.uid());
  INSERT INTO public.pos_till_session_events(session_id,event_type,actor_user_id,detail)
  VALUES (s.id,'cash_movement',auth.uid(),jsonb_build_object('kind','cash_in','amount',round(p_amount,2),'reason_code','backorder_deposit','deposit',v_doc));
 END IF;
 INSERT INTO public.pos_fulfillment_deposits(document_number,request_id,customer_id,amount,currency,exchange_rate_applied,tender,reference,till_session_id,journal_entry_id,store_credit_ledger_id,created_by)
 VALUES (v_doc,r.id,r.customer_id,round(p_amount,2),p_currency,v_rate,p_tender,v_ref,CASE WHEN p_tender='cash' THEN s.id END,v_j,v_sc,auth.uid())
 RETURNING * INTO d;
 RETURN private._pos_deposit_json(d);
EXCEPTION WHEN OTHERS THEN PERFORM public._sales_checkout_accounting_exit(); RAISE;
END $$;


--
-- Name: touch_ai_worker_schedule(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.touch_ai_worker_schedule(p_worker_key text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF auth.role() <> 'service_role'
     AND NOT public.has_staff_role(ARRAY['admin']::public.staff_role[]) THEN
    RAISE EXCEPTION 'admin or service_role required';
  END IF;
  UPDATE public.ai_worker_schedules
  SET last_run_at = now(), updated_at = now()
  WHERE worker_key = p_worker_key;
END;
$$;


