--
-- Name: trg_delivery_job_online_auto_assign(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_delivery_job_online_auto_assign() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_inv UUID;
BEGIN
  IF NEW.assignee_user_id IS NOT NULL THEN
    RETURN NEW;
  END IF;

  SELECT dn.sales_invoice_id INTO v_inv
  FROM public.delivery_notes dn
  WHERE dn.id = NEW.delivery_note_id;

  IF v_inv IS NOT NULL AND public._invoice_is_storefront_dispatch(v_inv) THEN
    BEGIN
      PERFORM public._try_auto_assign_delivery_job(NEW.id);
    EXCEPTION
      WHEN OTHERS THEN
        NULL;
    END;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: trg_pick_list_online_auto_ship(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_pick_list_online_auto_ship() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.status = 'done' AND OLD.status IS DISTINCT FROM 'done' THEN
    BEGIN
      PERFORM public._auto_ship_online_dispatch_after_pick(NEW.id);
    EXCEPTION
      WHEN OTHERS THEN
        NULL;
    END;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: trg_sales_invoice_online_dispatch_finalize(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_sales_invoice_online_dispatch_finalize() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.doc_type = 'invoice'
     AND NEW.status = 'posted'
     AND OLD.status IS DISTINCT FROM 'posted'
     AND NEW.fulfillment_mode = 'dispatch' THEN
    BEGIN
      PERFORM public._finalize_online_dispatch_order(NEW.id);
    EXCEPTION
      WHEN OTHERS THEN
        NULL;
    END;
  END IF;
  RETURN NEW;
END;
$$;


