END;
$$;


--
-- Name: update_delivery_job_status(uuid, public.delivery_job_status); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_delivery_job_status(p_delivery_job_id uuid, p_status public.delivery_job_status) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_job public.delivery_jobs%ROWTYPE;
  v_evt TEXT;
  v_token TEXT := NULL;
BEGIN
  PERFORM public._logistics_begin_rpc();
  PERFORM public._require_dispatcher_staff();

  SELECT * INTO v_job FROM public.delivery_jobs WHERE id = p_delivery_job_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'delivery job not found';
  END IF;
  IF v_job.status IN ('completed', 'failed') THEN
    RAISE EXCEPTION 'terminal delivery job cannot change status (status=%)', v_job.status;
  END IF;
  IF p_status = 'pending' THEN
    RAISE EXCEPTION 'cannot revert job to pending';
  END IF;

  IF p_status = 'completed'
     AND (v_job.pod_photo_path IS NULL OR v_job.pod_signature_path IS NULL) THEN
    RAISE EXCEPTION 'POD photo and signature required; use submit_delivery_pod';
  END IF;

  IF p_status = 'failed' THEN
    RAISE EXCEPTION 'use fail_delivery_job for failed status (reason + optional reattempt)';
  END IF;

  UPDATE public.delivery_jobs
  SET
    status = p_status,
    dispatched_at = CASE
      WHEN p_status = 'dispatched' THEN COALESCE(dispatched_at, now())
      ELSE dispatched_at
    END,
    completed_at = CASE WHEN p_status = 'completed' THEN now() ELSE completed_at END,
    failed_at = CASE WHEN p_status = 'failed' THEN now() ELSE failed_at END,
    completed_via = CASE
      WHEN p_status = 'completed' THEN COALESCE(completed_via, 'manual'::public.delivery_completed_via)
      ELSE completed_via
    END,
    updated_at = now()
  WHERE id = p_delivery_job_id;

  -- Single mint on dispatch: plaintext returned once; SMS notify uses same token.
  IF p_status = 'dispatched' THEN
    v_token := public.mint_delivery_track_token(p_delivery_job_id);
    PERFORM public._notify_out_for_delivery(p_delivery_job_id, v_token);
  END IF;

  IF p_status IN ('completed', 'failed') THEN
    UPDATE public.delivery_track_tokens
    SET revoked_at = COALESCE(revoked_at, now())
    WHERE delivery_job_id = p_delivery_job_id
      AND revoked_at IS NULL;
  END IF;

  v_evt := CASE p_status
    WHEN 'dispatched' THEN 'delivery_dispatched'
    WHEN 'completed' THEN 'delivery_completed'
    WHEN 'failed' THEN 'delivery_failed'
    ELSE NULL
  END;

  IF v_evt IS NOT NULL THEN
    PERFORM public.emit_domain_event(
      v_evt,
      'delivery_job:' || p_status::text || ':' || p_delivery_job_id::text,
      jsonb_build_object(
        'delivery_job_id', p_delivery_job_id,
        'delivery_note_id', v_job.delivery_note_id,
        'status', p_status::text
      )
    );
  END IF;

  RETURN jsonb_build_object(
    'delivery_job_id', p_delivery_job_id,
    'track_token', to_jsonb(v_token)
  );
END;
$$;


--
-- Name: FUNCTION update_delivery_job_status(p_delivery_job_id uuid, p_status public.delivery_job_status); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.update_delivery_job_status(p_delivery_job_id uuid, p_status public.delivery_job_status) IS 'Returns jsonb {delivery_job_id, track_token}. track_token is set only when transitioning to dispatched (one mint for SMS + share). Do not remint unless intentionally rotating; remint revokes the prior token.';


--
-- Name: update_item_kit(uuid, public.kit_sell_mode, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_item_kit(p_kit_id uuid, p_sell_mode public.kit_sell_mode DEFAULT NULL::public.kit_sell_mode, p_is_active boolean DEFAULT NULL::boolean, p_title text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE v_stock_item_id UUID; BEGIN PERFORM public._require_kit_staff(); UPDATE public.item_kits SET sell_mode=COALESCE(p_sell_mode,sell_mode),is_active=COALESCE(p_is_active,is_active),updated_at=now() WHERE id=p_kit_id RETURNING stock_item_id INTO v_stock_item_id; IF NOT FOUND THEN RAISE EXCEPTION 'kit not found: %',p_kit_id; END IF; IF p_title IS NOT NULL AND btrim(p_title)<>'' THEN UPDATE public.stock_items SET description=btrim(p_title) WHERE id=v_stock_item_id; END IF; RETURN p_kit_id; END; $$;


--
-- Name: update_own_customer_profile(text, text, text, text, boolean, boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_own_customer_profile(p_display_name text DEFAULT NULL::text, p_email text DEFAULT NULL::text, p_phone_e164 text DEFAULT NULL::text, p_whatsapp_e164 text DEFAULT NULL::text, p_sms_receipts boolean DEFAULT NULL::boolean, p_email_receipts boolean DEFAULT NULL::boolean, p_whatsapp_receipts boolean DEFAULT NULL::boolean) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cust UUID := public._current_customer_id();
BEGIN
  IF v_cust IS NULL THEN
    RAISE EXCEPTION 'customer profile required';
  END IF;

  UPDATE public.customers
  SET
    display_name = COALESCE(NULLIF(trim(p_display_name), ''), display_name),
    email = CASE WHEN p_email IS NULL THEN email ELSE NULLIF(trim(p_email), '') END,
    phone_e164 = CASE WHEN p_phone_e164 IS NULL THEN phone_e164 ELSE NULLIF(trim(p_phone_e164), '') END,
    whatsapp_e164 = CASE
      WHEN p_whatsapp_e164 IS NULL THEN whatsapp_e164
      ELSE NULLIF(trim(p_whatsapp_e164), '')
    END,
    sms_receipts = COALESCE(p_sms_receipts, sms_receipts),
    email_receipts = COALESCE(p_email_receipts, email_receipts),
    whatsapp_receipts = COALESCE(p_whatsapp_receipts, whatsapp_receipts),
    updated_at = now()
  WHERE id = v_cust
    AND profile_id = auth.uid();

  IF NOT FOUND THEN
    RAISE EXCEPTION 'customer row not found';
  END IF;

  RETURN v_cust;
END;
$$;


--
-- Name: update_pos_customer(uuid, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_pos_customer(p_customer_id uuid, p_customer_kind text, p_display_name text, p_business_name text DEFAULT NULL::text, p_email text DEFAULT NULL::text, p_phone_e164 text DEFAULT NULL::text, p_whatsapp_e164 text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_kind TEXT := lower(trim(COALESCE(p_customer_kind, 'individual')));
  v_name TEXT := NULLIF(trim(COALESCE(p_display_name, '')), '');
  v_business TEXT := NULLIF(trim(COALESCE(p_business_name, '')), '');
BEGIN
  PERFORM public._require_sales_staff();
  IF v_kind NOT IN ('individual', 'business') THEN RAISE EXCEPTION 'invalid customer kind'; END IF;
  IF v_name IS NULL THEN RAISE EXCEPTION 'customer display name required'; END IF;
  IF v_kind = 'business' AND v_business IS NULL THEN RAISE EXCEPTION 'business name required'; END IF;

  UPDATE public.customers SET
    customer_kind = v_kind,
    display_name = v_name,
    business_name = v_business,
    email = NULLIF(trim(COALESCE(p_email, '')), ''),
    phone_e164 = NULLIF(trim(COALESCE(p_phone_e164, '')), ''),
    whatsapp_e164 = NULLIF(trim(COALESCE(p_whatsapp_e164, '')), ''),
    updated_at = now()
  WHERE id = p_customer_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'customer not found'; END IF;
  RETURN p_customer_id;
END;
$$;


--
-- Name: update_warehouse_bin(uuid, text, integer, text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_warehouse_bin(p_bin_id uuid, p_name text DEFAULT NULL::text, p_pick_path_seq integer DEFAULT NULL::integer, p_aisle text DEFAULT NULL::text, p_rack text DEFAULT NULL::text, p_shelf text DEFAULT NULL::text, p_is_active boolean DEFAULT NULL::boolean) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM public._require_warehouse_staff();

  IF NOT EXISTS (SELECT 1 FROM public.warehouse_bins WHERE id = p_bin_id) THEN
    RAISE EXCEPTION 'bin not found';
  END IF;

  UPDATE public.warehouse_bins
  SET
    name = COALESCE(NULLIF(btrim(p_name), ''), name),
    pick_path_seq = COALESCE(p_pick_path_seq, pick_path_seq),
    aisle = CASE WHEN p_aisle IS NULL THEN aisle ELSE NULLIF(btrim(p_aisle), '') END,
    rack = CASE WHEN p_rack IS NULL THEN rack ELSE NULLIF(btrim(p_rack), '') END,
    shelf = CASE WHEN p_shelf IS NULL THEN shelf ELSE NULLIF(btrim(p_shelf), '') END,
    is_active = COALESCE(p_is_active, is_active),
    updated_at = now()
  WHERE id = p_bin_id;

  RETURN p_bin_id;
END;
$$;


--
-- Name: upsert_customer_address(uuid, text, text, text, text, text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_customer_address(p_id uuid DEFAULT NULL::uuid, p_label text DEFAULT ''::text, p_line1 text DEFAULT NULL::text, p_line2 text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_province text DEFAULT NULL::text, p_postal_code text DEFAULT NULL::text, p_country text DEFAULT 'Zimbabwe'::text, p_is_default boolean DEFAULT false) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cust UUID := public._current_customer_id();
  v_id UUID;
BEGIN
  IF v_cust IS NULL THEN
    RAISE EXCEPTION 'customer profile required';
  END IF;
  IF p_line1 IS NULL OR length(trim(p_line1)) = 0 THEN
    RAISE EXCEPTION 'line1 required';
  END IF;

  IF COALESCE(p_is_default, false) THEN
    UPDATE public.customer_addresses
    SET is_default = false, updated_at = now()
    WHERE customer_id = v_cust AND is_default
      AND (p_id IS NULL OR id IS DISTINCT FROM p_id);
  END IF;

  IF p_id IS NOT NULL THEN
    UPDATE public.customer_addresses
    SET
      label = COALESCE(p_label, label),
      line1 = trim(p_line1),
      line2 = p_line2,
      city = p_city,
      province = p_province,
      postal_code = p_postal_code,
      country = COALESCE(NULLIF(trim(p_country), ''), country),
      is_default = COALESCE(p_is_default, is_default),
      updated_at = now()
    WHERE id = p_id AND customer_id = v_cust
    RETURNING id INTO v_id;

    IF v_id IS NULL THEN
      RAISE EXCEPTION 'address not found';
    END IF;
    RETURN v_id;
  END IF;

  INSERT INTO public.customer_addresses (
    customer_id, label, line1, line2, city, province, postal_code, country, is_default
  )
  VALUES (
    v_cust,
    COALESCE(p_label, ''),
    trim(p_line1),
    p_line2,
    p_city,
    p_province,
    p_postal_code,
    COALESCE(NULLIF(trim(p_country), ''), 'Zimbabwe'),
    COALESCE(p_is_default, false)
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


--
-- Name: upsert_customer_garage_vehicle(uuid, text, text, text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_customer_garage_vehicle(p_id uuid DEFAULT NULL::uuid, p_make text DEFAULT NULL::text, p_model text DEFAULT NULL::text, p_generation text DEFAULT NULL::text, p_engine text DEFAULT NULL::text, p_vin text DEFAULT NULL::text, p_is_primary boolean DEFAULT false) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cust UUID := public._current_customer_id();
  v_id UUID;
BEGIN
  IF v_cust IS NULL THEN
    RAISE EXCEPTION 'customer profile required';
  END IF;

  IF COALESCE(p_is_primary, false) THEN
    UPDATE public.customer_garage_vehicles
    SET is_primary = false, updated_at = now()
    WHERE customer_id = v_cust AND is_primary
      AND (p_id IS NULL OR id IS DISTINCT FROM p_id);
  END IF;

  IF p_id IS NOT NULL THEN
    UPDATE public.customer_garage_vehicles
    SET
      make = COALESCE(p_make, make),
      model = COALESCE(p_model, model),
      generation = COALESCE(p_generation, generation),
      engine = COALESCE(p_engine, engine),
      vin = COALESCE(p_vin, vin),
      is_primary = COALESCE(p_is_primary, is_primary),
      updated_at = now()
    WHERE id = p_id AND customer_id = v_cust
    RETURNING id INTO v_id;

    IF v_id IS NULL THEN
      RAISE EXCEPTION 'garage vehicle not found';
    END IF;
    RETURN v_id;
  END IF;

  INSERT INTO public.customer_garage_vehicles (
    customer_id, make, model, generation, engine, vin, is_primary
  )
  VALUES (
    v_cust, p_make, p_model, p_generation, p_engine, p_vin, COALESCE(p_is_primary, false)
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


--
-- Name: upsert_fleet_vehicle(text, text, public.fleet_vehicle_status, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_fleet_vehicle(p_plate text, p_label text DEFAULT NULL::text, p_status public.fleet_vehicle_status DEFAULT 'active'::public.fleet_vehicle_status, p_assigned_driver_user_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text, p_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_plate TEXT;
  v_id UUID;
BEGIN
  PERFORM public._fleet_begin_rpc();
  PERFORM public._require_fleet_staff();

  v_plate := public._normalize_fleet_plate(p_plate);
  IF v_plate IS NULL OR length(v_plate) = 0 THEN
    RAISE EXCEPTION 'plate is required';
  END IF;

  PERFORM public._assert_fleet_driver_assignee(p_assigned_driver_user_id);

  IF p_id IS NULL THEN
    IF EXISTS (SELECT 1 FROM public.fleet_vehicles WHERE plate = v_plate) THEN
      RAISE EXCEPTION 'fleet plate already exists: %', v_plate;
    END IF;

    INSERT INTO public.fleet_vehicles (
      plate, label, status, assigned_driver_user_id, notes, created_by
    )
    VALUES (
      v_plate,
      NULLIF(trim(p_label), ''),
      COALESCE(p_status, 'active'::public.fleet_vehicle_status),
      p_assigned_driver_user_id,
      NULLIF(trim(p_notes), ''),
      auth.uid()
    )
    RETURNING id INTO v_id;
  ELSE
    IF NOT EXISTS (SELECT 1 FROM public.fleet_vehicles WHERE id = p_id) THEN
      RAISE EXCEPTION 'fleet vehicle not found';
    END IF;
    IF EXISTS (
      SELECT 1 FROM public.fleet_vehicles
      WHERE plate = v_plate AND id IS DISTINCT FROM p_id
    ) THEN
      RAISE EXCEPTION 'fleet plate already exists: %', v_plate;
    END IF;

    UPDATE public.fleet_vehicles
    SET
      plate = v_plate,
      label = NULLIF(trim(p_label), ''),
      status = COALESCE(p_status, status),
      assigned_driver_user_id = p_assigned_driver_user_id,
      notes = NULLIF(trim(p_notes), '')
    WHERE id = p_id
    RETURNING id INTO v_id;
  END IF;

  RETURN v_id;
END;
$$;


--
-- Name: upsert_pos_card_terminal(uuid, text, text, text, text, text, jsonb, uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_pos_card_terminal(p_id uuid, p_code text, p_label text, p_acquirer_name text, p_external_terminal_id text, p_adapter_key text, p_adapter_config jsonb, p_warehouse_id uuid, p_device_id text, p_is_active boolean) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_id UUID; v_bad TEXT; v_allowed TEXT[]:=ARRAY[
 'package_name','purchase_action','refund_action','status_action','reversal_action',
 'amount_minor_key','currency_key','reference_key','operation_key','original_transaction_id_key',
 'result_status_key','result_transaction_id_key','result_rrn_key','result_auth_code_key',
 'result_last4_key','result_scheme_key','result_response_code_key','result_response_message_key'
];
BEGIN
 IF NOT public.has_staff_role(ARRAY['admin']::public.staff_role[]) THEN RAISE EXCEPTION 'admin role required'; END IF;
 IF trim(COALESCE(p_code,''))='' OR trim(COALESCE(p_label,''))='' THEN RAISE EXCEPTION 'terminal code and label required'; END IF;
 IF COALESCE(p_adapter_key,'')<>'android_intent_v1' THEN RAISE EXCEPTION 'unsupported terminal adapter'; END IF;
 SELECT k INTO v_bad FROM jsonb_object_keys(COALESCE(p_adapter_config,'{}'::jsonb)) AS x(k)
 WHERE NOT(k=ANY(v_allowed)) LIMIT 1;
 IF v_bad IS NOT NULL THEN RAISE EXCEPTION 'unsupported or sensitive terminal config key: %',v_bad; END IF;
 IF trim(COALESCE(p_adapter_config->>'package_name',''))='' OR trim(COALESCE(p_adapter_config->>'purchase_action',''))='' THEN
  RAISE EXCEPTION 'android intent terminal requires package_name and purchase_action';
 END IF;
 IF p_warehouse_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.warehouses WHERE id=p_warehouse_id AND is_active) THEN RAISE EXCEPTION 'active warehouse required'; END IF;
 INSERT INTO public.pos_card_terminals(id,code,label,acquirer_name,external_terminal_id,adapter_key,adapter_config,warehouse_id,device_id,is_active,created_by,updated_by)
 VALUES(COALESCE(p_id,gen_random_uuid()),trim(p_code),trim(p_label),NULLIF(trim(COALESCE(p_acquirer_name,'')),''),NULLIF(trim(COALESCE(p_external_terminal_id,'')),''),p_adapter_key,COALESCE(p_adapter_config,'{}'::jsonb),p_warehouse_id,NULLIF(trim(COALESCE(p_device_id,'')),''),COALESCE(p_is_active,true),auth.uid(),auth.uid())
 ON CONFLICT(code) DO UPDATE SET label=EXCLUDED.label,acquirer_name=EXCLUDED.acquirer_name,external_terminal_id=EXCLUDED.external_terminal_id,
  adapter_key=EXCLUDED.adapter_key,adapter_config=EXCLUDED.adapter_config,warehouse_id=EXCLUDED.warehouse_id,device_id=EXCLUDED.device_id,
  is_active=EXCLUDED.is_active,updated_by=auth.uid(),updated_at=now()
 RETURNING id INTO v_id;
 RETURN v_id;
END $$;


--
-- Name: upsert_pos_customer_garage_vehicle(uuid, uuid, text, text, text, text, text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_pos_customer_garage_vehicle(p_customer_id uuid, p_vehicle_id uuid DEFAULT NULL::uuid, p_model_slug text DEFAULT NULL::text, p_make text DEFAULT 'Nissan'::text, p_model text DEFAULT NULL::text, p_generation text DEFAULT NULL::text, p_chassis_code text DEFAULT NULL::text, p_engine text DEFAULT NULL::text, p_vin text DEFAULT NULL::text, p_is_primary boolean DEFAULT false) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id UUID := COALESCE(p_vehicle_id, gen_random_uuid());
BEGIN
  PERFORM public._require_sales_staff();
  IF NOT EXISTS (SELECT 1 FROM public.customers WHERE id = p_customer_id) THEN
    RAISE EXCEPTION 'customer not found';
  END IF;
  IF NULLIF(trim(COALESCE(p_model_slug, '')), '') IS NULL
     OR NULLIF(trim(COALESCE(p_model, '')), '') IS NULL
     OR NULLIF(trim(COALESCE(p_generation, '')), '') IS NULL
     OR NULLIF(trim(COALESCE(p_chassis_code, '')), '') IS NULL
     OR NULLIF(trim(COALESCE(p_engine, '')), '') IS NULL THEN
    RAISE EXCEPTION 'canonical model/generation/chassis/engine required';
  END IF;

  IF p_is_primary THEN
    UPDATE public.customer_garage_vehicles SET is_primary = FALSE, updated_at = now()
    WHERE customer_id = p_customer_id AND is_primary;
  END IF;

  INSERT INTO public.customer_garage_vehicles (
    id, customer_id, make, model_slug, model, generation, chassis_code, engine, vin, is_primary
  ) VALUES (
    v_id, p_customer_id, NULLIF(trim(COALESCE(p_make, '')), ''), trim(p_model_slug), trim(p_model),
    trim(p_generation), trim(p_chassis_code), trim(p_engine), NULLIF(trim(COALESCE(p_vin, '')), ''), p_is_primary
  )
  ON CONFLICT (id) DO UPDATE SET
    make = EXCLUDED.make,
    model_slug = EXCLUDED.model_slug,
    model = EXCLUDED.model,
    generation = EXCLUDED.generation,
    chassis_code = EXCLUDED.chassis_code,
    engine = EXCLUDED.engine,
    vin = EXCLUDED.vin,
    is_primary = EXCLUDED.is_primary,
    updated_at = now()
  WHERE public.customer_garage_vehicles.customer_id = p_customer_id;

  IF NOT FOUND THEN RAISE EXCEPTION 'garage vehicle not found for customer'; END IF;
  RETURN v_id;
END;
$$;


--
-- Name: FUNCTION upsert_pos_customer_garage_vehicle(p_customer_id uuid, p_vehicle_id uuid, p_model_slug text, p_make text, p_model text, p_generation text, p_chassis_code text, p_engine text, p_vin text, p_is_primary boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.upsert_pos_customer_garage_vehicle(p_customer_id uuid, p_vehicle_id uuid, p_model_slug text, p_make text, p_model text, p_generation text, p_chassis_code text, p_engine text, p_vin text, p_is_primary boolean) IS 'Sales-staff garage maintenance with canonical EPC fitment identifiers.';


--
-- Name: upsert_pos_popular_pin(text, text, text, text, text, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_pos_popular_pin(p_item_type text, p_item_key text, p_label text, p_subtitle text DEFAULT NULL::text, p_search_query text DEFAULT NULL::text, p_maker_slug text DEFAULT NULL::text, p_model_slug text DEFAULT NULL::text, p_category_name text DEFAULT NULL::text, p_subcategory_name text DEFAULT NULL::text, p_oem_part_number text DEFAULT NULL::text, p_image_url text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id uuid;
  v_type text := lower(trim(COALESCE(p_item_type, '')));
  v_key text := trim(COALESCE(p_item_key, ''));
  v_label text := trim(COALESCE(p_label, ''));
  v_query text := trim(COALESCE(p_search_query, p_label, ''));
  v_image text := NULLIF(trim(COALESCE(p_image_url, '')), '');
BEGIN
  PERFORM public._require_sales_staff();
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authenticated staff required'; END IF;
  IF v_type NOT IN ('part','model','category','subcategory') THEN RAISE EXCEPTION 'unsupported popular item type'; END IF;
  IF v_key = '' OR v_label = '' OR v_query = '' THEN RAISE EXCEPTION 'item key, label and search query required'; END IF;

  IF v_image IS NULL AND v_type = 'part' AND NULLIF(trim(COALESCE(p_oem_part_number,'')), '') IS NOT NULL THEN
    SELECT sii.storage_path INTO v_image
    FROM public.stock_items si
    JOIN public.stock_item_images sii ON sii.stock_item_id = si.id
    WHERE si.oem_part_number = trim(p_oem_part_number)
    ORDER BY sii.is_primary DESC, sii.sort_order, sii.created_at
    LIMIT 1;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.pos_operator_popular_pins
    WHERE user_id = auth.uid() AND item_type = v_type AND item_key = v_key
  ) AND (
    SELECT count(*) FROM public.pos_operator_popular_pins WHERE user_id = auth.uid()
  ) >= 24 THEN
    RAISE EXCEPTION 'popular item pin limit reached (24)';
  END IF;

  INSERT INTO public.pos_operator_popular_pins (
    user_id, item_type, item_key, label, subtitle, search_query,
    maker_slug, model_slug, category_name, subcategory_name, oem_part_number, image_url
  ) VALUES (
    auth.uid(), v_type, v_key, v_label, NULLIF(trim(COALESCE(p_subtitle,'')),''), v_query,
    NULLIF(trim(COALESCE(p_maker_slug,'')),''), NULLIF(trim(COALESCE(p_model_slug,'')),''),
    NULLIF(trim(COALESCE(p_category_name,'')),''), NULLIF(trim(COALESCE(p_subcategory_name,'')),''),
    NULLIF(trim(COALESCE(p_oem_part_number,'')),''), v_image
  )
  ON CONFLICT (user_id, item_type, item_key) DO UPDATE SET
    label = EXCLUDED.label,
    subtitle = EXCLUDED.subtitle,
    search_query = EXCLUDED.search_query,
    maker_slug = EXCLUDED.maker_slug,
    model_slug = EXCLUDED.model_slug,
    category_name = EXCLUDED.category_name,
    subcategory_name = EXCLUDED.subcategory_name,
    oem_part_number = EXCLUDED.oem_part_number,
    image_url = EXCLUDED.image_url,
    updated_at = now()
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$$;


--
-- Name: upsert_preferred_supplier(text, text, text, text, public.currency_code, text, text, text, text, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_preferred_supplier(p_code text, p_name text, p_email text DEFAULT NULL::text, p_phone_e164 text DEFAULT NULL::text, p_currency public.currency_code DEFAULT 'USD'::public.currency_code, p_notes text DEFAULT NULL::text, p_address text DEFAULT NULL::text, p_tax_id text DEFAULT NULL::text, p_payment_terms text DEFAULT NULL::text, p_categories text[] DEFAULT '{}'::text[]) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_id UUID;
BEGIN
 IF NOT public.has_staff_role(ARRAY['admin','warehouse','finance']::public.staff_role[]) THEN RAISE EXCEPTION 'not authorized'; END IF;
 INSERT INTO public.suppliers(code,name,email,phone_e164,default_currency,is_active,is_preferred,relationship_notes,address_text,tax_id,payment_terms,product_categories,updated_at)
 VALUES(upper(trim(p_code)),trim(p_name),p_email,p_phone_e164,p_currency,true,true,p_notes,p_address,p_tax_id,p_payment_terms,COALESCE(p_categories,'{}'),now())
 ON CONFLICT(code) DO UPDATE SET name=EXCLUDED.name,email=EXCLUDED.email,phone_e164=EXCLUDED.phone_e164,default_currency=EXCLUDED.default_currency,is_active=true,is_preferred=true,relationship_notes=EXCLUDED.relationship_notes,address_text=EXCLUDED.address_text,tax_id=EXCLUDED.tax_id,payment_terms=EXCLUDED.payment_terms,product_categories=EXCLUDED.product_categories,updated_at=now()
 RETURNING id INTO v_id;
 RETURN v_id;
END;$$;


--
-- Name: upsert_salary_structure(uuid, public.salary_pay_type, numeric, public.currency_code, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_salary_structure(p_employee_id uuid, p_pay_type public.salary_pay_type, p_rate numeric, p_currency public.currency_code, p_effective_from date, p_effective_to date DEFAULT NULL::date) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id UUID;
BEGIN
  PERFORM public._require_hr_staff();

  IF NOT EXISTS (SELECT 1 FROM public.employees WHERE id = p_employee_id) THEN
    RAISE EXCEPTION 'employee not found: %', p_employee_id;
  END IF;
  IF p_rate IS NULL OR p_rate < 0 THEN
    RAISE EXCEPTION 'rate must be >= 0';
  END IF;
  IF p_effective_from IS NULL THEN
    RAISE EXCEPTION 'effective_from required';
  END IF;

  -- Close overlapping active structures ending after new start
  UPDATE public.salary_structures
  SET is_active = false,
      effective_to = COALESCE(effective_to, p_effective_from - 1)
  WHERE employee_id = p_employee_id
    AND is_active
    AND effective_from <= COALESCE(p_effective_to, '9999-12-31'::date)
    AND COALESCE(effective_to, '9999-12-31'::date) >= p_effective_from;

  INSERT INTO public.salary_structures (
    employee_id, pay_type, rate, currency, effective_from, effective_to, is_active
  )
  VALUES (
    p_employee_id, p_pay_type, p_rate, p_currency, p_effective_from, p_effective_to, true
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


--
-- Name: upsert_staff_product_page(uuid, numeric, text, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_staff_product_page(p_stock_item_id uuid, p_unit_price numeric, p_discount_kind text DEFAULT 'none'::text, p_discount_value numeric DEFAULT 0, p_discount_description text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_list UUID; v_kind TEXT:=lower(trim(COALESCE(p_discount_kind,'none'))); v_value NUMERIC:=COALESCE(p_discount_value,0); v_desc TEXT:=NULLIF(trim(COALESCE(p_discount_description,'')),'');
BEGIN
 IF NOT public.has_staff_role(ARRAY['admin','sales','warehouse']::public.staff_role[]) THEN RAISE EXCEPTION 'staff role required'; END IF;
 IF p_stock_item_id IS NULL THEN RAISE EXCEPTION 'stock_item_id required'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.stock_items WHERE id=p_stock_item_id) THEN RAISE EXCEPTION 'unknown stock_item_id'; END IF;
 IF p_unit_price IS NULL OR p_unit_price<0 THEN RAISE EXCEPTION 'unit_price must be >= 0'; END IF;
 IF v_kind NOT IN('none','percent','amount') THEN RAISE EXCEPTION 'discount_kind must be none|percent|amount'; END IF;
 IF v_kind='none' THEN v_value:=0; v_desc:=NULL; ELSIF v_kind='percent' AND (v_value<0 OR v_value>100) THEN RAISE EXCEPTION 'percent discount must be 0..100'; ELSIF v_kind='amount' AND v_value<0 THEN RAISE EXCEPTION 'amount discount must be >= 0'; END IF;
 IF v_kind<>'none' AND v_desc IS NULL THEN RAISE EXCEPTION 'discount_description required when discount is set'; END IF;
 SELECT id INTO v_list FROM public.price_lists WHERE is_active AND (is_default OR code='RETAIL') ORDER BY is_default DESC,code LIMIT 1;
 IF v_list IS NULL THEN RAISE EXCEPTION 'no active default/retail price list'; END IF;
 INSERT INTO public.price_list_items(price_list_id,stock_item_id,unit_price,core_charge) VALUES(v_list,p_stock_item_id,p_unit_price,0) ON CONFLICT(price_list_id,stock_item_id) DO UPDATE SET unit_price=EXCLUDED.unit_price;
 INSERT INTO public.stock_item_shop_merch(stock_item_id,discount_kind,discount_value,discount_description,updated_at,updated_by) VALUES(p_stock_item_id,v_kind,v_value,v_desc,now(),auth.uid()) ON CONFLICT(stock_item_id) DO UPDATE SET discount_kind=EXCLUDED.discount_kind,discount_value=EXCLUDED.discount_value,discount_description=EXCLUDED.discount_description,updated_at=now(),updated_by=auth.uid();
 RETURN p_stock_item_id;
END;$$;


--
-- Name: upsert_stock_reconciliation_lines(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_stock_reconciliation_lines(p_reconciliation_id uuid, p_lines jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_status public.stock_entry_status;
  v_line JSONB;
  v_item UUID;
  v_counted NUMERIC;
  v_updated INT := 0;
BEGIN
  PERFORM public._recon_begin_rpc();
  PERFORM public._require_warehouse_staff();

  SELECT status INTO v_status
  FROM public.stock_reconciliations
  WHERE id = p_reconciliation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'reconciliation not found: %', p_reconciliation_id;
  END IF;
  IF v_status <> 'draft' THEN
    RAISE EXCEPTION 'lines editable only while draft (status=%)', v_status;
  END IF;

  IF p_lines IS NULL OR jsonb_typeof(p_lines) <> 'array' OR jsonb_array_length(p_lines) = 0 THEN
    RAISE EXCEPTION 'lines required';
  END IF;

  FOR v_line IN SELECT * FROM jsonb_array_elements(p_lines)
  LOOP
    v_item := (v_line ->> 'stock_item_id')::uuid;
    v_counted := (v_line ->> 'counted_qty')::numeric;

    IF v_counted IS NULL OR v_counted < 0 THEN
      RAISE EXCEPTION 'counted_qty required and must be >= 0 for item %', v_item;
    END IF;

    UPDATE public.stock_reconciliation_lines
    SET counted_qty = v_counted
    WHERE stock_reconciliation_id = p_reconciliation_id
      AND stock_item_id = v_item;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'item % not on reconciliation draft', v_item;
    END IF;

    v_updated := v_updated + 1;
  END LOOP;

  RETURN v_updated;
END;
$$;


--
-- Name: upsert_supplier_quotation(uuid, public.currency_code, numeric, jsonb, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_supplier_quotation(p_rfq_id uuid, p_currency public.currency_code, p_exchange_rate numeric, p_lines jsonb, p_valid_until date DEFAULT NULL::date, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_supplier UUID;
  v_rfq_st public.procurement_doc_status;
  v_sq UUID;
  v_st public.procurement_doc_status;
  v_line JSONB;
  v_no INT := 0;
  v_rate NUMERIC;
BEGIN
  PERFORM public._procurement_begin_rpc();
  v_supplier := public.current_supplier_id();
  IF v_supplier IS NULL THEN
    RAISE EXCEPTION 'supplier profile required';
  END IF;

  SELECT status INTO v_rfq_st FROM public.rfqs WHERE id = p_rfq_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'RFQ not found: %', p_rfq_id;
  END IF;
  IF v_rfq_st <> 'submitted' THEN
    RAISE EXCEPTION 'RFQ must be submitted before quoting';
  END IF;

  PERFORM public._assert_supplier_invited_to_rfq(p_rfq_id, v_supplier);

  IF p_lines IS NULL OR jsonb_array_length(p_lines) = 0 THEN
    RAISE EXCEPTION 'quotation lines required';
  END IF;

  v_rate := CASE
    WHEN p_currency = 'USD' THEN COALESCE(p_exchange_rate, 1)
    ELSE p_exchange_rate
  END;
  IF p_currency = 'ZIG' AND (v_rate IS NULL OR v_rate <= 0) THEN
    RAISE EXCEPTION 'positive exchange_rate required for ZIG';
  END IF;

  SELECT id, status INTO v_sq, v_st
  FROM public.supplier_quotations
  WHERE rfq_id = p_rfq_id AND supplier_id = v_supplier;

  IF v_sq IS NULL THEN
    INSERT INTO public.supplier_quotations (
      document_number, rfq_id, supplier_id, currency, exchange_rate_applied, valid_until, notes
    )
    VALUES (
      public.next_series_value('SQ-'), p_rfq_id, v_supplier, p_currency, v_rate, p_valid_until, p_notes
    )
    RETURNING id INTO v_sq;
  ELSE
    IF v_st <> 'draft' THEN
      RAISE EXCEPTION 'only draft quotations can be edited';
    END IF;
    UPDATE public.supplier_quotations
    SET
      currency = p_currency,
      exchange_rate_applied = v_rate,
      valid_until = p_valid_until,
      notes = COALESCE(p_notes, notes),
      updated_at = now()
    WHERE id = v_sq;
    DELETE FROM public.supplier_quotation_lines WHERE supplier_quotation_id = v_sq;
  END IF;

  FOR v_line IN SELECT * FROM jsonb_array_elements(p_lines)
  LOOP
    v_no := v_no + 1;
    INSERT INTO public.supplier_quotation_lines (
      supplier_quotation_id, line_no, rfq_line_id, stock_item_id, uom_id, qty, unit_price, currency
    )
    VALUES (
      v_sq,
      v_no,
      NULLIF(v_line ->> 'rfq_line_id', '')::uuid,
      (v_line ->> 'stock_item_id')::uuid,
      (v_line ->> 'uom_id')::uuid,
      (v_line ->> 'qty')::numeric,
      (v_line ->> 'unit_price')::numeric,
      COALESCE((v_line ->> 'currency')::public.currency_code, p_currency)
    );
  END LOOP;

  PERFORM public._procurement_end_rpc();
  RETURN v_sq;
EXCEPTION
  WHEN OTHERS THEN
    PERFORM public._procurement_end_rpc();
    RAISE;
END;
$$;


--
-- Name: verify_auth_challenge(text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_auth_challenge(p_kind text, p_channel text, p_identifier text, p_code_hash text, p_ip_hash text DEFAULT NULL::text, p_device_hash text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_kind text := lower(trim(coalesce(p_kind,'')));
  v_channel text := lower(trim(coalesce(p_channel,'')));
  v_identifier text := lower(trim(coalesce(p_identifier,'')));
  v_now timestamptz := clock_timestamp();
  v_id uuid;
  v_hash text;
  v_attempts integer;
begin
  if auth.role() is distinct from 'service_role' then raise exception 'service_role required'; end if;
  if v_kind not in ('auth_otp','password_reset') then raise exception 'invalid challenge kind'; end if;
  if v_channel not in ('email','phone') then raise exception 'invalid challenge channel'; end if;
  if v_identifier='' or coalesce(trim(p_code_hash),'')='' then raise exception 'identifier/code hash required'; end if;

  perform public._consume_auth_rate_limit(v_kind||':verify:identifier',v_channel||':'||v_identifier,20,900);
  if coalesce(trim(p_ip_hash),'')<>'' then perform public._consume_auth_rate_limit(v_kind||':verify:ip',trim(p_ip_hash),60,900); end if;
  if coalesce(trim(p_device_hash),'')<>'' then perform public._consume_auth_rate_limit(v_kind||':verify:device',trim(p_device_hash),40,900); end if;
  perform public._consume_auth_rate_limit(v_kind||':verify:global','global',1200,60);

  perform pg_advisory_xact_lock(hashtextextended(v_kind||':'||v_channel||':'||v_identifier,0));

  if v_kind='auth_otp' then
    select id,code_hash,attempt_count into v_id,v_hash,v_attempts
      from public.auth_otp_challenges
      where channel=v_channel and identifier=v_identifier and consumed_at is null and expires_at>v_now
      order by created_at desc limit 1 for update;
  else
    select id,code_hash,attempt_count into v_id,v_hash,v_attempts
      from public.password_reset_challenges
      where channel=v_channel and identifier=v_identifier and consumed_at is null and expires_at>v_now
      order by created_at desc limit 1 for update;
  end if;

  if v_id is null then raise exception 'AUTH_CHALLENGE_INVALID_OR_EXPIRED'; end if;
  if coalesce(v_attempts,0)>=5 then raise exception 'AUTH_CHALLENGE_ATTEMPTS_EXCEEDED'; end if;

  if v_hash is distinct from p_code_hash then
    if v_kind='auth_otp' then
      update public.auth_otp_challenges set attempt_count=attempt_count+1 where id=v_id;
    else
      update public.password_reset_challenges set attempt_count=attempt_count+1 where id=v_id;
    end if;
    raise exception 'AUTH_CHALLENGE_INVALID_OR_EXPIRED';
  end if;

  if v_kind='auth_otp' then
    update public.auth_otp_challenges set consumed_at=v_now where id=v_id and consumed_at is null;
    update public.auth_otp_challenges set expires_at=least(expires_at,v_now)
      where channel=v_channel and identifier=v_identifier and id<>v_id and consumed_at is null and expires_at>v_now;
  else
    update public.password_reset_challenges set consumed_at=v_now where id=v_id and consumed_at is null;
    update public.password_reset_challenges set expires_at=least(expires_at,v_now)
      where channel=v_channel and identifier=v_identifier and id<>v_id and consumed_at is null and expires_at>v_now;
  end if;

  return v_id;
end;
$$;


--
-- Name: verify_delivery_pod_otp(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_delivery_pod_otp(p_delivery_job_id uuid, p_code text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_job public.delivery_jobs%ROWTYPE;
  v_uid UUID := auth.uid();
  v_allowed BOOLEAN := false;
  v_otp public.delivery_pod_otps%ROWTYPE;
  v_hash TEXT;
BEGIN
  PERFORM public._logistics_begin_rpc();

  IF p_code IS NULL OR length(trim(p_code)) = 0 THEN
    RAISE EXCEPTION 'OTP code required';
  END IF;

  SELECT * INTO v_job FROM public.delivery_jobs WHERE id = p_delivery_job_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'delivery job not found';
  END IF;

  IF auth.role() = 'service_role'
     OR public.has_staff_role(
       ARRAY['admin', 'warehouse', 'dispatcher']::public.staff_role[]
     ) THEN
    v_allowed := true;
  ELSIF v_uid IS NOT NULL
        AND v_job.assignee_user_id = v_uid
        AND public.has_staff_role(ARRAY['driver']::public.staff_role[]) THEN
    v_allowed := true;
  END IF;

  IF NOT v_allowed THEN
    RAISE EXCEPTION 'assigned driver or dispatcher/warehouse/admin required to verify POD OTP';
  END IF;

  SELECT * INTO v_otp
  FROM public.delivery_pod_otps
  WHERE delivery_job_id = p_delivery_job_id
    AND verified_at IS NULL
    AND expires_at > now()
  ORDER BY created_at DESC
  LIMIT 1
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'no active POD OTP for job';
  END IF;

  IF v_otp.attempts >= v_otp.max_attempts THEN
    RAISE EXCEPTION 'POD OTP max attempts exceeded';
  END IF;

  v_hash := public._hash_delivery_pod_otp(p_code);
  IF v_hash IS DISTINCT FROM v_otp.code_hash THEN
    UPDATE public.delivery_pod_otps
    SET attempts = attempts + 1
    WHERE id = v_otp.id;
    RAISE EXCEPTION 'invalid POD OTP';
  END IF;

  UPDATE public.delivery_pod_otps
  SET verified_at = now()
  WHERE id = v_otp.id;

  RETURN true;
END;
$$;


--
-- Name: void_pos_cart(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.void_pos_cart(p_cart_id uuid, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cart public.pos_carts%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not authenticated';
  END IF;
  IF NOT public.is_pos_approver() THEN
    RAISE EXCEPTION 'admin or shop manager approval required';
  END IF;

  PERFORM public._require_cart_mutate(p_cart_id);
  SELECT * INTO v_cart FROM public.pos_carts WHERE id = p_cart_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'cart not found: %', p_cart_id;
  END IF;
  IF v_cart.status NOT IN ('open', 'parked') THEN
    RAISE EXCEPTION 'only open or parked carts can be voided (got %)', v_cart.status;
  END IF;

  UPDATE public.pos_carts
  SET status = 'abandoned', updated_at = now()
  WHERE id = p_cart_id;

  PERFORM public._log_pos_action(
    'cart_voided',
    'pos_carts',
    p_cart_id,
    jsonb_build_object('status', v_cart.status),
    jsonb_build_object('status', 'abandoned'),
    p_notes
  );

  RETURN p_cart_id;
END;
$$;


--
-- Name: void_pos_cart_governed(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.void_pos_cart_governed(p_cart_id uuid, p_reason_code text, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v UUID;
BEGIN
 PERFORM private.require_pos_reason('void_cart',p_reason_code);
 IF public.pos_action_requires_manager('void_cart',0) AND NOT public.is_pos_approver() THEN RAISE EXCEPTION 'POS manager approval required'; END IF;
 v:=public.void_pos_cart(p_cart_id,concat_ws(' · ',p_reason_code,p_notes));
 UPDATE public.pos_action_audit SET reason_code=p_reason_code,approved_by_user_id=CASE WHEN public.is_pos_approver() THEN auth.uid() ELSE NULL END,approval_policy_action='void_cart'
 WHERE id=(SELECT id FROM public.pos_action_audit WHERE entity_type='pos_carts' AND entity_id=p_cart_id ORDER BY created_at DESC LIMIT 1);
 RETURN v;
END $$;


--
-- Name: wishlist_move_to_cart(uuid, numeric, boolean, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wishlist_move_to_cart(p_cart_id uuid, p_qty numeric DEFAULT 1, p_remove_from_wishlist boolean DEFAULT true, p_stock_item_id uuid DEFAULT NULL::uuid, p_oem_part_number text DEFAULT NULL::text, p_wishlist_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cust UUID := public._current_customer_id();
  v_item UUID;
  v_wish UUID;
  v_uom UUID;
  v_line UUID;
BEGIN
  IF v_cust IS NULL THEN
    RAISE EXCEPTION 'customer profile required';
  END IF;
  IF p_cart_id IS NULL THEN
    RAISE EXCEPTION 'cart_id required (create_customer_cart first)';
  END IF;
  IF p_qty IS NULL OR p_qty <= 0 THEN
    RAISE EXCEPTION 'qty must be > 0';
  END IF;

  IF p_wishlist_id IS NOT NULL THEN
    SELECT id, stock_item_id INTO v_wish, v_item
    FROM public.customer_wishlist_items
    WHERE id = p_wishlist_id AND customer_id = v_cust;
    IF v_wish IS NULL THEN
      RAISE EXCEPTION 'wishlist item not found';
    END IF;
  ELSE
    v_item := public._resolve_customer_stock_item(p_stock_item_id, p_oem_part_number);
    SELECT id INTO v_wish
    FROM public.customer_wishlist_items
    WHERE customer_id = v_cust AND stock_item_id = v_item;
  END IF;

  SELECT base_uom_id INTO v_uom
  FROM public.stock_items
  WHERE id = v_item;
  IF v_uom IS NULL THEN
    RAISE EXCEPTION 'stock item missing base_uom_id';
  END IF;

  v_line := public.add_customer_cart_line(p_cart_id, v_item, v_uom, p_qty);

  IF p_remove_from_wishlist AND v_wish IS NOT NULL THEN
    DELETE FROM public.customer_wishlist_items
    WHERE id = v_wish AND customer_id = v_cust;
  END IF;

  RETURN v_line;
END;
$$;


--
-- Name: FUNCTION wishlist_move_to_cart(p_cart_id uuid, p_qty numeric, p_remove_from_wishlist boolean, p_stock_item_id uuid, p_oem_part_number text, p_wishlist_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.wishlist_move_to_cart(p_cart_id uuid, p_qty numeric, p_remove_from_wishlist boolean, p_stock_item_id uuid, p_oem_part_number text, p_wishlist_id uuid) IS 'Thin atomic helper: add_customer_cart_line then optional wishlist delete. Prefer compose when no remove needed.';


--
-- Name: write_off_driver_cash_shortage(uuid, numeric, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.write_off_driver_cash_shortage(p_handin_id uuid, p_amount numeric, p_reason_code text, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE h public.driver_cash_handins%ROWTYPE; v_j uuid; v_out numeric; v_rc record;
BEGIN
 IF NOT public.is_pos_approver() THEN RAISE EXCEPTION 'POS manager approval required'; END IF;
 SELECT * INTO h FROM public.driver_cash_handins WHERE id=p_handin_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'hand-in not found'; END IF;
 IF h.driver_user_id=auth.uid() THEN RAISE EXCEPTION 'you cannot write off your own shortage'; END IF;
 IF h.approved_by=auth.uid() THEN RAISE EXCEPTION 'a different manager must write off a shortage you approved'; END IF;
 SELECT * INTO v_rc FROM public.pos_approval_reason_codes WHERE action='driver_cash_write_off' AND code=p_reason_code AND is_active;
 IF NOT FOUND THEN RAISE EXCEPTION 'reason required'; END IF;
 IF v_rc.requires_notes AND trim(COALESCE(p_notes,''))='' THEN RAISE EXCEPTION 'notes required for this reason'; END IF;
 v_out := h.owed_amount - h.recovered_amount - h.written_off_amount;
 IF v_out <= 0 THEN RAISE EXCEPTION 'nothing is owed on %', h.document_number; END IF;
 IF COALESCE(p_amount,0) <= 0 OR round(p_amount,2) > v_out THEN RAISE EXCEPTION 'amount must be between 0.01 and % %', h.currency, v_out; END IF;
 v_j := private._driver_cash_journal(h, '5310', '1250', p_amount, 'written off (' || p_reason_code || ')');
 INSERT INTO public.driver_cash_recoveries(handin_id, kind, amount, currency, journal_entry_id, notes, recorded_by)
 VALUES (h.id, 'write_off', round(p_amount,2), h.currency, v_j, concat_ws(': ', p_reason_code, NULLIF(trim(COALESCE(p_notes,'')),'')), auth.uid());
 UPDATE public.driver_cash_handins SET written_off_amount = written_off_amount + round(p_amount,2) WHERE id=h.id RETURNING * INTO h;
 RETURN private._driver_cash_handin_json(h);
END $$;


