--
-- Name: product_review_aggregates; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.product_review_aggregates WITH (security_invoker='true') AS
 SELECT stock_item_id,
    round(avg(rating), 2) AS avg_rating,
    count(*) AS review_count
   FROM public.customer_product_reviews
  WHERE (status = 'approved'::public.product_review_status)
  GROUP BY stock_item_id;


--
-- Name: VIEW product_review_aggregates; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.product_review_aggregates IS 'Approved review avg + count per stock_item_id (security_invoker).';


