--
-- Name: v_master_stock; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_master_stock WITH (security_invoker='true') AS
 SELECT si.id AS stock_item_id,
    si.oem_part_number,
    si.description,
    COALESCE(sum(sl.quantity), (0)::numeric) AS qty_total,
    COALESCE(sum(sl.quantity) FILTER (WHERE ((w.role_code = 'WH1'::text) OR ((w.code)::text = ANY ((ARRAY['WH1'::character varying, 'MAIN'::character varying])::text[])))), (0)::numeric) AS qty_wh1,
    COALESCE(sum(sl.quantity) FILTER (WHERE ((w.role_code = 'WH2'::text) OR ((w.code)::text = 'WH2'::text))), (0)::numeric) AS qty_wh2
   FROM ((public.stock_items si
     LEFT JOIN public.stock_levels sl ON ((sl.stock_item_id = si.id)))
     LEFT JOIN public.warehouses w ON (((w.id = sl.warehouse_id) AND w.is_active)))
  GROUP BY si.id, si.oem_part_number, si.description;


--
-- Name: VIEW v_master_stock; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_master_stock IS 'Master stock totals + WH1/WH2. No SELECT for authenticated — use list_master_stock.';


