COMMENT ON TABLE public.warehouse_bins IS 'Shelf/bin locations within a warehouse. Bins on Quarantine warehouses are allowed; they do not bypass Quarantine transfer/return protocols.';


--
-- Name: warranty_claims; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.warranty_claims (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    document_number text NOT NULL,
    status public.warranty_claim_status DEFAULT 'open'::public.warranty_claim_status NOT NULL,
    stock_serial_id uuid,
    sales_invoice_id uuid,
    stock_batch_id uuid,
    stock_item_id uuid,
    customer_id uuid,
    resolution public.warranty_claim_resolution,
    credit_note_id uuid,
    replacement_stock_entry_id uuid,
    quarantine_stock_entry_id uuid,
    currency public.currency_code,
    notes text,
    reject_reason text,
    created_by uuid,
    decided_by uuid,
    decided_at timestamp with time zone,
    closed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT warranty_claim_linkage CHECK (((stock_serial_id IS NOT NULL) OR (sales_invoice_id IS NOT NULL))),
    CONSTRAINT warranty_claim_resolution_when_decided CHECK ((((status = 'open'::public.warranty_claim_status) AND (resolution IS NULL)) OR ((status = 'rejected'::public.warranty_claim_status) AND (resolution = 'reject_only'::public.warranty_claim_resolution)) OR ((status = 'approved'::public.warranty_claim_status) AND (resolution = ANY (ARRAY['replacement'::public.warranty_claim_resolution, 'credit_note'::public.warranty_claim_resolution, 'return_only'::public.warranty_claim_resolution]))) OR ((status = 'closed'::public.warranty_claim_status) AND (resolution = ANY (ARRAY['replacement'::public.warranty_claim_resolution, 'credit_note'::public.warranty_claim_resolution, 'return_only'::public.warranty_claim_resolution, 'reject_only'::public.warranty_claim_resolution])))))
);


--
-- Name: whatsapp_bot_rate_limits; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.whatsapp_bot_rate_limits (
    wa_from text NOT NULL,
    window_started_at timestamp with time zone DEFAULT now() NOT NULL,
    request_count integer DEFAULT 0 NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT whatsapp_bot_rate_limits_request_count_check CHECK ((request_count >= 0))
);


--
-- Name: TABLE whatsapp_bot_rate_limits; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.whatsapp_bot_rate_limits IS 'Fixed-window request budget per WhatsApp sender for parts-finder bot. service_role only.';


--
-- Name: whatsapp_flow_orders; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.whatsapp_flow_orders (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    status text DEFAULT 'PENDING'::text NOT NULL,
    currency public.currency_code DEFAULT 'USD'::public.currency_code NOT NULL,
    subtotal numeric(18,4) DEFAULT 0 NOT NULL,
    delivery_fee numeric(18,4) DEFAULT 0 NOT NULL,
    total numeric(18,4) DEFAULT 0 NOT NULL,
    delivery_method text DEFAULT 'counter_collect'::text NOT NULL,
    delivery_notes text,
    wa_id text,
    lines jsonb DEFAULT '[]'::jsonb NOT NULL,
    payment_link text,
    payment_reference text,
    channel text DEFAULT 'whatsapp_flow'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    payment_provider text DEFAULT 'paynow'::text NOT NULL,
    payment_source_reference text,
    ecocash_payer_msisdn text,
    ecocash_payer_mode text,
    fx_rate_id uuid,
    settle_currency public.currency_code,
    settle_total numeric(18,4),
    settle_amount_minor bigint,
    CONSTRAINT whatsapp_flow_orders_delivery_fee_check CHECK ((delivery_fee >= (0)::numeric)),
    CONSTRAINT whatsapp_flow_orders_delivery_method_check CHECK ((delivery_method = ANY (ARRAY['counter_collect'::text, 'harare'::text, 'nationwide'::text]))),
    CONSTRAINT whatsapp_flow_orders_ecocash_payer_mode_check CHECK (((ecocash_payer_mode IS NULL) OR (ecocash_payer_mode = ANY (ARRAY['whatsapp'::text, 'saved'::text, 'other'::text])))),
    CONSTRAINT whatsapp_flow_orders_payment_provider_check CHECK ((payment_provider = ANY (ARRAY['paynow'::text, 'contipay'::text, 'ecocash'::text, 'stub'::text]))),
    CONSTRAINT whatsapp_flow_orders_settle_amount_minor_check CHECK (((settle_amount_minor IS NULL) OR (settle_amount_minor >= 0))),
    CONSTRAINT whatsapp_flow_orders_settle_total_check CHECK (((settle_total IS NULL) OR (settle_total >= (0)::numeric))),
    CONSTRAINT whatsapp_flow_orders_status_check CHECK ((status = ANY (ARRAY['PENDING'::text, 'PAID'::text, 'FAILED'::text, 'CANCELLED'::text, 'FULFILLING'::text, 'COMPLETED'::text]))),
    CONSTRAINT whatsapp_flow_orders_subtotal_check CHECK ((subtotal >= (0)::numeric)),
    CONSTRAINT whatsapp_flow_orders_total_check CHECK ((total >= (0)::numeric))
);


--
-- Name: TABLE whatsapp_flow_orders; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.whatsapp_flow_orders IS 'Orders created from WhatsApp Flows cart/checkout; settled via Paynow/ContiPay webhook.';


--
-- Name: COLUMN whatsapp_flow_orders.payment_provider; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.whatsapp_flow_orders.payment_provider IS 'Checkout rail: paynow|contipay aggregators, or ecocash direct C2B merchant API.';


--
-- Name: COLUMN whatsapp_flow_orders.payment_source_reference; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.whatsapp_flow_orders.payment_source_reference IS 'Merchant sourceReference sent to EcoCash (or PSP merchant ref).';


--
-- Name: COLUMN whatsapp_flow_orders.ecocash_payer_msisdn; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.whatsapp_flow_orders.ecocash_payer_msisdn IS 'Normalized 263… EcoCash wallet charged (may differ from wa_id).';


--
-- Name: COLUMN whatsapp_flow_orders.ecocash_payer_mode; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.whatsapp_flow_orders.ecocash_payer_mode IS 'whatsapp = WA MSISDN; saved = profile/saved phone; other = entered MSISDN.';


--
-- Name: COLUMN whatsapp_flow_orders.fx_rate_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.whatsapp_flow_orders.fx_rate_id IS 'D-57: daily_exchange_rates.id applied when settling EcoCash/ZiG; null for USD rails.';


--
-- Name: COLUMN whatsapp_flow_orders.settle_currency; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.whatsapp_flow_orders.settle_currency IS 'D-57: payable currency at pay step (ZIG for EcoCash); browse currency column stays USD.';


--
-- Name: COLUMN whatsapp_flow_orders.settle_total; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.whatsapp_flow_orders.settle_total IS 'D-57: payable major units for EcoCash C2B (from MoneyMinor); null when USD rail.';


--
-- Name: COLUMN whatsapp_flow_orders.settle_amount_minor; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.whatsapp_flow_orders.settle_amount_minor IS 'D-57: payable amount_minor (ZiG or USD settle); AI must never invent this.';


