--
-- Name: chat_messages chat_messages_customer_insert; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY chat_messages_customer_insert ON public.chat_messages FOR INSERT TO authenticated WITH CHECK (((sender_user_id = ( SELECT auth.uid() AS uid)) AND (sender_kind = 'customer'::public.chat_sender_kind) AND (NOT public.is_staff()) AND (EXISTS ( SELECT 1
   FROM public.chat_threads t
  WHERE ((t.id = chat_messages.thread_id) AND (t.customer_user_id = ( SELECT auth.uid() AS uid)) AND (t.status = ANY (ARRAY['open'::public.chat_thread_status, 'assigned'::public.chat_thread_status])))))));


--
-- Name: chat_messages chat_messages_select; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY chat_messages_select ON public.chat_messages FOR SELECT TO authenticated USING ((EXISTS ( SELECT 1
   FROM public.chat_threads t
  WHERE ((t.id = chat_messages.thread_id) AND public._can_select_chat_thread(t.*)))));


--
-- Name: chat_messages chat_messages_staff_insert; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY chat_messages_staff_insert ON public.chat_messages FOR INSERT TO authenticated WITH CHECK (((sender_user_id = ( SELECT auth.uid() AS uid)) AND (sender_kind = 'staff'::public.chat_sender_kind) AND public.has_staff_role(public._chat_staff_roles()) AND (EXISTS ( SELECT 1
   FROM public.chat_threads t
  WHERE ((t.id = chat_messages.thread_id) AND public._can_select_chat_thread(t.*) AND (t.status = ANY (ARRAY['open'::public.chat_thread_status, 'assigned'::public.chat_thread_status])))))));


