--
-- Name: chat_participants chat_participants_insert_own; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY chat_participants_insert_own ON public.chat_participants FOR INSERT TO authenticated WITH CHECK (((user_id = ( SELECT auth.uid() AS uid)) AND (((role = 'customer'::public.chat_participant_role) AND (NOT public.is_staff()) AND (EXISTS ( SELECT 1
   FROM public.chat_threads t
  WHERE ((t.id = chat_participants.thread_id) AND (t.customer_user_id = ( SELECT auth.uid() AS uid)))))) OR ((role = 'staff'::public.chat_participant_role) AND public.has_staff_role(public._chat_staff_roles()) AND (EXISTS ( SELECT 1
   FROM public.chat_threads t
  WHERE ((t.id = chat_participants.thread_id) AND public._can_select_chat_thread(t.*))))))));


--
-- Name: chat_participants chat_participants_select; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY chat_participants_select ON public.chat_participants FOR SELECT TO authenticated USING (((user_id = ( SELECT auth.uid() AS uid)) OR (EXISTS ( SELECT 1
   FROM public.chat_threads t
  WHERE ((t.id = chat_participants.thread_id) AND public._can_select_chat_thread(t.*))))));


