-- Name: chat_participants chat_participants_update_own; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY chat_participants_update_own ON public.chat_participants FOR UPDATE TO authenticated USING ((user_id = ( SELECT auth.uid() AS uid))) WITH CHECK (((user_id = ( SELECT auth.uid() AS uid)) AND (role = ( SELECT p.role
   FROM public.chat_participants p
  WHERE ((p.thread_id = chat_participants.thread_id) AND (p.user_id = ( SELECT auth.uid() AS uid)))))));


